# =============================================================================
# v8053 SYMBOL CANONICALIZATION (Pair Mapping Fix)
# - Do NOT touch tokens/keys.
# - Normalizes symbols across price/order layers to avoid endless SCAN loops.
# =============================================================================
def _pp8053_canon_symbol(sym: str) -> str:
    try:
        s = str(sym or "").strip().upper()
    except Exception:
        s = ""
    if not s:
        return ""
    # canonical: remove common separators
    return (s.replace("/", "")
             .replace("-", "")
             .replace("_", "")
             .replace(":", "")
             .replace(" ", ""))

def _pp8053_symbol_aliases(sym: str) -> list:
    """Return deterministic alias list (most preferred first)."""
    try:
        raw = str(sym or "").strip().upper()
    except Exception:
        raw = ""
    can = _pp8053_canon_symbol(raw)
    out = []
    for x in (raw, can):
        if x and x not in out:
            out.append(x)
    # common alternates
    if raw:
        a = raw.replace("-", "_").replace("/", "_")
        if a and a not in out:
            out.append(a)
        b = raw.replace("-", "").replace("_", "").replace("/", "")
        if b and b not in out:
            out.append(b)
    # also include dashed form for display/legacy (e.g. BTC-IRT)
    if can and len(can) >= 6:
        # heuristic: quote IRT/USDT/IRT etc
        for q in ("IRT", "USDT", "USD", "USDC"):
            if can.endswith(q) and len(can) > len(q):
                base = can[:-len(q)]
                dashed = f"{base}-{q}"
                if dashed not in out:
                    out.append(dashed)
                undersc = f"{base}_{q}"
                if undersc not in out:
                    out.append(undersc)
                break
    return out
