# ---- v8029: Adaptive BEAR-scalping thresholds (anti-starvation) ----
# Base condition (from prompt): allow entry in BEAR if TOP8 volatility is high.
# Root fix: if no trades happen for a while, progressively relax the threshold (still only TOP8 + small entries).
BEAR_SCALP_VOL_PCT_BASE = 0.60   # %
BEAR_SCALP_VOL_PCT_RELAX_1 = 0.40
BEAR_SCALP_VOL_PCT_RELAX_2 = 0.25
NO_TRADE_RELAX_SEC_1 = 20 * 60   # 20 minutes
NO_TRADE_RELAX_SEC_2 = 45 * 60   # 45 minutes

def _pp8029_guess_wname(obj, bot=None) -> str:
    """Best-effort wallet name resolver (never raises)."""
    try:
        for k in ("wname","wallet_name","wallet","name"):
            v = getattr(obj, k, None)
            if isinstance(v, str) and v.strip():
                s = v.strip()
                if s.upper().startswith("W"):
                    return s
        # sometimes stored as nested object with .name
        v = getattr(obj, "wallet", None)
        if v is not None:
            n = getattr(v, "name", None)
            if isinstance(n, str) and n.strip():
                return n.strip()
        # fallback to active wallet in bot (if any)
        if bot is not None:
            aw = getattr(bot, "_active_wallet_name", None)
            if isinstance(aw, str) and aw.strip():
                return aw.strip()
    except Exception:
        pass
    return "W?"

def _pp8029_get_last_trade_ts(bot, wname: str) -> float:
    """Max of last buy/sell timestamps tracked by PP_SYNC (0 if unknown)."""
    try:
        w = str(wname)
        lb = getattr(bot, "_pp_last_buy_ts_by_wallet", {}) or {}
        ls = getattr(bot, "_pp_last_sell_ts_by_wallet", {}) or {}
        tb = float(lb.get(w) or 0.0) if isinstance(lb, dict) else 0.0
        ts = float(ls.get(w) or 0.0) if isinstance(ls, dict) else 0.0
        return float(max(tb, ts, 0.0))
    except Exception:
        return 0.0

def _pp8029_bear_scap_threshold(bot, wname: str, now_ts: float) -> float:
    """Adaptive TOP8 abs-change threshold (percentage)."""
    try:
        last = _pp8029_get_last_trade_ts(bot, wname)
        if last <= 0.0:
            # initialize to bot start time if available
            last = float(getattr(bot, "_pp_boot_ts", 0.0) or 0.0)
        if last <= 0.0:
            last = float(now_ts)
        idle = float(max(0.0, float(now_ts) - float(last)))
        if idle >= float(NO_TRADE_RELAX_SEC_2):
            return float(BEAR_SCALP_VOL_PCT_RELAX_2)
        if idle >= float(NO_TRADE_RELAX_SEC_1):
            return float(BEAR_SCALP_VOL_PCT_RELAX_1)
        return float(BEAR_SCALP_VOL_PCT_BASE)
    except Exception:
        return float(BEAR_SCALP_VOL_PCT_BASE)

def _pp8029_top8_max_abs_chg_pct(bot) -> float:
    """Compute max(abs(%chg)) among current TOP8 using per_symbol price history (dashboard-compatible)."""
    try:
        ranked = list(getattr(bot, "_dash_ranked", []) or [])
    except Exception:
        ranked = []
    # collect top symbols
    syms = []
    try:
        for s, _ in ranked[:8]:
            if s:
                syms.append(str(s).strip())
    except Exception:
        syms = []
    if not syms:
        # fallback to last scanned top8
        try:
            syms = list(getattr(bot, "_pp733_top8_syms", []) or [])[:8]
        except Exception:
            syms = []
    try:
        states = getattr(bot, "states", {}) or {}
        wstate = states.get("W1") or (next(iter(states.values())) if states else None)
        ps = getattr(wstate, "per_symbol", {}) or {}
    except Exception:
        ps = {}
    mx = 0.0
    for sym in syms:
        try:
            st = ps.get(sym)
            prices = getattr(st, "prices", None) if st is not None else None
            if prices is None:
                continue
            try:
                prices = list(prices)
            except Exception:
                continue
            if len(prices) < 2:
                continue
            ref = float(prices[0] or 0.0)
            cur = float(prices[-1] or 0.0)
            if ref <= 0.0 or cur <= 0.0:
                continue
            chg = abs((cur / ref - 1.0) * 100.0)
            if chg > mx:
                mx = chg
        except Exception:
            continue
    return float(mx)

def _pp8029_set_wallet_status(bot, wname: str, status: str, reason: str = "", src: str = "", *, ts: float = None, now_ts: float = None, heartbeat_reason: str = None, prio: int = 10, stale_after: float = 6.0) -> None:
    """Write Status/Reason into _dash_wallet_status for UI (never raises).

    Institutional requirements:
      - Deterministic: every wallet always has a non-empty, displayable reason.
      - Single Source of Truth: _dash_wallet_status[wname] is the authoritative UI state used by DashboardManager.
      - Concurrency-safe: respects bot._dash_lock if present.
      - Non-overwrite by accident: priority-based updates + dedupe + stale expiry.
      - Debug cannot replace real status: low-priority writers (e.g. BUY_DEBUG / HEARTBEAT) will not override fresh higher-priority reasons.
    """
    try:
        if bot is None:
            return

        # Resolve wallet name deterministically (prevents writing under 'W?' / empty key)
        _w = str(wname or '').strip()
        if (not _w) or (_w == 'W?') or (_w.lower() in ('unknown', 'na', 'n/a')):
            try:
                _aw = str(getattr(bot, '_active_wallet_name', '') or '').strip()
            except Exception:
                _aw = ''
            if _aw:
                _w = _aw
            else:
                _w = str(wname or 'default')

        _status = str(status or 'WAITING').strip().upper() or 'WAITING'

        # Backward-compatible: allow heartbeat_reason to populate empty reasons (never leaves UI blank).
        try:
            if (not str(reason or "").strip()) and (heartbeat_reason is not None):
                _hr = str(heartbeat_reason or "").strip()
                if _hr:
                    reason = _hr
        except Exception:
            pass

        _reason = _pp8031_safe_reason(reason)
        _src = str(src or '').strip()[:48]

        try:
            _prio = int(prio)
        except Exception:
            _prio = 10
        if _prio < 0:
            _prio = 0
        if _prio > 100:
            _prio = 100

        try:
            _stale_after = float(stale_after or 0.0)
        except Exception:
            _stale_after = 6.0
        if _stale_after <= 0.0:
            _stale_after = 6.0


        # --- PP8053: clamp system writers so they never override strategy ---
        try:
            _raw = str(reason or "")
            _tag = (str(_src or "") + "|" + str(_status or "") + "|" + _raw).upper()
            _is_sys = ("HEARTBEAT" in _tag) or ("SCAN" in _tag) or ("SCANNING" in _tag)
            # boot age
            try:
                import time as _t2
                _boot = float(getattr(bot, "_pp_boot_ts", 0.0) or 0.0)
                _age = max(0.0, float(_t2.time()) - _boot)
            except Exception:
                _age = 9999.0

            if _is_sys:
                # System messages max priority = 2
                try:
                    _prio = min(int(_prio), 2)
                except Exception:
                    _prio = 2

                # SCAN only for first 5 seconds
                try:
                    if (_age > 5.0) and ((not _raw.strip()) or (_raw.strip().upper() in ("SCAN", "SCANNING"))):
                        reason = "R: HEARTBEAT"
                        _reason = _pp8031_safe_reason(reason)
                except Exception:
                    pass

                # System stales fast (never hides strategy for long)
                try:
                    _stale_after = min(float(_stale_after), 2.0)
                except Exception:
                    _stale_after = 2.0
        except Exception:
            pass

# Ensure store exists
        if (not hasattr(bot, '_dash_wallet_status')) or (not isinstance(getattr(bot, '_dash_wallet_status', None), dict)):
            bot._dash_wallet_status = {}

        import time as _t
        _now = float(ts) if (ts is not None) else (float(now_ts) if (now_ts is not None) else float(_t.time()))

        def _write():
            prev = bot._dash_wallet_status.get(_w) if isinstance(bot._dash_wallet_status, dict) else None
            if not isinstance(prev, dict):
                prev = {}

            # Extract previous metadata
            try:
                _p_prio = int(prev.get('prio', 0) or 0)
            except Exception:
                _p_prio = 0
            try:
                _p_ts = float(prev.get('ts', 0.0) or 0.0)
            except Exception:
                _p_ts = 0.0
            _p_reason = str(prev.get('reason', '') or '').strip()
            _p_status = str(prev.get('status', '') or '').strip().upper()

            # Dedupe rapid identical updates (prevents UI spam + accidental markup truncation side-effects)
            try:
                if (_p_status == _status) and (_p_reason == _reason):
                    if (_now - _p_ts) < 0.8:
                        prev['ts'] = _now
                        if _src:
                            prev['src'] = _src
                        # keep prio as-is
                        bot._dash_wallet_status[_w] = prev
                        return
            except Exception:
                pass

            # Priority gate:
            # - Lower priority cannot overwrite a higher priority status if that status is fresh and non-empty.
            # - But allow override if the previous status is stale (age > stale_after) or missing a reason/status.
            try:
                _age = _now - _p_ts
            except Exception:
                _age = 0.0

            if (_prio < _p_prio) and (_p_reason and _p_status) and (_age <= _stale_after):
                # Do not overwrite; keep stronger reason stable.
                return

            try:
                seq = int(prev.get('seq', 0) or 0) + 1
            except Exception:
                seq = 1

            bot._dash_wallet_status[_w] = {
                'status': _status,
                'reason': _reason,
                'ts': _now,
                'seq': seq,
                'src': _src,
                'prio': _prio,
            }

        _lk = getattr(bot, '_dash_lock', None)
        if _lk is None:
            _write()
        else:
            try:
                with _lk:
                    _write()
            except Exception:
                _write()
    except Exception:
        return


def _pp8031_safe_reason(reason: str, default: str = "SCANNING") -> str:
    """Normalize Status/Reason to a UI-safe short string (never raises).

    Maturity rules (deterministic):
    - Remove invisible/RTL control chars that can make Reason *look* blank while being truthy.
    - Collapse whitespace.
    - Escape Rich markup brackets so Reason cannot break the TUI.
    - If `default` is empty, allow returning empty (callers use this to detect blank-ish reasons).
    """
    def _clean(x: str) -> str:
        try:
            s = str(x or "")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            s = ""
        # Strip invisible / bidi / formatting controls (common sources of 'blank reason')
        try:
            for ch in ("\ufeff","\u200b","\u200c","\u200d","\u200e","\u200f",
                       "\u202a","\u202b","\u202c","\u202d","\u202e",
                       "\u2066","\u2067","\u2068","\u2069","\u00ad"):
                s = s.replace(ch, "")
            s = "".join(c for c in s if (ord(c) >= 32 and ord(c) != 127))
        except Exception:
            pass
        # Normalize whitespace
        try:
            s = s.replace("\r", " ").replace("\n", " ").replace("\t", " ")
            s = " ".join(s.strip().split())
        except Exception:
            try:
                s = str(s).strip()
            except Exception:
                s = ""
        # Rich-safe
        try:
            s = s.replace("[", "⟦").replace("]", "⟧")
        except Exception:
            pass
        return s

    r = _clean(reason)
    if not r:
        d = _clean(default)
        return d if d else ""
    # cap length for dashboard safety
    try:
        return r[:96]
    except Exception:
        return r

def _pp8029_ensure_wallet_status_recent(
    bot,
    wname: str,
    *,
    max_age_sec: float = 4.0,
    fallback_status: str = "WAITING",
    fallback_reason: str = "SCANNING",
    prio: int = 2,
    src: str = "HEARTBEAT",
    now_ts=None,
    heartbeat_reason=None,
) -> None:
    """Ensure _dash_wallet_status[wname] is present and has a non-empty reason.

    - Observability only: does NOT change trading logic.
    - Never silent: any exception is surfaced as a low-priority DASH_LIVENESS_FAIL reason.
    - Will NOT overwrite fresh, higher-priority reasons (handled by _pp8029_set_wallet_status gate).
    """
    try:
        import time as _t

        if bot is None:
            return
        _w = str(wname or "").strip() or "default"

        try:
            _now = float(now_ts) if (now_ts is not None) else float(_t.time())
        except Exception:
            _now = float(_t.time())

        # Base fallback reason (never empty)
        _fr = str(fallback_reason or "").strip() or "SCAN"

        # Explicit heartbeat_reason overrides generic fallbacks
        try:
            _hr = str(heartbeat_reason or "").strip()
            if _hr:
                _fr = _hr
        except Exception:
            pass

        # If we have a recent per-wallet veto, prefer it over generic SCAN/IDLE
        try:
            _wm = getattr(bot, "_dash_wallet_last_veto", {}) or {}
            _wts = getattr(bot, "_dash_wallet_last_veto_ts", {}) or {}
            _v = str(_wm.get(_w) or "").strip()
            _vts = float(_wts.get(_w) or 0.0)
            if _v and ((_now - _vts) <= max(60.0, float(max_age_sec or 0.0) * 10.0)):
                if str(_fr).upper() in ("SCAN", "SCANNING", "IDLE", "WAITING"):
                    _fr = _v
        except Exception:
            pass

        _sm = getattr(bot, "_dash_wallet_status", None)
        if not isinstance(_sm, dict):
            _pp8029_set_wallet_status(
                bot,
                _w,
                str(fallback_status or "WAITING"),
                _fr,
                src=src,
                prio=int(prio or 2),
                stale_after=float(max_age_sec or 0.0) or 2.0,
                ts=_now,
                heartbeat_reason=_fr,
            )
            return

        cur = _sm.get(_w)
        if not isinstance(cur, dict):
            _pp8029_set_wallet_status(
                bot,
                _w,
                str(fallback_status or "WAITING"),
                _fr,
                src=src,
                prio=int(prio or 2),
                stale_after=float(max_age_sec or 0.0) or 2.0,
                ts=_now,
                heartbeat_reason=_fr,
            )
            return

        try:
            _ts = float(cur.get("ts", 0.0) or 0.0)
        except Exception:
            _ts = 0.0
        _rsn = str(cur.get("reason", "") or "").strip()

        if _rsn and ((_now - _ts) <= float(max_age_sec or 0.0)):
            return

        _pp8029_set_wallet_status(
            bot,
            _w,
            str(fallback_status or "WAITING"),
            _rsn or _fr,
            src=src,
            prio=int(prio or 2),
            stale_after=float(max_age_sec or 0.0) or 2.0,
            ts=_now,
            heartbeat_reason=_fr,
        )
    except Exception as e:
        # No silent failure: surface liveness issues in UI at low priority.
        try:
            _pp8029_set_wallet_status(
                bot,
                str(wname or "").strip() or "default",
                "WAITING",
                f"DASH_LIVENESS_FAIL {type(e).__name__}",
                src="DASH",
                prio=3,
                stale_after=2.0,
            )
        except Exception:
            pass
def _pp_vto_type_from_msg(veto_or_msg: str) -> int:
    """Map a veto/debug message to a small stable integer for dashboards."""
    try:
        s = str(veto_or_msg or "").strip().upper()
        if not s:
            return 0

        # Common veto buckets (keep stable!)
        if any(k in s for k in ("BALANCE", "NO_CASH", "INSUFFICIENT", "FUNDS", "LOW_QUOTE", "LOW_IRT")):
            return 1
        if any(k in s for k in ("COOLDOWN", "SANCTUARY", "WAIT", "LOCK", "BLOCK")):
            return 2
        if any(k in s for k in ("STALE", "QUALITY", "NO_PRICE", "NO_DEPTH", "LAG", "FRESH")):
            return 3
        if any(k in s for k in ("SPREAD", "SLIPPAGE", "DEPTH", "BOOK")):
            return 4
        if any(k in s for k in ("NO_PROFIT", "NO_EDGE", "EDGE_BELOW", "MARGIN")):
            return 5
        if any(k in s for k in ("OPEN_ORDERS", "PENDING", "SYNC", "ORDER_EXISTS")):
            return 6
        if any(k in s for k in ("SAFETY", "SANITY", "HALT", "PANIC")):
            return 7
        if any(k in s for k in ("AI_VETO", "MODEL", "PHOENIX", "BRAIN", "VETO")):
            return 8

        return 9
    except Exception:
        return 0


def _pp9001_push_dash_buy_debug(bot, wname: str, msg: str) -> None:
    """Push a short diagnostic string to dashboard/WHY. Safe: never raises.

    Institutional semantics:
      - Debug NEVER overrides a fresh higher-priority Status/Reason.
      - But if Status is empty/stale, Debug may fill it with LOW priority for visibility.
    """
    try:
        import time as _t
        from collections import deque as _pp_deque

        _m = str(msg or "").strip()
        if not _m:
            return

        # ---- Status SSoT (LOW priority): reflect WHY in Status only if it won't override stronger reasons ----
        try:
            if False and '_pp8029_set_wallet_status' in globals() and callable(globals().get('_pp8029_set_wallet_status')):
                # stale_after is huge so BUY_DEBUG won't override by staleness; heartbeat handles liveness separately.
                globals()['_pp8029_set_wallet_status'](bot, str(wname), 'WAITING', _m[:200], src='BUY_DEBUG', prio=1, stale_after=1e9)
        except Exception:
            pass

        # ---- global WHY (short) ----
        try:
            setattr(bot, "_pp_diag_last_veto_gene", _m[:96])
            setattr(bot, "_pp_diag_last_veto_ts", float(_t.time()))
        except Exception:
            pass

        # ---- per-wallet WHY (for veto transparency) ----
        try:
            _wm = getattr(bot, "_dash_wallet_last_veto", None)
            if not isinstance(_wm, dict):
                _wm = {}
                setattr(bot, "_dash_wallet_last_veto", _wm)
            _wm[str(wname)] = _m[:160]
            _wts = getattr(bot, "_dash_wallet_last_veto_ts", None)
            if not isinstance(_wts, dict):
                _wts = {}
                setattr(bot, "_dash_wallet_last_veto_ts", _wts)
            _wts[str(wname)] = float(_t.time())
        except Exception:
            pass

        # ---- vtoType (stable numeric code for UI) ----
        try:
            _vt = int(_pp_vto_type_from_msg(_m))
            # common attribute names some dashboards look for:
            setattr(bot, "vtoType", _vt)
            setattr(bot, "vto_type", _vt)
            setattr(bot, "_pp_diag_vto_type", _vt)
            setattr(bot, "_pp_diag_vtotype", _vt)
        except Exception:
            pass

        # ---- force-start/decision reason (longer) ----
        try:
            setattr(bot, "_pp_last_fs_reason", _m[:240])
            setattr(bot, "_pp_last_fs_reason_ts", float(_t.time()))
        except Exception:
            pass

        # ---- per-wallet ring buffer used by DashboardManager wallet panel ----
        try:
            _w = str(wname or "").strip()
            if not _w:
                _w = "default"
            _mapp = getattr(bot, "_dash_buy_debug", None)
            if not isinstance(_mapp, dict):
                _mapp = {}
                setattr(bot, "_dash_buy_debug", _mapp)

            _dq = _mapp.get(_w)
            if not isinstance(_dq, _pp_deque):
                _dq = _pp_deque(maxlen=10)
                _mapp[_w] = _dq

            _ts = _t.strftime("%H:%M:%S", _t.localtime())
            _dq.appendleft(f"{_ts} | {_m}"[:180])
        except Exception:
            pass

        # ---- optional: last-events rail (best effort) ----
        try:
            _ev = getattr(bot, "_dash_last_events", None)
            if (_ev is not None) and (hasattr(_ev, 'appendleft') or hasattr(_ev, 'append')):
                _ts = _t.strftime("%H:%M:%S", _t.localtime())
                _ev.appendleft(f"{_ts} | BUYDBG[{wname}] {_m}"[:180]) if hasattr(_ev, "appendleft") else _ev.append(f"{_ts} | BUYDBG[{wname}] {_m}"[:180])
        except Exception:
            pass

    except Exception:
        return


def _pp_vote_type_str(v) -> str:
    try:
        if isinstance(v, (int, float)):
            vi = int(v)
            if vi == 1:
                return "BUY"
            if vi == -1:
                return "SELL"
            return "HOLD"
        s = str(v or "").strip().upper()
        if s in ("1", "+1", "BUY", "LONG"):
            return "BUY"
        if s in ("-1", "SELL", "SHORT"):
            return "SELL"
        if s in ("0", "HOLD", "FLAT", "NEUTRAL"):
            return "HOLD"
        return s or "HOLD"
    except Exception:
        return "HOLD"

def _pp_vote_type_code(v) -> int:
    try:
        if isinstance(v, (int, float)):
            vi = int(v)
            return 1 if vi > 0 else (-1 if vi < 0 else 0)
        s = str(v or "").strip().upper()
        if s in ("1", "+1", "BUY", "LONG"):
            return 1
        if s in ("-1", "SELL", "SHORT"):
            return -1
        return 0
    except Exception:
        return 0
