# PP8001: Trade Counter (global) + conditional fixed penalty after N trades
# - START_COUNT: seed counter on restart (e.g., export START_COUNT=5)
# - TRADE_COUNT_DAILY=1: reset counter when day changes (optional; default is per-run)
# =========================
import os
import datetime as _PP8001_dt

_PP8001_trade_day = ""
try:
    _PP8001_trade_day = _PP8001_dt.datetime.now().strftime("%Y%m%d")
except Exception:
    _PP8001_trade_day = ""

def _pp8001__read_start_count() -> int:
    try:
        _v = str(os.getenv("START_COUNT", "0") or "0").strip()
        if not _v:
            return 0
        # allow "5.0" etc
        return max(0, int(float(_v)))
    except Exception:
        return 0

# Counter for all wallets (W1/W2/W3): recommended to match exchange/account-wide limits
daily_trade_count: int = _pp8001__read_start_count()

# PP8001 defaults (safe): absolute profit floor and conditional penalty (do NOT override existing env).
try:
    os.environ.setdefault("MIN_NET_PROFIT_IRT", "2000")
    os.environ.setdefault("FIXED_PENALTY_IRT", "4000")
    os.environ.setdefault("FIXED_PENALTY_AFTER_TRADES", "8")
except Exception:
    pass


def _pp8001_maybe_reset_trade_counter() -> None:
    """Optional daily reset (enabled by TRADE_COUNT_DAILY=1)."""
    global daily_trade_count, _PP8001_trade_day
    try:
        _flag = str(os.getenv("TRADE_COUNT_DAILY", "0") or "0").strip().lower() in ("1","true","yes","y","on")
        if not _flag:
            return
        _cur = _PP8001_dt.datetime.now().strftime("%Y%m%d")
        if _PP8001_trade_day and _cur != _PP8001_trade_day:
            daily_trade_count = 0
        _PP8001_trade_day = _cur
    except Exception:
        return


