# =====================================================
# PP130: CognitiveBrain (Autonomous Agent Core)
# - Lightweight (stdlib only), Termux-friendly
# - Provides: Oracle (linear regression slope on last 20 prices)
#             Self-learning (brain.json persistence)
# =====================================================

class CognitiveBrain:
    """
    Lightweight autonomous brain:
      - predict_next_move(prices): simple linear regression slope on last 20 prices.
      - record_trade(pnl_toman): updates confidence_score and win/loss counters in brain.json.
      - volume_multiplier(): halves sizing when confidence is low.
      - brain_iq(): adaptive intelligence proxy = total wins recorded.
    """

    def __init__(self, brain_path: str | None = None):
        try:
            base_dir = _os.path.dirname(_os.path.abspath(__file__))
        except Exception:
            base_dir = _os.getcwd()
        self.brain_path = brain_path or _os.path.join(base_dir, "brain.json")
        self._lock = threading.RLock()
        self.state = {
            "version": "v145",
            "confidence_score": 0.50,   # 0..1
            "wins": 0,
            "losses": 0,
            "trades": 0,
            "last_pnls": [],            # bounded
            "updated_at": None,
        }
        self._load()

    def _load(self) -> None:
        with self._lock:
            try:
                if not _os.path.exists(self.brain_path):
                    return
                with open(self.brain_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    for k, v in data.items():
                        self.state[k] = v
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return

    def _save(self) -> None:
        with self._lock:
            try:
                self.state["updated_at"] = int(_pp920_time.time())
                lp = self.state.get("last_pnls", [])
                if not isinstance(lp, list):
                    lp = []
                if len(lp) > 200:
                    lp = lp[-200:]
                self.state["last_pnls"] = lp
                tmp = self.brain_path + ".tmp"
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump(self.state, f, ensure_ascii=False, separators=(",", ":"))
                try:
                    _os.replace(tmp, self.brain_path)
                except Exception:
                    with open(self.brain_path, "w", encoding="utf-8") as f:
                        json.dump(self.state, f, ensure_ascii=False, separators=(",", ":"))
                    try:
                        if _os.path.exists(tmp):
                            _os.remove(tmp)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return

    @staticmethod
    def _linreg_slope(y: list[float]) -> float:
        n = len(y)
        if n < 2:
            return 0.0
        xm = (n - 1) / 2.0
        ym = sum(y) / float(n)
        num = 0.0
        den = 0.0
        for i, yi in enumerate(y):
            dx = float(i) - xm
            dy = float(yi) - ym
            num += dx * dy
            den += dx * dx
        if den <= 0.0:
            return 0.0
        return float(num) / float(den)

    def predict_next_move(self, prices) -> tuple[float, float]:
        try:
            p = [float(x) for x in (prices or [])][-20:]
        except Exception:
            p = []
        if len(p) < 2:
            return 0.0, 0.0
        slope = self._linreg_slope(p)
        try:
            mean_p = sum(p) / float(len(p))
        except Exception:
            mean_p = 0.0
        slope_pct = 0.0
        if mean_p and math.isfinite(mean_p) and mean_p != 0.0 and math.isfinite(slope):
            slope_pct = (slope / mean_p) * 100.0
        if not math.isfinite(slope_pct):
            slope_pct = 0.0
        return float(slope), float(slope_pct)

    def record_trade(self, pnl_toman: float) -> None:
        with self._lock:
            try:
                pnl = float(pnl_toman or 0.0)
            except Exception:
                pnl = 0.0

            self.state["trades"] = int(self.state.get("trades", 0) or 0) + 1
            lp = self.state.get("last_pnls", [])
            if not isinstance(lp, list):
                lp = []
            lp.append(pnl)

            conf = float(self.state.get("confidence_score", 0.50) or 0.50)
            step = 0.03
            if pnl > 0:
                self.state["wins"] = int(self.state.get("wins", 0) or 0) + 1
                conf = min(0.95, conf + step)
            elif pnl < 0:
                self.state["losses"] = int(self.state.get("losses", 0) or 0) + 1
                conf = max(0.05, conf - step)

            self.state["confidence_score"] = float(conf)
            self.state["last_pnls"] = lp
            self._save()

    def confidence(self) -> float:
        try:
            c = float(self.state.get("confidence_score", 0.50) or 0.50)
        except Exception:
            c = 0.50
        if not math.isfinite(c):
            c = 0.50
        return max(0.05, min(0.95, c))

    def volume_multiplier(self) -> float:
        c = self.confidence()
        return 0.5 if c < 0.45 else 1.0

    def brain_iq(self) -> int:
        try:
            return int(self.state.get("wins", 0) or 0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0

