# ============================================================
# ROOTFIX: Fee-aware order sizing (prevents Insufficient Balance due to fee/slippage/rounding)
# ============================================================ (prevents Insufficient Balance due to fee/slippage/rounding)
# ============================================================
def _pp_fee_aware_spend(quote_free: float, max_trade_quote: float,
                        fee_bps: float = 0.0, slippage_bps: float = 0.0,
                        safety_bps: float = 10.0) -> float:
    try:
        q = max(0.0, float(quote_free))
        mx = max(0.0, float(max_trade_quote))
        fb = max(0.0, float(fee_bps))
        sb = max(0.0, float(slippage_bps))
        saf = max(0.0, float(safety_bps))
        total_bps = fb + sb + saf
        frac = max(0.0, 1.0 - (total_bps / 10000.0))
        return min(mx, q * frac)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return min(max(0.0, float(max_trade_quote)), max(0.0, float(quote_free)) * 0.90)

