import os
import sys
import logging

# Global file-lock handle for single-instance guard
_PP_INSTANCE_LOCK_FD = None

from logging.handlers import RotatingFileHandler

def setup_logging(
    level: int = logging.INFO,
    log_dir: str = "logs",
    log_file: str = "trading_bot.log",
    max_bytes: int = 10 * 1024 * 1024,
    backup_count: int = 5,
    tui: bool = False,
) :
    """Initialize logging.

    - Always logs to rotating file logs/trading_bot.log
    - When tui=True, suppresses console spam (Rich dashboard owns the terminal)
    - Keeps an in-memory ring buffer for the dashboard footer (last important events)
    """
    if getattr(setup_logging, '_configured', False):
        return
    os.makedirs(log_dir, exist_ok=True)
    log_path = os.path.join(log_dir, log_file)
    root = logging.getLogger()
    root.setLevel(level)
    formatter = logging.Formatter("%(asctime)s - %(name)s - %(levelname)s - %(message)s")

    # File (always)
    file_handler = RotatingFileHandler(
        log_path, maxBytes=max_bytes, backupCount=backup_count, encoding="utf-8"
    )
    file_handler.setLevel(level)
    file_handler.setFormatter(formatter)
    root.addHandler(file_handler)

    # Dashboard ring-buffer (always; very small, memory-safe)
    try:
        global _DASH_RING_HANDLER
        if _DASH_RING_HANDLER is None:
            _DASH_RING_HANDLER = _DashRingHandler(maxlen=int(os.getenv("DASH_LOG_RING", "400") or 400))
            _DASH_RING_HANDLER.setLevel(level)
            _DASH_RING_HANDLER.setFormatter(formatter)
            root.addHandler(_DASH_RING_HANDLER)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # Console (only when NOT in TUI mode)
    if not tui:
        console = logging.StreamHandler(sys.stdout)
        console.setLevel(level)
        console.setFormatter(formatter)
        root.addHandler(console)

    setup_logging._configured = True
    root.info("Logging initialized (production mode)")
