from collections import deque as _deque_dash
# PP210 FIX: expose `deque` name for legacy/market context code
deque = _deque_dash

_DASH_RING_HANDLER = None

class _DashRingHandler(logging.Handler):
    """Small ring buffer for last important log lines (memory-safe)."""
    def __init__(self, maxlen: int = 400):
        super().__init__(level=logging.INFO)
        self._buf = _deque_dash(maxlen=int(maxlen or 400))
        try:
            self._lock = threading.RLock()
        except Exception:
            self._lock = None

    def emit(self, record: logging.LogRecord) -> None:
        try:
            msg = self.format(record)
        except Exception:
            try:
                msg = str(record.getMessage())
            except Exception:
                msg = ""
        if not msg:
            return
        try:
            item = (int(record.levelno or 0), float(_pp920_time.time()), msg)
        except Exception:
            item = (0, 0.0, msg)
        try:
            if self._lock:
                with self._lock:
                    self._buf.append(item)
            else:
                self._buf.append(item)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def last_important(self, n: int = 3) -> List[str]:
        try:
            n = int(n)
        except Exception:
            n = 3
        n = max(1, min(10, n))
        keys = ("ORDER", "BUY", "SELL", "FILLED", "REAL TRADING", "DAILY LOSS", "PP113", "ERROR", "CRITICAL", "LOCK", "CANCEL")
        try:
            if self._lock:
                with self._lock:
                    buf = list(self._buf)
            else:
                buf = list(self._buf)
        except Exception:
            buf = []
        # pick important (severity>=WARNING OR contains keywords)
        imp = [m for (lvl, _, m) in buf if (lvl >= logging.WARNING) or any(k in m for k in keys)]
        src = imp if imp else [m for (_, _, m) in buf]
        return [str(x) for x in (src[-n:] if src else ["(no events)"])]

def _dash_last_events(n: int = 3) -> List[str]:
    try:
        h = _DASH_RING_HANDLER
        if h is None:
            return []
        return h.last_important(n=n)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return []


def _is_finite_number(x: Any) -> bool:
    """Return True if x can be converted to a finite float."""
    try:
        return math.isfinite(float(x))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False


