# PP145: COGNITIVE UPGRADES (Strategic Self-Awareness v145)
# - Contextual Logic: Multi-Timeframe (15m + 1h) trend gating
# - Empirical Memory Loop: trading_memory.json + self-correction weights
# - Autonomous Risk: Kelly-based sizing + Panic Mode
# - Deep Optimization: Learning-loop watchdog self-recovery
# ============================================================

def _pp145_rsi(closes: List[float], period: int = 14) -> float:
    """
    RSI (pure python). Returns 50.0 when insufficient data.
    """
    try:
        p = int(period or 14)
    except Exception:
        p = 14
    if p <= 1:
        p = 14
    try:
        arr = [float(x) for x in (closes or []) if x is not None]
    except Exception:
        arr = []
    if len(arr) < (p + 1):
        return 50.0
    gains = 0.0
    losses = 0.0
    # Use the last (p) deltas
    start = len(arr) - (p + 1)
    if start < 0:
        start = 0
    prev = arr[start]
    for x in arr[start + 1:]:
        d = float(x) - float(prev)
        if d >= 0:
            gains += d
        else:
            losses += (-d)
        prev = x
    avg_gain = gains / float(p)
    avg_loss = losses / float(p)
    eps = 1e-12
    # If the series is flat (no gains and no losses), RSI should be neutral.
    if avg_gain <= eps and avg_loss <= eps:
        return 50.0
    if avg_loss <= eps:
        return 100.0
    if avg_gain <= eps:
        return 0.0
    rs = avg_gain / avg_loss
    rsi = 100.0 - (100.0 / (1.0 + rs))
    try:
        if not math.isfinite(rsi):
            return 50.0
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 50.0
    return float(max(0.0, min(100.0, rsi)))


def _pp145_linreg_slope_pct(values: List[float]) -> float:
    """
    Linear regression slope as percent of mean (pure python).
    """
    try:
        arr = [float(x) for x in (values or []) if x is not None]
    except Exception:
        arr = []
    n = len(arr)
    if n < 4:
        return 0.0
    xs = list(range(n))
    x_mean = (n - 1) / 2.0
    y_mean = sum(arr) / float(n)
    denom = 0.0
    num = 0.0
    for i, y in enumerate(arr):
        dx = float(xs[i]) - float(x_mean)
        denom += dx * dx
        num += dx * (float(y) - float(y_mean))
    if denom <= 1e-12:
        return 0.0
    slope = num / denom
    mean_p = abs(float(y_mean)) if abs(float(y_mean)) > 1e-12 else 0.0
    if mean_p <= 1e-12:
        return 0.0
    return float((slope / mean_p) * 100.0)


class TradingMemory:
    """
    PP145 Empirical Memory Loop.

    File: trading_memory.json
      - Stores per-trade "market signature" (RSI, BTC price, distance from support)
      - Self-correction weights:
          If a strategy is losing in the last 3 trades, its weight decays by 20%
          until performance recovers.
      - Provides Kelly-based sizing stats from recent trades.
    """

    def __init__(self, path: Optional[str] = None, max_trades: int = 4000):
        self.max_trades = int(max_trades or 4000)
        self._lock = threading.RLock()
        self._last_op_ts = 0.0
        self._last_ok_ts = 0.0
        self._op_count = 0
        self._path = self._resolve_path(path)
        self.state = {
            "version": 145,
            "updated_ts": 0.0,
            "trades": [],
            "strategy_weights": {},
            "strategy_recent": {},
        }
        self._load()

        # PP703: Alpha feedback snapshots (non-invasive, in-memory only)
        try:
            from collections import deque as _pp703_deque
            self._pp703_alpha = {"snapshots": _pp703_deque(maxlen=720), "last_gap": 0.0, "last_alert": "", "last_calc_ts": 0.0}
        except Exception:
            self._pp703_alpha = {"snapshots": [], "last_gap": 0.0, "last_alert": "", "last_calc_ts": 0.0}

    @staticmethod
    def _resolve_path(path: Optional[str]) -> str:
        try:
            p = (str(path or "").strip() or str(os.getenv("TRADING_MEMORY_PATH", "") or "").strip())
        except Exception:
            p = ""
        if not p:
            try:
                base = os.path.dirname(os.path.abspath(__file__))
            except Exception:
                base = os.getcwd()
            p = os.path.join(base, "trading_memory.json")
        try:
            return os.path.abspath(p)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return p

    @property
    def path(self) -> str:
        return str(self._path)

    def try_lock(self, timeout: float = 0.05) -> bool:
        try:
            return bool(self._lock.acquire(timeout=float(timeout)))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False

    def unlock(self) -> None:
        try:
            self._lock.release()
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def _touch_op(self, ok: bool = True) -> None:
        now = _pp920_time.time()
        self._last_op_ts = float(now)
        if ok:
            self._last_ok_ts = float(now)
        self._op_count = int(self._op_count or 0) + 1

    def _load(self) -> None:
        try:
            p = self.path
            if not os.path.isfile(p):
                return
            with open(p, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                self.state.update(data)
        except Exception:
            # do not crash live trading if memory is corrupt
            return

    def _save_atomic(self) -> None:
        p = self.path
        d = os.path.dirname(p) or "."
        try:
            os.makedirs(d, exist_ok=True)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        tmp = p + ".tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(self.state, f, ensure_ascii=False, indent=2)
            try:
                os.replace(tmp, p)
            except Exception:
                # fallback: remove then rename
                try:
                    if os.path.exists(p):
                        os.remove(p)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                os.rename(tmp, p)
        except Exception:
            # best-effort cleanup
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

    def record_trade(self,
                     wallet: str,
                     symbol: str,
                     pnl_toman: float,
                     strategy: str,
                     signature: Optional[Dict[str, Any]] = None,
                     entry_price: float = 0.0,
                     exit_price: float = 0.0,
                     qty: float = 0.0,
                     note: str = "") -> None:
        stg = (str(strategy or "EDGE").strip().upper() or "EDGE")
        try:
            pnl = float(pnl_toman or 0.0)
        except Exception:
            pnl = 0.0
        trade = {
            "ts": float(_pp920_time.time()),
            "wallet": str(wallet or ""),
            "symbol": str(symbol or ""),
            "pnl_toman": float(pnl),
            "strategy": stg,
            "signature": dict(signature or {}),
            "entry_price": float(entry_price or 0.0),
            "exit_price": float(exit_price or 0.0),
            "qty": float(qty or 0.0),
            "note": str(note or "")[:200],
        }
        with self._lock:
            ok = True
            try:
                trades = self.state.get("trades")
                if not isinstance(trades, list):
                    trades = []
                trades.append(trade)
                if len(trades) > self.max_trades:
                    trades = trades[-self.max_trades:]
                self.state["trades"] = trades
                self.state["updated_ts"] = float(_pp920_time.time())
                # update recents
                rec = self.state.get("strategy_recent")
                if not isinstance(rec, dict):
                    rec = {}
                lst = rec.get(stg)
                if not isinstance(lst, list):
                    lst = []
                lst.append(float(pnl))
                lst = lst[-50:]
                rec[stg] = lst
                self.state["strategy_recent"] = rec

                # self-correction weights
                wmap = self.state.get("strategy_weights")
                if not isinstance(wmap, dict):
                    wmap = {}
                w = float(wmap.get(stg, 1.0) or 1.0)
                last3 = lst[-3:] if len(lst) >= 3 else lst
                if len(last3) >= 3 and all(float(x) < 0.0 for x in last3):
                    # 3 recent losing trades => reduce by 20%
                    w = max(0.20, float(w) * 0.80)
                elif float(pnl) > 0.0 and w < 1.0:
                    # gradual recovery when profitable again
                    w = min(1.0, float(w) * 1.05)
                wmap[stg] = float(w)
                self.state["strategy_weights"] = wmap

                # persist
                self._save_atomic()
            except Exception:
                ok = False
            self._touch_op(ok=ok)

    def strategy_weight(self, strategy: str) -> float:
        stg = (str(strategy or "EDGE").strip().upper() or "EDGE")
        try:
            with self._lock:
                wmap = self.state.get("strategy_weights") or {}
                w = float((wmap or {}).get(stg, 1.0) or 1.0)
        except Exception:
            w = 1.0
        if not math.isfinite(w):
            w = 1.0
        return float(max(0.10, min(1.50, w)))

    def recent_trades(self, n: int = 40) -> List[Dict[str, Any]]:
        try:
            n = int(n)
        except Exception:
            n = 40
        n = max(0, min(500, n))
        try:
            with self._lock:
                t = self.state.get("trades") or []
                if not isinstance(t, list):
                    return []
                return list(t[-n:])
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return []

    def kelly_fraction(self, n: int = 40) -> float:
        """
        Compute Kelly fraction from last n trades.
        Kelly = W - (1-W)/R, where:
            W = win rate
            R = avg_win / avg_loss
        Returns a conservative capped fraction in [0, 0.15].
        """
        trades = self.recent_trades(n=n)
        if not trades:
            return 0.02  # cold-start: 2% of cash
        wins = []
        losses = []
        for tr in trades:
            try:
                pnl = float(tr.get("pnl_toman", 0.0) or 0.0)
            except Exception:
                pnl = 0.0
            if pnl > 0:
                wins.append(pnl)
            elif pnl < 0:
                losses.append(-pnl)
        total = len(trades)
        if total <= 0:
            return 0.02
        w = float(len(wins)) / float(total)
        if not losses:
            # no loss data yet => cap
            return float(max(0.01, min(0.10, 0.08 * (0.5 + w))))
        avg_win = (sum(wins) / float(len(wins))) if wins else 0.0
        avg_loss = (sum(losses) / float(len(losses))) if losses else 0.0
        if avg_loss <= 1e-12:
            return 0.02
        R = avg_win / avg_loss if avg_win > 0 else 0.0
        if R <= 1e-9:
            return 0.01
        k = w - ((1.0 - w) / R)
        if not math.isfinite(k):
            k = 0.0
        # Conservative clamps (keep capital alive)
        k = max(0.0, min(0.15, float(k)))
        # tiny floor to keep learning alive
        if k <= 0.0:
            k = 0.005
        return float(k)

    def force_flush(self) -> None:
        """Emergency: clear memory file + in-memory history (used by watchdog)."""
        with self._lock:
            self.state = {
                "version": 145,
                "updated_ts": float(_pp920_time.time()),
                "trades": [],
                "strategy_weights": {},
                "strategy_recent": {},
            }
            try:
                self._save_atomic()
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        self._touch_op(ok=True)


    # ------------------------------------------------------------------
    # PP703 Alpha Feedback Loop: Inflation-aware benchmarking vs USDT
    # ------------------------------------------------------------------
    @staticmethod
    def _pp703_sf(x, d=0.0) -> float:
        try:
            v = float(x)
            if v != v:
                return float(d)
            if v == float('inf') or v == float('-inf'):
                return float(d)
            return v
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return float(d)

    def _pp703_total_equity_irt(self, bot) -> float:
        """Best-effort total equity in IRT (sum of dashboard equity caches)."""
        try:
            ec = getattr(bot, '_dash_equity_cache', None) or {}
            tot = 0.0
            if isinstance(ec, dict):
                for _, v in (ec or {}).items():
                    tot += self._pp703_sf(v, 0.0)
            if tot <= 0.0:
                tot = self._pp703_sf(getattr(bot, 'equity', 0.0), 0.0)
            return float(tot)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

    def _pp703_usdt_irt_rate(self, bot) -> float:
        """Best-effort USDT/IRT rate from dashboard caches, then depth()."""
        try:
            r = self._pp703_sf(getattr(bot, '_dash_usdt_rate', 0.0), 0.0)
            if r > 0.0:
                return float(r)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        try:
            pm = getattr(bot, '_dash_price_map', None) or {}
            r = self._pp703_sf((pm or {}).get('USDT', 0.0), 0.0)
            if r > 0.0:
                return float(r)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        try:
            api = (getattr(bot, 'apis', {}) or {}).get('W1')
        except Exception:
            api = None
        if api is not None:
            try:
                depth = api.depth('USDTIRT')
                try:
                    _, _, mid = _book_top(depth or {})
                except Exception:
                    mid = 0.0
                if float(mid) > 0.0:
                    return float(mid)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

        # PP916: Fallback to global USDT rate guard (keeps Alpha-Gap alive even if dashboard cache isn't ready)
        try:
            _g = globals().get("_pp9001__usdt_rate_guard")
            if callable(_g):
                rr = self._pp703_sf(_g(bot), 0.0)
                if rr > 0.0:
                    try:
                        setattr(bot, "_dash_usdt_rate", float(rr))
                    except Exception:
                        pass
                    return float(rr)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return 0.0

    def record_alpha_snapshot(self, bot, ts: float = None) -> None:
        """Record (ts, equity_irt, usdt_rate) for Alpha Gap reporting."""
        try:
            st = getattr(self, '_pp703_alpha', None)
            if not isinstance(st, dict):
                return
            snaps = st.get('snapshots')
            if snaps is None:
                return
            import time as _pp703_time
            t = float(ts or _pp703__pp920_time.time())
            eq = float(self._pp703_total_equity_irt(bot) or 0.0)
            ur = float(self._pp703_usdt_irt_rate(bot) or 0.0)
            if eq <= 0.0 or ur <= 0.0:
                return
            try:
                snaps.append((t, eq, ur))
            except Exception:
                if isinstance(snaps, list):
                    snaps.append((t, eq, ur))
                    if len(snaps) > 720:
                        del snaps[:-720]
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return

    def alpha_gap(self, window_sec: float = 3600.0) -> dict:
        """Compare bot equity growth (IRT) vs USDT/IRT growth over the same window."""
        out = {'ok': False, 'eq_ret_pct': 0.0, 'usdt_ret_pct': 0.0, 'lag_pct': 0.0}
        try:
            st = getattr(self, '_pp703_alpha', None)
            if not isinstance(st, dict):
                return out
            snaps = st.get('snapshots')
            if not snaps or len(snaps) < 2:
                return out
            try:
                now_t, now_eq, now_ur = snaps[-1]
                now_t = float(now_t)
                now_eq = float(now_eq)
                now_ur = float(now_ur)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return out
            # earliest snapshot within window
            start = None
            try:
                for t, eq, ur in snaps:
                    if (now_t - float(t)) <= float(window_sec):
                        start = (float(t), float(eq), float(ur))
                        break
            except Exception:
                start = None
            if start is None:
                try:
                    t0, eq0, ur0 = snaps[0]
                    start = (float(t0), float(eq0), float(ur0))
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return out
            t0, eq0, ur0 = start
            if eq0 <= 0.0 or ur0 <= 0.0 or now_eq <= 0.0 or now_ur <= 0.0:
                return out
            eq_ret = (now_eq / eq0 - 1.0) * 100.0
            usdt_ret = (now_ur / ur0 - 1.0) * 100.0
            lag = usdt_ret - eq_ret
            out.update({'ok': True, 'eq_ret_pct': float(eq_ret), 'usdt_ret_pct': float(usdt_ret), 'lag_pct': float(lag)})
            try:
                st['last_gap'] = float(lag)
                st['last_calc_ts'] = float(now_t)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return out
        return out

    def inflation_alert(self, window_sec: float = 3600.0, min_lag_pct: float = 0.10) -> str:
        """Return alert text if USDT growth outpaces bot equity growth."""
        try:
            g = self.alpha_gap(window_sec=window_sec)
            if not bool(g.get('ok', False)):
                return ''
            lag = float(g.get('lag_pct') or 0.0)
            if lag > float(min_lag_pct):
                msg = f"[!] Inflation Alert: Lagging by {lag:.2f}%"
                try:
                    self._pp703_alpha['last_alert'] = msg
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                return msg
            try:
                self._pp703_alpha['last_alert'] = ''
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            return ''
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return ''
class MarketContext:
    """
    Multi-timeframe market context from BTC (or configured symbol).
      - Maintains 15m + 1h bar closes (resampled from ticks)
      - Detects crash and provides bias for gating
    """

    def __init__(self):
        self.ticks: deque = deque(maxlen=5000)  # (ts, price)
        self.tf15: deque = deque(maxlen=256)    # close
        self.tf60: deque = deque(maxlen=256)    # close
        self._b15 = 0
        self._b60 = 0
        self.last_price = 0.0
        self.last_update_ts = 0.0
        self._last_analysis = {}

    def update(self, ts: float, price: float) -> None:
        try:
            p = float(price or 0.0)
        except Exception:
            p = 0.0
        if p <= 0:
            return
        try:
            t = float(ts or _pp920_time.time())
        except Exception:
            t = _pp920_time.time()
        self.last_price = float(p)
        self.last_update_ts = float(t)
        try:
            self.ticks.append((float(t), float(p)))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # resample to 15m / 1h bucket closes
        try:
            b15 = int(float(t) // 900.0)
            if self._b15 == 0:
                self._b15 = b15
            if b15 != self._b15:
                # bucket closed => append last close
                self.tf15.append(float(p))
                self._b15 = b15
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            b60 = int(float(t) // 3600.0)
            if self._b60 == 0:
                self._b60 = b60
            if b60 != self._b60:
                self.tf60.append(float(p))
                self._b60 = b60
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def detect_crash(self) -> Dict[str, Any]:
        """
        Crash heuristic (BTC):
          - drop >= 5% from peak in last 5 minutes  OR
          - drop >= 8% from peak in last 15 minutes
        """
        now = _pp920_time.time()
        cur = float(self.last_price or 0.0)
        if cur <= 0:
            return {"crash": False}
        win5 = []
        win15 = []
        try:
            for ts, px in list(self.ticks):
                age = now - float(ts)
                if age <= 900.0:
                    win15.append(float(px))
                if age <= 300.0:
                    win5.append(float(px))
        except Exception:
            win5, win15 = [], []
        peak5 = max(win5) if win5 else cur
        peak15 = max(win15) if win15 else cur
        drop5 = (peak5 - cur) / max(1e-12, peak5)
        drop15 = (peak15 - cur) / max(1e-12, peak15)
        crash = (drop5 >= 0.05) or (drop15 >= 0.08)
        out = {
            "crash": bool(crash),
            "cur": float(cur),
            "peak5": float(peak5),
            "peak15": float(peak15),
            "drop5": float(drop5),
            "drop15": float(drop15),
        }
        return out

    def analyze(self) -> Dict[str, Any]:
        """
        Return dict with:
          - slope15_pct, slope60_pct
          - bias (STRONG_BEARISH/BEARISH/NEUTRAL/BULLISH/STRONG_BULLISH)
          - spend_mult, tp_mult (contextual adjustments)
        """
        # 15m / 1h slopes (fallback to tick-window if bars are not yet available)
        s15 = _pp145_linreg_slope_pct(list(self.tf15)[-16:])
        if (len(self.tf15) < 4) and abs(float(s15)) < 1e-9:
            try:
                now = _pp920_time.time()
                vals = [float(px) for ts, px in list(self.ticks) if (now - float(ts)) <= 900.0]
                s15 = _pp145_linreg_slope_pct(list(vals)[-180:])
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        s60 = _pp145_linreg_slope_pct(list(self.tf60)[-16:])
        if (len(self.tf60) < 4) and abs(float(s60)) < 1e-9:
            try:
                now = _pp920_time.time()
                vals = [float(px) for ts, px in list(self.ticks) if (now - float(ts)) <= 3600.0]
                s60 = _pp145_linreg_slope_pct(list(vals)[-600:])
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        bias = "NEUTRAL"
        # thresholds are in percent-per-bar units (relative to mean)
        if (s60 <= -0.10 and s15 <= -0.15) or (s60 <= -0.18):
            bias = "STRONG_BEARISH"
        elif (s60 <= -0.05) or (s15 <= -0.10):
            bias = "BEARISH"
        elif (s60 >= 0.10 and s15 >= 0.15) or (s60 >= 0.18):
            bias = "STRONG_BULLISH"
        elif (s60 >= 0.05) or (s15 >= 0.10):
            bias = "BULLISH"

        spend_mult = 1.0
        tp_mult = 1.0
        if bias == "BEARISH":
            spend_mult = 0.70
            tp_mult = 0.60
        elif bias == "STRONG_BEARISH":
            spend_mult = 0.55
            tp_mult = 0.45
        elif bias == "BULLISH":
            spend_mult = 1.05
            tp_mult = 1.05
        elif bias == "STRONG_BULLISH":
            spend_mult = 1.12
            tp_mult = 1.10

        thought = f"BTC trend 15m={s15:+.2f}% 1h={s60:+.2f}% => {bias}; sizing x{spend_mult:.2f}, TP x{tp_mult:.2f}"
        out = {
            "slope15_pct": float(s15),
            "slope60_pct": float(s60),
            "bias": str(bias),
            "spend_mult": float(spend_mult),
            "tp_mult": float(tp_mult),
            "thought": thought,
            "ts": float(_pp920_time.time()),
            "price": float(self.last_price or 0.0),
        }
        self._last_analysis = dict(out)
        return out

    def recover_ok(self) -> bool:
        a = self._last_analysis or self.analyze()
        bias = str(a.get("bias") or "NEUTRAL")
        # require not bearish and some positive/flat short slope
        try:
            s15 = float(a.get("slope15_pct", 0.0) or 0.0)
            s60 = float(a.get("slope60_pct", 0.0) or 0.0)
        except Exception:
            s15, s60 = 0.0, 0.0
        if bias in ("BEARISH", "STRONG_BEARISH"):
            return False
        # additionally require short-term slope not negative
        return (s15 >= -0.02) and (s60 >= -0.05)


class LearningLoopWatchdog:
    """
    PP145 Smart watchdog (in-process):
    Detects lock/freeze in learning loop and self-recovers quickly by:
      - flushing trading_memory
      - rebuilding CognitiveBrain and EdgeModel (processing core)
    """

    def __init__(self, bot, stall_hits: int = 3):
        self.bot = bot
        self._stall_hits = 0
        self._stall_hits_max = int(stall_hits or 3)
        self._last_tick = 0.0

    def tick(self) -> None:
        now = _pp920_time.time()
        # avoid calling too frequently
        if self._last_tick and (now - self._last_tick) < 5.0:
            return
        self._last_tick = float(now)
        mem = getattr(self.bot, "trading_memory", None)
        if mem is None:
            return
        # Try to acquire quickly; if not possible, it might be frozen
        ok = False
        try:
            ok = bool(mem.try_lock(timeout=0.05))
        except Exception:
            ok = False
        if not ok:
            self._stall_hits += 1
        else:
            try:
                mem.unlock()
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            self._stall_hits = 0

        if self._stall_hits < self._stall_hits_max:
            return

        # Freeze confirmed
        self._stall_hits = 0
        try:
            lg = getattr(self.bot, "logger", None)
            if lg is not None:
                lg.critical("[PP145] Learning-loop FREEZE detected -> flushing trading_memory + rebuilding core")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # Flush memory
        try:
            mem.force_flush()
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # Rebuild core (best-effort)
        try:
            self.bot.trading_memory = TradingMemory(path=getattr(mem, "path", None))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            self.bot.brain = CognitiveBrain()
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            self.bot.model = _EdgeModel()
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            self.bot._strategic_thought = "Learning freeze recovered: memory flushed, core rebuilt."
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

def _pp145_market_signature(symst: Any, price: float, btc_price: float) -> Dict[str, Any]:
    """
    Build 'electronic market signature' for a trade.
      - RSI (symbol)
      - BTC price
      - distance from support (recent low)
    """
    try:
        px = float(price or 0.0)
    except Exception:
        px = 0.0
    try:
        btc = float(btc_price or 0.0)
    except Exception:
        btc = 0.0

    closes = []
    try:
        closes = list(getattr(symst, "prices", []) or [])
    except Exception:
        closes = []
    rsi = _pp145_rsi(closes, period=int(os.getenv("SIG_RSI_PERIOD", "14") or 14))
    support = 0.0
    dist = 0.0
    try:
        look = int(os.getenv("SUPPORT_LOOKBACK_TICKS", "120") or 120)
    except Exception:
        look = 120
    try:
        recent = [float(x) for x in closes[-look:] if x is not None]
    except Exception:
        recent = []
    if recent:
        try:
            support = float(min(recent))
        except Exception:
            support = 0.0
    if support > 0 and px > 0:
        dist = (px - support) / px
    try:
        symst.last_support = float(support)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return {
        "rsi": float(rsi),
        "btc_price": float(btc),
        "dist_from_support": float(dist),
        "support": float(support),
    }


def _pp145_apply_market_context_to_thresholds(bot: Any, buy_thr_eff: float) -> Tuple[float, Dict[str, Any]]:
    """
    Apply contextual gating (15m + 1h) to buy threshold.
    If market is bearish => tighten buying.
    """
    mkt = getattr(bot, "_mkt_analysis", None) or {}
    bias = str(mkt.get("bias") or "NEUTRAL")
    try:
        b = float(buy_thr_eff or 0.0)
    except Exception:
        b = 0.0
    if bias == "BEARISH":
        b += 0.06
    elif bias == "STRONG_BEARISH":
        b += 0.10
    b = max(0.0, min(0.99, float(b)))
    return float(b), dict(mkt)


def _pp145_dynamic_tp_pct(bot: Any) -> float:
    try:
        base = float(os.getenv("TP_BASE_PCT", "0.012") or 0.012)
    except Exception:
        base = 0.012
    mkt = getattr(bot, "_mkt_analysis", None) or {}
    try:
        tp_mult = float(mkt.get("tp_mult", 1.0) or 1.0)
    except Exception:
        tp_mult = 1.0
    tp = float(base) * float(tp_mult)
    # keep reasonable bounds
    return float(max(0.002, min(0.05, tp)))


def _pp145_market_precheck(bot: Any) -> None:
    """
    Update global market context once per cycle (BTC 15m + 1h trend) and manage Panic Mode.
    """
    try:
        api = (getattr(bot, "apis", {}) or {}).get("W1")
    except Exception:
        api = None
    if api is None:
        return
    sym = str(getattr(bot, "market_trend_symbol", "BTCIRT") or "BTCIRT").strip().upper()
    ts = _pp920_time.time()

    mid = 0.0
    try:
        depth = api.depth(sym)
        _, _, mid = _book_top(depth or {})
    except Exception:
        mid = 0.0

    # fallback: use cached price map from metas if available
    if mid <= 0.0:
        try:
            mp = getattr(bot, "_dash_symbol_px_map", {}) or getattr(bot, "_dash_price_map", {}) or {}
            mid = float(mp.get(sym, 0.0) or 0.0)
        except Exception:
            mid = 0.0

    if mid <= 0.0:
        return

    ctx = getattr(bot, "_mkt_ctx", None)
    if ctx is None:
        return
    try:
        ctx.update(ts, float(mid))
    except Exception as _pp210_e:
        _pp200_heal(_pp210_e, tag="mkt_ctx_update")
        return

    analysis = {}
    try:
        analysis = ctx.analyze()
    except Exception:
        analysis = {}
    try:
        bot._mkt_analysis = dict(analysis or {})
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    crash = {}
    try:
        crash = ctx.detect_crash()
    except Exception:
        crash = {"crash": False}

    is_crash = bool((crash or {}).get("crash", False))
    if is_crash and (not bool(getattr(bot, "_panic_mode", False))):
        bot._panic_mode = True
        bot._panic_since = float(ts)
        bot._panic_reason = f"MarketCrash drop5={float(crash.get('drop5', 0.0))*100:.1f}% drop15={float(crash.get('drop15', 0.0))*100:.1f}%"
        bot._strategic_thought = f"PANIC MODE: {bot._panic_reason} — buys halted; waiting for trend recovery."
        try:
            lg = getattr(bot, "logger", None)
            if lg is not None:
                lg.critical(f"[PP145] PANIC MODE ON: {bot._panic_reason}")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    if bool(getattr(bot, "_panic_mode", False)):
        # Exit panic when crash is no longer detected and trends are not bearish.
        try:
            if (not is_crash) and bool(ctx.recover_ok()):
                bot._panic_mode = False
                bot._panic_reason = ""
                bot._strategic_thought = "Panic cleared: trend recovery confirmed; resuming normal entries."
                try:
                    lg = getattr(bot, "logger", None)
                    if lg is not None:
                        lg.warning("[PP145] PANIC MODE OFF: recovery confirmed.")
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    else:
        # Normal strategic thought summary
        base = str((analysis or {}).get("thought") or "Market context updating...")
        bot._strategic_thought = base


class CognitiveCore:
    """
    PP155 CognitiveCore (Operational 3-Layer Intelligence):
      - Memory: save_trade_outcome(result) persists outcomes to JSON (cognitive_memory.json by default)
      - Learning: if a symbol records >3 consecutive losses, blacklist it for 3 hours
      - Trend Prediction: get_market_sentiment() via linear regression => "Bullish" | "Bearish" | "Sideways"
      - Dynamic Sizing: Kelly-based sizing scaled by prediction confidence
      - Telemetry: experience-vs-algorithm decision ratios (for IQ / BRAIN STATUS)
    """

    def __init__(self, bot=None):
        self.bot = bot
        self.experience_map = {}  # sym -> {"wins":int,"losses":int,"streak_loss":int,"blocked_until":float}
        self._lock = threading.RLock()
        self.decisions_total = 0
        self.decisions_experience = 0

        self.last_sentiment = "Sideways"
        self.last_confidence = 0.0
        self.last_thought = "COGNITIVE CORE ONLINE."

        try:
            self.memory_path = str(_os.getenv("COGNITIVE_MEMORY_PATH", "cognitive_memory.json") or "cognitive_memory.json").strip()
        except Exception:
            self.memory_path = "cognitive_memory.json"
        self._state = {"version": "v155", "symbols": {}, "trades": []}
        self._last_save_ts = 0.0
        self._load_state()

    def _clamp(self, x, lo=0.0, hi=1.0):
        try:
            v = float(x)
        except Exception:
            v = 0.0
        if v < lo:
            return float(lo)
        if v > hi:
            return float(hi)
        return float(v)

    def _load_state(self) -> None:
        p = str(self.memory_path or "").strip() or "cognitive_memory.json"
        try:
            if not os.path.exists(p):
                return
            with open(p, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                return
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return

        try:
            syms = data.get("symbols", {}) if isinstance(data.get("symbols", {}), dict) else {}
        except Exception:
            syms = {}

        now = _pp920_time.time()
        with self._lock:
            try:
                self._state = data if isinstance(data, dict) else {"version": "v155", "symbols": {}, "trades": []}
            except Exception:
                self._state = {"version": "v155", "symbols": {}, "trades": []}

            # hydrate experience_map
            for k, v in (syms or {}).items():
                try:
                    sym = str(k).strip().upper()
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_continue")
                    continue
                if not sym:
                    continue
                rec = {"wins": 0, "losses": 0, "streak_loss": 0, "blocked_until": 0.0}
                if isinstance(v, dict):
                    try:
                        rec["wins"] = int(v.get("wins", 0) or 0)
                    except Exception:
                        rec["wins"] = 0
                    try:
                        rec["losses"] = int(v.get("losses", 0) or 0)
                    except Exception:
                        rec["losses"] = 0
                    try:
                        rec["streak_loss"] = int(v.get("streak_loss", 0) or 0)
                    except Exception:
                        rec["streak_loss"] = 0
                    try:
                        rec["blocked_until"] = float(v.get("blocked_until", 0.0) or 0.0)
                    except Exception:
                        rec["blocked_until"] = 0.0
                if float(rec.get("blocked_until", 0.0) or 0.0) <= float(now):
                    rec["blocked_until"] = 0.0
                self.experience_map[sym] = rec

    def _save_state(self) -> None:
        p = str(self.memory_path or "").strip() or "cognitive_memory.json"
        try:
            d = os.path.dirname(p) or "."
            os.makedirs(d, exist_ok=True)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # atomic write
        tmp = p + ".tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(self._state, f, ensure_ascii=False, indent=2)
            try:
                os.replace(tmp, p)
            except Exception:
                try:
                    if os.path.exists(p):
                        os.remove(p)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                try:
                    os.rename(tmp, p)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

        except Exception:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

    def trend_vector(self, prices):
        """
        Linear regression on recent prices.
        Returns dict: {slope, slope_pct, r2, confidence}
        """
        try:
            y = [float(x) for x in (prices or []) if x is not None]
        except Exception:
            y = []
        if len(y) < 3:
            return {"slope": 0.0, "slope_pct": 0.0, "r2": 0.0, "confidence": 0.0}

        # use last N points
        try:
            max_n = int(_os.getenv("PP155_LINREG_N", "24") or 24)
        except Exception:
            max_n = 24
        if max_n < 3:
            max_n = 3
        y = y[-max_n:]
        n = len(y)

        # x = 0..n-1
        sx = (n - 1) * n / 2.0
        sxx = (n - 1) * n * (2 * n - 1) / 6.0
        sy = sum(y)
        sxy = 0.0
        for i, yi in enumerate(y):
            sxy += float(i) * float(yi)

        den = float(n) * float(sxx) - float(sx) * float(sx)
        if abs(den) <= 1e-12:
            slope = 0.0
            intercept = float(sy) / float(n)
        else:
            slope = (float(n) * float(sxy) - float(sx) * float(sy)) / float(den)
            intercept = (float(sy) - float(slope) * float(sx)) / float(n)

        # r2
        try:
            y_mean = float(sy) / float(n)
        except Exception:
            y_mean = 0.0
        ss_tot = 0.0
        ss_res = 0.0
        for i, yi in enumerate(y):
            y_hat = float(intercept) + float(slope) * float(i)
            ss_tot += (float(yi) - float(y_mean)) ** 2
            ss_res += (float(yi) - float(y_hat)) ** 2
        r2 = 1.0 - (ss_res / ss_tot) if ss_tot > 1e-12 else 0.0
        r2 = self._clamp(r2, 0.0, 1.0)

        mu = max(1e-12, abs(float(y_mean)))
        slope_pct = float(slope) * float(n - 1) / mu * 100.0

        # conservative confidence
        confidence = self._clamp(0.10 + 0.90 * float(r2), 0.0, 1.0)
        return {"slope": float(slope), "slope_pct": float(slope_pct), "r2": float(r2), "confidence": float(confidence)}

    def note_decision(self, experience: bool) -> None:
        with self._lock:
            self.decisions_total += 1
            if experience:
                self.decisions_experience += 1

    def brain_status(self):
        with self._lock:
            tot = max(1, int(self.decisions_total))
            exp_pct = 100.0 * float(self.decisions_experience) / float(tot)
            alg_pct = 100.0 - float(exp_pct)
        exp_pct = self._clamp(exp_pct, 0.0, 100.0)
        alg_pct = self._clamp(alg_pct, 0.0, 100.0)
        return float(exp_pct), float(alg_pct)

    def is_blocked(self, symbol: str) -> bool:
        sym = str(symbol or "").strip().upper()
        if not sym:
            return False
        with self._lock:
            rec = dict(self.experience_map.get(sym, {}) or {})
        try:
            until = float(rec.get("blocked_until", 0.0) or 0.0)
        except Exception:
            until = 0.0
        if until <= 0.0:
            return False
        now = _pp920_time.time()
        if until <= now:
            with self._lock:
                rec = dict(self.experience_map.get(sym, {}) or {})
                rec["blocked_until"] = 0.0
                self.experience_map[sym] = rec
                try:
                    self._state.setdefault("symbols", {})
                    self._state["symbols"][sym] = dict(rec)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

            return False
        return True

    def record_symbol_pnl(self, sym: str, pnl_toman: float) -> None:
        """Update in-memory stats (does not force disk write)."""
        sym = str(sym or "").strip().upper()
        if not sym:
            return
        try:
            pnl = float(pnl_toman or 0.0)
        except Exception:
            pnl = 0.0
        now = _pp920_time.time()
        with self._lock:
            rec = dict(self.experience_map.get(sym, {}) or {})
            rec.setdefault("wins", 0)
            rec.setdefault("losses", 0)
            rec.setdefault("streak_loss", 0)
            rec.setdefault("blocked_until", 0.0)

            if pnl > 0.0:
                rec["wins"] = int(rec.get("wins", 0) or 0) + 1
                rec["streak_loss"] = 0
            elif pnl < 0.0:
                rec["losses"] = int(rec.get("losses", 0) or 0) + 1
                rec["streak_loss"] = int(rec.get("streak_loss", 0) or 0) + 1
                # PP155 Learning: >3 consecutive losses => 3h blacklist
                if int(rec["streak_loss"]) > 3:
                    rec["blocked_until"] = float(now + 3 * 3600.0)
            # pnl==0: no change

            # clear expired blocks
            try:
                if float(rec.get("blocked_until", 0.0) or 0.0) <= float(now):
                    rec["blocked_until"] = 0.0
            except Exception:
                rec["blocked_until"] = 0.0

            self.experience_map[sym] = rec
            try:
                self._state.setdefault("symbols", {})
                self._state["symbols"][sym] = dict(rec)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

    def save_trade_outcome(self, result) -> None:
        """
        Persist a trade outcome to JSON and update learning stats.

        Expected result shape (best-effort):
          - dict: {"symbol": "BTCIRT", "pnl_toman": 1234.0, ...}
          - OR any obj with .symbol and .pnl_toman/.pnl
        """
        sym = ""
        pnl = 0.0

        try:
            if isinstance(result, dict):
                sym = str(result.get("symbol", "") or "").strip().upper()
                if "pnl_toman" in result:
                    pnl = float(result.get("pnl_toman", 0.0) or 0.0)
                elif "pnl" in result:
                    pnl = float(result.get("pnl", 0.0) or 0.0)
                else:
                    pnl = float(result.get("profit", 0.0) or 0.0)
            else:
                sym = str(getattr(result, "symbol", "") or "").strip().upper()
                if hasattr(result, "pnl_toman"):
                    pnl = float(getattr(result, "pnl_toman", 0.0) or 0.0)
                elif hasattr(result, "pnl"):
                    pnl = float(getattr(result, "pnl", 0.0) or 0.0)
                else:
                    pnl = float(getattr(result, "profit", 0.0) or 0.0)
        except Exception:
            sym = ""
            pnl = 0.0

        if not sym:
            return

        # Update stats
        self.record_symbol_pnl(sym, float(pnl))

        now = _pp920_time.time()
        with self._lock:
            try:
                self._state.setdefault("trades", [])
                self._state["trades"].append({"ts": float(now), "symbol": sym, "pnl_toman": float(pnl)})
                # cap history
                max_hist = int(_os.getenv("PP155_MAX_COG_TRADES", "2000") or 2000)
                if max_hist < 100:
                    max_hist = 100
                if len(self._state["trades"]) > max_hist:
                    self._state["trades"] = self._state["trades"][-max_hist:]
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            # throttled save
            try:
                min_gap = float(_os.getenv("PP155_SAVE_MIN_GAP", "0.8") or 0.8)
            except Exception:
                min_gap = 0.8
            if (now - float(self._last_save_ts)) >= float(min_gap):
                self._last_save_ts = float(now)
                self._save_state()

        # refresh last_thought (for dashboard)
        try:
            if self.is_blocked(sym):
                self.last_thought = f"Learning from losses in {sym}; blacklisted for cooldown (3h)."
            else:
                if float(pnl) < 0:
                    self.last_thought = f"Learning from past loss in {sym}; standing by for recovery..."
                elif float(pnl) > 0:
                    self.last_thought = f"Trade success in {sym}; reinforcing current behavior."
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def get_market_sentiment(self, prices=None, symbol: str | None = None) -> str:
        """
        Sentiment classifier based on linear regression slope_pct + confidence.
        Returns: "Bullish" | "Bearish" | "Sideways"
        """
        p = None
        if prices is not None:
            try:
                p = [float(x) for x in (prices or []) if x is not None]
            except Exception:
                p = None

        if p is None:
            # best-effort: pull from bot market context
            try:
                bot = self.bot
                ctx = getattr(bot, "_mkt_ctx", None) if bot is not None else None
                if ctx is not None and getattr(ctx, "tf15", None):
                    p = [float(x) for x in list(getattr(ctx, "tf15", []))[-36:]]
                elif ctx is not None and getattr(ctx, "tf60", None):
                    p = [float(x) for x in list(getattr(ctx, "tf60", []))[-36:]]
                elif ctx is not None and getattr(ctx, "ticks", None):
                    p = [float(px) for (_, px) in list(getattr(ctx, "ticks", []))[-60:]]
            except Exception:
                p = None

        if not p or len(p) < 6:
            self.last_sentiment = "Sideways"
            return "Sideways"

        tv = self.trend_vector(p)
        slope_pct = float(tv.get("slope_pct", 0.0) or 0.0)
        conf = float(tv.get("confidence", 0.0) or 0.0)
        self.last_confidence = float(conf)

        try:
            thr = float(_os.getenv("PP155_SENTIMENT_SLOPE_PCT", "0.25") or 0.25)  # percent over window
        except Exception:
            thr = 0.25

        # If confidence is low, avoid strong regime calls
        try:
            min_conf = float(_os.getenv("PP155_SENTIMENT_MIN_CONF", "0.45") or 0.45)
        except Exception:
            min_conf = 0.45

        if conf < min_conf:
            self.last_sentiment = "Sideways"
            return "Sideways"

        if slope_pct > abs(thr):
            self.last_sentiment = "Bullish"
            return "Bullish"
        if slope_pct < -abs(thr):
            self.last_sentiment = "Bearish"
            return "Bearish"

        self.last_sentiment = "Sideways"
        return "Sideways"

    def compose_thought(self, *, symbol: str | None = None, sentiment: str | None = None, confidence: float | None = None) -> str:
        sym = str(symbol or "").strip().upper()
        sent = str(sentiment or self.last_sentiment or "Sideways")
        try:
            conf = float(confidence if confidence is not None else self.last_confidence)
        except Exception:
            conf = 0.0

        if sym and self.is_blocked(sym):
            return f"Learning from past loss in {sym}; standing by for recovery (blacklisted 3h)."

        c_pct = int(self._clamp(conf, 0.0, 1.0) * 100.0)
        if sent == "Bearish":
            return f"Trend is bearish; reducing trade size. Confidence: {c_pct}%"
        if sent == "Bullish":
            return f"Trend is positive; increasing trade size (Kelly). Confidence: {c_pct}%"
        return f"Analyzing market context... Confidence: {c_pct}% - waiting for clearer signal."

    def dynamic_sizing(self, cash: float, base_cap: float, confidence: float) -> float:
        """
        Returns adjusted cap_quote based on:
          - Kelly fraction (from TradingMemory)
          - Prediction confidence (0..1)
        Output: [0..min(cash, base_cap)]
        """
        try:
            cash_f = float(cash or 0.0)
        except Exception:
            cash_f = 0.0
        try:
            cap = float(base_cap or 0.0)
        except Exception:
            cap = 0.0
        if cash_f <= 0.0 or cap <= 0.0:
            return 0.0

        # Kelly fraction from empirical memory
        kf = 0.02
        try:
            tm = getattr(self.bot, "trading_memory", None) if self.bot is not None else None
            if tm is not None and hasattr(tm, "kelly_fraction"):
                kf = float(tm.kelly_fraction())
        except Exception:
            kf = 0.02
        kf = self._clamp(kf, 0.0, 0.15)

        try:
            conf = self._clamp(float(confidence or 0.0), 0.0, 1.0)
        except Exception:
            conf = 0.0

        # scale Kelly by confidence (conservative)
        scale = 0.35 + 0.65 * conf  # 0.35..1.0
        eff_frac = self._clamp(kf * scale, 0.0, 0.15)

        cash_ceiling = float(cash_f) * float(eff_frac)
        out = min(float(cap), float(cash_ceiling)) if cash_f > 0.0 else 0.0

        # Safety floor
        try:
            floor_frac = float(_os.getenv("PP155_MIN_FRACTION", "0.005") or 0.005)  # 0.5%
        except Exception:
            floor_frac = 0.005
        out = max(0.0, min(float(cap), max(float(out), float(cash_f) * float(floor_frac))))
        return float(out)


class DashboardManager:
    """
    PP130 Fixed TUI Dashboard (Rich)
    - Screen mode (no scroll), refresh every ~5 seconds
    - English-only labels, unit: TOMAN
    - Uses terminal height ("length") by stacking 5 sections:
        W1 / W2 / W3 / REPORTS / TOP 8
    - Minimal colors (~90% B/W): Cyan header, PnL green/red, small status highlights.
    """

    def __init__(self, bot, refresh_sec: float = 5.0):
        self.bot = bot
        self.refresh_sec = float(refresh_sec or 5.0)
        self._stop = threading.Event()
        self._thr = None

    def start(self):
        if self._thr and self._thr.is_alive():
            return
        self._stop.clear()
        target = getattr(self, "_run", None)
        if not callable(target):
            # Safety net for partial/older builds: don't crash the whole bot if UI runner is missing.
            def _fallback_runner():
                import time as _time
                while not self._stop.is_set():
                    _time.sleep(1.0)
            target = _fallback_runner
        self._thr = threading.Thread(target=target, name="DashboardManager", daemon=True)
        self._thr.start()

    def stop(self):
        self._stop.set()
        try:
            if self._thr:
                self._thr.join(timeout=1.0)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    @staticmethod
    def _money_short(x: float) -> str:
        try:
            v = float(x or 0.0)
        except Exception:
            v = 0.0
        a = abs(v)
        if a >= 1e12:
            s = f"{v/1e12:.2f}T"
        elif a >= 1e9:
            s = f"{v/1e9:.2f}B"
        elif a >= 1e6:
            s = f"{v/1e6:.2f}M"
        elif a >= 1e3:
            s = f"{v/1e3:.2f}K"
        else:
            s = f"{v:.0f}"
        return f"{s} TOMAN"

    def _wallet_snapshot(self, wname: str) -> dict:
        out = {"ok": True, "name": wname, "cash": 0.0, "eq": 0.0, "engaged": 0.0, "assets": [], "pnl": 0.0, "open_steps": 0, "usdt_timer": None, "strategy": ""}
        bot = self.bot

        # v8040-liveness: keep dashboard Status/Reason fresh (no silent WAITING).
        # Observability only; does NOT change trading logic.
        try:
            _pp8029_ensure_wallet_status_recent(
                bot,
                str(wname or "").strip() or "W?",
                now_ts=time.time(),
                heartbeat_reason="SCAN",
            )
        except Exception as e:
            # No silent failure: surface dashboard liveness issues.
            try:
                _pp8029_set_wallet_status(
                    bot,
                    str(wname or "").strip() or "W?",
                    "WAITING",
                    f"DASH_LIVENESS_FAIL {type(e).__name__}",
                    src="DASH",
                    prio=3,
                    stale_after=2.0,
                )
            except Exception:
                pass
            try:
                _pp9001_push_dash_buy_debug(
                    bot,
                    str(wname or "").strip() or "W?",
                    f"DASH_LIVENESS_FAIL {type(e).__name__}",
                )
            except Exception:
                pass

        # v8027: Veto Transparency (per-wallet last blocker message)
        try:
            _wm = getattr(bot, "_dash_wallet_last_veto", {}) or {}
            if isinstance(_wm, dict):
                out["last_veto"] = str(_wm.get(wname, "") or "")
            else:
                out["last_veto"] = ""
        except Exception:
            out["last_veto"] = ""
        # v8027: Optional status override produced by main loop (wallet-isolated)
        try:
            _sm = getattr(bot, "_dash_wallet_status", {}) or {}
            if isinstance(_sm, dict) and wname in _sm and isinstance(_sm.get(wname), dict):
                out["status_override"] = str((_sm.get(wname) or {}).get("status", "") or "")
                out["wait_reason"] = _pp8031_safe_reason(str((_sm.get(wname) or {}).get("reason", "") or ""), default="SCAN")
        except Exception:
            pass
        try:
            # caches are maintained by the main loop (guard with dash lock to prevent partial reads)
            _lk = getattr(bot, "_dash_lock", None)
            if _lk is None:
                bc_free = getattr(bot, "_dash_balances_cache", {}) or {}
                bc_total = getattr(bot, "_dash_balances_total_cache", None)
                if not isinstance(bc_total, dict):
                    bc_total = bc_free
                ec_free = getattr(bot, "_dash_equity_cache", {}) or {}
                ec_total = getattr(bot, "_dash_equity_total_cache", None)
                if not isinstance(ec_total, dict):
                    ec_total = ec_free
                errs = getattr(bot, "_dash_wallet_errors", {}) or {}
                b_free = bc_free.get(wname, {}) or {}
                b = bc_total.get(wname, {}) or b_free
                _cash = float(b_free.get(getattr(bot, "quote", "IRT"), 0.0) or 0.0)
                _eq = float(ec_total.get(wname, 0.0) or 0.0)
            else:
                with _lk:
                    bc_free = getattr(bot, "_dash_balances_cache", {}) or {}
                    bc_total = getattr(bot, "_dash_balances_total_cache", None)
                    if not isinstance(bc_total, dict):
                        bc_total = bc_free
                    ec_free = getattr(bot, "_dash_equity_cache", {}) or {}
                    ec_total = getattr(bot, "_dash_equity_total_cache", None)
                    if not isinstance(ec_total, dict):
                        ec_total = ec_free
                    errs = getattr(bot, "_dash_wallet_errors", {}) or {}
                    b_free = bc_free.get(wname, {}) or {}
                    b = bc_total.get(wname, {}) or b_free
                    _cash = float(b_free.get(getattr(bot, "quote", "IRT"), 0.0) or 0.0)
                    _eq = float(ec_total.get(wname, 0.0) or 0.0)
            st = (getattr(bot, "states", {}) or {}).get(wname)
            if errs.get(wname):
                out["ok"] = False
                out["err"] = str(errs.get(wname))
            out["cash"] = _cash
            out["eq"] = _eq
            # v12: attach sanity status + buy debug ring for this wallet
            try:
                out["sanity"] = str(getattr(bot, "_dash_sanity_halt_reason", "") or "")
            except Exception:
                out["sanity"] = ""
            try:
                _bdm = getattr(bot, "_dash_buy_debug", {}) or {}
                _bd = _bdm.get(wname)
                if _bd:
                    out["buy_debug"] = list(_bd)[:10]
                else:
                    out["buy_debug"] = []
            except Exception:
                out["buy_debug"] = []
            # PP722: show engaged IRT (equity minus free cash) + sanctuary countdown
            try:
                out["engaged"] = max(0.0, float(out.get("eq", 0.0) or 0.0) - float(out.get("cash", 0.0) or 0.0))
            except Exception:
                out["engaged"] = 0.0
            try:
                rem = None
                try:
                    rem = (getattr(bot, "_pp722_sanctuary_remaining", {}) or {}).get(wname)
                except Exception:
                    rem = None
                if rem is not None:
                    out["usdt_timer"] = float(rem or 0.0)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            # PP130: derive PnL + open positions from best-effort position estimates
            try:
                pmap = getattr(bot, "_dash_price_map", {}) or {}
                _pnl = 0.0
                _steps = 0
                ps = getattr(st, "per_symbol", {}) or {}
                for _sym, _symst in (ps or {}).items():
                    try:
                        _pq = float(getattr(_symst, "pos_qty", 0.0) or 0.0)
                    except Exception:
                        _pq = 0.0
                    if _pq > 0.0:
                        try:
                            _ae = float(getattr(_symst, "avg_entry_price", 0.0) or 0.0)
                        except Exception:
                            _ae = 0.0
                        # Active trade is defined as a non-zero entry price (prevents treating passive holdings as trades).
                        if _ae > 0.0:
                            _steps += 1
                        try:
                            _px = float(pmap.get(_sym, 0.0) or 0.0)
                        except Exception:
                            _px = 0.0
                        # Last-known-price fallback for P&L (works even if API/Internet is down)
                        if _px <= 0.0:
                            try:
                                _su = str(_sym or "").upper().strip()
                                _lk = float(_pp_price_cache_get(_su, 0.0) or 0.0)
                                if _lk <= 0.0 and _su.endswith("IRT") and len(_su) > 3:
                                    _lk = float(_pp_price_cache_get(_su[:-3], 0.0) or 0.0)
                                if _lk > 0.0:
                                    _px = float(_lk)
                            except Exception as _pp200_e:
                                _pp200_report(_pp200_e, tag="exc_pass")
                        if _ae > 0.0 and _px > 0.0:
                            _pnl += (float(_px) - float(_ae)) * float(_pq)
                out["pnl"] = float(_pnl)
                out["open_steps"] = int(_steps)
            except Exception:
                out["pnl"] = 0.0
                out["open_steps"] = 0
            try:
                out["strategy"] = str(getattr(st, "strategy_line", "") or "")
            except Exception:
                out["strategy"] = ""
            assets_tmp = []  # (asset, display_value_str, sort_abs_decimal)
            try:
                from decimal import Decimal
            except Exception:
                Decimal = None  # type: ignore

            for k, v in (b or {}).items():
                if k == getattr(bot, 'quote', 'IRT'):
                    continue
                ak = str(k)
                auk = ak.upper().strip()
                if not auk:
                    continue

                try:
                    d = _pp7826__to_dec(v)
                except Exception:
                    try:
                        d = Decimal(str(v)) if Decimal is not None else 0.0
                    except Exception:
                        d = Decimal('0') if Decimal is not None else 0.0

                try:
                    s = format(d, '.8f')
                except Exception:
                    try:
                        s = format(float(v or 0.0), '.8f')
                    except Exception:
                        s = '0.00000000'

                try:
                    sortv = abs(Decimal(s)) if Decimal is not None else abs(float(s))
                except Exception:
                    sortv = Decimal('0') if Decimal is not None else 0.0

                try:
                    if (Decimal is not None and sortv > Decimal('0')) or (Decimal is None and float(sortv) > 0.0):
                        assets_tmp.append((ak, s, sortv))
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

            try:
                assets_tmp.sort(key=lambda t: (-t[2], t[0]))
            except Exception:
                try:
                    assets_tmp.sort(key=lambda t: (t[0],))
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

            assets = [(a, v) for (a, v, _sv) in assets_tmp]
            out['assets'] = assets
        except Exception as e:
            out["ok"] = False
            out["err"] = str(e)
        return out

    def _status_cell(self, snap: dict) -> str:
        """Deterministic wallet Status/Reason renderer (LIVE-safe).

        - WAITING/HOLD must always have a non-empty reason.
        - Reason must be visible in Termux (avoid dim-only text).
        - Formatting must survive narrow panels: 2-line layout (Status + R:).
        - Debug is never allowed to substitute Status.
        """
        try:
            if not bool(snap.get("ok", True)):
                return "[red]OFFLINE[/red]"

            ov = str(snap.get("status_override") or "").strip().upper()
            wr = _pp8031_safe_reason(str(snap.get("wait_reason") or ""), default="SCAN").strip()

            # Explicit overrides from SFDA / main loop (wallet-isolated)
            if ov == "TRADING":
                return "[green]Status: TRADING[/green]"

            # HOLD means: no trade this cycle (still show the real reason)
            if ov in ("WAITING", "HOLD") and wr:
                return f"[yellow]Status: WAITING[/yellow]\nR: {wr}"

            if ov in ("BUY", "SELL") and wr:
                # In rare cases UI receives BUY/SELL tags; render as TRADING with reason.
                return f"[green]Status: TRADING[/green]\nR: {wr}"

            # Never allow "WAITING with empty reason" to leak into UI.
            if ov in ("WAITING", "HOLD") and (not wr):
                ov = ""

            # Compute deterministic WAITING reason from real state (fallback)
            steps = int(snap.get("open_steps") or 0)
            cash = float(snap.get("cash") or 0.0)
            minv = float(snap.get("min_cash") or 0.0)
            veto = _pp8031_safe_reason(str(snap.get("last_veto") or ""), default="").strip()

            if cash < minv and minv > 0:
                # provable but compact (k-units)
                try:
                    ck = int(max(0.0, cash) // 1000)
                    mk = int(max(0.0, minv) // 1000)
                    rs = f"L-CASH {ck}k<{mk}k"
                except Exception:
                    rs = "L-CASH"
                return f"[yellow]Status: WAITING[/yellow]\nR: {rs}"

            if steps <= 0:
                # STEP=0 => no active trade (scan mode).
                if veto:
                    v = veto.upper()
                    if len(v) > 42:
                        v = v[:41] + "…"
                    rs = f"VETO {v}"
                else:
                    rs = "SCAN"
                return f"[yellow]Status: WAITING[/yellow]\nR: {rs}"

            # active ladder steps
            return f"[green]Status: ACTIVE[/green] [dim]steps={steps}[/dim]"
        except Exception:
            return "[yellow]Status: WAITING[/yellow]\nR: UNKNOWN"
    def _wallet_panel(self, wname: str):
        """Compact, readable wallet panel for Termux.

        IMPORTANT:
        - No feature removal: keeps Equity/Cash/Engaged/Steps/USDT timer + Assets summary + P&L + Strategy.
        - Defaults to compact layout to reduce vertical overflow on phone screens.
        - Set WALLET_PANEL_MODE=full to render the verbose table.
        """
        import os
        from rich.panel import Panel
        from rich.table import Table
        from rich.text import Text
        from rich import box

        s = self._wallet_snapshot(wname)
        mode = str(os.getenv("WALLET_PANEL_MODE", "compact") or "compact").strip().lower()
        if mode not in ("compact", "full"):
            mode = "compact"

        if not s.get("ok", True):
            t = Table.grid(padding=(0, 1))
            t.expand = True
            t.add_column(ratio=1)
            t.add_row(Text("OFFLINE", style="bold red"))
            err = str(s.get("err") or "Connection Error")[:200]
            t.add_row(Text(err, style="white"))
            return Panel(t, title=f"{wname}", box=box.SQUARE, padding=(0, 1), style="white on black", expand=True)

        try:
            eq = float(s.get("eq") or 0.0)
        except Exception:
            eq = 0.0
        try:
            cash = float(s.get("cash") or 0.0)
        except Exception:
            cash = 0.0
        try:
            engaged = float(s.get("engaged") or 0.0)
        except Exception:
            engaged = 0.0
        try:
            steps = int(s.get("open_steps") or 0)
        except Exception:
            steps = 0
        try:
            pnl = float(s.get("pnl") or 0.0)
        except Exception:
            pnl = 0.0

        strat = (s.get("strategy") or "").strip() or "PREDICTING MARKET"
        status = self._status_cell(s)

        # USDT timer label
        ut_s = ""
        try:
            ut = s.get("usdt_timer", None)
            if ut is not None:
                rv = float(ut or 0.0)
                if rv <= 0.0:
                    ut_s = "READY"
                else:
                    mm = int(rv) // 60
                    ss = int(rv) % 60
                    ut_s = f"{mm:02d}:{ss:02d}"
        except Exception:
            ut_s = ""

        # Assets summary (single line)
        assets = s.get("assets") or []
        def _fmt_amt(v):
            # If value already provided as fixed 8dp string (e.g. BTC), return as-is (NO float conversion).
            try:
                if isinstance(v, str):
                    sv = v.strip()
                    if sv:
                        import re as _re
                        if __pp920_re.match(r'^[-+]?\d+\.\d{8}$', sv):
                            return sv
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

            try:
                x = float(v)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return '0'
            ax = abs(x)
            if ax >= 1000:
                return f"{x:,.0f}"
            # Keep fixed 8 decimals to preserve satoshis / micro-units (no trimming).
            return f"{x:.8f}"

        a_parts = []
        try:
            for k, v in (assets or [])[:4]:
                a_parts.append(f"{k}:{_fmt_amt(v)}")
            if isinstance(assets, list) and len(assets) > 4:
                a_parts.append(f"+{len(assets) - 4}")
        except Exception:
            a_parts = []

        assets_line = " • ".join(a_parts) if a_parts else "-"
        has_trade = bool(steps and int(steps) > 0)
        if not has_trade:
            # Explicit UX requirement: never show 0 for inactive trades
            pnl_s = "[dim]NO ACTIVE TRADE[/dim]"
        else:
            pnl_style = "green" if pnl >= 0 else "red"
            # Signed TOMAN P&L for the currently open trade(s)
            pnl_s = f"[{pnl_style}]{pnl:+,.0f} TOMAN[/{pnl_style}]"

        if mode == "compact":
            t = Table.grid(padding=(0, 1))
            t.expand = True
            t.add_column(ratio=1)
            t.add_row(Text.from_markup(f"EQUITY {self._money_short(eq)}  |  CASH {self._money_short(cash)}", style="bold white"))
            line2 = f"ENG {self._money_short(engaged)}  |  STEPS {steps}"
            if ut_s:
                line2 += f"  |  USDT {ut_s}"
            t.add_row(Text(line2, style="white"))
            t.add_row(Text.from_markup(f"P&L {pnl_s}", style="white"))
            t.add_row(Text.from_markup(f"ASSETS {assets_line}", style="white"))
            # v12: Status / Strategy (never truncated; never replaced by debug)
            try:
                t.add_row(Text.from_markup(str(status), style="white"))
            except Exception:
                t.add_row(Text(str(status), style="white"))
            try:
                _stx = str(strat or "").strip()
            except Exception:
                _stx = ""
            if _stx:
                if len(_stx) > 140:
                    _stx = _stx[:140] + "…"
                t.add_row(Text(f"STRAT {_stx}", style="white"))

            # v12: sanity + buy debug (why BUY was rejected)
            try:
                _san = str(s.get("sanity") or "").strip()
            except Exception:
                _san = ""
            if _san:
                t.add_row(Text.from_markup(f"[bold red]{_san[:120]}[/bold red]"))
            try:
                _bd = s.get("buy_debug") or []
            except Exception:
                _bd = []
            if _bd:
                t.add_row(Text("BUY DEBUG:", style="bold yellow"))
                for _ln in list(_bd)[:4]:
                    t.add_row(Text(str(_ln)[:160], style="dim"))
            return Panel(t, title=f"{wname}", box=box.SQUARE, padding=(0, 1), style="white on black", expand=True)

        # Full verbose (kept as option)
        t = Table.grid(padding=(0, 1))
        t.expand = True
        t.add_column(justify="left", ratio=1)
        t.add_column(justify="right", ratio=1)
        t.add_row("EQUITY", self._money_short(eq))
        t.add_row("CASH", self._money_short(cash))
        t.add_row("STEPS", str(steps))
        t.add_row("ENGAGED", self._money_short(engaged))
        if ut_s:
            t.add_row("USDT TIMER", ut_s)
        t.add_row("ASSETS", assets_line)
        # v12: sanity + buy debug (why BUY was rejected)
        try:
            _san = str(s.get("sanity") or "").strip()
        except Exception:
            _san = ""
        if _san:
            t.add_row("SANITY", _san[:160])
        try:
            _bd = s.get("buy_debug") or []
        except Exception:
            _bd = []
        if _bd:
            t.add_row("BUY DEBUG", " | ".join([str(x)[:60] for x in list(_bd)[:3]]))
        t.add_row("P&L", Text.from_markup(pnl_s))
        # Full mode: keep STATUS and STRATEGY separate (never hide Reason).
        try:
            t.add_row("STATUS", Text.from_markup(str(status)[:240], style="white"))
        except Exception:
            t.add_row("STATUS", str(status)[:240])
        try:
            _stg = str(strat or '').strip()
            if len(_stg) > 240:
                _stg = _stg[:240] + "…"
            t.add_row("STRATEGY", _stg)
        except Exception:
            t.add_row("STRATEGY", str(strat or '')[:240])
        return Panel(t, title=f"{wname}", box=box.HEAVY, padding=(0, 1), style="white on black", expand=True)

    def _reports_panel(self):

        from rich.panel import Panel
        from rich.table import Table
        from rich.text import Text
        from rich import box

        bot = self.bot
        # global stats
        lat = 0.0
        trades = "-"
        try:
            rt = getattr(bot, "runtime_context", None) or getattr(bot, "rt", None)
            if rt is not None:
                lat = float(getattr(rt, "cycle_latency", 0.0) or 0.0)
        except Exception:
            lat = 0.0
        try:
            for k in ("total_trades", "trade_count", "trades_count", "filled_trades", "orders_filled"):
                if hasattr(bot, k):
                    v = getattr(bot, k)
                    if isinstance(v, (int, float)) and float(v) >= 0:
                        trades = str(int(v))
                        break
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # brain stats
        brain = getattr(bot, "brain", None)
        iq = 0
        conf = 0.0
        try:
            if brain is not None:
                iq = int(brain.brain_iq())
                conf = float(brain.confidence())
        except Exception:
            iq = 0
            conf = 0.0

        # last events
        events = []
        try:
            events = _dash_last_events(3) or []
        except Exception:
            events = []

        t = Table.grid(padding=(0, 1))
        t.expand = True
        t.add_column(justify="left", ratio=1)
        t.add_column(justify="right", ratio=1)


        # --- DAILY P&L + OPEN TRADES (requested) ---
        daily_pnl_toman = 0.0
        daily_pnl_pct = 0.0
        open_trades_cnt = 0
        try:
            import time as _t
            _now = float(_t.time())
            _lt = _t.localtime(_now)
            _day0 = _t.mktime((_lt.tm_year, _lt.tm_mon, _lt.tm_mday, 0, 0, 0, _lt.tm_wday, _lt.tm_yday, _lt.tm_isdst))

            # Sum realized P&L for today's closed trades (TradingMemory)
            _mem = getattr(bot, "trading_memory", None)
            _trades = []
            if _mem is not None:
                _st = getattr(_mem, "state", {}) or {}
                _trades = _st.get("trades") or []
            if isinstance(_trades, list):
                for _tr in _trades:
                    if not isinstance(_tr, dict):
                        continue
                    try:
                        _ts = float(_tr.get("ts", 0.0) or 0.0)
                    except Exception:
                        _ts = 0.0
                    if _ts < float(_day0):
                        continue
                    try:
                        daily_pnl_toman += float(_tr.get("pnl_toman", 0.0) or 0.0)
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")

            # Open trades count (positions across all wallets)
            _states0 = getattr(bot, "states", {}) or {}
            for _wname0, _st0 in (_states0 or {}).items():
                _ps0 = getattr(_st0, "per_symbol", {}) or {}
                for _sym0, _symst0 in (_ps0 or {}).items():
                    try:
                        _pq0 = float(getattr(_symst0, "pos_qty", 0.0) or 0.0)
                    except Exception:
                        _pq0 = 0.0
                    if _pq0 > 0.0:
                        open_trades_cnt += 1

            # % reference: current Net Worth (raw) if available, else sum equity caches
            _nw = 0.0
            try:
                _nw = float(getattr(bot, "_dash_net_worth_raw", 0.0) or 0.0)
            except Exception:
                _nw = 0.0
            if _nw <= 0.0:
                try:
                    _ec = getattr(bot, "_dash_equity_raw_cache", None) or getattr(bot, "_dash_equity_cache", None) or {}
                    if isinstance(_ec, dict) and _ec:
                        _nw = float(sum([float(v or 0.0) for v in _ec.values()]))
                except Exception:
                    _nw = 0.0
            if _nw > 0.0:
                daily_pnl_pct = (float(daily_pnl_toman) / float(_nw)) * 100.0
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        _dp_style = "green" if daily_pnl_toman >= 0 else "red"
        _dp_pct_s = f"{daily_pnl_pct:+.2f}%"
        _dp_t_s = f"[{_dp_style}]{daily_pnl_toman:,.0f} TOMAN[/{_dp_style}]"
        t.add_row("DAILY P&L", f"{_dp_pct_s} | {_dp_t_s}")
        t.add_row("OPEN TRADES", str(int(open_trades_cnt)))

        # --- Advanced Trade Reports (P&L / Stats / Pending) ---
        open_lbl = "-"
        open_pnl_pct = 0.0
        open_pnl_toman = 0.0
        try:
            _best_notional = 0.0
            _states = getattr(bot, "states", {}) or {}
            for _wname, _st in (_states or {}).items():
                _ps = getattr(_st, "per_symbol", {}) or {}
                for _sym, _symst in (_ps or {}).items():
                    try:
                        _pq = float(getattr(_symst, "pos_qty", 0.0) or 0.0)
                        _ae = float(getattr(_symst, "avg_entry_price", 0.0) or 0.0)
                        _mid = float(getattr(_symst, "last_mid", 0.0) or 0.0)
                    except Exception:
                        continue
                    if _pq > 0.0 and _ae > 0.0 and _mid > 0.0:
                        _pnl = (float(_mid) - float(_ae)) * float(_pq)
                        _notional = float(_ae) * float(_pq)
                        if _notional > _best_notional:
                            _best_notional = _notional
                            open_lbl = f"{str(_wname)}:{str(_sym)}"
                            open_pnl_toman = float(_pnl)
                            open_pnl_pct = (float(_mid) / float(_ae) - 1.0) * 100.0
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        # Trades succeeded today (from TradingMemory)
        succ_today = 0
        trades_today = 0
        try:
            import time as _t
            _now = float(_t.time())
            _lt = _t.localtime(_now)
            _day0 = _t.mktime((_lt.tm_year, _lt.tm_mon, _lt.tm_mday, 0, 0, 0, _lt.tm_wday, _lt.tm_yday, _lt.tm_isdst))
            _mem = getattr(bot, "trading_memory", None)
            _trades = []
            if _mem is not None:
                _st = getattr(_mem, "state", {}) or {}
                _trades = _st.get("trades") or []
            if isinstance(_trades, list):
                for _tr in _trades:
                    if not isinstance(_tr, dict):
                        continue
                    try:
                        _ts = float(_tr.get("ts", 0.0) or 0.0)
                    except Exception:
                        _ts = 0.0
                    if _ts >= float(_day0):
                        trades_today += 1
                        try:
                            _p = float(_tr.get("pnl_toman", 0.0) or 0.0)
                        except Exception:
                            _p = 0.0
                        if _p > 0.0:
                            succ_today += 1
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        # Open orders (cached snapshots)
        open_orders = 0
        try:
            _oc = getattr(bot, "_open_orders_cache", None)
            if isinstance(_oc, dict):
                for _k, _v in _oc.items():
                    try:
                        _orders = _v[1] if isinstance(_v, (list, tuple)) and len(_v) > 1 else []
                    except Exception:
                        _orders = []
                    if isinstance(_orders, list):
                        open_orders += int(len(_orders))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        # Pending (exit pending + recent order-sync failures)
        pending_exit = 0
        pending_sync = 0
        try:
            _ep = getattr(bot, "_exit_pending", None)
            if isinstance(_ep, dict):
                pending_exit = int(len(_ep))
        except Exception:
            pending_exit = 0
        try:
            import time as _t2
            _now2 = float(_t2.time())
            _hs = getattr(bot, "_order_sync_health", None)
            try:
                _gr = float(getattr(bot, "order_sync_grace_sec", 45.0) or 45.0)
            except Exception:
                _gr = 45.0
            if isinstance(_hs, dict):
                for _k, _st in _hs.items():
                    try:
                        _ts, _ok, _msg = _st
                    except Exception:
                        continue
                    if (not bool(_ok)) and ((_now2 - float(_ts or 0.0)) <= float(_gr)):
                        pending_sync += 1
        except Exception:
            pending_sync = 0
        pending_total = int(pending_exit) + int(pending_sync)

        try:
            _pnl_pct_s = f"{float(open_pnl_pct):+.2f}%"
        except Exception:
            _pnl_pct_s = "+0.00%"
        _pnl_val_s = self._money_short(float(open_pnl_toman))
        t.add_row("P&L (OPEN)", f"{open_lbl}  {_pnl_pct_s} | {_pnl_val_s}")
        t.add_row("STATS", f"Succeeded {succ_today}/{trades_today} | Open Orders {open_orders}")
        t.add_row("PENDING", f"{pending_total} (exit {pending_exit} | sync {pending_sync})")
        t.add_row("GLOBAL TRADES", trades)
        t.add_row("API LATENCY", f"{lat:.3f}s")
        # Freshness Quality: derived from timestamp of last successful price receipt from exchange
        try:
            _now = _pp920_time.time()
            _fresh = float(os.getenv("FRESH_PRICE_MAX_AGE_SEC", "10") or 10.0)
            _fresh = max(1.0, min(120.0, _fresh))

            _last = float(getattr(bot, "_pp_last_exchange_px_ts", 0.0) or 0.0)
            _age_last = None
            if _last > 0.0:
                _age_last = max(0.0, _now - _last)

            _d = getattr(bot, "_dash_depth_cache", {}) or {}
            _age_oldest = None
            try:
                _ts_list = [float(v.get("ts") or 0.0) for v in (_d or {}).values() if isinstance(v, dict) and float(v.get("ts") or 0.0) > 0.0]
                if _ts_list:
                    _age_oldest = max(0.0, _now - min(_ts_list))
            except Exception:
                _age_oldest = None

            _ages = []
            try:
                if isinstance(_age_last, (int, float)) and (0.0 <= float(_age_last) < 9000.0):
                    _ages.append(float(_age_last))
            except Exception:
                pass
            try:
                if isinstance(_age_oldest, (int, float)) and (0.0 <= float(_age_oldest) < 9000.0):
                    _ages.append(float(_age_oldest))
            except Exception:
                pass
            _max_age = max(_ages) if _ages else 9999.0

            # Smooth to avoid dashboard "jump" when one feed is momentarily late.
            _prev = float(getattr(bot, "_pp_dash_quality_age_ema", 0.0) or 0.0)
            _ema = _max_age if (_prev <= 0.0 or _prev > 9000.0) else (0.70 * _prev + 0.30 * _max_age)
            setattr(bot, "_pp_dash_quality_age_ema", float(_ema))

            _q = max(0.0, min(1.0, 1.0 - (_ema / _fresh))) if _fresh > 0.0 else 0.0
            _status = "FRESH" if _ema <= _fresh else "STALE"
            t.add_row("QUALITY", f"{_status} | Q={_q:.2f} | age={_ema:.2f}s")

            # Auto FORCE_REFRESH if stale beyond threshold (throttled)
            if (_status == "STALE") and hasattr(bot, "_pp_force_refresh_cmd"):
                try:
                    _lt = float(getattr(bot, "_pp_force_refresh_ts", 0.0) or 0.0)
                    if (_now - _lt) > 1.0:
                        bot._pp_force_refresh_cmd(reason="STALE_DASH", age=float(_max_age))
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        t.add_row("BRAIN IQ", str(iq))
        t.add_row("CONFIDENCE", f"{conf:.2f}")
        try:
            _why = str(getattr(bot, "_pp_diag_last_veto_gene", "") or "")
            if _why:
                if len(_why) > 160:
                    _why = _why[:160] + "…"
                t.add_row("WHY", _why)
        except Exception:
            pass
        try:
            _vt = int(getattr(bot, "vtoType", 0) or getattr(bot, "_pp_diag_vto_type", 0) or 0)
            t.add_row("vtoType", str(_vt))
        except Exception:
            pass

        # PP155: Strategic self-awareness text stream (CognitiveCore-first)
        try:
            _st = ""
            _cc = getattr(bot, "cognitive_core", None)
            if _cc is not None:
                try:
                    _st = str(getattr(_cc, "last_thought", "") or "")
                except Exception:
                    _st = ""
                if not _st:
                    try:
                        _st = str(_cc.compose_thought() or "")
                    except Exception:
                        _st = ""
            if not _st:
                _st = str(getattr(bot, "_strategic_thought", "") or "")
        except Exception:
            _st = ""
        if len(_st) > 160:
            _st = _st[:160] + "…"
        t.add_row("STRATEGIC_THOUGHT", _st if _st else "(n/a)")

        # PP170: LEGACY INTELLIGENCE (revived heritage status)
        try:
            _li = getattr(bot, "legacy_intel", None) or getattr(bot, "legacy_intelligence", None)
            if _li is not None:
                t.add_row("LEGACY INTELLIGENCE", "")
                try:
                    _items = list(_li.status_items())
                except Exception:
                    _items = []
                for _k, _v in (_items or [])[:10]:
                    try:
                        t.add_row(str(_k), str(_v))
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # events as a compact block (no extra colors)
        ev_text = "\n".join([str(x)[:160] for x in events]) if events else "(no events)"
        t2 = Table.grid(padding=(0, 0))
        t2.add_column(ratio=1)
        t2.add_row(Text(ev_text, style="white"))

        wrap = Table.grid(padding=(0, 1))
        wrap.expand = True
        wrap.add_column(ratio=1)
        wrap.add_row(t)
        wrap.add_row(Text("LAST EVENTS", style="bold white"))
        wrap.add_row(t2)

        return Panel(wrap, title="[bold white]REPORTS[/bold white]", box=box.HEAVY, style="white on black")


# --- DashboardManager method patch (fixes mis-indentation & enables 5-column dashboard) ---

def _ppdm__scanner_panel(self):
    """
    PP181 FIX (enhanced): Compact TOP panel.

    Root fixes:
      - If bot doesn't populate `_dash_ranked`, build a ranked TOP8 from the latest per-symbol `last_score`
        (prefers W1 state; falls back to the first available wallet state).
      - If bot doesn't populate `_dash_depth_cache`, fall back to `_dash_symbol_px_map` / `_dash_price_map` for prices.

    Termux-safe: if `rich` is missing, returns a plain string.
    """
    import os, time
    try:
        from rich.panel import Panel
        from rich.table import Table
        from rich.text import Text
        from rich import box
    except Exception:
        # Rich not available: return a minimal text blob.
        try:
            bot = getattr(self, "bot", None)
            syms = list(getattr(bot, "symbols", []) or []) if bot is not None else []
            return "TOP8: rich-missing | symbols=%d" % (len(syms) if syms else 0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return "TOP8: rich-missing"

    bot = getattr(self, "bot", None)
    syms = []
    try:
        syms = list(getattr(bot, "symbols", []) or []) if bot is not None else []
    except Exception:
        syms = []

    # Prefer precomputed dashboard caches (if core loop provides them)
    depth_cache = {}
    try:
        depth_cache = getattr(bot, "_dash_depth_cache", {}) or {}
    except Exception:
        depth_cache = {}

    px_fallback = {}
    try:
        px_fallback = getattr(bot, "_dash_symbol_px_map", {}) or getattr(bot, "_dash_price_map", {}) or {}
    except Exception:
        px_fallback = {}

    # Pull a lightweight score list if present (computed by intel worker)
    ranked = []
    try:
        ranked = list(getattr(bot, "_dash_ranked", []) or [])
    except Exception:
        ranked = []

    # Build ranked from states if missing
    if not ranked:
        wstate = None
        try:
            states = getattr(bot, "states", {}) or {}
            wstate = states.get("W1")
            if wstate is None and states:
                # first wallet state
                wstate = next(iter(states.values()))
        except Exception:
            wstate = None

        try:
            ps = getattr(wstate, "per_symbol", {}) or {}
        except Exception:
            ps = {}

        tmp = []
        try:
            for s in (syms or [])[:64]:
                st = ps.get(s)
                sc = 0.0
                if st is not None:
                    try:
                        sc = float(getattr(st, "last_score", 0.0) or 0.0)
                    except Exception:
                        sc = 0.0
                tmp.append((str(s), float(sc)))
            tmp.sort(key=lambda x: float(x[1]), reverse=True)
            ranked = tmp[:8]
        except Exception:
            ranked = [(s, 0.0) for s in (syms or [])[:8]]

    # Fallback ranking: first N symbols
    if not ranked:
        try:
            ranked = [(s, 0.0) for s in (syms or [])[:8]]
        except Exception:
            ranked = []

    t = Table.grid(expand=True)
    t.add_column(justify="left", ratio=2)
    t.add_column(justify="right", ratio=1)

    # header
    try:
        now = time.strftime("%H:%M:%S", time.localtime())
    except Exception:
        now = "TIME"
    try:
        ver = str(os.getenv("PP_TAG", "") or os.getenv("PP_VERSION", "v186") or "v181")
    except Exception:
        ver = "v181"
    try:
        live_mode = bool(getattr(bot, "live", False)) and (not bool(getattr(bot, "dry", False)))
    except Exception:
        live_mode = False

    # Data connectivity is derived from the latest wallet snapshots (never randomized).
    _dws = getattr(bot, "_dash_wallet_status", None)
    _conn_ok = False
    try:
        if isinstance(_dws, dict) and _dws:
            _conn_ok = any(bool(v.get("conn")) for v in _dws.values() if isinstance(v, dict))
    except Exception:
        _conn_ok = False

    mode = ("LIVE" if live_mode else "DRY") + ("/ONLINE" if _conn_ok else "/OFFLINE")
    t.add_row(Text(f"TOP8  {now}", style="bold white"), Text(f"{ver} {mode}", style="white"))

    # rows
    rows = []
    try:
        for sym, sc in (ranked or [])[:8]:
            sym = str(sym)
            try:
                scf = float(sc or 0.0)
            except Exception:
                scf = 0.0

            d = depth_cache.get(sym) or {}
            bid = d.get("bid") or d.get("best_bid") or d.get("b") or 0.0
            ask = d.get("ask") or d.get("best_ask") or d.get("a") or 0.0
            try:
                bid = float(bid or 0.0)
            except Exception:
                bid = 0.0
            try:
                ask = float(ask or 0.0)
            except Exception:
                ask = 0.0
            mid = (bid + ask) / 2.0 if (bid > 0 and ask > 0) else (bid or ask or 0.0)

            # Fallback to symbol price map (meta last price) if no depth cache
            if mid <= 0.0:
                try:
                    mid = float(px_fallback.get(sym) or 0.0)
                except Exception:
                    mid = 0.0

            rows.append((sym, scf, mid))
    except Exception:
        rows = []

    if not rows:
        t.add_row(Text("(no symbols)", style="white"), Text("-", style="white"))
        return Panel(t, box=box.HEAVY, style="white on black")

    for sym, scf, mid in rows:
        # % change is computed from live mid-price history when available.
        # Ranked value is used only as a last-resort fallback.
        chg = None
        try:
            _wstate = None
            _states = getattr(bot, "states", {}) or {}
            _wstate = _states.get("W1") or (next(iter(_states.values())) if _states else None)
            _ps = getattr(_wstate, "per_symbol", {}) or {}
            _symst = _ps.get(sym)
            if _symst is not None:
                _prices = getattr(_symst, "prices", None)
                if _prices is not None:
                    try:
                        _prices = list(_prices)
                    except Exception:
                        _prices = []
                else:
                    _prices = []
                if len(_prices) >= 2:
                    _ref = float(_prices[0] or 0.0)
                    if _ref > 0.0 and float(mid) > 0.0:
                        chg = (float(mid) / _ref - 1.0) * 100.0
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        if chg is None:
            try:
                chg = float(scf or 0.0)
            except Exception:
                chg = 0.0

        try:
            schg = f"{float(chg):+.3f}%"
        except Exception:
            schg = str(chg)

        # show mid as integer (IRT)
        try:
            smid = f"{int(float(mid)):,}"
        except Exception:
            smid = str(mid)

        t.add_row(Text(sym, style="white"), Text(f"{schg} | {smid}", style="white"))

    return Panel(t, box=box.HEAVY, style="white on black")

def _to_float(x, default: float = 0.0) -> float:
    """Robust float coercion used across the bot.

    Notes:
      - Treats None/bool/empty-string as default
      - Never raises; returns `default` on any conversion error
    """
    try:
        if x is None:
            return float(default)
        if isinstance(x, bool):
            return float(default)
        if isinstance(x, (int, float)):
            # preserve finite numbers; map NaN/inf to default
            v = float(x)
            if v != v or v in (float("inf"), float("-inf")):
                return float(default)
            return v
        s = str(x).strip()
        if s == "" or s.lower() in ("nan", "none", "null", "inf", "+inf", "-inf"):
            return float(default)
        v = float(s)
        if v != v or v in (float("inf"), float("-inf")):
            return float(default)
        return v
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(default)
