# # SENTIMENT SAFETY GUARD
# # =========================
class SentimentProviderProtocol:
    """Minimal contract for sentiment providers used in live trading.

    No monkey-patching. Implementations must expose:
    - refresh(symbols) -> None  (may be sync)
    - get(symbol) -> float
    """
    def refresh(self, symbols) :  # pragma: no cover
        raise NotImplementedError

    def get(self, symbol: str) -> float:  # pragma: no cover
        raise NotImplementedError

class NewsSocialSentimentAdapter(SentimentProviderProtocol):
    """Wrap legacy sentiment implementations safely (no monkey patching)."""

    def __init__(self, impl=None):
        self._impl = impl
        self._log = logging.getLogger(__name__ + '.sentiment')

    def refresh(self, symbols):
        if self._impl is None:
            return None
        try:
            if hasattr(self._impl, 'refresh'):
                return self._impl.refresh(symbols)
            if hasattr(self._impl, 'update'):
                return self._impl.update(symbols)
            if hasattr(self._impl, 'run'):
                return self._impl.run(symbols)
            self._log.warning('Sentiment impl has no refresh/update/run; skipping')
        except Exception as e:
            self._log.exception('Sentiment refresh failed: %s', e)
        return None

    def get(self, symbol: str) -> float:
        if self._impl is None:
            return 0.0
        try:
            if hasattr(self._impl, 'get'):
                v = self._impl.get(symbol)
            elif hasattr(self._impl, 'score'):
                v = self._impl.score(symbol)
            else:
                self._log.warning('Sentiment impl has no get/score; returning 0.0')
                v = 0.0
            return float(v)
        except Exception as e:
            self._log.exception('Sentiment get failed: %s', e)
            return 0.0

