class TradeState:
    def __init__(self) :
        self.is_open = False
        self.side = None
        self.entry_price = None
        self.size = 0.0
        self.open_time = None
        self.unrealized_pnl = 0.0

class DynamicThresholdController:
    """Dynamic threshold using rolling percentile + EWMA smoothing."""

    def __init__(self, window: int = 240, percentile: float = 70.0, ewma_alpha: float = 0.18, seed_blend: float = 0.55, min_th: float = 0.12, max_th: float = 0.95):
        from collections import deque
        self.window = int(window)
        self.percentile = float(percentile)
        self.ewma_alpha = float(ewma_alpha)
        self.seed_blend = float(seed_blend)
        self.min_th = float(min_th)
        self.max_th = float(max_th)
        self.hist = deque(maxlen=max(10, self.window))
        self._ewma = None

    def update(self, scores):
        if scores is None:
            return
        try:
            it = scores if hasattr(scores, '__iter__') and not isinstance(scores, (str, bytes, dict)) else [scores]
        except Exception:
            it = [scores]
        for x in it:
            try:
                v = float(x)
                if math.isfinite(v):
                    self.hist.append(abs(v))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_continue")
                continue
    def value(self, seed: float = 0.24) -> float:
        try:
            seed = abs(float(seed))
        except Exception:
            seed = 0.24
        if not self.hist:
            base = seed
        else:
            data = sorted(self.hist)
            p = max(0.0, min(100.0, self.percentile)) / 100.0
            idx = int(round((len(data) - 1) * p))
            base = float(data[max(0, min(len(data)-1, idx))])
        target = (self.seed_blend * base) + ((1.0 - self.seed_blend) * seed)
        if self._ewma is None:
            self._ewma = target
        else:
            a = max(0.0, min(1.0, self.ewma_alpha))
            self._ewma = (a * target) + ((1.0 - a) * self._ewma)
        out = float(self._ewma)
        if not math.isfinite(out):
            out = seed
        return max(self.min_th, min(self.max_th, out))

