class RuntimeContext:
    def __init__(self) :
        self.last_cycle_ts = 0
        self.cycle_latency = 0.0

        # regime + scoring
        self.market_regime = "unknown"
        self.regime_trend = 0.0
        self.regime_vol = 0.0

        self.signal_score = 0.0
        self.signal_confidence = 0.0
        self.volatility = 0.0
        self.drawdown = 0.0
        self.base_threshold = 0.24
        self._dyn_th = DynamicThresholdController()

        # guards / injectables
        self.stress_level = 0.0
        self.risk_factor = 1.0

        # trade lock governor (hard entry gate)
        self.trade_lock_allowed = True
        self.trade_lock_reason = ""
        self.trade_lock_remaining_s = 0.0
        # macro regime (risk-on / risk-off) sensor
        self.macro_regime = "NEUTRAL"
        self.macro_score = 0.0
        self.macro_factor = 1.0

        # Adaptive per-sensor weights (regime-aware). Filled automatically in DecisionEngine.
        self.adaptive_signal_weights: Dict[str, float] = {}
        self._adaptive_signal_weight_ewma: Dict[str, float] = {}

        self.portfolio_weight = 1.0
        self.wallet_name = ""
        self.wallet_allowed = True

# ============================
# STRESS CONTEXT
# ============================

class StressContext:
    def __init__(self):
        self.api_lag = False
        self.volatility_spike = False
        self.price_gap = False
        self.level = 0.0

    def compute_level(self) -> float:
        lvl = 0.0
        if self.api_lag:
            lvl += 0.4
        if self.volatility_spike:
            lvl += 0.4
        if self.price_gap:
            lvl += 0.3
        self.level = min(1.0, float(lvl))
        return self.level

