class StressDetector:
    def __init__(self):
        self.last_price = {}

    def update(self, symbol: str, price, cycle_latency):
        stress = StressContext()
        try:
            price_f = float(price)
        except Exception:
            price_f = 0.0
        try:
            api_lag_th = float(globals().get('STRESS_API_LAG', 3.0))
        except Exception:
            api_lag_th = 3.0
        try:
            vol_spike_th = float(globals().get('STRESS_VOL_SPIKE', 0.05))
        except Exception:
            vol_spike_th = 0.05
        try:
            gap_th = float(globals().get('STRESS_PRICE_GAP', 0.03))
        except Exception:
            gap_th = 0.03
        try:
            if float(cycle_latency or 0.0) > api_lag_th:
                stress.api_lag = True
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        prev = float(self.last_price.get(symbol, 0.0) or 0.0)
        if prev > 0 and price_f > 0:
            change = abs(price_f - prev) / prev
            if change > vol_spike_th:
                stress.volatility_spike = True
            if change > gap_th:
                stress.price_gap = True
        if price_f > 0 and math.isfinite(price_f):
            self.last_price[symbol] = price_f
        stress.compute_level()
        return stress

