# # ============================
# # LATENCY WATCHDOG (REST)
# # ============================
class LatencyWatchdog:
    """REST latency watchdog: returns stress level 0..1."""

    def __init__(self, warn: float = 3.0, critical: float = 6.0, ewma_alpha: float = 0.25):
        self.warn = float(warn)
        self.critical = float(critical)
        self.ewma_alpha = float(ewma_alpha)
        self.ewma = None

    def update(self, latency_seconds: float) -> float:
        try:
            lat = float(latency_seconds or 0.0)
        except Exception:
            lat = 0.0
        if not math.isfinite(lat) or lat < 0:
            lat = 0.0
        if self.ewma is None:
            self.ewma = lat
        else:
            a = max(0.01, min(0.99, self.ewma_alpha))
            self.ewma = (a * lat) + ((1.0 - a) * float(self.ewma))
        ref = float(self.ewma or 0.0)
        if ref <= self.warn:
            return 0.0
        if ref >= self.critical:
            return 1.0
        denom = max(1e-9, (self.critical - self.warn))
        return (ref - self.warn) / denom

