# # ============================
# # ADAPTIVE STRESS MODEL (trend/vol/spread)
# # ============================
#
class AdaptiveStressModel:
    """Adaptive stress score in [0,1] from vol/trend/spread + base guards."""

    def __init__(self, window: int = 240, ewma_alpha: float = 0.25, min_samples: int = 20):
        from collections import defaultdict, deque
        self.window = int(max(30, window))
        self.ewma_alpha = float(ewma_alpha)
        self.min_samples = int(max(10, min_samples))
        self._vol_hist = defaultdict(lambda: deque(maxlen=self.window))
        self._trend_hist = defaultdict(lambda: deque(maxlen=self.window))
        self._spread_hist = defaultdict(lambda: deque(maxlen=self.window))
        self._ewma = {}

    @staticmethod
    def _sf(x) -> float:
        try:
            v = float(x)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0
        if not math.isfinite(v):
            return 0.0
        return max(0.0, v)

    def _score_percentile(self, arr, value: float, p_low: float = 50.0, p_high: float = 90.0, fallback_ref: float = 1.0) -> float:
        v = self._sf(value)
        if len(arr) < self.min_samples:
            ref = max(1e-12, float(fallback_ref))
            return max(0.0, min(1.0, v / ref))
        data = sorted(float(x) for x in arr)
        def _pct(p):
            p = max(0.0, min(100.0, float(p))) / 100.0
            idx = int(round((len(data) - 1) * p))
            return data[max(0, min(len(data)-1, idx))]
        lo = _pct(p_low)
        hi = _pct(p_high)
        if not math.isfinite(lo) or not math.isfinite(hi) or hi <= lo:
            ref = max(1e-12, float(data[-1] if data else 1.0))
            return max(0.0, min(1.0, v / ref))
        return max(0.0, min(1.0, (v - lo) / (hi - lo)))

    def update(self, symbol: str, vol, trend_strength, spread, base: float = 0.0) -> float:
        v = self._sf(vol)
        t = self._sf(trend_strength)
        s = self._sf(spread)
        b = self._sf(base)
        self._vol_hist[symbol].append(v)
        self._trend_hist[symbol].append(t)
        self._spread_hist[symbol].append(s)
        vol_score = self._score_percentile(self._vol_hist[symbol], v, fallback_ref=max(1e-12, v if v else 1.0))
        trend_score = self._score_percentile(self._trend_hist[symbol], t, fallback_ref=max(1e-12, t if t else 1.0))
        spread_score = self._score_percentile(self._spread_hist[symbol], s, fallback_ref=max(1e-12, s if s else 0.001))
        raw = 0.45 * vol_score + 0.35 * spread_score + 0.20 * trend_score
        raw = max(raw, b)
        raw = max(0.0, min(1.0, float(raw)))
        prev = self._ewma.get(symbol)
        if prev is None:
            out = raw
        else:
            a = max(0.01, min(0.99, self.ewma_alpha))
            out = (a * raw) + ((1.0 - a) * float(prev))
        if not math.isfinite(out):
            out = raw
        out = max(0.0, min(1.0, out))
        self._ewma[symbol] = out
        return out

