# # ============================
# # SIGNAL INTELLIGENCE (PATCH)
# # ============================
#
# # ============================
# # MARKET REGIME DETECTOR (Range/Trend + Vol)
# # ============================
#
class RegimeDetector:
    """Detect simple market regime (TREND/RANGE) + volatility estimate."""

    def __init__(self, window: int = 30, min_points: int = 10):
        from collections import defaultdict, deque
        self.window = int(max(10, window))
        self.min_points = int(max(5, min_points))
        self.prices = defaultdict(lambda: deque(maxlen=self.window))

    def update(self, symbol: str, price) -> dict:
        try:
            p = float(price)
        except Exception:
            p = 0.0
        if not math.isfinite(p) or p <= 0:
            return {'regime': 'UNKNOWN', 'trend_strength': 0.0, 'vol': 0.0}
        arr = self.prices[symbol]
        arr.append(p)
        if len(arr) < self.min_points:
            return {'regime': 'UNKNOWN', 'trend_strength': 0.0, 'vol': 0.0}
        rets = []
        prev = None
        for x in arr:
            if prev is not None and prev > 0 and x > 0:
                rets.append(math.log(x / prev))
            prev = x
        vol = math.sqrt(sum(r*r for r in rets) / max(1, len(rets))) if rets else 0.0
        mean = sum(arr) / len(arr)
        var = sum((x-mean)**2 for x in arr) / max(1, len(arr)-1)
        std = math.sqrt(var) if var > 0 else 0.0
        trend_strength = abs((arr[-1] - mean) / std) if std > 1e-12 else 0.0
        regime = 'TREND' if trend_strength >= 1.0 else 'RANGE'
        return {'regime': regime, 'trend_strength': float(trend_strength), 'vol': float(vol)}

