class IntelligentSignal:
    """Weighted signal container (supports negative strength for SELL)."""

    def __init__(self, value: bool, strength: float, confidence: float, ttl: int = 3, name: str = 'sig'):
        self.value = bool(value)
        self.name = str(name or 'sig')
        try:
            s = float(strength)
        except Exception:
            s = 0.0
        self.strength = max(-1.5, min(1.5, s))
        try:
            c = float(confidence)
        except Exception:
            c = 0.0
        self.confidence = max(0.0, min(1.0, c))
        self.ttl = int(ttl)

    def decay(self) -> bool:
        self.ttl -= 1
        self.strength *= 0.85
        return self.ttl > 0

    def score(self) -> float:
        if not self.value:
            return 0.0
        if self.name.lower() == 'ml' and self.confidence < 0.15:
            return 0.0
        return float(self.strength) * float(self.confidence)

