class DecisionEngine:
    """Signal fusion -> BUY/SELL/HOLD (replacement for broken legacy)."""

    BUY = "BUY"
    SELL = "SELL"
    HOLD = "HOLD"

    @staticmethod
    def _canon_sig_name(name: str) -> str:
        n = (name or '').strip().lower()
        if not n:
            return 'unknown'
        if 'flow' in n or 'orderflow' in n:
            return 'flow'
        if 'whale' in n:
            return 'whale'
        if n in ('ml', 'model') or 'ml' in n or 'model' in n:
            return 'ml'
        if 'strategy' in n:
            return 'strategy'
        return n

    @staticmethod
    def _adaptive_weight(sig_name: str, context) -> float:
        try:
            regime = getattr(context, 'regime', None) or getattr(context, 'market_regime', None) or ''
            regime = str(regime).upper()
        except Exception:
            regime = ''
        n = DecisionEngine._canon_sig_name(sig_name)
        w = 1.0
        if regime == 'TREND':
            if n in ('flow', 'whale', 'ml', 'strategy'):
                w *= 1.10
        elif regime == 'RANGE':
            if n in ('flow', 'whale'):
                w *= 0.95
            if n in ('strategy',):
                w *= 1.05
        return float(w)

    @staticmethod
    def _get_threshold(context) -> float:
        for attr in ('threshold', 'decision_threshold', 'dynamic_threshold'):
            try:
                v = getattr(context, attr, None)
                if v is None:
                    continue
                return max(0.01, float(v))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_continue")
                continue
        return 0.18

    @staticmethod
    def decide(signals, runtime_context, signal_performance=None) -> str:
        if not signals:
            return DecisionEngine.HOLD
        th = DecisionEngine._get_threshold(runtime_context)
        stress = 0.0
        for attr in ('stress_level', 'stress', 'stress_score'):
            try:
                stress = float(getattr(runtime_context, attr, 0.0) or 0.0)
                break
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_continue")
                continue
        stress = max(0.0, min(1.0, stress))
        th_eff = th * (1.0 + 0.8 * stress)
        score = 0.0
        for s in signals:
            try:
                name = DecisionEngine._canon_sig_name(getattr(s, 'name', None) or getattr(s, 'source', None) or 'unknown')
                if getattr(s, 'value', True) is False:
                    continue
                strength = float(getattr(s, 'strength', 0.0) or 0.0)
                conf = float(getattr(s, 'confidence', 0.0) or 0.0)
                conf = max(0.0, min(1.0, conf))
                base = strength * conf
                w = DecisionEngine._adaptive_weight(name, runtime_context)
                if signal_performance is not None:
                    try:
                        if hasattr(signal_performance, 'get_weight'):
                            w *= float(signal_performance.get_weight(name))
                        elif hasattr(signal_performance, 'weight_for'):
                            w *= float(signal_performance.weight_for(name))
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                score += base * w
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_continue")
                continue
        if score >= th_eff:
            return DecisionEngine.BUY
        if score <= -th_eff:
            return DecisionEngine.SELL
        return DecisionEngine.HOLD

