# # ============================================================
# # Decision Certificates (HMAC) for LIVE order authorization
# #   - Prevents accidental internal bypass of the single Order Gate
# #   - LIVE BUY orders require a valid decision certificate
# #   - Deterministic-only: certificate issuance requires deterministic=True in order_ctx
# # ============================================================
#
def _b64url_encode(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

def _b64url_decode(s: str) -> bytes:
    pad = "=" * ((4 - (len(s) % 4)) % 4)
    return base64.urlsafe_b64decode((s + pad).encode("ascii"))

def _canonical_json(obj: Dict[str, Any]) -> bytes:
    # Stable encoding for signatures
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")

class DecisionAuthority:
    """Issue/verify short-lived HMAC decision certificates for LIVE BUY orders."""

    _counter: int = 0

    def __init__(self, secret: bytes, ttl_sec: int = 60, skew_sec: int = 0) -> None:
        if not secret:
            raise ValueError('empty secret')
        self._secret = secret if isinstance(secret, (bytes, bytearray)) else str(secret).encode('utf-8')
        try:
            ttl = int(ttl_sec)
        except Exception:
            ttl = 60
        self._ttl = ttl if ttl > 0 else 60
        if self._ttl < 5:
            self._ttl = 5
        try:
            self._skew = int(skew_sec or 0)
        except Exception:
            self._skew = 0
        if self._skew < 0:
            self._skew = 0

    @classmethod
    def from_env(cls) -> Optional['DecisionAuthority']:
        """Build a DecisionAuthority from environment variables.

        Accepts:
          - DECISION_CERT_SECRET (preferred) or DECISION_SECRET
          - DECISION_CERT_TTL_SEC or DECISION_TTL_SEC (default 60, min 5)
          - DECISION_CERT_CLOCK_SKEW_SEC / DECISION_CERT_SKEW_SEC / DECISION_SKEW_SEC (default 0)
        """
        secret = (os.environ.get('DECISION_CERT_SECRET') or os.environ.get('DECISION_SECRET') or '').strip()
        if not secret:
            return None
        ttl_raw = (os.environ.get('DECISION_CERT_TTL_SEC') or os.environ.get('DECISION_TTL_SEC') or '60').strip()
        try:
            ttl = int(ttl_raw)
        except Exception:
            ttl = 60
        skew_raw = (os.environ.get('DECISION_CERT_CLOCK_SKEW_SEC') or os.environ.get('DECISION_CERT_SKEW_SEC') or os.environ.get('DECISION_SKEW_SEC') or '0').strip()
        try:
            skew = int(skew_raw)
        except Exception:
            skew = 0
        return cls(secret=secret.encode('utf-8'), ttl_sec=ttl, skew_sec=skew)

    @staticmethod
    def _canonical_json(obj) -> bytes:
        import json
        return json.dumps(obj, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

    @classmethod
    def _next_ctr(cls) -> int:
        cls._counter += 1
        return cls._counter

    def issue(self, payload):
        import base64, time, hmac, hashlib, json
        pl = dict(payload or {})
        pl['v'] = 1
        pl['ts'] = int(_pp920_time.time())
        pl['ctr'] = self._next_ctr()
        msg = self._canonical_json(pl)
        sig = hmac.new(self._secret, msg, hashlib.sha256).digest()
        token = base64.urlsafe_b64encode(msg).decode('ascii').rstrip('=') + '.' + base64.urlsafe_b64encode(sig).decode('ascii').rstrip('=')
        return token

    def verify(self, token: str):
        import base64, time, hmac, hashlib, json
        if not token or '.' not in str(token):
            raise ValueError('bad token')
        a, b = str(token).split('.', 1)
        def _b64d(s):
            s = str(s)
            pad = '=' * ((4 - (len(s) % 4)) % 4)
            return base64.urlsafe_b64decode(s + pad)
        msg = _b64d(a)
        sig = _b64d(b)
        exp = hmac.new(self._secret, msg, hashlib.sha256).digest()
        if not hmac.compare_digest(exp, sig):
            raise ValueError('bad signature')
        pl = json.loads(msg.decode('utf-8'))
        ts = int(pl.get('ts') or 0)
        if ts <= 0:
            raise ValueError('missing ts')
        now = int(_pp920_time.time())
        skew = int(getattr(self, '_skew', 0) or 0)
        # allow limited clock skew (Termux/mobile time drift)
        if (now - ts) > (self._ttl + skew):
            raise ValueError('expired')
        if (ts - now) > skew:
            raise ValueError('from_future')
        return pl

