def get_decision_authority() -> Optional[DecisionAuthority]:
    global _DECISION_AUTHORITY
    if _DECISION_AUTHORITY is None:
        _DECISION_AUTHORITY = DecisionAuthority.from_env()
    return _DECISION_AUTHORITY

