class DecisionRecord:
    def __init__(self, symbol, decision, price, score, signals, timestamp):
        self.symbol = symbol
        self.decision = decision
        self.price = price
        self.score = score
        self.signals = signals or []
        self.timestamp = timestamp
        self.evaluated = False
        self.result = 0.0

