import argparse as _argparse
from collections import deque as _deque

class _HTTPClient:
    """Minimal urllib HTTP client with explicit errors (no silent swallowing)."""
    def __init__(self, timeout: float = 30.0, user_agent: str = "PP5-UltraAI/1.0",
                     verify_ssl: Optional[bool] = None, ca_bundle: str = ""):
            """
            Termux/mobile SSL notes:
              - SSL verification is **mandatory** (no bypass flags).
              - If your Termux CA bundle is non-standard, set ARZPLUS_CA_BUNDLE=/path/to/cert.pem
            """
            import os as _os
            self.timeout = float(timeout)
            self.user_agent = str(user_agent)
            # Security hard rule: always verify SSL. 'verify_ssl' parameter is ignored by design.
            self.verify_ssl = True
            self.ca_bundle = str(ca_bundle or _os.getenv("ARZPLUS_CA_BUNDLE", "")).strip()
            self._ssl_context = None

    def _get_ssl_context(self, url: str):
        """Return a cached, verified SSL context for HTTPS only.
        SSL verification is mandatory.
        """
        import ssl
        try:
            if not (str(url).lower().startswith('https://')):
                return None
            if self._ssl_context is not None:
                return self._ssl_context
            if self.ca_bundle:
                ctx = ssl.create_default_context(cafile=self.ca_bundle)
            else:
                ctx = ssl.create_default_context()
            # Hardening (best-effort): require TLSv1.2+
            try:
                ctx.minimum_version = ssl.TLSVersion.TLSv1_2
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            self._ssl_context = ctx
            return self._ssl_context
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return None

    def request(self, method: str, url: str,
                headers: Optional[Dict[str, str]] = None,
                params: Optional[Dict[str, Any]] = None,
                json_body: Any = None,
                form_body: Optional[Dict[str, Any]] = None) -> Tuple[int, Dict[str, str], str]:
        import urllib.request, urllib.parse, urllib.error
        import ssl, socket, time as _time

        method = (method or "GET").upper()
        headers = dict(headers or {})
        headers.setdefault("User-Agent", self.user_agent)
        headers.setdefault("Accept", "application/json")

        if params:
            q = urllib.parse.urlencode(params, doseq=True)
            url = url + ("&" if "?" in url else "?") + q

        data = None
        # Prefer JSON; fallback to form when requested explicitly.
        if json_body is not None:
            data = json.dumps(json_body, ensure_ascii=False).encode("utf-8")
            headers.setdefault("Content-Type", "application/json")
        elif form_body is not None:
            try:
                form_payload = {str(k): ("" if v is None else str(v)) for k, v in dict(form_body).items()}
            except Exception:
                form_payload = form_body
            data = urllib.parse.urlencode(form_payload, doseq=True).encode("utf-8")
            headers.setdefault("Content-Type", "application/x-www-form-urlencoded")

        req = urllib.request.Request(url=url, data=data, headers=headers, method=method)

        # Retry policy (network/SSL hiccups are common on mobile/Termux).
        # IMPORTANT: Never automatically retry authenticated/private requests to avoid duplicate orders.
        allow_retry = (
            method == "GET"
            and ("Authorization" not in headers)
            and (json_body is None)
            and (form_body is None)
        )
        try:
            max_tries = int(os.getenv("ARZPLUS_HTTP_RETRY", "3") or 3)
        except Exception:
            max_tries = 3
        try:
            backoff = float(os.getenv("ARZPLUS_HTTP_BACKOFF", "0.6") or 0.6)
        except Exception:
            backoff = 0.6
        max_tries = max(1, min(max_tries, 6))
        backoff = max(0.15, min(backoff, 3.0))

        last_err: Optional[BaseException] = None

        for attempt in range(max_tries):
            try:
                with urllib.request.urlopen(req, timeout=self.timeout, context=self._get_ssl_context(url)) as resp:
                    status = int(getattr(resp, "status", 200))
                    txt = resp.read().decode("utf-8", errors="replace")
                    hdrs = {k: v for k, v in resp.headers.items()}
                    return status, hdrs, txt

            except urllib.error.HTTPError as e:
                # HTTP errors are real responses; only retry on transient server/rate-limit codes.
                try:
                    etxt = e.read().decode("utf-8", errors="replace")
                except Exception:
                    etxt = str(e)
                status = int(getattr(e, "code", 0) or 0)
                hdrs = dict(getattr(e, "headers", {}) or {})
                if allow_retry and status in (429, 500, 502, 503, 504) and attempt < (max_tries - 1):
                    _time.sleep(backoff)
                    backoff = min(backoff * 2.0, 6.0)
                    continue
                return status, hdrs, etxt

            except Exception as e:
                last_err = e
                msg = (str(e) or "").lower()

                transient = isinstance(
                    e,
                    (
                        urllib.error.URLError,
                        TimeoutError,
                        socket.timeout,
                        ssl.SSLError,
                        ConnectionError,
                        OSError,
                    ),
                )
                if any(k in msg for k in (
                    "timed out", "timeout", "handshake", "temporary failure", "name or service",
                    "connection reset", "connection aborted", "broken pipe", "tls", "ssl"
                )):
                    transient = True

                if allow_retry and transient and attempt < (max_tries - 1):
                    _time.sleep(backoff)
                    backoff = min(backoff * 2.0, 6.0)
                    continue
                return 0, {}, str(e)

        return 0, {}, (str(last_err) if last_err is not None else "")


class ArzPlusAPI:
    """
    ArzPlus REST client (v719 hardened).
    - Uses requests.Session() for Keep-Alive (low latency on volatility).
    - Discovery-first: /market/symbols/ is the source of truth for enabled markets and precision rules.
    - Enforces tick_size/step_size/min/max quantities on order creation to prevent rejects.
    """

    BASE_URL = "https://api.arzplus.net/api/v1"

    def __init__(self, token: str = "", timeout: float = 30.0, rate_limit_per_min: int = 100, verify_ssl: bool = True):
        self.token = str(token or "").strip()
        self.api_token = self.token  # official ArzPlus header expects: Authorization: Token <api_token>
        self.timeout = float(timeout or 30.0)
        self.rate_limit_per_min = int(rate_limit_per_min or 100)
        self.verify_ssl = bool(verify_ssl)

        # Local rate-limit window tracking (per instance)
        self._rl_window_ts = 0.0
        self._rl_count = 0

        # Market specs cache keyed by market name (e.g., BTCIRT, GOLDIRT)
        self._market_specs = {}

        # Session (Keep-Alive)
        self._session = None
        self._build_session()

    # ----------------- Session / Rate limit -----------------
    def _build_session(self) -> None:
        try:
            import requests
            from requests.adapters import HTTPAdapter
        except Exception as e:
            # requests is expected to exist on Termux for v719
            raise RuntimeError("requests is required for ArzPlusAPI v719") from e

        s = requests.Session()
        # Base headers
        s.headers.update({
            "Accept": "application/json",
            "User-Agent": "parisa718/v719 (requests-session)",
        })
        # Keep-alive pools
        try:
            adapter = HTTPAdapter(pool_connections=10, pool_maxsize=10, max_retries=0)
            s.mount("https://", adapter)
            s.mount("http://", adapter)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        self._session = s

    def reset_session(self) -> None:
        """Hard reset the underlying requests.Session (Advanced Heal)."""
        try:
            if self._session is not None:
                self._session.close()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        self._session = None
        self._build_session()
        try:
            self._rl_window_ts = 0.0
            self._rl_count = 0
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    def _rate_limit(self) -> None:
        import time
        now = float(_pp920_time.time())
        try:
            if (not self._rl_window_ts) or (now - float(self._rl_window_ts)) >= 60.0:
                self._rl_window_ts = now
                self._rl_count = 0
            self._rl_count = int(self._rl_count) + 1
        except Exception:
            self._rl_window_ts = now
            self._rl_count = 1

        # Hard ceiling (exchange: 100 req/min). Sleep remainder of the window if exceeded.
        try:
            lim = int(self.rate_limit_per_min) if self.rate_limit_per_min is not None else 0
        except Exception:
            lim = 0

        if lim and self._rl_count > lim:
            import time as _t
            try:
                remain = max(0.0, 60.0 - (now - float(self._rl_window_ts)))
            except Exception:
                remain = 1.0
            # Minimal jitter to avoid sync-thundering
            _t.sleep(float(remain) + 0.05)
            self._rl_window_ts = float(_t.time())
            self._rl_count = 1

    def _headers(self, auth: bool) -> dict:
        h = {}
        if auth and self.api_token:
            # REQUIRED EXACT FORMAT (docs): Authorization: Token <TOKEN>
            h["Authorization"] = f"Token {self.api_token}"
        return h

    # ----------------- Market specs cache -----------------
    def _extract_rows(self, payload) -> list:
        """Best-effort extractor: list endpoint may return list or dict envelopes."""
        if payload is None:
            return []
        if isinstance(payload, list):
            return [x for x in payload if isinstance(x, dict)]
        if isinstance(payload, dict):
            # common envelopes
            for k in ("results", "data", "symbols", "markets", "tickers", "items"):
                v = payload.get(k)
                if isinstance(v, list):
                    return [x for x in v if isinstance(x, dict)]
            # sometimes directly one market dict
            if "name" in payload:
                return [payload]
        return []

    def _ingest_market_specs(self, payload) -> None:
        try:
            rows = self._extract_rows(payload)
            for it in rows:
                try:
                    nm = str(it.get("name") or "").strip().upper()
                    if not nm:
                        continue
                    # Store under multiple aliases (prevents price/order symbol mismatch)
                    for kk in _pp8053_symbol_aliases(nm):
                        try:
                            self._market_specs[str(kk).strip().upper()] = it
                        except Exception:
                            continue
                except Exception:
                    continue
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)


    def get_market_spec(self, symbol: str) -> dict:
        sym0 = str(symbol or "").strip().upper()
        # Try canonical + aliases first
        try:
            for a in _pp8053_symbol_aliases(sym0):
                spec = self._market_specs.get(str(a).strip().upper())
                if isinstance(spec, dict):
                    return spec
        except Exception:
            pass
        # refresh once
        try:
            r = self.symbols()
            if isinstance(r, dict) and bool(r.get("ok")):
                self._ingest_market_specs(r.get("data"))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)
        # try again after refresh
        try:
            for a in _pp8053_symbol_aliases(sym0):
                spec = self._market_specs.get(str(a).strip().upper())
                if isinstance(spec, dict):
                    return spec
        except Exception:
            pass
        return {}


    def _call(self, method: str, path: str, auth: bool = False, params: dict = None, json_body=None, data=None, allow_retry: bool = True) -> dict:
        import time
        method = str(method or "GET").upper().strip()
        p = str(path or "/").strip()
        if not p.startswith("/"):
            p = "/" + p
        url = self.BASE_URL + p

        self._rate_limit()

        try:
            import requests
            sess = self._session
            if sess is None:
                self._build_session()
                sess = self._session

            # v729 Order Execution Safety: ArzPlus requires 'price' and 'amount' as STRINGs.
            # Some legacy paths may call _call('POST','/market/orders/', json_body=...) with numeric types.
            # This sanitizer makes such orders compliant (and normalizes IRT prices to integer strings) before sending.
            try:
                if method == 'POST' and p.rstrip('/').endswith('/market/orders'):
                    if isinstance(json_body, dict):
                        _sym = str(json_body.get('symbol') or '').strip().upper()
                        if _sym:
                            json_body['symbol'] = _sym
                        # price
                        if 'price' in json_body:
                            _pr = json_body.get('price')
                            if _pr is not None:
                                try:
                                    if _sym.endswith('IRT'):
                                        try:
                                            from decimal import Decimal, ROUND_HALF_UP
                                            json_body['price'] = str(int(Decimal(str(_pr).strip()).to_integral_value(rounding=ROUND_HALF_UP)))
                                        except Exception:
                                            json_body['price'] = str(int(float(str(_pr).strip())))
                                    else:
                                        json_body['price'] = str(_pr)
                                except Exception:
                                    json_body['price'] = str(_pr)
                        # amount
                        if 'amount' in json_body:
                            _am = json_body.get('amount')
                            if _am is not None:
                                # best effort: quantize to market step_size if available
                                try:
                                    sp = self.get_market_spec(_sym) if hasattr(self, 'get_market_spec') else {}
                                    step_dec = int((sp or {}).get('step_size', 0) or 0)
                                    step_dec = max(0, min(step_dec, 12))
                                except Exception:
                                    step_dec = 0
                                try:
                                    from decimal import Decimal as _D, ROUND_DOWN as _RD
                                    _v = _D(str(_am).strip())
                                    if step_dec <= 0:
                                        _v = _v.to_integral_value(rounding=_RD)
                                    else:
                                        _v = _v.quantize(_D('1e-' + str(step_dec)), rounding=_RD)
                                    json_body['amount'] = format(_v, 'f')
                                except Exception:
                                    json_body['amount'] = str(_am)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

            resp = sess.request(
                method,
                url,
                params=params,
                json=json_body,
                data=data,
                headers=self._headers(auth),
                timeout=float(self.timeout),
                verify=bool(self.verify_ssl),
            )
            st = int(getattr(resp, "status_code", 0) or 0)
            text = ""
            try:
                text = resp.text or ""
            except Exception:
                text = ""

            payload = None
            try:
                if text:
                    payload = resp.json()
            except Exception:
                payload = None

            # Null/empty JSON is treated as heal-trigger (Advanced Heal)
            if payload is None:
                if allow_retry:
                    try:
                        _pp200_heal(RuntimeError("NULL_RESPONSE"), tag="pp719_null_response")
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                    try:
                        self.reset_session()
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                    time.sleep(0.25)
                    return self._call(method, p, auth=auth, params=params, json_body=json_body, data=data, allow_retry=False)
                return {"ok": False, "status": st, "data": {}, "error": "NULL_RESPONSE", "text": text[:400]}

            # Update market specs cache when discovering markets
            try:
                if method == "GET" and p.rstrip("/") == "/market/symbols":
                    self._ingest_market_specs(payload)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            ok = 200 <= st < 300
            out = {"ok": bool(ok), "status": st, "data": payload}
            if not ok:
                # Common error fields
                try:
                    err = None
                    if isinstance(payload, dict):
                        err = payload.get("detail") or payload.get("error") or payload.get("message")
                    out["error"] = str(err or text or "HTTP_ERROR")[:300]
                except Exception:
                    out["error"] = "HTTP_ERROR"
                out["text"] = text[:400]
            return out

        except requests.RequestException as e:
            try:
                _pp200_heal(e, tag="pp719_network")
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            if allow_retry:
                try:
                    self.reset_session()
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                time.sleep(0.35)
                return self._call(method, p, auth=auth, params=params, json_body=json_body, data=data, allow_retry=False)
            return {"ok": False, "status": 0, "data": {}, "error": "NETWORK_ERROR", "text": str(e)[:400]}
        except Exception as e:
            try:
                _pp200_heal(e, tag="pp719_exception")
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            if allow_retry:
                try:
                    self.reset_session()
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                time.sleep(0.35)
                return self._call(method, p, auth=auth, params=params, json_body=json_body, data=data, allow_retry=False)
            return {"ok": False, "status": 0, "data": {}, "error": "EXCEPTION", "text": str(e)[:400]}

    # ----------------- Public endpoints -----------------
    def symbols(self) -> dict:
        # GET /market/symbols/ (public)
        return self._call("GET", "/market/symbols/", auth=False)

    def get_all_tickers(self) -> dict:
        # Backward-compatible alias
        return self.symbols()

    def symbol(self, symbol: str) -> dict:
        sym0 = str(symbol or "").strip().upper()
        spec = self.get_market_spec(sym0)
        sym = str((spec.get("name") if isinstance(spec, dict) else "") or _pp8053_canon_symbol(sym0) or sym0).strip().upper()
        # Some deployments require trailing slash; try both.
        r = self._call("GET", f"/market/symbols/{sym}/", auth=False)
        st = str(r.get("status") or "")
        if (not bool(r.get("ok"))) and st in ("301", "302", "307", "308", "404"):
            r2 = self._call("GET", f"/market/symbols/{sym}", auth=False)
            if bool(r2.get("ok")):
                return r2
        return r

    def depth(self, symbol: str) -> dict:
        sym0 = str(symbol or "").strip().upper()
        spec = self.get_market_spec(sym0)
        sym = str((spec.get("name") if isinstance(spec, dict) else "") or _pp8053_canon_symbol(sym0) or sym0).strip().upper()
        return self._call("GET", f"/market/depth/{sym}", auth=False)

    def trades(self, symbol: str, limit: int = 100, offset: int = 0) -> dict:
        sym0 = str(symbol or "").strip().upper()
        spec = self.get_market_spec(sym0)
        sym = str((spec.get("name") if isinstance(spec, dict) else "") or _pp8053_canon_symbol(sym0) or sym0).strip().upper()
        limit = int(limit) if limit is not None else 100
        offset = int(offset) if offset is not None else 0
        return self._call("GET", "/market/trades/", auth=False, params={"symbol": sym, "limit": limit, "offset": offset})

    # ----------------- Private endpoints -----------------
    def wallet_balance(self) -> dict:
        return self._call("GET", "/wallet/balance/", auth=True)

    def balance(self) -> dict:
        """
        Convenience mapping: returns {"ok":bool,"status":int,"data":{asset: free_float, ...}}.

        Rootfix:
        - Accepts ArzPlus payload variations: {"wallet":[...]}, {"results":[...]}, {"data":...}, mapping-style payloads.
        - Parses numeric strings robustly (commas/spaces).
        - Never misinterprets nested dict payload as a normalized mapping.
        """
        r = self.wallet_balance()
        payload = r.get("data")
        # PP20260102: cache raw payload for UI total-balance rendering (do NOT affect trading sizing)
        # IMPORTANT: only mark as "fresh/live" when the HTTP call actually succeeded (ok==True).
        # This prevents decorative-changing numbers when the internet is down.
        try:
            import time as _t
            if bool(r.get('ok')) and payload is not None:
                self._pp_last_wallet_balance_payload = payload
                self._pp_last_wallet_balance_ts = float(_t.time())
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        out_map = {}

        def _to_float(v) -> float:
            try:
                if v is None:
                    return 0.0
                if isinstance(v, (int, float)):
                    return float(v)
                if isinstance(v, str):
                    s = v.strip().replace(",", "")
                    if not s:
                        return 0.0
                    return float(s)
                return float(v)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return 0.0

        def _ingest_item(it) -> None:
            try:
                if not isinstance(it, dict):
                    return
                a = it.get("asset")
                if a is None:
                    a = it.get("coin")
                if a is None:
                    a = it.get("currency")
                if a is None:
                    a = it.get("symbol")
                if a is None:
                    a = it.get("code")
                a = str(a or "").strip().upper()
                if not a:
                    return
                f = it.get("free")
                if f is None:
                    f = it.get("available")
                if f is None:
                    f = it.get("balance")
                if f is None:
                    f = it.get("amount")
                out_map[a] = _to_float(f)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return

        def _maybe_parse_mapping(mp: dict) -> None:
            # mapping asset->free (ignore non-asset keys)
            try:
                for k, v in (mp or {}).items():
                    ak = str(k or "").strip().upper()
                    if not ak:
                        continue
                    if ak in ("WALLET", "WALLETS", "RESULTS", "DATA", "BALANCES", "OK", "STATUS", "ERROR", "DETAIL", "MESSAGE"):
                        continue
                    if isinstance(v, (list, dict)):
                        continue
                    out_map[ak] = _to_float(v)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return

        rows = payload

        # unwrap common containers
        if isinstance(rows, dict):
            for key in ("wallet", "wallets", "results", "balances", "data"):
                if key in rows:
                    rows = rows.get(key)
                    break

        if isinstance(rows, list):
            for it in rows:
                _ingest_item(it)
        elif isinstance(rows, dict):
            # payload could be a single balance row or a mapping
            if any(k in rows for k in ("asset", "coin", "currency", "symbol")):
                _ingest_item(rows)
            else:
                _maybe_parse_mapping(rows)

        r2 = dict(r)
        r2["data"] = out_map
        if isinstance(payload, (dict, list)) and not out_map:
            # keep raw for diagnostics (no token exposure)
            r2["raw"] = payload
        return r2

    def _dec_quant(self, x, decimals: int, rounding):
        from decimal import Decimal, ROUND_DOWN
        d = int(max(0, int(decimals)))
        try:
            dx = x if isinstance(x, Decimal) else Decimal(str(x))
        except Exception:
            dx = Decimal("0")
        if d == 0:
            return dx.quantize(Decimal("1"), rounding=rounding)
        q = Decimal("1").scaleb(-d)  # 10^-d
        return dx.quantize(q, rounding=rounding)

    def _dec_to_str(self, d) -> str:
        try:
            # no scientific notation
            return format(d, "f")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return str(d)

    def create_order(self, symbol: str, amount: float, price: float, side: str, fill_type: str = "limit", market: str = "spot") -> dict:
        """
        POST /market/orders/ (private)
        Enforces tick_size/step_size/min/max quantity using market specs.
        """
        sym0 = str(symbol or "").strip().upper()
        spec = self.get_market_spec(sym0)
        sym = str((spec.get("name") if isinstance(spec, dict) else "") or _pp8053_canon_symbol(sym0) or sym0).strip().upper()
        side_v = str(side or "").strip().lower()
        if side_v not in ("buy", "sell"):
            return {"ok": False, "status": 0, "data": {}, "error": "BAD_SIDE"}

        # Market spec (precision rules)
        spec = self.get_market_spec(sym)
        try:
            tick = int(spec.get("tick_size", 0) if spec is not None else 0)
        except Exception:
            tick = 0
        try:
            step = int(spec.get("step_size", 8) if spec is not None else 8)
        except Exception:
            step = 8

        # v730 RED-LINE amount precision overrides (do NOT rely on exchange metadata for these):
        # - PAXGIRT amount: 7 decimals
        # - USDTIRT amount: 2 decimals
        try:
            if sym in ("PAXGIRT", "GOLDIRT"):
                step = 7
            elif sym == "USDTIRT":
                step = 2
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        try:
            mn = spec.get("min_trade_quantity") if isinstance(spec, dict) else None
            mx = spec.get("max_trade_quantity") if isinstance(spec, dict) else None
        except Exception:
            mn = None
            mx = None

        from decimal import Decimal, ROUND_DOWN, ROUND_UP

        # Quantity: floor to step_size
        qty = self._dec_quant(Decimal(str(amount)), step, ROUND_DOWN)
        # Enforce min/max quantity if present
        try:
            if mn is not None and Decimal(str(mn)) > 0 and qty < Decimal(str(mn)):
                return {"ok": False, "status": 0, "data": {}, "error": "MIN_TRADE_QUANTITY"}
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        try:
            if mx is not None and Decimal(str(mx)) > 0 and qty > Decimal(str(mx)):
                qty = self._dec_quant(Decimal(str(mx)), step, ROUND_DOWN)
        except Exception:
            pass        # Price: tick_size rounding; for buy -> ROUND_UP, for sell -> ROUND_DOWN
        pr = Decimal(str(price))
        pr_round = ROUND_UP if side_v == "buy" else ROUND_DOWN
        pr = self._dec_quant(pr, tick, pr_round)

        # PP723 Integer Precision: IRT markets must send integer price (no decimals) -> then STRING
        try:
            _base = str((spec or {}).get("base_asset", "") or "").upper().strip()
        except Exception:
            _base = ""
        _is_irt_mkt = (_base == "IRT") or bool(sym.endswith("IRT"))
        if _is_irt_mkt:
            try:
                pr = pr.to_integral_value(rounding=(ROUND_UP if side_v == "buy" else ROUND_DOWN))
            except Exception:
                try:
                    pr = Decimal(str(int(float(pr))))
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
        # v729: USDT/PAXG precision comes ONLY from /market/symbols spec (step_size). No hardcoded overrides.

        # Strings (String Rule): NEVER send numeric types for price/amount in JSON
        qty_s = str(self._dec_to_str(qty))
        pr_s = str(int(pr)) if _is_irt_mkt else str(self._dec_to_str(pr))
        payload = {
            "symbol": sym,
            "amount": qty_s,
            "price": pr_s,
            "side": side_v,
            "fill_type": str(fill_type or "limit").strip().lower(),
            "market": str(market or "spot").strip().lower(),
        }
        return self._call("POST", "/market/orders/", auth=True, json_body=payload)

    def place_normal_order(self, symbol: str, amount: float, price: float, *, side: str = 'buy', fill_type: str = 'limit', market: str = 'spot') -> dict:
        """v729: Preferred order entry.
        Routes through create_order which applies ArzPlus precision (tick_size/step_size) and String Rule.
        """
        return self.create_order(symbol, amount, price, side=side, fill_type=fill_type, market=market)

    def list_orders(self, symbol: str = None, status: str = None, limit: int = 50, offset: int = 0) -> dict:
        params = {}
        if symbol:
            params["symbol"] = str(symbol).strip().upper()
        if status:
            params["status"] = str(status).strip()
        try:
            params["limit"] = int(limit) if limit is not None else 50
            params["offset"] = int(offset) if offset is not None else 0
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return self._call("GET", "/market/orders/", auth=True, params=params)

    def get_order(self, order_id: int) -> dict:
        oid = int(order_id) if order_id is not None else 0
        return self._call("GET", f"/market/orders/{oid}", auth=True)

    def cancel_order(self, order_id: int) -> dict:
        oid = int(order_id) if order_id is not None else 0
        return self._call("POST", "/market/orders/cancel/", auth=True, json_body={"id": oid})


