def _book_top(depth: Dict[str, Any]) -> Tuple[float, float, float]:
    bids = (depth or {}).get("bids") or []
    asks = (depth or {}).get("asks") or []
    bid = 0.0
    ask = 0.0
    try:
        if bids:
            b0 = bids[0]
            if isinstance(b0, dict):
                bid = float(b0.get("price") or 0.0)
            elif isinstance(b0, (list, tuple)) and len(b0) > 0:
                bid = float(b0[0] or 0.0)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="book_top_bid")
        bid = 0.0
    try:
        if asks:
            a0 = asks[0]
            if isinstance(a0, dict):
                ask = float(a0.get("price") or 0.0)
            elif isinstance(a0, (list, tuple)) and len(a0) > 0:
                ask = float(a0[0] or 0.0)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="book_top_ask")
        ask = 0.0
    mid = (bid + ask) / 2.0 if bid > 0 and ask > 0 else (bid or ask or 0.0)
    return bid, ask, mid

def _spread_bps(bid: float, ask: float) -> float:
    """Best-effort spread in basis points (always non-negative).

    Notes:
      - Handles both normal and occasionally inverted books.
      - Caps extreme values to avoid poisoning downstream EMAs on bad ticks.
    """
    try:
        bid = float(bid or 0.0)
        ask = float(ask or 0.0)
    except Exception:
        return 0.0

    if bid <= 0.0 or ask <= 0.0:
        return 0.0

    mid = (bid + ask) / 2.0
    if mid <= 0.0:
        return 0.0

    spr_bps = abs((ask - bid) / max(1e-12, mid) * 10000.0)

    # Hard cap to prevent rare bad-book spikes from freezing trading logic.
    if spr_bps > 5000.0:
        spr_bps = 5000.0
    return float(spr_bps)

def _book_side_amount(levels: Any, n: int) -> float:
    """Sum of 'amount' field for first n levels (best-effort)."""
    try:
        n = int(n)
    except Exception:
        n = 5
    if n <= 0:
        return 0.0
    total = 0.0
    try:
        for row in (levels or [])[:n]:
            if not row:
                continue
            try:
                total += float(row.get("amount") or 0.0)
            except Exception:
                try:
                    # tolerate tuple/list like [price, amount]
                    total += float(row[1] if isinstance(row, (list, tuple)) and len(row) > 1 else 0.0)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0
    return float(total)

def _book_bid_amount(depth: Dict[str, Any], n: int) -> float:
    return _book_side_amount((depth or {}).get("bids") or [], n)

def _pp110_update_bid_volume(symst: Any, depth_data: Dict[str, Any], ts: float) -> float:
    """Update rolling bid-volume samples for confirmation filters."""
    try:
        levels = int(os.getenv("VOLUME_CONFIRM_LEVELS", os.getenv("EDGE_BOOK_LEVELS", "15") or "15") or 15)
    except Exception:
        levels = 15
    vol = float(_book_bid_amount(depth_data, levels))
    try:
        symst.last_bid_vol = vol
        symst.bid_vol_samples.append((float(ts), float(vol)))
        win = float(os.getenv("VOLUME_CONFIRM_WINDOW_SEC", "600") or 600.0)
        # prune
        while symst.bid_vol_samples and (float(ts) - float(symst.bid_vol_samples[0][0])) > win:
            symst.bid_vol_samples.popleft()
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return vol

def _pp110_bid_vol_avg(symst: Any) -> float:
    try:
        xs = [float(v) for (_t, v) in (symst.bid_vol_samples or [])]
        return float(sum(xs) / max(1, len(xs)))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

def _pp110_update_signal_streak(symst: Any, score: float, buy_thr: float, sell_thr: float) -> Tuple[str, int]:
    sig = "HOLD"
    try:
        if float(score) >= float(buy_thr):
            sig = "BUY"
        elif float(score) <= -float(sell_thr):
            sig = "SELL"
    except Exception:
        sig = "HOLD"
    try:
        if sig == getattr(symst, "last_signal", "HOLD"):
            symst.signal_streak = int(getattr(symst, "signal_streak", 0) or 0) + 1
        else:
            symst.last_signal = sig
            symst.signal_streak = 1
        return sig, int(symst.signal_streak or 0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return sig, 1

def _pp110_volume_confirm_ok(symst: Any, prev_mid: float, mid: float) -> bool:
    """BUY confirmation: require bid-volume >= avg*(1+pct). Divergence can also satisfy."""
    enabled = str(os.getenv("VOLUME_CONFIRM_ENABLED", "1") or "1").strip().lower() in ("1", "true", "yes", "on")
    if not enabled:
        return True
    try:
        pct = float(os.getenv("VOLUME_CONFIRM_PCT", "0.20") or 0.20)
    except Exception:
        pct = 0.20
    avg = _pp110_bid_vol_avg(symst)
    cur = float(getattr(symst, "last_bid_vol", 0.0) or 0.0)
    if avg <= 0.0:
        return True  # no history yet; don't block early boot
    ratio = cur / max(1e-9, avg)
    if ratio >= (1.0 + pct):
        return True
    # Optional divergence: price down but bids up strongly
    div_en = str(os.getenv("DIVERGENCE_ENABLED", "1") or "1").strip().lower() in ("1", "true", "yes", "on")
    if not div_en:
        return False
    try:
        drop_bps = float(os.getenv("DIVERGENCE_PRICE_DROP_BPS", "8") or 8.0)  # 0.08%
        div_ratio = float(os.getenv("DIVERGENCE_BID_VOL_RATIO", "1.35") or 1.35)
    except Exception:
        drop_bps, div_ratio = 8.0, 1.35
    if prev_mid and mid and float(mid) < float(prev_mid) * (1.0 - drop_bps / 10000.0) and ratio >= div_ratio:
        return True
    return False
def _clamp(x: float, lo: float, hi: float) -> float:
    return lo if x < lo else hi if x > hi else x

# ============================================================
# SAFE OVERLAYS (Consciousness + Quantum)
# - Default OFF: ENABLE_CONSCIOUSNESS=0, ENABLE_QUANTUM=0
# - Even when ON, Quantum adjustment is bounded by QUANTUM_MAX_ADJUST
# ============================================================

class MarketConsciousness:
    """Lightweight market-regime monitor (standard library only).

    ورودی‌ها:
      - bid/ask/mid و depth (اختیاری)
      - raw_score (خروجی مدل محلی برای هر نماد)
      - symbol_state (برای برگشت‌ها/ولتیلیتی)

    خروجی:
      - ConsciousnessSnapshot (رژیم بازار + سطح ریسک 0..1)
    """
    def __init__(
        self,
        alpha: float = 0.12,
        vol_alpha: float = 0.08,
        spread_alpha: float = 0.12,
        window: int = 120,
        enabled: Optional[bool] = None,
    ):
        self.alpha = float(alpha)
        self.vol_alpha = float(vol_alpha)
        self.spread_alpha = float(spread_alpha)
        self.window = int(max(30, window))
        if enabled is None:
            enabled = str(os.getenv("ENABLE_CONSCIOUSNESS", "0") or "0").strip().lower() in ("1", "true", "yes", "on")
        self.enabled = bool(enabled)

        self._market_score_ema = 0.0
        self._spread_bps_ema = 0.0
        self._vol_ema = 0.0
        self._last_ts = 0.0
        self._recent_scores = _qdeque(maxlen=self.window)

    @staticmethod
    def _ema(prev: float, x: float, a: float) -> float:
        if prev == 0.0:
            return float(x)
        return float(prev + a * (float(x) - prev))

    @staticmethod
    def _spread_bps(bid: float, ask: float) -> float:
        b = float(bid or 0.0)
        a = float(ask or 0.0)
        if b <= 0 or a <= 0:
            return 0.0
        mid = (a + b) / 2.0
        if mid <= 0:
            return 0.0
        return float((a - b) / mid * 10000.0)

    @staticmethod
    def _safe_std(xs: List[float]) -> float:
        n = len(xs)
        if n < 2:
            return 0.0
        mu = sum(xs) / n
        var = sum((x - mu) ** 2 for x in xs) / max(1, (n - 1))
        return float(math.sqrt(max(0.0, var)))

    def update(
        self,
        symbol: str,
        bid: float,
        ask: float,
        mid: float,
        depth: Optional[Dict[str, Any]] = None,
        raw_score: Optional[float] = None,
        symbol_state: Optional[Any] = None,
    ) -> ConsciousnessSnapshot:
        ts = _pp920_time.time()
        if not self.enabled:
            # Still return a deterministic snapshot for callers (no side-effects).
            return ConsciousnessSnapshot(
                ts=ts,
                market_score_ema=float(self._market_score_ema),
                spread_bps_ema=float(self._spread_bps_ema),
                vol_ema=float(self._vol_ema),
                risk_level=0.0,
                regime="NEUTRAL",
                notes="disabled",
            )

        s = 0.0 if raw_score is None else float(raw_score)
        self._recent_scores.append(s)

        spr = self._spread_bps(bid, ask)
        # Per-symbol vol from recent returns (log-returns are preferred)
        vol = 0.0
        try:
            if symbol_state is not None and hasattr(symbol_state, "returns"):
                rs = list(getattr(symbol_state, "returns") or [])[-60:]
                vol = self._safe_std([float(x) for x in rs])
        except Exception:
            vol = 0.0

        self._market_score_ema = self._ema(self._market_score_ema, s, self.alpha)
        self._spread_bps_ema = self._ema(self._spread_bps_ema, spr, self.spread_alpha)
        self._vol_ema = self._ema(self._vol_ema, vol, self.vol_alpha)
        self._last_ts = ts

        # Risk model (explainable): spread + vol drive risk_off; market_score drives risk_on
        # Normalize components into 0..1
        spread_risk = _clamp(self._spread_bps_ema / 60.0, 0.0, 1.0)  # 60 bps => high risk
        vol_risk = _clamp(self._vol_ema / 0.010, 0.0, 1.0)          # ~1% log-vol => high risk
        score_risk_on = _clamp((abs(self._market_score_ema)) / 0.9, 0.0, 1.0)

        # risk_level: higher means "be conservative"
        risk_level = _clamp(0.55 * spread_risk + 0.35 * vol_risk - 0.20 * score_risk_on, 0.0, 1.0)

        if risk_level >= 0.66:
            regime = "RISK_OFF"
        elif risk_level <= 0.33:
            regime = "RISK_ON"
        else:
            regime = "NEUTRAL"

        notes = f"spr_ema={self._spread_bps_ema:.1f} vol_ema={self._vol_ema:.5f} score_ema={self._market_score_ema:.3f}"
        return ConsciousnessSnapshot(
            ts=ts,
            market_score_ema=float(self._market_score_ema),
            spread_bps_ema=float(self._spread_bps_ema),
            vol_ema=float(self._vol_ema),
            risk_level=float(risk_level),
            regime=regime,
            notes=notes,
        )


class NeuralCortex:
    """Safe post-processor for scores based on MarketConsciousness.

    این کلاس «تصمیم» را عوض نمی‌کند مگر این‌که ENABLE_QUANTUM=1 باشد.
    حتی در آن حالت هم سقف تغییر محدود است.
    """
    def __init__(self, consciousness: Optional[MarketConsciousness] = None):
        self.consciousness = consciousness

    def risk_multiplier(self, snap: Optional[ConsciousnessSnapshot]) -> float:
        if snap is None:
            return 1.0
        # In RISK_OFF we reduce aggressiveness; in RISK_ON we keep 1.0
        if snap.regime == "RISK_OFF":
            return float(_clamp(1.0 - 0.6 * snap.risk_level, 0.30, 1.0))
        if snap.regime == "NEUTRAL":
            return float(_clamp(1.0 - 0.25 * snap.risk_level, 0.70, 1.0))
        return 1.0


@dataclass
class QuantumState:
    phase: str = "STABLE"     # "STABLE" | "ATTACK" | "DEFEND"
    strength: float = 0.0     # 0..1
    last_update_ts: float = 0.0


class QuantumDecisionEngine:
    """Quantum-*named* module با منطق واقعی و ایمن (نه دمو/دکوری).

    فلسفه:
      - score را با درنظر گرفتن رژیم بازار (Consciousness) «اندکی» تنظیم می‌کند
      - هیچ وقت قرار نیست مدل اصلی را override کند یا تغییر شدید بدهد
    """
    def __init__(self, cortex: Optional[NeuralCortex] = None, enabled: Optional[bool] = None):
        self.cortex = cortex or NeuralCortex(None)
        if enabled is None:
            enabled = str(os.getenv("ENABLE_QUANTUM", "0") or "0").strip().lower() in ("1", "true", "yes", "on")
        self.enabled = bool(enabled)
        self.max_adjust = abs(float(os.getenv("QUANTUM_MAX_ADJUST", "0.08") or 0.08))
        self.state = QuantumState()

    def _update_phase(self, snap: Optional[ConsciousnessSnapshot]) -> None:
        now = _pp920_time.time()
        self.state.last_update_ts = now
        if snap is None:
            self.state.phase = "STABLE"
            self.state.strength = 0.0
            return
        # Simple regime->phase mapping
        if snap.regime == "RISK_OFF":
            self.state.phase = "DEFEND"
            self.state.strength = float(_clamp(snap.risk_level, 0.0, 1.0))
        elif snap.regime == "RISK_ON":
            self.state.phase = "ATTACK"
            self.state.strength = float(_clamp(1.0 - snap.risk_level, 0.0, 1.0))
        else:
            self.state.phase = "STABLE"
            self.state.strength = float(_clamp(0.5 - abs(snap.risk_level - 0.5), 0.0, 0.5))

    def adjust_score(
        self,
        symbol: str,
        raw_score: float,
        snap: Optional[ConsciousnessSnapshot],
        symbol_state: Optional[Any] = None,
    ) -> float:
        s = float(raw_score)
        if not self.enabled:
            return s
        self._update_phase(snap)

        # Conservative multiplier when risk rises
        mult = self.cortex.risk_multiplier(snap)
        adj = s * mult

        # Small phase bias (bounded)
        bias = 0.0
        if self.state.phase == "DEFEND":
            bias = -0.15 * self.state.strength
        elif self.state.phase == "ATTACK":
            bias = 0.08 * self.state.strength

        out = adj + bias
        # Cap total adjustment relative to original score for safety
        delta = _clamp(out - s, -self.max_adjust, self.max_adjust)
        return float(_clamp(s + delta, -1.0, 1.0))


class QuantumInspiredOptimizer:
    """Parameter tuner (safe, optional).

    این کلاس فقط ابزار است؛ هیچ‌چیز را خودکار تغییر نمی‌دهد مگر caller صدا بزند.
    """
    def __init__(self):
        self.last_params: Dict[str, float] = {}

    def suggest(
        self,
        base: Dict[str, float],
        snap: Optional[ConsciousnessSnapshot] = None,
    ) -> Dict[str, float]:
        # Safe: only very small nudges
        out = dict(base or {})
        if snap is None:
            return out
        # When risk is high, nudge thresholds upward to trade less
        k = float(_clamp(snap.risk_level, 0.0, 1.0))
        out["buy_thr_mul"] = float(_clamp(1.0 + 0.20 * k, 1.0, 1.25))
        out["sell_thr_mul"] = float(_clamp(1.0 + 0.10 * k, 1.0, 1.15))
        self.last_params = out
        return out


def _pp5_env_true(name: str, default: str = "0") -> bool:
    v = str(os.getenv(name, default) or default).strip().lower()
    return v in ("1", "true", "yes", "y", "on")

def _pp5_get_consciousness(self):
    """Lazy-create MarketConsciousness when ENABLE_CONSCIOUSNESS=1 (safe by default)."""
    if not _pp5_env_true("ENABLE_CONSCIOUSNESS", "0"):
        return None
    mc = getattr(self, "consciousness", None)
