def _pp5_postprocess_score(
    self,
    sym: str,
    symst: _SymbolState,
    bid: float,
    ask: float,
    mid: float,
    depth_data: Dict[str, Any],
    score: float,
) -> float:
    """Apply Consciousness/Quantum overlays (bounded + safe)."""
    snap: Optional[ConsciousnessSnapshot] = None
    try:
        mc = _pp5_get_consciousness(self)
        if mc is not None:
            snap = mc.update(
                symbol=sym,
                bid=float(bid or 0.0),
                ask=float(ask or 0.0),
                mid=float(mid or 0.0),
                depth=depth_data,
                raw_score=float(score),
                symbol_state=symst,
            )
            try:
                setattr(symst, "last_regime", getattr(snap, "regime", ""))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        q = _pp5_get_quantum(self)
        if q is not None:
            score = q.adjust_score(sym, float(score), snap, symst)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return float(score)


class _EdgeModelLegacy:
    """
    Lightweight internal AI (no TF):
      - Momentum (EMA fast/slow)
      - Volatility (EMA variance of returns)
      - Order book imbalance (top of book)
      - Spread penalty
    Outputs score in [-1, +1]
    """
    def __init__(self, fast_alpha: float = 0.20, slow_alpha: float = 0.06, var_alpha: float = 0.08):
        self.fast_alpha = float(fast_alpha)
        self.slow_alpha = float(slow_alpha)
        self.var_alpha = float(var_alpha)

    def update_and_score(self, st: _SymbolState, bid: float, ask: float, mid: float, depth: Dict[str, Any]) -> float:
        if mid <= 0:
            return 0.0
        if st.last_mid > 0:
            r = (mid / st.last_mid) - 1.0
        else:
            r = 0.0
        st.last_mid = mid

        st.prices.append(mid)
        st.returns.append(r)

        # EMA fast/slow
        if st.ema_fast == 0.0:
            st.ema_fast = mid
            st.ema_slow = mid
        st.ema_fast = (1 - self.fast_alpha) * st.ema_fast + self.fast_alpha * mid
        st.ema_slow = (1 - self.slow_alpha) * st.ema_slow + self.slow_alpha * mid

        # EMA variance on returns
        st.ema_var = (1 - self.var_alpha) * st.ema_var + self.var_alpha * (r * r)
        vol = math.sqrt(max(0.0, st.ema_var))

        mom = 0.0
        if st.ema_slow > 0:
            mom = (st.ema_fast / st.ema_slow) - 1.0

        # Book imbalance (top levels)
        bids = (depth or {}).get("bids") or []
        asks = (depth or {}).get("asks") or []
        bq = 0.0
        aq = 0.0
        for i in range(min(5, len(bids))):
            try:
                bq += float((bids[i] or {}).get("amount") or (bids[i] or {}).get("volume") or 0.0)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        for i in range(min(5, len(asks))):
            try:
                aq += float((asks[i] or {}).get("amount") or (asks[i] or {}).get("volume") or 0.0)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        imb = 0.0
        denom = (bq + aq)
        if denom > 0:
            imb = (bq - aq) / denom  # [-1, +1]

        spr = _spread_bps(bid, ask)
        spread_penalty = _clamp(spr / 80.0, 0.0, 1.5)

        # Risk-adjust: higher vol => smaller effective momentum/imbalance
        vol_scale = 1.0 / (1.0 + (vol * 40.0))
        raw = (mom * 14.0 + imb * 0.9) * vol_scale
        raw = raw - 0.20 * spread_penalty

        score = _clamp(raw, -1.0, 1.0)
        st.last_score = score
        return score


