                                    setattr(self, "_pp_last_fs_reason", (f"NO_EDGE sym={sym} score={float(score or 0.0):.6f} thr={float(buy_thr_eff or 0.0):.6f} phoenix={str(_pp910_pred or '')}")[:240])
                                    setattr(self, "_pp_last_fs_reason_ts", _pp920_time.time())
