# =============================================================================
# PP12 EVALUATION ADDON (Institutional-style, stdlib-only, Termux-friendly)
# - Walk-forward evaluation (OOS)
# - Simple grid calibration for thresholds (no TensorFlow, no heavy deps)
# =============================================================================

# ════════════════════════════════════════════════════════════════════════════
# 🏦 FUND-GRADE SUITE (Risk + Journal + FactSheet + Ranking) - REAL MODE
# ════════════════════════════════════════════════════════════════════════════
class FundGradeSuite:
    """
    Fund-grade layer that adds:
      - portfolio risk controls (VaR/CVaR/MaxDD + daily lock) WITHOUT disabling emergency exits
      - persistent journal (JSONL) suitable for audit
      - periodic factsheet-style reports (JSON + TXT)
      - ranking/score (0..10) using existing _fund_grade_score heuristic

    Principles:
      - ریشه‌ای، اما بدون حذف قابلیت‌های قبلی
      - واقعی (همه چیز از داده واقعی و وضعیت واقعی می‌آید)
      - سبک و Termux-friendly: فقط stdlib
    """
    def __init__(self, *, report_dir: str = None, logger: Optional[logging.Logger] = None):
        self.logger = logger or logging.getLogger()

        self.report_dir = str(report_dir or os.getenv("PP14_REPORT_DIR", "pp14_reports")).strip() or "pp14_reports"
        try:
            os.makedirs(self.report_dir, exist_ok=True)
        except Exception:
            self.report_dir = "."

        self.journal_path = os.path.join(self.report_dir, "journal.jsonl")
        self.equity_path = os.path.join(self.report_dir, "equity.jsonl")
        self.latest_factsheet_json = os.path.join(self.report_dir, "factsheet_latest.json")
        self.latest_factsheet_txt = os.path.join(self.report_dir, "factsheet_latest.txt")

        # Risk knobs (env-overridable)
        self.risk_per_trade_pct = float(os.getenv("RISK_PER_TRADE_PCT", "0.005") or 0.005)
        self.max_drawdown_pct = float(os.getenv("MAX_DRAWDOWN_PCT", "0.20") or 0.20)
        self.var_conf = float(os.getenv("VAR_CONF", "0.99") or 0.99)
        self.max_var_pct = float(os.getenv("MAX_VAR_PCT", "0.06") or 0.06)
        self.max_cvar_pct = float(os.getenv("MAX_CVAR_PCT", "0.09") or 0.09)
        self.var_min_samples = int(os.getenv("VAR_MIN_SAMPLES", "120") or 120)

        self.report_every_sec = int(os.getenv("FACTSHEET_EVERY_SEC", "3600") or 3600)
        self._last_report_ts = 0.0

        self._max_hist = int(os.getenv("EQUITY_HISTORY_MAX", "20000") or 20000)
        self._eq_ts: Dict[str, Any] = {}
        self._eq_val: Dict[str, Any] = {}
        self._eq_peak: Dict[str, float] = {}

    def _dq(self, wname: str):
        if wname not in self._eq_ts:
            self._eq_ts[wname] = _deque(maxlen=self._max_hist)
            self._eq_val[wname] = _deque(maxlen=self._max_hist)
            self._eq_peak[wname] = 0.0

    def _append_jsonl(self, path: str, obj: dict) -> None:
        try:
            with open(path, "a", encoding="utf-8") as f:
                f.write(_json.dumps(obj, ensure_ascii=False) + "\n")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def on_wallet_snapshot(self, ts: float, w: _WalletCfg, st: Optional[_LiveState], balances: dict, equity: float, price_map: dict) -> None:
        wname = str(getattr(w, "name", "") or "")
        self._dq(wname)

        eq = float(equity or 0.0)
        self._eq_ts[wname].append(float(ts))
        self._eq_val[wname].append(eq)

        # peak/dd
        peak = float(self._eq_peak.get(wname, 0.0) or 0.0)
        if eq > peak:
            self._eq_peak[wname] = eq
            peak = eq
        dd = (peak - eq) / peak if peak > 0 else 0.0

        self._append_jsonl(self.equity_path, {"ts": float(ts), "wallet": wname, "equity_irt": eq, "peak_irt": peak, "drawdown_pct": float(dd)})

        # Hard drawdown lock
        if st is not None and float(dd) > abs(float(self.max_drawdown_pct)):
            lock_sec = int(os.getenv("DD_LOCK_SEC", "3600") or 3600)
            st.locked_until = max(float(getattr(st, "locked_until", 0.0) or 0.0), float(ts) + float(lock_sec))
            self.logger.critical(f"[{wname}] MAX_DRAWDOWN LOCK dd={dd:.4f} peak={peak:.0f} eq={eq:.0f} locked_until={st.locked_until:.0f}")

    def _equity_returns(self, wname: str):
        self._dq(wname)
        ts = list(self._eq_ts[wname])
        eq = list(self._eq_val[wname])
        if len(eq) < 3:
            return ts, eq, []
        rets = []
        for i in range(1, len(eq)):
            a = float(eq[i-1] or 0.0)
            b = float(eq[i] or 0.0)
            if a <= 0 or b <= 0:
                rets.append(0.0)
            else:
                rets.append(math.log(b / a))
        return ts, eq, rets

    def _max_drawdown(self, eq: List[float]) -> float:
        peak = 0.0
        mdd = 0.0
        for v in eq:
            v = float(v or 0.0)
            if v > peak:
                peak = v
            if peak > 0:
                dd = (peak - v) / peak
                if dd > mdd:
                    mdd = dd
        return float(mdd)

    def _var_cvar(self, rets: List[float], conf: float):
        if not rets or len(rets) < self.var_min_samples:
            return None, None
        arr = sorted(float(x) for x in rets)
        q = max(0, min(len(arr)-1, int((1.0 - float(conf)) * len(arr))))
        var = -arr[q]
        tail = arr[:q+1]
        cvar = -(sum(tail) / max(1, len(tail)))
        return float(var), float(cvar)

    def _annualize_factor(self, ts: List[float], rets: List[float]) -> float:
        if len(ts) < 3 or not rets:
            return 0.0
        dts = []
        for i in range(1, len(ts)):
            dt = float(ts[i] - ts[i-1])
            if 1.0 <= dt <= 3600.0:
                dts.append(dt)
        if not dts:
            return 0.0
        dt_mean = sum(dts) / len(dts)
        return (365.0 * 24.0 * 3600.0) / max(1.0, dt_mean)

    def factsheet(self, wname: str) -> dict:
        ts, eq, rets = self._equity_returns(wname)
        if len(eq) < 2:
            return {"wallet": wname, "ok": False, "reason": "not_enough_equity_samples"}

        t0 = float(ts[0] if ts else _pp920_time.time())
        t1 = float(ts[-1] if ts else _pp920_time.time())
        dur_sec = max(1.0, t1 - t0)
        total_ret = (float(eq[-1]) / max(1e-12, float(eq[0]))) - 1.0

        periods_per_year = self._annualize_factor(ts, rets)
        mean_r = (sum(rets) / len(rets)) if rets else 0.0
        var_r = 0.0
        for x in rets:
            var_r += (x - mean_r) * (x - mean_r)
        sd_r = math.sqrt(var_r / max(1, (len(rets)-1))) if len(rets) > 2 else 0.0

        ann_ret = 0.0
        ann_vol = 0.0
        sharpe = 0.0
        sortino = 0.0
        if periods_per_year > 0 and rets:
            ann_ret = math.expm1(mean_r * periods_per_year)
            ann_vol = sd_r * math.sqrt(periods_per_year)
            if sd_r > 1e-12:
                sharpe = (mean_r / sd_r) * math.sqrt(periods_per_year)
            downs = [x for x in rets if x < 0]
            if downs:
                md = sum(downs) / len(downs)
                vd = 0.0
                for x in downs:
                    vd += (x - md) * (x - md)
                sd_d = math.sqrt(vd / max(1, (len(downs)-1))) if len(downs) > 2 else 0.0
                if sd_d > 1e-12:
                    sortino = (mean_r / sd_d) * math.sqrt(periods_per_year)

        mdd = self._max_drawdown(eq)
        calmar = (ann_ret / max(1e-12, mdd)) if mdd > 0 else 0.0

        var99, cvar99 = self._var_cvar(rets, conf=self.var_conf)
        var_pct = (math.expm1(var99) if var99 is not None else None)
        cvar_pct = (math.expm1(cvar99) if cvar99 is not None else None)

        out = {
            "wallet": wname,
            "ok": True,
            "period": {"start_ts": t0, "end_ts": t1, "duration_sec": dur_sec},
            "equity": {"start_irt": float(eq[0]), "end_irt": float(eq[-1])},
            "returns": {"total_return": float(total_ret), "annualized_return": float(ann_ret), "annualized_vol": float(ann_vol),
                        "sharpe_like": float(sharpe), "sortino_like": float(sortino)},
            "risk": {"max_drawdown": float(mdd), "calmar_like": float(calmar), "var_conf": float(self.var_conf),
                     "var": None if var99 is None else float(var_pct), "cvar": None if cvar99 is None else float(cvar_pct)},
        }
        try:
            out["fund_grade_score"] = float(_fund_grade_score({
                "total_return": out["returns"]["total_return"],
                "max_drawdown": out["risk"]["max_drawdown"],
                "sharpe_like": out["returns"]["sharpe_like"],
                "trades": 0.0,
            }))
        except Exception:
            out["fund_grade_score"] = 0.0
        return out

    def pre_trade(self, *, wallet_cfg: _WalletCfg, wallet_state: _LiveState, sym: str, side: str,
                  qty: float, price: float, notional: float,
                  equity: float, quote_free: float, asset_free: float,
                  score: float, spr_bps: float, sym_state: _SymbolState, meta: dict) -> Tuple[bool, Optional[float], str]:
        wname = str(getattr(wallet_cfg, "name", "") or "")
        side = str(side).lower().strip()
        eq = float(equity or 0.0)
        if eq <= 0:
            return False, None, "equity<=0"

        now = _pp920_time.time()
        if float(getattr(wallet_state, "locked_until", 0.0) or 0.0) > now:
            return False, None, f"locked_until={float(wallet_state.locked_until):.0f}"

        max_spr = float(getattr(wallet_cfg, "max_spread_bps", 0.0) or 0.0)
        if max_spr > 0 and float(spr_bps or 0.0) > max_spr * 1.25:
            return False, None, f"spread_too_wide({spr_bps:.1f}bps)"

        if side == "sell":
            if qty <= 0:
                return False, None, "qty<=0"
            if qty > (asset_free * 1.05 + 1e-12):
                return False, None, "qty_exceeds_asset_free"
            return True, None, "ok"

        if side != "buy":
            return True, None, "ok"

        if qty <= 0 or price <= 0 or notional <= 0:
            return False, None, "invalid_qty_price"

        # Position sizing: risk budget per trade
        risk_budget = eq * abs(float(self.risk_per_trade_pct))

        vol = 0.0
        try:
            vol = math.sqrt(max(0.0, float(getattr(sym_state, "ema_var", 0.0) or 0.0)))
        except Exception:
            vol = 0.0
        vol = max(1e-6, float(vol))
        k_sigma = float(os.getenv("STOP_SIGMA", "2.5") or 2.5)
        stop_move = max(1e-6, k_sigma * vol)
        qty_cap_risk = risk_budget / max(1e-12, float(price) * float(stop_move))

        # Wallet VaR/CVaR lock (based on equity history)
        wfs = self.factsheet(wname)
        var_pct = None
        cvar_pct = None
        try:
            var_pct = (wfs.get("risk") or {}).get("var")
            cvar_pct = (wfs.get("risk") or {}).get("cvar")
        except Exception:
            var_pct = None
            cvar_pct = None

        if var_pct is not None and float(var_pct) > abs(float(self.max_var_pct)):
            lock_sec = int(os.getenv("VAR_LOCK_SEC", "1800") or 1800)
            wallet_state.locked_until = max(float(wallet_state.locked_until or 0.0), now + lock_sec)
            return False, None, f"wallet_var_exceeded({float(var_pct):.4f})"
        if cvar_pct is not None and float(cvar_pct) > abs(float(self.max_cvar_pct)):
            lock_sec = int(os.getenv("CVAR_LOCK_SEC", "1800") or 1800)
            wallet_state.locked_until = max(float(wallet_state.locked_until or 0.0), now + lock_sec)
            return False, None, f"wallet_cvar_exceeded({float(cvar_pct):.4f})"

        qty_cap_cash = float(quote_free or 0.0) / max(1e-12, float(price))
        qty_allowed = min(float(qty), float(qty_cap_cash), float(qty_cap_risk))
        if qty_allowed <= 0:
            return False, None, "qty_allowed<=0"
        if qty_allowed < float(qty):
            return True, float(qty_allowed), "qty_reduced_risk"
        return True, None, "ok"

    def maybe_emit_reports(self, now_ts: float) -> None:
        if self.report_every_sec <= 0:
            return
        if (now_ts - float(self._last_report_ts or 0.0)) < float(self.report_every_sec):
            return
        self._last_report_ts = float(now_ts)

        wallets = sorted(list(self._eq_ts.keys()))
        fs_all = [self.factsheet(w) for w in wallets]

        # Rank by fund_grade_score
        try:
            scores = [float((x or {}).get("fund_grade_score") or 0.0) for x in fs_all]
            order = sorted(range(len(scores)), key=lambda i: scores[i], reverse=True)
            ranking = [{"rank": k+1, "wallet": fs_all[i].get("wallet"), "score": scores[i]} for k,i in enumerate(order)]
        except Exception:
            ranking = []

        report = {"ts": float(now_ts), "wallets": fs_all, "ranking": ranking}

        try:
            with open(self.latest_factsheet_json, "w", encoding="utf-8") as f:
                f.write(_json.dumps(report, ensure_ascii=False, indent=2))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            lines_out = []
            lines_out.append(f"PP14 FACTSHEET @ {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(now_ts))}")
            lines_out.append("="*72)
            for fs in fs_all:
                if not fs.get("ok"):
                    lines_out.append(f"{fs.get('wallet')}: (no data)")
                    continue
                r = fs.get("returns") or {}
                rk = fs.get("risk") or {}
                lines_out.append(
                    f"{fs.get('wallet')}: score={fs.get('fund_grade_score',0):.2f} "
                    f"ret={r.get('total_return',0):+.2%} ann={r.get('annualized_return',0):+.2%} "
                    f"mdd={rk.get('max_drawdown',0):.2%} sharpe={r.get('sharpe_like',0):.2f} "
                    f"VaR{int(self.var_conf*100)}={(rk.get('var') if rk.get('var') is not None else 'NA')}"
                )
            if ranking:
                lines_out.append("-"*72)
                lines_out.append("RANKING:")
                for it in ranking:
                    lines_out.append(f"  {it['rank']}. {it['wallet']}  score={it['score']:.2f}")
            with open(self.latest_factsheet_txt, "w", encoding="utf-8") as f:
                f.write("\n".join(lines_out) + "\n")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        self.logger.info(f"[FACTSHEET] wrote {self.latest_factsheet_json} and {self.latest_factsheet_txt}")

    def journal_order(self, *, ts: float, wallet: str, symbol: str, side: str, qty: float, price: float,
                      notional: float, ok: bool, extra: Optional[dict] = None) -> None:
        obj = {"ts": float(ts), "wallet": str(wallet), "symbol": str(symbol), "side": str(side),
               "qty": float(qty), "price": float(price), "notional_irt": float(notional), "ok": bool(ok)}
        if extra:
            obj["extra"] = extra
        self._append_jsonl(self.journal_path, obj)


def factsheet_from_db(db_path: str, wallet: str) -> dict:
    try:
        eq_perf = recorded_equity_performance_from_db(db_path, wallet)
        fs = {"wallet": wallet, "ok": True if eq_perf and eq_perf.get("ok") else False, "recorded_equity_perf": eq_perf}
        if eq_perf and eq_perf.get("ok"):
            fs["fund_grade_score"] = float(_fund_grade_score({
                "total_return": float(eq_perf.get("total_return") or 0.0),
                "max_drawdown": float(eq_perf.get("max_drawdown") or 0.0),
                "sharpe_like": float(eq_perf.get("sharpe_like") or 0.0),
                "trades": float(eq_perf.get("trades") or 0.0),
            }))
        return fs
    except Exception as e:
        return {"wallet": wallet, "ok": False, "error": str(e)}


class PP5LiveTripleWalletFundGrade(PP5LiveTripleWalletInstitutional):
    """Default runtime bot (3 wallets) with FundGradeSuite enabled."""
    # v8042 MATURITY: provide missing scrub hook at the class level (prevents wallet-cycle exception spam / deadlocks).
    # This is NOT a new feature; it completes an already-referenced capability and is a deterministic no-op when unsupported.
    def _scrub_low_quality_assets(self, api=None, wname: str = "", balances_free=None):
        try:
            # Prefer first implementation in MRO (excluding this class).
            for _cls in type(self).mro()[1:]:
                _fn = getattr(_cls, "_scrub_low_quality_assets", None)
                if callable(_fn):
                    return _fn(self, api=api, wname=wname, balances_free=balances_free)
        except Exception:
            return balances_free
        return balances_free


# v8036 MATURITY: ensure FundGrade always exposes asset scrub hook (prevents decision-deadlock on missing method)
# NOTE: no behavior change when base hook is absent or fails; this is a compatibility bridge.
def _scrub_low_quality_assets(self, api, wname: str, balances_free):
    try:
        _base = globals().get("PP5LiveTripleWallet")
        _fn = getattr(_base, "_scrub_low_quality_assets", None) if _base is not None else None
        if callable(_fn):
            return _fn(self, api=api, wname=wname, balances_free=balances_free)
    except Exception:
        return None
    return None
    def __init__(self, symbols: List[str], quote: str = "IRT"):
        super().__init__(symbols=symbols, quote=quote)
        # PP114: legacy guard - provide balances method if missing
        if not hasattr(self, "_balances"):
            def _b(self, api):
                return _pp114_balances_fallback(api)
            _pp114__bind(self, "_balances", _b)

        self.fund_suite = FundGradeSuite(report_dir=os.getenv("PP14_REPORT_DIR", "pp14_reports"), logger=self.logger)
        self.logger.info(f"[PP14] FundGradeSuite enabled report_dir={self.fund_suite.report_dir!r}")


