def _load_tick_rows(db_path: str, symbol: str, wallet: str = "W1") -> List[Tuple[float, float, float, float, float, float]]:
    db = _sqlite3.connect(str(db_path))
    cur = db.cursor()
    cur.execute(
        "SELECT ts,bid,ask,mid,spr_bps,score FROM ticks WHERE wallet=? AND symbol=? ORDER BY ts ASC",
        (str(wallet), str(symbol).upper())
    )
    rows = cur.fetchall()
    db.close()
    return rows or []

def _backtest_rows(rows: List[Tuple[float, float, float, float, float, float]],
                   initial_cash_irt: float = 1_000_000.0,
                   buy_thr: float = 0.55, sell_thr: float = 0.55,
                   fee_bps: float = 12.0, slippage_bps: float = 5.0,
                   max_trade_quote_pct: float = 0.10) -> Dict[str, Any]:
    if not rows:
        return {"ok": False, "error": "no_rows"}

    cash = float(initial_cash_irt)
    asset = 0.0
    fee = float(fee_bps) / 10000.0
    slip = float(slippage_bps) / 10000.0
    equity_curve: List[float] = []
    trades = 0

    first_ask = float(rows[0][2] or 0.0)
    last_mid = float(rows[-1][3] or 0.0)
    bh_asset = (float(initial_cash_irt) * (1.0 - fee)) / max(1e-12, first_ask * (1.0 + slip)) if first_ask > 0 else 0.0
    bh_final = bh_asset * last_mid if last_mid > 0 else 0.0

    for (ts, bid, ask, mid, spr_bps, score) in rows:
        bid = float(bid or 0.0); ask = float(ask or 0.0); mid = float(mid or 0.0); score = float(score or 0.0)
        if mid <= 0:
            continue
        equity = cash + asset * mid
        equity_curve.append(equity)

        if score >= float(buy_thr) and cash > 0 and ask > 0:
            spend = _pp_fee_aware_spend(cash, equity * float(max_trade_quote_pct), fee_bps=float(fee_bps), slippage_bps=float(slippage_bps), safety_bps=float(_os.getenv('ORDER_SAFETY_BPS','10') or 10))
            # PP602: SovereignVetoCouncil + resurrected genes => minimum size on any risk hint
            try:
                _pp602_sym = None
                try:
                    _pp602_sym = (locals().get('sym') or locals().get('symbol') or locals().get('pair') or locals().get('s') or '')
                except Exception:
                    _pp602_sym = ''
                _pp602_payload = None
                try:
                    _pp602_payload = (locals().get('payload') or locals().get('_payload') or None)
                except Exception:
                    _pp602_payload = None
                if _pp602_payload is None:
                    try:
                        if hasattr(self, 'get_cached'):
                            _pp602_payload = self.get_cached(str(_pp602_sym))
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag='pp602_payload')
                        _pp602_payload = None
                _pp602_council = None
                try:
                    _pp602_council = getattr(self, '_pp602_veto_council', None)
                    if _pp602_council is None:
                        _pp602_council = SovereignVetoCouncil(getattr(self, 'bot', None) or self)
                        setattr(self, '_pp602_veto_council', _pp602_council)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag='pp602_council')
                    _pp602_council = None
                if _pp602_council is not None and isinstance(_pp602_payload, dict):
                    _pp602_mult, _pp602_rsn = _pp602_council.min_size_multiplier(str(_pp602_sym), _pp602_payload)
                    try:
                        _pp602_mult = float(_pp602_mult or 1.0)
                    except Exception:
                        _pp602_mult = 1.0
                    if _pp602_mult < 1.0:
                        spend = float(spend) * float(max(0.0, min(1.0, _pp602_mult)))
                        try:
                            setattr(self, '_pp602_last_min_size_reason', str(_pp602_rsn)[:180])
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag='pp602_min_size')
                pass
            if spend > 0:
                px = ask * (1.0 + slip)
                qty = (spend * (1.0 - fee)) / max(1e-12, px)
                if qty > 0:
                    cash -= spend
                    asset += qty
                    trades += 1

        elif score <= -float(sell_thr) and asset > 0 and bid > 0:
            qty = asset * 0.25
            if qty > 0:
                px = bid * (1.0 - slip)
                got = qty * px * (1.0 - fee)
                asset -= qty
                cash += got
                trades += 1

    final_equity = cash + asset * max(1e-12, float(rows[-1][3] or 0.0))
    total_ret = (final_equity / float(initial_cash_irt)) - 1.0
    mdd = _bt_max_drawdown(equity_curve)

    rets: List[float] = []
    for i in range(1, len(equity_curve)):
        e0 = equity_curve[i-1]
        e1 = equity_curve[i]
        if e0 > 0:
            rets.append((e1 / e0) - 1.0)
    mu = _safe_mean(rets)
    sd = _safe_std(rets)
    sharpe_like = (mu / sd) * math.sqrt(365.0 * 24.0 * 60.0) if sd > 0 else 0.0
    bh_ret = (bh_final / float(initial_cash_irt)) - 1.0 if bh_final > 0 else 0.0

    return {
        "ok": True,
        "ticks": int(len(rows)),
        "trades": int(trades),
        "initial_cash_irt": float(initial_cash_irt),
        "final_equity_irt": float(final_equity),
        "total_return": float(total_ret),
        "max_drawdown": float(mdd),
        "sharpe_like": float(sharpe_like),
        "buy_hold_return": float(bh_ret),
        "buy_hold_final_irt": float(bh_final),
        "fee_bps": float(fee_bps),
        "slippage_bps": float(slippage_bps),
    }

def _calibrate_on_rows(rows: List[Tuple[float, float, float, float, float, float]],
                       buy_grid: List[float], sell_grid: List[float],
                       initial_cash_irt: float, fee_bps: float, slippage_bps: float, max_trade_pct: float) -> Dict[str, Any]:
    best = None
    top: List[Tuple[float, float, float, Dict[str, Any]]] = []
    for b in buy_grid:
        for s in sell_grid:
            if s <= 0 or b <= 0:
                continue
            r = _backtest_rows(rows, initial_cash_irt=initial_cash_irt, buy_thr=float(b), sell_thr=float(s),
                               fee_bps=float(fee_bps), slippage_bps=float(slippage_bps), max_trade_quote_pct=float(max_trade_pct))
            if not r.get("ok"):
                continue
            # Objective: prefer stable equity (penalize drawdown)
            score = float(r.get("sharpe_like") or 0.0) - 2.0 * float(r.get("max_drawdown") or 0.0) + 0.25 * float(r.get("total_return") or 0.0)
            top.append((score, float(b), float(s), r))
            if (best is None) or (score > best[0]):
                best = (score, float(b), float(s), r)
    top.sort(key=lambda x: x[0], reverse=True)
    return {
        "ok": bool(best),
        "best": {
            "objective": float(best[0]) if best else None,
            "buy_thr": float(best[1]) if best else None,
            "sell_thr": float(best[2]) if best else None,
            "metrics": best[3] if best else None,
        } if best else None,
        "top5": [
            {"objective": float(sc), "buy_thr": float(b), "sell_thr": float(s), "metrics": m}
            for (sc, b, s, m) in top[:5]
        ],
        "grid_size": int(len(buy_grid) * len(sell_grid)),
        "rows": int(len(rows)),
    }

def calibrate_thresholds_from_db(db_path: str, symbol: str, wallet: str = "W1",
                                 buy_grid: Optional[List[float]] = None,
                                 sell_grid: Optional[List[float]] = None,
                                 initial_cash_irt: float = 1_000_000.0,
                                 fee_bps: float = 12.0, slippage_bps: float = 5.0,
                                 max_trade_pct: float = 0.10) -> Dict[str, Any]:
    rows = _load_tick_rows(db_path=db_path, symbol=symbol, wallet=wallet)
    if not rows:
        return {"ok": False, "error": "no_rows"}
    if buy_grid is None:
        buy_grid = [round(x, 2) for x in [0.35,0.40,0.45,0.50,0.55,0.60,0.65,0.70,0.75,0.80]]
    if sell_grid is None:
        sell_grid = [round(x, 2) for x in [0.35,0.40,0.45,0.50,0.55,0.60,0.65,0.70,0.75,0.80]]
    out = _calibrate_on_rows(rows, buy_grid, sell_grid, initial_cash_irt, fee_bps, slippage_bps, max_trade_pct)
    out.update({"symbol": str(symbol).upper(), "wallet": str(wallet), "db_path": str(db_path)})
    if out.get("ok") and out.get("best"):
        b = out["best"]["buy_thr"]; s = out["best"]["sell_thr"]
        out["recommended_env"] = f"export BUY_THRESHOLD={b}; export SELL_THRESHOLD={s}"
    return out

def walkforward_evaluate_from_db(db_path: str, symbol: str, wallet: str = "W1",
                                 splits: int = 5, train_frac: float = 0.60,
                                 buy_grid: Optional[List[float]] = None,
                                 sell_grid: Optional[List[float]] = None,
                                 initial_cash_irt: float = 1_000_000.0,
                                 fee_bps: float = 12.0, slippage_bps: float = 5.0,
                                 max_trade_pct: float = 0.10) -> Dict[str, Any]:
    rows = _load_tick_rows(db_path=db_path, symbol=symbol, wallet=wallet)
    n = len(rows)
    if n < 200:
        return {"ok": False, "error": "not_enough_rows", "rows": int(n), "message": "Need more recorded ticks for OOS evaluation."}
    if buy_grid is None:
        buy_grid = [round(x, 2) for x in [0.40,0.45,0.50,0.55,0.60,0.65,0.70]]
    if sell_grid is None:
        sell_grid = [round(x, 2) for x in [0.40,0.45,0.50,0.55,0.60,0.65,0.70]]

    splits = max(2, int(splits))
    train_size = max(50, int(n * float(train_frac)))
    remaining = max(1, n - train_size)
    test_size = max(50, remaining // splits)

    folds = []
    for k in range(splits):
        tr_end = min(n, train_size + k * test_size)
        te_start = tr_end
        te_end = min(n, te_start + test_size)
        if te_end - te_start < 50:
            break
        train_rows = rows[:tr_end]
        test_rows = rows[te_start:te_end]

        cal = _calibrate_on_rows(train_rows, buy_grid, sell_grid, initial_cash_irt, fee_bps, slippage_bps, max_trade_pct)
        best = (cal.get("best") or {})
        b = best.get("buy_thr") or 0.55
        s = best.get("sell_thr") or 0.55

        test = _backtest_rows(test_rows, initial_cash_irt=initial_cash_irt, buy_thr=float(b), sell_thr=float(s),
                              fee_bps=float(fee_bps), slippage_bps=float(slippage_bps), max_trade_quote_pct=float(max_trade_pct))

        folds.append({
            "fold": int(k+1),
            "train_rows": int(len(train_rows)),
            "test_rows": int(len(test_rows)),
            "best_buy_thr": float(b),
            "best_sell_thr": float(s),
            "train_best": best.get("metrics"),
            "test": test,
        })

    # Aggregate OOS
    oos_rets = [float(f["test"].get("total_return") or 0.0) for f in folds if f.get("test",{}).get("ok")]
    oos_mdd  = [float(f["test"].get("max_drawdown") or 0.0) for f in folds if f.get("test",{}).get("ok")]
    oos_sh   = [float(f["test"].get("sharpe_like") or 0.0) for f in folds if f.get("test",{}).get("ok")]

    def _scrub_low_quality_assets(self, api: ArzPlusAPI, wname: str, balances_free: Dict[str, float]) -> None:
        """Compatibility wrapper: keep v8027 scrubbing hook callable in FundGrade runtime.

        This method existed in the core bot line; some patchsets/loaders can drop it from the active MRO.
        We do NOT change behavior: if an upstream implementation exists, we delegate; otherwise we no-op.
        """
        try:
            return super()._scrub_low_quality_assets(api=api, wname=wname, balances_free=balances_free)  # type: ignore[attr-defined]
        except Exception:
            return

    def _med(xs):
        xs = sorted(xs)
        if not xs:
            return 0.0
        m = len(xs)//2
        return float(xs[m]) if len(xs)%2==1 else float(xs[m-1]+xs[m])/2.0

    return {
        "ok": True,
        "db_path": str(db_path),
        "symbol": str(symbol).upper(),
        "wallet": str(wallet),
        "rows": int(n),
        "splits": int(len(folds)),
        "train_frac": float(train_frac),
        "folds": folds,
        "oos": {
            "mean_total_return": float(_safe_mean(oos_rets)),
            "median_total_return": float(_med(oos_rets)),
            "mean_max_drawdown": float(_safe_mean(oos_mdd)),
            "median_max_drawdown": float(_med(oos_mdd)),
            "mean_sharpe_like": float(_safe_mean(oos_sh)),
            "median_sharpe_like": float(_med(oos_sh)),
        }
    }

def _pp_startup_audit(args) -> None:
    """Fail-fast checks so LIVE mode never starts in an ambiguous/unsafe state.

    هدف: اگر کد «از مسیر اصلی منحرف شود» یا وضعیت شبکه/توکن/حالت‌اجرا مبهم باشد،
    قبل از ارسال سفارش واقعی، با پیام واضح متوقف شود (نه دفن خطا).
    """
    problems: List[str] = []

    # Core class sanity
    cls = globals().get('PP5_DEFAULT_CLASS')
    if cls is None:
        problems.append('PP5_DEFAULT_CLASS is not defined')
    else:
        for m in ('loop', '_place_buy', '_place_sell', '_list_open_orders', '_reconcile_and_cancel_stale'):
            if not hasattr(cls, m):
                problems.append(f'PP5_DEFAULT_CLASS missing method: {m}')

    # Detect a "silent" dry-run
    live_cli = bool(getattr(args, 'live', False))
    live_env = str(os.getenv('LIVE_TRADING', '0') or '0').strip().lower() in ('1','true','yes','on')
    dry_env = str(os.getenv('DRY_RUN', '1') or '1').strip().lower() in ('1','true','yes','on')
    if live_cli or live_env:
        if dry_env:
            problems.append('LIVE requested but DRY_RUN=1 (set DRY_RUN=0 for real trading)')
        # Safe reconcile strongly recommended in LIVE
        sr = str(os.getenv('SAFE_RECONCILE', '1') or '1').strip().lower() in ('1','true','yes','on')
        if not sr:
            problems.append('SAFE_RECONCILE=0 in LIVE mode (high risk of double-buy on network issues). Set SAFE_RECONCILE=1')

        # Token presence (do NOT print tokens)
        t1 = str(os.getenv('ARZPLUS_WALLET_1_TOKEN', '') or '').strip()
        t2 = str(os.getenv('ARZPLUS_WALLET_2_TOKEN', '') or '').strip()
        t3 = str(os.getenv('ARZPLUS_WALLET_3_TOKEN', '') or '').strip()
        missing = []
        if not t1: missing.append('W1')
        if not t2: missing.append('W2')
        if not t3: missing.append('W3')
        if missing:
            problems.append(f'Missing ArzPlus tokens for: {missing} (set env vars or paste into manual-token section)')

    if problems:
        msg = '\n'.join(' - ' + p for p in problems)
        raise RuntimeError('Startup audit failed:\n' + msg)


# ============================================================
# PP113: Dynamic Market Scanner (Auto-Discovery)
# - Uses ArzPlusAPI.get_all_tickers()
# - Ranks by 24h quoteVolume + Price Change % (trend power)
# - Selects TOP N (default 8) for live trading
# ============================================================

def _pp113__to_float(x: Any, default: float = 0.0) -> float:
    try:
        if x is None:
            return float(default)
        if isinstance(x, (int, float)):
            return float(x)
        s = str(x).strip()
        if not s:
            return float(default)
        s = s.replace(",", "").replace("٪", "%").replace("%", "").strip()
        return float(s)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(default)

def _pp113__pick(row: Dict[str, Any], *keys: str) -> Any:
    for k in keys:
        if k in row:
            return row.get(k)
    return None

def _pp113__extract_rows(resp: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(resp, dict):
        return []
    data = resp.get("data")
    if data is None:
        return []
    # common: list
    if isinstance(data, list):
        return [x for x in data if isinstance(x, dict)]
    # common: dict with list under a key
    if isinstance(data, dict):
        for k in ("results", "data", "symbols", "markets", "tickers", "items"):
            v = data.get(k)
            if isinstance(v, list):
                return [x for x in v if isinstance(x, dict)]
        # dict mapping symbol -> row
        if data and all(isinstance(v, dict) for v in data.values()):
            out = []
            for sym, row in data.items():
                if isinstance(row, dict):
                    r = dict(row)
                    if "symbol" not in r:
                        r["symbol"] = sym
                    out.append(r)
            return out
    return []

def _pp113__get_symbol(row: Dict[str, Any]) -> str:
    s = _pp113__pick(row, "symbol", "Symbol", "pair", "Pair", "market", "Market", "name", "code")
    return str(s or "").strip().upper()

def _pp113__get_last_price(row: Dict[str, Any]) -> float:
    return _pp113__to_float(_pp113__pick(row, "last", "lastPrice", "last_price", "close", "closePrice", "price", "mid"))

def _pp113__get_open_price(row: Dict[str, Any]) -> float:
    return _pp113__to_float(_pp113__pick(row, "open", "openPrice", "open_price", "first", "prevClose", "prev_close"))

def _pp113__get_quote_volume(row: Dict[str, Any]) -> float:
    # Primary: direct quote volume fields
    qv = _pp113__to_float(_pp113__pick(
        row,
        "volume", "volume_24h", "volume24h", "volume24H", "quoteVolume", "quote_volume", "quoteVolume24h", "quote_volume_24h",
        "volumeQuote", "volume_quote", "quoteVol", "quote_vol",
        "turnover", "quoteTurnover", "quote_turnover"
    ), default=0.0)
    if qv > 0.0:
        return qv

    # Secondary: if we only have base volume, approximate quote volume = baseVolume * lastPrice
    bv = _pp113__to_float(_pp113__pick(
        row,
        "baseVolume", "base_volume", "volume", "vol", "volume24h", "volume_24h"
    ), default=0.0)
    if bv > 0.0:
        lp = _pp113__get_last_price(row)
        if lp > 0.0:
            return bv * lp
        return bv
    return 0.0

def _pp113__get_change_pct(row: Dict[str, Any]) -> float:
    # Direct percent field
    p = _pp113__to_float(_pp113__pick(
        row,
        "priceChangePercent", "price_change_percent",
        "changePercent", "change_percent", "changePercent",
        "percentChange", "percent_change",
        "chgPct", "chg_pct",
        "change_24h_pct", "pct_24h", "pctChange24h"
    ), default=0.0)
    if p != 0.0:
        return p

    # Sometimes change is a string with % sign
    p2 = _pp113__pick(row, "change", "priceChange", "price_change")
    # If 'change' is already percent-like, parse; otherwise compute from open/last.
    pp = _pp113__to_float(p2, default=0.0)
    if abs(pp) > 0.0 and abs(pp) <= 1000.0:
        # Heuristic: if abs <= 1000 treat as percent-like
        return pp

    o = _pp113__get_open_price(row)
    l = _pp113__get_last_price(row)
    if o > 0.0 and l > 0.0:
        return (l - o) / o * 100.0
    return 0.0

def _pp113_dynamic_scan(api: "ArzPlusAPI",
                        quote: str = "IRT",
                        top_n: int = 8,
                        logger: Optional[logging.Logger] = None,
                        resp: Optional[Dict[str, Any]] = None,
                        rows: Optional[List[Dict[str, Any]]] = None) -> List[str]:
    """
    Auto-discover all symbols and rank them by:
      - 24h quoteVolume (liquidity)
      - Price Change % (trend power)

    Returns TOP N symbols (IRT-only).
    """
    try:
        top_n = int(top_n or 8)
        top_n = max(1, min(50, top_n))  # hard clamp
    except Exception:
        top_n = 8

    try:
        if rows is None:
            r = resp if resp is not None else api.get_all_tickers()
            if not isinstance(r, dict) or (not r.get("ok")):
                return []
            rows = _pp113__extract_rows(r)
        if not rows:
            return []

        quote = str(quote or "IRT").strip().upper()
        want_positive = _pp5_env_true("PP113_POSITIVE_TREND_ONLY", default="0")
        min_qv = _pp113__to_float(os.getenv("PP113_MIN_QUOTEVOL", "0") or 0.0, default=0.0)

        # Weights (volume dominates, trend is secondary)
        wv = _pp113__to_float(os.getenv("PP113_WEIGHT_VOLUME", "0.70") or 0.70, default=0.70)
        wt = _pp113__to_float(os.getenv("PP113_WEIGHT_TREND", "0.30") or 0.30, default=0.30)
        sw = max(1e-9, (wv + wt))
        wv, wt = wv / sw, wt / sw

        cand = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            sym = _pp113__get_symbol(row)
            if not sym or (not sym.endswith(quote)):
                continue
            qv = _pp113__get_quote_volume(row)
            if qv < min_qv:
                continue
            chg = _pp113__get_change_pct(row)
            if want_positive and chg < 0.0:
                chg = 0.0
            # Avoid NaNs
            if qv < 0.0:
                qv = 0.0
            cand.append((sym, float(qv), float(chg)))

        if not cand:
            return []

        # Normalization
        import math as _math
        v_logs = [_math.log1p(x[1]) for x in cand]
        c_pos = [max(0.0, x[2]) for x in cand]
        max_v = max(v_logs) if v_logs else 1.0
        max_c = max(c_pos) if c_pos else 1.0
        if max_v <= 0.0:
            max_v = 1.0
        if max_c <= 0.0:
            max_c = 1.0

        scored = []
        for sym, qv, chg in cand:
            v = _math.log1p(qv) / max_v
            c = max(0.0, chg) / max_c
            score = (wv * v) + (wt * c)
            scored.append((score, sym, qv, chg))

        scored.sort(key=lambda x: x[0], reverse=True)
        top = scored[:top_n]
        out = [x[1] for x in top]

        # Log compact summary (avoid memory growth)
        try:
            if logger is None:
                logger = logging.getLogger()
            logger.info(f"[PP113] scan ok | candidates={len(scored)} top={len(out)} symbols={out}")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return out
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return []


def _pp5_main():
    parser = _argparse.ArgumentParser()
    parser.add_argument("--live", action="store_true", help="Enable REAL live trading (must be used along with LIVE_TRADING=1 and DRY_RUN=0).")
    parser.add_argument("--allow-multi", action="store_true", help="Allow multiple bot instances (NOT recommended; can cause duplicate orders/DB locks)")
    parser.add_argument("--report-dir", default=os.getenv("PP14_REPORT_DIR", "pp14_reports"), help="output directory for journal/factsheet")
    parser.add_argument("--splits", type=int, default=int(os.getenv("WF_SPLITS", "5") or 5), help="walk-forward splits")
    parser.add_argument("--train-frac", type=float, default=float(os.getenv("WF_TRAIN_FRAC", "0.60") or 0.60), help="walk-forward train fraction")
    parser.add_argument("--db", default=os.getenv("RECORD_DB_PATH", "pp10_ticks.sqlite"), help="SQLite DB path (ticks)")
    parser.add_argument("--symbol", default=os.getenv("BACKTEST_SYMBOL", ""), help="symbol for backtest (e.g., BTCIRT)")
    parser.add_argument("--wallet", default=os.getenv("BACKTEST_WALLET", "W1"), help="wallet name for backtest (W1/W2/W3)")
    parser.add_argument("--initial-cash", type=float, default=float(os.getenv("BACKTEST_INITIAL_CASH", "1000000") or 1000000),
                        help="initial cash (IRT) for backtest")
    parser.add_argument("--fee-bps", type=float, default=float(os.getenv("BACKTEST_FEE_BPS", "12") or 12),
                        help="fee in bps for backtest")
    parser.add_argument("--slippage-bps", type=float, default=float(os.getenv("BACKTEST_SLIPPAGE_BPS", "5") or 5),
                        help="slippage in bps for backtest")
    parser.add_argument("--max-trade-pct", type=float, default=float(os.getenv("BACKTEST_MAX_TRADE_PCT", "0.10") or 0.10),
                        help="max trade size as fraction of equity for backtest")
    parser.add_argument("--record", action="store_true", help="force enable tick recorder (RECORD_TICKS=1)")
    parser.add_argument("--model", default=os.getenv("MODEL", "HYBRID"), help="EDGE or HYBRID (default HYBRID)")
    # ---- Special / offline modes (no orders) ----
    parser.add_argument('--doctor', action='store_true', help='Run connectivity diagnostics (no orders) and exit.')
    parser.add_argument('--selftest', action='store_true', help='Run self-test (no orders) and exit.')
    parser.add_argument('--backtest', action='store_true', help='Run simple backtest from recorded ticks DB and exit.')
    parser.add_argument('--backtest-pro', dest='backtest_pro', action='store_true', help='Run extended backtest suite (legacy_sim + signal_diag + recorded_equity_perf) and exit.')
    parser.add_argument('--signal-diag', dest='signal_diag', action='store_true', help='Run signal diagnostics on recorded ticks DB and exit.')
    parser.add_argument('--calibrate', action='store_true', help='Grid-search BUY/SELL thresholds on recorded ticks DB and exit.')
    parser.add_argument('--walkforward', action='store_true', help='Walk-forward (OOS) evaluation on recorded ticks DB and exit.')
    parser.add_argument('--factsheet', action='store_true', help='Compute factsheet from recorded equity/performance and exit.')
    parser.add_argument('--factsheet-all', dest='factsheet_all', action='store_true', help='Compute factsheet for W1/W2/W3 and exit.')
    args = parser.parse_args()

    # Start watchdog heartbeat toucher ASAP (safe even without watchdog)
    _pp110_child_hb_init()

    # SSL safety: verification is mandatory (no bypass).

    # ===== MODE SELECTION (PRODUCTION) =====
    # Goals:
    # - REAL trading by default when valid tokens are present.
    # - NEVER silently fall back to DRY_RUN when tokens are missing (fail-fast instead).
    # - Special modes (doctor/backtest/calibrate/...) never auto-enable LIVE.
    #
    # Apply manual tokens + WalletStore tokens here (no import-time side effects).
    _pp_apply_manual_tokens()
    _maybe_set_env_from_walletstore()

    # Determine whether this run is a "special" (non-live) mode.
    _special = any(bool(getattr(args, k, False)) for k in (
        "doctor","selftest","backtest","backtest_pro","signal_diag","calibrate","walkforward","factsheet","factsheet_all"
    ))

    # ---- SPECIAL / OFFLINE MODES (no orders) ----
    # These modes must never start the watchdog or the live loop.
    if _special:
        os.environ['PP5_CLI_LIVE'] = '0'
        os.environ['LIVE_TRADING'] = '0'
        os.environ['DRY_RUN'] = '1'
        try:
            setup_logging(tui=False)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # Small helper: stable JSON printing (no token leaks)
        def _pp5__print_json(obj):
            try:
                import json as _json
                print(_json.dumps(obj, ensure_ascii=False, indent=2, sort_keys=False))
            except Exception:
                try:
                    print(str(obj))
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

        # Choose a symbol for DB-based modes
        _sym = (getattr(args, 'symbol', '') or '').strip().upper()
        if not _sym:
            _syms = str(os.getenv('SYMBOLS', os.getenv('PP5_SYMBOLS', 'PAXGIRT')) or 'PAXGIRT')
            _sym = (_syms.split(',')[0] if _syms else 'PAXGIRT').strip().upper()

        if getattr(args, 'doctor', False):
            _pp5_doctor()
            return
        if getattr(args, 'selftest', False):
            _pp5_selftest()
            return

        if getattr(args, 'signal_diag', False):
            res = signal_diagnostics_from_db(str(getattr(args,'db','') or ''), _sym, str(getattr(args,'wallet','W1') or 'W1'))
            _pp5__print_json(res)
            return

        if getattr(args, 'calibrate', False):
            res = calibrate_thresholds_from_db(str(getattr(args,'db','') or ''), _sym, str(getattr(args,'wallet','W1') or 'W1'),
                                               initial_cash_irt=float(getattr(args,'initial_cash',1_000_000.0) or 1_000_000.0),
                                               fee_bps=float(getattr(args,'fee_bps',12.0) or 12.0),
                                               slippage_bps=float(getattr(args,'slippage_bps',5.0) or 5.0),
                                               max_trade_pct=float(getattr(args,'max_trade_pct',0.10) or 0.10))
            _pp5__print_json(res)
            return

        if getattr(args, 'walkforward', False):
            res = walkforward_evaluate_from_db(str(getattr(args,'db','') or ''), _sym, str(getattr(args,'wallet','W1') or 'W1'),
                                               splits=int(getattr(args,'splits',5) or 5), train_frac=float(getattr(args,'train_frac',0.60) or 0.60),
                                               initial_cash_irt=float(getattr(args,'initial_cash',1_000_000.0) or 1_000_000.0),
                                               fee_bps=float(getattr(args,'fee_bps',12.0) or 12.0),
                                               slippage_bps=float(getattr(args,'slippage_bps',5.0) or 5.0),
                                               max_trade_pct=float(getattr(args,'max_trade_pct',0.10) or 0.10))
            _pp5__print_json(res)
            return

        if getattr(args, 'factsheet_all', False):
            wallets = ['W1','W2','W3']
            res = [factsheet_from_db(str(getattr(args,'db','') or ''), w) for w in wallets]
            _pp5__print_json({'ok': True, 'db_path': str(getattr(args,'db','') or ''), 'factsheets': res})
            return
        if getattr(args, 'factsheet', False):
            res = factsheet_from_db(str(getattr(args,'db','') or ''), str(getattr(args,'wallet','W1') or 'W1'))
            _pp5__print_json(res)
            return

        # Backtests
        _buy_thr = float(os.getenv('BUY_THRESHOLD', '0.55') or 0.55)
        _sell_thr = float(os.getenv('SELL_THRESHOLD', '0.55') or 0.55)
        if getattr(args, 'backtest_pro', False):
            res = backtest_from_db_pro(str(getattr(args,'db','') or ''), _sym, str(getattr(args,'wallet','W1') or 'W1'),
                                       start_equity_quote=float(getattr(args,'initial_cash',1_000_000.0) or 1_000_000.0),
                                       fee_bps=float(getattr(args,'fee_bps',12.0) or 12.0),
                                       slip_bps=float(getattr(args,'slippage_bps',5.0) or 5.0),
                                       buy_thr=float(_buy_thr), sell_thr=float(_sell_thr))
            _pp5__print_json(res)
            return
        if getattr(args, 'backtest', False):
            res = backtest_from_db(str(getattr(args,'db','') or ''), _sym, str(getattr(args,'wallet','W1') or 'W1'),
                                   initial_cash_irt=float(getattr(args,'initial_cash',1_000_000.0) or 1_000_000.0),
                                   buy_thr=float(_buy_thr), sell_thr=float(_sell_thr),
                                   fee_bps=float(getattr(args,'fee_bps',12.0) or 12.0),
                                   slippage_bps=float(getattr(args,'slippage_bps',5.0) or 5.0),
                                   max_trade_quote_pct=float(getattr(args,'max_trade_pct',0.10) or 0.10))
            _pp5__print_json(res)
            return

        raise RuntimeError('Special mode requested but no handler matched (internal).')


    _toks_present = all((os.getenv(k) or "").strip() for k in (
        "ARZPLUS_WALLET_1_TOKEN", "ARZPLUS_WALLET_2_TOKEN", "ARZPLUS_WALLET_3_TOKEN"
    ))

    # LIVE must be explicit: no auto-live based on token presence.
    _want_live = bool(getattr(args, "live", False))

    if _want_live:
        # Human arming gate (prevents accidental real trading).
        _armed = str(os.getenv("ARZPLUS_LIVE_ARMED", "") or "").strip().lower() in ("1", "true", "yes", "on", "y")
        if not _armed:
            raise RuntimeError("LIVE trading requires explicit arming: export ARZPLUS_LIVE_ARMED=YES then run with --live.")

        # SSL safety is mandatory and enforced by _HTTPClient (no bypass).

        os.environ["PP5_CLI_LIVE"] = "1"
        os.environ["LIVE_TRADING"] = "1"
        os.environ["DRY_RUN"] = "0"
        globals()["_PP5_CLI_LIVE_ARMED_RUNTIME"] = True

        if not _toks_present:
            raise RuntimeError("LIVE trading selected but missing hardcoded tokens W1/W2/W3. Paste tokens in manual-token section or set env vars.")
    else:
        os.environ["PP5_CLI_LIVE"] = "0"
        globals()["_PP5_CLI_LIVE_ARMED_RUNTIME"] = False
        os.environ.setdefault("LIVE_TRADING", "0")
        os.environ.setdefault("DRY_RUN", "1")
        # This build is intended for REAL trading only; refuse to run the trading loop in DRY mode.
        if not _special:
            raise RuntimeError("DRY mode is disabled in this build. Run with --live and export ARZPLUS_LIVE_ARMED=YES.")

# Fail-fast sanity checks (no orders). Disable by setting STARTUP_AUDIT=0.
    if str(os.getenv('STARTUP_AUDIT', '1') or '1').strip().lower() in ('1','true','yes','on'):
        _pp_startup_audit(args)
    mode = "LIVE" if (os.getenv("PP5_CLI_LIVE","0").strip().lower() in ("1","true","yes","on") and os.getenv("DRY_RUN","1").strip() in ("0","false","no","off")) else "DRY_RUN"
    # v730 ROOTFIX: enforce mandatory monitor symbols early (prevents BTC-only universe / stale env issues)
    try:
        _mandatory = ['PAXGIRT', 'USDTIRT', 'BTCIRT']
        _raw_syms = os.getenv('SYMBOLS', os.getenv('PP5_SYMBOLS', '') or '')
        _lst = [s.strip().upper() for s in str(_raw_syms).split(',') if str(s).strip()]
        for _m in _mandatory:
            if _m not in _lst:
                _lst.append(_m)
        if not _lst:
            _lst = list(_mandatory)
        _joined = ','.join(_lst)
        os.environ['PP5_SYMBOLS'] = _joined
        os.environ['SYMBOLS'] = _joined
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    logging.getLogger().warning(f"[MODE] {mode} | symbols={os.getenv('SYMBOLS', os.getenv('PP5_SYMBOLS','BTCIRT'))} quote={os.getenv('QUOTE','IRT')}")

    # ===== SINGLE INSTANCE GUARD (ROOTFIX) =====
    # Prevents duplicate orders / duplicated writers / SQLite locks due to accidentally launching twice.
    if not args.allow_multi:
        global _PP_INSTANCE_LOCK_FD
        try:
            import fcntl as _fcntl
            _lock_path = os.path.join(os.path.dirname(__file__) or ".", ".pp_bot_instance.lock")
            _PP_INSTANCE_LOCK_FD = os.open(_lock_path, os.O_CREAT | os.O_RDWR, 0o600)
            try:
                _fcntl.flock(_PP_INSTANCE_LOCK_FD, _fcntl.LOCK_EX | _fcntl.LOCK_NB)
            except BlockingIOError:
                other_pid = None
                try:
                    os.lseek(_PP_INSTANCE_LOCK_FD, 0, os.SEEK_SET)
                    other_pid = os.read(_PP_INSTANCE_LOCK_FD, 64).decode("utf-8", "ignore").strip() or None
                except Exception:
                    other_pid = None

                def _pp118_pid_alive(_pid: int) -> bool:
                    try:
                        if _pid <= 0:
                            return False
                        if os.path.exists(f"/proc/{_pid}"):
                            return True
                        os.kill(_pid, 0)
                        return True
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_return")
                        return False

                if other_pid and str(other_pid).isdigit() and not _pp118_pid_alive(int(other_pid)):
                    # Stale lock file (previous crash). Recreate and lock.
                    try:
                        os.close(_PP_INSTANCE_LOCK_FD)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    try:
                        os.unlink(_lock_path)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    _PP_INSTANCE_LOCK_FD = os.open(_lock_path, os.O_CREAT | os.O_RDWR, 0o600)
                    _fcntl.flock(_PP_INSTANCE_LOCK_FD, _fcntl.LOCK_EX | _fcntl.LOCK_NB)
                    os.ftruncate(_PP_INSTANCE_LOCK_FD, 0)
                    os.write(_PP_INSTANCE_LOCK_FD, str(os.getpid()).encode())
                else:
                    raise RuntimeError(f"Another instance is already running (pid={other_pid}). If you are sure it's stale, delete {_lock_path} and retry. (Forcing multi-instance is NOT recommended).")
            try:
                os.ftruncate(_PP_INSTANCE_LOCK_FD, 0)
                os.write(_PP_INSTANCE_LOCK_FD, str(os.getpid()).encode("utf-8"))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        except Exception as e:
            # Fail-fast: this is safer than running with potential duplicates.
            raise


    if args.record:
        os.environ["RECORD_TICKS"] = "1"
        if args.db:
            os.environ["RECORD_DB_PATH"] = str(args.db)

    if args.model:
        os.environ["MODEL"] = str(args.model)


    try:
        setup_logging(tui=True)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # ---- Offline evaluation modes (no live trading) ----
    def _pick_symbol() -> str:
        sym = (args.symbol or "").strip().upper()
        if not sym:
            syms = os.getenv("SYMBOLS", os.getenv("PP5_SYMBOLS", "PAXGIRT")).strip()
            sym = (syms.split(",")[0] if syms else "PAXGIRT").strip().upper()
        return sym

    # ===== LIVE LOOP =====
    quote = "IRT"  # Absolute IRT (Toman) dominance (no rial conversion)
    # Fixed 3-second pulse (price refresh + dashboard cadence)
    interval = 3

    # PP113: Public API client for discovery/scanning (no auth)
    _pp113_pub = None
    try:
        _pp113_pub = ArzPlusAPI(token="<PASTE_YOUR_SECRET_HERE>",
                                timeout=float(os.getenv("ARZPLUS_PUBLIC_TIMEOUT", "15") or 15.0),
                                rate_limit_per_min=int(os.getenv("ARZPLUS_PUBLIC_RL", "100") or 100))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)
        _pp113_pub = None

    # Discovery Logic: pull enabled markets from /market/symbols/ at startup (NO manual list)
    _enabled_syms = []
    try:
        if _pp113_pub is not None:
            _tickers = _pp113_pub.get_all_tickers()
            _rows = _pp113__extract_rows(_tickers)
            for _it in (_rows or []):
                if not isinstance(_it, dict):
                    continue
                if _it.get("enable") is not True:
                    continue
                _nm = str(_it.get("name") or "").strip().upper()
                if not _nm:
                    continue
                if not _nm.endswith("IRT"):
                    continue
                _enabled_syms.append(_nm)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)
        _enabled_syms = []

    # Trinity Priority System
    # Trinity Priority System (v728): PAXGIRT (gold) > BTCIRT > USDTIRT
    try:
        _uni = list(_enabled)  # type: ignore[name-defined]
    except Exception:
        try:
            _uni = list(_enabled_syms)  # type: ignore[name-defined]
        except Exception:
            _uni = []
    # v729: Force primary monitor list at process start (break BTC-only universe issues)
    # Primaries are always included even if discovery temporarily misses them.
    _pri = ["PAXGIRT", "USDTIRT", "BTCIRT"]
    if _enabled_syms:
        _seen = set()
        symbols = []
        for _s in (_pri + _enabled_syms):
            _s = str(_s or "").strip().upper()
            if _s and _s not in _seen:
                symbols.append(_s)
                _seen.add(_s)
    else:
        symbols = list(_pri)

    bot = PP5_DEFAULT_CLASS(symbols=symbols, quote=quote)
    # PP119: Start fixed Rich TUI dashboard (non-blocking)
    _dash = None
    try:
        _dash = DashboardManager(bot, refresh_sec=float(os.getenv("DASH_REFRESH_SEC", "1.2") or 1.2))
        _dash.start()
    except Exception as _e:
        try:
            logging.getLogger().exception("[UI] dashboard init failed")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            print(f"[UI] dashboard init failed: {_e!r}", flush=True)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        _dash = None


    # PP113: Background periodic re-scan (every 15 minutes by default)
    try:
        if hasattr(bot, "start_dynamic_scanner"):
            bot.start_dynamic_scanner(
                api=_pp113_pub,
                interval_sec=int(os.getenv("PP113_SCAN_INTERVAL_SEC", "30") or 900),
                top_n=int(os.getenv("PP113_TOP_N", "8") or 8),
            )
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        bot.loop(interval_sec=interval)
    finally:
        try:
            if _dash is not None:
                _dash.stop()
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

# ============================================================
# PP110: Built-in Watchdog (Termux/Android friendly)
# - Run: python3 parisa110   (watchdog + LIVE)
# - No extra files required.
# - Restarts child process on crash (incl. OOM/SIGKILL) or hang.
# ============================================================

def _pp110_apply_termux_defaults() -> None:
    """Defaults tuned for 24/7 LIVE on Termux. User env overrides always win."""
    try:
        _os.environ.setdefault("ARZPLUS_LIVE_ARMED", "YES")
        # Signal accuracy knobs (can be overridden)
        _os.environ.setdefault("BUY_THRESHOLD", "0.68")
        _os.environ.setdefault("SELL_THRESHOLD", "0.68")
        _os.environ.setdefault("EDGE_BOOK_LEVELS", "15")
        _os.environ.setdefault("SIGNAL_STABLE_TICKS", "2")
        _os.environ.setdefault("VOLUME_CONFIRM_ENABLED", "1")
        _os.environ.setdefault("VOLUME_CONFIRM_PCT", "0.20")
        _os.environ.setdefault("VOLUME_CONFIRM_WINDOW_SEC", "600")
        _os.environ.setdefault("VOLUME_CONFIRM_LEVELS", "15")
        # SQLite under pressure (reduce 'database is locked' probability)
        _os.environ.setdefault("SQLITE_TIMEOUT_SEC", "60")
        # Watchdog: prefer subprocess over fork (more reliable with Rich TUI on Termux/Python 3.12).
        _os.environ.setdefault("PP110_USE_SUBPROCESS", "1")
        # Watchdog heartbeat must point to the actual rotating log file.
        _os.environ.setdefault("PP110_HEARTBEAT_FILE", _os.path.join("logs", "trading_bot.log"))
        # Dashboard stability on Termux (reduce flicker / CPU)
        _os.environ.setdefault("DASH_REFRESH_SEC", "3.0")
        _os.environ.setdefault("DASH_SCREEN", "0")  # disable alternate screen by default on Termux
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return

def _pp110_tokens_present() -> Tuple[bool, List[str]]:
    """Return (ok, missing_env_vars) for the 3 live-wallet tokens.

    Root-cause fix:
    - PP110 watchdog bootstrap validates tokens *before* calling _pp5_main().
      But manual tokens are only applied inside _pp5_main(), so LIVE startup
      could fail even when tokens are correctly pasted at the top of this file.
    - We therefore (safely) apply manual tokens + WalletStore tokens *here*
      before checking environment variables.
    """
    try:
        _pp_apply_manual_tokens()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    try:
        _maybe_set_env_from_walletstore()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    missing: List[str] = []


    def _pp110__is_placeholder(_v: str) -> bool:

        try:

            _vv = str(_v or "").strip().upper()

        except Exception:

            _vv = ""

        if not _vv:

            return True

        # Common placeholder patterns (never print token values)

        if ("<PASTE" in _vv) or ("PASTE_" in _vv) or ("TOKEN_HERE" in _vv) or ("PASTE_ARZPLUS" in _vv):

            return True

        # e.g. "<TOKEN>" / "<SECRET_TOKEN>" etc.

        if _vv.startswith("<") and _vv.endswith(">") and (("TOKEN" in _vv) or ("PASTE" in _vv) or ("SECRET" in _vv)):

            return True

        return False

    for k in ("ARZPLUS_WALLET_1_TOKEN", "ARZPLUS_WALLET_2_TOKEN", "ARZPLUS_WALLET_3_TOKEN"):

        v = (_os.environ.get(k) or "").strip()

        if (not v) or _pp110__is_placeholder(v):

            missing.append(k)

    return (len(missing) == 0), missing

def _pp110_child_argv() -> List[str]:
    """Force LIVE without requiring the user to type flags."""
    import sys as _sys
    argv = list(_sys.argv[1:])
    # real only: strip dry-run flags if present
    argv = [a for a in argv if a not in ("--dry-run","--dryrun","--paper")]
    if "--live" not in argv:
        argv.append("--live")
    return [_sys.argv[0]] + argv

def _pp110_rss_mb(pid: int) -> float:
    """Read RSS from /proc/<pid>/status (Linux/Android)."""
    try:
        p = f"/proc/{int(pid)}/status"
        with open(p, "r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                if line.startswith("VmRSS:"):
                    parts = line.split()
                    if len(parts) >= 2:
                        kb = float(parts[1])
                        return kb / 1024.0
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return 0.0

def _pp110_heartbeat_age_sec(path: str) -> float:
    try:
        st = _os.stat(path)
        return float(_pp920_time.time() - float(st.st_mtime))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return -1.0  # unknown / missing


def _pp110_heartbeat_age(path: str) -> float:
    """Compatibility alias used by watchdog loops."""
    return _pp110_heartbeat_age_sec(path)


# --- PP110 HEARTBEAT TOUCHER (prevents false stale restarts on Termux/Rich UI) ---
_PP110_HB_STOP_EVENT = None

def _pp110_hb_abspath(path: str) -> str:
    try:
        p = str(path or "").strip() or "trading_bot.log"
        p = _os.path.abspath(p)
        d = _os.path.dirname(p)
        if d and not _os.path.isdir(d):
            try:
                _os.makedirs(d, exist_ok=True)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        return p
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return str(path or "trading_bot.log")

def _pp110_touch_file(path: str) -> None:
    try:
        p = _pp110_hb_abspath(path)
        try:
            with open(p, "a", encoding="utf-8") as _f:
                pass
        except Exception:
            # best-effort create
            try:
                open(p, "a").close()
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return
        try:
            _os.utime(p, None)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

def _pp110_start_hb_toucher(path: str, interval_sec: float = 20.0):
    """Touch heartbeat file periodically so watchdog won't restart when logs are quiet."""
    try:
        import threading as _threading
        stop = _threading.Event()
        p = _pp110_hb_abspath(path)

        def _worker():
            # touch immediately
            _pp110_touch_file(p)
            while not stop.is_set():
                stop.wait(max(1.0, float(interval_sec or 20.0)))
                _pp110_touch_file(p)

        t = _threading.Thread(target=_worker, name="PP110Heartbeat", daemon=True)
        t.start()
        return stop
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return None

def _pp110_child_hb_init():
    """Safe to call multiple times; starts toucher once."""
    global _PP110_HB_STOP_EVENT
    try:
        hb = str(_os.getenv("PP110_HEARTBEAT_FILE", "trading_bot.log") or "trading_bot.log")
        hb = _pp110_hb_abspath(hb)
        # ensure file is fresh at start to avoid 'age ~ 1e9' from old stale file
        _pp110_touch_file(hb)
        if _PP110_HB_STOP_EVENT is None:
            interval = float(_os.getenv("PP110_HB_TOUCH_INTERVAL_SEC", "20") or 20.0)
            _PP110_HB_STOP_EVENT = _pp110_start_hb_toucher(hb, interval_sec=interval)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

def _pp110_watchdog() -> None:
    import signal as _signal
    import sys as _sys

    # knobs (override via env)
    soft_mb = float(_os.getenv("PP110_MEM_SOFT_MB", "900") or 900.0)
    hard_mb = float(_os.getenv("PP110_MEM_HARD_MB", "1100") or 1100.0)
    hb_path = _pp110_hb_abspath(str(_os.getenv("PP110_HEARTBEAT_FILE", "trading_bot.log") or "trading_bot.log"))
    hb_max_age = float(_os.getenv("PP110_HEARTBEAT_MAX_AGE_SEC", "120") or 120.0)
    hb_grace = float(_os.getenv("PP110_HEARTBEAT_GRACE_SEC", "180") or 180.0)
    hb_grace = max(60.0, hb_grace)
    restart_delay = float(_os.getenv("PP110_RESTART_DELAY_SEC", "2") or 2.0)
    term_grace = float(_os.getenv("PP110_TERM_GRACE_SEC", "8") or 8.0)
    # Ensure heartbeat file exists & is fresh (prevents stale restarts on cold start)
    _pp110_touch_file(hb_path)
    # Propagate absolute heartbeat path to child for consistency
    _os.environ["PP110_HEARTBEAT_FILE"] = hb_path

    backoff = 0.0
    cycle = 0

    while True:
        cycle += 1
        try:
            # Fork a child that runs the real bot.
            pid = _os.fork()
        except AttributeError:
            # No fork (very rare). Run directly.
            _pp5_main()
            return

        if pid == 0:
            # --- CHILD ---
            try:
                _os.environ["PP110_WATCHDOG_CHILD"] = "1"
                # Start heartbeat toucher early in child so parent won't restart while UI/logs are quiet
                _pp110_child_hb_init()
                # Child argv override: force LIVE & safety
                child_argv = _pp110_child_argv()
                _sys.argv = child_argv
                _pp5_main()
            except SystemExit as _e:
                code = int(getattr(_e, "code", 0) or 0)
                _os._exit(code)
            except Exception:
                try:
                    traceback.print_exc()
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                _os._exit(1)

        # --- PARENT (WATCHDOG) ---
        child_pid = int(pid)
        start_ts = _pp920_time.time()
        last_hb_ok_ts = start_ts
        print(f"[WATCHDOG] child started pid={child_pid} cycle={cycle} soft_mb={soft_mb} hard_mb={hard_mb} hb='{hb_path}'", flush=True)

        while True:
            # Check child exit (non-blocking)
            try:
                got, status = _os.waitpid(child_pid, _os.WNOHANG)
            except ChildProcessError:
                got, status = (child_pid, 0)

            if got == child_pid:
                # Child exited
                exit_code = 0
                sig = None
                try:
                    if _os.WIFEXITED(status):
                        exit_code = _os.WEXITSTATUS(status)
                    elif _os.WIFSIGNALED(status):
                        sig = _os.WTERMSIG(status)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                if sig is not None:
                    print(f"[WATCHDOG] child pid={child_pid} exited by signal={sig}. restarting...", flush=True)
                else:
                    print(f"[WATCHDOG] child pid={child_pid} exited code={exit_code}. restarting...", flush=True)
                break

            # RSS monitor
            rss = _pp110_rss_mb(child_pid)
            if rss > 0:
                if rss >= hard_mb:
                    print(f"[WATCHDOG] RSS hard limit hit ({rss:.0f}MB >= {hard_mb:.0f}MB). KILL child pid={child_pid}", flush=True)
                    try:
                        _os.kill(child_pid, _signal.SIGKILL)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                elif rss >= soft_mb:
                    print(f"[WATCHDOG] RSS soft limit hit ({rss:.0f}MB >= {soft_mb:.0f}MB). TERM child pid={child_pid}", flush=True)
                    try:
                        _os.kill(child_pid, _signal.SIGTERM)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

            # Heartbeat monitor (log mtime)
            age = _pp110_heartbeat_age_sec(hb_path)
            now = _pp920_time.time()
            if age >= 0:
                # If heartbeat is updating, record it.
                if age <= hb_max_age:
                    last_hb_ok_ts = now
                # If heartbeat stale beyond max age *after* grace window, restart.
                if (now - start_ts) >= hb_grace and age > hb_max_age and (now - last_hb_ok_ts) > hb_max_age:
                    print(f"[WATCHDOG] heartbeat stale age={age:.0f}s (> {hb_max_age:.0f}s). Restarting child pid={child_pid}", flush=True)
                    try:
                        _os.kill(child_pid, _signal.SIGTERM)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    # give it a moment then hard kill
                    t_end = _pp920_time.time() + term_grace
                    while _pp920_time.time() < t_end:
                        try:
                            got2, _st2 = _os.waitpid(child_pid, _os.WNOHANG)
                            if got2 == child_pid:
                                break
                        except Exception:
                            break
                        time.sleep(0.5)
                    try:
                        _os.kill(child_pid, _signal.SIGKILL)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

            time.sleep(1.0)

        # Backoff on rapid crashes
        runtime = _pp920_time.time() - start_ts
        if runtime < 10.0:
            backoff = min(30.0, max(backoff * 1.6, 2.0))
        else:
            backoff = 0.0
        sleep_for = max(restart_delay, backoff)
        time.sleep(sleep_for)


def _pp110_watchdog_subprocess() -> None:
    """
    Watchdog implementation using subprocess (instead of os.fork).
    This is more reliable with Rich full-screen TUI on Termux/Python 3.12.
    The child inherits the same terminal (TUI works), while the parent supervises
    memory + heartbeat and restarts on crash/hang.
    """
    import subprocess as _subprocess
    import sys as _sys
    import time as _time
    import traceback as _traceback

    # knobs (override via env)
    soft_mb = float(_os.getenv("PP110_MEM_SOFT_MB", "900") or 900.0)
    hard_mb = float(_os.getenv("PP110_MEM_HARD_MB", "1100") or 1100.0)
    hb_path = _pp110_hb_abspath(str(_os.getenv("PP110_HEARTBEAT_FILE", _os.path.join("logs", "trading_bot.log")) or _os.path.join("logs", "trading_bot.log")))
    # Ensure watchdog and child use the SAME heartbeat file (absolute path).
    _os.environ["PP110_HEARTBEAT_FILE"] = hb_path
    hb_max_age = float(_os.getenv("PP110_HEARTBEAT_MAX_AGE_SEC", "120") or 120.0)
    hb_grace = float(_os.getenv("PP110_HEARTBEAT_GRACE_SEC", "180") or 180.0)
    restart_delay = float(_os.getenv("PP110_RESTART_DELAY_SEC", "2") or 2.0)
    term_grace = float(_os.getenv("PP110_TERM_GRACE_SEC", "8") or 8.0)

    # Ensure log directory exists so heartbeat path is valid from the first second.
    try:
        _os.makedirs(_os.path.dirname(hb_path) or ".", exist_ok=True)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # Touch the heartbeat file immediately (prevents stale-age=1e9 on cold start)
    _pp110_touch_file(hb_path)

    backoff = 0.0
    cycle = 0

    while True:
        cycle += 1
        try:
            child_argv = _pp110_child_argv()
            cmd = [_sys.executable, "-u"] + child_argv

            child_env = dict(_os.environ)
            child_env["PP110_WATCHDOG_CHILD"] = "1"
            child_env["PP110_HEARTBEAT_FILE"] = hb_path
            # Also disable watchdog entry recursion defensively
            child_env.setdefault("PP110_DISABLE_WATCHDOG", "1")

            p = _subprocess.Popen(cmd, env=child_env)
            pid = int(getattr(p, "pid", 0) or 0)
            try:
                print(f"[WATCHDOG] child started pid={pid} cycle={cycle} soft_mb={soft_mb} hard_mb={hard_mb} hb={hb_path!r}", flush=True)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            start_ts = __pp920_time.time()
            last_hb_ok = start_ts

            # supervise
            while True:
                ret = p.poll()
                if ret is not None:
                    try:
                        print(f"[WATCHDOG] child exited pid={pid} code={ret}", flush=True)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    break

                # memory checks
                try:
                    rss = float(_pp110_rss_mb(pid))
                except Exception:
                    rss = 0.0
                if hard_mb and rss and rss > hard_mb:
                    try:
                        print(f"[WATCHDOG] HARD mem {rss:.1f}MB>{hard_mb:.1f}MB => killing pid={pid}", flush=True)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    try:
                        p.terminate()
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    _time.sleep(term_grace)
                    try:
                        p.kill()
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    break
                if soft_mb and rss and rss > soft_mb:
                    # soft notice only
                    try:
                        print(f"[WATCHDOG] SOFT mem {rss:.1f}MB>{soft_mb:.1f}MB pid={pid}", flush=True)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                # heartbeat checks
                now = __pp920_time.time()
                try:
                    age = float(_pp110_heartbeat_age(hb_path))
                except Exception:
                    age = 1e9
                if age >= 0 and age <= hb_max_age:
                    last_hb_ok = now
                else:
                    # allow grace at startup and after last ok heartbeat
                    if (now - start_ts) > hb_grace and (now - last_hb_ok) > hb_grace:
                        try:
                            print(f"[WATCHDOG] heartbeat stale age={age:.1f}s (max={hb_max_age}) => restarting pid={pid}", flush=True)
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e)

                        try:
                            p.terminate()
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e)

                        _time.sleep(term_grace)
                        try:
                            p.kill()
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e)

                        break

                _time.sleep(1.0)

        except KeyboardInterrupt:
            try:
                if 'p' in locals() and p and p.poll() is None:
                    p.terminate()
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            raise
        except Exception:
            try:
                _traceback.print_exc()
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        # backoff and restart
        try:
            _time.sleep(restart_delay + backoff)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        backoff = min(30.0, backoff + 1.0)

def _pp110_entry__legacy_pre150() -> None:
    """Single-command entrypoint: python3 parisa110 (watchdog + LIVE)."""
    # If launched as a watchdog child (subprocess mode), bypass watchdog and run the real bot directly.
    if str(_os.getenv("PP110_WATCHDOG_CHILD", "0") or "0").strip().lower() in ("1","true","yes","on"):
        import sys as _sys
        _sys.argv = _pp110_child_argv()
        _pp5_main()
        return
    # Apply safe defaults (user can override via env)
    _pp110_apply_termux_defaults()

    # Pull manual tokens (if pasted in header) into env so child inherits them.
    _pp_apply_manual_tokens()
    try:
        _maybe_set_env_from_walletstore()
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    ok, missing = _pp110_tokens_present()
    if not ok:
        raise RuntimeError(f"Missing ArzPlus tokens for LIVE: {missing}. Paste them at top of file or set env ARZPLUS_WALLET_1_TOKEN/2/3.")

    # Ensure the 'arming' flag is present (user wanted fully real trading).
    _os.environ.setdefault("ARZPLUS_LIVE_ARMED", "YES")

    # Run watchdog unless user explicitly disables it.
    if str(_os.getenv("PP110_DISABLE_WATCHDOG", "0") or "0").strip().lower() in ("1","true","yes","on"):
        # Direct run (still forces LIVE via argv injection)
        import sys as _sys
        _sys.argv = _pp110_child_argv()
        _pp5_main()
        return
    if str(_os.getenv("PP110_USE_SUBPROCESS", "1") or "1").strip().lower() in ("1","true","yes","on"):
        _pp110_watchdog_subprocess()
    else:
        _pp110_watchdog()


