def _ppdm_render_header_v145(self):
    from rich.panel import Panel
    from rich.table import Table
    from rich.text import Text
    from rich import box
    from datetime import datetime

    bot = getattr(self, "bot", None)
    try:
        ver = str(os.getenv("PP_VERSION", "v155") or "v145")
    except Exception:
        ver = "v145"
    try:
        mode = "LIVE" if (bool(getattr(bot, "live", False)) and (not bool(getattr(bot, "dry", True)))) else "DRY"
    except Exception:
        mode = "DRY"

    sig = ""  # minimalist startup (signature removed)

    grid = Table.grid(expand=True)
    grid.add_column(ratio=1, justify="left")
    grid.add_column(ratio=3, justify="center")
    grid.add_column(ratio=2, justify="right")

    left = Text(datetime.now().strftime("%Y-%m-%d %H:%M:%S"), style="bold white")
    center = Text(sig, style="bold white")
    right = Text.from_markup(f"[bold green]COGNITIVE ENGINE ACTIVE[/bold green]  {ver} | {mode}")

    grid.add_row(left, center, right)
    return Panel(grid, box=box.HEAVY, style="white on black")


def _ppdm_run_v145(self):
    """
    Robust dashboard runner (avoids the old mis-indentation patch).
    """
    from rich.live import Live
    from rich.layout import Layout
    from rich.console import Console
    console = Console()
    layout = Layout()
    layout.split_column(
        Layout(name="header", size=3),
        Layout(name="body", ratio=1),
    )

    layout["body"].split_row(
        Layout(name="wallets", ratio=4),
        Layout(name="reports", ratio=2),
        Layout(name="scanner", ratio=2),
    )

    # wallets layout (W1/W2/W3)
    layout["body"]["wallets"].split_row(
        Layout(name="w1", ratio=1),
        Layout(name="w2", ratio=1),
        Layout(name="w3", ratio=1),
    )
    bot = getattr(self, "bot", None)

    # Dashboard refresh cadence (seconds)
    try:
        refresh_sec = float(os.getenv("DASH_REFRESH_SEC", "1.2") or 1.2)
    except Exception:
        refresh_sec = 1.2
    # Sync dashboard cadence with bot pulse when available to avoid jitter/flicker.
    try:
        _br = float(getattr(bot, "_dash_refresh_sec", 0.0) or 0.0)
        if _br > 0.0:
            refresh_sec = float(_br)
    except Exception:
        pass
    rps = max(1, int(round(1.0 / max(0.2, refresh_sec))))

    # Use full-screen mode only on real TTYs (reduces "jumping" on non-interactive terminals).
    # Termux + some terminals may "jump" in alternate-screen; default to non-screen there.
    try:
        _prefix = str(os.getenv("PREFIX", "") or "")
        _is_termux = bool(os.getenv("TERMUX_VERSION") or os.getenv("TERMUX_APP_PACKAGE_MANAGER") or _prefix.startswith("/data/data/com.termux"))
    except Exception:
        _is_termux = False
    _default_dash_screen = "0" if _is_termux else "1"
    try:
        _dash_screen = str(os.getenv("DASH_SCREEN", _default_dash_screen) or _default_dash_screen).strip().lower() in ("1", "true", "yes", "on")
    except Exception:
        _dash_screen = (not _is_termux)
    try:
        _is_tty = bool(getattr(console, "is_terminal", False))
    except Exception:
        _is_tty = True
    _screen_flag = bool(_dash_screen and _is_tty)

    with Live(layout, console=console, screen=_screen_flag, refresh_per_second=rps) as _ppdash_live:

            while True:
                try:
                    layout["header"].update(self._render_header())
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                try:
                    layout["body"]["wallets"]["w1"].update(self._wallet_panel("W1"))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                try:
                    layout["body"]["wallets"]["w2"].update(self._wallet_panel("W2"))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                try:
                    layout["body"]["wallets"]["w3"].update(self._wallet_panel("W3"))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                try:
                    layout["body"]["reports"].update(self._reports_panel())
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                try:
                    layout["body"]["scanner"].update(self._scanner_panel())
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                try:
                    _ppdash_live.refresh()
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

                time.sleep(max(0.2, refresh_sec))


