# ---- CognitiveCore (v150) ----
class CognitiveCoreLegacy:
    """
    PP150 CognitiveCore:
      - Predictive Analysis: linear regression trend vector on recent prices
      - Experience Memory: self.experience_map keeps per-symbol streaks + 2h cooldown after 3 consecutive losses
      - Dynamic Sizing: Kelly-based sizing scaled by prediction confidence
      - Telemetry: experience-vs-algorithm decision ratios (for dashboard IQ / BRAIN STATUS)
    """

    def __init__(self, bot=None):
        self.bot = bot
        self.experience_map = {}  # sym -> {"wins":int,"losses":int,"streak_loss":int,"blocked_until":float}
        self._lock = threading.RLock()
        self.decisions_total = 0
        self.decisions_experience = 0
        self.decisions_algo = 0
        self._last_confidence = 0.0

    @staticmethod
    def _clamp(x: float, lo: float, hi: float) -> float:
        try:
            v = float(x)
        except Exception:
            v = 0.0
        if not math.isfinite(v):
            v = 0.0
        return max(float(lo), min(float(hi), float(v)))

    def trend_vector(self, prices, window: int = 30) -> dict:
        """
        Returns:
          slope: price units / step
          slope_pct: approx total percent move across window
          r2: coefficient of determination
          confidence: 0..1 (derived from r2 with mild smoothing)
        """
        try:
            ys = [float(x) for x in (prices or []) if _is_finite_number(x)]
        except Exception:
            ys = []
        if len(ys) < 6:
            return {"slope": 0.0, "slope_pct": 0.0, "r2": 0.0, "confidence": 0.0}

        ys = ys[-int(max(6, window)):]
        n = len(ys)
        xs = list(range(n))
        x_mean = (n - 1) / 2.0
        y_mean = sum(ys) / float(n)

        # least squares slope
        num = 0.0
        den = 0.0
        for i, y in enumerate(ys):
            dx = float(i) - float(x_mean)
            num += dx * (float(y) - float(y_mean))
            den += dx * dx
        slope = (num / den) if den > 1e-12 else 0.0
        intercept = float(y_mean) - float(slope) * float(x_mean)

        # r2
        ss_tot = 0.0
        ss_res = 0.0
        for i, y in enumerate(ys):
            y_hat = float(intercept) + float(slope) * float(i)
            ss_tot += (float(y) - float(y_mean)) ** 2
            ss_res += (float(y) - float(y_hat)) ** 2
        r2 = 0.0
        if ss_tot > 1e-12:
            r2 = 1.0 - (ss_res / ss_tot)
        r2 = self._clamp(r2, 0.0, 1.0)

        mu = max(1e-12, abs(float(y_mean)))
        slope_pct = float(slope) * float(n - 1) / mu * 100.0

        # confidence: smooth + conservative
        confidence = self._clamp(0.10 + 0.90 * float(r2), 0.0, 1.0)
        return {"slope": float(slope), "slope_pct": float(slope_pct), "r2": float(r2), "confidence": float(confidence)}

    def note_decision(self, experience: bool) -> None:
        with self._lock:
            self.decisions_total += 1
            if experience:
                self.decisions_experience += 1
            else:
                self.decisions_algo += 1

    def brain_status(self) -> tuple[float, float]:
        with self._lock:
            tot = int(self.decisions_total or 0)
            if tot <= 0:
                return 0.0, 100.0
            exp = float(self.decisions_experience or 0) / float(tot) * 100.0
            exp = self._clamp(exp, 0.0, 100.0)
            return float(exp), float(100.0 - exp)

    def is_blocked(self, symbol: str) -> bool:
        sym = str(symbol or "").strip().upper()
        if not sym:
            return False
        now = _pp920_time.time()
        with self._lock:
            rec = dict(self.experience_map.get(sym) or {})
            until = float(rec.get("blocked_until", 0.0) or 0.0)
            if until > now:
                return True
            # auto-clear if expired
            if until > 0.0 and until <= now:
                rec["blocked_until"] = 0.0
                rec["streak_loss"] = int(rec.get("streak_loss", 0) or 0)
                self.experience_map[sym] = rec
        return False

    def record_symbol_pnl(self, symbol: str, pnl_toman: float) -> None:
        sym = str(symbol or "").strip().upper()
        if not sym:
            return
        now = _pp920_time.time()
        with self._lock:
            rec = dict(self.experience_map.get(sym) or {})
            rec.setdefault("wins", 0)
            rec.setdefault("losses", 0)
            rec.setdefault("streak_loss", 0)
            rec.setdefault("blocked_until", 0.0)

            pnl = float(pnl_toman or 0.0)
            if pnl >= 0.0:
                rec["wins"] = int(rec.get("wins", 0) or 0) + 1
                rec["streak_loss"] = 0
                rec["blocked_until"] = 0.0
            else:
                rec["losses"] = int(rec.get("losses", 0) or 0) + 1
                rec["streak_loss"] = int(rec.get("streak_loss", 0) or 0) + 1
                if int(rec["streak_loss"]) >= 3:
                    rec["blocked_until"] = float(now + 2 * 3600.0)
            self.experience_map[sym] = rec

    def dynamic_sizing(self, cash: float, base_cap: float, confidence: float) -> float:
        """
        Returns adjusted cap_quote based on:
          - Kelly fraction from TradingMemory (or conservative fallback)
          - Prediction confidence (0..1)
          - Available cash
          - Never exceeds base_cap
        """
        try:
            cash_f = max(0.0, float(cash))
        except Exception:
            cash_f = 0.0
        try:
            cap = max(0.0, float(base_cap))
        except Exception:
            cap = 0.0

        conf = self._clamp(confidence, 0.0, 1.0)
        self._last_confidence = float(conf)

        # Kelly from empirical memory (global, conservative)
        kf = 0.02
        try:
            bot = self.bot
            _mem = getattr(bot, "trading_memory", None)
            if _mem is not None:
                kf = float(_mem.kelly_fraction() or 0.02)
        except Exception:
            kf = 0.02

        # Apply confidence scaling (more confident => closer to Kelly cap)
        kf = self._clamp(kf, 0.0, 0.15)
        scale = 0.35 + 0.65 * conf  # 0.35..1.0
        eff_frac = self._clamp(kf * scale, 0.0, 0.15)

        # cash-based ceiling
        cash_ceiling = float(cash_f) * float(eff_frac)
        out = min(float(cap), float(cash_ceiling)) if cash_f > 0.0 else 0.0

        # Safety floor (don't accidentally zero everything on cold-start)
        try:
            floor_frac = float(_os.getenv("PP150_MIN_FRACTION", "0.005") or 0.005)  # 0.5%
        except Exception:
            floor_frac = 0.005
        out = max(0.0, min(float(cap), max(float(out), float(cash_f) * float(floor_frac))))

        # PP705: Micro-step mode (very small buy STEPS)
        bot = getattr(self, 'bot', None)
        app = 1.0
        try:
            app = float(getattr(bot, 'risk_appetite', 1.0) or 1.0)
        except Exception:
            app = 1.0
        app = self._clamp(app, 0.50, 2.00)

        mn = 0.0
        try:
            mn = float(getattr(bot, 'min_notional_irt', 0.0) or 0.0)
        except Exception:
            mn = 0.0

        # Ensure at least one tiny-but-valid order size when risk appetite is raised
        if mn > 0.0 and cash_f > 0.0 and float(app) >= 1.02:
            try:
                mm = float(_os.getenv('PP705_MICRO_STEP_MULT', '1.03') or 1.03)
            except Exception:
                mm = 1.03
            micro_floor = float(mn) * float(mm)
            out = max(float(out), min(float(cash_f), float(micro_floor)))

        # If inflation alert is active, cap per-step spending (keeps trades tiny but active)
        infl_micro = False
        try:
            infl_micro = bool(getattr(bot, '_pp705_inflation_risk', False))
        except Exception:
            infl_micro = False
        if infl_micro and cash_f > 0.0:
            try:
                cap_frac = float(_os.getenv('PP705_MICRO_CAP_FRAC', '0.02') or 0.02)
            except Exception:
                cap_frac = 0.02
            cap_frac = max(0.001, min(float(cap_frac), 0.10))
            micro_cap = float(cash_f) * float(cap_frac)
            if mn > 0.0:
                micro_cap = max(float(micro_cap), min(float(cash_f), float(mn) * 1.01))
            out = min(float(out), min(float(cap), float(micro_cap)))

        out = max(0.0, min(float(cap), float(out)))
        return float(out)


