# ---- Entry fix: prioritize dashboard when stdout is a real TTY ----
def _pp110_entry() -> None:
    """PP150 entrypoint: watchdog stays silent when TTY so Rich TUI can own the screen."""
    # If launched as a watchdog child (subprocess mode), bypass watchdog and run the real bot directly.
    if str(_os.getenv("PP110_WATCHDOG_CHILD", "0") or "0").strip().lower() in ("1","true","yes","on"):
        import sys as _sys
        _sys.argv = _pp110_child_argv()
        try:
            _os.environ.setdefault("PP_VERSION", "v160")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        _pp5_main()
        return

    _pp110_apply_termux_defaults()

    # Pull manual tokens (if pasted in header) into env so child inherits them.
    _pp_apply_manual_tokens()
    try:
        _maybe_set_env_from_walletstore()
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    ok, missing = _pp110_tokens_present()
    if not ok:
        raise RuntimeError(f"Missing ArzPlus tokens for LIVE: {missing}. Paste them at top of file or set env ARZPLUS_WALLET_1_TOKEN/2/3.")

    # Ensure the 'arming' flag is present (user wanted fully real trading).
    _os.environ.setdefault("ARZPLUS_LIVE_ARMED", "YES")
    _os.environ.setdefault("PP_VERSION", "v160")

    # If stdout is a real TTY, prefer full-screen TUI and keep watchdog silent.
    try:
        import sys as _sys
        if hasattr(_sys.stdout, "isatty") and bool(_sys.stdout.isatty()):
            _os.environ.setdefault("PP110_WATCHDOG_SILENT", "1")
            _os.environ.setdefault("PP110_DISABLE_WATCHDOG", "1")
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # Run watchdog unless user explicitly disables it.
    if str(_os.getenv("PP110_DISABLE_WATCHDOG", "0") or "0").strip().lower() in ("1","true","yes","on"):
        import sys as _sys
        _sys.argv = _pp110_child_argv()
        _pp5_main()
        return

    if str(_os.getenv("PP110_USE_SUBPROCESS", "1") or "1").strip().lower() in ("1","true","yes","on"):
        _pp110_watchdog_subprocess()
    else:
        _pp110_watchdog()


# ============================================================
# PP170: Deep Heritage Recovery + USDT-First Intelligence
#   - Non-Interference: does NOT modify ArzPlus API call methods.
#   - Revives legacy StrategyDNA + NLP detector + orphan strategies
#   - Adds Anti-Inflation pre-buy gate for legacy-driven buys
#   - Adds Integrity Self-Test (silent-disable on conflicts)
# ============================================================

try:
    import inspect as _pp170_inspect
    import ast as _pp170_ast
    import random as _pp170_random
    from dataclasses import dataclass as _pp170_dataclass, field as _pp170_field
except Exception:  # pragma: no cover
    _pp170_inspect = None
    _pp170_ast = None
    _pp170_random = None
    _pp170_dataclass = None
    _pp170_field = None

def _pp170__read_source() -> str:
    try:
        p = __file__
        with open(p, "r", encoding="utf-8", errors="ignore") as f:
            return f.read()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return ""

def _pp170__discover_legacy_orphans(max_ver: int = 110):
    # Heuristic orphan scanner for pre-v110 legacy defs.
    src = _pp170__read_source()
    if not src:
        return []
    out = []
    try:
        for m in re.finditer(r'^\\s*def\\s+([A-Za-z_][A-Za-z0-9_]*)\\s*\\(', src, re.M):
            name = m.group(1)
            v = None
            mm = _pp920_re.match(r'^_pp(\\d+)_', name)
            if mm:
                try:
                    v = int(mm.group(1))
                except Exception:
                    v = None
            if v is None:
                try:
                    ctx = src[max(0, m.start() - 800):m.start()]
                    mpp = re.findall(r'PP(\d{1,3})', ctx)
                    if mpp:
                        v = int(mpp[-1])
                except Exception:
                    v = None
            if v is None or v >= int(max_ver):
                continue
            # Count call sites (exclude the def itself)
            try:
                call_pat = re.compile(r'(?<!def\\s)\\b' + re.escape(name) + r'\\s*\\(', re.M)
                calls = len(call_pat.findall(src))
            except Exception:
                calls = 1
            if calls <= 0:
                out.append(str(name))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return []
    try:
        return sorted(list(dict.fromkeys(out)))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return out

def _pp170__legacy_keyword(name: str) -> bool:
    try:
        s = str(name or "").lower()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False
    keys = (
        "arb", "arbitr", "cointegr", "pairs", "spread", "zscore", "meanrev", "revert",
        "kalman", "denoise", "noise", "filter", "hurst", "entropy", "stationary",
        "garch", "volatility", "stat", "regress", "bayes",
    )
    return any(k in s for k in keys)

def _pp170__safe_call(fn, *, bot=None, sym=None, symst=None, bid=None, ask=None, mid=None, depth_data=None):
    # Call legacy functions safely with best-effort signature matching.
    if fn is None:
        raise RuntimeError("legacy_fn_none")
    sig = None
    if _pp170_inspect is not None:
        try:
            sig = _pp170_inspect.signature(fn)
        except Exception:
            sig = None
    kwargs = {}
    if sig is not None:
        for p in sig.parameters.values():
            nm = str(p.name)
            if nm in ("self", "bot"):
                kwargs[nm] = bot
            elif nm in ("symbol", "sym"):
                kwargs[nm] = sym
            elif nm in ("state", "symst", "st"):
                kwargs[nm] = symst
            elif nm in ("bid", "best_bid"):
                kwargs[nm] = bid
            elif nm in ("ask", "best_ask"):
                kwargs[nm] = ask
            elif nm in ("mid", "price", "last_price"):
                kwargs[nm] = mid
            elif nm in ("depth", "depth_data", "orderbook"):
                kwargs[nm] = depth_data
            elif nm in ("prices", "history", "series"):
                try:
                    kwargs[nm] = list(getattr(symst, "prices", []) or [])
                except Exception:
                    kwargs[nm] = []
    try:
        return fn(**kwargs) if kwargs else fn()
    except TypeError:
        try:
            return fn(sym, symst, mid)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return fn()

if _pp170_dataclass is not None:
    @_pp170_dataclass
    class StrategyDNA:
        # Strategy DNA: revived for PP170.
        genes: dict = _pp170_field(default_factory=dict)
        generation: int = 0
        fitness: float = 0.0

        @staticmethod
        def random(seed: int = None):
            if _pp170_random is None:
                raise RuntimeError("random_unavailable")
            if seed is not None:
                try:
                    _pp170_random.seed(int(seed))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

            g = {
                "entry_aggression": float(_pp170_random.uniform(0.6, 1.4)),
                "exit_aggression": float(_pp170_random.uniform(0.6, 1.4)),
                "noise_sensitivity": float(_pp170_random.uniform(0.4, 1.6)),
                "pump_bias": float(_pp170_random.uniform(-1.0, 1.0)),
            }
            return StrategyDNA(genes=g, generation=0, fitness=0.0)

        def mutate(self, rate: float = 0.20):
            if _pp170_random is None:
                return self
            g = dict(self.genes or {})
            for k in list(g.keys()):
                try:
                    if float(_pp170_random.random()) < float(rate):
                        g[k] = float(g[k]) * float(_pp170_random.uniform(0.85, 1.15))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

            self.genes = g
            try:
                self.generation = int(self.generation) + 1
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            return self

        def crossover(self, other: "StrategyDNA"):
            if _pp170_random is None:
                return self
            og = dict(getattr(other, "genes", {}) or {})
            g = dict(self.genes or {})
            for k in set(list(g.keys()) + list(og.keys())):
                try:
                    if float(_pp170_random.random()) < 0.5:
                        g[k] = og.get(k, g.get(k))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

            return StrategyDNA(genes=g, generation=max(int(self.generation), int(getattr(other, "generation", 0) or 0)) + 1, fitness=0.0)
else:
    class StrategyDNA:  # pragma: no cover
        def __init__(self, genes=None, generation=0, fitness=0.0):
            self.genes = dict(genes or {})
            self.generation = int(generation or 0)
            self.fitness = float(fitness or 0.0)

class _PP170NLPDetector:
    def __init__(self):
        self.active = True
        self.last_score = 0.0
        self._pos = set(["bull","bullish","pump","breakout","surge","rally","uptrend","adoption","growth","approval","support","moon",
                         "صعود","افزایش","جهش","شکست","رالی","تقویت","حمایت","پامپ"])
        self._neg = set(["bear","bearish","dump","crash","selloff","downtrend","lawsuit","hack","exploit","ban","rejection","resistance",
                         "نزول","کاهش","ریزش","دامپ","تحریم","هک","مقاومت","رد"])

    def analyze(self, texts):
        if not self.active:
            self.last_score = 0.0
            return 0.0
        try:
            arr = [str(x) for x in (texts or []) if x is not None]
        except Exception:
            arr = []
        if not arr:
            self.last_score = 0.0
            return 0.0
        pos = 0
        neg = 0
        for t in arr[:50]:
            low = t.lower()
            for w in self._pos:
                if w in low:
                    pos += 1
            for w in self._neg:
                if w in low:
                    neg += 1
        denom = max(1, pos + neg)
        score = float(pos - neg) / float(denom)
        score = max(-1.0, min(1.0, float(score)))
        self.last_score = float(score)
        return float(score)

class _PP170GeneticEvolution:
    def __init__(self, pop_size: int = 10):
        self.enabled = True
        self.running = False
        self.pop_size = int(pop_size or 10)
        self.population = []
        self.best = None
        self._init_population()

    def _init_population(self):
        try:
            self.population = [StrategyDNA.random() for _ in range(max(2, int(self.pop_size)))]
            self.best = self.population[0] if self.population else None
        except Exception:
            self.population = []
            self.best = None

    def start(self):
        self.running = True

    def stop(self):
        self.running = False

    def update_fitness(self, pnl_toman: float = 0.0):
        if not self.enabled:
            return
        try:
            pnl = float(pnl_toman or 0.0)
        except Exception:
            pnl = 0.0
        if self.best is None and self.population:
            self.best = self.population[0]
        if self.best is None:
            return
        try:
            self.best.fitness = float(self.best.fitness or 0.0) + (1.0 if pnl > 0 else (-1.0 if pnl < 0 else 0.0))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            if _pp170_random is not None and float(_pp170_random.random()) < 0.15:
                self.best = self.best.mutate(0.25)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def suggest_delta(self):
        if not (self.enabled and self.running and self.best is not None):
            return 0.0
        try:
            g = dict(getattr(self.best, "genes", {}) or {})
            e = float(g.get("entry_aggression", 1.0) or 1.0)
            n = float(g.get("noise_sensitivity", 1.0) or 1.0)
            p = float(g.get("pump_bias", 0.0) or 0.0)
            delta = 0.12 * (e - 1.0) - 0.06 * (n - 1.0) + 0.04 * p
            return float(max(-0.25, min(0.25, delta)))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

def _pp170__convert_excess_irt_to_usdt(bot, api, *, wallet_name: str, keep_irt: float = 0.0, min_convert_irt: float = 50000.0) -> bool:
    try:
        if not bot or not api:
            return False
        if str(getattr(bot, "quote", "IRT") or "IRT").upper() != "IRT":
            return True
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

    try:
        oo = bot._open_orders_count(api, "USDTIRT")
        if oo is not None and int(oo) > 0:
            return True
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        b = bot._balances(api)
        irt_free = float((b or {}).get("IRT", 0.0) or 0.0)
    except Exception:
        irt_free = 0.0

    try:
        reserve = float(os.getenv("USDT_SANCTUARY_RESERVE_IRT", "20000") or 20000.0)
    except Exception:
        reserve = 20000.0

    try:
        keep_total = float(keep_irt or 0.0) + float(reserve)
    except Exception:
        keep_total = float(reserve)

    spend_irt = max(0.0, float(irt_free) - float(keep_total))
    if spend_irt <= float(min_convert_irt):
        return True

    try:
        dp = api.depth("USDTIRT")
        depth = (dp or {}).get("data") or {}
        _bid, _ask, _mid = _book_top(depth)
        px_raw = float(_ask or _mid or 0.0)
    except Exception:
        px_raw = 0.0

    if px_raw <= 0.0:
        try:
            px_raw = float(getattr(bot, "_dash_usdt_rate", 0.0) or 0.0)
        except Exception:
            px_raw = 0.0
    if px_raw <= 0.0:
        return False

    try:
        meta = bot._symbol_meta("USDTIRT")
    except Exception:
        meta = {}

    qty_raw = float(spend_irt) / float(px_raw) if float(px_raw) > 0 else 0.0
    try:
        price = bot._round_price_limit("USDTIRT", float(px_raw), meta, side="buy")
        qty = bot._round_amount_step(float(qty_raw), meta)
    except Exception:
        price = float(px_raw)
        qty = float(qty_raw)

    if qty <= 0.0 or price <= 0.0:
        return False

    try:
        res = bot._place_buy(api, str(wallet_name), "USDTIRT", float(qty), float(price))
        return bool(res and res.get("ok"))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

class LegacyIntelligenceManager:
    def __init__(self, bot):
        self.bot = bot
        self.disabled = set()
        self.last_contrib = []
        self.orphans = []
        self.nlp = _PP170NLPDetector()
        self.genetic = _PP170GeneticEvolution(pop_size=int(os.getenv("PP170_GEN_POP", "10") or 10))
        try:
            self.genetic.start()
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            self.orphans = list(_pp170__discover_legacy_orphans(110) or [])
        except Exception:
            self.orphans = []

        self.legacy_funcs = []
        try:
            for nm in (self.orphans or []):
                if not _pp170__legacy_keyword(nm):
                    continue
                fn = globals().get(nm)
                if callable(fn):
                    self.legacy_funcs.append(fn)
        except Exception:
            self.legacy_funcs = []

    def status_items(self):
        items = []
        try:
            items.append(("NLP-Detector: ACTIVE", "YES" if bool(getattr(self.nlp, "active", False)) else "NO"))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            items.append(("Genetic-Evolution: RUNNING", "YES" if bool(getattr(self.genetic, "running", False)) else "NO"))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            items.append(("Legacy-Orphans: ACTIVE", f"{len(self.legacy_funcs)} / SILENCED {len(self.disabled)}"))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            gate = "ON" if str(os.getenv("PP170_USDT_FIRST", "1") or "1").strip().lower() in ("1","true","yes","on") else "OFF"
            items.append(("USDT-First Gate", gate))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return items

    def integrity_selftest(self):
        bot = self.bot
        try:
            _orig_buy = getattr(bot, "_place_buy", None)
            _orig_sell = getattr(bot, "_place_sell", None)
        except Exception:
            _orig_buy = None
            _orig_sell = None

        def _guard(*a, **k):
            raise RuntimeError("API_INTERFERENCE: order attempted during PP170 selftest")

        try:
            if callable(_orig_buy):
                setattr(bot, "_place_buy", _guard)
            if callable(_orig_sell):
                setattr(bot, "_place_sell", _guard)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            _ = self.nlp.analyze(["BTC pumps on ETF approval", "ریزش بازار پس از خبر منفی"])
        except Exception:
            try:
                self.nlp.active = False
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        try:
            _ = float(self.genetic.suggest_delta() or 0.0)
        except Exception:
            try:
                self.genetic.enabled = False
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        dummy_depth = {"bids": [[100, 1]], "asks": [[101, 1]]}
        for fn in list(self.legacy_funcs or []):
            nm = str(getattr(fn, "__name__", "legacy_fn"))
            try:
                _ = _pp170__safe_call(fn, bot=bot, sym="BTCIRT", symst=None, bid=100.0, ask=101.0, mid=100.5, depth_data=dummy_depth)
            except Exception:
                self.disabled.add(nm)

        try:
            if callable(_orig_buy):
                setattr(bot, "_place_buy", _orig_buy)
            if callable(_orig_sell):
                setattr(bot, "_place_sell", _orig_sell)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def evaluate(self, sym: str, symst, bid: float, ask: float, mid: float, depth_data):
        delta = 0.0
        contrib = []

        try:
            texts = []
            try:
                texts = list(getattr(self.bot, "_news_headlines", []) or [])
            except Exception:
                texts = []
            s = float(self.nlp.analyze(texts) or 0.0)
            if abs(s) > 0.01:
                delta += 0.18 * s
                contrib.append(("NLP", f"{s:+.2f}"))
                try:
                    _cc = getattr(self.bot, "cognitive_core", None)
                    if _cc is not None:
                        setattr(_cc, "last_nlp_score", float(s))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            g = float(self.genetic.suggest_delta() or 0.0)
            if abs(g) > 0.0001:
                delta += float(g)
                contrib.append(("GEN", f"{g:+.3f}"))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        for fn in (self.legacy_funcs or []):
            nm = str(getattr(fn, "__name__", "legacy"))
            if nm in self.disabled:
                continue
            try:
                out = _pp170__safe_call(fn, bot=self.bot, sym=sym, symst=symst, bid=bid, ask=ask, mid=mid, depth_data=depth_data)
                if isinstance(out, (int, float)):
                    delta += 0.07 * float(out)
                    contrib.append((nm, f"{float(out):+.2f}"))
                elif isinstance(out, dict):
                    sig = str(out.get("signal", "") or "").upper().strip()
                    if sig == "BUY":
                        delta += 0.30
                        contrib.append((nm, "BUY"))
                    elif sig == "SELL":
                        delta -= 0.30
                        contrib.append((nm, "SELL"))
                    elif "score" in out:
                        try:
                            vv = float(out.get("score") or 0.0)
                            delta += 0.07 * vv
                            contrib.append((nm, f"{vv:+.2f}"))
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e)

                elif isinstance(out, (tuple, list)) and out:
                    if isinstance(out[0], str):
                        sig = str(out[0] or "").upper().strip()
                        if sig == "BUY":
                            delta += 0.30
                            contrib.append((nm, "BUY"))
                        elif sig == "SELL":
                            delta -= 0.30
                            contrib.append((nm, "SELL"))
                    elif isinstance(out[0], (int, float)):
                        vv = float(out[0])
                        delta += 0.07 * vv
                        contrib.append((nm, f"{vv:+.2f}"))
            except Exception:
                self.disabled.add(nm)

        try:
            delta = max(-0.75, min(0.75, float(delta)))
        except Exception:
            delta = 0.0
        self.last_contrib = list(contrib or [])
        return float(delta), self.last_contrib

    def anti_inflation_confirm(self, api, wallet_name: str, required_irt: float = 0.0) -> bool:
        try:
            gate = str(os.getenv("PP170_USDT_FIRST", "1") or "1").strip().lower() in ("1","true","yes","on")
            if not gate:
                return True
        except Exception:
            gate = True
        try:
            dd = bool(getattr(self.bot, "_dollar_defense", False))
        except Exception:
            dd = False
        if not dd:
            return False
        try:
            ok = _pp170__convert_excess_irt_to_usdt(self.bot, api, wallet_name=str(wallet_name), keep_irt=float(required_irt or 0.0))
            return bool(ok)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False

