try:
    from collections import deque as _pp175_deque
except Exception:
    _pp175_deque = None

def calculate_net_profit_margin(
    *,
    notional_irt: float,
    expected_profit_pct: float,
    buy_fee_rate: float | None = None,
    sell_fee_rate: float | None = None,
    include_hidden_fee: bool | None = None,
) -> dict:
    """
    PP175 Dynamic Fee Guard.

    Computes fee-aware net profit margin for a round-trip:
      - BUY notional: N
      - SELL notional: N * (1 + expected_profit_pct)
      - Fees modeled as percentage of notional + optional hidden fixed fee (IRT).

    Returns dict with:
      - gross_profit_pct
      - total_fee_pct
      - net_profit_pct
      - profit_to_fee (gross / fee)
      - net_to_fee    (net / fee)
    """
    try:
        N = max(0.0, float(notional_irt or 0.0))
    except Exception:
        N = 0.0
    try:
        g = max(0.0, float(expected_profit_pct or 0.0))
    except Exception:
        g = 0.0

    # Pull default fee rates from existing config constants (do not modify)
    try:
        bfr = float(BUY_FEE_RATE) if buy_fee_rate is None else float(buy_fee_rate)
    except Exception:
        bfr = 0.0
    try:
        sfr = float(SELL_FEE_RATE) if sell_fee_rate is None else float(sell_fee_rate)
    except Exception:
        try:
            sfr = float(FEE_RATE)
        except Exception:
            sfr = 0.0

    # Include hidden fixed fee (modeled in IRT), best-effort
    if include_hidden_fee is None:
        include_hidden_fee = str(os.getenv("PP175_INCLUDE_HIDDEN_FEE", "1") or "1").strip().lower() in ("1", "true", "yes", "on")

    fee_pct = 0.0
    try:
        # Percent fees relative to BUY notional (conservative)
        fee_pct = float(bfr) + float(sfr) * (1.0 + float(g))
    except Exception:
        fee_pct = 0.0

    hidden_pct = 0.0
    if include_hidden_fee and N > 0.0:
        try:
            # Use existing hidden fee knobs if present
            hf = float(globals().get("ARZPLUS_HIDDEN_FEE_IRT", 0.0) or 0.0)
        except Exception:
            hf = 0.0
        try:
            if hf > 0.0:
                if globals().get("_arzplus_hidden_fee_applies", None) is not None:
                    try:
                        if _arzplus_hidden_fee_applies("buy"):
                            hidden_pct += hf / N
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    try:
                        if _arzplus_hidden_fee_applies("sell"):
                            hidden_pct += hf / N
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                else:
                    # fallback: assume applies to sell
                    hidden_pct += hf / N
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    total_fee_pct = max(0.0, float(fee_pct) + float(hidden_pct))
    net_profit_pct = max(-1.0, float(g) - float(total_fee_pct))

    # Efficiency ratios
    if total_fee_pct > 0.0:
        profit_to_fee = float(g) / float(total_fee_pct)
        net_to_fee = float(net_profit_pct) / float(total_fee_pct)
    else:
        profit_to_fee = float("inf")
        net_to_fee = float("inf")

    return {
        "gross_profit_pct": float(g),
        "total_fee_pct": float(total_fee_pct),
        "net_profit_pct": float(net_profit_pct),
        "profit_to_fee": float(profit_to_fee),
        "net_to_fee": float(net_to_fee),
    }

# ---- Weighted Consensus Engine (CognitiveCore extension) ----
try:
    _pp175__orig_cc_init = CognitiveCore.__init__

    def _pp175_cc_init(self, bot=None):
        _pp175__orig_cc_init(self, bot)
        try:
            self.weights = {
                "modern": float(os.getenv("PP175_WEIGHT_MODERN", "0.7") or 0.7),
                "legacy": float(os.getenv("PP175_WEIGHT_LEGACY", "0.3") or 0.3),
            }
        except Exception:
            self.weights = {"modern": 0.7, "legacy": 0.3}
        try:
            self.consensus_threshold = float(os.getenv("PP175_CONSENSUS_THR", "0.7") or 0.7)
        except Exception:
            self.consensus_threshold = 0.7
        try:
            self.last_consensus = {"dir": "HOLD", "buy_w": 0.0, "sell_w": 0.0}
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    CognitiveCore.__init__ = _pp175_cc_init

    def _pp175_weighted_consensus(self, modern_vote: str, legacy_vote: str):
        mv = str(modern_vote or "HOLD").upper()
        lv = str(legacy_vote or "HOLD").upper()
        w = dict(getattr(self, "weights", {}) or {})
        try:
            w_mod = float(w.get("modern", 0.7) or 0.7)
        except Exception:
            w_mod = 0.7
        try:
            w_leg = float(w.get("legacy", 0.3) or 0.3)
        except Exception:
            w_leg = 0.3
        thr = float(getattr(self, "consensus_threshold", 0.7) or 0.7)

        buy_w = 0.0
        sell_w = 0.0
        if mv == "BUY":
            buy_w += w_mod
        elif mv == "SELL":
            sell_w += w_mod
        if lv == "BUY":
            buy_w += w_leg
        elif lv == "SELL":
            sell_w += w_leg

        if buy_w >= thr and buy_w > sell_w:
            out = "BUY"
        elif sell_w >= thr and sell_w > buy_w:
            out = "SELL"
        else:
            out = "HOLD"

        try:
            self.last_consensus = {"dir": out, "buy_w": float(buy_w), "sell_w": float(sell_w), "mv": mv, "lv": lv}
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return out, float(buy_w), float(sell_w)

    CognitiveCore.weighted_consensus = _pp175_weighted_consensus
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

# ---- Consensus application: annotate sym-state at score-postprocess stage ----
try:
    _pp175__orig_postprocess = _pp5_postprocess_score

    def _pp5_postprocess_score(self, sym, symst, bid, ask, mid, depth_data, score):
        s2 = float(_pp175__orig_postprocess(self, sym, symst, bid, ask, mid, depth_data, score))
        try:
            # legacy delta is stored by PP170 wrapper (best-effort)
            d = float(getattr(symst, "legacy_delta", 0.0) or 0.0)
        except Exception:
            d = 0.0
        modern_score = float(s2) - float(d)
        legacy_score = float(d)

        # votes from each layer (BUY/SELL/HOLD) using base thresholds
        try:
            buy_thr_ref = float(getattr(self, "buy_thr", 0.0) or 0.0)
        except Exception:
            buy_thr_ref = 0.0
        try:
            sell_thr_ref = float(getattr(self, "sell_thr", 0.0) or 0.0)
        except Exception:
            sell_thr_ref = 0.0

        # fallback thresholds if missing
        if buy_thr_ref <= 0.0:
            buy_thr_ref = float(os.getenv("PP175_FALLBACK_BUY_THR", "0.55") or 0.55)
        if sell_thr_ref <= 0.0:
            sell_thr_ref = float(os.getenv("PP175_FALLBACK_SELL_THR", "0.55") or 0.55)

        # legacy vote threshold as a fraction of buy threshold (configurable)
        try:
            leg_thr = float(os.getenv("PP175_LEGACY_VOTE_THR", "") or 0.0)
        except Exception:
            leg_thr = 0.0
        if leg_thr <= 0.0:
            leg_thr = max(0.08, 0.30 * float(buy_thr_ref))

        def _vote(x: float, thr: float) -> str:
            try:
                if float(x) >= float(thr):
                    return "BUY"
                if float(x) <= -float(thr):
                    return "SELL"
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return "HOLD"
            return "HOLD"

        mv = _vote(modern_score, buy_thr_ref)
        lv = _vote(legacy_score, leg_thr)

        # consensus via CognitiveCore when available
        cd = "HOLD"
        buy_w = 0.0
        sell_w = 0.0
        try:
            _cc = getattr(self, "cognitive_core", None)
            if _cc is not None and hasattr(_cc, "weighted_consensus"):
                cd, buy_w, sell_w = _cc.weighted_consensus(mv, lv)
            else:
                # local fallback (same math)
                w_mod = float(os.getenv("PP175_WEIGHT_MODERN", "0.7") or 0.7)
                w_leg = float(os.getenv("PP175_WEIGHT_LEGACY", "0.3") or 0.3)
                thr = float(os.getenv("PP175_CONSENSUS_THR", "0.7") or 0.7)
                if mv == "BUY":
                    buy_w += w_mod
                elif mv == "SELL":
                    sell_w += w_mod
                if lv == "BUY":
                    buy_w += w_leg
                elif lv == "SELL":
                    sell_w += w_leg
                if buy_w >= thr and buy_w > sell_w:
                    cd = "BUY"
                elif sell_w >= thr and sell_w > buy_w:
                    cd = "SELL"
                else:
                    cd = "HOLD"
        except Exception:
            cd = "HOLD"

        # Fortress: fault-storm veto (too many swallowed exceptions in a short window)
        try:
            ring = list(globals().get("_pp200_heal_ring", []) or [])
            now = float(_pp920_time.time())
            win = float(os.getenv("PP175_FAULT_WINDOW_SEC", "30") or 30.0)
            thr_f = int(os.getenv("PP175_FAULT_STORM", "12") or 12)
            faults = 0
            for _t, *_rest in ring:
                try:
                    if (now - float(_t)) <= win:
                        faults += 1
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_continue")
                    continue
            if faults >= thr_f:
                cd = "HOLD"
                buy_w = 0.0
                sell_w = 0.0
                try:
                    symst.pp175_fault_storm = int(faults)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            symst.pp175_modern_score = float(modern_score)
            symst.pp175_legacy_score = float(legacy_score)
            symst.pp175_votes = {"modern": mv, "legacy": lv}
            symst.pp175_consensus_dir = str(cd)
            symst.pp175_consensus_w = {"buy": float(buy_w), "sell": float(sell_w)}
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return float(s2)

except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

# ---- Enforce consensus at signal emission stage (prevents logical lock/whipsaw) ----
try:
    _pp175__orig_update_streak = _pp110_update_signal_streak

    def _pp110_update_signal_streak(symst: Any, score: float, buy_thr: float, sell_thr: float) -> Tuple[str, int]:
        # If score would trigger BUY/SELL but consensus doesn't agree, neutralize.
        try:
            cd = str(getattr(symst, "pp175_consensus_dir", "") or "").upper().strip()
        except Exception:
            cd = ""
        try:
            sc = float(score or 0.0)
        except Exception:
            sc = 0.0
        try:
            bt = float(buy_thr or 0.0)
        except Exception:
            bt = 0.0
        try:
            st = float(sell_thr or 0.0)
        except Exception:
            st = 0.0

        try:
            would_buy = (bt > 0.0 and sc >= bt)
            would_sell = (st > 0.0 and sc <= -st)
        except Exception:
            would_buy = False
            would_sell = False

        if (would_buy and cd != "BUY") or (would_sell and cd != "SELL"):
            # Force HOLD while keeping streak logic stable via original function
            sc = 0.0

        return _pp175__orig_update_streak(symst, sc, buy_thr, sell_thr)

except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

# ---- Circuit Breaker + Fee Guard injection into bot order placement ----
try:
    _pp175__orig_pp5_init = PP5LiveTripleWallet.__init__

    def _pp175_pp5_init(self, *a, **kw):
        _pp175__orig_pp5_init(self, *a, **kw)
        try:
            if _pp175_deque is not None:
                self._pp175_order_events = _pp175_deque(maxlen=32)  # (ts, side)
                self._pp175_contradictions = _pp175_deque(maxlen=64)  # ts only
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            self._pp175_waitwatch_until = 0.0
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            self._pp175_net_eff = None
            self._pp175_net_eff_ema = None
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    PP5LiveTripleWallet.__init__ = _pp175_pp5_init
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

def _pp175_now() -> float:
    try:
        return float(_pp920_time.time())
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

def _pp175_record_order_event(bot: Any, side: str) -> None:
    try:
        if _pp175_deque is None:
            return
        now = _pp175_now()
        s = str(side or "").upper().strip()
        if not hasattr(bot, "_pp175_order_events") or bot._pp175_order_events is None:
            bot._pp175_order_events = _pp175_deque(maxlen=32)
        if not hasattr(bot, "_pp175_contradictions") or bot._pp175_contradictions is None:
            bot._pp175_contradictions = _pp175_deque(maxlen=64)

        # contradiction detection
        win = float(os.getenv("PP175_CONTRADICT_WINDOW_SEC", "90") or 90.0)
        if bot._pp175_order_events:
            last_ts, last_side = bot._pp175_order_events[-1]
            try:
                if str(last_side).upper().strip() != s and (now - float(last_ts)) <= win:
                    bot._pp175_contradictions.append(now)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        bot._pp175_order_events.append((now, s))

        # prune contradictions over 15 minutes
        horizon = float(os.getenv("PP175_CONTRADICT_HORIZON_SEC", "900") or 900.0)
        try:
            while bot._pp175_contradictions and (now - float(bot._pp175_contradictions[0])) > horizon:
                bot._pp175_contradictions.popleft()
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # trigger circuit breaker: > 5 contradictions in 15 minutes -> 3 minutes wait&watch
        try:
            limit = int(os.getenv("PP175_CONTRADICT_LIMIT", "5") or 5)
        except Exception:
            limit = 5
        try:
            if len(bot._pp175_contradictions) > int(limit):
                cool = float(os.getenv("PP175_WAITWATCH_SEC", "180") or 180.0)
                bot._pp175_waitwatch_until = max(float(getattr(bot, "_pp175_waitwatch_until", 0.0) or 0.0), now + cool)
                try:
                    if hasattr(bot, "_events"):
                        bot._events.append(f"PP175 CIRCUIT BREAKER: Wait&Watch for {int(cool)}s (contradictions={len(bot._pp175_contradictions)})")
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

def _pp175_waitwatch_active(bot: Any) -> bool:
    try:
        until = float(getattr(bot, "_pp175_waitwatch_until", 0.0) or 0.0)
    except Exception:
        until = 0.0
    return until > _pp175_now()

def _pp175_expected_profit_pct(bot: Any) -> float:
    # Prefer existing config/attrs if present, else env fallback
    cands = []
    try:
        cands.append(getattr(bot, "take_profit_pct", None))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        _risk = getattr(bot, "risk", None)
        if _risk is not None:
            cands.append(getattr(_risk, "take_profit_pct", None))
            cands.append(getattr(_risk, "base_tp_pct", None))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # env fallbacks
    for k in ("TARGET_PROFIT_PCT", "TAKE_PROFIT_PCT", "PP175_EXPECTED_PROFIT_PCT"):
        try:
            v = os.getenv(k, "")
            if v is not None and str(v).strip() != "":
                cands.append(v)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    for v in cands:
        try:
            f = float(v)
            if f > 0:
                return float(f)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_continue")
            continue
    return 0.022  # conservative default

def _pp175_notional_usdt(bot: Any, sym: str, qty: float, price: float) -> float:
    s = str(sym or "").upper().strip()
    try:
        q = float(qty or 0.0)
    except Exception:
        q = 0.0
    try:
        p = float(price or 0.0)
    except Exception:
        p = 0.0
    if q <= 0 or p <= 0:
        return 0.0
    # USDTIRT: qty is already USDT
    try:
        if s == str(globals().get("USDT_SYMBOL", "USDTIRT")).upper().strip() or s == "USDTIRT":
            return float(q)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # Otherwise estimate via last_usdt_rate
    try:
        rate = float(getattr(bot, "last_usdt_rate", 0.0) or 0.0)
    except Exception:
        rate = 0.0
    if rate <= 0:
        # fallback: best-effort from bot cache
        try:
            rate = float(getattr(bot, "_last_usdt_rate", 0.0) or 0.0)
        except Exception:
            rate = 0.0
    if rate <= 0:
        return 0.0
    try:
        notional_irt = float(q) * float(p)
        return float(notional_irt) / float(rate) if rate > 0 else 0.0
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

# Wrap _place_buy/_place_sell to add Dynamic Fee Guard + Circuit Breaker
try:
    _pp175__orig_place_buy = PP5LiveTripleWallet._place_buy
    _pp175__orig_place_sell = PP5LiveTripleWallet._place_sell

    def _pp175_place_buy(self, api: ArzPlusAPI, wname: str, sym: str, qty: float, price: float):
        # Circuit breaker: Wait&Watch blocks BUYs by default
        try:
            if _pp175_waitwatch_active(self):
                return {"ok": False, "status": 0, "error": "WAIT_WATCH", "text": "PP175: circuit breaker active; BUY paused"}
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # Fee guard: skip for USDT hedge conversions (USDTIRT)
        try:
            s = str(sym or "").upper().strip()
            if s == str(globals().get("USDT_SYMBOL", "USDTIRT")).upper().strip() or s == "USDTIRT":
                return _pp175__orig_place_buy(self, api, wname, sym, qty, price)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # Compute net-efficiency for small trades
        try:
            notional_irt = float(qty) * float(price)
        except Exception:
            notional_irt = 0.0
        try:
            n_usdt = float(_pp175_notional_usdt(self, sym, qty, price) or 0.0)
        except Exception:
            n_usdt = 0.0

        exp_pct = float(_pp175_expected_profit_pct(self) or 0.0)
        m = calculate_net_profit_margin(notional_irt=float(notional_irt), expected_profit_pct=float(exp_pct))

        # Update NET_EFF indicator (ema)
        try:
            ne = float(m.get("net_to_fee", 0.0))
            self._pp175_net_eff = ne
            a = float(os.getenv("PP175_NETEFF_EMA_ALPHA", "0.20") or 0.20)
            prev = getattr(self, "_pp175_net_eff_ema", None)
            if prev is None or (isinstance(prev, float) and (math.isinf(prev) or math.isnan(prev))):
                self._pp175_net_eff_ema = ne
            else:
                self._pp175_net_eff_ema = float(prev) + a * (ne - float(prev))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # Entry Threshold: for <100 USDT, require expectancy >= 2.5x fees
        try:
            dust_thr = float(os.getenv("PP175_DUST_USDT_THR", "100") or 100.0)
        except Exception:
            dust_thr = 100.0
        try:
            mult = float(os.getenv("PP175_EXPECTANCY_FEE_MULT", "2.5") or 2.5)
        except Exception:
            mult = 2.5

        try:
            fee_pct = float(m.get("total_fee_pct", 0.0) or 0.0)
            ratio = float(m.get("profit_to_fee", 0.0) or 0.0)
            netp = float(m.get("net_profit_pct", 0.0) or 0.0)
        except Exception:
            fee_pct = 0.0
            ratio = 0.0
            netp = 0.0

        # Optional: block negative-net entries (on by default)
        try:
            block_neg = str(os.getenv("PP175_BLOCK_NEG_NET", "1") or "1").strip().lower() in ("1","true","yes","on")
        except Exception:
            block_neg = True

        if block_neg and fee_pct > 0.0 and netp <= 0.0:
            return {"ok": False, "status": 0, "error": "FEE_GUARD_NETNEG", "text": f"PP175: net profit <=0 after fees (fee_pct={fee_pct:.4f})"}

        if n_usdt > 0.0 and n_usdt < dust_thr and fee_pct > 0.0:
            if ratio < mult:
                return {
                    "ok": False,
                    "status": 0,
                    "error": "FEE_GUARD_DUST",
                    "text": f"PP175: dust trade blocked (<{dust_thr:.0f} USDT) expectancy/fees={ratio:.2f}x < {mult:.2f}x (fee_pct={fee_pct:.4f})",
                }

        res = _pp175__orig_place_buy(self, api, wname, sym, qty, price)
        try:
            if isinstance(res, dict) and res.get("ok"):
                _pp175_record_order_event(self, "BUY")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return res

    def _pp175_place_sell(self, api: ArzPlusAPI, wname: str, sym: str, qty: float, price: float):
        # Wait&Watch: SELLs allowed by default to avoid trapped positions
        try:
            if _pp175_waitwatch_active(self):
                block_sell = str(os.getenv("PP175_WAITWATCH_BLOCK_SELL", "0") or "0").strip().lower() in ("1","true","yes","on")
                if block_sell:
                    return {"ok": False, "status": 0, "error": "WAIT_WATCH", "text": "PP175: circuit breaker active; SELL paused"}
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        res = _pp175__orig_place_sell(self, api, wname, sym, qty, price)
        try:
            if isinstance(res, dict) and res.get("ok"):
                _pp175_record_order_event(self, "SELL")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return res

    PP5LiveTripleWallet._place_buy = _pp175_place_buy
    PP5LiveTripleWallet._place_sell = _pp175_place_sell

except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

# ---- Dashboard: NET_EFF in IQ / BRAIN STATUS and keep LEGACY INTELLIGENCE ----
try:
    _pp175__orig_reports_panel = DashboardManager._reports_panel

    def _ppdm_reports_panel_v175(self):
        from rich.panel import Panel
        from rich.table import Table
        from rich.text import Text
        from rich import box

        bot = self.bot
        lat = 0.0
        trades = "-"
        try:
            rt = getattr(bot, "runtime_context", None) or getattr(bot, "rt", None)
            if rt is not None:
                lat = float(getattr(rt, "cycle_latency", 0.0) or 0.0)
        except Exception:
            lat = 0.0

        try:
            trades = getattr(bot, "total_trades", None)
            if trades is None:
                trades = getattr(bot, "trades", None)
            trades = "-" if trades is None else str(int(trades))
        except Exception:
            trades = "-"

        conf = 0.0
        try:
            _brain = getattr(bot, "brain", None)
            if _brain is not None:
                conf = float(getattr(_brain, "data", {}).get("confidence_score", 0.0) or 0.0)
        except Exception:
            conf = 0.0

        # IQ / BRAIN STATUS (experience vs algorithm)
        exp_pct = 0.0
        alg_pct = 100.0
        try:
            _cc = getattr(bot, "cognitive_core", None)
            if _cc is not None:
                exp_pct, alg_pct = _cc.brain_status()
        except Exception:
            exp_pct, alg_pct = (0.0, 100.0)

        # NET_EFF (net-to-fee, EMA if present)
        net_eff = None
        try:
            net_eff = getattr(bot, "_pp175_net_eff_ema", None)
            if net_eff is None:
                net_eff = getattr(bot, "_pp175_net_eff", None)
        except Exception:
            net_eff = None

        events = []
        try:
            events = list(getattr(bot, "_events", []) or [])
        except Exception:
            events = []

        t = Table.grid(padding=(0, 1))
        t.add_column(justify="left", style="white", ratio=1)
        t.add_column(justify="right", style="white", ratio=1)

        t.add_row("CYCLE LATENCY", f"{lat:.2f}s")
        t.add_row("TRADES", str(trades))
        t.add_row("CONFIDENCE", f"{conf:.2f}")

        if net_eff is None:
            t.add_row("IQ / BRAIN STATUS", f"EXP {exp_pct:.0f}% | ALG {alg_pct:.0f}% | NET_EFF -")
        else:
            try:
                ne = float(net_eff)
                if math.isinf(ne) or math.isnan(ne):
                    t.add_row("IQ / BRAIN STATUS", f"EXP {exp_pct:.0f}% | ALG {alg_pct:.0f}% | NET_EFF ∞")
                else:
                    t.add_row("IQ / BRAIN STATUS", f"EXP {exp_pct:.0f}% | ALG {alg_pct:.0f}% | NET_EFF {ne:.2f}x")
            except Exception:
                t.add_row("IQ / BRAIN STATUS", f"EXP {exp_pct:.0f}% | ALG {alg_pct:.0f}% | NET_EFF -")

        # Strategic self-awareness text stream
        try:
            _st = str(getattr(bot, "_strategic_thought", "") or "")
        except Exception:
            _st = ""
        if len(_st) > 180:
            _st = _st[:180] + "…"
        t.add_row("STRATEGIC_THOUGHT", _st if _st else "(n/a)")

        # LEGACY INTELLIGENCE (from PP170), now guaranteed present in v175 reports panel
        try:
            _li = getattr(bot, "legacy_intel", None) or getattr(bot, "legacy_intelligence", None)
            if _li is not None:
                t.add_row("LEGACY INTELLIGENCE", "")
                try:
                    _items = list(_li.status_items())
                except Exception:
                    _items = []
                for _k, _v in (_items or [])[:10]:
                    try:
                        t.add_row(str(_k), str(_v))
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # Circuit breaker status
        try:
            if _pp175_waitwatch_active(bot):
                try:
                    until = float(getattr(bot, "_pp175_waitwatch_until", 0.0) or 0.0)
                except Exception:
                    until = 0.0
                left = max(0, int(until - _pp175_now()))
                t.add_row("WAIT & WATCH", f"ACTIVE ({left}s)")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        ev_text = "\n".join([str(x)[:160] for x in events]) if events else "(no events)"
        t2 = Table.grid(padding=(0, 0))
        t2.add_column(ratio=1)
        t2.add_row(Text(ev_text, style="white"))

        grid = Table.grid(expand=True)
        grid.add_column(ratio=1)
        grid.add_row(t)
        grid.add_row(t2)

        return Panel(grid, title="[bold white]REPORTS[/bold white]", box=box.HEAVY, style="white on black")

    DashboardManager._reports_panel = _ppdm_reports_panel_v175
except Exception:
    # If anything fails, keep existing panel
    pass


