# ============================================================
# PP160: Tether Sanctuary + Hunter Engine + Disaster Recovery
#   - Auto-USDT conversion after SELL (if IRT > 50k)
#   - Portfolio valuation in USDT (USDT as base currency for metrics)
#   - Pump alert detector (5m volume >= 500% MA & rising price)
#   - Experience learning v160 (experience_v160.json + 24h cooldown with reason)
#   - Dollar Defense (USDT/IRT spike) => freeze buys, bias sells
#   - Full-screen TUI stays; Watchdog remains silent; fallback to text logs
# ============================================================

def _pp160_usdt_spike_detect(samples: Any, current_rate: float) -> bool:
    # Detect sudden USDT/IRT jump as IRR inflation shock (Dollar Defense)
    try:
        if current_rate <= 0:
            return False
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False
    try:
        th = float(os.getenv("USDT_SPIKE_PCT", "0.012") or 0.012)  # 1.2% in ~5m
    except Exception:
        th = 0.012
    try:
        win = float(os.getenv("USDT_SPIKE_WINDOW_SEC", "300") or 300.0)
    except Exception:
        win = 300.0
    try:
        now = _pp920_time.time()
        if not samples:
            return False
        # find sample ~win seconds ago
        old = None
        for ts, r in list(samples):
            if (now - float(ts)) >= win and float(r) > 0:
                old = float(r)
        if old is None:
            # fallback: compare against oldest
            ts0, r0 = list(samples)[0]
            old = float(r0) if float(r0) > 0 else None
        if old is None or old <= 0:
            return False
        pct = (float(current_rate) - float(old)) / float(old)
        return bool(pct >= th)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

def _pp160_infer_loss_reason(*, spread_bps: float, vola: float, bid_volume: float) -> str:
    # Best-effort heuristics; persisted only on losing trades.
    try:
        if float(spread_bps) >= float(os.getenv("LOSS_REASON_SPREAD_BPS", "45") or 45):
            return "wide_spread"
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        if float(bid_volume) <= float(os.getenv("LOSS_REASON_LOW_VOL", "0.0") or 0.0):
            # if bid_volume isn't available, don't force low_volume
            return "unknown"
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        if float(vola) >= float(os.getenv("LOSS_REASON_HIGH_VOLA", "0.05") or 0.05):
            return "high_volatility"
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        if float(bid_volume) < float(os.getenv("LOSS_REASON_LOW_BOOK", "150") or 150):
            return "low_volume"
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return "unknown"

def _pp160_env_true(name: str, default: bool = False) -> bool:
    try:
        v = os.getenv(name)
    except Exception:
        v = None
    if v is None:
        return bool(default)
    s = str(v).strip().lower()
    return s in ("1", "true", "yes", "y", "on", "t")


# ============================================================
# PP722: The Balanced Hunter — Strategic Wait Timer + USDT Sanctuary
# - Cash (IRT) is NOT immediately locked into USDT.
# - If cash stays idle for WAIT_SEC without PRIMARY buys (GOLD/BTC), convert to USDT.
# - USDT entry is aggressive: 80 BPS above Best Bid (limit buy), respecting tick_size/step_size.
# ============================================================

def _pp722_fmt_mmss(sec: float) -> str:
    try:
        s = int(max(0.0, float(sec or 0.0)))
    except Exception:
        s = 0
    m = s // 60
    r = s % 60
    return f"{m:02d}:{r:02d}"

def _pp722_sanctuary_tick(bot: Any,
                          api: Any,
                          *,
                          wallet_name: str,
                          cash_irt: float,
                          min_irt: float = 200000.0,
                          wait_sec: int = 300,
                          reserve_irt: float = 20000.0,
                          aggr_add: int = 10) -> None:
    """v723 sanctuary controller (hardened).

    Key fixes (root-cause for "no trade for 30+ minutes"):
      1) Absolute idle timer: DOES NOT reset on transient API/balance errors and DOES NOT reset on merely placing
         an unfilled GOLD/BTC order. It only resets on an actually filled PRIMARY trade (handled elsewhere).
      2) Gate visibility: any early-return condition (empty book / spend too small / qty rounds to 0 / order rejected)
         is logged (throttled) so it shows up in Termux.
      3) Price source: uses orderbook depth for USDT and guarantees a marketable price when spread > aggr_add.

    Conversion rule:
      - If cash_irt >= min_irt and stays idle for wait_sec, convert to USDT via aggressive limit-buy.
      - Price = max(int(best_bid + aggr_add), int(best_ask))  # crosses the book to fill (while honoring +aggr_add minimum).
      - amount/price are ultimately sent as STRINGs by ArzPlusAPI.create_order (per docs).
    """
    try:
        import time as _t
        _now = float(_t.time())

        wname = str(wallet_name or "").strip()
        if not wname:
            return

        # Ensure state dicts exist
        if not hasattr(bot, "_pp722_cash_idle_since"):
            bot._pp722_cash_idle_since = {}
        if not hasattr(bot, "_pp722_last_primary_buy_ts"):
            bot._pp722_last_primary_buy_ts = {}
        if not hasattr(bot, "_pp722_sanctuary_remaining"):
            bot._pp722_sanctuary_remaining = {}
        if not hasattr(bot, "_pp722_last_sanctuary_ts"):
            bot._pp722_last_sanctuary_ts = {}
        if not hasattr(bot, "_pp722_last_balance_ok"):
            bot._pp722_last_balance_ok = {}
        if not hasattr(bot, "_pp722_sanctuary_last_note_ts"):
            bot._pp722_sanctuary_last_note_ts = {}

        # Throttled logger (avoid spamming every cycle)
        def _note(msg: str, level: str = "info", throttle_sec: float = 30.0) -> None:
            try:
                last = float((bot._pp722_sanctuary_last_note_ts.get(wname, 0.0) or 0.0))
            except Exception:
                last = 0.0
            if (last > 0.0) and ((_now - last) < float(throttle_sec)):
                return
            try:
                bot._pp722_sanctuary_last_note_ts[wname] = float(_now)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            lg = getattr(bot, "logger", None)
            try:
                if lg is None:
                    print(f"[SANCTUARY] {wname} | {msg}")
                    return
                fn = getattr(lg, str(level), None)
                if callable(fn):
                    fn(f"[SANCTUARY] {wname} | {msg}")
                else:
                    lg.info(f"[SANCTUARY] {wname} | {msg}")
            except Exception:
                try:
                    print(f"[SANCTUARY] {wname} | {msg}")
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

        # Normalize inputs
        try:
            cash_in = None if cash_irt is None else float(cash_irt)
        except Exception:
            pass

        # Balance-error hardening: if cash reading is missing/zero due to transient errors, reuse last good cash
        cash = cash_in
        last_bal = bot._pp722_last_balance_ok.get(wname) if isinstance(getattr(bot, "_pp722_last_balance_ok", None), dict) else None
        if cash is not None and cash > 0.0:
            try:
                bot._pp722_last_balance_ok[wname] = {"ts": float(_now), "cash": float(cash)}
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
        elif (cash is None) or (cash <= 0.0):
            if isinstance(last_bal, dict):
                try:
                    _ts = float(last_bal.get("ts") or 0.0)
                    _c = float(last_bal.get("cash") or 0.0)
                except Exception:
                    _ts, _c = 0.0, 0.0
                # If we had a good balance recently, keep using it (do NOT reset timer).
                if _c > 0.0 and (_ts > 0.0) and ((_now - _ts) <= 1800.0):
                    cash = float(_c)
                    _note("balance read was empty; using last-good CASH for timer stability", level="warning", throttle_sec=60.0)

        if cash is None:
            # Can't do anything without a known cash value; keep existing timer state
            return

        _min = float(min_irt or 0.0)
        _wait = float(wait_sec or 300.0)
        _reserve = float(reserve_irt or 0.0)
        _add = 10  # v725 hard-lock: +10 units above Best Bid

        last_primary = float((bot._pp722_last_primary_buy_ts.get(wname, 0.0) or 0.0))
        idle_since = float((bot._pp722_cash_idle_since.get(wname, 0.0) or 0.0))

        # If cash is below threshold, reset timer
        if cash < _min:
            bot._pp722_cash_idle_since[wname] = 0.0
            bot._pp722_sanctuary_remaining[wname] = float(_wait)
            return

        # v730: idle timer is sensitive ONLY to CASH(IRT) stability (does NOT reset on other asset volatility)
        try:
            if not hasattr(bot, '_pp722_last_cash_irt'):
                bot._pp722_last_cash_irt = {}
            _eps = float(os.getenv('USDT_TIMER_CASH_EPS', '10') or 10.0)
            _prev = bot._pp722_last_cash_irt.get(wname) if isinstance(getattr(bot, '_pp722_last_cash_irt', None), dict) else None
            if _prev is None:
                bot._pp722_last_cash_irt[wname] = float(cash)
            else:
                try:
                    if abs(float(cash) - float(_prev)) > float(_eps):
                        idle_since = float(_now)
                    bot._pp722_last_cash_irt[wname] = float(cash)
                except Exception:
                    bot._pp722_last_cash_irt[wname] = float(cash)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        # Start / refresh timer (absolute, only based on last FILLED primary buy timestamp)
        if idle_since <= 0.0:
            idle_since = _now
        if last_primary > idle_since:
            idle_since = last_primary
        bot._pp722_cash_idle_since[wname] = float(idle_since)

        elapsed = max(0.0, _now - float(idle_since))
        remaining = max(0.0, float(_wait) - float(elapsed))
        bot._pp722_sanctuary_remaining[wname] = float(remaining)

        # v729: FORCE_NOW=1 bypasses the idle timer and triggers conversion immediately.
        try:
            _fn = str(os.getenv('FORCE_NOW', '0') or '0').strip().lower()
            force_now = _fn in ('1', 'true', 'yes', 'on')
        except Exception:
            force_now = False
        if force_now:
            remaining = 0.0
            bot._pp722_sanctuary_remaining[wname] = 0.0

        if remaining > 0.0:
            return

        # Cooldown guard
        try:
            cd = float(os.getenv("USDT_SANCTUARY_COOLDOWN_SEC", "2.0") or 2.0)
        except Exception:
            cd = 2.0
        # v730: FORCE_NOW bypasses cooldown too
        if force_now:
            cd = 0.0

        last_s = float((bot._pp722_last_sanctuary_ts.get(wname, 0.0) or 0.0))
        if last_s > 0.0 and (_now - last_s) < cd:
            return

        # Do not stack USDT orders (v725: cancel stale/new orders so CASH does not stay locked)
        try:
            lo = api.list_orders(symbol="USDTIRT", status="new", limit=20, offset=0)
            if isinstance(lo, dict) and bool(lo.get("ok")):
                d = lo.get("data") or {}
                res = d.get("results") or []
                if isinstance(res, list) and len(res) > 0:
                    # Cancel open USDT orders that might be stuck (silent blocker).
                    canceled = 0
                    for o in res:
                        try:
                            oid = o.get("id")
                            if oid is None:
                                continue
                            api.cancel_order(int(oid))
                            canceled += 1
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                    if canceled > 0:
                        _note(f"found {canceled} open USDTIRT order(s) -> canceled; will re-place aggressively", level="warning", throttle_sec=10.0)
                    else:
                        _note("skipping: there is already an OPEN USDTIRT order (unable to cancel)", level="warning", throttle_sec=20.0)
                        return
        except Exception as _e:
            _pp200_heal(_e, tag="pp723_list_orders_usdt")

        # Read USDT book (public)
        dp = api.depth("USDTIRT")
        if not isinstance(dp, dict) or not bool(dp.get("ok")):
            _note("depth(USDTIRT) failed; skipping this cycle (timer preserved)", level="warning", throttle_sec=20.0)
            return
        dd = dp.get("data") or {}
        bid, ask, mid = _book_top(dd)

        if bid <= 0.0 and ask > 0.0:
            # Some books may expose only asks; still try to execute.
            bid = float(ask)
        if bid <= 0.0 and ask <= 0.0:
            _note("orderbook empty (bid/ask=0); skipping this cycle", level="warning", throttle_sec=30.0)
            return

        # v729 Aggressive buy: reference = max(best_bid, last_trade_price) then +10, and marketable (>= best ask).
        last_px = 0.0
        try:
            lt = (dd.get('last_trade') or {}) if isinstance(dd, dict) else {}
            last_px = float((lt or {}).get('price') or 0.0)
        except Exception:
            last_px = 0.0
        ref_px = max(float(bid), float(last_px))
        px = int(ref_px + float(_add))
        if ask > 0.0:
            try:
                px = max(int(px), int(float(ask)))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

        # Spendable IRT (leave reserve)
        spend = max(0.0, float(cash) - float(_reserve))
        try:
            _mn = float(getattr(bot, "min_notional_irt", 0.0) or 0.0)
        except Exception:
            _mn = 0.0
        # v725: exchange-side minimum notional for IRT markets (user confirmed): 200000 TOMAN
        # Also respect configured min_irt (sanctuary threshold) if higher.
        _mn = max(float(_mn), float(_min), 200000.0)
        if spend <= _mn:
            _note(f"skipping: spend={spend:.2f} <= min_notional={_mn:.2f}", level="debug", throttle_sec=60.0)
            return

        # Amount Scaling (USDT): compute qty and round DOWN to exchange step_size (dynamic from /market/symbols)
        step_dec = 2
        min_qty = 0.0
        try:
            sp = api.get_market_spec("USDTIRT") if hasattr(api, "get_market_spec") else None
            if isinstance(sp, dict):
                try:
                    step_dec = int(sp.get("step_size", step_dec) or step_dec)
                except Exception:
                    step_dec = step_dec
                try:
                    min_qty = float(sp.get("min_trade_quantity") or 0.0)
                except Exception:
                    min_qty = 0.0
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        step_dec = max(0, min(int(step_dec), 12))

        try:
            from decimal import Decimal as _D, ROUND_DOWN as _RD
            q = _D(str(spend)) / _D(str(px))
            if step_dec == 0:
                q = q.to_integral_value(rounding=_RD)
            else:
                q = q.quantize(_D('1e-%d' % step_dec), rounding=_RD)
            qty = float(q)
        except Exception:
            qty = 0.0

        # v725 Floor Fix: ensure cost does not exceed spend due to float/rounding edge cases
        try:
            from decimal import Decimal as _D, ROUND_DOWN as _RD
            _cost = _D(str(px)) * _D(str(qty))
            _sp = _D(str(spend))
            if _cost > _sp:
                _step = _D('1') if int(step_dec) == 0 else _D('1e-%d' % int(step_dec))
                _q = _D(str(qty)) - _step
                if _q < _D('0'):
                    _q = _D('0')
                if int(step_dec) == 0:
                    qty = float(_q.to_integral_value(rounding=_RD))
                else:
                    qty = float(_q.quantize(_step, rounding=_RD))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        if qty <= 0.0:
            _note("skipping: qty rounded to 0 (check step_size/mins)", level="warning", throttle_sec=60.0)
            return
        if min_qty > 0.0 and qty < min_qty:
            _note(f"skipping: qty={qty} < min_trade_quantity={min_qty}", level="warning", throttle_sec=60.0)
            return

        # Place order (create_order enforces: price int->string, amount string, tick/step/min/max)
        try:
            import uuid as _uuid
            client_id = f"{wname}-USDTIRT-{int(_now*1000)}-{_uuid.uuid4().hex[:8]}"
        except Exception:
            client_id = f"{wname}-USDTIRT-{int(_now*1000)}"
        # NOTE: ArzPlus docs don't advertise a client_id field; we keep it local for logging/dedup.
        res = api.place_normal_order('USDTIRT', qty, px, side='buy', fill_type='limit', market='spot')
        if not isinstance(res, dict) or not bool(res.get("ok")):
            _note(f"order rejected | px={px} qty={qty} | resp={res}", level="error", throttle_sec=20.0)
            return

        # Mark sanctuary action timestamp (avoid bursts)
        bot._pp722_last_sanctuary_ts[wname] = float(_now)
        _note(f"USDT conversion order sent | client_id={client_id} price={px} amount={qty}", level="warning", throttle_sec=5.0)
        return

    except Exception as _e:
        _pp200_heal(_e, tag="pp723_sanctuary_tick")
        try:
            if api is not None and hasattr(api, "reset_session"):
                api.reset_session()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        # Force immediate Trinity restart
        try:
            setattr(bot, "_pp200_restart_now", True)
            setattr(bot, "_pp200_force_priority_restart", True)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

def _pp160_auto_usdt_conversion(bot: Any, api: Any, *, wallet_name: str, min_irt: float = 0.0) -> None:
    # v713 The Fluid Sovereign (هوش پیش‌دستانه و چند‌وجهی)
    # - USDT-IRT Nexus: خروج حداکثری از تومان هنگام ضعف (Priority One)، مگر فرصت سود بزرگ‌تر.
    # - Multi-Asset Opportunism: مقایسه لحظه‌ای بازدهی/مومنتوم USDT/BTC/ETH/PAXG در تومان.
    # - Neural-Adaptive Aggression: تهاجم پویا 20..300 BPS بر اساس نوسان (ATR proxy) + Spread + فشار سفارشات.
    # - Strategic Life-Support: اگر مسیر مستقیم مسدود/نامناسب بود، روتِ جایگزین انتخاب می‌شود (توقف تعریف ندارد).
    # - گزارش‌دهی: وضعیت استراتژی زنده + تومان محور.
    try:
        if not bot or not api:
            return
        # Only run in live mode (avoid paper trading drift)
        try:
            if not bool(getattr(bot, "live", False)) or bool(getattr(bot, "dry", False)):
                return
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return

    try:
        import time
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return

    now = float(_pp920_time.time())

    # Per-wallet isolation (do not cascade failures)
    try:
        iso = getattr(bot, "_pp712_wallet_isolation_until", None)
        if isinstance(iso, dict):
            until = float(iso.get(str(wallet_name), 0.0) or 0.0)
            if until > 0.0 and now < until:
                return
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # ---- helpers ----
    def _hist_push(sym: str, mid: float) -> list:
        try:
            hmap = getattr(bot, "_pp712_oracle_hist", None)
            if not isinstance(hmap, dict):
                hmap = {}
                setattr(bot, "_pp712_oracle_hist", hmap)
            h = hmap.get(sym)
            if not isinstance(h, list):
                h = []
                hmap[sym] = h
            h.append(float(mid))
            if len(h) > 32:
                del h[:-32]
            return h
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return [float(mid)]

    def _momentum_pct(sym: str, h: list) -> float:
        try:
            br = getattr(bot, "brain", None)
            if br is not None and hasattr(br, "predict_next_move"):
                _, sp = br.predict_next_move(h)
                return float(sp)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return 0.0

    def _dyn_pulse(sev: float) -> tuple[float, float]:
        try:
            s = float(sev)
        except Exception:
            s = 0.0
        if not math.isfinite(s):
            s = 0.0
        s = max(0.0, min(1.0, s))
        # cooldown fixed at 2.0s (per red-line speed)
        cd = 2.0
        # aggression in [20 .. 300] bps
        bps = 20.0 + s * (300.0 - 20.0)
        return float(cd), float(bps)

    # last attempt map (per wallet+symbol)
    try:
        if not hasattr(bot, "_pp712_oracle_last_ts") or not isinstance(getattr(bot, "_pp712_oracle_last_ts", None), dict):
            bot._pp712_oracle_last_ts = {}
        last_map = bot._pp712_oracle_last_ts
    except Exception:
        last_map = {}

    # Balances (heal on failure: clear cache and retry immediately)
    balances = None
    try:
        balances = bot._balances(api) if hasattr(bot, "_balances") else None
    except Exception as _e:
        _pp200_heal(_e, tag=f"oracle_balance:{wallet_name}")
        balances = None
    if not isinstance(balances, dict):
        try:
            balances = bot._balances(api) if hasattr(bot, "_balances") else {}
        except Exception as _e2:
            _pp200_heal(_e2, tag=f"oracle_balance_retry:{wallet_name}")
            balances = {}
    if not isinstance(balances, dict):
        return

    def _bal(asset: str) -> float:
        try:
            return float((balances or {}).get(str(asset).upper(), 0.0) or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

    irt_free = _bal("IRT")
    usdt_free = _bal("USDT")
    btc_free = _bal("BTC")
    eth_free = _bal("ETH")
    paxg_free = _bal("PAXG")

    # Convert floors
    try:
        min_notional_irt = float(getattr(bot, "min_notional_irt", 200000.0) or 200000.0)
    except Exception:
        min_notional_irt = 200000.0
    try:
        min_irt_eff = max(0.0, float(min_irt or 0.0))
    except Exception:
        min_irt_eff = 0.0
    min_floor = max(float(min_notional_irt), float(min_irt_eff), 0.0)

    # Candidate sanctuaries (PAXG optional)
    cand = [("PAXGIRT", "PAXG"), ("GOLDIRT", "PAXG"), ("USDTIRT", "USDT"), ("BTCIRT", "BTC"), ("ETHIRT", "ETH")]

    # Strategic Life-Support: skip temporarily banned paths (set by _pp200_heal)
    try:
        _ban = getattr(bot, '_pp713_path_ban', None)
    except Exception:
        _ban = None
    _cand = []
    for _sym, _asset in (cand or []):
        try:
            if isinstance(_ban, dict):
                _u = float(_ban.get(f"{wallet_name}:{_sym}", 0.0) or 0.0)
                if _u > 0.0 and now < _u:
                    continue
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        _cand.append((_sym, _asset))
    cand = _cand

    mkt = {}  # sym -> {bid, ask, mid, spr, obi}
    for sym, _a in cand:
        depth = None
        try:
            depth = api.depth(sym)
            if not isinstance(depth, dict) or not depth.get("ok"):
                raise RuntimeError(f"depth failed: {sym}")
            d = depth.get("data") or {}
        except Exception as _e:
            _pp200_heal(_e, tag=f"oracle_depth:{sym}:{wallet_name}")
            # retry once after heal
            try:
                depth = api.depth(sym)
                if not isinstance(depth, dict) or not depth.get("ok"):
                    continue
                d = depth.get("data") or {}
            except Exception as _e2:
                _pp200_heal(_e2, tag=f"oracle_depth_retry:{sym}:{wallet_name}")
                continue
        try:
            bid, ask, mid = _book_top(d)
            if mid <= 0:
                continue
            spr = _spread_bps(bid, ask)
        except Exception:
            continue
        obi = 0.0
        try:
            bvol = _book_side_amount((d or {}).get('bids') or [], 5)
            avol = _book_side_amount((d or {}).get('asks') or [], 5)
            den = float(bvol) + float(avol)
            if den > 0.0:
                obi = (float(bvol) - float(avol)) / den
        except Exception:
            obi = 0.0
        mkt[sym] = {"bid": float(bid), "ask": float(ask), "mid": float(mid), "spr": float(spr), "obi": float(obi)}

    if not mkt:
        return

    # Update momentum history
    mom = {}
    for sym, rec in (mkt or {}).items():
        try:
            h = _hist_push(sym, float(rec.get("mid", 0.0) or 0.0))
            mom[sym] = _momentum_pct(sym, h)
        except Exception:
            mom[sym] = 0.0

    # --- IRT Intelligence Index (toman strength) ---
    usdt_m = float(mom.get("USDTIRT", 0.0) or 0.0)
    btc_m = float(mom.get("BTCIRT", 0.0) or 0.0)
    eth_m = float(mom.get("ETHIRT", 0.0) or 0.0)
    paxg_m = float(mom.get("GOLDIRT", 0.0) or 0.0)

    # Absolute inflation hunt: if USDTIRT shoots up fast, force aggressive sanctuary override (ignore vetoes)
    try:
        if usdt_m > 0.10:
            setattr(bot, "_pp712_absolute_aggression_until", float(now + 4.0))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    target_sym = "USDTIRT"
    mode = "Toman Defense"

    # Market Ambush: if USDTIRT is falling with meaningful speed => toman strengthening
    if usdt_m < -0.015 and float((mkt.get('USDTIRT', {}) or {}).get('obi', 0.0) or 0.0) <= 0.0:
        target_sym = "IRT"
        mode = "Market Ambush"
    else:
        # Score sanctuaries (momentum - spread penalty). Prefer higher momentum with better liquidity.
        scores = {}
        for sym in ("USDTIRT", "BTCIRT", "ETHIRT", "GOLDIRT"):
            if sym not in mkt:
                continue
            try:
                sp = float(mom.get(sym, 0.0) or 0.0)
            except Exception:
                sp = 0.0
            try:
                spr = float(mkt[sym].get("spr", 0.0) or 0.0)
            except Exception:
                spr = 0.0
            # Spread penalty: 0.002% per 1 bps
            try:
                obi = float(mkt.get(sym, {}).get('obi', 0.0) or 0.0)
            except Exception:
                obi = 0.0
            score = sp - (spr * 0.002) + (obi * 0.005)
            scores[sym] = float(score)
        # pick best; default to USDT defense
        best = "USDTIRT"
        bestv = float(scores.get(best, -1e9))
        for sym, v in (scores or {}).items():
            if v > bestv:
                best, bestv = sym, float(v)

        bullish = False
        try:
            bullish = (btc_m > 0.03 and eth_m > 0.03) or (btc_m > 0.06 and eth_m > 0.0) or (eth_m > 0.06 and btc_m > 0.0)
        except Exception:
            bullish = False
        th = 0.01 if bullish else 0.02

        # Growth chase: BTC/ETH/PAXG clearly outperform USDT (in toman terms)
        if best in ("BTCIRT", "ETHIRT", "GOLDIRT") and float(bestv) > float(scores.get("USDTIRT", -1e9)) + float(th):
            target_sym = best
            mode = "Chasing Growth"
        else:
            target_sym = "USDTIRT"
            mode = "Toman Defense"

    # Persist strategy mode for dashboard
    try:
        setattr(bot, "_pp712_strategy_mode", str(mode))
        if not hasattr(bot, "_pp712_wallet_strategy") or not isinstance(getattr(bot, "_pp712_wallet_strategy", None), dict):
            bot._pp712_wallet_strategy = {}
        bot._pp712_wallet_strategy[str(wallet_name)] = str(mode)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Dynamic pulse severity from target momentum + target spread
    sev = 0.0
    try:
        if target_sym == 'IRT':
            sev = abs(float(usdt_m))
        else:
            sev = abs(float(mom.get(target_sym, 0.0) or 0.0))
            try:
                sev = max(sev, float((mkt.get(target_sym, {}) or {}).get('spr', 0.0) or 0.0) / 300.0)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            try:
                sev = max(sev, abs(float((mkt.get(target_sym, {}) or {}).get('obi', 0.0) or 0.0)) * 0.5)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            # ATR proxy: mean abs returns over recent mids
            try:
                _hmap = getattr(bot, '_pp712_oracle_hist', None)
                _h = (_hmap or {}).get(target_sym) if isinstance(_hmap, dict) else None
                if isinstance(_h, list) and len(_h) >= 6:
                    _rs = []
                    for _i in range(1, min(len(_h), 10)):
                        _p0 = float(_h[-_i-1] or 0.0)
                        _p1 = float(_h[-_i] or 0.0)
                        if _p0 > 0.0 and _p1 > 0.0:
                            _rs.append(abs((_p1 - _p0) / _p0))
                    if _rs:
                        _v = float(sum(_rs)) / float(len(_rs))
                        sev = max(sev, min(1.0, float(_v) * 8.0))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            # Priority One: IRT -> USDT under weakening toman => maximum aggression
            try:
                if target_sym == 'USDTIRT' and float(usdt_m) > 0.0:
                    sev = max(sev, 1.0)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            try:
                _until = float(getattr(bot, '_pp712_absolute_aggression_until', 0.0) or 0.0)
                if _until > 0.0 and now < _until:
                    sev = max(sev, 1.0)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
    except Exception:
        sev = 0.0
    cd, aggr_bps = _dyn_pulse(sev)

    # Throttle: per wallet+target (do not update on data-fetch failures)
    key = f"{wallet_name}:{target_sym}"
    try:
        last_ts = float((last_map or {}).get(key, 0.0) or 0.0)
    except Exception:
        last_ts = 0.0
    try:
        if last_ts > 0.0 and (now - last_ts) < float(cd):
            return
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    def _sell_to_irt(sym: str, asset: str, qty: float) -> bool:
        if sym not in mkt:
            return False
        try:
            if qty <= 0.0:
                return False
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False
        try:
            bid = float(mkt[sym].get("bid", 0.0) or 0.0)
            if bid <= 0:
                return False
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False
        try:
            px = float(bid) * (1.0 - (float(aggr_bps) / 10000.0))
            px = max(0.0, float(px))
        except Exception:
            px = float(bid)
        # value check
        try:
            if (float(qty) * float(bid)) < float(min_notional_irt):
                return False
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        try:
            res = bot._place_sell(api, str(wallet_name), str(sym), float(qty), float(px))
            if isinstance(res, dict) and bool(res.get("ok")):
                return True
        except Exception as _e:
            _pp200_heal(_e, tag=f"oracle_sell:{sym}:{wallet_name}")
        return False

    def _buy_from_irt(sym: str, qty_irt: float) -> bool:
        if sym not in mkt:
            return False
        try:
            if qty_irt <= 0.0:
                return False
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False
        try:
            ask = float(mkt[sym].get("ask", 0.0) or 0.0)
            if ask <= 0:
                return False
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False
        try:
            bid = float(mkt[sym].get("bid", 0.0) or 0.0)
        except Exception:
            bid = 0.0
        # v730 pricing rule: cross the book using max(int(best_bid)+10, int(best_ask)) so order fills immediately
        try:
            px = float(max(float(int(bid) + 10), float(int(ask))))
            px = max(0.0, float(px))
        except Exception:
            px = float(ask)
        try:
            qty = float(qty_irt) / float(px)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False
        if qty <= 0.0:
            return False
        # place order (autonomous sanctuary actions bypass vetoes upstream)
        try:
            res = bot._place_buy(api, str(wallet_name), str(sym), float(qty), float(px))
            if isinstance(res, dict) and bool(res.get("ok")):
                return True
        except Exception as _e:
            _pp200_heal(_e, tag=f"oracle_buy:{sym}:{wallet_name}")
        return False

    # --- Execution logic ---
    acted = False

    # If target is IRT: unwind sanctuary assets back to IRT (smart cash)
    if target_sym == "IRT":
        try:
            if usdt_free > 0 and _sell_to_irt("USDTIRT", "USDT", usdt_free):
                acted = True
            if btc_free > 0 and _sell_to_irt("BTCIRT", "BTC", btc_free):
                acted = True
            if eth_free > 0 and _sell_to_irt("ETHIRT", "ETH", eth_free):
                acted = True
            if paxg_free > 0 and _sell_to_irt(("PAXGIRT" if "PAXGIRT" in (mkt or {}) else "GOLDIRT"), "PAXG", paxg_free):
                acted = True
        except Exception as _e:
            _pp200_heal(_e, tag=f"oracle_unwind:{wallet_name}")
        if acted:
            try:
                last_map[key] = float(now)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
        return

    # Otherwise: ensure we have enough IRT to deploy; if not, free it by selling non-target sanctuaries.
    if irt_free < float(min_floor):
        # sell the largest non-target sanctuary position first (strategic healing route)
        candidates = []
        try:
            if target_sym != "USDTIRT" and usdt_free > 0:
                candidates.append(("USDTIRT", usdt_free))
            if target_sym != "BTCIRT" and btc_free > 0:
                candidates.append(("BTCIRT", btc_free))
            if target_sym != "ETHIRT" and eth_free > 0:
                candidates.append(("ETHIRT", eth_free))
            _gold_sym = "PAXGIRT" if "PAXGIRT" in (mkt or {}) else "GOLDIRT"
            if target_sym != _gold_sym and paxg_free > 0:
                candidates.append((_gold_sym, paxg_free))
        except Exception:
            candidates = []
        # pick max notional by mid
        best_sym = ""
        best_qty = 0.0
        best_val = 0.0
        for sym, q in candidates:
            try:
                mid = float((mkt.get(sym, {}) or {}).get("mid", 0.0) or 0.0)
                val = float(q) * float(mid)
            except Exception:
                val = 0.0
            if val > best_val:
                best_val = val
                best_sym = sym
                best_qty = float(q)
        if best_sym and best_qty > 0:
            if _sell_to_irt(best_sym, "", best_qty):
                try:
                    last_map[key] = float(now)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                return
        return

    # We have IRT: deploy into target sanctuary
    qty_irt = float(irt_free)
    if qty_irt <= 0.0:
        return

    if _buy_from_irt(target_sym, qty_irt):
        try:
            last_map[key] = float(now)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return

    # Strategic Life-Support: route-switch to next best sanctuary if direct path is blocked
    try:
        _alts = []
        try:
            _scores = locals().get('scores', None)
            if isinstance(_scores, dict) and _scores:
                _alts = [k for k, _v in sorted(_scores.items(), key=lambda kv: kv[1], reverse=True)]
        except Exception:
            _alts = []
        if not _alts:
            _alts = ['USDTIRT', 'BTCIRT', 'ETHIRT', 'PAXGIRT', 'GOLDIRT']
        for _s in _alts:
            if _s == target_sym or _s == 'IRT':
                continue
            if _buy_from_irt(_s, qty_irt):
                try:
                    last_map[f"{wallet_name}:{_s}"] = float(now)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                try:
                    _pp200_heal(RuntimeError('route-switch'), tag=f"oracle_route_switch:{target_sym}->{_s}:{wallet_name}")
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                return
    except Exception as _e:
        _pp200_heal(_e, tag=f"oracle_route_fallback:{wallet_name}")
    return
def _pp180_env_true(k: str, default: str = "0") -> bool:
    try:
        v = str(os.getenv(k, default) or default).strip().lower()
        return v in ("1", "true", "yes", "on")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

def _pp180_now() -> float:
    try:
        return _pp920_time.time()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

def _pp180_safe_float(x, d=0.0) -> float:
    try:
        return float(x)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(d)

def _pp180_portfolio_value_usdt_from_eq_cache(eq_cache: Any, usdt_rate: float) -> float:
    try:
        ur = float(usdt_rate or 0.0)
    except Exception:
        ur = 0.0
    if ur <= 0:
        return 0.0
    try:
        total_irt = 0.0
        for _, v in (dict(eq_cache or {}) or {}).items():
            try:
                total_irt += float(v or 0.0)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        return float(total_irt) / ur
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

def _pp180_pick_liquidity_mode_and_sovereign(bot: Any) -> Tuple[str, Optional[str], float]:
    """
    Returns: (mode, sovereign_wallet_name, total_equity_usdt)
      - mode: "SNIPER" | "PORTFOLIO"
    """
    eq_cache = getattr(bot, "_dash_equity_cache", {}) or {}
    ur = _pp180_safe_float(getattr(bot, "_dash_usdt_rate", 0.0), 0.0)
    total_usdt = _pp180_portfolio_value_usdt_from_eq_cache(eq_cache, ur)

    try:
        thr = float(os.getenv("PP180_PORTFOLIO_USDT_THR", "1200") or 1200.0)
    except Exception:
        thr = 1200.0
    mode = "PORTFOLIO" if total_usdt >= float(thr) else "SNIPER"

    sovereign = None
    try:
        sovereign = max(eq_cache.items(), key=lambda kv: _pp180_safe_float(kv[1], 0.0))[0] if eq_cache else None
    except Exception:
        sovereign = None

    try:
        setattr(bot, "_pp180_liq_mode", str(mode))
        setattr(bot, "_pp180_sovereign_wallet", sovereign)
        setattr(bot, "_pp180_total_equity_usdt", float(total_usdt))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return mode, sovereign, float(total_usdt)

def _pp180__read_source() -> str:
    # Prefer PP170 reader if present (ensures correct __file__ handling)
    try:
        f = globals().get("_pp170__read_source")
        if callable(f):
            s = f()
            if s:
                return str(s)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        p = globals().get("__file__")
        if p:
            return Path(str(p)).read_text(encoding="utf-8", errors="ignore")
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return ""

def _pp180__deep_scan_sleepers(max_ver: int = 130) -> List[Dict[str, Any]]:
    """
    Deep scan the whole file for *sleeping* legacy defs/classes (mostly pre-v110),
    plus classic legacy keywords (arbitrage/fractal/harmonic/kalman/stat/noise).
    Returns list[{name, kind, ver, reason}]
    """
    src = _pp180__read_source()
    if not src:
        return []
    candidates: List[Tuple[str, str, Optional[int], str]] = []
    key_terms = (
        "arbitrage", "arb", "fractal", "harmonic", "pattern", "gann", "elliott",
        "kalman", "noise", "denoise", "filter", "stat", "zscore", "hurst",
        "meanrevert", "cointegr", "spread", "orderbook", "imbalance",
    )

    # defs
    try:
        for m in re.finditer(r'^\s*def\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(', src, re.M):
            name = m.group(1)
            ver = None
            mm = _pp920_re.match(r'^_pp(\d+)_', name)
            if mm:
                try:
                    ver = int(mm.group(1))
                except Exception:
                    ver = None
            if (ver is not None and ver < int(max_ver)) or any(t in name.lower() for t in key_terms):
                candidates.append((name, "def", ver, "name-match"))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # classes
    try:
        for m in re.finditer(r'^\s*class\s+([A-Za-z_][A-Za-z0-9_]*)\s*(\(|:)', src, re.M):
            name = m.group(1)
            ver = None
            mm = _pp920_re.match(r'^_pp(\d+)_', name)
            if mm:
                try:
                    ver = int(mm.group(1))
                except Exception:
                    ver = None
            if (ver is not None and ver < int(max_ver)) or any(t in name.lower() for t in key_terms):
                candidates.append((name, "class", ver, "name-match"))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    out: List[Dict[str, Any]] = []
    try:
        for name, kind, ver, why in candidates:
            try:
                cnt = len(re.findall(r'\b' + re.escape(name) + r'\b', src))
            except Exception:
                cnt = 9
            if cnt <= 1:
                reason = "orphan"
            elif cnt <= 2:
                reason = "near-orphan"
            else:
                reason = "dormant"
            out.append({"name": name, "kind": kind, "ver": ver, "reason": reason, "why": why, "mentions": cnt})
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        rank = {"orphan": 0, "near-orphan": 1, "dormant": 2}
        out.sort(key=lambda d: (rank.get(str(d.get("reason")), 9),
                                9999 if d.get("ver") is None else int(d.get("ver")),
                                str(d.get("name"))))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        cap = int(os.getenv("PP180_SLEEPERS_CAP", "48") or 48)
    except Exception:
        cap = 48
    return out[:max(8, cap)]

class _PP180LegacySensor:
    __slots__ = ("name", "kind", "obj", "enabled", "fail", "last", "reason")
    def __init__(self, name: str, kind: str, obj: Any, reason: str = ""):
        self.name = str(name)
        self.kind = str(kind)
        self.obj = obj
        self.enabled = True
        self.fail = 0
        self.last = None
        self.reason = str(reason)

    def _call(self, ctx: Dict[str, Any]) -> Any:
        f = self.obj
        if callable(f):
            if _pp180_inspect is None:
                return f()
            sig = None
            try:
                sig = _pp180_inspect.signature(f)
            except Exception:
                sig = None
            if sig is None:
                return f()
            kwargs = {}
            for p, prm in sig.parameters.items():
                if p in ctx:
                    kwargs[p] = ctx[p]
                elif p == "prices":
                    kwargs[p] = ctx.get("prices")
                elif p in ("returns", "rets"):
                    kwargs[p] = ctx.get("returns")
                elif p in ("depth", "depth_data", "book"):
                    kwargs[p] = ctx.get("depth_data")
                elif p in ("bid", "ask", "mid", "price"):
                    kwargs[p] = ctx.get(p)
                elif p in ("sym", "symbol"):
                    kwargs[p] = ctx.get("sym")
                elif p in ("state", "symst", "st"):
                    kwargs[p] = ctx.get("symst")
                elif p in ("bot", "selfbot", "engine"):
                    kwargs[p] = ctx.get("bot")
            for p, prm in sig.parameters.items():
                if prm.default is prm.empty and prm.kind in (prm.POSITIONAL_ONLY, prm.POSITIONAL_OR_KEYWORD) and p not in kwargs:
                    raise TypeError(f"missing required param: {p}")
            return f(**kwargs)
        return None

    def eval_vote(self, ctx: Dict[str, Any]) -> Tuple[int, float, str]:
        if not self.enabled:
            return 0, 0.0, "DISABLED"
        try:
            r = self._call(ctx)
            self.last = r
        except Exception as e:
            self.fail += 1
            if self.fail >= 3:
                self.enabled = False
            return 0, 0.0, f"ERR:{type(e).__name__}"

        try:
            if isinstance(r, dict):
                s = str(r.get("signal") or r.get("side") or r.get("action") or "").upper().strip()
                c = _pp180_safe_float(r.get("confidence", r.get("conf", 0.0)), 0.0)
                if s in ("BUY", "LONG"):
                    return +1, max(0.0, min(1.0, c or 0.55)), "DICT"
                if s in ("SELL", "SHORT"):
                    return -1, max(0.0, min(1.0, c or 0.55)), "DICT"
                v = _pp180_safe_float(r.get("score", r.get("value", 0.0)), 0.0)
                if v > 0:
                    return +1, max(0.0, min(1.0, abs(v))), "DICT_SCORE"
                if v < 0:
                    return -1, max(0.0, min(1.0, abs(v))), "DICT_SCORE"
                return 0, max(0.0, min(1.0, c)), "DICT_HOLD"
            if isinstance(r, (int, float)):
                v = float(r)
                if v > 0:
                    return +1, max(0.0, min(1.0, abs(v))), "NUM"
                if v < 0:
                    return -1, max(0.0, min(1.0, abs(v))), "NUM"
                return 0, 0.0, "ZERO"
            if isinstance(r, (list, tuple)) and r:
                s0 = r[0]
                if isinstance(s0, str):
                    s = str(s0).upper().strip()
                    c = _pp180_safe_float(r[1] if len(r) > 1 else 0.55, 0.55)
                    if s in ("BUY", "LONG"):
                        return +1, max(0.0, min(1.0, c)), "TUP"
                    if s in ("SELL", "SHORT"):
                        return -1, max(0.0, min(1.0, c)), "TUP"
                if isinstance(s0, (int, float)):
                    v = float(s0)
                    if v > 0:
                        return +1, max(0.0, min(1.0, abs(v))), "TUPNUM"
                    if v < 0:
                        return -1, max(0.0, min(1.0, abs(v))), "TUPNUM"
            return 0, 0.0, "HOLD"
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0, 0.0, "PARSE_ERR"

class _PP180LegacyResurrectionHub:
    def __init__(self, bot: Any):
        self.bot = bot
        self.sensors: List[_PP180LegacySensor] = []
        self.sleepers: List[Dict[str, Any]] = []
        self.ready = False
        self.last_summary = {}
        self._lock = threading.RLock()

    def discover_and_activate(self) -> None:
        with self._lock:
            self.sleepers = _pp180__deep_scan_sleepers()
            self.sensors = []
            for d in (self.sleepers or []):
                name = str(d.get("name") or "")
                kind = str(d.get("kind") or "")
                if not name:
                    continue
                obj = globals().get(name)
                if obj is None:
                    continue
                if kind == "class" and isinstance(obj, type):
                    inst = None
                    try:
                        inst = obj()
                    except Exception:
                        inst = None
                    if inst is None:
                        continue
                    f = None
                    for mn in ("signal", "predict", "compute", "run", "evaluate"):
                        try:
                            if callable(getattr(inst, mn, None)):
                                f = getattr(inst, mn)
                                break
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e)

                    if f is None:
                        continue
                    self.sensors.append(_PP180LegacySensor(name=name + "." + str(getattr(f, "__name__", "call")),
                                                          kind="class", obj=f, reason=str(d.get("reason"))))
                else:
                    if callable(obj):
                        self.sensors.append(_PP180LegacySensor(name=name, kind="def", obj=obj, reason=str(d.get("reason"))))
            self.ready = True
            try:
                setattr(self.bot, "_pp180_legacy_sleepers", list(self.sleepers))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

    def status_items(self) -> List[str]:
        with self._lock:
            s_on = sum(1 for s in (self.sensors or []) if getattr(s, "enabled", False))
            s_all = len(self.sensors or [])
            return [
                f"Legacy-Resurrection: {'ACTIVE' if self.ready else 'OFF'}",
                f"Legacy-Sensors: {s_on}/{s_all}",
            ]

    def eval_symbol(self, sym: str, symst: Any, depth_data: Dict[str, Any], bid: float, ask: float, mid: float) -> Dict[str, Any]:
        if not self.ready:
            return {"vote": "HOLD", "w": 0.0, "pump_hint": 0.0, "sensors": []}

        ctx = {
            "bot": self.bot,
            "sym": sym,
            "symst": symst,
            "depth_data": depth_data,
            "bid": float(bid or 0.0),
            "ask": float(ask or 0.0),
            "mid": float(mid or 0.0),
            "prices": list(getattr(symst, "prices", []) or []),
            "returns": list(getattr(symst, "returns", []) or []),
        }

        votes = 0
        wsum = 0.0
        pump_hint = 0.0
        detail = []
        with self._lock:
            for s in (self.sensors or []):
                if not getattr(s, "enabled", False):
                    continue
                v, c, note = s.eval_vote(ctx)
                if v != 0:
                    votes += v
                    wsum += float(c or 0.0)
                pump_hint += float(c or 0.0) * float(v)
                if len(detail) < 6:
                    detail.append(f"{s.name}:{'B' if v>0 else ('S' if v<0 else 'H')}@{c:.2f}")

        vote_dir = "HOLD"
        if votes > 0 and wsum > 0.5:
            vote_dir = "BUY"
        elif votes < 0 and wsum > 0.5:
            vote_dir = "SELL"
        out = {"vote": vote_dir, "w": max(0.0, min(1.0, float(wsum) / 3.0)), "pump_hint": float(pump_hint), "sensors": detail}
        try:
            self.last_summary[sym] = out
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return out

def _pp180_compute_volatility(symst: Any) -> float:
    try:
        rets = list(getattr(symst, "returns", []) or [])
        vals = [float(x) for x in rets if x is not None]
        if len(vals) < 8:
            return 0.0
        mu = sum(vals) / max(1, len(vals))
        var = sum((x - mu) ** 2 for x in vals) / max(1, (len(vals) - 1))
        v = math.sqrt(max(0.0, var))
        cap = _pp180_safe_float(os.getenv("PP180_VOL_CAP", "0.03"), 0.03)
        return max(0.0, min(1.0, v / max(1e-9, cap)))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

def _pp180_compute_pump(symst: Any) -> float:
    try:
        pxs = list(getattr(symst, "prices", []) or [])
        vals = [float(x) for x in pxs if x is not None]
        if len(vals) < 12:
            return 0.0
        a = vals[-1]
        b = vals[-10]
        if b <= 0:
            return 0.0
        ch = (a - b) / b
        k = _pp180_safe_float(os.getenv("PP180_PUMP_SOFT", "0.06"), 0.06)
        s = max(-1.0, min(1.0, ch / max(1e-9, k)))
        return float(s)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

def _pp180_bravery_index(vol01: float, pump: float, consensus_dir: str) -> float:
    try:
        cd = str(consensus_dir or "HOLD").upper()
    except Exception:
        cd = "HOLD"
    base = max(0.0, min(1.0, float(vol01))) * max(0.0, min(1.0, abs(float(pump))))
    if (pump > 0 and cd == "BUY") or (pump < 0 and cd == "SELL"):
        return float(base)
    return 0.0

def _pp180_intel_loop(bot: Any, stop_evt: Any, interval_sec: float) -> None:
    try:
        hub = getattr(bot, "_pp180_legacy_hub", None)
        if hub is None:
            hub = _PP180LegacyResurrectionHub(bot)
            setattr(bot, "_pp180_legacy_hub", hub)
        if not getattr(hub, "ready", False):
            hub.discover_and_activate()
    except Exception:
        hub = None

    while True:
        try:
            if stop_evt is not None and getattr(stop_evt, "is_set", lambda: False)():
                return
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            _pp180_pick_liquidity_mode_and_sovereign(bot)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        sovereign = getattr(bot, "_pp180_sovereign_wallet", None)
        states = getattr(bot, "states", {}) or {}
        st_obj = states.get(sovereign) if (sovereign and sovereign in states) else None
        if st_obj is None:
            try:
                st_obj = next(iter(states.values())) if states else None
            except Exception:
                st_obj = None

        per_symbol = getattr(st_obj, "per_symbol", {}) if st_obj is not None else {}
        syms = list(getattr(bot, "symbols", []) or [])
        depth_cache = getattr(bot, "_dash_depth_cache", {}) or {}

        results = {}
        for sym in syms:
            try:
                symst = per_symbol.get(sym)
                if symst is None:
                    continue
                depth_data = depth_cache.get(sym) or {}
                bid = _pp180_safe_float((depth_data.get("bid") if isinstance(depth_data, dict) else 0.0), 0.0)
                ask = _pp180_safe_float((depth_data.get("ask") if isinstance(depth_data, dict) else 0.0), 0.0)
                mid = _pp180_safe_float(getattr(symst, "last_mid", 0.0), 0.0)
                vol01 = _pp180_compute_volatility(symst)
                pump = _pp180_compute_pump(symst)
                leg = {"vote": "HOLD", "w": 0.0, "pump_hint": 0.0, "sensors": []}
                if hub is not None and getattr(hub, "ready", False):
                    leg = hub.eval_symbol(sym, symst, depth_data, bid, ask, mid)
                results[sym] = {"vol01": vol01, "pump": pump, "legacy": leg}
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_continue")
                continue
        try:
            setattr(bot, "_pp180_intel", results)
            setattr(bot, "_pp180_intel_ts", _pp180_now())
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            time.sleep(max(0.35, float(interval_sec)))
        except Exception:
            try:
                time.sleep(0.9)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

def _pp180_start_intel(bot: Any) -> None:
    if not _pp180_env_true("PP180_PARALLEL_INTEL", default="1"):
        return
    if getattr(bot, "_pp180_intel_started", False):
        return
    try:
        setattr(bot, "_pp180_intel_started", True)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        stop_evt = threading.Event()
        setattr(bot, "_pp180_intel_stop", stop_evt)
    except Exception:
        stop_evt = None

    try:
        interval_sec = float(os.getenv("PP180_INTEL_INTERVAL_SEC", "1.0") or 1.0)
    except Exception:
        interval_sec = 1.0

    th = threading.Thread(target=_pp180_intel_loop, args=(bot, stop_evt, interval_sec),
                          daemon=True, name="pp180-intel")
    try:
        setattr(bot, "_pp180_intel_thread", th)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        th.start()
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

