# ---- Logical Bravery Engine: sizing boost when pump-confirmed (still fee-guarded) ----
try:
    _pp180__orig_dyn_sizing = CognitiveCore.dynamic_sizing

    def _pp180_dynamic_sizing(self, equity_quote: float, confidence: float) -> float:
        base = float(_pp180__orig_dyn_sizing(self, equity_quote, confidence))
        bot = getattr(self, "bot", None)
        sym = getattr(self, "last_symbol", None) or getattr(bot, "_last_symbol", None)
        vol01 = 0.0
        pump = 0.0
        cd = "HOLD"

        try:
            if bot is not None and sym:
                intel = (getattr(bot, "_pp180_intel", {}) or {}).get(str(sym)) or {}
                vol01 = float(intel.get("vol01", 0.0) or 0.0)
                pump = float(intel.get("pump", 0.0) or 0.0)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            if bot is not None and sym:
                sovereign = getattr(bot, "_pp180_sovereign_wallet", None)
                st_obj = (getattr(bot, "states", {}) or {}).get(sovereign) if sovereign else None
                if st_obj is None:
                    st_obj = next(iter((getattr(bot, "states", {}) or {}).values())) if (getattr(bot, "states", {}) or {}) else None
                symst = (getattr(st_obj, "per_symbol", {}) or {}).get(str(sym)) if st_obj is not None else None
                if symst is not None:
                    cd = str(getattr(symst, "pp175_consensus_dir", "HOLD") or "HOLD").upper()
        except Exception:
            cd = "HOLD"

        bi = _pp180_bravery_index(vol01, pump, cd)
        try:
            setattr(self, "last_bravery_index", float(bi))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        mult = 1.0
        if bi > 0:
            try:
                cap = float(os.getenv("PP180_BRAVERY_SIZE_CAP", "1.55") or 1.55)
            except Exception:
                cap = 1.55
            mult = 1.0 + min(max(0.0, float(bi) * 0.9), max(0.0, cap - 1.0))

        out = float(base) * float(mult)
        try:
            hard = float(os.getenv("PP155_MAX_SIZE_FRAC", "0.35") or 0.35)
            out = max(0.0, min(out, hard))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return float(out)

    CognitiveCore.dynamic_sizing = _pp180_dynamic_sizing
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

