# ============================================================
# PP181: Surgical Integrity Fixes (REAL-TRADING SAFE)
# - Defer __main__ execution until after all patches are loaded
# - Guard against order placement inside legacy sensors / self-tests
# - Integrate PP180 legacy vote into PP175 weighted consensus (organic integration)
# - Lightweight runtime diagnostics (no heavy display)
# ============================================================

import threading as _pp181_threading
import traceback as _pp181_traceback
import logging as _pp181_logging
import os as _pp181_os
import time as _pp181_time

_pp181_tls = _pp181_threading.local()

def _pp181_logger():
    lg = _pp181_logging.getLogger("PP181")
    if not getattr(lg, "_pp181_inited", False):
        try:
            lg.setLevel(_pp181_logging.INFO)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            if not lg.handlers:
                # stderr only by default (Termux friendly). Enable file via PP181_LOG_FILE=1
                h = _pp181_logging.StreamHandler()
                fmt = _pp181_logging.Formatter("%(asctime)s %(levelname)s %(message)s")
                h.setFormatter(fmt)
                lg.addHandler(h)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            if str(_pp181_os.getenv("PP181_LOG_FILE", "0") or "0").strip().lower() in ("1","true","yes","on"):
                fh = _pp181_logging.FileHandler(_pp181_os.getenv("PP181_LOG_PATH","pp181_runtime.log") or "pp181_runtime.log")
                fmt = _pp181_logging.Formatter("%(asctime)s %(levelname)s %(message)s")
                fh.setFormatter(fmt)
                lg.addHandler(fh)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            lg._pp181_inited = True
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    return lg

def _pp181_event(bot, msg: str, level: str = "INFO", exc: BaseException = None):
    # bounded event feed (if bot has _events deque/list)
    try:
        ev = getattr(bot, "_events", None)
        if ev is not None:
            try:
                ev.append(str(msg))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # optional logging
    try:
        lg = _pp181_logger()
        if exc is not None:
            lg.warning("%s | exc=%r", msg, exc, exc_info=True)
        else:
            getattr(lg, level.lower(), lg.info)("%s", msg)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

