# Wrap PP180 legacy sensor eval so it can never place orders, and failures are recorded
try:
    _pp181__orig_eval_vote = _PP180LegacySensor.eval_vote
    def _pp181_eval_vote(self, ctx):
        if not getattr(self, "enabled", True):
            return 0, 0.0, "DISABLED"
        prev = bool(getattr(_pp181_tls, "block_orders", False))
        _pp181_tls.block_orders = True
        try:
            return _pp181__orig_eval_vote(self, ctx)
        except Exception as e:
            try:
                bot = (ctx or {}).get("bot")
            except Exception:
                bot = None
            if bot is not None:
                _pp181_event(bot, f"PP181 LEGACY SENSOR FAIL: {getattr(self,'name','?')} | {e!r}", level="WARNING", exc=e)
            # preserve PP180 behavior: disable after repeated failures happens inside original
            raise
        finally:
            _pp181_tls.block_orders = prev
    _PP180LegacySensor.eval_vote = _pp181_eval_vote
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

# Improve PP180 discover_and_activate: instantiate legacy classes with (bot) if possible
try:
    _pp181__orig_discover = _PP180LegacyResurrectionHub.discover_and_activate
    def _pp181_discover_and_activate(self):
        try:
            return _pp181__orig_discover(self)
        except Exception as e:
            try:
                _pp181_event(getattr(self, "bot", None), f"PP181 discover_and_activate fallback: {e!r}", level="WARNING", exc=e)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            # Fallback: safer activation with constructor probing
            with getattr(self, "_lock", _pp181_threading.RLock()):
                self.sleepers = []
                try:
                    self.sleepers = _pp180__deep_scan_sleepers()
                except Exception:
                    self.sleepers = []
                self.sensors = []
                cap = 48
                try:
                    cap = int(_pp181_os.getenv("PP180_SLEEPERS_CAP","48") or 48)
                except Exception:
                    cap = 48
                for d in (self.sleepers or [])[:max(0, cap)]:
                    try:
                        name = str(d.get("name") or "")
                        kind = str(d.get("kind") or "")
                        if not name:
                            continue
                        obj = globals().get(name)
                        if obj is None:
                            continue
                        if kind == "class" and isinstance(obj, type):
                            inst = None
                            for args in ((), (getattr(self,"bot",None),)):
                                try:
                                    inst = obj(*args)
                                    break
                                except Exception:
                                    inst = None
                            if inst is None:
                                continue
                            f = None
                            for mn in ("signal","predict","compute","run","evaluate"):
                                try:
                                    if callable(getattr(inst, mn, None)):
                                        f = getattr(inst, mn)
                                        break
                                except Exception as _pp200_e:
                                    _pp200_heal(_pp200_e)

                            if f is None:
                                continue
                            self.sensors.append(_PP180LegacySensor(name=name+"."+str(getattr(f,"__name__","call")),
                                                                   kind="class", obj=f, reason=str(d.get("reason") or "")))
                        else:
                            if callable(obj):
                                self.sensors.append(_PP180LegacySensor(name=name, kind="def", obj=obj, reason=str(d.get("reason") or "")))
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_continue")
                        continue
                self.ready = True
    _PP180LegacyResurrectionHub.discover_and_activate = _pp181_discover_and_activate
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

# Organic integration: feed PP180 legacy vote into PP175 consensus if strong enough
