try:
    import ast as _pp185_ast
    import io as _pp185_io
    import tokenize as _pp185_tokenize
    import keyword as _pp185_keyword
    from collections import Counter as _pp185_Counter
except Exception:
    _pp185_ast = None
    _pp185_io = None
    _pp185_tokenize = None
    _pp185_keyword = None
    _pp185_Counter = None

_pp185_tls = threading.local()

def _pp185_env_int(name: str, default: int) -> int:
    try:
        v = os.getenv(name, str(default))
        return int(float(v))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return int(default)

def _pp185_env_float(name: str, default: float) -> float:
    try:
        v = os.getenv(name, str(default))
        return float(v)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(default)

def _pp185_in_sensor() -> bool:
    try:
        return bool(getattr(_pp185_tls, "block_orders", False))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

class _PP185Sensor:
    __slots__ = ("name", "kind", "obj", "enabled", "fail", "last", "reason", "score01")
    def __init__(self, name: str, kind: str, obj: Any, reason: str = ""):
        self.name = str(name)
        self.kind = str(kind)
        self.obj = obj
        self.enabled = True
        self.fail = 0
        self.last = None
        self.reason = str(reason)
        self.score01 = 0.0  # rolling reliability (0..1)

    def _call(self, ctx: Dict[str, Any]) -> Any:
        f = self.obj
        # allow plain callable, bound method, or object with .signal/.predict
        if not callable(f):
            # try adaptor
            for mn in ("signal", "predict", "compute", "run", "evaluate"):
                try:
                    g = getattr(f, mn, None)
                    if callable(g):
                        f = g
                        break
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_continue")
                    continue
        if not callable(f):
            return None

        # signature aware best-effort (no heavy inspect if missing)
        sig = None
        try:
            if _pp180_inspect is not None:
                sig = _pp180_inspect.signature(f)
        except Exception:
            sig = None

        if sig is None:
            # safest: attempt calling with no args
            return f()

        kwargs = {}
        sym = ctx.get("sym")
        symst = ctx.get("symst")
        bot = ctx.get("bot")
        depth = ctx.get("depth_data") if isinstance(ctx, dict) else None
        if depth is None:
            depth = ctx.get("depth") if isinstance(ctx, dict) else None
        bid = ctx.get("bid")
        ask = ctx.get("ask")
        mid = ctx.get("mid")

        # common parameter mapping
        for p in list(sig.parameters.keys()):
            if p in ("symbol", "sym", "pair"):
                kwargs[p] = sym
            elif p in ("state", "symst", "st"):
                kwargs[p] = symst
            elif p in ("bot", "engine", "selfbot"):
                kwargs[p] = bot
            elif p in ("depth", "orderbook", "book"):
                kwargs[p] = depth
            elif p == "bid":
                kwargs[p] = bid
            elif p == "ask":
                kwargs[p] = ask
            elif p == "mid":
                kwargs[p] = mid

        # reject missing required params
        for p, prm in sig.parameters.items():
            if prm.default is prm.empty and prm.kind in (prm.POSITIONAL_ONLY, prm.POSITIONAL_OR_KEYWORD) and p not in kwargs:
                raise TypeError(f"missing required param: {p}")

        return f(**kwargs)

    def eval_vote(self, ctx: Dict[str, Any]) -> Tuple[int, float, str]:
        if not self.enabled:
            return 0, 0.0, "DISABLED"
        try:
            # hard safety: never allow placing orders inside sensor context
            setattr(_pp185_tls, "block_orders", True)
            r = self._call(ctx)
            self.last = r
        except Exception as e:
            self.fail += 1
            if self.fail >= 3:
                self.enabled = False
            return 0, 0.0, f"ERR:{type(e).__name__}"
        finally:
            try:
                setattr(_pp185_tls, "block_orders", False)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        try:
            # normalize to directional vote
            if isinstance(r, dict):
                s = str(r.get("signal") or r.get("side") or r.get("action") or "").upper().strip()
                c = _pp180_safe_float(r.get("confidence", r.get("conf", 0.0)), 0.0)
                if s in ("BUY", "LONG"):
                    return +1, max(0.0, min(1.0, c or 0.55)), "DICT"
                if s in ("SELL", "SHORT"):
                    return -1, max(0.0, min(1.0, c or 0.55)), "DICT"
                v = _pp180_safe_float(r.get("score", r.get("value", 0.0)), 0.0)
                if v > 0:
                    return +1, max(0.0, min(1.0, abs(v))), "DICT_SCORE"
                if v < 0:
                    return -1, max(0.0, min(1.0, abs(v))), "DICT_SCORE"
                return 0, 0.0, "DICT_HOLD"
            if isinstance(r, (list, tuple)) and len(r) >= 1:
                s0 = r[0]
                if isinstance(s0, str):
                    s = str(s0).upper().strip()
                    c = _pp180_safe_float(r[1] if len(r) > 1 else 0.55, 0.55)
                    if s in ("BUY", "LONG"):
                        return +1, max(0.0, min(1.0, c)), "TUP"
                    if s in ("SELL", "SHORT"):
                        return -1, max(0.0, min(1.0, c)), "TUP"
                if isinstance(s0, (int, float)):
                    v = float(s0)
                    if v > 0:
                        return +1, max(0.0, min(1.0, abs(v))), "TUPNUM"
                    if v < 0:
                        return -1, max(0.0, min(1.0, abs(v))), "TUPNUM"
            if isinstance(r, (int, float)):
                v = float(r)
                if v > 0:
                    return +1, max(0.0, min(1.0, abs(v))), "NUM"
                if v < 0:
                    return -1, max(0.0, min(1.0, abs(v))), "NUM"
            return 0, 0.0, "HOLD"
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0, 0.0, "PARSE_ERR"


