def _pp185_linreg_slope(vals: List[float]) -> float:
    try:
        n = len(vals)
        if n < 3:
            return 0.0
        x = list(range(n))
        sx = sum(x)
        sy = sum(vals)
        sxx = sum(t*t for t in x)
        sxy = sum(x[i] * vals[i] for i in range(n))
        den = (n * sxx - sx * sx)
        if abs(den) < 1e-12:
            return 0.0
        return (n * sxy - sx * sy) / den
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

class FractalPatternDetector:
    """🌀 Real fractal pattern detector (bullish/bearish fractals)"""
    def detect_fractals(self, series: List[float], period: int = 5) -> List[Dict[str, Any]]:
        out = []
        try:
            p = max(2, int(period))
            n = len(series)
            if n < (2 * p + 3):
                return out
            for i in range(p, n - p):
                win = series[i - p:i + p + 1]
                v = series[i]
                if v == max(win):
                    out.append({"type": "BEAR", "i": i, "price": v})
                elif v == min(win):
                    out.append({"type": "BULL", "i": i, "price": v})
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return out
        return out

    def signal(self, symst: Any, period: int = 5) -> Dict[str, Any]:
        try:
            pxs = list(getattr(symst, "prices", []) or [])
            vals = [float(x) for x in pxs if x is not None]
            if len(vals) < 30:
                return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
            fr = self.detect_fractals(vals[-160:], period=period)
            if not fr:
                return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
            last = fr[-60:]
            bulls = sum(1 for f in last if f.get("type") == "BULL")
            bears = sum(1 for f in last if f.get("type") == "BEAR")
            diff = bulls - bears
            conf = max(0.0, min(1.0, abs(diff) / 6.0))
            if diff >= 2:
                return {"signal": "BUY", "confidence": max(0.15, conf), "score": +conf, "bulls": bulls, "bears": bears}
            if diff <= -2:
                return {"signal": "SELL", "confidence": max(0.15, conf), "score": -conf, "bulls": bulls, "bears": bears}
            return {"signal": "HOLD", "confidence": conf * 0.4, "score": 0.0, "bulls": bulls, "bears": bears}
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}

class HurstRegimeSensor:
    """📈 Real Hurst exponent regime sensor (trend vs mean-revert)"""
    def _hurst(self, series: List[float]) -> float:
        try:
            vals = [float(x) for x in series if x is not None]
            n = len(vals)
            if n < 40:
                return 0.5
            # log returns
            rets = []
            for i in range(1, n):
                a = vals[i-1]
                b = vals[i]
                if a <= 0 or b <= 0:
                    continue
                rets.append(math.log(b / a))
            if len(rets) < 30:
                return 0.5
            # R/S across a few chunk sizes
            chunks = [8, 12, 16, 24, 32]
            xs, ys = [], []
            for c in chunks:
                if len(rets) < c * 4:
                    continue
                segs = len(rets) // c
                rs_vals = []
                for s in range(segs):
                    seg = rets[s*c:(s+1)*c]
                    if len(seg) < 4:
                        continue
                    m = sum(seg)/len(seg)
                    dev = [x - m for x in seg]
                    z = []
                    acc = 0.0
                    for d in dev:
                        acc += d
                        z.append(acc)
                    R = max(z) - min(z)
                    S = math.sqrt(sum(d*d for d in dev)/max(1, len(dev)-1))
                    if S > 1e-12:
                        rs_vals.append(R / S)
                if rs_vals:
                    rs = sum(rs_vals) / len(rs_vals)
                    if rs > 1e-12:
                        xs.append(math.log(c))
                        ys.append(math.log(rs))
            if len(xs) < 2:
                return 0.5
            slope = _pp185_linreg_slope(ys) / max(1e-12, _pp185_linreg_slope(xs))
            # clamp
            return max(0.0, min(1.0, float(slope)))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.5

    def signal(self, symst: Any) -> Dict[str, Any]:
        try:
            pxs = list(getattr(symst, "prices", []) or [])
            vals = [float(x) for x in pxs if x is not None]
            if len(vals) < 60:
                return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
            w = vals[-220:]
            H = self._hurst(w)
            # direction via slope
            slope = _pp185_linreg_slope(w[-40:])
            trend_dir = +1 if slope > 0 else (-1 if slope < 0 else 0)
            conf = max(0.0, min(1.0, abs(H - 0.5) / 0.18))
            if H >= 0.56 and trend_dir != 0:
                return {"signal": "BUY" if trend_dir > 0 else "SELL", "confidence": max(0.12, conf), "score": float(trend_dir) * conf, "hurst": H}
            if H <= 0.44:
                # mean-reversion: compare last to ema_slow if available
                ema = float(getattr(symst, "ema_slow", 0.0) or 0.0)
                last = w[-1]
                if ema > 0:
                    dirn = -1 if last > ema else +1
                    return {"signal": "BUY" if dirn > 0 else "SELL", "confidence": max(0.10, conf*0.8), "score": float(dirn) * conf*0.8, "hurst": H}
            return {"signal": "HOLD", "confidence": conf*0.25, "score": 0.0, "hurst": H}
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}

class KalmanDenoiserSensor:
    """🎛️ Real 1D Kalman denoiser -> slope vote"""
    def _kalman(self, series: List[float], q: float = 1e-5, r: float = 1e-2) -> List[float]:
        x = []
        try:
            vals = [float(v) for v in series if v is not None]
            if len(vals) < 6:
                return vals
            xhat = vals[0]
            P = 1.0
            for z in vals:
                # predict
                P = P + q
                # update
                K = P / (P + r)
                xhat = xhat + K * (z - xhat)
                P = (1 - K) * P
                x.append(float(xhat))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return x
        return x

    def signal(self, symst: Any) -> Dict[str, Any]:
        try:
            pxs = list(getattr(symst, "prices", []) or [])
            vals = [float(x) for x in pxs if x is not None]
            if len(vals) < 50:
                return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
            w = vals[-140:]
            sm = self._kalman(w, q=_pp185_env_float("PP185_KALMAN_Q", 1e-5), r=_pp185_env_float("PP185_KALMAN_R", 1e-2))
            if len(sm) < 20:
                return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
            slope = _pp185_linreg_slope(sm[-25:])
            # normalize by volatility proxy
            mu = sum(w[-60:]) / 60.0
            var = sum((x - mu) ** 2 for x in w[-60:]) / 59.0
            vol = math.sqrt(max(1e-12, var))
            s = slope / max(1e-9, vol)
            conf = max(0.0, min(1.0, abs(s) * 3.2))
            if s > 0.25:
                return {"signal": "BUY", "confidence": max(0.10, conf), "score": +conf}
            if s < -0.25:
                return {"signal": "SELL", "confidence": max(0.10, conf), "score": -conf}
            return {"signal": "HOLD", "confidence": conf*0.2, "score": 0.0}
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}

class TriangleArbitrageSensor:
    """
    ⚖️ Real triangle mispricing sensor (USDTIRT + XUSDT vs XIRT)
    - فقط سنسور تصمیم‌یار است (نه اجرای آربیتراژ واقعی).
    """
    def __init__(self, thresh_pct: float = 0.009):
        self.thresh_pct = float(thresh_pct)

    def signal(self, bot: Any, sym: str, symst: Any) -> Dict[str, Any]:
        try:
            # need USDTIRT
            states = None
            try:
                st_obj = getattr(bot, "states", None)
                states = getattr(st_obj, "per_symbol", None) if st_obj is not None else None
            except Exception:
                states = None
            if not isinstance(states, dict) or not states:
                return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}

            us = states.get("USDTIRT") or states.get("USDT-IRT") or states.get("USDT/IRT")
            if us is None:
                return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
            us_mid = _pp180_safe_float(getattr(us, "last_mid", 0.0), 0.0)
            if us_mid <= 0:
                return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}

            s = str(sym).upper().replace("/", "").replace("-", "")
            if s.endswith("USDT") and s != "USDTIRT":
                base = s[:-4]
                # implied IRT price via USDT path
                xus_mid = _pp180_safe_float(getattr(symst, "last_mid", 0.0), 0.0)
                if xus_mid <= 0:
                    return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
                implied = xus_mid * us_mid
                xirt = states.get(base + "IRT")
                if xirt is None:
                    return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
                xirt_mid = _pp180_safe_float(getattr(xirt, "last_mid", 0.0), 0.0)
                if xirt_mid <= 0:
                    return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
                diff = (xirt_mid - implied) / max(1e-9, implied)
                # If XIRT cheaper than implied => undervalued in IRT market (potential upward correction)
                # Use as directional confirmation (low weight)
                t = float(self.thresh_pct)
                if diff <= -t:
                    conf = max(0.0, min(1.0, abs(diff) / (t * 2.2)))
                    return {"signal": "BUY", "confidence": max(0.10, conf*0.7), "score": +conf*0.7, "mispricing": diff}
                if diff >= t:
                    conf = max(0.0, min(1.0, abs(diff) / (t * 2.2)))
                    return {"signal": "SELL", "confidence": max(0.10, conf*0.7), "score": -conf*0.7, "mispricing": diff}
            return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return {"signal": "HOLD", "confidence": 0.0, "score": 0.0}


