def _pp185_token_counts(src: str) -> Dict[str, int]:
    if _pp185_tokenize is None or _pp185_io is None or _pp185_Counter is None or _pp185_keyword is None:
        return {}
    try:
        toks = list(_pp185_tokenize.generate_tokens(_pp185_io.StringIO(src).readline))
        names = []
        for tt, ts, *_ in toks:
            if tt == _pp185_tokenize.NAME and ts and ts not in _pp185_keyword.kwlist:
                names.append(ts)
        return dict(_pp185_Counter(names))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return {}

def _pp185_is_api_sensitive(name: str) -> bool:
    n = str(name).lower()
    # anything that might touch auth/wallet/order should never be a legacy sensor
    bad = ("token", "auth", "login", "wallet", "balance", "create_order", "order", "buy", "sell", "withdraw", "deposit", "signature")
    return any(b in n for b in bad)

def _pp185_keyterm_hit(name: str) -> bool:
    n = str(name).lower()
    terms = ("arbitrage", "arb", "fractal", "harmonic", "gann", "elliott", "kalman", "hurst", "noise", "denoise",
             "filter", "zscore", "mean", "revert", "spread", "imbalance", "regime", "volatility", "pump")
    return any(t in n for t in terms)

def _pp185_discover_class_methods(src: str) -> List[Tuple[str, str]]:
    """
    returns list of (ClassName, method_name) candidates from AST
    """
    if _pp185_ast is None:
        return []
    try:
        t = _pp185_ast.parse(src)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return []
    out = []
    try:
        for node in t.body:
            if isinstance(node, _pp185_ast.ClassDef):
                cname = node.name
                # class-level keyword gate
                class_hit = _pp185_keyterm_hit(cname) or ("detector" in cname.lower()) or ("strategy" in cname.lower())
                for item in node.body:
                    if isinstance(item, _pp185_ast.FunctionDef):
                        mn = item.name
                        if mn.startswith("__"):
                            continue
                        # only harvest risky names if keyterm appears (avoid generic 'run')
                        if _pp185_is_api_sensitive(mn):
                            continue
                        if class_hit or _pp185_keyterm_hit(mn) or _pp920_re.match(r"^_pp(\d+)_", mn or ""):
                            out.append((cname, mn))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return out
    return out

def _pp185_build_sensors(bot: Any) -> List[_PP185Sensor]:
    try:
        src = _pp180__read_source()
    except Exception:
        src = None
    if not src:
        return []

    counts = _pp185_token_counts(src)

    sensors: List[_PP185Sensor] = []

    # 1) revive real algorithmic detectors (guaranteed-safe & deterministic)
    try:
        sensors.append(_PP185Sensor("FractalPatternDetector", "class", FractalPatternDetector(), "revived"))
        sensors.append(_PP185Sensor("HurstRegimeSensor", "class", HurstRegimeSensor(), "revived"))
        sensors.append(_PP185Sensor("KalmanDenoiserSensor", "class", KalmanDenoiserSensor(), "revived"))
        sensors.append(_PP185Sensor("TriangleArbitrageSensor", "class", TriangleArbitrageSensor(), "revived"))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # 2) harvest orphan top-level functions/classes already present but ignored
    try:
        sleepers = []
        try:
            sleepers = _pp180__deep_scan_sleepers(max_ver=150)  # a bit wider for 'ignored' capabilities
        except Exception:
            sleepers = []
        for it in sleepers or []:
            try:
                name = it.get("name")
                if not name or _pp185_is_api_sensitive(name):
                    continue
                # prefer truly orphan defs: token count == 1 (only definition)
                if counts and counts.get(name, 99) > 2 and not _pp185_keyterm_hit(name):
                    continue
                obj = globals().get(name)
                if obj is None:
                    continue
                if callable(obj) or isinstance(obj, type):
                    sensors.append(_PP185Sensor(str(name), str(it.get("kind") or "def"), obj, str(it.get("reason") or "")))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_continue")
                continue
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # 3) harvest class methods (often ignored by PP180 because globals().get(method) fails)
    try:
        cap = _pp185_env_int("PP185_METHOD_CAP", 36)
        cm = _pp185_discover_class_methods(src)[:max(12, cap)]
        for cname, mn in cm:
            try:
                if _pp185_is_api_sensitive(cname) or _pp185_is_api_sensitive(mn):
                    continue
                cls = globals().get(cname)
                if not isinstance(cls, type):
                    continue
                inst = None
                try:
                    inst = cls()
                except Exception:
                    inst = None
                if inst is None:
                    continue
                f = getattr(inst, mn, None)
                if not callable(f):
                    continue
                sensors.append(_PP185Sensor(f"{cname}.{mn}", "method", f, "class-method"))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_continue")
                continue
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # cap + dedupe
    cap = _pp185_env_int("PP185_SENSOR_CAP", 64)
    out = []
    seen = set()
    for s in sensors:
        n = s.name
        if n in seen:
            continue
        seen.add(n)
        out.append(s)
        if len(out) >= max(16, cap):
            break
    return out


