# Install: inject sensors into PP180 legacy hub & hard-block orders inside sensors
# ----------------------------

def _pp185_install_sensor_order_guard() -> None:
    try:
        cls = globals().get("ArzPlusBot")
        if cls is None:
            cls = globals().get("PP5LiveTripleWallet")
        if cls is None:
            return
        obuy = getattr(cls, "_place_buy", None)
        osell = getattr(cls, "_place_sell", None)

        if callable(obuy):
            def _pp185_buy_guard(self, api, wname, sym, qty, price, __ob=obuy):
                if _pp185_in_sensor():
                    return {"ok": False, "status": 0, "error": "PP185_SENSOR_GUARD", "reason": "orders-blocked-in-sensor"}
                return __ob(self, api, wname, sym, qty, price)
            setattr(cls, "_place_buy", _pp185_buy_guard)

        if callable(osell):
            def _pp185_sell_guard(self, api, wname, sym, qty, price, __os=osell):
                if _pp185_in_sensor():
                    return {"ok": False, "status": 0, "error": "PP185_SENSOR_GUARD", "reason": "orders-blocked-in-sensor"}
                return __os(self, api, wname, sym, qty, price)
            setattr(cls, "_place_sell", _pp185_sell_guard)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

def _pp185_patch_legacy_hub() -> None:
    try:
        Hub = globals().get("_PP180LegacyResurrectionHub")
        if Hub is None:
            return
        orig = getattr(Hub, "discover_and_activate", None)
        if not callable(orig):
            return

        def _pp185_discover_and_activate(self):
            # keep original discovery
            try:
                orig(self)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            try:
                bot = getattr(self, "bot", None)
                extra = _pp185_build_sensors(bot)
                if extra:
                    cur = list(getattr(self, "sensors", []) or [])
                    # wrap to PP180 sensor format (compatible: needs .eval_vote)
                    # We can directly append because _PP185Sensor has eval_vote
                    cur.extend(extra)
                    # dedupe by name
                    seen = set()
                    ded = []
                    for s in cur:
                        try:
                            n = getattr(s, "name", None)
                        except Exception:
                            n = None
                        if not n or n in seen:
                            continue
                        seen.add(n)
                        ded.append(s)
                    setattr(self, "sensors", ded)
                try:
                    setattr(self, "ready", True)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                # publish report for dashboard
                try:
                    rep = {
                        "active": [getattr(s, "name", "?") for s in (getattr(self, "sensors", []) or []) if getattr(s, "enabled", True)],
                        "disabled": [getattr(s, "name", "?") for s in (getattr(self, "sensors", []) or []) if not getattr(s, "enabled", True)],
                        "count": len(getattr(self, "sensors", []) or []),
                    }
                    setattr(bot, "_pp185_legacy_report", rep)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

            except Exception:
                try:
                    setattr(self, "ready", True)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

        setattr(Hub, "discover_and_activate", _pp185_discover_and_activate)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

def _pp185_patch_cognitive_overlay() -> None:
    """
    Organic integration: use pp180 intel legacy vote + pp185 sensors as secondary perceptual layer
    into PP175 weighted consensus, without touching API.
    """
    try:
        orig = _pp5_postprocess_score
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return
    try:
        def _pp185_postprocess_score(self, sym, symst, bid, ask, mid, depth, rsi=None, mom=None, trend_vector=None, **kw):
            out = orig(self, sym, symst, bid, ask, mid, depth, rsi=rsi, mom=mom, trend_vector=trend_vector, **kw)
            try:
                bot = getattr(self, "bot", None)
                intel = getattr(bot, "_pp180_intel", {}) if bot is not None else {}
                pack = intel.get(sym) if isinstance(intel, dict) else None
                leg = (pack or {}).get("legacy") if isinstance(pack, dict) else None
                # record for dashboard: bravery/logical etc already exist; here only expose revived count
                if bot is not None and hasattr(bot, "_pp185_legacy_report"):
                    pass
                # If legacy strongly agrees with current direction, nudge confidence (but keep fee-guards & consensus)
                if isinstance(out, dict) and isinstance(leg, dict):
                    v = str(leg.get("vote") or "HOLD").upper().strip()
                    w = _pp180_safe_float(leg.get("w", 0.0), 0.0)
                    if w >= 0.55 and v in ("BUY", "SELL"):
                        try:
                            conf = float(out.get("confidence", 0.0) or 0.0)
                            bump = min(0.08, 0.06 * w)
                            out["confidence"] = max(0.0, min(1.0, conf + bump))
                            out["pp185_secondary"] = {"legacy_vote": v, "legacy_w": w, "bump": bump}
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e)

            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            return out
        globals()["_pp5_postprocess_score"] = _pp185_postprocess_score
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

def _pp185_patch_dashboard_reports() -> None:
    try:
        DM = globals().get("DashboardManager")
        if DM is None:
            return
        orig = getattr(DM, "_reports_panel", None)
        if not callable(orig):
            return

        def _pp185_reports_panel(self, bot):
            p = orig(self, bot)
            try:
                rep = getattr(bot, "_pp185_legacy_report", None)
                if not isinstance(rep, dict):
                    return p
                active = rep.get("active") or []
                disabled = rep.get("disabled") or []
                # try to render with rich if available; otherwise keep original
                try:
                    from rich.panel import Panel
                    from rich.text import Text
                    title = Text("DIGITAL CONSCIENCE / LEGACY", style="bold yellow")
                    body = Text()
                    body.append(f"Active Sensors: {len(active)}\n", style="bold green")
                    if active:
                        body.append(" • " + ", ".join(active[:14]) + ("\n" if len(active) > 14 else "\n"), style="green")
                    if disabled:
                        body.append(f"Disabled: {len(disabled)}\n", style="bold red")
                    return Panel(body, title=title, border_style="yellow")
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return p
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return p

        setattr(DM, "_reports_panel", _pp185_reports_panel)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

try:
    _pp185_install_sensor_order_guard()
    _pp185_patch_legacy_hub()
    _pp185_patch_cognitive_overlay()
    _pp185_patch_dashboard_reports()
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

# ---- Version stamp ----
try:
    _pp181_os.environ["PP_VERSION"] = str(_pp181_os.getenv("PP_VERSION", "v186") or "v181")
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

