# ============================================================
# PP187: DEEP ORPHAN RECLAMATION (NO REWRITE / SAFE WIRING)
# - هدف: زنده کردن همه قابلیت‌های یتیم/مخفی موجود در لایه‌های کد
# - بدون بازنویسی الگوریتم‌های قدیمی: فقط کشف/اتصال/ایمن‌سازی
# - ایمنی: جلوگیری از هرگونه ثبت اردر از داخل قابلیت‌های احیاشده
# ============================================================

try:
    import inspect as _pp187_inspect
    import ast as _pp187_ast
except Exception:  # pragma: no cover
    _pp187_inspect = None
    _pp187_ast = None

def _pp187__safe_str(x):
    try:
        return str(x)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return ""

def _pp187__read_src():
    # reuse PP170 reader if present
    try:
        return _pp170__read_source()
    except Exception:
        try:
            with open(__file__, "r", encoding="utf-8", errors="ignore") as f:
                return f.read()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return ""

def _pp187__legacy_keyterm_hit(name: str) -> bool:
    try:
        n = str(name or "").lower()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False
    terms = (
        "arbitrage", "arb", "fractal", "harmonic", "gann", "elliott", "wave",
        "kalman", "hurst", "denoise", "noise", "filter", "entropy", "garch",
        "cointegr", "pairs", "spread", "zscore", "mean", "revert", "stationary",
        "pattern", "regime", "volatility", "pump", "imbalance",
        "bayes", "markov", "hmm", "lstm", "nlp", "news", "sentiment",
        "genetic", "dna", "evolution",
    )
    return any(t in n for t in terms)

def _pp187__is_probably_safe_callable(obj) -> bool:
    """
    Conservative safety filter:
    - Allow analysis-like functions; reject anything that looks like order/token/network manipulator.
    - This does NOT modify the callable; it only decides whether to EXECUTE it.
    """
    try:
        nm = _pp187__safe_str(getattr(obj, "__name__", ""))
        low = nm.lower()
        # hard deny by name
        deny = ("create_order", "send_order", "place_order", "order_create",
                "_place_buy", "_place_sell", "withdraw", "deposit",
                "wallet", "token", "apikey",
                "requests", "urllib", "socket", "subprocess", "system", "os.system", "exec", "eval")
        if any(d in low for d in deny):
            return False
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

    # Source scan for risky tokens (best-effort)
    try:
        if _pp187_inspect is not None:
            sc = _pp187__safe_str(_pp187_inspect.getsource(obj)).lower()
            deny2 = ("create_order", "_place_buy", "_place_sell", "requests.", "urllib", "socket", "subprocess", "os.system",
                     "open(", "import requests", "import urllib", "import socket")
            if any(d in sc for d in deny2):
                return False
    except Exception:
        # if source can't be read, don't block
        pass
    return True

def _pp187__count_calls(src: str, name: str) -> int:
    try:
        # calls like name( ; exclude def name(
        pat = re.compile(r'(?<!def\s)\b' + re.escape(name) + r'\s*\(', re.M)
        return len(pat.findall(src))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0

def _pp187__count_method_calls(src: str, mname: str) -> int:
    try:
        pat = re.compile(r'\.' + re.escape(mname) + r'\s*\(', re.M)
        return len(pat.findall(src))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0

def _pp187__version_of(name: str):
    try:
        mm = _pp920_re.match(r'^_pp(\d+)_', str(name))
        if mm:
            return int(mm.group(1))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return None
    return None

def _pp187__deep_discover_orphans(src: str):
    """
    Returns descriptors:
      ("func", func_name)
      ("method", class_name, method_name)
    Orphans = defs/methods with zero callsites (heuristic), prioritized by legacy keywords.
    """
    out = []
    if not src:
        return out

    # -------- module-level functions --------
    try:
        for m in re.finditer(r'^\s*def\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(', src, re.M):
            nm = m.group(1)
            if not nm or nm.startswith("__"):
                continue
            calls = _pp187__count_calls(src, nm)
            if calls > 0:
                continue

            v = _pp187__version_of(nm)
            allow = False
            try:
                if v is not None and int(v) < 110:
                    allow = True
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            try:
                if not allow and _pp187__legacy_keyterm_hit(nm):
                    allow = True
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            try:
                if (not allow) and ("_pp170__legacy_keyword" in globals()) and _pp170__legacy_keyword(nm):
                    allow = True
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            if not allow:
                # extra heuristic: nearby "PP###" tag lower than 110
                try:
                    ctx = src[max(0, m.start() - 900):m.start()]
                    tags = re.findall(r'PP(\d{1,3})', ctx)
                    if tags and int(tags[-1]) < 110:
                        allow = True
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

            if allow:
                out.append(("func", nm))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # -------- class methods (AST) --------
    if _pp187_ast is None:
        return out
    try:
        t = _pp187_ast.parse(src)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return out

    for node in getattr(t, "body", []) or []:
        try:
            if not isinstance(node, _pp187_ast.ClassDef):
                continue
            cname = _pp187__safe_str(getattr(node, "name", ""))
            if not cname:
                continue
            lowc = cname.lower()
            class_hit = False
            try:
                if ("_pp170__legacy_keyword" in globals()) and _pp170__legacy_keyword(cname):
                    class_hit = True
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            try:
                if _pp187__legacy_keyterm_hit(cname):
                    class_hit = True
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            if not class_hit and not any(k in lowc for k in ("strategy", "signal", "detector", "analy", "arb", "stat", "filter", "model", "pattern")):
                continue

            for item in getattr(node, "body", []) or []:
                if isinstance(item, _pp187_ast.FunctionDef):
                    mn = _pp187__safe_str(getattr(item, "name", ""))
                    if not mn or mn.startswith("__"):
                        continue
                    if _pp187__count_method_calls(src, mn) > 0:
                        continue
                    allow = False
                    try:
                        if _pp187__legacy_keyterm_hit(mn) or class_hit:
                            allow = True
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    try:
                        if (not allow) and ("_pp170__legacy_keyword" in globals()) and _pp170__legacy_keyword(mn):
                            allow = True
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    try:
                        v = _pp187__version_of(mn)
                        if (not allow) and (v is not None) and int(v) < 110:
                            allow = True
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    if allow:
                        out.append(("method", cname, mn))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_continue")
            continue
    return out

def _pp187__can_instantiate(cls) -> bool:
    if cls is None or _pp187_inspect is None:
        return False
    try:
        sig = _pp187_inspect.signature(cls)
        for p in sig.parameters.values():
            if p.name in ("self",):
                continue
            if p.default is _pp187_inspect._empty and p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD):
                return False
        return True
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

def _pp187__materialize_descriptor(desc):
    """
    Converts descriptor -> callable (bound if possible)
    Returns (callable, label) or (None, label)
    """
    try:
        if not isinstance(desc, (tuple, list)) or not desc:
            return None, "bad_desc"
        kind = desc[0]
        if kind == "func":
            nm = desc[1]
            fn = globals().get(nm)
            if callable(fn):
                return fn, nm
            return None, nm
        if kind == "method":
            cname, mn = desc[1], desc[2]
            cls = globals().get(cname)
            if cls is None:
                return None, f"{cname}.{mn}"
            if not _pp187__can_instantiate(cls):
                return None, f"{cname}.{mn}"
            try:
                inst = cls()
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return None, f"{cname}.{mn}"
            try:
                f = getattr(inst, mn, None)
                if callable(f):
                    return f, f"{cname}.{mn}"
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return None, f"{cname}.{mn}"
            return None, f"{cname}.{mn}"
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return None, "materialize_err"

def _pp187__wrap_safe_call_with_order_guard():
    """
    Patch _pp170__safe_call to ensure revived legacy callables cannot place orders.
    This does NOT touch ArzPlusClient or API tokens; it only guards bot-level order helpers during sensor execution.
    """
    try:
        if "_pp170__safe_call" not in globals():
            return
        if getattr(_pp170__safe_call, "_pp187_guarded", False):
            return

        _orig = _pp170__safe_call

        def _guarded(fn, *, bot=None, sym=None, symst=None, bid=None, ask=None, mid=None, depth_data=None):
            if bot is None:
                return _orig(fn, bot=bot, sym=sym, symst=symst, bid=bid, ask=ask, mid=mid, depth_data=depth_data)

            _orig_buy = getattr(bot, "_place_buy", None)
            _orig_sell = getattr(bot, "_place_sell", None)

            def _blk(*a, **k):
                raise RuntimeError("PP187_ORDER_BLOCKED_IN_LEGACY")

            try:
                if callable(_orig_buy):
                    setattr(bot, "_place_buy", _blk)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            try:
                if callable(_orig_sell):
                    setattr(bot, "_place_sell", _blk)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            try:
                return _orig(fn, bot=bot, sym=sym, symst=symst, bid=bid, ask=ask, mid=mid, depth_data=depth_data)
            finally:
                try:
                    if callable(_orig_buy):
                        setattr(bot, "_place_buy", _orig_buy)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

                try:
                    if callable(_orig_sell):
                        setattr(bot, "_place_sell", _orig_sell)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

        _guarded._pp187_guarded = True
        globals()["_pp170__safe_call"] = _guarded
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

def _pp187__extend_legacy_manager():
    """
    Extends LegacyIntelligenceManager to:
      - harvest deep orphans (module funcs + class methods)
      - execute only safe callables
      - keep execution bounded (round-robin cap) to avoid API latency
    """
    try:
        Hub = globals().get("LegacyIntelligenceManager", None)
        if Hub is None:
            return
        if getattr(Hub, "_pp187_extended", False):
            return

        _pp187__wrap_safe_call_with_order_guard()

        _orig_init = Hub.__init__
        _orig_eval = Hub.evaluate

        def __init__(self, bot):
            _orig_init(self, bot)
            try:
                src = _pp187__read_src()
                descs = _pp187__deep_discover_orphans(src)
            except Exception:
                descs = []
            revived = []
            disabled = []
            try:
                existing = set()
                for f in list(getattr(self, "legacy_funcs", []) or []):
                    try:
                        existing.add(_pp187__safe_str(getattr(f, "__name__", "")))
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                for d in descs:
                    fn, label = _pp187__materialize_descriptor(d)
                    if fn is None:
                        disabled.append(label)
                        continue
                    nm = _pp187__safe_str(getattr(fn, "__name__", "")) or label
                    if nm in existing:
                        continue
                    try:
                        self.legacy_funcs.append(fn)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)

                    existing.add(nm)
                    revived.append(label)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            # persist report (for optional UI)
            try:
                setattr(self, "_pp187_revived", list(revived)[:5000])
                setattr(self, "_pp187_revived_disabled", list(disabled)[:5000])
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            # bounded exec configuration (real-mode safety)
            try:
                self._pp187_rr = 0
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            try:
                self._pp187_eval_cap = int(_os.getenv("PP187_LEGACY_EVAL_CAP", "18") or 18)
            except Exception:
                self._pp187_eval_cap = 18

        def evaluate(self, sym: str, symst, bid: float, ask: float, mid: float, depth_data):
            # Execute a bounded subset per call (round-robin)
            try:
                funcs_all = list(getattr(self, "legacy_funcs", []) or [])
            except Exception:
                funcs_all = []
            try:
                cap = int(getattr(self, "_pp187_eval_cap", 18) or 18)
            except Exception:
                cap = 18
            if cap <= 0:
                cap = 18

            if len(funcs_all) > cap:
                try:
                    i = int(getattr(self, "_pp187_rr", 0) or 0) % max(1, len(funcs_all))
                except Exception:
                    i = 0
                subset = funcs_all[i:i + cap]
                if len(subset) < cap:
                    subset = subset + funcs_all[0:max(0, cap - len(subset))]
                try:
                    self._pp187_rr = (i + cap) % max(1, len(funcs_all))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

            else:
                subset = funcs_all

            safe_subset = []
            dormant = 0
            for fn in subset:
                try:
                    if _pp187__is_probably_safe_callable(fn):
                        safe_subset.append(fn)
                    else:
                        dormant += 1
                except Exception:
                    dormant += 1

            orig_list = None
            try:
                orig_list = getattr(self, "legacy_funcs", None)
                self.legacy_funcs = safe_subset
            except Exception:
                orig_list = None

            try:
                d, c = _orig_eval(self, sym, symst, bid, ask, mid, depth_data)
            finally:
                try:
                    if orig_list is not None:
                        self.legacy_funcs = orig_list
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

            # stats
            try:
                setattr(self, "_pp187_dormant_last", int(dormant))
                setattr(self, "_pp187_safe_ran_last", int(len(safe_subset)))
                setattr(self, "_pp187_total_funcs", int(len(funcs_all)))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            return d, c

        Hub.__init__ = __init__
        Hub.evaluate = evaluate
        Hub._pp187_extended = True
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

