def _pp190__now() -> float:
    try:
        return float(_pp190__pp920_time.time())
    except Exception:
        try:
            import time as _t
            return float(_t.time())
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0


def _pp190__sf(x, d=0.0) -> float:
    try:
        return float(x)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(d)


def _pp190__safe_str(x, d="") -> str:
    try:
        s = str(x)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return str(d)
    return s if s is not None else str(d)


def _pp190__keyword_hit(name: str) -> bool:
    s = _pp190__safe_str(name, "").lower()
    if not s:
        return False
    key = (
        "nlp", "sentiment", "news", "emotion", "affect",
        "arb", "arbitrage", "triangular", "triangle", "tri_arb",
        "fractal", "hurst", "harmonic", "fibo", "fibonacci", "elliott", "gann", "wave",
        "pattern", "zigzag", "butterfly", "bat", "crab", "shark"
    )
    return any(k in s for k in key)


def _pp190__is_legacy_name(name: str) -> bool:
    """Best-effort filter to keep PP190 sandbox focused on *pre-v110* (or unversioned) legacy genes."""
    s = _pp190__safe_str(name, "")
    if not s:
        return False
    try:
        import re as _re
        mm = __pp920_re.match(r'^_pp(\d+)_', s)
        if mm:
            try:
                v = int(mm.group(1))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return False
            try:
                mx = int(_pp190_os.getenv('PP190_LEGACY_MAX_VER', '110') or 110)
            except Exception:
                mx = 110
            return int(v) <= int(mx)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return True

def _pp190__unsafe_gene(fn) -> bool:
    """
    Reject genes that might touch order/transfer/withdraw paths.
    Conservative: fail-closed (unsafe) only on strong indicators.
    """
    try:
        c = getattr(fn, "__code__", None)
        names = set(getattr(c, "co_names", ()) or ())
    except Exception:
        names = set()
    bad = (
        "_place_buy", "_place_sell", "create_order", "submit_order", "order",
        "withdraw", "transfer", "deposit", "api_post", "api_put"
    )
    for n in names:
        s = _pp190__safe_str(n, "").lower()
        if any(b in s for b in bad):
            return True
    return False


def _pp190__coerce_vote(out) -> _pp190_Tuple[str, float]:
    """
    Normalize gene outputs to ("BUY"/"SELL"/"HOLD", score_float)
    """
    # numeric => signed score
    try:
        if isinstance(out, (int, float)):
            sc = float(out)
            if sc >= 0.12:
                return "BUY", float(sc)
            if sc <= -0.12:
                return "SELL", float(sc)
            return "HOLD", float(sc)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # dict => signal + score
    try:
        if isinstance(out, dict):
            sig = _pp190__safe_str(out.get("signal", out.get("vote", out.get("dir", out.get("action", "")))), "").upper().strip()
            sc = _pp190__sf(out.get("score", out.get("delta", out.get("strength", 0.0))), 0.0)
            if sig in ("BUY", "SELL", "HOLD"):
                if sig == "BUY" and sc <= 0:
                    sc = abs(float(sc))
                if sig == "SELL" and sc >= 0:
                    sc = -abs(float(sc))
                return sig, float(sc)
            # infer from score
            if sc >= 0.12:
                return "BUY", float(sc)
            if sc <= -0.12:
                return "SELL", float(sc)
            return "HOLD", float(sc)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # string => vote
    try:
        if isinstance(out, str):
            sig = out.strip().upper()
            if sig in ("BUY", "SELL", "HOLD"):
                sc = 0.15 if sig == "BUY" else (-0.15 if sig == "SELL" else 0.0)
                return sig, float(sc)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return "HOLD", 0.0


class _pp190_LegacyGene:
    __slots__ = ("name", "fn", "kind", "weight", "fails", "disabled", "last_vote", "last_score", "last_ts", "reason")
    def __init__(self, name: str, fn, kind: str):
        self.name = str(name)
        self.fn = fn
        self.kind = str(kind)
        self.weight = 1.0
        self.fails = 0
        self.disabled = False
        self.last_vote = "HOLD"
        self.last_score = 0.0
        self.last_ts = 0.0
        self.reason = ""

    def call(self, ctx: dict) -> _pp190_Tuple[str, float]:
        # NOTE: genes are never hard-disabled; "disabled" is treated as a soft-penalty marker only.
        try:
            if bool(self.disabled):
                self.reason = self.reason or "soft_disabled"
                try:
                    self.weight = float(max(0.02, min(1.0, float(self.weight or 0.0) * 0.50)))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # hard contain unsafe genes (do NOT disable; execute via safe proxies + TLS guard)
        try:
            if _pp190__unsafe_gene(self.fn):
                self.reason = "unsafe_gene_soft"
                try:
                    self.weight = float(max(0.02, min(1.0, float(self.weight or 0.0) * 0.25)))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
        except Exception as _pp200_e:
            _heal = globals().get("_pp200_self_heal_call", None)
            _led = None
            try:
                _b = ctx.get("bot")
                _br = getattr(_b, "_pp200_bridge", None) if _b is not None else None
                _led = getattr(_br, "ledger", None) if _br is not None else None
            except Exception:
                _led = None
            if callable(_heal) and (_led is not None):
                out, _err = _heal(
                    self.fn,
                    name=self.name,
                    sym=ctx.get("sym"),
                    symst=ctx.get("symst"),
                    bid=ctx.get("bid"),
                    ask=ctx.get("ask"),
                    mid=ctx.get("mid"),
                    depth_data=ctx.get("depth_data"),
                    bot=ctx.get("bot"),
                    ledger=_led,
                )
                if _err:
                    try:
                        self.fails += 1
                        self.reason = ("heal_fail:" + str(_err))[:180]
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
            else:
                out = _pp170__safe_call(
                    self.fn,
                    bot=ctx.get("bot"),
                    sym=ctx.get("sym"),
                    symst=ctx.get("symst"),
                    bid=ctx.get("bid"),
                    ask=ctx.get("ask"),
                    mid=ctx.get("mid"),
                    depth_data=ctx.get("depth_data"),
                )
            prev_block = None

        try:
            out = _pp170__safe_call(
                self.fn,
                bot=ctx.get("bot"),
                sym=ctx.get("sym"),
                symst=ctx.get("symst"),
                bid=ctx.get("bid"),
                ask=ctx.get("ask"),
                mid=ctx.get("mid"),
                depth_data=ctx.get("depth_data"),
            )
            vote, sc = _pp190__coerce_vote(out)
            self.last_vote = vote
            self.last_score = float(sc)
            self.last_ts = _pp190__now()
            self.reason = ""
            return vote, float(sc)
        except Exception as e:
            try:
                self.fails += 1
                self.reason = f"{type(e).__name__}"
                if self.fails >= int(_pp190_os.getenv("PP190_GENE_MAX_FAILS", "3") or 3):
                    # keep gene alive; apply penalty instead of disabling
                    try:
                        self.weight = float(max(0.02, min(1.0, float(self.weight or 0.0) * 0.55)))
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
                    self.disabled = False
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            return "HOLD", 0.0
        finally:
            try:
                if prev_block is not None:
                    setattr(globals().get("_pp181_tls", None), "block_orders", bool(prev_block))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

class _pp190_Legacy_Sandbox:
    """
    Isolated evaluation layer for dormant legacy genes (NLP sentiment, triangular arbitrage, fractal/harmonics).
    Provides a SECONDARY confirmation for BUY/SELL decisions.

    Design:
      - Discover genes once (deep archeology)
      - Evaluate light subset each tick (round-robin) to avoid latency
      - Cache per-symbol verdicts for order-time checks
      - Self-correction: decrease gene weights after bad outcomes; disable chronic offenders
    """
    def __init__(self, bot):
        self.bot = bot
        self.ready = False
        self.genes: _pp190_Dict[str, _pp190_LegacyGene] = {}
        self.disabled: set = set()
        self._rr: _pp190_List[str] = []
        self._rr_i = 0
        self.last_by_sym: _pp190_Dict[str, dict] = {}
        self.last_details_by_sym: _pp190_Dict[str, list] = {}
        self._lock = _pp190_threading.Lock() if _pp190_threading is not None else None
        self._discover()

    def _discover(self) -> None:
        genes = {}

        # 1) Prefer PP170/PP187 discovered orphans
        try:
            li = getattr(self.bot, "legacy_intel", None) or getattr(self.bot, "legacy_intelligence", None)
            # include callable legacy_funcs and orphan names
            fns = []
            try:
                fns.extend(list(getattr(li, "legacy_funcs", []) or []))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            try:
                for nm in (getattr(li, "orphans", []) or []):
                    if _pp190__keyword_hit(nm):
                        fn = globals().get(str(nm))
                        if callable(fn):
                            fns.append(fn)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            for fn in (fns or []):
                nm = _pp190__safe_str(getattr(fn, "__name__", "legacy"), "legacy")
                if not _pp190__keyword_hit(nm):
                    continue
                if not _pp190__is_legacy_name(nm):
                    continue
                if nm in genes:
                    continue
                genes[nm] = _pp190_LegacyGene(nm, fn, kind="legacy")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # 2) Deep archeology: scan global callables matching keywords
        try:
            for nm, obj in list(globals().items()):
                if not _pp190__keyword_hit(nm):
                    continue
                if not _pp190__is_legacy_name(nm):
                    continue
                if nm in genes:
                    continue
                if callable(obj) and (not isinstance(obj, type)):
                    genes[nm] = _pp190_LegacyGene(str(nm), obj, kind="global")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # 3) Deep archeology: parse this file source for def/class names (recover not-yet-exposed callables)
        try:
            import re as _re
            _src = ""
            try:
                _src = _pp187__read_src() if callable(globals().get("_pp187__read_src", None)) else ""
            except Exception:
                _src = ""
            if not _src:
                try:
                    import inspect as _ins
                    _src = _ins.getsource(sys.modules[__name__])  # type: ignore
                except Exception:
                    _src = ""
            if _src:
                for m in _re.finditer(r'^\s*(?:def|class)\s+([A-Za-z_][A-Za-z0-9_]*)\s*[\(:]', _src, _re.M):
                    nm = m.group(1)
                    if not _pp190__keyword_hit(nm):
                        continue
                    if not _pp190__is_legacy_name(nm):
                        continue
                    if nm in genes:
                        continue
                    obj = globals().get(nm)
                    if callable(obj) and (not isinstance(obj, type)):
                        genes[nm] = _pp190_LegacyGene(str(nm), obj, kind="src")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # Hard cap to keep Termux safe
        try:
            cap = int(_pp190_os.getenv("PP190_GENE_CAP", "30") or 30)
        except Exception:
            cap = 30

        # stable order
        ordered = sorted(list(genes.values()), key=lambda g: (g.kind, g.name))[:max(8, cap)]
        self.genes = {g.name: g for g in ordered}
        self._rr = list(self.genes.keys())
        self._rr_i = 0
        self.ready = True if self.genes else False

    def _next_batch(self, k: int) -> _pp190_List[_pp190_LegacyGene]:
        if not self._rr:
            return []
        out = []
        for _ in range(int(max(1, k))):
            try:
                nm = self._rr[self._rr_i % len(self._rr)]
            except Exception:
                nm = None
            self._rr_i += 1
            if not nm:
                continue
            g = self.genes.get(nm)
            if g is None:
                continue
            out.append(g)
        return out

    def tick(self, sym: str, symst, bid: float, ask: float, mid: float, depth_data: dict) -> None:
        if not self.ready:
            return

        try:
            sym_u = str(sym).upper()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return

        try:
            batch = int(_pp190_os.getenv("PP190_GENE_BATCH", "6") or 6)
        except Exception:
            batch = 6

        ctx = {"bot": self.bot, "sym": sym_u, "symst": symst, "bid": bid, "ask": ask, "mid": mid, "depth_data": depth_data}

        votes = []
        details = []
        score_sum = 0.0
        w_sum = 0.0

        for g in self._next_batch(batch):
            vote, sc = g.call(ctx)
            w = float(max(0.0, min(1.0, g.weight)))
            score_sum += w * float(sc)
            w_sum += w
            votes.append(vote)
            details.append((g.name, vote, float(sc), w, bool(g.disabled)))

        # Normalize to [-1,1] like score
        if w_sum > 0:
            score_sum = float(score_sum) / float(w_sum)

        if score_sum >= 0.10:
            final_vote = "BUY"
        elif score_sum <= -0.10:
            final_vote = "SELL"
        else:
            final_vote = "HOLD"

        payload = {
            "vote": final_vote,
            "score": float(score_sum),
            "ts": _pp190__now(),
            "n": int(len(details)),
        }

        try:
            if self._lock is not None:
                with self._lock:
                    self.last_by_sym[sym_u] = payload
                    self.last_details_by_sym[sym_u] = details
            else:
                self.last_by_sym[sym_u] = payload
                self.last_details_by_sym[sym_u] = details
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # expose to dashboard caches (lightweight)
        try:
            setattr(symst, "pp190_sandbox_vote", str(final_vote))
            setattr(symst, "pp190_sandbox_score", float(score_sum))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def get_cached(self, sym: str) -> dict:
        try:
            sym_u = str(sym).upper()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return {"vote": "HOLD", "score": 0.0, "ts": 0.0, "n": 0}
        try:
            if self._lock is not None:
                with self._lock:
                    return dict(self.last_by_sym.get(sym_u) or {})
            return dict(self.last_by_sym.get(sym_u) or {})
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return {"vote": "HOLD", "score": 0.0, "ts": 0.0, "n": 0}

    def secondary_confirm(self, side: str, sym: str) -> bool:
        """
        Strict confirmation: BUY requires sandbox BUY; SELL requires sandbox SELL.
        If sandbox lacks a fresh verdict, fail-closed => False.
        """
        s = str(side or "").upper().strip()
        if s not in ("BUY", "SELL"):
            return True
        c = self.get_cached(sym)
        v = str(c.get("vote", "HOLD") or "HOLD").upper()
        ts = _pp190__sf(c.get("ts", 0.0), 0.0)
        try:
            max_age = float(_pp190_os.getenv("PP190_SANDBOX_MAX_AGE_SEC", "25") or 25)
        except Exception:
            max_age = 25.0
        if ts <= 0 or (_pp190__now() - ts) > float(max_age):
            return False
        return v == s

    def on_trade_outcome(self, result) -> None:
        """
        Self-correction loop: adapt gene weights based on realized PnL.
        If a gene repeatedly aligns with losing outcomes, its weight decays; chronic offenders are disabled.
        """
        sym = ""
        pnl_usdt = 0.0
        try:
            if isinstance(result, dict):
                sym = _pp190__safe_str(result.get("symbol", ""), "").upper()
                if "pnl_usdt" in result:
                    pnl_usdt = _pp190__sf(result.get("pnl_usdt", 0.0), 0.0)
                elif "pnl_toman" in result:
                    ur = _pp190__sf(getattr(self.bot, "_dash_usdt_rate", 0.0), 0.0)
                    if ur > 0:
                        pnl_usdt = float(_pp190__sf(result.get("pnl_toman", 0.0), 0.0)) / float(ur)
            else:
                sym = _pp190__safe_str(getattr(result, "symbol", ""), "").upper()
                pnl_usdt = _pp190__sf(getattr(result, "pnl_usdt", getattr(result, "pnl", 0.0)), 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return

        if not sym:
            return

        try:
            details = list(self.last_details_by_sym.get(sym) or [])
        except Exception:
            details = []

        if not details:
            return

        # learning rate
        try:
            a = float(_pp190_os.getenv("PP190_SELF_CORR_ALPHA", "0.12") or 0.12)
        except Exception:
            a = 0.12
        a = max(0.03, min(0.35, float(a)))

        good = 1.0 if float(pnl_usdt) > 0 else 0.0

        for nm, vote, sc, w, dis in details:
            g = self.genes.get(str(nm))
            if g is None or g.disabled:
                continue
            # if gene had non-trivial opinion, update
            try:
                opinion = str(vote).upper()
            except Exception:
                pass

            # weight target: reward if pnl positive, punish if pnl negative
            # also punish stronger if gene score was strong but pnl negative
            strength = min(1.0, abs(float(sc)))
            if good > 0:
                target = 1.0
                delta = a * (target - g.weight)
                g.weight = float(max(0.05, min(1.0, g.weight + delta)))
            else:
                # punish
                target = 0.0
                delta = a * (target - g.weight) * (1.0 + 0.5 * strength)
                g.weight = float(max(0.02, min(1.0, g.weight + delta)))
                try:
                    g.fails += 1
                    if g.fails >= int(_pp190_os.getenv("PP190_GENE_DISABLE_AFTER_LOSSES", "7") or 7):
                        # keep gene alive; apply penalty instead of disabling
                        try:
                            g.weight = float(max(0.02, min(1.0, float(g.weight or 0.0) * 0.65)))
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                        g.reason = "selfcorr_penalty"
                        g.disabled = False
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

    def legacy_genes_active_summary(self) -> str:
        try:
            active = [g for g in self.genes.values() if not bool(g.disabled)]
        except Exception:
            active = []
        try:
            disabled = [g for g in self.genes.values() if bool(g.disabled)]
        except Exception:
            disabled = []

        # highlight main categories (best effort)
        cats = {"NLP": False, "TRI_ARB": False, "FRACTAL": False}
        for g in active:
            nm = g.name.lower()
            if ("nlp" in nm) or ("sentiment" in nm) or ("news" in nm) or ("emotion" in nm):
                cats["NLP"] = True
            if ("tri" in nm and "arb" in nm) or ("triangular" in nm) or ("triangle" in nm):
                cats["TRI_ARB"] = True
            if ("fractal" in nm) or ("harmonic" in nm) or ("hurst" in nm) or ("elliott" in nm) or ("fibo" in nm):
                cats["FRACTAL"] = True

        parts = []
        parts.append(f"NLP-Sentiment:{'ACTIVE' if cats['NLP'] else 'IDLE'}")
        parts.append(f"Triangular-Arb:{'ACTIVE' if cats['TRI_ARB'] else 'IDLE'}")
        parts.append(f"Fractal/Harmonics:{'ACTIVE' if cats['FRACTAL'] else 'IDLE'}")
        parts.append(f"Genes:{len(active)}")
        parts.append(f"Silenced:{len(disabled)}")
        parts.append("SelfCorrection:ON")
        return " | ".join(parts)


