# ---- Strict secondary confirmation at consensus stage (fail-closed) ----
try:
    _pp190__orig_post = _pp5_postprocess_score

    def _pp5_postprocess_score(self, sym, symst, bid, ask, mid, depth_data, score):
        s2 = _pp190__orig_post(self, sym, symst, bid, ask, mid, depth_data, score)
        # Secondary confirm applies only when consensus wants to trade
        try:
            cd = str(getattr(symst, "pp175_consensus_dir", "HOLD") or "HOLD").upper().strip()
        except Exception:
            cd = "HOLD"

        if cd in ("BUY", "SELL"):
            try:
                bot = getattr(self, "bot", None)
            except Exception:
                bot = None
            sb = None
            try:
                sb = getattr(bot, "_pp190_sandbox", None) if bot is not None else None
            except Exception:
                sb = None

            # v8064 (mature): never hard-lock consensus when PP190 sandbox is missing.
            # Lazy-init sandbox once; if still unavailable, treat as NEUTRAL (report-only).
            if sb is None:
                try:
                    _owner = bot if bot is not None else self
                    sb = _pp190_Legacy_Sandbox(_owner)
                    try:
                        setattr(_owner, "_pp190_sandbox", sb)
                    except Exception:
                        pass
                    # attach to cognitive core for introspection (best-effort)
                    try:
                        cc = getattr(_owner, "cognitive_core", None)
                        if cc is not None:
                            setattr(cc, "_pp190_sandbox", sb)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e)
                except Exception:
                    sb = None

            if sb is None:
                # Sandbox unavailable => NEUTRAL: do NOT overwrite pp175_consensus_dir.
                try:
                    setattr(symst, "pp190_secondary_ok", False)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)
                return float(s2)

            # PP190 vote contract (Tier-1 style):
            # - VETO only on fresh, explicit opposite vote.
            # - APPROVE on fresh match.
            # - NEUTRAL on stale/unknown/HOLD (never overwrites consensus).
            try:
                _c = sb.get_cached(sym) if (sb is not None and hasattr(sb, "get_cached")) else {}
                _v = str((_c or {}).get("vote", "HOLD") or "HOLD").upper()
                _ts = float((_c or {}).get("ts", 0.0) or 0.0)
            except Exception:
                _v, _ts = "HOLD", 0.0

            try:
                _max_age = float(_pp190_os.getenv("PP190_SANDBOX_MAX_AGE_SEC", "25") or 25)
            except Exception:
                _max_age = 25.0

            try:
                _fresh = (_ts > 0.0) and ((_pp190__now() - _ts) <= float(_max_age))
            except Exception:
                _fresh = False

            ok = bool(_fresh and (_v == cd))
            veto = bool(_fresh and (_v in ("BUY", "SELL")) and (_v != cd))

            try:
                setattr(symst, "pp190_secondary_ok", bool(ok))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            if veto:
                try:
                    symst.pp175_consensus_dir = "HOLD"
                    # mark veto explicitly (dashboard)
                    symst.pp190_secondary_veto = True
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)
            else:
                # clear sticky veto flag if present
                try:
                    symst.pp190_secondary_veto = False
                except Exception:
                    pass

        return float(s2)

except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

