def _pp200_now() -> float:
    try:
        return float(_pp200__pp920_time.time())
    except Exception:
        try:
            import time as __t
            return float(__t.time())
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

def _pp200_s(val, default="") -> str:
    try:
        return str(val)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return str(default)

