def _pp200_log(bot, msg: str, *, level: str = "info") -> None:
    # Never silent: best-effort log to bot.logger, else print.
    try:
        lg = getattr(bot, "logger", None)
    except Exception:
        lg = None
    try:
        if lg is not None and hasattr(lg, str(level)):
            getattr(lg, str(level))(str(msg))
            return
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    try:
        print(str(msg))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

class _pp200_IntegrityLedger:
    """
    Tracks recovered logic and operational integrity of legacy genes.
    No silent swallowing: each failure is counted and surfaced to dashboard.
    """
    def __init__(self):
        self.total = 0
        self.recovered = 0
        self.operational = 0
        self.degraded = 0
        self.failures = 0
        self.heal_attempts = 0
        self.heal_success = 0
        self.last_err: _pp200_Dict[str, str] = {}
        self.last_ok_ts: _pp200_Dict[str, float] = {}
        self.err_counts: _pp200_Dict[str, int] = {}
        self.non_operational: _pp200_Dict[str, _pp200_Any] = {}  # name -> {'reason':str,'next_retry_ts':float,'count':int}
        self.state: _pp200_Dict[str, str] = {}  # ACTIVE/DEGRADED/FAULTY/RECOVERED
        try:
            self._lock = _pp200_threading.Lock() if _pp200_threading is not None else None
        except Exception:
            self._lock = None

        # Async heavy-gene execution (Termux real-time): non-blocking threadpool + future cache
        try:
            import concurrent.futures as _pp200_cf
        except Exception:
            _pp200_cf = None
        self._pp200_executor = None
        try:
            _mw = int(os.getenv("PP200_ASYNC_WORKERS", "2") or 2)
        except Exception:
            _mw = 2
        _mw = max(1, min(8, int(_mw)))
        try:
            if _pp200_cf is not None:
                self._pp200_executor = _pp200_cf.ThreadPoolExecutor(max_workers=_mw, thread_name_prefix="PP200G")
        except Exception as _pp200_e:
            try:
                _pp200_heal(_pp200_e, tag="pp200_executor_init")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            self._pp200_executor = None

        # futures: name -> Future ; fmeta: name -> start_ts ; last_async: name -> (out, err, ts)
        try:
            self._pp200_futures = {}
            self._pp200_fmeta = {}
            self._pp200_last_async = {}
        except Exception:
            self._pp200_futures = {}
            self._pp200_fmeta = {}
            self._pp200_last_async = {}


    def _with_lock(self):
        return self._lock

    def register(self, name: str, *, recovered: bool = False) -> None:
        n = _pp200_s(name)
        lk = self._with_lock()
        try:
            if lk is not None:
                with lk:
                    self.total += 1
                    if recovered:
                        self.recovered += 1
                        self.state[n] = "RECOVERED"
                    else:
                        self.state.setdefault(n, "ACTIVE")
            else:
                self.total += 1
                if recovered:
                    self.recovered += 1
                    self.state[n] = "RECOVERED"
                else:
                    self.state.setdefault(n, "ACTIVE")
        except Exception:
            # last resort, still no silent: bump counters minimally
            self.total += 1

    def mark_ok(self, name: str) -> None:
        n = _pp200_s(name)
        lk = self._with_lock()
        try:
            if lk is not None:
                with lk:
                    self.operational += 1
                    self.last_ok_ts[n] = _pp200_now()
                    if self.state.get(n) in ("FAULTY", "DEGRADED"):
                        self.state[n] = "ACTIVE"
            else:
                self.operational += 1
                self.last_ok_ts[n] = _pp200_now()
                if self.state.get(n) in ("FAULTY", "DEGRADED"):
                    self.state[n] = "ACTIVE"
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def mark_fail(self, name: str, err: str) -> None:
        n = _pp200_s(name)
        e = _pp200_s(err)[:500]
        lk = self._with_lock()
        try:
            if lk is not None:
                with lk:
                    self.failures += 1
                    self.last_err[n] = e
                    self.err_counts[n] = int(self.err_counts.get(n, 0)) + 1
                    self.state[n] = "FAULTY"
            else:
                self.failures += 1
                self.last_err[n] = e
                self.err_counts[n] = int(self.err_counts.get(n, 0)) + 1
                self.state[n] = "FAULTY"
        except Exception:
            self.failures += 1

    def mark_degraded(self, name: str, reason: str) -> None:
        n = _pp200_s(name)
        r = _pp200_s(reason)[:250]
        lk = self._with_lock()
        try:
            if lk is not None:
                with lk:
                    self.degraded += 1
                    self.last_err[n] = r
                    self.state[n] = "DEGRADED"
            else:
                self.degraded += 1
                self.last_err[n] = r
                self.state[n] = "DEGRADED"
        except Exception:
            self.degraded += 1

    def mark_heal_attempt(self, name: str) -> None:
        try:
            self.heal_attempts += 1
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    def mark_heal_success(self, name: str) -> None:
        try:
            self.heal_success += 1
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)


    def mark_non_operational(self, name: str, reason: str, cooldown_sec: float = 600.0) -> None:
        """Mark a gene as currently non-operational (irrelevant / incompatible) but allow periodic retry."""
        n = _pp200_s(name)
        try:
            now = _pp200_now()
        except Exception:
            import time as _t
            now = float(_t.time())
        try:
            cd = float(cooldown_sec or 600.0)
        except Exception:
            cd = 600.0
        try:
            rec = self.non_operational.get(n) if isinstance(self.non_operational, dict) else None
            cnt = 1
            if isinstance(rec, dict):
                try:
                    cnt = int(rec.get("count", 0)) + 1
                except Exception:
                    cnt = 1
            self.non_operational[n] = {"reason": _pp200_s(reason)[:160], "next_retry_ts": float(now + cd), "count": int(cnt)}
            self.state[n] = "NON_OPERATIONAL"
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="mark_non_operational")
    def integrity_percent(self) -> float:
        try:
            if self.total <= 0:
                return 0.0
            # operational coverage is: unique genes that have succeeded at least once / total
            uniq_ok = len(self.last_ok_ts or {})
            return max(0.0, min(100.0, 100.0 * float(uniq_ok) / float(self.total)))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

    def recovered_count(self) -> int:
        try:
            return int(self.recovered)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0

    def brief(self) -> str:
        try:
            return f"{self.integrity_percent():.1f}% ok | recovered={self.recovered_count()} | fails={int(self.failures)} | heal={int(self.heal_success)}/{int(self.heal_attempts)}"
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return "n/a"

def _pp200_extract_commented_blocks(src_text: str) -> _pp200_List[str]:
    """
    Pulls commented-out function/class blocks like:
      # def foo(...):
      #     ...
    Returns list of candidate code strings (uncommented).
    """
    blocks: _pp200_List[str] = []
    try:
        lines = (src_text or "").splitlines()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return blocks

    i = 0
    n = len(lines)
    header_pat = _pp200_re.compile(r"^\s*#\s*(def|class)\s+[A-Za-z_][A-Za-z0-9_]*\s*\(") if _pp200_re else None
    header_pat2 = _pp200_re.compile(r"^\s*#\s*(def|class)\s+[A-Za-z_][A-Za-z0-9_]*\b") if _pp200_re else None

    while i < n:
        line = lines[i]
        is_header = False
        try:
            if header_pat and header_pat.search(line):
                is_header = True
            elif header_pat2 and header_pat2.search(line):
                is_header = True
        except Exception:
            is_header = False

        if not is_header:
            i += 1
            continue

        # capture contiguous commented block
        j = i
        buff = []
        while j < n:
            lj = lines[j]
            if lj.strip() == "#":
                buff.append("")
                j += 1
                continue
            if not lj.lstrip().startswith("#"):
                break
            # strip first '#'
            k = lj.find("#")
            content = lj[k+1:]
            # if there's a single leading space, drop it
            if content.startswith(" "):
                content = content[1:]
            buff.append(content.rstrip("\n"))
            j += 1

        code = "\n".join(buff)
        # quick sanity: must include 'def ' or 'class ' start
        if "def " in code or "class " in code:
            blocks.append(code)
        i = j + 1

    # Deduplicate (keep order)
    seen = set()
    out = []
    for b in blocks:
        key = b.strip()[:200]
        if key in seen:
            continue
        seen.add(key)
        out.append(b)
    return out

def _pp200_safe_exec(code: str) -> _pp200_Dict[str, _pp200_Any]:
    """
    Execute recovered code in a restricted namespace.

    Worldclass root-fix:
    - No imports from recovered blocks
    - No dunder/underscore attribute access (prevents sandbox escapes)
    - Tight builtins surface
    - Size cap to keep latency bounded
    """
    # normalize
    if code is None:
        code = ""
    if not isinstance(code, str):
        try:
            code = str(code)
        except Exception:
            code = ""
    # keep latency bounded
    if len(code) > 20000:
        raise ValueError("pp200_safe_exec:code_too_large")

    # stdlib-only (no new deps)
    import ast as _pp200_ast

    try:
        tree = _pp200_ast.parse(code, mode="exec")
    except Exception as _e:
        raise

    # minimal builtins (no __import__/open/eval/exec/compile/etc)
    safe_builtins = {
        "abs": abs, "min": min, "max": max, "sum": sum, "len": len, "range": range,
        "float": float, "int": int, "str": str, "bool": bool,
        "dict": dict, "list": list, "tuple": tuple, "set": set,
        "enumerate": enumerate, "zip": zip, "sorted": sorted,
        "any": any, "all": all, "round": round,
        "Exception": Exception,
    }

    # forbid some names explicitly (even if user defines them)
    _forbid_names = set(["__builtins__", "__import__", "eval", "exec", "open", "compile", "globals", "locals", "vars", "dir", "input", "getattr", "setattr", "delattr"])

    def _bad_attr(attr: str) -> bool:
        try:
            if not attr:
                return True
            if attr.startswith("_") or "__" in attr:
                return True
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return True
        return False

    # Validate AST: block imports and sandbox-escape primitives; allow normal mathy code.
    for node in _pp200_ast.walk(tree):
        # hard bans
        if isinstance(node, (_pp200_ast.Import, _pp200_ast.ImportFrom)):
            raise ValueError("pp200_safe_exec:import_blocked")
        if isinstance(node, (_pp200_ast.Global, _pp200_ast.Nonlocal)):
            raise ValueError("pp200_safe_exec:scope_blocked")
        if isinstance(node, (_pp200_ast.With, _pp200_ast.AsyncWith)):
            raise ValueError("pp200_safe_exec:with_blocked")
        if isinstance(node, (_pp200_ast.Delete, _pp200_ast.Assert, _pp200_ast.Raise)):
            raise ValueError("pp200_safe_exec:stmt_blocked")
        # unbounded loops are a latency hazard; for-loops are acceptable
        if isinstance(node, _pp200_ast.While):
            raise ValueError("pp200_safe_exec:while_blocked")
        # attribute hygiene
        if isinstance(node, _pp200_ast.Attribute):
            if _bad_attr(getattr(node, "attr", "")):
                raise ValueError("pp200_safe_exec:dunder_attr_blocked")
        if isinstance(node, _pp200_ast.Name):
            nid = getattr(node, "id", "")
            if isinstance(nid, str):
                if nid in _forbid_names:
                    raise ValueError("pp200_safe_exec:name_blocked")
                if nid.startswith("__"):
                    raise ValueError("pp200_safe_exec:dunder_name_blocked")
        # call hygiene
        if isinstance(node, _pp200_ast.Call):
            fn = getattr(node, "func", None)
            if isinstance(fn, _pp200_ast.Name):
                if fn.id not in safe_builtins:
                    # allow calls to whitelisted modules via attribute, not bare names
                    raise ValueError(f"pp200_safe_exec:call_blocked:{fn.id}")
            elif isinstance(fn, _pp200_ast.Attribute):
                if _bad_attr(getattr(fn, "attr", "")):
                    raise ValueError("pp200_safe_exec:dunder_call_blocked")
            else:
                raise ValueError("pp200_safe_exec:call_unknown_blocked")

    # provide whitelisted modules explicitly (no import inside recovered code)
    _pp200_math = __import__("math")
    _pp200_re = __import__("re")
    try:
        import statistics as _pp200_stats
    except Exception:
        _pp200_stats = None

    g = {
        "__builtins__": safe_builtins,
        "__name__": "__pp200_safe_exec__",
        "math": _pp200_math,
        "re": _pp200_re,
    }
    if _pp200_stats is not None:
        g["statistics"] = _pp200_stats

    l = {}
    exec(compile(tree, "<pp200_gene>", "exec", dont_inherit=True, optimize=2), g, l)

    # merge (keep previous behavior)
    out = dict(g)
    out.update(l)
    return out

class _pp200_LegacyAPIShim:
    """
    Compatibility facade for legacy genes that expect 'api' like object.
    Provides depth/ticker methods backed by already-fetched data (no extra API calls).
    """
    def __init__(self, sym: str, symst, bid: float, ask: float, mid: float, depth_data: dict):
        self.sym = sym
        self.symst = symst
        self.bid = float(bid or 0.0)
        self.ask = float(ask or 0.0)
        self.mid = float(mid or 0.0)
        self._depth = depth_data or {}

    def depth(self, symbol=None):
        return self._depth

    def get_depth(self, symbol=None):
        return self._depth

    def orderbook(self, symbol=None):
        return self._depth

    def book(self, symbol=None):
        return self._depth

    def ticker(self, symbol=None):
        return {"bid": self.bid, "ask": self.ask, "last": self.mid, "mid": self.mid}

def _pp200_normalize_vote(out) -> _pp200_Tuple[str, float, _pp200_Dict[str, _pp200_Any]]:
    """
    Normalize arbitrary gene output into (vote, confidence, meta).
    vote in {"BUY","SELL","HOLD"}
    confidence in [0,1]
    """
    meta = {}
    try:
        if isinstance(out, dict):
            meta = dict(out)
            v = str(out.get("vote") or out.get("signal") or out.get("action") or "HOLD").upper()
            sc = out.get("score", out.get("confidence", out.get("strength", 0.0)))
            conf = max(0.0, min(1.0, abs(_pp200_f(sc, 0.0))))
            if v not in ("BUY","SELL","HOLD"):
                # heuristic from score sign
                if _pp200_f(sc, 0.0) >= 0.12:
                    v = "BUY"
                elif _pp200_f(sc, 0.0) <= -0.12:
                    v = "SELL"
                else:
                    v = "HOLD"
            return v, conf, meta
        if isinstance(out, (tuple, list)) and len(out) >= 2:
            v = str(out[0]).upper()
            sc = _pp200_f(out[1], 0.0)
            conf = max(0.0, min(1.0, abs(sc)))
            meta = {"raw": out}
            if v not in ("BUY","SELL","HOLD"):
                if sc >= 0.12:
                    v = "BUY"
                elif sc <= -0.12:
                    v = "SELL"
                else:
                    v = "HOLD"
            return v, conf, meta
        if isinstance(out, str):
            s = out.strip().upper()
            if "BUY" in s and "SELL" in s:
                return "HOLD", 0.0, {"raw": out}
            if "BUY" in s:
                return "BUY", 0.25, {"raw": out}
            if "SELL" in s:
                return "SELL", 0.25, {"raw": out}
            return "HOLD", 0.0, {"raw": out}
        if isinstance(out, bool):
            return ("BUY", 0.20, {"raw": out}) if out else ("HOLD", 0.0, {"raw": out})
        if isinstance(out, (int, float)):
            sc = _pp200_f(out, 0.0)
            if sc >= 0.12:
                return "BUY", max(0.05, min(1.0, abs(sc))), {"raw": out}
            if sc <= -0.12:
                return "SELL", max(0.05, min(1.0, abs(sc))), {"raw": out}
            return "HOLD", 0.0, {"raw": out}
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    return "HOLD", 0.0, {"raw": out}

class _pp600_Series(list):
    """Lightweight series that acts as list AND scalar (float(series) -> last)."""
    def __float__(self):
        try:
            return float(self[-1]) if self else 0.0
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0
    def __int__(self):
        try:
            return int(float(self))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0

def _pp600_series(seq) -> _pp600_Series:
    try:
        s = _pp600_Series()
        if seq:
            s.extend(list(seq))
        return s
    except Exception:
        try:
            return _pp600_Series(list(seq) if seq else [])
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return _pp600_Series()

def _pp200_build_call_kwargs(fn, *, sym, symst, bid, ask, mid, depth_data, bot=None) -> _pp200_Dict[str, _pp200_Any]:
    kw = {}
    names = []
    try:
        if _pp200_inspect is not None:
            sig = _pp200_inspect.signature(fn)
            names = [p.name for p in sig.parameters.values()]
    except Exception:
        names = []

    shim = _pp200_LegacyAPIShim(sym, symst, bid, ask, mid, depth_data)

    ctx = {
        "symbol": sym,
        "sym": sym,
        "pair": sym,
        "bid": float(bid or 0.0),
        "ask": float(ask or 0.0),
        "mid": float(mid or 0.0),
        "price": float(mid or 0.0),
        "last": float(mid or 0.0),
        "depth": depth_data or {},
        "orderbook": depth_data or {},
        "depth_data": depth_data or {},
        "symst": symst,
        "state": symst,
        "ctx": symst,
        "context": {"sym": sym, "bid": bid, "ask": ask, "mid": mid, "depth": depth_data},
        "api": shim,
        "client": shim,
        "exchange": shim,
        "now": _pp200_now(),
        "ts": _pp200_now(),
    }

    # optional: pass nlp/news snapshot if available
    try:
        intel = getattr(bot, "_pp180_intel", None)
        if isinstance(intel, dict):
            ctx["intel"] = intel
            ctx["news"] = intel.get("news")
            ctx["sentiment"] = intel.get("sentiment")
            ctx["text"] = intel.get("text")
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # PP600: Legacy candle injection (close/high/low series + last candle dict)
    try:
        _ticks = []
        _tf15 = []
        _tf60 = []
        try:
            _ticks = list(getattr(symst, "prices", None) or [])
        except Exception:
            _ticks = []
        try:
            _tf15 = list(getattr(symst, "tf15_closes", None) or [])
        except Exception:
            _tf15 = []
        try:
            _tf60 = list(getattr(symst, "tf60_closes", None) or [])
        except Exception:
            _tf60 = []
        # ensure current mid is reflected
        try:
            _m = float(mid or 0.0)
            if _m > 0:
                if not _ticks or float(_ticks[-1] or 0.0) != _m:
                    _ticks = (_ticks + [_m])[-512:]
                if not _tf15 or float(_tf15[-1] or 0.0) != _m:
                    _tf15 = (_tf15 + [_m])[-512:]
                if not _tf60 or float(_tf60[-1] or 0.0) != _m:
                    _tf60 = (_tf60 + [_m])[-512:]
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        _close = _pp600_series(_tf15 or _ticks)
        _close_fast = _pp600_series(_ticks)
        _close_slow = _pp600_series(_tf60 or _tf15 or _ticks)

        try:
            _bid = float(bid or 0.0)
            _ask = float(ask or 0.0)
            _mid = float(mid or 0.0)
            _hi = max([x for x in (_bid, _ask, _mid) if x > 0] or [0.0])
            _lo = min([x for x in (_bid, _ask, _mid) if x > 0] or [0.0])
        except Exception:
            _hi = 0.0
            _lo = 0.0
            _mid = float(mid or 0.0) if mid else 0.0

        candle = {"open": float(_mid or 0.0), "high": float(_hi or 0.0), "low": float(_lo or 0.0), "close": float(_mid or 0.0)}

        ctx["close"] = _close
        ctx["high"] = _close
        ctx["low"] = _close
        ctx["open"] = _close
        ctx["closes"] = _close
        ctx["close_fast"] = _close_fast
        ctx["close_slow"] = _close_slow
        ctx["candle"] = candle
        ctx["ohlc"] = candle
        ctx["ohlcv"] = {**candle, "volume": 0.0}
        ctx["close_price"] = float(_close)
        ctx["high_price"] = float(_hi or 0.0)
        ctx["low_price"] = float(_lo or 0.0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")


    if names:
        for nm in names:
            if nm in ctx:
                kw[nm] = ctx[nm]
        # fill required params that are missing with safe defaults
        try:
            if _pp200_inspect is not None:
                sig = _pp200_inspect.signature(fn)
                for p in sig.parameters.values():
                    if p.name in kw:
                        continue
                    if p.default is not _pp200_inspect._empty:
                        continue
                    # required: provide safe placeholder
                    if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
                        continue
                    kw[p.name] = 0.0
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

    return kw

def _pp200_self_heal_call(fn, *, name: str, sym, symst, bid, ask, mid, depth_data, bot, ledger: _pp200_IntegrityLedger):
    """
    Never silent: on failure, report and attempt a single parameter repair pass, then return neutral.
    """
    try:
        # PP200PS Safety: hard timeout for legacy gene execution (best-effort; works on main thread on Linux/Termux)
        _pp200_alarm_set = False
        _pp200_sig = None
        _pp200_old_handler = None
        try:
            _ms = float(os.getenv("PP200PS_GENE_TIMEOUT_MS", "25") or 25.0)
        except Exception:
            _ms = 25.0
        if _ms and float(_ms) > 0:
            try:
                import signal as _pp200_signal
                _pp200_sig = _pp200_signal
                def _pp200__alarm_handler(signum, frame):
                    raise TimeoutError("legacy_gene_timeout")
                try:
                    _pp200_old_handler = _pp200_sig.getsignal(_pp200_sig.SIGALRM)
                except Exception:
                    _pp200_old_handler = None
                try:
                    _pp200_sig.signal(_pp200_sig.SIGALRM, _pp200__alarm_handler)
                    # setitimer provides sub-second precision; fallback to alarm if not present
                    if hasattr(_pp200_sig, "setitimer"):
                        _pp200_sig.setitimer(_pp200_sig.ITIMER_REAL, max(0.001, float(_ms) / 1000.0))
                    else:
                        _pp200_sig.alarm(int(max(1, round(float(_ms) / 1000.0))))
                    _pp200_alarm_set = True
                except Exception:
                    _pp200_alarm_set = False
            except Exception:
                _pp200_alarm_set = False
        kw = _pp200_build_call_kwargs(fn, sym=sym, symst=symst, bid=bid, ask=ask, mid=mid, depth_data=depth_data, bot=bot)
        out = fn(**kw) if kw else fn()
        # disable gene timeout
        try:
            if _pp200_alarm_set and _pp200_sig is not None:
                try:
                    if hasattr(_pp200_sig, "setitimer"):
                        _pp200_sig.setitimer(_pp200_sig.ITIMER_REAL, 0)
                    else:
                        _pp200_sig.alarm(0)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                try:
                    if _pp200_old_handler is not None:
                        _pp200_sig.signal(_pp200_sig.SIGALRM, _pp200_old_handler)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        ledger.mark_ok(name)
        return out, None
    except Exception as e1:
        # disable gene timeout (if set)
        try:
            if _pp200_alarm_set and _pp200_sig is not None:
                try:
                    if hasattr(_pp200_sig, "setitimer"):
                        _pp200_sig.setitimer(_pp200_sig.ITIMER_REAL, 0)
                    else:
                        _pp200_sig.alarm(0)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                try:
                    if _pp200_old_handler is not None:
                        _pp200_sig.signal(_pp200_sig.SIGALRM, _pp200_old_handler)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        ledger.mark_fail(name, f"{type(e1).__name__}: {e1}")
        ledger.mark_heal_attempt(name)
        _pp200_log(bot, f"[PP200][HEAL] gene={name} failed: {type(e1).__name__}: {e1}", level="warning")
        # attempt minimal repair: drop kwargs that may be unexpected
        try:
            # try calling with only (sym) if possible
            if _pp200_inspect is not None:
                sig = _pp200_inspect.signature(fn)
                params = list(sig.parameters.values())
                # prepare positional attempts
                args = []
                if params:
                    # choose up to 2 common args
                    if len(params) >= 1:
                        args.append(sym)
                    if len(params) >= 2:
                        args.append(depth_data or {})
                out2 = fn(*args)
                ledger.mark_heal_success(name)
                ledger.mark_ok(name)
                return out2, None
        except Exception as e2:
            ledger.mark_fail(name, f"{type(e2).__name__}: {e2}")
            _pp200_log(bot, f"[PP200][HEAL] gene={name} repair failed: {type(e2).__name__}: {e2}", level="warning")
        # not silent: mark degraded and return neutral
        ledger.mark_degraded(name, "neutral_return_after_fail")
        return {"vote": "HOLD", "score": 0.0, "err": str(e1)}, str(e1)

def _pp200_gene_keywords(name: str) -> bool:
    nm = (name or "").lower()
    keys = (
        "nlp", "sentiment", "emotion", "news", "text",
        "arb", "arbitrage", "triangle", "tri",
        "fractal", "harmonic", "elliott", "hurst", "fibo", "gann",
        "pattern", "regime", "entropy", "denoise", "kalman", "volume", "orderflow", "imbalance",
    )
    for k in keys:
        if k in nm:
            return True
    # also accept legacy pp tags
    if nm.startswith("_pp") or "pp" in nm:
        return True
    return False

def _pp200_is_callable_gene(obj) -> bool:
    try:
        return callable(obj) and (not isinstance(obj, type))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

class _pp200_LegacyBridge:
    """
    Upgrades PP190 sandbox into an "intelligent protocol adapter":
    - discovers live genes + recovered commented genes
    - normalizes outputs
    - provides secondary confirmation & veto
    - self-heals calls (non-silent)
    """
    def __init__(self, bot, base_sandbox=None):
        self.bot = bot
        self.base = base_sandbox
        self.ledger = _pp200_IntegrityLedger()
        # WisdomOracle cache (best-effort; resolved via globals to avoid import-time ordering issues)
        try:
            _wo = globals().get("WisdomOracle", None)
            self._pp200_oracle = _wo() if callable(_wo) else None
        except Exception:
            self._pp200_oracle = None
        self.genes: _pp200_Dict[str, _pp200_Any] = {}
        self.weights: _pp200_Dict[str, float] = {}
        self.errs: _pp200_Dict[str, str] = {}
        self._rr: _pp200_List[str] = []
        self._rr_i = 0
        try:
            self._lock = _pp200_threading.Lock() if _pp200_threading is not None else None
        except Exception:
            self._lock = None

        self._discover_live_genes()
        self._recover_commented_genes()
        self._rr = list(self.genes.keys())
        # keep deterministic order
        self._rr.sort()

    def _discover_live_genes(self):
        # take genes from base sandbox if exists
        try:
            if self.base is not None and hasattr(self.base, "genes") and isinstance(self.base.genes, dict):
                for nm, g in list(self.base.genes.items()):
                    try:
                        fn = getattr(g, "fn", None) or getattr(g, "func", None) or getattr(g, "callable", None)
                        if fn is None and callable(g):
                            fn = g
                        if fn is None:
                            continue
                        if not _pp200_gene_keywords(nm):
                            continue
                        self.genes[str(nm)] = fn
                        self.weights[str(nm)] = float(getattr(g, "weight", 0.3) or 0.3)
                        self.ledger.register(str(nm), recovered=False)
                    except Exception as e:
                        self.ledger.mark_fail(str(nm), f"discover_live:{type(e).__name__}:{e}")
            else:
                # fallback: scan globals
                for nm, obj in list(globals().items()):
                    if not _pp200_gene_keywords(nm):
                        continue
                    if _pp200_is_callable_gene(obj):
                        self.genes[str(nm)] = obj
                        self.weights[str(nm)] = 0.3
                        self.ledger.register(str(nm), recovered=False)
        except Exception as e:
            _pp200_log(self.bot, f"[PP200] discover_live_genes error: {e}", level="warning")

    def _recover_commented_genes(self):
        # recover commented blocks from this file (self-contained)
        try:
            src = globals().get("__file__")
            if src:
                try:
                    with open(src, "r", encoding="utf-8", errors="replace") as f:
                        text = f.read()
                except Exception:
                    text = ""
            else:
                text = ""
        except Exception:
            text = ""

        if not text:
            return

        blocks = _pp200_extract_commented_blocks(text)
        # Keep only relevant blocks (NLP/arb/fractal keywords)
        good_blocks = []
        for b in blocks:
            head = (b.strip().splitlines() or [""])[0].lower()
            if any(k in b.lower() for k in ("nlp", "sentiment", "arb", "arbitrage", "triangle", "fractal", "harmonic", "hurst", "elliott", "fibo", "gann", "volume", "orderflow")):
                good_blocks.append(b)

        # Attempt compile+exec per block, register top-level callables.
        for code in good_blocks[:160]:
            try:
                ns = _pp200_safe_exec(code)
            except Exception as e:
                # Not silent: count as recovered-but-faulty (kept in ledger)
                name_hint = ""
                try:
                    m = _pp200_re.search(r"\b(def|class)\s+([A-Za-z_][A-Za-z0-9_]*)", code)
                    if m:
                        name_hint = m.group(2)
                except Exception:
                    name_hint = ""
                if name_hint:
                    self.ledger.register(name_hint, recovered=True)
                    self.ledger.mark_fail(name_hint, f"recover_exec:{type(e).__name__}:{e}")
                continue

            for nm, obj in list(ns.items()):
                if not _pp200_gene_keywords(nm):
                    continue
                if _pp200_is_callable_gene(obj):
                    # avoid overriding live gene of same name
                    key = str(nm)
                    if key in self.genes:
                        continue
                    self.genes[key] = obj
                    self.weights[key] = 0.18  # recovered genes start lower
                    self.ledger.register(key, recovered=True)

    def _next_names(self, batch: int) -> _pp200_List[str]:
        if not self._rr:
            return []
        b = max(1, min(int(batch), max(1, len(self._rr))))
        out = []
        # Skip genes marked NON_OPERATIONAL until their retry window.
        try:
            now = _pp200_now()
        except Exception:
            now = _pp920_time.time()
        tries = 0
        while len(out) < b and tries < (b * 4 + 8):
            tries += 1
            nm = self._rr[self._rr_i % len(self._rr)]
            self._rr_i += 1
            rec = None
            try:
                rec = self.ledger.non_operational.get(nm) if isinstance(getattr(self.ledger, "non_operational", None), dict) else None
            except Exception:
                rec = None
            if isinstance(rec, dict):
                try:
                    nrt = float(rec.get("next_retry_ts", 0.0) or 0.0)
                except Exception:
                    nrt = 0.0
                if now < nrt:
                    # keep gene alive; do not skip (Fortress rule: no gene burial)
                    pass
            out.append(nm)
        return out

    def tick(self, sym: str, symst, bid: float, ask: float, mid: float, depth_data: dict) -> dict:
        """
        Evaluate genes in a budgeted manner; keep cache in bot._pp200_legacy_cache.

        Fortress v400 upgrades (non-breaking):
          - cap affects per-tick sampling only (no gene burial)
          - rolling vote window so *all* genes participate in council over time
        """
        bot = self.bot
        try:
            batch = int(os.getenv("PP200_GENE_BATCH", "10") or 10)
        except Exception:
            batch = 10
        try:
            cap = int(os.getenv("PP200_GENE_CAP", "60") or 60)
        except Exception:
            cap = 60
        # v8062: autonomous universe expansion (anti-starvation)
        # If user is stuck trading only primaries (PAXGIRT/USDTIRT/BTCIRT) for long, add TOP-ranked IRT symbols.
        try:
            if int(os.getenv("PP8062_AUTO_EXPAND_SYMBOLS", "1") or 1):
                _nowu = float(_pp920_time.time())
                _lastu = float(getattr(bot, "_pp8062_last_universe_refresh", 0.0) or 0.0)
                _refresh = float(os.getenv("PP8062_UNIVERSE_REFRESH_SEC", "30") or 30.0)
                if (_nowu - _lastu) >= _refresh:
                    try:
                        setattr(bot, "_pp8062_last_universe_refresh", float(_nowu))
                    except Exception:
                        pass
                    _prim = ["PAXGIRT", "USDTIRT", "BTCIRT"]
                    _syms = [str(s).strip().upper() for s in (getattr(bot, "symbols", []) or []) if str(s).strip()]
                    # only if currently limited to primaries
                    if _syms and len(_syms) <= 3 and all(s in _prim for s in _syms):
                        # check notrade duration (across wallets)
                        _lastt = 0.0
                        _lb = getattr(bot, "_pp_last_buy_ts_by_wallet", {}) or {}
                        _ls = getattr(bot, "_pp_last_sell_ts_by_wallet", {}) or {}
                        if isinstance(_lb, dict):
                            for _v in _lb.values():
                                try:
                                    _lastt = max(_lastt, float(_v or 0.0))
                                except Exception:
                                    pass
                        if isinstance(_ls, dict):
                            for _v in _ls.values():
                                try:
                                    _lastt = max(_lastt, float(_v or 0.0))
                                except Exception:
                                    pass
                        if _lastt <= 0.0:
                            _lastt = float(getattr(bot, "_pp_boot_ts", 0.0) or 0.0)
                        _dt = max(0.0, float(_nowu) - float(_lastt or 0.0))
                        _need = float(os.getenv("PP8062_EXPAND_AFTER_SEC", "900") or 900.0)
                        if _dt >= _need:
                            _cand = []
                            # Use dashboard ranking if available (doesn't require extra API calls)
                            _ranked = list(getattr(bot, "_dash_ranked", []) or [])
                            for _r in _ranked:
                                try:
                                    _s = str(_r[0] if isinstance(_r, (tuple, list)) and _r else _r).strip().upper()
                                except Exception:
                                    continue
                                if (not _s.endswith("IRT")) or (_s in _prim) or (_s in _cand):
                                    continue
                                _cand.append(_s)
                                if len(_cand) >= 8:
                                    break
                            # Fallback to last scanned top8 cache
                            if not _cand:
                                try:
                                    _cand = [str(x).strip().upper() for x in (getattr(bot, "_pp733_top8_syms", []) or []) if str(x).strip()][:8]
                                except Exception:
                                    _cand = []
                            if _cand:
                                _new = list(_prim) + [s for s in _cand if s not in _prim]
                                try:
                                    bot.symbols = _new
                                except Exception:
                                    pass
                                try:
                                    bot._pp733_top8_syms = list(_cand)
                                except Exception:
                                    pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="pp8062_expand")

        # cap affects sampling, NOT registry (Fortress: no gene burial)
        try:
            if int(cap) > 0:
                batch = min(int(batch), int(cap))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        # strict time budget to keep latency bounded (Termux-safe)
        try:
            _budget_ms = float(os.getenv("PP200PS_BUDGET_MS", "95") or 95.0)
        except Exception:
            _budget_ms = 95.0
        _t0 = time.perf_counter()
        _budget_s = max(0.02, min(0.35, float(_budget_ms) / 1000.0))

        # Rolling vote cache init (stdlib-only)
        try:
            from collections import deque as _pp200_deque
        except Exception:
            _pp200_deque = None
        try:
            if not isinstance(getattr(self, "_pp200_gene_last", None), dict):
                self._pp200_gene_last = {}
            if _pp200_deque is not None:
                if not isinstance(getattr(self, "_pp200_vote_q", None), _pp200_deque):
                    self._pp200_vote_q = _pp200_deque()
            else:
                if getattr(self, "_pp200_vote_q", None) is None:
                    self._pp200_vote_q = []
            if not isinstance(getattr(self, "_pp200_agg", None), dict):
                self._pp200_agg = {"score": 0.0, "w_sum": 0.0, "veto": 0.0}
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        try:
            now_ts = float(_pp200_now())
        except Exception:
            now_ts = float(_pp920_time.time())

        # Runtime heavy-gene profiling (real-time): detect heavy genes by measured latency (not name-only)
        try:
            gperf = getattr(self, "_pp200_gperf", None)
            if not isinstance(gperf, dict):
                gperf = {}
                setattr(self, "_pp200_gperf", gperf)
            gperf_id = getattr(self, "_pp200_gperf_by_id", None)
            if not isinstance(gperf_id, dict):
                gperf_id = {}
                setattr(self, "_pp200_gperf_by_id", gperf_id)
        except Exception:
            gperf = {}
            gperf_id = {}
            try:
                setattr(self, "_pp200_gperf", gperf)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            try:
                setattr(self, "_pp200_gperf_by_id", gperf_id)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
        try:
            _pp200_heavy_ms = float(os.getenv("PP200_HEAVY_MS", "55") or 55.0)
        except Exception:
            _pp200_heavy_ms = 55.0
        _pp200_heavy_ms = max(5.0, min(2000.0, float(_pp200_heavy_ms)))
        try:
            _pp200_heavy_min_samples = int(os.getenv("PP200_HEAVY_MIN_SAMPLES", "2") or 2)
        except Exception:
            _pp200_heavy_min_samples = 2
        _pp200_heavy_min_samples = max(1, min(20, int(_pp200_heavy_min_samples)))
        try:
            _pp200_profile_budget = int(os.getenv("PP200_PROFILE_UNKNOWN_PER_TICK", "1") or 1)
        except Exception:
            _pp200_profile_budget = 1
        _pp200_profile_budget = max(0, min(16, int(_pp200_profile_budget)))
        # Memoization: cache gene name -> cid (Termux-safe, avoids per-tick hashing)
        try:
            _pp200_cid_cache = getattr(self, '_pp200_gene_cid_cache', None)
            if not isinstance(_pp200_cid_cache, dict):
                _pp200_cid_cache = {}
                setattr(self, '_pp200_gene_cid_cache', _pp200_cid_cache)
        except Exception:
            _pp200_cid_cache = {}

        def _pp200_gene_cid(_s: str) -> str:
            try:
                _s = str(_s or '').strip()
            except Exception:
                _s = ''
            if not _s:
                return 'GENE:gene:0000000000'
            try:
                _cached = _pp200_cid_cache.get(_s)
                if isinstance(_cached, str) and _cached:
                    return _cached
            except Exception:
                _cached = None
            try:
                _h = hashlib.sha1(_s.encode('utf-8', 'replace')).hexdigest()[:10]
            except Exception:
                _h = '0000000000'
            try:
                _base = re.sub(r'[^a-zA-Z0-9_]+', '_', _s).strip('_')
            except Exception:
                _base = _s
            _base = (_base[:42] if _base else 'gene')
            _cid = 'GENE:{}:{}'.format(_base, _h)
            try:
                # Prevent unbounded growth; keep within sane limit
                if len(_pp200_cid_cache) < 90000:
                    _pp200_cid_cache[_s] = _cid
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            return _cid

        def _pp200_get_perf_rec(_nm: str):
            try:
                _rec = gperf.get(_nm)
            except Exception:
                _rec = None
            try:
                _cid = _pp200_gene_cid(_nm)
            except Exception:
                _cid = "GENE:gene:0000000000"
            if not isinstance(_rec, dict):
                try:
                    _rec = gperf_id.get(_cid)
                except Exception:
                    _rec = None
            return _rec, _cid

        def _pp200_update_perf(_nm: str, _ms: float) -> None:
            try:
                if _ms is None:
                    return
                _ms = float(_ms)
                if _ms < 0:
                    _ms = 0.0
                _rec, _cid = _pp200_get_perf_rec(_nm)
                if not isinstance(_rec, dict):
                    _rec = {"n": 0, "ema_ms": 0.0, "last_ms": 0.0, "max_ms": 0.0}
                try:
                    _n = int(_rec.get("n", 0) or 0) + 1
                except Exception:
                    _n = 1
                try:
                    _ema = float(_rec.get("ema_ms", 0.0) or 0.0)
                except Exception:
                    _ema = 0.0
                try:
                    _alpha = 0.22 if _n < 8 else 0.12
                except Exception:
                    _alpha = 0.12
                try:
                    _ema = (_alpha * _ms) + ((1.0 - _alpha) * _ema)
                except Exception:
                    _ema = _ms
                try:
                    _mx = float(_rec.get("max_ms", 0.0) or 0.0)
                except Exception:
                    _mx = 0.0
                if _ms > _mx:
                    _mx = _ms
                _rec["n"] = int(_n)
                _rec["ema_ms"] = float(_ema)
                _rec["last_ms"] = float(_ms)
                _rec["max_ms"] = float(_mx)
                try:
                    _rec["heavy"] = bool((_ema >= _pp200_heavy_ms) or (_ms >= _pp200_heavy_ms))
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                try:
                    gperf[_nm] = _rec
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                try:
                    if isinstance(gperf_id, dict):
                        # keep minimal id-based record; attach last known name for resilience
                        _r2 = dict(_rec)
                        _r2["name"] = str(_nm)[:120]
                        gperf_id[_cid] = _r2
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
            except Exception as _pp200_e:
                try:
                    _pp200_heal(_pp200_e, tag="pp200_perf_update")
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

        def _pp200_is_heavy_runtime(_nm: str) -> bool:
            try:
                _rec, _cid = _pp200_get_perf_rec(_nm)
                if isinstance(_rec, dict):
                    try:
                        _n = int(_rec.get("n", 0) or 0)
                    except Exception:
                        _n = 0
                    if _n >= _pp200_heavy_min_samples:
                        try:
                            if bool(_rec.get("heavy", False)):
                                return True
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                        try:
                            if float(_rec.get("ema_ms", 0.0) or 0.0) >= _pp200_heavy_ms:
                                return True
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                        try:
                            if float(_rec.get("last_ms", 0.0) or 0.0) >= _pp200_heavy_ms:
                                return True
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            return False
        try:
            window_sec = float(os.getenv("PP200_VOTE_WINDOW_SEC", "55") or 55.0)
        except Exception:
            window_sec = 55.0
        window_sec = max(10.0, min(300.0, float(window_sec)))

        # purge expired votes without scanning all genes (deque-based)
        try:
            q = getattr(self, "_pp200_vote_q", None)
            glast = getattr(self, "_pp200_gene_last", {}) if isinstance(getattr(self, "_pp200_gene_last", None), dict) else {}
            agg = getattr(self, "_pp200_agg", {}) if isinstance(getattr(self, "_pp200_agg", None), dict) else {"score": 0.0, "w_sum": 0.0, "veto": 0.0}
            if hasattr(q, "popleft"):
                while q:
                    try:
                        ts0, nm0 = q[0]
                    except Exception:
                        break
                    if (now_ts - float(ts0)) <= window_sec:
                        break
                    try:
                        q.popleft()
                    except Exception:
                        break
                    rec = glast.get(nm0)
                    # only purge if this entry is still the latest for the gene
                    try:
                        if isinstance(rec, dict) and float(rec.get("ts", 0.0) or 0.0) == float(ts0):
                            agg["score"] = float(agg.get("score", 0.0) or 0.0) - float(rec.get("score", 0.0) or 0.0)
                            agg["w_sum"] = float(agg.get("w_sum", 0.0) or 0.0) - float(rec.get("w_sum", 0.0) or 0.0)
                            agg["veto"] = float(agg.get("veto", 0.0) or 0.0) - float(rec.get("veto", 0.0) or 0.0)
                            glast.pop(nm0, None)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
            else:
                # list fallback: bounded trimming (best-effort)
                try:
                    if isinstance(q, list) and len(q) > 50000:
                        self._pp200_vote_q = q[-25000:]
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
            setattr(self, "_pp200_gene_last", glast)
            setattr(self, "_pp200_agg", agg)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        names = self._next_names(batch)
        # Async heavy-gene execution (Termux): prioritize completed heavy futures without blocking
        _pp200_executor = getattr(self, "_pp200_executor", None)
        _pp200_futures = getattr(self, "_pp200_futures", None)
        _pp200_fmeta = getattr(self, "_pp200_fmeta", None)
        _pp200_last_async = getattr(self, "_pp200_last_async", None)
        if not isinstance(_pp200_futures, dict):
            _pp200_futures = {}
            self._pp200_futures = _pp200_futures
        if not isinstance(_pp200_fmeta, dict):
            _pp200_fmeta = {}
            self._pp200_fmeta = _pp200_fmeta
        if not isinstance(_pp200_last_async, dict):
            _pp200_last_async = {}
            self._pp200_last_async = _pp200_last_async

        # compile heavy regex once (name-based heuristic; overrideable by env)
        try:
            _pp200_heavy_rx = getattr(self, "_pp200_heavy_rx", None)
        except Exception:
            _pp200_heavy_rx = None
        if _pp200_heavy_rx is None:
            try:
                _rx_pat = os.getenv(
                    "PP200_HEAVY_GENE_REGEX",
                    r"(hurst|fractal|kalman|wavelet|garch|hmm|particle|monte|fft|fourier|svd|pca|lstm|transformer|xgboost|catboost|lightgbm|deep|neural|dnn|vae|gan|bayes|markov|entropy|lyapunov|dfa|arima|sarima|prophet|seasonal|copula|volatility|stoch(?:astic)?\s*(?:sim|mc))",
                )
                _pp200_heavy_rx = re.compile(_rx_pat, re.IGNORECASE)
            except Exception as _pp200_e:
                _pp200_heavy_rx = None
                try:
                    _pp200_heal(_pp200_e, tag="pp200_heavy_rx")
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
            try:
                setattr(self, "_pp200_heavy_rx", _pp200_heavy_rx)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        # scheduling limits
        try:
            _pp200_async_sched_cap = int(os.getenv("PP200_ASYNC_SCHEDULE_PER_TICK", "2") or 2)
        except Exception:
            _pp200_async_sched_cap = 2
        _pp200_async_sched_cap = max(0, min(8, int(_pp200_async_sched_cap)))
        _pp200_async_sched = 0
        try:
            _pp200_async_queue_cap = int(os.getenv("PP200_ASYNC_QUEUE_CAP", "0") or 0)
        except Exception:
            _pp200_async_queue_cap = 0
        if _pp200_async_queue_cap <= 0:
            _pp200_async_queue_cap = 12
        _pp200_async_queue_cap = max(2, min(64, int(_pp200_async_queue_cap)))
        try:
            _pp200_hard_to = float(os.getenv("PP200_ASYNC_HARD_TIMEOUT_SEC", "4.5") or 4.5)
        except Exception:
            _pp200_hard_to = 4.5
        _pp200_hard_to = max(1.0, min(30.0, float(_pp200_hard_to)))

        # promote ready heavy futures into this tick's evaluation set (fast convergence)
        ready = []
        try:
            if isinstance(_pp200_futures, dict) and _pp200_futures:
                for _nm, _ft in list(_pp200_futures.items()):
                    if len(ready) >= 4:
                        break
                    try:
                        _st = float(_pp200_fmeta.get(_nm, now_ts))
                    except Exception:
                        _st = now_ts
                    # drop stale/blocked futures from tracking to avoid deadlocks (thread keeps running but we stop waiting)
                    if (now_ts - float(_st)) > _pp200_hard_to:
                        try:
                            _pp200_futures.pop(_nm, None)
                            _pp200_fmeta.pop(_nm, None)
                            _pp200_heal(RuntimeError(f"PP200 async hard-timeout gene={_nm} age={now_ts-_st:.2f}s"), tag="pp200_async_timeout")
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                        continue
                    try:
                        if hasattr(_ft, "done") and _ft.done():
                            ready.append(_nm)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
        except Exception as _pp200_e:
            try:
                _pp200_heal(_pp200_e, tag="pp200_ready_scan")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        if ready:
            # keep stable order: completed first, then the round-robin batch without duplicates
            try:
                names = list(ready) + [x for x in list(names) if x not in set(ready)]
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        details = []
        # batch-only stats (diagnostic)
        batch_score_sum = 0.0
        batch_w_sum = 0.0
        batch_veto_score = 0.0

        # Latency-wisdom weight dampening during fault storms (no disabling, just influence reduction)
        _pp200_fault_factor = 1.0
        try:
            ring = list(globals().get("_pp200_heal_ring", []) or [])
            _now0 = float(_pp920_time.time())
            _win = float(os.getenv("PP200_FAULT_WINDOW_SEC", "30") or 30.0)
            _thr = int(os.getenv("PP200_FAULT_STORM", "12") or 12)
            _fc = 0
            for _t, *_rest in ring:
                try:
                    if (_now0 - float(_t)) <= _win:
                        _fc += 1
                except Exception:
                    continue
            if _fc >= _thr:
                _pp200_fault_factor = 0.70
            elif _fc >= max(3, int(_thr * 0.5)):
                _pp200_fault_factor = 0.85
        except Exception:
            _pp200_fault_factor = 1.0

        for nm in names:
            if (time.perf_counter() - _t0) >= _budget_s:
                break
            fn = self.genes.get(nm)
            if fn is None:
                continue
            w_base = float(self.weights.get(nm, 0.15) or 0.15)
            w_base = max(0.01, min(1.0, w_base))

            # Wisdom-weight (oracle_wisdom.json) + latency wisdom (perf) without disabling
            w_or = 1.0
            try:
                _orc = getattr(self, "_pp200_oracle", None)
                if _orc is not None and hasattr(_orc, "get_weight"):
                    w_or = float(_orc.get_weight(nm, default=1.0) or 1.0)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="pp200_oracle_weight")

            w_lat = 1.0
            try:
                _rec, _cid = _pp200_get_perf_rec(nm)
                _tref = float(_pp200_heavy_ms)
                if isinstance(_rec, dict) and _tref > 1.0:
                    _ema = float(_rec.get("ema_ms", 0.0) or 0.0)
                    _last = float(_rec.get("last_ms", 0.0) or 0.0)
                    _mx = max(_ema, _last)
                    if _mx > _tref:
                        _r = max(1.0, _mx / _tref)
                        w_lat = 1.0 / (1.0 + 0.85 * (_r - 1.0))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="pp200_latency_weight")
                w_lat = 1.0

            # Apply global fault-storm dampening (computed once per tick)
            try:
                w_lat = float(w_lat) * float(_pp200_fault_factor)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

            w = float(w_base) * float(max(0.05, w_or)) * float(max(0.15, w_lat))
            w = float(max(0.01, min(3.0, w)))

            # Async heavy-gene execution: schedule heavy genes in background to avoid blocking (Termux real-time)
            out = None
            err = None
            _is_heavy = False
            _pp200_prof_unknown = False
            # Prefer runtime-based heavy detection; fall back to regex heuristic
            try:
                _is_heavy = bool(_pp200_is_heavy_runtime(nm))
            except Exception:
                _is_heavy = False
            try:
                if (not _is_heavy) and (_pp200_heavy_rx is not None):
                    _is_heavy = bool(_pp200_heavy_rx.search(str(nm)))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            # Avoid first-run freezes: profile unknown genes asynchronously with a per-tick budget
            try:
                _rec = None
                try:
                    _rec = gperf.get(nm)
                except Exception:
                    _rec = None
                _n = 0
                if isinstance(_rec, dict):
                    try:
                        _n = int(_rec.get("n", 0) or 0)
                    except Exception:
                        _n = 0
                if (not _is_heavy) and (_pp200_executor is not None) and (_n < _pp200_heavy_min_samples) and (_pp200_profile_budget > 0):
                    _is_heavy = True
                    _pp200_prof_unknown = True
                    _pp200_profile_budget -= 1
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

            if _is_heavy and (_pp200_executor is not None):
                try:
                    _ft = _pp200_futures.get(nm)
                    # If a future completed, consume it immediately (no blocking)
                    if _ft is not None and hasattr(_ft, "done") and _ft.done():
                        try:
                            out, err = _ft.result(timeout=0)
                        except Exception as _pp200_e:
                            try:
                                _pp200_heal(_pp200_e, tag="pp200_async_result")
                            except Exception as _pp200_e:
                                _pp200_heal(_pp200_e, tag="exc_pass")
                                pass
                            out, err = ("HOLD", 0.0, {"async_error": str(_pp200_e)}), True
                        try:
                            _st0 = _pp200_fmeta.get(nm, now_ts)
                            try:
                                _st0 = float(_st0)
                            except Exception:
                                _st0 = now_ts
                            _pp200_update_perf(nm, max(0.0, (now_ts - float(_st0)) * 1000.0))
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="pp200_perf_async")
                        try:
                            _pp200_last_async[nm] = (out, err, now_ts)
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                        try:
                            _pp200_futures.pop(nm, None)
                            _pp200_fmeta.pop(nm, None)
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                    else:
                        # Schedule if not already running and within per-tick limits
                        try:
                            if _ft is None and (_pp200_async_sched < _pp200_async_sched_cap) and (len(_pp200_futures) < _pp200_async_queue_cap):
                                _pp200_async_sched += 1
                                _pp200_fmeta[nm] = now_ts
                                _pp200_futures[nm] = _pp200_executor.submit(
                                    _pp200_self_heal_call,
                                    fn,
                                    name=nm,
                                    sym=sym,
                                    symst=symst,
                                    bid=bid,
                                    ask=ask,
                                    mid=mid,
                                    depth_data=depth_data,
                                    bot=bot,
                                    ledger=self.ledger,
                                )
                        except Exception as _pp200_e:
                            try:
                                _pp200_heal(_pp200_e, tag="pp200_async_submit")
                            except Exception as _pp200_e:
                                _pp200_heal(_pp200_e, tag="exc_pass")
                                pass
                        # Use last-known async output while pending (stale, lower confidence)
                        try:
                            if nm in _pp200_last_async:
                                out, err, _ts_last = _pp200_last_async.get(nm)
                                try:
                                    # degrade confidence for stale results to avoid overpowering council
                                    if isinstance(out, tuple) and len(out) == 3:
                                        _v, _c, _m = out
                                        if isinstance(_m, dict):
                                            _m2 = dict(_m)
                                            _m2["async_stale"] = True
                                            out = (_v, float(_c) * 0.70, _m2)
                                except Exception as _pp200_e:
                                    _pp200_heal(_pp200_e, tag="exc_pass")
                                    pass
                            else:
                                out, err = ("HOLD", 0.0, {"async_pending": True}), False
                        except Exception:
                            out, err = ("HOLD", 0.0, {"async_pending": True}), False
                except Exception as _pp200_e:
                    try:
                        _pp200_heal(_pp200_e, tag="pp200_async_sched")
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
            # Fallback: synchronous call for non-heavy genes (or when executor unavailable)
            if out is None:
                _pp200_t0 = None
                try:
                    _pp200_t0 = time.perf_counter()
                except Exception:
                    _pp200_t0 = None
                out, err = _pp200_self_heal_call(fn, name=nm, sym=sym, symst=symst, bid=bid, ask=ask, mid=mid, depth_data=depth_data, bot=bot, ledger=self.ledger)
                try:
                    if _pp200_t0 is not None:
                        _pp200_update_perf(nm, max(0.0, (time.perf_counter() - _pp200_t0) * 1000.0))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="pp200_perf_sync")

            vote, conf, meta = _pp200_normalize_vote(out)

            # Noise reduction: mark consistently irrelevant genes as NON_OPERATIONAL (with periodic retry)
            try:
                st = getattr(self, "_gene_stats", None)
                if st is None or not isinstance(st, dict):
                    self._gene_stats = {}
                    st = self._gene_stats
                rec = st.get(nm, [0, 0, 0])  # runs, non_hold, fails
                rec[0] = int(rec[0]) + 1
                if vote in ("BUY", "SELL") and float(conf) >= 0.20:
                    rec[1] = int(rec[1]) + 1
                if err:
                    rec[2] = int(rec[2]) + 1
                st[nm] = rec
                # irrelevance: hold-only for long period
                if rec[0] >= 40 and rec[1] == 0 and rec[2] == 0:
                    self.ledger.mark_non_operational(nm, reason="irrelevant_output_hold_only", cooldown_sec=600.0)
                # incompatibility: too many failures
                if rec[0] >= 20 and rec[2] / max(1.0, float(rec[0])) >= 0.55:
                    self.ledger.mark_non_operational(nm, reason="irrelevant_incompatible_errors", cooldown_sec=600.0)
            except Exception as _pp210_e:
                _pp200_heal(_pp210_e, tag="noise_reduction")

            # Weighted score: BUY=+1, SELL=-1, HOLD=0 times conf*weight
            sgn = 0.0
            if vote == "BUY":
                sgn = 1.0
            elif vote == "SELL":
                sgn = -1.0
            score_i = float(sgn) * float(conf) * float(w)
            eff_i = abs(float(w)) * max(0.2, float(conf))
            veto_i = float(score_i) if (abs(float(score_i)) >= 0.30 and vote in ("BUY", "SELL")) else 0.0

            batch_score_sum += float(score_i)
            batch_w_sum += float(eff_i)
            batch_veto_score += float(veto_i)

            details.append((nm, vote, float(conf), float(w), err, meta))

            # Rolling update: subtract old then add new (O(1))
            try:
                glast = getattr(self, "_pp200_gene_last", None)
                agg = getattr(self, "_pp200_agg", None)
                q = getattr(self, "_pp200_vote_q", None)
                if isinstance(glast, dict) and isinstance(agg, dict):
                    old = glast.get(nm)
                    if isinstance(old, dict):
                        agg["score"] = float(agg.get("score", 0.0) or 0.0) - float(old.get("score", 0.0) or 0.0)
                        agg["w_sum"] = float(agg.get("w_sum", 0.0) or 0.0) - float(old.get("w_sum", 0.0) or 0.0)
                        agg["veto"] = float(agg.get("veto", 0.0) or 0.0) - float(old.get("veto", 0.0) or 0.0)
                    glast[nm] = {"ts": float(now_ts), "vote": vote, "conf": float(conf), "w": float(w), "score": float(score_i), "w_sum": float(eff_i), "veto": float(veto_i)}
                    agg["score"] = float(agg.get("score", 0.0) or 0.0) + float(score_i)
                    agg["w_sum"] = float(agg.get("w_sum", 0.0) or 0.0) + float(eff_i)
                    agg["veto"] = float(agg.get("veto", 0.0) or 0.0) + float(veto_i)
                    # push to purge queue
                    if hasattr(q, "append"):
                        q.append((float(now_ts), nm))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            # Self-correction (intra-tick): if it fails repeatedly, decay weight but never disable
            try:
                ec = int(self.ledger.err_counts.get(nm, 0))
                if ec >= 3 and w > 0.05:
                    self.weights[nm] = max(0.02, w * 0.92)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

        # global aggregation (rolling window)
        try:
            agg = getattr(self, "_pp200_agg", {}) if isinstance(getattr(self, "_pp200_agg", None), dict) else {}
            score_sum = float(agg.get("score", 0.0) or 0.0)
            w_sum = float(agg.get("w_sum", 0.0) or 0.0)
            veto_score = float(agg.get("veto", 0.0) or 0.0)
        except Exception:
            score_sum = float(batch_score_sum)
            w_sum = float(batch_w_sum)
            veto_score = float(batch_veto_score)

        # final vote from global score
        final_vote = "HOLD"
        # v8062: dynamic anti-starvation threshold (token-safe)
        thr = 0.18
        try:
            thr = float(os.getenv("PP200_SCORE_THR_BASE", "0.18") or 0.18)
        except Exception:
            thr = 0.18
        try:
            floor = float(os.getenv("PP200_SCORE_THR_FLOOR", "0.08") or 0.08)
        except Exception:
            floor = 0.08
        try:
            now0 = float(now_ts)
            last = 0.0
            lb = getattr(bot, "_pp_last_buy_ts_by_wallet", {}) or {}
            ls = getattr(bot, "_pp_last_sell_ts_by_wallet", {}) or {}
            if isinstance(lb, dict):
                for _v in lb.values():
                    try:
                        last = max(last, float(_v or 0.0))
                    except Exception:
                        pass
            if isinstance(ls, dict):
                for _v in ls.values():
                    try:
                        last = max(last, float(_v or 0.0))
                    except Exception:
                        pass
            if last <= 0.0:
                last = float(getattr(bot, "_pp_boot_ts", 0.0) or 0.0)
            dt = max(0.0, now0 - float(last or 0.0))
            # staged relaxation (20m, 45m, 90m) – preserves safety floor
            try:
                r1 = float(os.getenv("PP200_RELAX_SEC_1", "1200") or 1200.0)
                r2 = float(os.getenv("PP200_RELAX_SEC_2", "2700") or 2700.0)
                r3 = float(os.getenv("PP200_RELAX_SEC_3", "5400") or 5400.0)
            except Exception:
                r1, r2, r3 = 1200.0, 2700.0, 5400.0
            if dt >= r3:
                thr = max(floor, thr * 0.45)
            elif dt >= r2:
                thr = max(floor, thr * 0.60)
            elif dt >= r1:
                thr = max(floor, thr * 0.80)
            try:
                bot._pp200_last_thr = float(thr)
                bot._pp200_last_notrade_sec = float(dt)
            except Exception:
                pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="pp200_thr")

        if score_sum >= thr:
            final_vote = "BUY"
        elif score_sum <= -thr:
            final_vote = "SELL"

        # consensus ratio from rolling votes
        consensus = 0.0
        try:
            if final_vote in ("BUY", "SELL"):
                glast = getattr(self, "_pp200_gene_last", None)
                if isinstance(glast, dict) and glast:
                    aligned = 0.0
                    active = 0.0
                    for _nm, rec in glast.items():
                        try:
                            if not isinstance(rec, dict):
                                continue
                            v = str(rec.get("vote", "HOLD") or "HOLD").upper()
                            conf = float(rec.get("conf", 0.0) or 0.0)
                            w = float(rec.get("w", 0.0) or 0.0)
                            eff = max(0.0, min(1.0, conf)) * max(0.0, w)
                            if v in ("BUY", "SELL"):
                                active += eff
                                if v == final_vote:
                                    aligned += eff
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_continue")
                            continue
                    if active > 0.0:
                        consensus = float(max(0.0, min(1.0, aligned / active)))
        except Exception:
            consensus = 0.0

        # ------------------------------------------------------------
        # PP400: Quality instrumentation (alignment + supporter pool)
        #  - O(batch) per tick (Termux-safe)
        #  - Persists via PP302 audit snapshot
        # ------------------------------------------------------------
        try:
            _audit_get = globals().get("_pp301_audit_get", None)
            _audit_touch = globals().get("_pp301_audit_touch", None)
            if callable(_audit_get) and callable(_audit_touch):
                _aud = _audit_get(self)
                _fv = str(final_vote or "HOLD").upper()
                for _it in list(details or []):
                    try:
                        _nm, _v, _c, _w, _err, _meta = _it
                    except Exception:
                        continue
                    try:
                        _nm = str(_nm)
                        if not _nm:
                            continue
                        _audit_touch(self, _nm, kind="gene")
                        _rec = _aud.get(_nm)
                        if not isinstance(_rec, dict):
                            continue
                        _gv = str(_v or "HOLD").upper()
                        if _fv in ("BUY", "SELL"):
                            if _gv == _fv:
                                _rec["aligned"] = int(_rec.get("aligned", 0) or 0) + 1
                            elif _gv in ("BUY", "SELL"):
                                _rec["misaligned"] = int(_rec.get("misaligned", 0) or 0) + 1
                            else:
                                _rec["abstain"] = int(_rec.get("abstain", 0) or 0) + 1
                        else:
                            if _gv in ("BUY", "SELL"):
                                _rec["aggressive"] = int(_rec.get("aggressive", 0) or 0) + 1
                            else:
                                _rec["aligned_hold"] = int(_rec.get("aligned_hold", 0) or 0) + 1
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="pp400_align")
                        continue
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="pp400_align_outer")

        try:
            # Supporter pool is stored on bot for cross-module access (BUY -> outcome).
            _pool = getattr(bot, "_pp400_support_pool", None)
            if not isinstance(_pool, dict):
                _pool = {"BUY": {}, "SELL": {}}
                setattr(bot, "_pp400_support_pool", _pool)

            _symU = str(sym).upper()

            # Config (safe defaults)
            try:
                _pool_win = float(os.getenv("PP400_SUPPORT_POOL_WIN_SEC", "120") or 120.0)
            except Exception:
                _pool_win = 120.0
            _pool_win = max(20.0, min(900.0, float(_pool_win)))
            try:
                _pool_cap = int(os.getenv("PP400_SUPPORT_POOL_CAP", "256") or 256)
            except Exception:
                _pool_cap = 256
            _pool_cap = max(32, min(2048, int(_pool_cap)))

            # Ensure symbol buckets exist + purge old entries (bounded scan <= cap)
            for _side in ("BUY", "SELL"):
                _sd = _pool.get(_side)
                if not isinstance(_sd, dict):
                    _sd = {}
                    _pool[_side] = _sd
                _by = _sd.get(_symU)
                if not isinstance(_by, dict):
                    _by = {}
                    _sd[_symU] = _by
                try:
                    for _gn, _er in list(_by.items()):
                        try:
                            if not isinstance(_er, dict):
                                _by.pop(_gn, None)
                                continue
                            if (now_ts - float(_er.get("ts", 0.0) or 0.0)) > _pool_win:
                                _by.pop(_gn, None)
                        except Exception:
                            continue
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

            # Add current batch supporters (O(batch))
            for _it in list(details or []):
                try:
                    _nm, _v, _c, _w, _err, _meta = _it
                except Exception:
                    continue
                try:
                    _vv = str(_v or "HOLD").upper()
                    if _vv not in ("BUY", "SELL"):
                        continue
                    _sc = float(_c or 0.0) * float(_w or 0.0)
                    if _sc <= 0.0:
                        continue
                    _by = _pool[_vv][_symU]
                    _key = str(_nm)
                    _cur = _by.get(_key)
                    if (not isinstance(_cur, dict)) or (float(_sc) > float(_cur.get("score", 0.0) or 0.0)):
                        _by[_key] = {"score": float(_sc), "conf": float(_c or 0.0), "w": float(_w or 0.0), "ts": float(now_ts)}
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="pp400_pool_add")
                    continue

            # Cap per side+symbol (fast prune if needed)
            try:
                for _side in ("BUY", "SELL"):
                    _by = (_pool.get(_side, {}) or {}).get(_symU)
                    if isinstance(_by, dict) and len(_by) > _pool_cap:
                        _items = sorted(
                            _by.items(),
                            key=lambda kv: float((kv[1] or {}).get("score", 0.0) or 0.0),
                            reverse=True,
                        )
                        _pool[_side][_symU] = dict(_items[:_pool_cap])
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="pp400_support_pool")

        payload = {
            "vote": final_vote,
            "score": float(score_sum),
            "w_sum": float(w_sum),
            "veto_score": float(veto_score),
            "consensus": float(consensus),
            "ts": float(now_ts),
            "n": int(len(getattr(self, "_pp200_gene_last", {}) or {})),
            "details": details[:24],
            "batch_score": float(batch_score_sum),
            "batch_n": int(len(details)),
        }

        # cache per symbol
        try:
            cache = getattr(bot, "_pp200_legacy_cache", None)
            if not isinstance(cache, dict):
                cache = {}
                setattr(bot, "_pp200_legacy_cache", cache)
            cache[str(sym).upper()] = payload
        except Exception as e:
            _pp200_log(bot, f"[PP200] cache set error: {e}", level="warning")

        return payload

    def get_cached(self, sym: str) -> dict:
        try:
            cache = getattr(self.bot, "_pp200_legacy_cache", None)
            if isinstance(cache, dict):
                return dict(cache.get(str(sym).upper()) or {})
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return {}

    def secondary_confirm_or_veto(self, sym: str, proposed: str) -> _pp200_Tuple[bool, bool, str]:
        """
        Returns (confirm, veto, reason)
        Fail-closed: if no fresh cache, returns (False, False, "no_fresh_cache")
        """
        p = (proposed or "HOLD").upper()
        c = self.get_cached(sym)
        v = str(c.get("vote", "HOLD") or "HOLD").upper()
        ts = _pp200_f(c.get("ts", 0.0), 0.0)
        try:
            max_age = float(os.getenv("PP200_SANDBOX_MAX_AGE_SEC", "25") or 25)
        except Exception:
            max_age = 25.0
        if ts <= 0 or (_pp200_now() - ts) > float(max_age):
            return False, False, "no_fresh_cache"

        # confirm if aligned
        if p in ("BUY","SELL") and v == p:
            return True, False, "legacy_confirm"

        # veto logic: if legacy is strong opposite, veto
        if p == "BUY" and v == "SELL" and _pp200_f(c.get("score", 0.0), 0.0) <= -0.22:
            return False, True, "legacy_veto_sell"
        if p == "SELL" and v == "BUY" and _pp200_f(c.get("score", 0.0), 0.0) >= 0.22:
            return False, True, "legacy_veto_buy"

        return False, False, "legacy_no_confirm"

    def on_trade_outcome(self, result) -> None:
        """
        Self-healing + self-correction:
          - Never disables genes
          - Decays weights for misaligned outcomes
          - Records integrity for dashboard
        """
        try:
            sym = ""
            pnl_usdt = 0.0
            if isinstance(result, dict):
                sym = _pp200_s(result.get("symbol") or "").upper()
                pnl_usdt = _pp200_f(result.get("pnl_usdt", result.get("pnl", 0.0)), 0.0)
                if pnl_usdt == 0.0 and _pp200_f(result.get("pnl_toman", 0.0), 0.0) != 0.0:
                    ur = _pp200_f(getattr(self.bot, "_dash_usdt_rate", 0.0), 0.0)
                    if ur > 0:
                        pnl_usdt = _pp200_f(result.get("pnl_toman", 0.0), 0.0) / float(ur)
            else:
                sym = _pp200_s(getattr(result, "symbol", "")).upper()
                pnl_usdt = _pp200_f(getattr(result, "pnl_usdt", getattr(result, "pnl", 0.0)), 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return

        if not sym:
            return

        # find last details
        try:
            c = self.get_cached(sym)
            details = list(c.get("details") or [])
        except Exception:
            details = []

        if not details:
            return

        try:
            a = float(os.getenv("PP200_SELF_CORR_ALPHA", "0.10") or 0.10)
        except Exception:
            a = 0.10
        a = max(0.03, min(0.30, float(a)))

        good = 1.0 if float(pnl_usdt) > 0 else 0.0
        for item in details:
            try:
                nm = str(item[0])
                vote = str(item[1]).upper()
                conf = _pp200_f(item[2], 0.0)
                w = float(self.weights.get(nm, 0.15) or 0.15)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_continue")
                continue
            # adjust weight without disabling
            strength = min(1.0, abs(float(conf)))
            if good > 0:
                target = 1.0
                delta = a * (target - w)
                self.weights[nm] = float(max(0.02, min(1.0, w + delta)))
            else:
                target = 0.0
                delta = a * (target - w) * (1.0 + 0.35 * strength)
                self.weights[nm] = float(max(0.01, min(1.0, w + delta)))
                # mark degraded if persistently losing
                try:
                    ec = int(self.ledger.err_counts.get(nm, 0))
                    if ec >= 5:
                        self.ledger.mark_degraded(nm, "frequent_errors_weight_decay")
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

    def integrity_items(self) -> _pp200_List[_pp200_Tuple[str, str]]:
        out = []
        try:
            out.append(("FUNCTIONAL_INTEGRITY_200", f"{self.ledger.integrity_percent():.1f}%"))
            out.append(("RECOVERED_LOGIC_COUNT", str(self.ledger.recovered_count())))
            out.append(("INTEGRITY_BRIEF_200", str(self.ledger.brief())[:220]))
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e)

        return out

