# ---- Enforce "no trade without collective wisdom": require legacy bridge confirm OR allow veto ----
try:
    _pp200__orig_update_signal = globals().get("_pp110_update_signal_streak", None)
except Exception:
    _pp200__orig_update_signal = None

try:
    if callable(_pp200__orig_update_signal):
        def _pp200_update_signal_streak(core, sym: str, score: float, vote: str):
            # first run original logic (weighted consensus etc.)
            v0 = vote
            try:
                res = _pp200__orig_update_signal(core, sym, score, vote)
            except Exception as e:
                # never silent: fallback to HOLD
                try:
                    bot = getattr(core, "bot", None)
                except Exception:
                    bot = None
                if bot is not None:
                    _pp200_log(bot, f"[PP200] _pp110_update_signal_streak error: {e}", level="error")
                res = None

            # veto/confirm gate
            try:
                br = getattr(core, "_pp200_bridge", None)
                if br is None:
                    br = getattr(getattr(core, "bot", None), "_pp200_bridge", None)
                if br is None:
                    return res
                proposed = str(vote or "HOLD").upper()
                if proposed in ("BUY","SELL"):
                    ok, veto, reason = br.secondary_confirm_or_veto(sym, proposed)
                    if veto:
                        # veto overrides everything => HOLD
                        try:
                            core._pp200_last_veto = f"{sym}:{proposed}:{reason}"
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e)

                        # force HOLD by calling original with HOLD
                        return _pp200__orig_update_signal(core, sym, score, "HOLD")
                    if not ok:
                        # require confirm
                        try:
                            core._pp200_last_no_confirm = f"{sym}:{proposed}:{reason}"
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e)

                        return _pp200__orig_update_signal(core, sym, score, "HOLD")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            return res

        globals()["_pp110_update_signal_streak"] = _pp200_update_signal_streak
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

