try:
    if callable(_pp200__orig_pick):
        def _pp200_pick_liquidity_mode_and_sovereign(bot):
            mode, sov, eq = _pp200__orig_pick(bot)
            # dynamic: choose wallet with highest quote buying power at this moment
            try:
                balances = getattr(bot, "_dash_balances_cache", {}) or {}
                # Determine quote: prefer USDT if bot quote symbols include USDT pairs
                quote = "USDT"
                try:
                    if getattr(bot, "quote", "IRT").upper() == "IRT":
                        quote = "IRT"
                except Exception:
                    quote = "USDT"

                best = sov
                best_amt = -1.0
                for wname, b in (balances or {}).items():
                    try:
                        if not isinstance(b, dict):
                            continue
                        amt = _pp200_f(b.get(quote, 0.0), 0.0)
                        # also consider USDT buying power if quote IRT (convert by usdt rate)
                        if quote == "IRT":
                            ur = _pp200_f(getattr(bot, "_dash_usdt_rate", 0.0), 0.0)
                            if ur > 0:
                                amt = max(amt, _pp200_f(b.get("USDT", 0.0), 0.0) * float(ur))
                        if amt > best_amt:
                            best_amt = amt
                            best = str(wname)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_continue")
                        continue
                if best:
                    sov = best
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e)

            return mode, sov, eq

        globals()["_pp180_pick_liquidity_mode_and_sovereign"] = _pp200_pick_liquidity_mode_and_sovereign
except Exception as _pp200_e:
    _pp200_heal(_pp200_e)

