# PP200 PERMANENT STABLE PATCH (v200PS)
# هدف: حفظ اصل سرمایه 100 دلاری در تضادها + کاهش نویز + تثبیت تاخیر زیر ~100ms
# NOTE: Non-Interference: هیچ تغییر در توکن‌ها/توابع API ارزپلاس انجام نمی‌شود.
# =============================================================================
try:
    import time as _pp200ps_time
    import math as _pp200ps_math
except Exception:
    _pp200ps_time = None
    _pp200ps_math = None

def _pp200ps_perf() -> float:
    try:
        return _pp200ps_time.perf_counter()
    except Exception:
        try:
            return _pp200_now()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

def _pp200ps_total_usdt(bot) -> float:
    """
    Best-effort total equity in USDT using dashboard caches only (no API changes).
    """
    try:
        balances = getattr(bot, "_dash_balances_cache", None) or {}
    except Exception:
        balances = {}
    try:
        ur = float(getattr(bot, "_dash_usdt_rate", 0.0) or 0.0)
    except Exception:
        ur = 0.0
    tot = 0.0
    try:
        for _, b in (balances or {}).items():
            if not isinstance(b, dict):
                continue
            try:
                tot += float(b.get("USDT", 0.0) or 0.0)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                irt = float(b.get("IRT", 0.0) or 0.0)
                if ur > 0:
                    tot += float(irt) / float(ur)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    return float(tot)

def _pp200ps_principal_mode(bot) -> bool:
    """
    Preserve-Principal mode: when equity is around the 'sacred' 100 USDT.
    """
    try:
        principal = float(os.getenv("PP200PS_PRINCIPAL_USDT", "100") or 100.0)
    except Exception:
        principal = 100.0
    try:
        band = float(os.getenv("PP200PS_PRINCIPAL_BAND", "1.35") or 1.35)
    except Exception:
        band = 1.35
    eq = _pp200ps_total_usdt(bot)
    if eq <= 0:
        # if unknown, be conservative
        return True
    return bool(eq <= principal * band)

def _pp200ps_get_net_eff(bot) -> float:
    try:
        v = getattr(bot, "_pp175_net_eff_ema", None)
        if v is None:
            v = getattr(bot, "_pp175_net_eff", None)
        if v is None:
            return 0.0
        return float(v)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

