# --- Permanent Stable: optimize bridge.tick + add conflict-aware sovereign consensus ---
try:
    if "_pp200_LegacyBridge" in globals():

        _pp200ps__orig_init = _pp200_LegacyBridge.__init__

        def _pp200ps_init(self, bot, base_sandbox=None):
            _pp200ps__orig_init(self, bot, base_sandbox)
            # Config cached once for latency; values can be overridden by env on restart.
            try:
                self._pp200ps_cap = int(os.getenv("PP200_GENE_CAP", "60") or 60)
            except Exception:
                self._pp200ps_cap = 60
            try:
                self._pp200ps_batch = int(os.getenv("PP200_GENE_BATCH", "8") or 8)
            except Exception:
                self._pp200ps_batch = 8
            try:
                self._pp200ps_budget_ms = float(os.getenv("PP200PS_BUDGET_MS", "95") or 95.0)
            except Exception:
                self._pp200ps_budget_ms = 95.0
            try:
                self._pp200ps_details_k = int(os.getenv("PP200PS_DETAILS_K", "6") or 6)
            except Exception:
                self._pp200ps_details_k = 6

            self._pp200ps_stats = {}  # name -> dict counters
            self._pp200ps_nonop = {}  # name -> (reason, retry_ts)
            self._pp200ps_last_ms = 0.0
            self._pp200ps_last_conflict = 0.0

            # Fortress rule: cap affects sampling only (no registry truncation / no gene burial)
            try:
                if isinstance(self._rr, list):
                    # keep deterministic order; never truncate the gene universe
                    self._rr = list(self._rr)
                    try:
                        self._rr.sort()
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
                    # Legacy cap-truncation preserved but forbidden by Fortress (no gene burial)
                    if False and isinstance(self._rr, list) and len(self._rr) > int(getattr(self, "_pp200ps_cap", 0) or 0):
                        self._rr = self._rr[:int(getattr(self, "_pp200ps_cap", 0) or 0)]
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            # Immediate wisdom wiring: persist ID map + initial weights for all discovered genes
            try:
                _ws = globals().get("_pp255_wisdom_save", None)
                if callable(_ws):
                    _ws(self, force=True)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        _pp200_LegacyBridge.__init__ = _pp200ps_init

        def _pp200ps_mark_nonop(self, nm: str, reason: str):
            try:
                r = _pp200_s(reason)[:220]
            except Exception:
                r = "non_operational"
            try:
                # retry after 10 minutes (allows future relevance without permanent death)
                retry = _pp200_now() + float(os.getenv("PP200PS_NONOP_RETRY_SEC", "600") or 600)
            except Exception:
                retry = _pp200_now() + 600.0
            try:
                self._pp200ps_nonop[str(nm)] = (r, float(retry))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                if hasattr(self, "ledger") and hasattr(self.ledger, "mark_non_operational"):
                    self.ledger.mark_non_operational(str(nm), r)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                # lightweight runtime log
                bot = getattr(self, "bot", None)
                if bot is not None:
                    _pp200_log(bot, f"[RECOVERED_LOGIC] NON_OPERATIONAL {nm} :: {r}", level="warning")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        def _pp200ps_should_skip(self, nm: str) -> bool:
            try:
                ent = (self._pp200ps_nonop or {}).get(str(nm))
                if not ent:
                    return False
                _, retry_ts = ent
                if _pp200_now() >= float(retry_ts):
                    # allow retry now; keep entry but refresh retry in case it fails again
                    return False
                return True
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return False

        _pp200_LegacyBridge._pp200ps_mark_nonop = _pp200ps_mark_nonop
        _pp200_LegacyBridge._pp200ps_should_skip = _pp200ps_should_skip

        # Replace tick with latency-budgeted version
        _pp200ps__orig_tick = _pp200_LegacyBridge.tick

        def _pp200ps_tick(self, sym: str, symst, bid: float, ask: float, mid: float, depth_data: dict) -> dict:
            bot = getattr(self, "bot", None)
            t0 = _pp200ps_perf()
            budget = float(getattr(self, "_pp200ps_budget_ms", 95.0) or 95.0) / 1000.0

            # Fortress rule: cap affects sampling only (no registry truncation / no gene burial)
            try:
                cap = int(getattr(self, "_pp200ps_cap", 60) or 60)
                if isinstance(self._rr, list):
                    # touch for safety; do not truncate
                    _ = len(self._rr)
                    # Legacy cap-truncation preserved but forbidden by Fortress (no gene burial)
                    if False and isinstance(self._rr, list) and len(self._rr) > cap:
                        self._rr = self._rr[:cap]
            except Exception:
                cap = 60

            # PP400: opportunistic gene discovery + immediate oracle wiring (ID + initial weights)
            try:
                now0 = float(_pp200_now())
            except Exception:
                now0 = float(_pp920_time.time())
            try:
                scan_iv = float(os.getenv("PP400_DISCOVERY_SCAN_SEC", "20") or 20.0)
            except Exception:
                scan_iv = 20.0
            try:
                last_scan = float(getattr(self, "_pp400_last_discovery_scan", 0.0) or 0.0)
            except Exception:
                last_scan = 0.0
            if (now0 - last_scan) >= max(5.0, min(180.0, scan_iv)):
                try:
                    self._pp400_last_discovery_scan = now0
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                try:
                    newn = 0
                    # scan globals for callable genes (cheap reflection)
                    for _nm, _obj in list(globals().items()):
                        try:
                            if not _pp200_gene_keywords(_nm):
                                continue
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_continue")
                            continue
                        if str(_nm) in (self.genes or {}):
                            continue
                        try:
                            if _pp200_is_callable_gene(_obj):
                                self.genes[str(_nm)] = _obj
                                # initial weight: conservative but non-zero
                                try:
                                    self.weights[str(_nm)] = float(self.weights.get(str(_nm), 0.20) or 0.20)
                                except Exception:
                                    self.weights[str(_nm)] = 0.20
                                try:
                                    self.ledger.register(str(_nm), recovered=False)
                                except Exception as _pp200_e:
                                    _pp200_heal(_pp200_e, tag="exc_pass")
                                    pass
                                newn += 1
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_continue")
                            continue
                    if newn > 0:
                        # refresh RR registry deterministically (no truncation)
                        try:
                            rr = list(self._rr or [])
                        except Exception:
                            rr = []
                        try:
                            rr.extend(list((self.genes or {}).keys()))
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                        try:
                            self._rr = sorted(list(set(rr)))
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                        # immediate wisdom persistence (writes id map + weights_by_id via PP302)
                        try:
                            _ws = globals().get("_pp255_wisdom_save", None)
                            if callable(_ws):
                                _ws(self, force=True)
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
            # Adaptive batch: if previous tick was slow, reduce; if fast, gently increase.
            try:
                b = int(getattr(self, "_pp200ps_batch", 8) or 8)
            except Exception:
                b = 8
            try:
                last_ms = float(getattr(self, "_pp200ps_last_ms", 0.0) or 0.0)
                if last_ms > 110.0 and b > 3:
                    b -= 1
                elif last_ms < 60.0 and b < 14:
                    b += 1
                self._pp200ps_batch = b
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            names = []
            try:
                names = self._next_names(b)
            except Exception:
                try:
                    names = self._next_names(3)
                except Exception:
                    names = []

            score_sum = 0.0
            w_sum = 0.0
            veto_score = 0.0
            buy_power = 0.0
            sell_power = 0.0
            details = []
            keep_k = int(getattr(self, "_pp200ps_details_k", 6) or 6)

            for nm in names:
                if (_pp200ps_perf() - t0) > budget:
                    break

                # noise reduction: skip temporarily non-operational genes (with periodic retry)
                try:
                    if self._pp200ps_should_skip(str(nm)):
                        continue
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                fn = None
                try:
                    fn = self.genes.get(nm)
                except Exception:
                    fn = None
                if fn is None:
                    continue

                try:
                    w = float(self.weights.get(nm, 0.15) or 0.15)
                except Exception:
                    w = 0.15
                if w < 0.01:
                    w = 0.01
                if w > 1.0:
                    w = 1.0

                out, err = _pp200_self_heal_call(
                    fn,
                    name=str(nm),
                    sym=sym,
                    symst=symst,
                    bid=bid,
                    ask=ask,
                    mid=mid,
                    depth_data=depth_data,
                    bot=bot,
                    ledger=getattr(self, "ledger", None),
                )

                vote, conf, meta = _pp200_normalize_vote(out)
                try:
                    conf = float(conf)
                except Exception:
                    conf = 0.0
                if conf < 0.0:
                    conf = 0.0
                if conf > 1.0:
                    conf = 1.0

                sgn = 0.0
                if vote == "BUY":
                    sgn = 1.0
                    buy_power += (conf * w)
                elif vote == "SELL":
                    sgn = -1.0
                    sell_power += (conf * w)

                score = (sgn * conf * w)
                score_sum += float(score)
                w_sum += abs(float(w)) * max(0.2, float(conf))

                if abs(score) >= 0.30 and vote in ("BUY", "SELL"):
                    veto_score += float(score)

                # Minimal details to reduce overhead
                try:
                    if keep_k > 0 and len(details) < keep_k:
                        details.append((str(nm), vote, float(conf), float(w), err))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                # stats + noise classifier (mark NON_OPERATIONAL)
                try:
                    st = (self._pp200ps_stats or {}).get(str(nm))
                    if st is None:
                        st = {"calls": 0, "errs": 0, "buy": 0, "sell": 0, "boring": 0}
                        self._pp200ps_stats[str(nm)] = st
                    st["calls"] = int(st.get("calls", 0)) + 1
                    if err:
                        st["errs"] = int(st.get("errs", 0)) + 1
                    if vote == "BUY":
                        st["buy"] = int(st.get("buy", 0)) + 1
                    elif vote == "SELL":
                        st["sell"] = int(st.get("sell", 0)) + 1
                    if (vote == "HOLD" and conf < 0.12) or (vote not in ("BUY","SELL","HOLD")):
                        st["boring"] = int(st.get("boring", 0)) + 1

                    c = int(st.get("calls", 0))
                    if c >= 40:
                        # 100% irrelevant: never produces directional info AND mostly boring
                        if int(st.get("buy", 0)) == 0 and int(st.get("sell", 0)) == 0 and int(st.get("boring", 0)) >= int(0.95 * c):
                            self._pp200ps_mark_nonop(str(nm), "irrelevant_output_hold_only")
                        # too many errors: likely incompatible with current data format
                        if int(st.get("errs", 0)) >= int(0.80 * c):
                            self._pp200ps_mark_nonop(str(nm), "irrelevant_incompatible_errors")
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
            # conflict measure among resurrected strategies
            tot_dir = float(buy_power + sell_power)
            conflict = 0.0
            if tot_dir > 0.0:
                conflict = float(min(buy_power, sell_power) / tot_dir)
            self._pp200ps_last_conflict = float(conflict)

            # Permanent-stable vote: bias to HOLD on ambiguity
            thr = 0.20
            if conflict >= 0.33:
                final_vote = "HOLD"
            else:
                if score_sum >= thr:
                    final_vote = "BUY"
                elif score_sum <= -thr:
                    final_vote = "SELL"
                else:
                    final_vote = "HOLD"

            t1 = _pp200ps_perf()
            ms = max(0.0, (t1 - t0) * 1000.0)
            self._pp200ps_last_ms = float(ms)
            try:
                if bot is not None:
                    setattr(bot, "_pp200_bridge_last_ms", float(ms))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            payload = {
                "vote": final_vote,
                "score": float(score_sum),
                "w_sum": float(w_sum),
                "veto_score": float(veto_score),
                "buy_power": float(buy_power),
                "sell_power": float(sell_power),
                "conflict": float(conflict),
                "ms": float(ms),
                "ts": _pp200_now(),
                "n": int(len(details)),
                "details": details,
            }

            # cache per symbol
            try:
                cache = getattr(bot, "_pp200_legacy_cache", None)
                if not isinstance(cache, dict):
                    cache = {}
                    setattr(bot, "_pp200_legacy_cache", cache)
                cache[str(sym).upper()] = payload
            except Exception as e:
                try:
                    _pp200_log(bot, f"[PP200PS] cache set error: {e}", level="warning")
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
            return payload

        _pp200_LegacyBridge.tick = _pp200ps_tick

        # Sovereign Consensus: conflict-aware + principal-safe confirmation
        _pp200ps__orig_sc = _pp200_LegacyBridge.secondary_confirm_or_veto

        def _pp200ps_secondary_confirm_or_veto(self, sym: str, proposed: str):
            ok, veto, reason = _pp200ps__orig_sc(self, sym, proposed)
            bot = getattr(self, "bot", None)
            p = str(proposed or "HOLD").upper()

            # If conflict among legacy outputs => strategic patience (especially for BUY)
            try:
                c = self.get_cached(sym)
                conflict = float(c.get("conflict", 0.0) or 0.0)
            except Exception:
                conflict = 0.0

            # Principal guard: when around 100USDT, require high net-eff and low conflict
            if _pp200ps_principal_mode(bot):
                ne = _pp200ps_get_net_eff(bot)
                try:
                    min_ne = float(os.getenv("PP200PS_MIN_NET_EFF", "2.0") or 2.0)
                except Exception:
                    min_ne = 2.0

                if p == "BUY":
                    if conflict >= 0.25:
                        return False, False, "principal_conflict_guard"
                    if ne > 0.0 and ne < min_ne:
                        return False, False, f"principal_net_eff_guard({ne:.2f}x<{min_ne:.2f}x)"
                    # Even if ok, require low ambiguity: legacy must be aligned (ok True)
                    if not ok:
                        return False, False, "principal_requires_confirm"
                if p == "SELL":
                    # allow exits, but if legacy conflict is extreme and not confirmed, prefer HOLD (avoid whipsaw)
                    if (conflict >= 0.40) and (not ok) and (not veto):
                        return False, False, "sell_conflict_patience"

            # General conflict guard (any equity): if conflict is strong, do not confirm
            if conflict >= 0.35 and p in ("BUY", "SELL"):
                if veto:
                    return ok, veto, reason
                return False, False, "legacy_conflict_guard"

            return ok, veto, reason

        _pp200_LegacyBridge.secondary_confirm_or_veto = _pp200ps_secondary_confirm_or_veto

        # Add latency + recovered-logic brief to integrity dashboard items
        _pp200ps__orig_items = _pp200_LegacyBridge.integrity_items

        def _pp200ps_integrity_items(self):
            out = []
            try:
                out = list(_pp200ps__orig_items(self) or [])
            except Exception:
                out = []
            try:
                out.append(("PP200_BRIDGE_MS", f"{float(getattr(self,'_pp200ps_last_ms',0.0)):.1f}ms"))
                out.append(("LEGACY_CONFLICT", f"{float(getattr(self,'_pp200ps_last_conflict',0.0)):.2f}"))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                led = getattr(self, "ledger", None)
                if led is not None and hasattr(led, "recovered_logic_brief"):
                    out.append(("RECOVERED_LOGIC", str(led.recovered_logic_brief())[:220]))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            return out

        _pp200_LegacyBridge.integrity_items = _pp200ps_integrity_items

except Exception as _pp200ps_e:
    try:
        _pp200_heal(_pp200ps_e)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
# --- Signature polish: gold-centered markup when rich is present ---
try:
    _pp200ps_sig = ""  # minimalist startup
    if "DashboardManager" in globals() and hasattr(DashboardManager, "_header_panel"):
        _pp200ps__orig_hdr = DashboardManager._header_panel
        def _pp200ps_header_panel(self, bot):
            try:
                return _pp200ps__orig_hdr(self, bot)
            except Exception:
                try:
                    from rich.panel import Panel
                    from rich.align import Align
                    from rich.text import Text
                    t = Text(_pp200ps_sig, style="bold #FFD700")
                    return Panel(Align.center(t), expand=True)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return _pp200ps_sig
        DashboardManager._header_panel = _pp200ps_header_panel
except Exception as _pp200ps_e:
    try:
        _pp200_heal(_pp200ps_e)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
# ============================================================
# PP220: THE ETERNAL MASTERPIECE (Permanent Stable)
# - Deep Long-run Stability (global leak control)
# - Sovereign Deadlock (freeze-on-crisis, never duplicate/wrong orders)
# - Dashboard: HEALING visibility
# NOTE: Does NOT modify ArzPlus tokens nor core API communication functions.
# ============================================================

try:
    import time as _pp220_time
    import threading as _pp220_threading
    import gc as _pp220_gc
    import math as _pp220_math
    import os as _pp220_os
    import sys as _pp220_sys
except Exception as _pp220_e_import:
    _pp200_heal(_pp220_e_import, tag="pp220_import")

def _pp220_now() -> float:
    try:
        return float(_pp220__pp920_time.time())
    except Exception:
        try:
            import time as __t
            return float(__t.time())
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

# ----------------------------
# Long-run stability: bounded globals + periodic pruning
# ----------------------------
_pp220_housekeeper_started = False
_pp220_last_prune_ts = 0.0
_pp220_last_gc_ts = 0.0

def _pp220__is_safe_global_name(n: str) -> bool:
    try:
        s = str(n or "")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False
    if not s or s.startswith("__"):
        return False
    # Never touch anything that looks like credentials / tokens / secrets / endpoints
    u = s.upper()
    if "TOKEN" in u or "SECRET" in u or "API_KEY" in u or "KEY" == u:
        return False
    if "ARZPLUS" in u and ("TOKEN" in u or "KEY" in u or "SECRET" in u):
        return False
    return True

def _pp220__prune_dict_inplace(d: dict, max_items: int) -> int:
    """Prune dict by insertion-order (keep newest). Returns number of deletions."""
    try:
        n = len(d)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0
    if n <= max_items:
        return 0
    try:
        # dict preserves insertion order (Py3.7+). Delete oldest keys.
        kill = n - max_items
        keys = list(d.keys())[:kill]
        for k in keys:
            try:
                del d[k]
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        return int(kill)
    except Exception as _e:
        _pp200_heal(_e, tag="pp220_prune_dict")
        return 0

def _pp220__prune_list_inplace(lst: list, max_items: int) -> int:
    try:
        n = len(lst)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0
    if n <= max_items:
        return 0
    try:
        kill = n - max_items
        del lst[:kill]
        return int(kill)
    except Exception as _e:
        _pp200_heal(_e, tag="pp220_prune_list")
        return 0

def _pp220_prune_globals(force: bool = False) -> None:
    """
    Best-effort global memory leak prevention for week-long runs.
    Prunes only cache-like globals; never touches tokens/API.
    """
    global _pp220_last_prune_ts, _pp220_last_gc_ts
    now = _pp220_now()
    try:
        interval = float(_pp220_os.getenv("PP220_PRUNE_INTERVAL_SEC", "60") or "60")
    except Exception:
        interval = 60.0
    interval = max(10.0, min(900.0, interval))

    if (not force) and now > 0 and _pp220_last_prune_ts > 0 and (now - _pp220_last_prune_ts) < interval:
        return

    _pp220_last_prune_ts = now

    try:
        max_cache = int(float(_pp220_os.getenv("PP220_MAX_CACHE_ITEMS", "1200") or "1200"))
    except Exception:
        max_cache = 1200
    max_cache = max(200, min(20000, max_cache))

    try:
        max_list = int(float(_pp220_os.getenv("PP220_MAX_LIST_ITEMS", "1500") or "1500"))
    except Exception:
        max_list = 1500
    max_list = max(200, min(50000, max_list))

    # only prune "cache-like" names
    name_hits = ("cache", "hist", "ring", "events", "votes", "ledger", "errors", "locks", "recent", "pending", "intel")
    try:
        g = globals()
        for name, obj in list(g.items()):
            if not _pp220__is_safe_global_name(name):
                continue
            lname = str(name).lower()
            if not any(h in lname for h in name_hits):
                continue
            # keep critical ledgers bounded but not destroyed
            try:
                if isinstance(obj, dict):
                    _pp220__prune_dict_inplace(obj, max_cache)
                elif isinstance(obj, list):
                    _pp220__prune_list_inplace(obj, max_list)
            except Exception as _e:
                _pp200_heal(_e, tag="pp220_prune_globals_item")
    except Exception as _e:
        _pp200_heal(_e, tag="pp220_prune_globals")

    # periodic GC (very conservative)
    try:
        gc_every = float(_pp220_os.getenv("PP220_GC_INTERVAL_SEC", "600") or "600")
    except Exception:
        gc_every = 600.0
    gc_every = max(120.0, min(3600.0, gc_every))
    try:
        if now > 0 and (_pp220_last_gc_ts <= 0 or (now - _pp220_last_gc_ts) >= gc_every):
            _pp220_last_gc_ts = now
            try:
                _pp220_gc.collect()
            except Exception as _e:
                _pp200_heal(_e, tag="pp220_gc")
    except Exception as _e:
        _pp200_heal(_e, tag="pp220_gc_gate")

def _pp220_start_housekeeper(bot=None) -> None:
    global _pp220_housekeeper_started
    if _pp220_housekeeper_started:
        return
    _pp220_housekeeper_started = True
    try:
        def _loop():
            # daemon loop: prune globals, never block trading thread
            while True:
                try:
                    _pp220_prune_globals(force=False)
                except Exception as _e:
                    _pp200_heal(_e, tag="pp220_housekeeper")
                try:
                    _pp220_time.sleep(1.0)
                except Exception:
                    try:
                        import time as __t
                        __t.sleep(1.0)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
        th = _pp220_threading.Thread(target=_loop, name="PP220-Housekeeper", daemon=True)
        th.start()
    except Exception as _e:
        _pp200_heal(_e, tag="pp220_housekeeper_start")

# ----------------------------
# Sovereign Deadlock: freeze-on-crisis, no duplicates, no wrong orders
# ----------------------------
_pp220_freeze_until = 0.0
_pp220_freeze_reason = ""
_pp220_uncertain = {}      # signature -> ts (exception path)
_pp220_recent = {}         # signature -> ts (success or attempt)
_pp220_sig_lock = None
try:
    _pp220_sig_lock = _pp220_threading.Lock()
except Exception:
    _pp220_sig_lock = None

def _pp220_set_freeze(seconds: float, reason: str) -> None:
    global _pp220_freeze_until, _pp220_freeze_reason
    now = _pp220_now()
    try:
        seconds = float(seconds)
    except Exception:
        seconds = 60.0
    seconds = max(3.0, min(3600.0, seconds))
    until = now + seconds if now > 0 else seconds
    # extend only
    try:
        if until > float(_pp220_freeze_until or 0.0):
            _pp220_freeze_until = float(until)
            _pp220_freeze_reason = str(reason or "freeze")[:200]
    except Exception:
        _pp220_freeze_until = until
        _pp220_freeze_reason = str(reason or "freeze")[:200]

def _pp220_is_frozen() -> bool:
    now = _pp220_now()
    try:
        return (now > 0) and (now < float(_pp220_freeze_until or 0.0))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

def _pp220_round(v: float, nd: int) -> float:
    try:
        v = float(v)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0
    if not _pp220_math.isfinite(v):
        return 0.0
    try:
        return float(round(v, int(nd)))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(v)

def _pp220_order_sig(side: str, symbol: str, wallet: str, qty, price) -> str:
    s = (str(side or "").upper() or "X")
    sym = (str(symbol or "").upper() or "<?>")
    w = (str(wallet or "").upper() or "W")
    q = _pp220_round(qty, 8)
    p = _pp220_round(price, 8)
    return f"{s}:{sym}:{w}:{q}:{p}"

def _pp220_should_freeze_from_clients(bot) -> bool:
    # look for ArzPlusClient / wallet clients health flags (without modifying them)
    try:
        wallets = getattr(bot, "wallets", None)
    except Exception:
        wallets = None
    clients = []
    try:
        if wallets is not None:
            # common patterns
            for attr in ("clients", "wallet_clients", "wallets", "items"):
                try:
                    c = getattr(wallets, attr, None)
                except Exception:
                    c = None
                if isinstance(c, dict):
                    clients.extend([v for v in c.values() if v is not None])
                elif isinstance(c, (list, tuple)):
                    clients.extend([v for v in c if v is not None])
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    try:
        c0 = getattr(bot, "client", None)
        if c0 is not None:
            clients.append(c0)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    # Any circuit breaker open or consecutive errors -> freeze
    for c in clients:
        try:
            if bool(getattr(c, "cb_open", False)):
                return True
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        try:
            ce = int(getattr(c, "consecutive_errors", 0) or 0)
            if ce >= 1:
                return True
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    return False

def _pp220_gate_order(bot, side: str, symbol: str, wallet_name: str, qty, price) -> (bool, str):
    """
    Returns (allowed, reason). This is "final freeze" gate:
    - Crisis => freeze (no order)
    - Duplicate or uncertain => block
    """
    # Hard SAFE_MODE gate (Iron Dome): no orders while SAFE_MODE
    try:
        if bool(globals().get('_pp500_safe_mode', False)):
            return False, f"SAFE_MODE:{globals().get('_pp500_safe_reason','') or 'CRISIS'}"
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # PP600: Active Circuit Breaker gate
    try:
        h = globals().get("SYSTEM_HEALTH", None)
        if isinstance(h, dict) and bool(h.get("critical", False)):
            return False, f"SYSTEM_HEALTH:{str(h.get('status','CRITICAL') or 'CRITICAL')[:16]}"
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Global freeze on obvious crisis
    if _pp220_is_frozen():
        return False, f"FROZEN:{_pp220_freeze_reason or 'crisis'}"

    # External kill switch (hard stop) - not demo; emergency brake.
    try:
        if str(_pp220_os.getenv("PP220_KILL", "") or "").strip() == "1":
            return False, "KILL_SWITCH"
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    # If clients indicate outage/cb -> freeze immediately
    try:
        if _pp220_should_freeze_from_clients(bot):
            _pp220_set_freeze(float(_pp220_os.getenv("PP220_FREEZE_SEC", "180") or "180"), "CLIENT_CB_OR_ERRORS")
            return False, "FROZEN:CLIENT_CB_OR_ERRORS"
    except Exception as _e:
        _pp200_heal(_e, tag="pp220_gate_clientcheck")

    # Basic sanity (never send nonsense)
    try:
        q = float(qty)
        p = float(price)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False, "BAD_QTY_PRICE"
    if (not _pp220_math.isfinite(q)) or (not _pp220_math.isfinite(p)) or q <= 0 or p <= 0:
        return False, "NONFINITE_QTY_PRICE"

    sig = _pp220_order_sig(side, symbol, wallet_name, q, p)
    now = _pp220_now()

    # TTL controls (tight for buys to prevent double-fire)
    try:
        buy_ttl = float(_pp220_os.getenv("PP220_DUP_BUY_TTL", "30") or "30")
    except Exception:
        buy_ttl = 30.0
    try:
        sell_ttl = float(_pp220_os.getenv("PP220_DUP_SELL_TTL", "15") or "15")
    except Exception:
        sell_ttl = 15.0
    buy_ttl = max(5.0, min(600.0, buy_ttl))
    sell_ttl = max(3.0, min(600.0, sell_ttl))

    # Uncertain TTL (network may have sent but we didn't get response)
    try:
        unc_ttl = float(_pp220_os.getenv("PP220_UNCERTAIN_TTL", "900") or "900")
    except Exception:
        unc_ttl = 900.0
    unc_ttl = max(30.0, min(3600.0, unc_ttl))

    ttl = buy_ttl if str(side).upper().startswith("B") else sell_ttl

    lk = _pp220_sig_lock
    if lk is not None:
        try:
            with lk:
                # prune maps
                try:
                    # keep bounded
                    if len(_pp220_recent) > 3000:
                        _pp220__prune_dict_inplace(_pp220_recent, 1800)
                    if len(_pp220_uncertain) > 2000:
                        _pp220__prune_dict_inplace(_pp220_uncertain, 1200)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                # uncertain blocks re-send for long window
                tsu = _pp220_uncertain.get(sig)
                if tsu is not None and now > 0 and (now - float(tsu)) < unc_ttl:
                    return False, "UNCERTAIN_ORDER_RECENT"

                ts = _pp220_recent.get(sig)
                if ts is not None and now > 0 and (now - float(ts)) < ttl:
                    return False, "DUPLICATE_ORDER_RECENT"

                # mark as attempted to prevent re-entry storms (even before API call)
                _pp220_recent[sig] = now
        except Exception as _e:
            _pp200_heal(_e, tag="pp220_gate_siglock")
    else:
        # no lock available; still best-effort
        try:
            ts = _pp220_recent.get(sig)
            if ts is not None and now > 0 and (now - float(ts)) < ttl:
                return False, "DUPLICATE_ORDER_RECENT"
            _pp220_recent[sig] = now
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    # Principal-protection: if capital is ~100 USDT and legacy conflicts exist -> strategic patience
    try:
        # If bot exposes conflict flag, honor it
        conflict = bool(getattr(bot, "_pp200_legacy_conflict", False) or getattr(bot, "_pp220_legacy_conflict", False))
    except Exception:
        conflict = False
    if conflict and str(side).upper().startswith("B"):
        # freeze shorter instead of trading into uncertainty
        _pp220_set_freeze(45.0, "LEGACY_CONFLICT_STRATEGIC_PATIENCE")
        return False, "FROZEN:LEGACY_CONFLICT"

    return True, "OK"

def _pp220_mark_uncertain(side: str, symbol: str, wallet_name: str, qty, price) -> None:
    sig = _pp220_order_sig(side, symbol, wallet_name, qty, price)
    now = _pp220_now()
    lk = _pp220_sig_lock
    try:
        if lk is not None:
            with lk:
                _pp220_uncertain[sig] = now
        else:
            _pp220_uncertain[sig] = now
    except Exception as _e:
        _pp200_heal(_e, tag="pp220_mark_uncertain")

