def _pp220_reports_panel(self):
    from rich.panel import Panel
    from rich.table import Table
    from rich.text import Text
    from rich import box

    bot = self.bot
    # global stats
    lat = 0.0
    trades = "-"
    try:
        rt = getattr(bot, "runtime_context", None) or getattr(bot, "rt", None)
        if rt is not None:
            lat = float(getattr(rt, "cycle_latency", 0.0) or 0.0)
    except Exception:
        lat = 0.0
    try:
        for k in ("total_trades", "trade_count", "trades_count", "filled_trades", "orders_filled"):
            if hasattr(bot, k):
                v = getattr(bot, k)
                if isinstance(v, (int, float)) and float(v) >= 0:
                    trades = str(int(v))
                    break
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # brain stats
    brain = getattr(bot, "brain", None)
    iq = 0
    conf = 0.0
    try:
        if brain is not None:
            iq = int(brain.brain_iq())
            conf = float(brain.confidence())
    except Exception:
        iq = 0
        conf = 0.0

    # last events
    events = []
    try:
        events = _dash_last_events(3) or []
    except Exception:
        events = []

    t = Table.grid(padding=(0, 1))
    t.expand = True
    t.add_column(justify="left", ratio=1)
    t.add_column(justify="right", ratio=1)

    t.add_row("GLOBAL TRADES", trades)
    t.add_row("API LATENCY", f"{lat:.3f}s")
    # PP220: self-healing visibility (background repaired errors)
    try:
        sc = int(globals().get("_pp200_heal_count", 0) or 0)
    except Exception:
        sc = 0
    t.add_row("HEALING_TOTAL", str(sc))
    # v711: momentary root-healing counter
    try:
        hs = int(getattr(bot, "_pp711_healed_this_cycle", 0) or 0)
    except Exception:
        hs = 0
    t.add_row("HEALING_STATUS", str(hs))
    # PP220: crisis freeze status (Sovereign Deadlock)
    try:
        if callable(globals().get("_pp220_is_frozen")) and _pp220_is_frozen():
            fr = str(globals().get("_pp220_freeze_reason", "") or "")[:80]
            t.add_row("SOVEREIGN_DEADLOCK", f"ON ({fr})" if fr else "ON")
        else:
            t.add_row("SOVEREIGN_DEADLOCK", "READY")
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    t.add_row("BRAIN IQ", str(iq))
    t.add_row("CONFIDENCE", f"{conf:.2f}")
    # PP155: Strategic self-awareness text stream (CognitiveCore-first)
    try:
        _st = ""
        _cc = getattr(bot, "cognitive_core", None)
        if _cc is not None:
            try:
                _st = str(getattr(_cc, "last_thought", "") or "")
            except Exception:
                _st = ""
            if not _st:
                try:
                    _st = str(_cc.compose_thought() or "")
                except Exception:
                    _st = ""
        if not _st:
            _st = str(getattr(bot, "_strategic_thought", "") or "")
    except Exception:
        _st = ""
    if len(_st) > 160:
        _st = _st[:160] + "…"
    t.add_row("STRATEGIC_THOUGHT", _st if _st else "(n/a)")

    # PP170: LEGACY INTELLIGENCE (revived heritage status)
    try:
        _li = getattr(bot, "legacy_intel", None) or getattr(bot, "legacy_intelligence", None)
        if _li is not None:
            t.add_row("LEGACY INTELLIGENCE", "")
            try:
                _items = list(_li.status_items())
            except Exception:
                _items = []
            for _k, _v in (_items or [])[:10]:
                try:
                    t.add_row(str(_k), str(_v))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e)

    except Exception as _pp200_e:
        _pp200_heal(_pp200_e)

    # events as a compact block (no extra colors)
    ev_text = "\n".join([str(x)[:160] for x in events]) if events else "(no events)"
    t2 = Table.grid(padding=(0, 0))
    t2.add_column(ratio=1)
    t2.add_row(Text(ev_text, style="white"))

    wrap = Table.grid(padding=(0, 1))
    wrap.expand = True
    wrap.add_column(ratio=1)
    wrap.add_row(t)
    wrap.add_row(Text("LAST EVENTS", style="bold white"))
    wrap.add_row(t2)

    return Panel(wrap, title="[bold white]REPORTS[/bold white]", box=box.HEAVY, style="white on black")


# ============================================================
# PP220.1: Eternal Stability Extensions
# - Prune bot attribute caches (not just module globals)
# - Hard override REPORTS to include HEALING_TOTAL
# ============================================================

try:
    import weakref as _pp220_weakref
except Exception as _pp220_e:
    _pp200_heal(_pp220_e, tag="pp220_weakref")

_pp220_bot_ref = None

def _pp220_set_bot_ref(bot) -> None:
    global _pp220_bot_ref
    try:
        _pp220_bot_ref = _pp220_weakref.ref(bot) if bot is not None else None
    except Exception:
        _pp220_bot_ref = None

def _pp220__prune_obj_attrs(obj, max_cache: int = 1200, max_list: int = 1500) -> None:
    if obj is None:
        return
    hits = ("cache", "hist", "ring", "events", "votes", "errors", "recent", "pending", "intel", "log", "trace")
    try:
        d = getattr(obj, "__dict__", None)
    except Exception:
        d = None
    if not isinstance(d, dict):
        return
    for k, v in list(d.items()):
        try:
            if not _pp220__is_safe_global_name(k):
                continue
            lk = str(k).lower()
            if not any(h in lk for h in hits):
                continue
            if isinstance(v, dict):
                _pp220__prune_dict_inplace(v, int(max_cache))
            elif isinstance(v, list):
                _pp220__prune_list_inplace(v, int(max_list))
        except Exception as _pp220_e:
            _pp200_heal(_pp220_e, tag="pp220_prune_bot_attr")

# Redefine prune function so housekeeper thread can prune bot attributes too.
def _pp220_prune_globals(force: bool = False) -> None:
    global _pp220_last_prune_ts, _pp220_last_gc_ts
    now = _pp220_now()
    try:
        interval = float(_pp220_os.getenv("PP220_PRUNE_INTERVAL_SEC", "60") or "60")
    except Exception:
        interval = 60.0
    interval = max(10.0, min(900.0, interval))
    if (not force) and now > 0 and _pp220_last_prune_ts > 0 and (now - _pp220_last_prune_ts) < interval:
        return
    _pp220_last_prune_ts = now

    try:
        max_cache = int(float(_pp220_os.getenv("PP220_MAX_CACHE_ITEMS", "1200") or "1200"))
    except Exception:
        max_cache = 1200
    max_cache = max(200, min(20000, max_cache))
    try:
        max_list = int(float(_pp220_os.getenv("PP220_MAX_LIST_ITEMS", "1500") or "1500"))
    except Exception:
        max_list = 1500
    max_list = max(200, min(50000, max_list))

    name_hits = ("cache", "hist", "ring", "events", "votes", "ledger", "errors", "locks", "recent", "pending", "intel")
    try:
        g = globals()
        for name, obj in list(g.items()):
            if not _pp220__is_safe_global_name(name):
                continue
            lname = str(name).lower()
            if not any(h in lname for h in name_hits):
                continue
            try:
                if isinstance(obj, dict):
                    _pp220__prune_dict_inplace(obj, max_cache)
                elif isinstance(obj, list):
                    _pp220__prune_list_inplace(obj, max_list)
            except Exception as _pp220_e:
                _pp200_heal(_pp220_e, tag="pp220_prune_globals_item")
    except Exception as _pp220_e:
        _pp200_heal(_pp220_e, tag="pp220_prune_globals")

    # prune bot attributes if we have a live bot ref
    try:
        bot = _pp220_bot_ref() if callable(_pp220_bot_ref) else None
    except Exception:
        bot = None
    try:
        _pp220__prune_obj_attrs(bot, max_cache=max_cache, max_list=max_list)
    except Exception as _pp220_e:
        _pp200_heal(_pp220_e, tag="pp220_prune_bot")

    # periodic GC
    try:
        gc_every = float(_pp220_os.getenv("PP220_GC_INTERVAL_SEC", "600") or "600")
    except Exception:
        gc_every = 600.0
    gc_every = max(120.0, min(3600.0, gc_every))
    try:
        if now > 0 and (_pp220_last_gc_ts <= 0 or (now - _pp220_last_gc_ts) >= gc_every):
            _pp220_last_gc_ts = now
            _pp220_gc.collect()
    except Exception as _pp220_e:
        _pp200_heal(_pp220_e, tag="pp220_gc")

# Redefine housekeeper starter: register bot ref and then start once.
def _pp220_start_housekeeper(bot=None) -> None:
    global _pp220_housekeeper_started
    if bot is not None:
        _pp220_set_bot_ref(bot)
    if _pp220_housekeeper_started:
        return
    _pp220_housekeeper_started = True
    try:
        def _loop():
            while True:
                try:
                    _pp220_prune_globals(force=False)
                except Exception as _pp220_e:
                    _pp200_heal(_pp220_e, tag="pp220_housekeeper")
                try:
                    _pp220_time.sleep(1.0)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
        th = _pp220_threading.Thread(target=_loop, name="PP220-Housekeeper", daemon=True)
        th.start()
    except Exception as _pp220_e:
        _pp200_heal(_pp220_e, tag="pp220_housekeeper_start")

