def _pp230_apply_safe_mode(tag: str, msg: str = "", *, freeze_sec: float = 90.0) -> None:
    """
    Safe Mode is NOT demo/testing: it is a conservative runtime degrade
    to protect the $100 principal and avoid duplicate/wrong orders under repeated faults.
    """
    global _pp230_last_safe_ts
    now = _pp230_now()
    _pp230_last_safe_ts = now
    # tighten legacy bridge load
    try:
        _pp230_set_override("PP200_GENE_BATCH", 2)
        _pp230_set_override("PP200_GENE_CAP", 28)
        _pp230_set_override("PP200PS_BUDGET_MS", 70)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    # freeze trading briefly (bravery -> freeze) if sovereign deadlock exists
    try:
        if "order" in str(tag).lower() or "api" in str(tag).lower() or "net" in str(tag).lower() or "socket" in str(msg).lower():
            freeze_sec = max(float(freeze_sec), 180.0)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    try:
        if "pp200_bridge" in str(tag).lower() or "oracle" in str(tag).lower():
            freeze_sec = max(float(freeze_sec), 60.0)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    try:
        if "pp222" in str(tag).lower():
            freeze_sec = max(float(freeze_sec), 60.0)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    try:
        if "pp230" in str(tag).lower():
            freeze_sec = max(float(freeze_sec), 60.0)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    try:
        if "pp220" in globals() and callable(globals().get("_pp220_set_freeze")):
            globals()["_pp220_set_freeze"](float(freeze_sec), f"PP230_SAFE_MODE:{tag}:{str(msg)[:120]}")
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass

