def _pp600_health_mark(status: str, tag: str = "", e=None) -> None:
    try:
        h = globals().get("SYSTEM_HEALTH", None)
        if not isinstance(h, dict):
            h = {}
            globals()["SYSTEM_HEALTH"] = h
        try:
            now = float(_pp500_now()) if callable(globals().get("_pp500_now", None)) else float(_pp920_time.time())
        except Exception:
            now = float(_pp920_time.time())
        h["last_ts"] = now
        h["count"] = int(h.get("count", 0) or 0) + 1
        h["last_tag"] = str(tag or "")[:160]
        h["last_error"] = (f"{type(e).__name__}:{e}" if e is not None else "")[:240]
        st = str(status or "OK").upper()
        h["status"] = st[:16]
        if st == "CRITICAL":
            h["critical"] = True
            if not float(h.get("since", 0.0) or 0.0):
                h["since"] = now
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")


def _pp500_now() -> float:
    try:
        import time as _t
        return float(_t.time())
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

def _pp500_is_critical_fault(tag: str, e) -> bool:
    try:
        t = str(tag or "").lower()
    except Exception:
        t = ""
    # Exclusions: gene/internal telemetry errors should not hard-stop trading
    try:
        if any(x in t for x in ("pp200", "gene", "ledger", "audit", "dash", "pp221", "pp222", "pp230", "oracle")):
            return False
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    # Critical domains: market data, funds, orders, network
    crit = (
        "price","ticker","quote","bid","ask","mid","depth","orderbook","book","kline","ohlc",
        "balance","wallet","equity","available","fund","asset",
        "order","place","submit","send","buy","sell","position","close","trade",
        "http","https","ssl","socket","net","api","arzplus","client","auth","sign","nonce",
    )
    try:
        if any(k in t for k in crit):
            return True
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    # Exception-message heuristics
    try:
        m = str(e or "").lower()
        if any(k in m for k in ("ssl", "certificate", "handshake", "timed out", "timeout", "connection reset", "connection refused", "name resolution", "temporarily unavailable")):
            return True
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return False

def _pp500_enter_safe_mode(tag: str, e=None, *, freeze_sec: float = 3600.0) -> None:
    global _pp500_safe_mode, _pp500_safe_reason, _pp500_safe_ts
    try:
        _pp500_safe_mode = True
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    try:
        _pp500_safe_reason = f"{str(tag or 'crisis')[:80]}:{type(e).__name__ if e is not None else 'ERR'}:{str(e)[:120] if e is not None else ''}"[:200]
    except Exception:
        _pp500_safe_reason = str(tag or "crisis")[:200]
    try:
        _pp500_safe_ts = float(_pp500_now())
    except Exception:
        _pp500_safe_ts = 0.0
    # PP600: mark global health as CRITICAL (Active Circuit Breaker)
    try:
        _pp600_health_mark("CRITICAL", str(tag or "crisis"), e)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Freeze trading immediately (PP220 gate).
    try:
        if "pp220" in globals() and callable(globals().get("_pp220_set_freeze")):
            globals()["_pp220_set_freeze"](float(max(60.0, min(3600.0, float(freeze_sec)))), f"PP500_SAFE_MODE:{_pp500_safe_reason}")
    except Exception as _pp200_e:
        try:
            _pp200_heal(_pp200_e, tag="pp500_freeze")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
    # Also apply PP230 safe overrides (budget tightening)
    try:
        _pp230_apply_safe_mode(str(tag or "pp500"), msg=str(_pp500_safe_reason or ""), freeze_sec=float(max(90.0, min(3600.0, float(freeze_sec)))))
    except Exception as _pp200_e:
        try:
            _pp200_heal(_pp200_e, tag="pp500_safe_override")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

# ----------------------------
# Swallow self-correction: repeated errors -> safe mode
# ----------------------------
try:
    _pp230__orig_swallow = _pp200_swallow
except Exception:
    _pp230__orig_swallow = None

def _pp230_swallow(e, tag="swallow"):
    try:
        _pp200_heal(e, tag=str(tag or "swallow"))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Iron Dome: immediate SAFE_MODE on critical faults (no repeats needed)
    try:
        if bool(globals().get("_pp500_safe_mode", False)):
            pass
        else:
            if bool(globals().get("_pp500_is_critical_fault", lambda *_: False)(tag, e)) and (not any(k in str(tag or '').lower() for k in ('price','depth','meta','symbol','wallet','wallet_balance','balance','irt','toman','sanctuary','usdt','btc','paxg','network','timeout','ssl','connection'))):
                try:
                    globals().get("_pp500_enter_safe_mode", lambda *_: None)(str(tag or "swallow"), e)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
    except Exception as _pp200_e:
        try:
            _pp200_heal(_pp200_e, tag="pp500_domeshield")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
# repeat detection
    try:
        t = str(tag or "swallow")[:120]
        k = f"{t}:{type(e).__name__}"
        c = int(_pp230_err_repeats.get(k, 0)) + 1
        _pp230_err_repeats[k] = c
        if c >= 3 and (not any(k in str(t or '').lower() for k in ('price','depth','meta','symbol','wallet','wallet_balance','balance','irt','toman','sanctuary','usdt','btc','paxg','network','timeout','ssl','connection'))):
            try:
                _pp230_apply_safe_mode(t, msg=str(e))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
try:
    # Override swallow entrypoint (keeps old behavior but adds self-correction)
    _pp200_swallow = _pp200_heal
except Exception as _pp200_e:
    _pp200_heal(_pp200_e, tag="exc_pass")
    pass
# ----------------------------
# Oracle liquidity sensing (suspicious mismatch => veto BUY)
# ----------------------------
def _pp230_liquidity_snapshot(bot) -> dict:
    out = {
        "total_usdt": 0.0,
        "max_usdt": 0.0,
        "max_wallet": "",
        "share": 0.0,
        "mismatch": 1.0,
        "suspicious": False,
        "reason": "",
        "wallet_errors": 0,
    }
    if bot is None:
        return out
    try:
        bc = getattr(bot, "_dash_balances_cache", None) or {}
        if not isinstance(bc, dict):
            bc = {}
        we = getattr(bot, "_dash_wallet_errors", None) or {}
        if not isinstance(we, dict):
            we = {}
        out["wallet_errors"] = int(len([k for k,v in we.items() if v]))
        total = 0.0
        mx = 0.0
        mxw = ""
        for w, bal in bc.items():
            try:
                if not isinstance(bal, dict):
                    continue
                u = float(bal.get("USDT", bal.get("TETHER", 0.0)) or 0.0)
            except Exception:
                u = 0.0
            total += max(0.0, u)
            if u > mx:
                mx = u
                mxw = str(w)
        out["total_usdt"] = float(total)
        out["max_usdt"] = float(mx)
        out["max_wallet"] = str(mxw)
        share = (mx / total) if total > 0 else 0.0
        out["share"] = float(share)
        out["mismatch"] = float(max(0.0, min(1.0, 1.0 - share)))
        # suspicious when $100-ish capital is fragmented OR wallet errors exist OR data looks inconsistent
        try:
            principal = float(_pp230_os.getenv("PP200PS_PRINCIPAL_USDT", "100") or 100) if _pp230_os is not None else 100.0
        except Exception:
            principal = 100.0
        try:
            band = float(_pp230_os.getenv("PP200PS_PRINCIPAL_BAND", "1.35") or 1.35) if _pp230_os is not None else 1.35
        except Exception:
            band = 1.35
        principal_mode = (total > 0) and (total <= principal * band)
        if out["wallet_errors"] > 0 and principal_mode:
            out["suspicious"] = True
            out["reason"] = "wallet_error"
            return out
        # fragmentation threshold
        if principal_mode and share < 0.58 and total >= 20.0:
            out["suspicious"] = True
            out["reason"] = "fragmented_principal"
            return out
        # inconsistency: total ~0 but max>0 shouldn't happen
        if total <= 0.0 and mx > 0.0:
            out["suspicious"] = True
            out["reason"] = "inconsistent_balances"
            return out
        out["suspicious"] = False
        out["reason"] = "ok"
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp230_liquidity_snapshot")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    return out

def _pp230_principal_mode(bot) -> bool:
    try:
        bc = getattr(bot, "_dash_balances_cache", None) or {}
        total = 0.0
        if isinstance(bc, dict):
            for bal in bc.values():
                if isinstance(bal, dict):
                    try:
                        total += float(bal.get("USDT", bal.get("TETHER", 0.0)) or 0.0)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
        principal = float(_pp230_os.getenv("PP200PS_PRINCIPAL_USDT", "100") or 100) if _pp230_os is not None else 100.0
        band = float(_pp230_os.getenv("PP200PS_PRINCIPAL_BAND", "1.35") or 1.35) if _pp230_os is not None else 1.35
        return (total > 0) and (total <= principal * band)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return True

# ----------------------------
# Oracle Wisdom Index + Stability snapshot surfaced in ledger and dashboard
# ----------------------------
def _pp230_compute_oracle_stability(bridge) -> float:
    try:
        led = getattr(bridge, "ledger", None)
        total = float(getattr(led, "total", 0) or 0)
        op = float(getattr(led, "operational", 0) or 0)
        fails = float(getattr(led, "failures", 0) or 0)
        nonop = 0.0
        try:
            if led is not None and hasattr(led, "non_operational_count"):
                nonop = float(led.non_operational_count() or 0)
        except Exception:
            nonop = 0.0
        # stability in [0,1]
        denom = (total + 1.0)
        okr = (op + 1.0) / denom
        fr = min(0.9, fails / denom)
        nr = min(0.9, nonop / denom)
        st = okr * (1.0 - 0.55 * fr) * (1.0 - 0.45 * nr)
        if _pp230_math is not None and (not _pp230_math.isfinite(st)):
            return 0.0
        return float(max(0.0, min(1.0, st)))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

def _pp230_top_wisdom(bridge, k: int = 4):
    try:
        weights = getattr(bridge, "weights", None) or {}
        if not isinstance(weights, dict):
            return []
        led = getattr(bridge, "ledger", None)
        state = getattr(led, "state", None) if led is not None else None
        # prefer operational / degraded over non-operational
        items = []
        for nm, w in list(weights.items()):
            try:
                ww = float(w)
            except Exception:
                ww = 0.0
            st = ""
            try:
                if isinstance(state, dict):
                    st = str(state.get(nm, ""))
            except Exception:
                st = ""
            if st == "NON_OPERATIONAL":
                ww *= 0.15
            items.append((nm, ww))
        items.sort(key=lambda x: x[1], reverse=True)
        return items[:max(1, int(k))]
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return []

