def _pp230_bridge_tick(self, sym: str, symst, bid: float, ask: float, mid: float, depth_data: dict) -> dict:
    # Apply safe overrides via temporary env (best-effort, bounded duration)
    env_prev = {}
    lk = _pp230_env_lock
    try:
        if _pp230_os is not None and isinstance(_pp230_safe_overrides, dict) and any(v is not None for v in _pp230_safe_overrides.values()):
            if lk is not None:
                lk.acquire()
            for k, v in _pp230_safe_overrides.items():
                if v is None:
                    continue
                try:
                    env_prev[k] = _pp230_os.environ.get(k)
                    _pp230_os.environ[k] = str(v)
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    try:
        out = _pp230__orig_bridge_tick(self, sym, symst, bid, ask, mid, depth_data) if callable(_pp230__orig_bridge_tick) else {}
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp230_bridge_tick")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        out = {}
    finally:
        # restore env
        try:
            if _pp230_os is not None and env_prev:
                for k, prev in env_prev.items():
                    try:
                        if prev is None:
                            _pp230_os.environ.pop(k, None)
                        else:
                            _pp230_os.environ[k] = str(prev)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
        finally:
            try:
                if lk is not None:
                    lk.release()
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    # snapshot stability + wisdom for dashboard/ledger
    try:
        st = _pp230_compute_oracle_stability(self)
        bot = getattr(self, "bot", None)
        if bot is not None:
            try:
                setattr(bot, "_pp230_oracle_stability", float(st))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        led = getattr(self, "ledger", None)
        if led is not None:
            try:
                setattr(led, "_pp230_oracle_stability", float(st))
                setattr(led, "_pp230_top_wisdom", _pp230_top_wisdom(self, k=4))
                setattr(led, "_pp230_liq_snapshot", _pp230_liquidity_snapshot(bot))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    return out

