def _pp230_recovered_logic_brief(self) -> str:
    base = ""
    try:
        if callable(_pp230__orig_rlb):
            base = str(_pp230__orig_rlb(self) or "")
    except Exception:
        base = ""
    try:
        st = float(getattr(self, "_pp230_oracle_stability", 0.0) or 0.0)
    except Exception:
        st = 0.0
    tw = []
    try:
        tw = list(getattr(self, "_pp230_top_wisdom", []) or [])
    except Exception:
        tw = []
    parts = []
    if base:
        parts.append(base)
    parts.append(f"WISDOM={max(0.0, min(1.0, st)):.2f}")
    if tw:
        try:
            show = " ".join([f"{str(nm)[:22]}={float(w):.2f}" for nm, w in tw[:4]])
            parts.append(f"TOP[{show}]")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    # liquidity snapshot for oracle veto visibility
    try:
        ls = getattr(self, "_pp230_liq_snapshot", None) or {}
        if isinstance(ls, dict):
            if bool(ls.get("suspicious")):
                parts.append(f"LIQ_ALERT={str(ls.get('reason','?'))}")
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    return " | ".join([p for p in parts if p])[:260]

