def _pp230_secondary_confirm_or_veto(self, sym: str, proposed: str):
    p = (proposed or "HOLD").upper()
    confirm, veto, reason = (False, False, "n/a")
    try:
        if callable(_pp230__orig_secondary):
            confirm, veto, reason = _pp230__orig_secondary(self, sym, proposed)
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp230_secondary_base")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        confirm, veto, reason = (False, False, "legacy_err")

    # Final sovereign rule: preserve $100 principal; on suspicion => freeze and veto BUY
    try:
        if p == "BUY":
            bot = getattr(self, "bot", None)
            snap = _pp230_liquidity_snapshot(bot)
            if bool(snap.get("suspicious")) and _pp230_principal_mode(bot):
                try:
                    if "pp220" in globals() and callable(globals().get("_pp220_set_freeze")):
                        globals()["_pp220_set_freeze"](90.0, f"PP230_ORACLE_LIQ_VETO:{snap.get('reason','?')}")
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                return False, True, f"oracle_liquidity_veto:{snap.get('reason','?')}"
            # conflict among recovered genes => strategic patience
            try:
                c = self.get_cached(sym)
                details = list(c.get("details") or [])
            except Exception:
                details = []
            if details and _pp230_principal_mode(bot):
                pos = 0.0
                neg = 0.0
                for it in details:
                    try:
                        nm = str(it[0])
                        strength = float(it[1])
                        w = float((getattr(self, "weights", {}) or {}).get(nm, 0.0) or 0.0)
                        if strength >= 0:
                            pos += w * min(1.0, strength)
                        else:
                            neg += w * min(1.0, -strength)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_continue")
                        continue
                if pos >= 0.35 and neg >= 0.35:
                    try:
                        if "pp220" in globals() and callable(globals().get("_pp220_set_freeze")):
                            globals()["_pp220_set_freeze"](45.0, "PP230_ORACLE_CONFLICT_VETO")
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
                    return False, True, "oracle_conflict_veto"
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp230_secondary_veto")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    return confirm, veto, reason

