def _pp230_place_buy(self, api, wname: str, sym: str, qty: float, price: float):
    # Honor sovereign deadlock
    try:
        if "pp220" in globals() and callable(globals().get("_pp220_is_frozen")) and globals()["_pp220_is_frozen"]():
            return {"ok": False, "status": 0, "error": "SOVEREIGN_DEADLOCK", "text": "Frozen by sovereign deadlock"}
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    # Oracle liquidity veto (final)
    try:
        bridge = getattr(self, "_pp200_bridge", None)
        if bridge is not None and hasattr(bridge, "secondary_confirm_or_veto"):
            c, v, r = bridge.secondary_confirm_or_veto(sym, "BUY")
            if v:
                return {"ok": False, "status": 0, "error": "ORACLE_VETO", "text": str(r)[:220]}
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp230_place_buy_oracle")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    # If principal-mode, route buy to the wallet with max USDT (to preserve $100 buying power)
    try:
        snap = _pp230_liquidity_snapshot(self)
        if _pp230_principal_mode(self) and snap.get("max_wallet"):
            best = str(snap.get("max_wallet"))
            # if selected wallet differs and best wallet api exists, reroute
            if best and str(wname) != best:
                try:
                    api2 = (getattr(self, "apis", {}) or {}).get(best)
                    if api2 is not None:
                        api = api2
                        wname = best
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    # Call original
    try:
        if callable(_pp230__orig_place_buy):
            return _pp230__orig_place_buy(self, api, wname, sym, qty, price)
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp230_place_buy")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        try:
            if "pp220" in globals() and callable(globals().get("_pp220_set_freeze")):
                globals()["_pp220_set_freeze"](180.0, f"PP230_BUY_ERR:{type(_e).__name__}")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        return {"ok": False, "status": 0, "error": "BUY_EXCEPTION", "text": f"{type(_e).__name__}:{_e}"[:220]}

    return {"ok": False, "status": 0, "error": "BUY_UNAVAILABLE", "text": "buy unavailable"}

