# ======================================================================
# PP256: Persist Pattern-Book (Predictive Veto Memory) with oracle_wisdom.json
# - No changes to ArzPlus API / tokens / network routines
# - Minimal, append-only monkeypatch: extends wisdom persistence to include
#   a bounded snapshot of _pp250_pattern (loss-pattern book) so Oracle veto
#   remains effective after restarts.
# ======================================================================

try:
    import ast as _pp256_ast
except Exception:
    _pp256_ast = None

def _pp256_pattern_snapshot(bridge, max_items: int = 200):
    """Return a JSON-safe bounded snapshot of bridge._pp250_pattern."""
    out = []
    try:
        pat = getattr(bridge, "_pp250_pattern", None)
        if not isinstance(pat, dict):
            return out
        items = list(pat.items())
        if max_items and len(items) > int(max_items):
            items = items[-int(max_items):]
        for fp, rec in items:
            try:
                r = rec if isinstance(rec, dict) else {}
                out.append({
                    "fp": repr(fp),
                    "tot": float(r.get("tot", 0.0) or 0.0),
                    "loss": float(r.get("loss", 0.0) or 0.0),
                    "win": float(r.get("win", 0.0) or 0.0),
                    "last": float(r.get("last", 0.0) or 0.0),
                })
            except Exception:
                out.append({"fp": repr(fp), "tot": 0.0, "loss": 0.0, "win": 0.0, "last": 0.0})
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp256_pattern_snapshot")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    return out

def _pp256_pattern_restore(bridge, payload: dict):
    """Restore bridge._pp250_pattern from JSON payload (best-effort)."""
    try:
        if not isinstance(payload, dict):
            return 0
        seq = payload.get("pattern_book")
        if not isinstance(seq, list):
            return 0
        max_items = int(_pp255_os.getenv("PP256_PATTERN_MAX", "200") or 200)
        # Restore as OrderedDict if available
        try:
            od = _pp250_OrderedDict()
        except Exception:
            od = {}
        n = 0
        for row in seq[-max_items:]:
            if not isinstance(row, dict):
                continue
            fp_s = row.get("fp")
            if fp_s is None:
                continue
            fp = fp_s
            if _pp256_ast is not None:
                try:
                    fp = _pp256_ast.literal_eval(fp_s)
                except Exception:
                    fp = fp_s
            rec = {
                "tot": float(row.get("tot", 0.0) or 0.0),
                "loss": float(row.get("loss", 0.0) or 0.0),
                "win": float(row.get("win", 0.0) or 0.0),
                "last": float(row.get("last", 0.0) or 0.0),
            }
            try:
                od[fp] = rec
            except Exception:
                try:
                    # fallback for non-hashable fp
                    od[str(fp)] = rec
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_continue")
                    continue
            n += 1
        try:
            setattr(bridge, "_pp250_pattern", od)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        return int(n)
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp256_pattern_restore")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        return 0

# --- Extend PP255 wisdom load/save (append-only) ---
try:
    _pp256__orig_wisdom_load = _pp255_wisdom_load
    _pp256__orig_wisdom_save = _pp255_wisdom_save

    def _pp255_wisdom_load(bridge) -> None:  # noqa: F811 (intentional override)
        try:
            _pp256__orig_wisdom_load(bridge)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        try:
            if _pp255_json is None:
                return
            p = _pp255_wisdom_path()
            if not p or (not _pp255_os.path.exists(p)):
                return
            with open(p, "r", encoding="utf-8") as f:
                obj = _pp255_json.load(f)
            n = _pp256_pattern_restore(bridge, obj if isinstance(obj, dict) else {})
            try:
                setattr(bridge, "_pp256_pattern_loaded", int(n))
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        except Exception as _e:
            try:
                _pp200_heal(_e, tag="pp256_wisdom_load_pattern")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    def _pp255_wisdom_save(bridge, force: bool = False) -> None:  # noqa: F811
        """Persist wisdom counters + bounded pattern book snapshot (atomic)."""
        try:
            if _pp255_json is None:
                return
            # keep existing throttle rules inside orig save by checking last_save
            now = _pp255_now()
            last = float(getattr(bridge, "_pp255_wisdom_last_save", 0.0) or 0.0)
            min_iv = float(_pp255_os.getenv("PP255_WISDOM_SAVE_MIN_SEC", "8") or 8.0)
            if (not force) and last > 0 and (now - last) < min_iv:
                return

            # Build base payload similar to pp255
            wt = int(getattr(bridge, "_pp250_w_total", 0) or 0)
            wy = int(getattr(bridge, "_pp250_w_yes", 0) or 0)
            wv = int(getattr(bridge, "_pp250_w_veto", 0) or 0)
            wl = str(getattr(bridge, "_pp250_w_last", "") or "")

            max_items = int(_pp255_os.getenv("PP256_PATTERN_MAX", "200") or 200)
            snap = _pp256_pattern_snapshot(bridge, max_items=max_items)

            payload = {}
            try:
                _p = _pp255_wisdom_path()
                if _p and _pp255_os.path.exists(_p):
                    with open(_p, "r", encoding="utf-8") as _f:
                        _o = _pp255_json.load(_f)
                        if isinstance(_o, dict):
                            payload = _o
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                payload.update({
                    "version": "pp256",
                    "ts": float(now),
                    "w_total": wt,
                    "w_yes": wy,
                    "w_veto": wv,
                    "w_last": wl[:240],
                    "pattern_book": snap,                 # bounded
                    "pattern_book_n": int(len(snap)),
                    "first_law": _PP255_FIRST_LAW,
                })
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            ok = _pp255_atomic_write_json(_pp255_wisdom_path(), payload)
            if ok:
                bridge._pp255_wisdom_last_save = now
        except Exception as _e:
            try:
                _pp200_heal(_e, tag="pp256_wisdom_save")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
except Exception as _e:
    try:
        _pp200_heal(_e, tag="pp256_patch_wisdom_persist_pattern")
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
# ============================================================
# PP257: THE IMMORTAL SOVEREIGN ORACLE (DNA + ABSOLUTE VETO + DEEP REPAIR)
# - No external dependencies (stdlib only)
# - Does NOT touch ArzPlus API communication functions / tokens
# ============================================================
try:
    import os as _pp257_os
    import time as _pp257_time
    import json as _pp257_json
    import tempfile as _pp257_tempfile
except Exception:
    _pp257_os = None
    _pp257_time = None
    _pp257_json = None
    _pp257_tempfile = None

_PP257_FIRST_LAW = ""

def _pp257_now() -> float:
    try:
        return float(_pp257__pp920_time.time())
    except Exception:
        try:
            return float(_pp920_time.time())
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

def _pp257_emergency_path() -> str:
    try:
        p = str((_pp257_os.getenv("PP257_EMERGENCY_PATH", "") or "").strip())
        if p:
            return p
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    return "emergency_state.json"

def _pp257_atomic_write_json(path: str, payload) -> bool:
    """Atomic JSON write; never raises."""
    try:
        if _pp257_json is None or _pp257_os is None or _pp257_tempfile is None:
            return False
        if not path:
            return False
        d = _pp257_os.path.dirname(path) or "."
        try:
            _pp257_os.makedirs(d, exist_ok=True)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        fd, tmp = _pp257_tempfile.mkstemp(prefix=".__pp257_", suffix=".json", dir=d)
        try:
            with _pp257_os.fdopen(fd, "w", encoding="utf-8") as f:
                _pp257_json.dump(payload, f, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
                f.flush()
                try:
                    _pp257_os.fsync(f.fileno())
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
            try:
                _pp257_os.replace(tmp, path)
            except Exception:
                try:
                    _pp257_os.rename(tmp, path)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return False
            return True
        finally:
            try:
                if _pp257_os.path.exists(tmp):
                    _pp257_os.unlink(tmp)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

def _pp257_safe_float(x, default=0.0):
    try:
        return float(x)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(default)

def _pp257_clamp(x, lo, hi):
    try:
        xv = float(x)
        return max(float(lo), min(float(hi), xv))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(lo)

