def _pp255_wisdom_load(bridge) -> None:  # noqa: F811
    """PP257: load counters + pattern book + full gene weights + DNA created timestamp."""
    try:
        # call existing loader first (counters + pattern)
        try:
            if callable(_pp257__orig_wisdom_load):
                _pp257__orig_wisdom_load(bridge)
        except Exception as _e:
            try:
                _pp200_heal(_e, tag="pp257_wisdom_load_base")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        if _pp257_json is None or _pp257_os is None:
            return
        try:
            p = _pp255_wisdom_path()
        except Exception:
            p = ""
        if not p or (not _pp257_os.path.exists(p)):
            return
        with open(p, "r", encoding="utf-8") as f:
            obj = _pp257_json.load(f)
        if not isinstance(obj, dict):
            return

        # DNA created timestamp for age display
        try:
            cts = float(obj.get("dna_created_ts", 0.0) or 0.0)
            if cts <= 0.0:
                cts = _pp257_now()
            setattr(bridge, "_pp257_dna_created_ts", cts)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        # persist weights snapshot
        try:
            sw = obj.get("gene_weights", obj.get("weights", None))
            if isinstance(sw, dict):
                # store raw saved weights so late-discovered genes can pick them up
                try:
                    bridge._pp257_saved_weights = {str(k): _pp257_safe_float(v, 0.3) for k, v in sw.items()}
                except Exception:
                    bridge._pp257_saved_weights = {}
                _pp257_merge_saved_weights_into_bridge(bridge, override=True)
        except Exception as _e:
            try:
                _pp200_heal(_e, tag="pp257_wisdom_load_weights")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp257_wisdom_load")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
def _pp255_wisdom_save(bridge, force: bool = False) -> None:  # noqa: F811
    """PP257: persist counters + bounded pattern book + full gene weights + DNA created timestamp."""
    try:
        # keep existing save behavior (throttle) by calling base first (it will write), but we want enriched file.
        # We'll write our enriched payload ourselves respecting throttle rules.
        if _pp257_json is None or _pp257_os is None:
            return
        try:
            path = _pp255_wisdom_path()
        except Exception:
            path = ""
        if not path:
            return

        now = _pp257_now()
        # throttle (default 8s)
        try:
            min_sec = float(_pp257_os.getenv("PP255_WISDOM_SAVE_MIN_SEC", "8") or 8.0)
        except Exception:
            min_sec = 8.0
        last = float(getattr(bridge, "_pp255_wisdom_last_save", 0.0) or 0.0)
        if (not force) and (now - last) < float(min_sec):
            return

        # load previous file to preserve dna_created_ts
        prev = {}
        try:
            if _pp257_os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    prev = _pp257_json.load(f)
                if not isinstance(prev, dict):
                    prev = {}
        except Exception:
            prev = {}

        created = _pp257_safe_float(prev.get("dna_created_ts", 0.0), 0.0)
        if created <= 0.0:
            created = _pp257_now()

        wt = int(getattr(bridge, "_pp250_w_total", 0) or 0)
        wy = int(getattr(bridge, "_pp250_w_yes", 0) or 0)
        wv = int(getattr(bridge, "_pp250_w_veto", 0) or 0)
        wl = str(getattr(bridge, "_pp250_w_last", "") or "")

        payload = {
            "version": "pp257",
            "ts": now,
            "dna_created_ts": created,
            "w_total": wt,
            "w_yes": wy,
            "w_veto": wv,
            "w_last": wl[:240],
            "first_law": _PP257_FIRST_LAW,
        }

        # pattern snapshot (bounded) if available
        try:
            max_items = int(_pp257_os.getenv("PP256_PATTERN_MAX", "200") or 200)
        except Exception:
            max_items = 200
        try:
            snap = None
            if callable(globals().get("_pp256_pattern_snapshot")):
                snap = globals().get("_pp256_pattern_snapshot")(bridge, max_items=max_items)
            if isinstance(snap, list):
                payload["pattern_book"] = snap
        except Exception as _e:
            try:
                _pp200_heal(_e, tag="pp257_wisdom_save_pattern")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        # weights snapshot (full)
        try:
            payload["gene_weights"] = _pp257_weights_snapshot(bridge)
        except Exception:
            payload["gene_weights"] = {}

        ok = _pp257_atomic_write_json(path, payload)
        if ok:
            try:
                bridge._pp255_wisdom_last_save = now
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                bridge._pp257_dna_created_ts = created
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp257_wisdom_save")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
