def _pp257_fmt_age(sec: float) -> str:
    try:
        s = max(0.0, float(sec))
    except Exception:
        s = 0.0
    d = int(s // 86400)
    h = int((s % 86400) // 3600)
    m = int((s % 3600) // 60)
    if d > 0:
        return f"{d}d {h:02d}h"
    if h > 0:
        return f"{h}h {m:02d}m"
    return f"{m}m"

