def _pp257_reports_panel(self):
    """Mobile-friendly reports panel with DNA age + swallow count and pulsing seal."""
    try:
        # prefer existing panel if it already returns rich Panel
        base = None
        if callable(_pp257__orig_reports_panel):
            try:
                base = _pp257__orig_reports_panel(self)
            except Exception:
                base = None
        # We will build a compact list-style panel if rich is available
        try:
            from rich.panel import Panel as _P
            from rich.text import Text as _T
            from rich.align import Align as _A
        except Exception:
            _P = None
            _T = None
            _A = None

        bot = getattr(self, "bot", None)
        # compute DNA age from bridge
        age_s = 0.0
        try:
            br = getattr(bot, "_pp200_bridge", None)
            cts = float(getattr(br, "_pp257_dna_created_ts", 0.0) or 0.0)
            if cts <= 0.0:
                # fallback: read from file if exists
                p = _pp255_wisdom_path()
                if _pp257_os is not None and _pp257_json is not None and p and _pp257_os.path.exists(p):
                    with open(p, "r", encoding="utf-8") as f:
                        obj = _pp257_json.load(f)
                    if isinstance(obj, dict):
                        cts = float(obj.get("dna_created_ts", 0.0) or 0.0)
            if cts > 0.0:
                age_s = max(0.0, _pp257_now() - cts)
        except Exception:
            age_s = 0.0

        # pulsing seal: blink sometimes
        now = _pp257_now()
        blink_on = (int(now) % 10) < 3
        seal_style = "blink bold gold1" if blink_on else "bold gold1"

        # metrics
        swallow_c = 0
        try:
            swallow_c = int(globals().get("_pp200_heal_count", 0) or 0)
        except Exception:
            swallow_c = 0

        # wisdom score
        wscore = ""
        try:
            br = getattr(bot, "_pp200_bridge", None)
            wt = float(getattr(br, "_pp250_w_total", 0) or 0.0)
            wy = float(getattr(br, "_pp250_w_yes", 0) or 0.0)
            wscore = f"{(wy/wt*100.0):.1f}%" if wt > 0 else "0.0%"
        except Exception:
            wscore = "?"

        # freeze status
        freeze = "OFF"
        try:
            fr = float(getattr(bot, "_pp220_freeze_until", 0.0) or 0.0)
            if fr > _pp257_now():
                freeze = "ON"
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        if _P is None:
            # fallback text-only
            lines = [
                _PP257_FIRST_LAW,
                f"ORACLE_DNA_AGE: {_pp257_fmt_age(age_s)}",
                f"ORACLE_WISDOM_SCORE: {wscore}",
                f"HEALING_TOTAL: {swallow_c}",
                f"FREEZE: {freeze}",
            ]
            return "\n".join(lines)

        # rich panel content
        t = _T()
        t.append(_PP257_FIRST_LAW + "\n", style=seal_style)
        t.append(f"ORACLE_DNA_AGE: {_pp257_fmt_age(age_s)}    ", style="bold white")
        t.append(f"ORACLE_WISDOM_SCORE: {wscore}\n", style="white")
        t.append(f"HEALING_TOTAL: {swallow_c}    ", style="white")
        t.append(f"FREEZE: {freeze}\n", style="white")

        # If base is a Panel, keep it but prepend our compact header by merging into a new Panel
        try:
            return _P(_A.center(t), title="[bold white]REPORTS[/bold white]", style="white on black")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return _P(t, title="[bold white]REPORTS[/bold white]", style="white on black")
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp257_reports_panel")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        if callable(_pp257__orig_reports_panel):
            return _pp257__orig_reports_panel(self)
        return None

