def _pp257_record_emergency(side: str, wallet: str, sym: str, qty, price, err: str):
    """Persist an emergency state when order path throws an unknown exception."""
    try:
        if _pp257_json is None:
            return
        now = _pp257_now()
        payload = {
            "ts": now,
            "pending": True,
            "checked": False,
            "side": str(side or ""),
            "wallet": str(wallet or ""),
            "symbol": str(sym or ""),
            "qty": str(qty),
            "price": str(price),
            "err": str(err or "")[:500],
            "first_law": _PP257_FIRST_LAW,
        }
        _pp257_atomic_write_json(_pp257_emergency_path(), payload)
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp257_emergency_save")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
def _pp257_load_emergency():
    try:
        if _pp257_json is None or _pp257_os is None:
            return None
        p = _pp257_emergency_path()
        if not p or (not _pp257_os.path.exists(p)):
            return None
        with open(p, "r", encoding="utf-8") as f:
            obj = _pp257_json.load(f)
        return obj if isinstance(obj, dict) else None
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return None

def _pp257_mark_emergency_checked(extra=None):
    try:
        obj = _pp257_load_emergency()
        if not isinstance(obj, dict):
            return
        obj["checked"] = True
        obj["checked_ts"] = _pp257_now()
        if isinstance(extra, dict):
            obj["check"] = extra
        _pp257_atomic_write_json(_pp257_emergency_path(), obj)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
def _pp257_check_emergency_on_boot(bot):
    """On startup, if emergency_state says a possible position may be open, query balances and freeze briefly."""
    try:
        st = _pp257_load_emergency()
        if not isinstance(st, dict):
            return
        if not bool(st.get("pending", False)):
            return
        if bool(st.get("checked", False)):
            return

        sym = str(st.get("symbol", "") or "").upper()
        wallet = str(st.get("wallet", "") or "")
        side = str(st.get("side", "") or "")

        # freeze to prevent duplicate orders until checked
        try:
            if "pp220" in globals() and callable(globals().get("_pp220_set_freeze")):
                globals()["_pp220_set_freeze"](90.0, "PP257_EMERGENCY_RECOVERY")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        api = None
        try:
            apis = getattr(bot, "apis", None)
            if isinstance(apis, dict) and wallet in apis:
                api = apis.get(wallet)
            elif isinstance(apis, dict) and apis:
                api = list(apis.values())[0]
        except Exception:
            api = None

        info = {"wallet": wallet, "symbol": sym, "side": side, "base_balance": None}
        if api is not None:
            try:
                bal = None
                if callable(getattr(api, "balance", None)):
                    bal = api.balance()
                elif callable(getattr(api, "get_balance", None)):
                    bal = api.get_balance()
                info["bal_type"] = type(bal).__name__
                # best-effort base asset extraction
                base = sym
                for q in ("USDT", "IRT", "IRR"):
                    if base.endswith(q) and len(base) > len(q):
                        base = base[:-len(q)]
                        break
                # search balance dict for base key
                bb = None
                if isinstance(bal, dict):
                    for k in (base, base.lower(), base.upper()):
                        if k in bal:
                            bb = bal.get(k)
                            break
                    # nested common shapes
                    if bb is None:
                        for container_key in ("balances", "result", "data"):
                            if isinstance(bal.get(container_key), dict) and base in bal.get(container_key):
                                bb = bal.get(container_key).get(base)
                                break
                info["base_balance"] = bb
            except Exception as _e:
                info["check_err"] = f"{type(_e).__name__}:{_e}"
        _pp257_mark_emergency_checked(info)
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp257_emergency_boot")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
