def _pp257_transaction_guard(fn, side: str):
    def _wrapped(self, api, wname, sym, qty, price):
        try:
            return fn(self, api, wname, sym, qty, price)
        except Exception as _e:
            # record emergency, freeze, and return a safe failure (do not raise)
            try:
                _pp257_record_emergency(side, wname, sym, qty, price, f"{type(_e).__name__}:{_e}")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                if "pp220" in globals() and callable(globals().get("_pp220_set_freeze")):
                    globals()["_pp220_set_freeze"](120.0, f"PP257_TX_GUARD:{side}")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                _pp200_heal(_e, tag=f"pp257_tx_guard_{side.lower()}")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            return {"ok": False, "err": f"pp257_tx_guard:{type(_e).__name__}", "reason": str(_e)[:220]}
    return _wrapped

try:
    if callable(_pp257__orig_place_buy):
        ArzPlusBot._place_buy = _pp257_transaction_guard(_pp257__orig_place_buy, "BUY")
    if callable(_pp257__orig_place_sell):
        ArzPlusBot._place_sell = _pp257_transaction_guard(_pp257__orig_place_sell, "SELL")
except Exception as _e:
    try:
        _pp200_heal(_e, tag="pp257_patch_tx_guard")
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
# ----------------------------
# 5) SWALLOW SAFE MODE: if the same tag repeats >3 times, revert key params to safe
# ----------------------------
try:
    _pp257__orig_swallow = _pp200_swallow
except Exception:
    _pp257__orig_swallow = None

_pp257_swallow_hist = {}

def _pp257_swallow(e, tag="swallow"):
    try:
        if callable(_pp257__orig_swallow):
            _pp257__orig_swallow(e, tag=tag)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    # repeat detection
    try:
        t = str(tag or "swallow")[:80]
        c = int(_pp257_swallow_hist.get(t, 0) or 0) + 1
        _pp257_swallow_hist[t] = c
        if c == 3:
            # safe mode: lower legacy load and freeze briefly to stop trading in unstable schema
            try:
                _pp257_os.environ.setdefault("PP200_GENE_BATCH", "6")
                _pp257_os.environ.setdefault("PP200PS_BUDGET_MS", "85")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            try:
                if "pp220" in globals() and callable(globals().get("_pp220_set_freeze")):
                    globals()["_pp220_set_freeze"](75.0, f"PP257_SAFE_MODE:{t}")
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
try:
    _pp200_swallow = _pp257_swallow  # type: ignore
except Exception as _pp200_e:
    _pp200_heal(_pp200_e, tag="exc_pass")
    pass

