# ============================================================
# PP-UNIFIED CORE BRIDGE (v8057-MATURE) — NO TOKEN TOUCH
# هدف:
#   1) همه تصمیم‌گیرها به مسیر واحد ارسال سفارش وصل شوند.
#   2) در هر سیکل فقط یک سفارش ارسال شود (ONE-ORDER PER CYCLE).
#   3) خروج از WAITING طولانی با یک seed-order محافظه‌کار (قابل خاموش/روشن با ENV).
# ============================================================

def _pp_unified_submit(self, api, wname: str, sym: str, side: str, qty: float, price: float,
                       *, reason: str = "", src: str = "UNIFIED", prio: int = 8,
                       force_seed: bool = False) -> dict:
    # Latch: one order per cycle
    try:
        if bool(getattr(self, "_pp_cycle_order_sent", False)):
            return {"ok": False, "status": 0, "error": "CYCLE_ORDER_ALREADY_SENT", "message": "one order per cycle"}
    except Exception:
        pass

    _side = str(side or "").strip().lower()
    if _side not in ("buy", "sell"):
        return {"ok": False, "status": 0, "error": "BAD_SIDE", "message": str(side)}

    # Commit reason for dashboard (keep R visible)
    try:
        _r = reason or f"{src}:{_side.upper()} {sym} qty={float(qty or 0.0):.8f} px={float(price or 0.0):.2f}"
        if hasattr(self, "_pp9000_commit_decision"):
            self._pp9000_commit_decision(str(wname), str(sym), action="WAITING", reason=str(_r), src=str(src), prio=int(prio), stale_after=8.0)
    except Exception:
        pass

    # Optional bypass for seed order only (still respects spec checks in place_* methods)
    did_force = False
    if bool(force_seed):
        try:
            setattr(self, "_pp_force_seed", True)
            did_force = True
        except Exception:
            did_force = False

    try:
        if _side == "buy":
            res = self._place_buy(api, wname, sym, qty, price)
        else:
            res = self._place_sell(api, wname, sym, qty, price)
    finally:
        if did_force:
            try:
                setattr(self, "_pp_force_seed", False)
            except Exception:
                pass

    ok = False
    try:
        if isinstance(res, dict):
            ok = bool(res.get("ok", False))
        else:
            ok = True
    except Exception:
        ok = False

    if ok:
        try:
            self._pp_cycle_order_sent = True
            try:
                import time as _t
                self._pp_last_order_ts = float(_t.time())
            except Exception:
                pass
            try:
                self._pp_cycle_order_info = {"wallet": str(wname), "symbol": str(sym), "side": _side, "qty": float(qty or 0.0), "price": float(price or 0.0)}
            except Exception:
                self._pp_cycle_order_info = None
        except Exception:
            pass
    return res if isinstance(res, dict) else {"ok": bool(ok), "status": 0, "data": res}


def _pp_unstuck_seed_tick(self) -> None:
    """
    Anti-stuck seed:
    اگر برای مدت طولانی هیچ سفارشی ثبت نشود و ربات در WAITING بماند،
    یک سفارش BUY کوچک و محافظه‌کار روی نماد نقدشونده (ترجیحاً USDTIRT) ارسال می‌کند.
    کنترل با ENV:
      PP_UNSTUCK_ENABLE=1/0
      PP_UNSTUCK_AFTER_SEC=240
      PP_UNSTUCK_MIN_NOTIONAL_IRT=200000
      PP_UNSTUCK_CASH_FRACTION=0.25
      PP_UNSTUCK_COOLDOWN_SEC=600
    """
    try:
        import os as _os
        import time as _t
        now = float(_t.time())
    except Exception:
        return

    try:
        en = str(_os.getenv("PP_UNSTUCK_ENABLE", "1") or "1").strip().lower() in ("1","true","yes","y","on")
    except Exception:
        en = True
    if not en:
        return

    # Cooldown
    try:
        if now < float(getattr(self, "_pp_unstuck_cd_until", 0.0) or 0.0):
            return
    except Exception:
        pass

    # If already sent order this cycle
    try:
        if bool(getattr(self, "_pp_cycle_order_sent", False)):
            return
    except Exception:
        pass

    # Time since last order
    try:
        last = float(getattr(self, "_pp_last_order_ts", 0.0) or 0.0)
    except Exception:
        last = 0.0
    try:
        boot = float(getattr(self, "_pp_boot_ts", 0.0) or 0.0)
    except Exception:
        boot = 0.0
    if last <= 0.0:
        last = boot

    try:
        after = float(_os.getenv("PP_UNSTUCK_AFTER_SEC", "240") or 240.0)
    except Exception:
        after = 240.0

    # Don't seed immediately after boot
    try:
        if boot > 0.0 and (now - boot) < max(25.0, min(after, 180.0)):
            return
    except Exception:
        pass

    if last > 0.0 and (now - last) < after:
        return

    # Symbols
    try:
        syms = [str(s).strip().upper() for s in (getattr(self, "symbols", None) or []) if str(s).strip()]
    except Exception:
        syms = []
    if not syms:
        return
    pref = ["USDTIRT", "BTCIRT", "PAXGIRT"]
    sym = None
    for p in pref:
        if p in syms:
            sym = p
            break
    if sym is None:
        sym = syms[0]

    # Pick wallet with max quote cash
    quote = "IRT"
    try:
        quote = str(getattr(self, "quote", "IRT") or "IRT").upper().strip()
    except Exception:
        quote = "IRT"

    best = None
    try:
        for w in (getattr(self, "wallets", None) or []):
            wname = str(getattr(w, "name", "") or "").strip()
            api = (getattr(self, "apis", {}) or {}).get(wname)
            if (not wname) or api is None:
                continue
            try:
                b = api.balance()
                data = (b.get("data") if isinstance(b, dict) else {}) or {}
                cash = float(data.get(quote, 0.0) or 0.0)
            except Exception:
                continue
            if best is None or cash > float(best.get("cash", 0.0) or 0.0):
                best = {"wname": wname, "api": api, "cash": cash}
    except Exception:
        best = None

    if not isinstance(best, dict) or float(best.get("cash", 0.0) or 0.0) <= 0.0:
        return

    cash = float(best.get("cash", 0.0) or 0.0)

    # Notional sizing
    try:
        minN = float(_os.getenv("PP_UNSTUCK_MIN_NOTIONAL_IRT", "200000") or 200000.0)
    except Exception:
        minN = 200000.0
    try:
        frac = float(_os.getenv("PP_UNSTUCK_CASH_FRACTION", "0.25") or 0.25)
    except Exception:
        frac = 0.25
    frac = max(0.05, min(frac, 0.50))

    notional = max(minN, cash * frac)
    notional = min(notional, cash * 0.50)
    if notional < (minN * 0.995):
        try:
            self._pp_unstuck_cd_until = now + 90.0
        except Exception:
            pass
        return

    # Price from orderbook
    px = 0.0
    try:
        pub = getattr(self, "public_api", None) or best.get("api")
        ob = pub.depth(sym)
        data = (ob.get("data") if isinstance(ob, dict) else {}) or {}
        asks = data.get("asks") or []
        bids = data.get("bids") or []
        if isinstance(asks, list) and asks:
            px = float((asks[0] or {}).get("price", 0.0) or 0.0)
        if px <= 0.0 and isinstance(bids, list) and bids:
            px = float((bids[0] or {}).get("price", 0.0) or 0.0)
        if px <= 0.0:
            lt = data.get("last_trade") or {}
            px = float((lt.get("price", 0.0) if isinstance(lt, dict) else 0.0) or 0.0)
    except Exception:
        px = 0.0

    if px <= 0.0:
        try:
            self._pp_unstuck_cd_until = now + 60.0
        except Exception:
            pass
        return

    qty = float(notional) / float(px)
    if qty <= 0.0:
        return

    # Commit reason & submit seed (force_seed bypasses veto only for this seed order)
    try:
        r = f"UNSTUCK_SEED {sym} n={float(notional):.0f} cash={float(cash):.0f}"
        if hasattr(self, "_pp9000_commit_decision"):
            self._pp9000_commit_decision(str(best["wname"]), str(sym), action="WAITING", reason=r, src="UNSTUCK", prio=8, stale_after=10.0)
    except Exception:
        pass

    ok = False
    try:
        res = self._pp_unified_submit(best["api"], best["wname"], sym, "buy", qty, px,
                                      reason=f"UNSTUCK_SEED BUY {sym} qty={qty:.8f} px={px:.2f}", src="UNSTUCK", prio=9,
                                      force_seed=True)
        ok = bool(res.get("ok")) if isinstance(res, dict) else False
    except Exception:
        ok = False

    try:
        cd_s = float(_os.getenv("PP_UNSTUCK_COOLDOWN_SEC", "600") or 600.0)
    except Exception:
        cd_s = 600.0
    try:
        self._pp_unstuck_cd_until = now + (cd_s if ok else 60.0)
    except Exception:
        pass


def _pp_apply_unified_bridge() -> None:
    """Attach helpers to PP5 live bot classes."""
    try:
        for _n, _obj in list(globals().items()):
            try:
                if not isinstance(_obj, type):
                    continue
                if hasattr(_obj, "loop") and hasattr(_obj, "_place_buy") and hasattr(_obj, "_place_sell"):
                    if not hasattr(_obj, "_pp_unified_submit"):
                        setattr(_obj, "_pp_unified_submit", _pp_unified_submit)
                    if not hasattr(_obj, "_pp_unstuck_seed_tick"):
                        setattr(_obj, "_pp_unstuck_seed_tick", _pp_unstuck_seed_tick)
            except Exception:
                continue
    except Exception:
        pass

# Apply immediately
_pp_apply_unified_bridge()
