def _pp300_atomic_write(path: str, payload: dict) -> bool:
    """Atomic json write best-effort."""
    try:
        if _pp300_json is None or _pp300_os is None:
            return False
        pdir = _pp300_os.path.dirname(path) or "."
        try:
            _pp300_os.makedirs(pdir, exist_ok=True)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _pp300_json.dump(payload, f, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
            f.flush()
            try:
                _pp300_os.fsync(f.fileno())
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        try:
            _pp300_os.replace(tmp, path)
        except Exception:
            # fallback
            with open(path, "w", encoding="utf-8") as f2:
                _pp300_json.dump(payload, f2, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        try:
            if _pp300_os.path.exists(tmp):
                _pp300_os.remove(tmp)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        return True
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

