def _pp300_bridge_get_weights(bridge) -> dict:
    """Try to snapshot per-gene weights from common bridge layouts."""
    out = {}
    try:
        # v240+ often keeps a dict
        for attr in ("gene_weights", "_gene_weights", "_pp257_gene_weights", "_pp250_gene_weights", "_weights", "weights"):
            try:
                v = getattr(bridge, attr, None)
                if isinstance(v, dict) and v:
                    for k, w in v.items():
                        try:
                            out[str(k)] = float(w)
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                    if out:
                        return out
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        # Some implementations store state per gene
        try:
            genes = getattr(bridge, "_genes", None)
            if isinstance(genes, dict):
                for gname, g in genes.items():
                    try:
                        w = None
                        if isinstance(g, dict):
                            w = g.get("w", g.get("weight", None))
                        else:
                            w = getattr(g, "w", getattr(g, "weight", None))
                        if w is not None:
                            out[str(gname)] = float(w)
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    return out

def _pp300_bridge_apply_weights(bridge, weights: dict) -> None:
    """Apply loaded weights into the bridge (best-effort, non-destructive)."""
    if not isinstance(weights, dict) or not weights:
        return
    try:
        # preferred: a dict field on bridge
        for attr in ("gene_weights", "_gene_weights", "_pp257_gene_weights", "_pp250_gene_weights", "_weights", "weights"):
            try:
                v = getattr(bridge, attr, None)
                if isinstance(v, dict):
                    for k, w in weights.items():
                        try:
                            v[str(k)] = float(w)
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                    return
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        # fallback: per-gene state
        genes = getattr(bridge, "_genes", None)
        if isinstance(genes, dict):
            for k, w in weights.items():
                if k in genes:
                    try:
                        g = genes[k]
                        if isinstance(g, dict):
                            g["w"] = float(w)
                        else:
                            setattr(g, "w", float(w))
                    except Exception as _pp200_e:
                        _pp200_heal(_pp200_e, tag="exc_pass")
                        pass
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
# Wrap existing wisdom save/load to guarantee weights persistence
