def _pp300_wisdom_load(bridge) -> None:
    try:
        if callable(_pp300__base_wisdom_load):
            _pp300__base_wisdom_load(bridge)

        # load enriched payload
        if _pp300_json is None or _pp300_os is None:
            return
        p = ""
        try:
            p = _pp255_wisdom_path()
        except Exception:
            p = _pp300_os.path.join(_pp300_script_dir(), "oracle_wisdom.json")
        if not p or (not _pp300_os.path.exists(p)):
            return
        with open(p, "r", encoding="utf-8") as f:
            obj = _pp300_json.load(f)
        if not isinstance(obj, dict):
            return

        # dna created time
        try:
            cts = float(obj.get("dna_created_ts", 0.0) or 0.0)
            if cts <= 0.0:
                cts = _pp300_now()
            bridge._pp300_dna_created_ts = cts
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        # apply weights
        try:
            w = obj.get("gene_weights", obj.get("weights", None))
            if isinstance(w, dict):
                _pp300_bridge_apply_weights(bridge, w)
                try:
                    bridge._pp300_weights_loaded = True
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp300_wisdom_load")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
def _pp300_wisdom_save(bridge, force: bool = False) -> None:
    """Save counters + pattern + gene weights into oracle_wisdom.json (throttled)."""
    try:
        if _pp300_json is None or _pp300_os is None:
            return

        # honor existing throttle if present
        try:
            now = _pp300_now()
            last = float(getattr(bridge, "_pp300_wisdom_last_save", 0.0) or 0.0)
            min_iv = float(_pp300_os.getenv("PP255_WISDOM_SAVE_MIN_SEC", "8") or 8.0)
            if (not force) and last > 0 and (now - last) < min_iv:
                return
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        path = ""
        try:
            path = _pp255_wisdom_path()
        except Exception:
            path = _pp300_os.path.join(_pp300_script_dir(), "oracle_wisdom.json")
        if not path:
            return

        # load old payload to preserve fields
        payload = {}
        try:
            if _pp300_os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    obj = _pp300_json.load(f)
                if isinstance(obj, dict):
                    payload.update(obj)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        # counters (keep compatibility with pp255/pp257 fields)
        try:
            payload["w_total"] = int(getattr(bridge, "_pp250_w_total", 0) or 0)
            payload["w_yes"] = int(getattr(bridge, "_pp250_w_yes", 0) or 0)
            payload["w_veto"] = int(getattr(bridge, "_pp250_w_veto", 0) or 0)
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        # dna created timestamp
        try:
            created = float(payload.get("dna_created_ts", 0.0) or 0.0)
            if created <= 0.0:
                # prefer bridge
                created = float(getattr(bridge, "_pp300_dna_created_ts", 0.0) or 0.0)
            if created <= 0.0:
                created = _pp300_now()
            payload["dna_created_ts"] = created
            try:
                bridge._pp300_dna_created_ts = created
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        # pattern book snapshot (if present)
        try:
            pat = getattr(bridge, "_pp250_pattern", None)
            if isinstance(pat, dict):
                mx = int(_pp300_os.getenv("PP256_PATTERN_MAX", "200") or 200)
                items = []
                for k, v in list(pat.items())[-mx:]:
                    if isinstance(v, dict):
                        vv = {}
                        for kk in ("tot", "loss", "win", "last"):
                            try:
                                vv[kk] = int(v.get(kk, 0) or 0) if kk != "last" else float(v.get(kk, 0.0) or 0.0)
                            except Exception as _pp200_e:
                                _pp200_heal(_pp200_e, tag="exc_pass")
                                pass
                        items.append([str(k), vv])
                payload["pattern_book"] = items
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        # weights snapshot
        payload["gene_weights"] = _pp300_bridge_get_weights(bridge)

        ok = _pp300_atomic_write(path, payload)
        if ok:
            try:
                bridge._pp300_wisdom_last_save = _pp300_now()
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp300_wisdom_save")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
