def _pp300_wisdom_ratio(bridge) -> float:
    try:
        t = float(getattr(bridge, "_pp250_w_total", 0) or 0.0)
        y = float(getattr(bridge, "_pp250_w_yes", 0) or 0.0)
        if t <= 0:
            return 1.0
        return max(0.0, min(1.0, y / t))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 1.0

def _pp300_pattern_risky(bridge, fingerprint: str) -> bool:
    """Return True if this fingerprint has a loss-heavy history."""
    try:
        pat = getattr(bridge, "_pp250_pattern", None)
        if not isinstance(pat, dict):
            return False
        rec = pat.get(fingerprint)
        if not isinstance(rec, dict):
            return False
        tot = float(rec.get("tot", 0) or 0.0)
        loss = float(rec.get("loss", 0) or 0.0)
        if tot < 3:
            return False
        lr = loss / tot if tot > 0 else 0.0
        thr = float(_pp300_os.getenv("PP300_PATTERN_LOSS_RATE_VETO", "0.60") or 0.60) if _pp300_os else 0.60
        return lr >= thr
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

try:
    _pp300__orig_secondary = _pp200_LegacyBridge.secondary_confirm_or_veto
except Exception:
    _pp300__orig_secondary = None

def _pp300_secondary_confirm_or_veto(self, bot, sym: str, direction: str, confidence: float, details=None):
    """
    Security Council:
      - If wisdom ratio < 0.50 => veto even strong BUY/SELL
      - If pattern book marks current fingerprint risky => veto
      - Otherwise delegate to base / existing logic
    """
    try:
        # delegate first to get base (it may compute fingerprint etc.)
        base = None
        if callable(_pp300__orig_secondary):
            base = _pp300__orig_secondary(self, bot, sym, direction, confidence, details)
        # base can be (ok, reason, extra) or dict; normalize
        ok = True
        reason = ""
        extra = {}
        try:
            if isinstance(base, tuple) and len(base) >= 2:
                ok = bool(base[0])
                reason = str(base[1] or "")
                if len(base) >= 3 and isinstance(base[2], dict):
                    extra = dict(base[2])
            elif isinstance(base, dict):
                ok = bool(base.get("ok", True))
                reason = str(base.get("reason", "") or "")
                extra = dict(base.get("extra", {}) or {})
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        # compute fingerprint (prefer existing in extra/details)
        fp = ""
        try:
            if isinstance(extra, dict):
                fp = str(extra.get("fingerprint", "") or extra.get("fp", "") or "")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        if not fp:
            try:
                if hasattr(self, "_pp250_fingerprint"):
                    fp = str(self._pp250_fingerprint(bot, sym) or "")
            except Exception:
                fp = ""

        # absolute veto conditions
        w = _pp300_wisdom_ratio(self)
        if w < 0.50:
            return (False, f"pp300_abs_veto:w_is_{w:.2f}<0.50", {"wisdom": w, "fingerprint": fp})
        if fp and _pp300_pattern_risky(self, fp):
            return (False, "pp300_abs_veto:pattern_risky", {"wisdom": w, "fingerprint": fp})

        return (ok, reason, extra)
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="pp300_secondary_veto")
        except Exception as _pp200_e:
            _pp200_heal(_pp200_e, tag="exc_pass")
            pass
        return (False, "pp300_abs_veto:exception", {"wisdom": 0.0})

try:
    _pp200_LegacyBridge.secondary_confirm_or_veto = _pp300_secondary_confirm_or_veto
except Exception as _pp200_e:
    _pp200_heal(_pp200_e, tag="exc_pass")
    pass
