def _pp300_install_bot_guards():
    if _pp300_Bot is None:
        return
    # capture originals
    for name in ("_place_buy", "_place_sell", "_balances"):
        if hasattr(_pp300_Bot, name):
            orig = getattr(_pp300_Bot, name)
            if callable(orig) and not getattr(orig, "_pp300_wrapped", False):
                def _mk(name, origf):
                    def _wrapped(self, *a, **kw):
                        # freeze if emergency and not checked
                        try:
                            fu = float(getattr(self, "_pp300_freeze_until", 0.0) or 0.0)
                            if fu > 0 and _pp300_now() < fu and name in ("_place_buy", "_place_sell"):
                                return {"ok": False, "reason": "pp300_freeze_active"}
                        except Exception as _pp200_e:
                            _pp200_heal(_pp200_e, tag="exc_pass")
                            pass
                        with _pp300_guard_cm(name, self, *a, **kw):
                            return origf(self, *a, **kw)
                    _wrapped._pp300_wrapped = True
                    return _wrapped
                setattr(_pp300_Bot, name, _mk(name, orig))
    return

