def _pp300_cycle_wrapper(self, *a, **kw):
    try:
        _pp300_maybe_do_resync()
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    # if emergency file exists, freeze + mark checked lazily
    try:
        if not getattr(self, "_pp300_emergency_checked", False):
            obj = _pp300_load_emergency()
            if isinstance(obj, dict) and obj:
                # freeze immediately to protect principal
                try:
                    setattr(self, "_pp300_freeze_until", _pp300_now() + float(_pp300_os.getenv("PP300_EMERGENCY_FREEZE_SEC", "180") or 180.0))
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                # attempt a balance read (guarded) to surface state
                try:
                    _ = self._balances()
                except Exception as _pp200_e:
                    _pp200_heal(_pp200_e, tag="exc_pass")
                    pass
                _pp300_mark_emergency_checked(obj, note="balances_checked_on_start")
                setattr(self, "_pp300_emergency_checked", True)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    if callable(_pp300__orig_cycle):
        return _pp300__orig_cycle(self, *a, **kw)
    return None

