def _pp300_dna_age_sec(bridge) -> float:
    try:
        created = float(getattr(bridge, "_pp300_dna_created_ts", 0.0) or 0.0)
        if created <= 0:
            # load from file if available
            p = _pp255_wisdom_path()
            if _pp300_os and _pp300_os.path.exists(p):
                with open(p, "r", encoding="utf-8") as f:
                    obj = _pp300_json.load(f)
                created = float((obj or {}).get("dna_created_ts", 0.0) or 0.0)
        if created <= 0:
            return 0.0
        return max(0.0, _pp300_now() - created)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0

