def _pp300_status_items(self):
    items = []
    if callable(_pp300__orig_status_items):
        try:
            items = list(_pp300__orig_status_items(self) or [])
        except Exception:
            items = []
    # add HEALING_TOTAL and ORACLE_DNA_AGE
    try:
        sc = int(getattr(globals().get("_pp200_heal_count", 0), "__int__", lambda: globals().get("_pp200_heal_count", 0))())
    except Exception:
        try:
            sc = int(globals().get("_pp200_heal_count", 0) or 0)
        except Exception:
            sc = 0
    try:
        age = _pp300_dna_age_sec(getattr(self, "bridge", None) or getattr(self, "_pp200_bridge", None) or getattr(self, "legacy_bridge", None) or self)
    except Exception:
        age = 0.0
    try:
        items.append(("HEALING_TOTAL", str(sc)))
        # format age
        d = int(age // 86400)
        h = int((age % 86400) // 3600)
        m = int((age % 3600) // 60)
        items.append(("ORACLE_DNA_AGE", f"{d}d {h:02d}h {m:02d}m"))
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
    return items

