# Centered pulsing signature for log header (no dependency)
def _pp300_emit_signature():
    try:
        sig = ""
        # try rich if available in environment already
        try:
            from rich.console import Console
            from rich.align import Align
            from rich.text import Text
            c = Console()
            # pulse every ~10 seconds
            pulse = int(_pp300_now() // 10) % 2 == 0
            t = Text(sig, style=("bold gold1" if pulse else "bold yellow"))
            c.print(Align.center(t))
        except Exception:
            # plain fallback
            w = 72
            try:
                w = int(_pp300_os.getenv("COLUMNS", "72") or 72)
            except Exception as _pp200_e:
                _pp200_heal(_pp200_e, tag="exc_pass")
                pass
            pad = max(0, (w - len(sig)) // 2)
            print((" " * pad) + sig)
    except Exception as _pp200_e:
        _pp200_heal(_pp200_e, tag="exc_pass")
        pass
