# ============================================================
# v602 Patch Set (non-breaking): legacy preservation + ruthless risk minimization
# ============================================================

# ---- Version seal (duplicate-safe) ----
try:
    if _pp400_os is not None:
        _pp602_VERSION = "v602"
        # If user didn't pin explicitly, surface v602 to dashboards/logs.
        if str(_pp400_os.environ.get("PP_VERSION", "")).strip().lower() in ("", "v400", "v600", "v601"):
            _pp400_os.environ["PP_VERSION"] = _pp602_VERSION
except Exception as _pp200_e:
    _pp200_heal(_pp200_e, tag="exc_pass")
    pass

# ---- SovereignVetoCouncil: add min-size rule when ANY legacy gene hints danger ----
try:
    if "SovereignVetoCouncil" in globals():
        def _pp602_min_size_multiplier(self, sym: str, payload: dict):
            '''
            Returns (multiplier, reason).

            Rule (ruthless):
              If even ONE (legacy/old) gene emits an error/flag or meta-risk signal,
              force trade size down to PP602_MIN_SIZE_MULT (default 0.05).
            '''
            # default no change
            try:
                min_mult = float(_pp400_os.getenv("PP602_MIN_SIZE_MULT", "0.03") or 0.05) if _pp400_os is not None else 0.05
            except Exception:
                min_mult = 0.05
            min_mult = float(max(0.0, min(1.0, min_mult)))

            try:
                if not isinstance(payload, dict):
                    return 1.0, "no_payload"
                details = payload.get("details", []) or []
                # Allow either 5-tuple or 6-tuple detail schema.
                danger_keys = ("risk", "danger", "hazard", "stress", "anomaly", "latency", "freeze", "halt", "blackout", "panic", "veto")
                for d in details:
                    try:
                        if not isinstance(d, (tuple, list)):
                            continue
                        nm = str(d[0] if len(d) > 0 else "")
                        vote = str(d[1] if len(d) > 1 else "HOLD").upper()
                        conf = float(d[2] if len(d) > 2 else 0.0) if len(d) > 2 else 0.0
                        w = float(d[3] if len(d) > 3 else 0.0) if len(d) > 3 else 0.0
                        err = bool(d[4]) if len(d) > 4 else False
                        meta = d[5] if len(d) > 5 else {}
                        # Heuristics for "legacy gene": name starts with common PP prefixes OR meta flag.
                        is_legacy = False
                        try:
                            if nm.startswith(("PP", "_pp", "LEGACY", "Gene", "GENE:", "pp")):
                                is_legacy = True
                        except Exception:
                            is_legacy = False
                        try:
                            if isinstance(meta, dict) and bool(meta.get("legacy", False)):
                                is_legacy = True
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")

                        # If any gene (especially legacy) errored, or meta indicates danger => min size
                        if err and is_legacy:
                            return min_mult, f"legacy_err:{nm}"
                        if isinstance(meta, dict):
                            # Any explicit danger key with truthy or high numeric value
                            for k in danger_keys:
                                if k in meta:
                                    v = meta.get(k)
                                    try:
                                        if isinstance(v, (int, float)) and float(v) >= 0.60:
                                            return min_mult, f"legacy_meta_{k}:{nm}:{float(v):.2f}"
                                        if isinstance(v, bool) and v:
                                            return min_mult, f"legacy_meta_{k}:{nm}"
                                        if isinstance(v, str) and v.strip():
                                            # string reason counts as risk hint
                                            if k in ("risk", "danger", "hazard", "freeze", "halt", "blackout", "panic", "veto", "anomaly"):
                                                return min_mult, f"legacy_meta_{k}:{nm}"
                                    except Exception as _pp200_e:
                                        _pp200_report(_pp200_e, tag="exc_pass")
                            # Textual reason fields (common)
                            try:
                                reason = str(meta.get("reason", "") or meta.get("why", "") or meta.get("note", "")).lower()
                                if is_legacy and any(k in reason for k in ("risk", "danger", "stress", "latency", "anomaly", "freeze", "halt", "blackout", "panic", "veto")):
                                    return min_mult, f"legacy_reason:{nm}"
                            except Exception as _pp200_e:
                                _pp200_report(_pp200_e, tag="exc_pass")

                        # Confidence collapse with non-trivial weight => treat as risk hint (legacy)
                        try:
                            if is_legacy and float(w) >= 0.10 and float(conf) <= 0.12 and vote == "HOLD":
                                return min_mult, f"legacy_lowconf_hold:{nm}"
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                    except Exception:
                        continue
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            return 1.0, "ok"

        SovereignVetoCouncil.min_size_multiplier = _pp602_min_size_multiplier
except Exception as _pp200_e:
    _pp200_heal(_pp200_e, tag="exc_pass")
    pass

