# PP603 Worldclass Patch (non-destructive, token-preserving, legacy-safe)
# =============================================================================
# - Orphan Gene Activation (Risk-first registry)
# - SovereignVetoCouncil hook for orphan risk genes
# - Version seal v603

try:
    import os as _pp603_os
    import sys as _pp603_sys
    import inspect as _pp603_inspect
    import time as _pp603_time
except Exception:
    _pp603_os = None
    _pp603_sys = None
    _pp603_inspect = None
    _pp603_time = None

def _pp603_swallow(e, tag="pp603", ctx=None):
    try:
        if "_pp200_swallow" in globals():
            _pp200_heal(e, tag=tag, ctx=ctx)  # type: ignore
            return
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    try:
        if _pp603_sys is not None:
            _pp603_sys.stderr.write(f"[{tag}] {type(e).__name__}: {e}\n")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

def _pp603_is_risk_gene(name: str) -> bool:
    n = (name or "").lower()
    risk_kw = ("risk", "veto", "stress", "panic", "crash", "drawdown", "stop", "kill",
               "black", "swan", "vol", "vola", "liquid", "margin", "latency", "slippage",
               "anomaly", "fraud", "sanction", "circuit", "guard", "throttle")
    if not any(k in n for k in risk_kw):
        return False
    trade_kw = ("order", "buy", "sell", "trade", "execute", "position", "open_", "close_", "market_", "limit_")
    return not any(k in n for k in trade_kw)

def _pp603_safe_call(fn, payload: dict, self_obj=None):
    if fn is None or _pp603_inspect is None:
        return None
    try:
        sig = _pp603_inspect.signature(fn)
        kwargs = {}
        pl = payload or {}
        for pname, p in sig.parameters.items():
            if pname in ("payload", "ctx", "context", "state"):
                kwargs[pname] = pl
            elif pname in ("symbol", "sym", "pair", "s"):
                kwargs[pname] = pl.get("symbol") or pl.get("sym") or pl.get("pair") or pl.get("s")
            elif pname in ("price", "last_price", "p"):
                kwargs[pname] = pl.get("price") or pl.get("last_price") or pl.get("p")
            elif pname in ("bot", "engine"):
                if self_obj is not None:
                    kwargs[pname] = self_obj
            elif pname in ("now", "ts", "timestamp"):
                kwargs[pname] = pl.get("ts") or pl.get("timestamp") or (_pp603__pp920_time.time() if _pp603_time else None)
        for pname, p in sig.parameters.items():
            if p.default is _pp603_inspect._empty and pname not in kwargs:
                return None
        return fn(**kwargs)
    except Exception as e:
        _pp603_swallow(e, tag="pp603_safe_call", ctx={"fn": getattr(fn, "__name__", "<?>")})
        return None

class _PP603GeneRegistry:
    def __init__(self, g=None):
        self._g = g if isinstance(g, dict) else globals()
        self._risk_genes = []
        self._all = []
        self._index()
    def _index(self):
        try:
            for k, v in (self._g or {}).items():
                if k.startswith("_"):
                    continue
                if callable(v):
                    self._all.append((k, v))
                    if _pp603_is_risk_gene(k):
                        self._risk_genes.append((k, v))
        except Exception as e:
            _pp603_swallow(e, tag="pp603_index")
    def risk_hints(self, payload: dict, self_obj=None, max_calls: int = 24):
        hints = []
        calls = 0
        for name, fn in self._risk_genes:
            if calls >= int(max_calls or 0):
                break
            calls += 1
            res = _pp603_safe_call(fn, payload=payload or {}, self_obj=self_obj)
            try:
                if res is None:
                    continue
                if isinstance(res, (tuple, list)) and res:
                    reason = str(res[-1])
                    flag = res[0]
                    if bool(flag) and reason.strip():
                        hints.append((name, reason[:180]))
                else:
                    r = str(res).strip()
                    if r and r.lower() not in ("ok", "none", "0", "false"):
                        hints.append((name, r[:180]))
            except Exception:
                continue
        return hints

try:
    _pp603_GENE_REGISTRY = _PP603GeneRegistry(globals())
except Exception as e:
    _pp603_swallow(e, tag="pp603_registry_ctor")
    _pp603_GENE_REGISTRY = None

# Attach to UniversalArsenal (visibility)
try:
    if "UniversalArsenal" in globals():
        def _pp603_gene_registry(self):
            gr = getattr(self, "_pp603_gene_registry_obj", None)
            if gr is None:
                gr = _pp603_GENE_REGISTRY
                try:
                    setattr(self, "_pp603_gene_registry_obj", gr)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
            return gr
        UniversalArsenal.gene_registry = _pp603_gene_registry  # type: ignore
except Exception as e:
    _pp603_swallow(e, tag="pp603_ua_attach")

# Hook SovereignVetoCouncil (ruthless shrink on any orphan risk hint)
try:
    if "SovereignVetoCouncil" in globals():
        _pp603_prev = getattr(SovereignVetoCouncil, "min_size_multiplier", None)
        def _pp603_min_size_multiplier(self, sym: str, payload: dict):
            try:
                if callable(_pp603_prev):
                    mult, rsn = _pp603_prev(self, sym, payload)  # type: ignore
                    try:
                        if float(mult) < 1.0:
                            return float(mult), str(rsn)
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
            except Exception as e:
                _pp603_swallow(e, tag="pp603_prev_min_mult")
            try:
                min_mult = 0.05
                try:
                    if _pp603_os is not None:
                        min_mult = float(_pp603_os.getenv("PP603_MIN_SIZE_MULT", _pp603_os.getenv("PP602_MIN_SIZE_MULT", "0.03")) or 0.05)
                except Exception:
                    min_mult = 0.05
                min_mult = float(max(0.0, min(1.0, min_mult)))
                hints = []
                gr = _pp603_GENE_REGISTRY
                if gr is not None:
                    hints = gr.risk_hints(payload or {}, self_obj=getattr(self, "bot", None) or self,
                                         max_calls=int(_pp603_os.getenv("PP603_RISKGENE_CALLS", "24") or 24) if _pp603_os else 24)
                if hints:
                    return min_mult, f"pp603_risk:{hints[0][0]}:{hints[0][1]}"
            except Exception as e:
                _pp603_swallow(e, tag="pp603_min_mult_logic")
            return 1.0, "ok"
        SovereignVetoCouncil.min_size_multiplier = _pp603_min_size_multiplier  # type: ignore
except Exception as e:
    _pp603_swallow(e, tag="pp603_veto_patch")

# Version seal
try:
    if _pp603_os is not None:
        _pp603_VERSION = "v603"
        if str(_pp603_os.environ.get("PP_VERSION", "")).strip().lower() in ("", "v400", "v600", "v601", "v602"):
            _pp603_os.environ["PP_VERSION"] = _pp603_VERSION
except Exception as e:
    _pp603_swallow(e, tag="pp603_version")

