def _pp700_is_pp_gene_name(name: str) -> bool:
    try:
        return bool(_pp700__pp920_re.match(r"^_pp\d{2,4}_", str(name or "")))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False

class _PP700GeneRegistry(_PP603GeneRegistry):
    """
    v700 hardened registry:
    - indexes public genes + ALL _ppXXX_ genes (including underscore names)
    - keeps a verifiable legacy manifest (parisa600.py block digests)
    """
    def __init__(self, g=None):
        self._reference = _PP700_V600_REFERENCE
        super().__init__(g)

    def _index(self):
        try:
            self._all = []
            self._risk_genes = []
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        try:
            for k, v in (self._g or {}).items():
                try:
                    # include public symbols
                    if not str(k).startswith("_"):
                        if callable(v):
                            self._all.append((k, v))
                            if _pp603_is_risk_gene(k):
                                self._risk_genes.append((k, v))
                        continue

                    # include legacy pp-genes (underscore names)
                    if _pp700_is_pp_gene_name(k) and callable(v):
                        self._all.append((k, v))
                        if _pp603_is_risk_gene(k):
                            self._risk_genes.append((k, v))
                except Exception:
                    continue
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    def reference_manifest(self) -> dict:
        return dict(self._reference or {})

    def audit_summary(self) -> dict:
        try:
            return {
                "total_indexed_genes": int(len(self._all or [])),
                "risk_genes": int(len(self._risk_genes or [])),
                "v600_ref_lines": int((self._reference or {}).get("lines", 0) or 0),
                "v600_ref_blocks": int(len((self._reference or {}).get("blocks", []) or [])),
                "v600_ref_sha256": str((self._reference or {}).get("sha256", ""))[:16] + "...",
            }
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return {"total_indexed_genes": 0, "risk_genes": 0}

# Replace the backbone registry with the hardened one (no deletion, only upgrade).
try:
    _pp603_GENE_REGISTRY = _PP700GeneRegistry(globals())
except Exception as _pp700_e:
    try:
        _pp603_swallow(_pp700_e, tag="pp700_registry_ctor")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

# -------- Iron Veto (no os.getenv dependency) --------
try:
    if "SovereignVetoCouncil" in globals() and hasattr(SovereignVetoCouncil, "__dict__"):
        # Fixed, internal, "iron" constants (do not read env)
        setattr(SovereignVetoCouncil, "IRON_MIN_SIZE_MULTIPLIER", float(0.02))
        setattr(SovereignVetoCouncil, "IRON_CRITICAL_MIN_SIZE_MULTIPLIER", float(0.01))

        def _pp700_min_size_multiplier(self, sym: str, payload: dict):
            # 1) Respect any prior hard reduction if it exists and is < 1.0
            try:
                prev = getattr(SovereignVetoCouncil, "_pp700_prev_min_size_multiplier", None)
                if callable(prev):
                    pm, pr = prev(self, sym, payload)
                    try:
                        if float(pm) < 1.0:
                            return float(pm), str(pr)
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
            except Exception as _pp700_e:
                try:
                    _pp603_swallow(_pp700_e, tag="pp700_prev_min_mult")
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

            # 2) Query the hardened registry
            gr = None
            try:
                # prefer attached arsenal registry
                if hasattr(self, "bot") and getattr(self, "bot", None) is not None:
                    ar = getattr(self.bot, "arsenal", None)
                    if ar is not None and hasattr(ar, "gene_registry"):
                        gr = ar.gene_registry()
            except Exception:
                gr = None
            try:
                if gr is None:
                    gr = globals().get("_pp603_GENE_REGISTRY")
            except Exception:
                gr = None

            hints = []
            try:
                if gr is not None and hasattr(gr, "analyze_risk"):
                    hints = gr.analyze_risk(payload or {}, max_genes=60) or []
            except Exception as _pp700_e:
                try:
                    _pp603_swallow(_pp700_e, tag="pp700_analyze_risk")
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

            if hints:
                # Heuristic severity (Iran market: volatility/liquidity shocks => be stricter)
                try:
                    txt = " | ".join([f"{a}:{b}" for a, b in hints[:8]])
                except Exception:
                    txt = "risk_hints"
                severity_critical = False
                try:
                    low = txt.lower()
                    if any(k in low for k in ("black", "swan", "circuit", "margin", "sanction", "fraud", "panic", "crash", "liquid")):
                        severity_critical = True
                except Exception:
                    severity_critical = False

                try:
                    base = float(getattr(SovereignVetoCouncil, "IRON_MIN_SIZE_MULTIPLIER", 0.02))
                    crit = float(getattr(SovereignVetoCouncil, "IRON_CRITICAL_MIN_SIZE_MULTIPLIER", 0.01))
                    mult = crit if severity_critical else base
                except Exception:
                    mult = 0.02
                return float(max(0.0, min(1.0, mult))), "IRON_VETO:" + str(txt)[:220]

            return 1.0, "ok"

        # Preserve the old patched function reference (for audit) without using env.
        try:
            setattr(SovereignVetoCouncil, "_pp700_prev_min_size_multiplier", getattr(SovereignVetoCouncil, "min_size_multiplier", None))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        SovereignVetoCouncil.min_size_multiplier = _pp700_min_size_multiplier  # type: ignore

except Exception as _pp700_e:
    try:
        _pp603_swallow(_pp700_e, tag="pp700_veto_patch")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

# -------- Modular Unity (pp200..pp606 in one class-based structure) --------
class PP700Group:
    __slots__ = ("pp", "_ns")
    def __init__(self, pp: int, ns: dict):
        self.pp = int(pp)
        self._ns = ns if isinstance(ns, dict) else globals()
    def __getattr__(self, name: str):
        key = f"_pp{self.pp}_{name}"
        if key in self._ns and callable(self._ns.get(key)):
            return self._ns[key]
        # allow direct raw name access as fallback
        raw = f"_pp{self.pp}_" + str(name)
        if raw in self._ns and callable(self._ns.get(raw)):
            return self._ns[raw]
        raise AttributeError(name)

class PP700Unified:
    """
    Unified entry point:
      hub.pp200.<fn>(...)
      hub.pp250.<fn>(...)
      ...
      hub.pp606.<fn>(...)
    """
    def __init__(self, ns=None):
        self._ns = ns if isinstance(ns, dict) else globals()
    def __getattr__(self, item: str):
        m = _pp700__pp920_re.match(r"^pp(\d{3})$", str(item or ""))
        if m:
            n = int(m.group(1))
            if 200 <= n <= 606:
                return PP700Group(n, self._ns)
        raise AttributeError(item)

# Expose a singleton hub (does not replace existing functions; only unifies access).
try:
    PP700 = PP700Unified(globals())
except Exception:
    PP700 = None

# Attach hub to UniversalArsenal and LegacyPower (visibility + cleanliness)
try:
    if "UniversalArsenal" in globals():
        UniversalArsenal.pp700 = lambda self: PP700  # type: ignore
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


