# ---- Safety Entry sizing floor (prevents < MIN_NOTIONAL_IRT) ----
try:
    _pp808_final__orig_dyn = CognitiveCoreLegacy.dynamic_sizing

    def _pp808_final_dynamic_sizing(self, cash: float, base_cap: float, confidence: float) -> float:
        out = float(_pp808_final__orig_dyn(self, cash, base_cap, confidence) or 0.0)
        try:
            bot = getattr(self, 'bot', None)
            now = float(_pp808__pp920_time.time()) if _pp808_time is not None else 0.0
            until = float(getattr(bot, '_pp707_safety_entry_until', 0.0) or 0.0)
            if bot is not None and until >= now:
                try:
                    mn = float(getattr(bot, 'min_notional_irt', 0.0) or 0.0)
                except Exception:
                    mn = 0.0
                if mn <= 0.0:
                    try:
                        mn = float((_pp808_os.getenv('MIN_NOTIONAL_IRT', '10000') if _pp808_os else '10000') or 10000)
                    except Exception:
                        mn = 10000.0

                # default cap fraction slightly higher than PP707 (so floor can pass)
                try:
                    frac = float((_pp808_os.getenv('PP808_SAFETY_CAP_FRAC', '0.008') if _pp808_os else '0.008') or 0.008)
                except Exception:
                    frac = 0.008
                frac = max(0.001, min(float(frac), 0.05))

                try:
                    mm = float((_pp808_os.getenv('PP705_MICRO_STEP_MULT', '1.03') if _pp808_os else '1.03') or 1.03)
                except Exception:
                    mm = 1.03

                floor = float(mn) * float(mm)
                cap = max(float(cash) * float(frac), float(floor)) if float(cash) > 0.0 else float(floor)

                out = min(float(out), float(cap))
                out = max(float(out), float(floor))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return float(max(0.0, out))

    CognitiveCoreLegacy.dynamic_sizing = _pp808_final_dynamic_sizing
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


