            if _pp808_os is not None and not str(_pp808_os.getenv('USDT_SANCTUARY_COOLDOWN_SEC', '') or '').strip():
                _pp808_os.environ['USDT_SANCTUARY_COOLDOWN_SEC'] = '2.0'
