try:
    from collections import deque as _pp703_deque
except Exception:
    _pp703_deque = None


def _pp703_now() -> float:
    try:
        import time as _t
        return float(_t.time())
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
