def _pp703_init_bot_counters(bot):
    try:
        if bot is None:
            return
        if not hasattr(bot, '_pp703_ai_rescues'):
            bot._pp703_ai_rescues = 0
        if not hasattr(bot, '_pp703_autotune_hits'):
            bot._pp703_autotune_hits = 0
        if not hasattr(bot, '_pp703_veto_log'):
            bot._pp703_veto_log = _pp703_deque(maxlen=2400) if _pp703_deque is not None else []
        if not hasattr(bot, '_pp703_buy_veto_events'):
            bot._pp703_buy_veto_events = _pp703_deque(maxlen=24) if _pp703_deque is not None else []
        if not hasattr(bot, '_pp703_last_autotune_cycle'):
            bot._pp703_last_autotune_cycle = -1
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return


def _pp703_extract_mid(payload, bot, sym: str) -> float:
    # payload-first
    try:
        if isinstance(payload, dict):
            for k in ('mid', 'price', 'last', 'last_price', 'lastPrice', 'close'):
                if k in payload and payload.get(k) is not None:
                    try:
                        v = float(payload.get(k) or 0.0)
                        if v > 0.0:
                            return v
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
            md = payload.get('meta') or payload.get('m')
            if isinstance(md, dict):
                for k in ('mid', 'price', 'last_price'):
                    if k in md:
                        try:
                            v = float(md.get(k) or 0.0)
                            if v > 0.0:
                                return v
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    # dashboard price maps
    try:
        mp = getattr(bot, '_dash_symbol_px_map', None) or getattr(bot, '_dash_price_map', None) or {}
        v = float((mp or {}).get(str(sym).upper(), 0.0) or 0.0)
        if v > 0.0:
            return v
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    # USDT rate if this is USDTIRT
    try:
        if str(sym).upper() == 'USDTIRT':
            v = float(getattr(bot, '_dash_usdt_rate', 0.0) or 0.0)
            if v > 0.0:
                return v
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return 0.0


def _pp703_identify_blocker_gene(payload, proposed: str = 'BUY') -> str:
    """Best-effort: pick the most influential non-aligned gene as 'blocker'."""
    try:
        if not isinstance(payload, dict):
            return 'UNKNOWN'
        details = payload.get('details')
        if not isinstance(details, list) or not details:
            return 'UNKNOWN'
        prop = str(proposed or '').upper().strip()
        best = None
        for rec in details:
            try:
                if not isinstance(rec, (list, tuple)) or len(rec) < 4:
                    continue
                name = str(rec[0] or 'GENE')
                vote = str(rec[1] or 'HOLD').upper().strip()
                conf = float(rec[2] or 0.0)
                w = float(rec[3] or 0.0)
                eff = abs(conf) * max(0.0, w)
                # treat non-matching vote as blocking
                if prop == 'BUY' and vote != 'BUY':
                    cand = (eff, name)
                elif prop == 'SELL' and vote != 'SELL':
                    cand = (eff, name)
                else:
                    continue
                if best is None or cand[0] > best[0]:
                    best = cand
            except Exception:
                continue
        if best is not None:
            return str(best[1])
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return 'UNKNOWN'


def _pp703_veto_top_gene(bot, window_sec: float = 3600.0):
    """Return (gene, count) for the last window."""
    try:
        lg = getattr(bot, '_pp703_veto_log', None)
        if not lg:
            return ('-', 0)
        now = _pp703_now()
        counts = {}
        for item in list(lg):
            try:
                ts, gene = item[0], item[1]
                if (now - float(ts)) > float(window_sec):
                    continue
                g = str(gene or 'UNKNOWN')
                counts[g] = counts.get(g, 0) + 1
            except Exception:
                continue
        if not counts:
            return ('-', 0)
        gene = max(counts.items(), key=lambda kv: kv[1])[0]
        return (gene, int(counts.get(gene, 0)))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return ('-', 0)


def _pp703_maybe_autotune(bot, bridge, sym: str):
    """If 3 consecutive cycles had BUY veto and price rose, relax blocker gene weight by 10%."""
    try:
        evq = getattr(bot, '_pp703_buy_veto_events', None)
        if not evq or len(evq) < 3:
            return
        # consider last 3 events
        e3 = list(evq)[-3:]
        (c1, s1, p1, g1) = e3[0]
        (c2, s2, p2, g2) = e3[1]
        (c3, s3, p3, g3) = e3[2]
        try:
            c1 = int(c1); c2 = int(c2); c3 = int(c3)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return
        if str(s1) != str(s2) or str(s2) != str(s3):
            return
        if str(s3).upper() != str(sym).upper():
            return
        if (c2 != c1 + 1) or (c3 != c2 + 1):
            return
        try:
            p1 = float(p1); p2 = float(p2); p3 = float(p3)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return
        if p1 <= 0.0 or p3 <= 0.0:
            return
        if not (p3 > p1):
            return
        # prevent multiple tunes in same cycle
        if int(getattr(bot, '_pp703_last_autotune_cycle', -1) or -1) == c3:
            return
        gene = str(g3 or 'UNKNOWN')
        if gene in ('UNKNOWN', '-', 'FIRST_LAW', 'NO_CONSENSUS'):
            return
        # adjust weight
        wmap = getattr(bridge, 'weights', None)
        if not isinstance(wmap, dict):
            return
        if gene not in wmap:
            return
        old = float(wmap.get(gene) or 0.0)
        if old <= 0.0:
            return
        new = max(0.01, min(1.0, old * 0.90))
        wmap[gene] = new
        try:
            bot._pp703_last_autotune_cycle = int(c3)
            bot._pp703_autotune_hits = int(getattr(bot, '_pp703_autotune_hits', 0) or 0) + 1
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        # best-effort event
        try:
            ev = getattr(bot, '_events', None)
            if isinstance(ev, list):
                ev.append(f"PP703 Auto-Tune: {gene} weight {old:.3f}->{new:.3f} (BUY veto x3 while price↑)")
                if len(ev) > 200:
                    del ev[:-200]
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return


