        _infl_max = max(18, min(80, _infl_max))
        _infl_s = str(infl_line)
        if len(_infl_s) > _infl_max:
            _infl_s = _infl_s[:_infl_max-1] + '…'
        mini.add_row('INFLATION', _infl_s)

        mini_panel = Panel(mini, title='DZH-BAN', box=box.SQUARE, style='white on black')

        wrap = Table.grid(expand=True)
        wrap.add_row(mini_panel)
        if base is None:
            wrap.add_row(Panel(Text('REPORTS: (base unavailable)', style='white'), title='REPORTS', box=box.SQUARE, style='white on black'))
        else:
            wrap.add_row(base)
        return wrap

