                    if str(sym or "").upper().strip() == "USDTIRT":
                        try:
                            cap = float((_pp707_os.getenv("PP707_SAFETY_MIN_MULT", "0.015") if _pp707_os is not None else "0.015") or 0.015)
                        except Exception:
                            cap = 0.015
                        cap = max(0.005, min(float(cap), 0.10))
