def _pp800__now() -> float:
    try:
        return float(_pp800__pp920_time.time()) if _pp800_time is not None else 0.0
    except Exception:
        try:
            import time as _t
            return float(_t.time())
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0


def _pp800__env_float(name: str, default: float) -> float:
    try:
        if _pp800_os is None:
            return float(default)
        v = (_pp800_os.getenv(str(name), "") or "").strip()
        if not v:
            return float(default)
        return float(v)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(default)


def _pp800__lr_slope(points, window_sec: float):
    # Linear regression slope (price per second) over points=[(ts, price), ...] within window_sec.
    # Returns: (slope_per_sec, npoints)
    try:
        w = float(window_sec or 0.0)
    except Exception:
        w = 0.0
    if w <= 1.0:
        return 0.0, 0
    try:
        pts = [(float(t), float(p)) for (t, p) in (points or []) if t and p]
    except Exception:
        pts = []
    if not pts:
        return 0.0, 0
    # keep only last window
    try:
        t1 = float(pts[-1][0])
    except Exception:
        t1 = 0.0
    if t1 <= 0.0:
        return 0.0, 0
    t0 = t1 - w
    pts = [(t, p) for (t, p) in pts if t >= t0]
    if len(pts) < 3:
        return 0.0, len(pts)
    # Normalize time to reduce numeric issues
    x = []
    y = []
    for (t, p) in pts:
        x.append(float(t - t0))
        y.append(float(p))
    n = float(len(x))
    try:
        mx = sum(x) / n
        my = sum(y) / n
        num = 0.0
        den = 0.0
        for i in range(len(x)):
            dx = x[i] - mx
            num += dx * (y[i] - my)
            den += dx * dx
        if den <= 0.0:
            return 0.0, len(pts)
        return float(num / den), len(pts)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0, len(pts)


def _pp800__rsi_from_prices(prices, period: int = 14) -> float:
    try:
        if "_pp145_rsi" in globals() and callable(globals()["_pp145_rsi"]):
            return float(globals()["_pp145_rsi"](list(prices or []), int(period or 14)))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    # fallback
    try:
        p = int(period or 14)
    except Exception:
        p = 14
    if p <= 1:
        p = 14
    try:
        arr = [float(x) for x in (prices or []) if x is not None]
    except Exception:
        arr = []
    if len(arr) < (p + 1):
        return 50.0
    gains = 0.0
    losses = 0.0
    for i in range(-p, 0):
        d = float(arr[i] - arr[i - 1])
        if d >= 0:
            gains += d
        else:
            losses -= d
    if losses <= 1e-12:
        return 100.0
    rs = gains / losses
    return float(100.0 - (100.0 / (1.0 + rs)))


def _pp800_cancel_open_orders(bot, reason: str = "phoenix_shadow_guard"):
    # Cancel all currently tracked open orders (best-effort).
    # Only acts in live non-dry mode.
    try:
        if not getattr(bot, "live", False) or getattr(bot, "dry", True):
            return 0
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0

    canceled = 0
    try:
        apis = getattr(bot, "apis", {}) or {}
        states = getattr(bot, "states", {}) or {}
    except Exception:
        apis = {}
        states = {}

    for wname, api in (apis or {}).items():
        try:
            st = (states or {}).get(wname)
        except Exception:
            st = None
        ps = {}
        try:
            ps = getattr(st, "per_symbol", {}) or {}
        except Exception:
            ps = {}
        for sym, symst in (ps or {}).items():
            try:
                ids = list(getattr(symst, "open_order_ids", set()) or [])
            except Exception:
                ids = []
            for oid in ids:
                try:
                    bot._cancel_order(api, str(wname), str(sym), int(oid), str(reason))
                    canceled += 1
                except Exception:
                    continue
    try:
        setattr(bot, "_pp800_canceled_orders", int(getattr(bot, "_pp800_canceled_orders", 0) or 0) + int(canceled))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return int(canceled)


def _pp800_phoenix_update(bot, force: bool = False) -> dict:
    # Computes Phoenix prediction and writes:
    #   bot._phoenix_target (float)
    #   bot._phoenix_pred_dir (str: BULL/BEAR/FLAT)
    #   bot._phoenix_conf (float percent 0..100)
    #   bot._phoenix_instinct (bool)
    #   bot._pp800_shadow_guard_until (float ts)
    # Returns a dict with the same info (safe, non-secret).
    now = _pp800__now()
    try:
        last = float(getattr(bot, "_pp800_phoenix_last_ts", 0.0) or 0.0)
    except Exception:
        last = 0.0
    # throttle
    if (not force) and last > 0 and (now - last) < 0.5:
        try:
            return dict(getattr(bot, "_pp800_phoenix_cache", {}) or {})
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return {}

    out = {"target": 0.0, "dir": "FLAT", "conf": 0.0, "instinct": False, "shadow_guard": False, "shadow_until": 0.0,
           "pct": 0.0, "rsi": 50.0, "s1": 0.0, "s5": 0.0, "s15": 0.0, "n1": 0, "n5": 0, "n15": 0}

    try:
        samp = getattr(bot, "_usdt_rate_samples", None)
        pts = list(samp or [])
    except Exception:
        pts = []
    # Need at least a few points
    # PP912: Populate USDT rate samples (REAL). Without this, Phoenix stays FLAT 0% / RSI 50 forever,
    # and DZH-BAN shows misleading FLAT+NO_EDGE even in active markets.
    try:
        _u = float(_pp9001__usdt_rate_guard(bot) or 0.0)
        if _u > 0.0:
            try:
                from collections import deque as _pp912_deque
            except Exception:
                _pp912_deque = None
            try:
                if (not hasattr(bot, "_usdt_rate_samples")) or (getattr(bot, "_usdt_rate_samples", None) is None):
                    bot._usdt_rate_samples = (_pp912_deque(maxlen=1200) if _pp912_deque is not None else [])
            except Exception:
                pass
            try:
                samp2 = getattr(bot, "_usdt_rate_samples", None)
                if samp2 is not None:
                    try:
                        # prefer append for deque/list
                        if hasattr(samp2, "append"):
                            samp2.append((float(now), float(_u)))
                    except Exception:
                        pass
            except Exception:
                pass
            try:
                pts = list(getattr(bot, "_usdt_rate_samples", []) or [])
            except Exception:
                pass
    except Exception:
        pass
    # Need at least a few points
    if len(pts) < 4:
        try:
            setattr(bot, "_pp800_phoenix_last_ts", now)
            setattr(bot, "_pp800_phoenix_cache", out)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return out

    # Current price
    try:
        cur = float(getattr(bot, "_dash_usdt_rate", 0.0) or 0.0)
    except Exception:
        cur = 0.0
    if cur <= 0.0:
        try:
            cur = float(pts[-1][1])
        except Exception:
            cur = 0.0
    if cur <= 0.0:
        try:
            setattr(bot, "_pp800_phoenix_last_ts", now)
            setattr(bot, "_pp800_phoenix_cache", out)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return out

    s1, n1 = _pp800__lr_slope(pts, 60.0)
    s5, n5 = _pp800__lr_slope(pts, 300.0)
    s15, n15 = _pp800__lr_slope(pts, 900.0)
    out["s1"], out["s5"], out["s15"] = float(s1), float(s5), float(s15)
    out["n1"], out["n5"], out["n15"] = int(n1), int(n5), int(n15)

    # Base target: 5m regression
    try:
        target = float(cur + (s5 * 300.0))
    except Exception:
        target = float(cur)

    # Cross-timeframe reinforcement
    try:
        if (s1 >= 0 and s5 >= 0) or (s1 <= 0 and s5 <= 0):
            target += float(0.25 * s1 * 300.0)
        if (s15 >= 0 and s5 >= 0) or (s15 <= 0 and s5 <= 0):
            target += float(0.10 * s15 * 300.0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Sanity clamps (avoid absurd targets)
    try:
        if target <= 0.0:
            target = float(cur)
        # clamp to ±10% in 5m hard safety
        lo = float(cur * 0.90)
        hi = float(cur * 1.10)
        if target < lo:
            target = lo
        if target > hi:
            target = hi
    except Exception:
        target = float(cur)

    pct = 0.0
    try:
        pct = (float(target) / float(cur)) - 1.0
    except Exception:
        pct = 0.0
    out["pct"] = float(pct)

    # Direction
    if pct > 0.001:
        d = "BULL"
    elif pct < -0.001:
        d = "BEAR"
    else:
        d = "FLAT"

    # Confidence heuristic: agreement across slopes + magnitude
    try:
        sign = lambda x: 1 if x > 0 else (-1 if x < 0 else 0)
        a = [sign(s1), sign(s5), sign(s15)]
        agree = 0
        if a[1] != 0 and a[0] == a[1]:
            agree += 1
        if a[1] != 0 and a[2] == a[1]:
            agree += 1
        base = 0.25 + 0.25 * agree  # 0.25..0.75
        mag = min(1.0, abs(pct) / 0.01)  # 1% => 1.0
        conf = 100.0 * base * (0.50 + 0.50 * mag)
        conf = max(5.0, min(99.0, float(conf)))
    except Exception:
        conf = 20.0

    # RSI on recent points (use last up to 300 samples)
    try:
        prices = [float(p) for (_, p) in pts[-300:]]
    except Exception:
        prices = []
    rsi = _pp800__rsi_from_prices(prices, period=14)
    out["rsi"] = float(rsi)

    # Instinct thresholds (ENV overridable)
    instinct_pct = _pp800__env_float("PP800_INSTINCT_PCT", 0.008)
    oversold = _pp800__env_float("PP800_RSI_OVERSOLD", float(getattr(bot, "_phoenix_rsi_oversold", 30.0) or 30.0))

    instinct = False
    try:
        instinct = (pct >= float(instinct_pct)) and (float(rsi) <= float(oversold))
    except Exception:
        instinct = False

    # v711 Inflation Hunter: if toman devaluation speed is extreme, go ABSOLUTE (ignore BUY vetoes for USDT)
    try:
        win = float(_pp800__env_float("USDT_SPIKE_WINDOW_SEC", 300.0) or 300.0)
    except Exception:
        win = 300.0
    try:
        spike_pct = float(_pp800__env_float("USDT_SPIKE_PCT", 0.012) or 0.012)
    except Exception:
        spike_pct = 0.012
    try:
        thr_1m = float(spike_pct) * (60.0 / max(60.0, float(win)))
    except Exception:
        thr_1m = 0.0024
    try:
        speed_1m = (float(s1) * 60.0) / float(cur) if float(cur) > 0.0 else 0.0
    except Exception:
        speed_1m = 0.0
    try:
        if float(speed_1m) > 0.0 and float(speed_1m) >= float(thr_1m):
            instinct = True
            try:
                setattr(bot, "_pp711_absolute_aggression", True)
                setattr(bot, "_pp711_absolute_aggr_until", float(now + max(30.0, float(win))))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
        else:
            try:
                setattr(bot, "_pp711_absolute_aggression", False)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
    except Exception:
        try:
            setattr(bot, "_pp711_absolute_aggression", False)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # Anti-Flash Crash / anomaly: prediction diverges too far from current (model instability)
    shadow_trigger = False
    shadow_pct = _pp800__env_float("PP800_SHADOW_PCT", 0.03)
    try:
        shadow_trigger = abs(float(pct)) >= float(shadow_pct)
    except Exception:
        shadow_trigger = False

    # Maintain shadow guard for some time once triggered
    try:
        until = float(getattr(bot, "_pp800_shadow_guard_until", 0.0) or 0.0)
    except Exception:
        until = 0.0
    if shadow_trigger:
        guard_sec = _pp800__env_float("PP800_SHADOW_SEC", float(getattr(bot, "_pp800_shadow_guard_sec", 180.0) or 180.0))
        until = max(until, now + max(30.0, float(guard_sec)))
        try:
            setattr(bot, "_pp800_shadow_guard_until", float(until))
            setattr(bot, "_pp800_shadow_guard_hits", int(getattr(bot, "_pp800_shadow_guard_hits", 0) or 0) + 1)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        # Best-effort cancel open orders to avoid cascading risk
        try:
            _pp800_cancel_open_orders(bot, reason=f"phoenix_shadow_guard|pct={pct:+.3f}")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # Apply active shadow guard status
    try:
        shadow_active = (until > 0 and now < until)
    except Exception:
        shadow_active = False

    out["target"] = float(target)
    out["dir"] = str(d)
    out["conf"] = float(conf)
    out["instinct"] = bool(instinct)
    out["shadow_guard"] = bool(shadow_active)
    out["shadow_until"] = float(until)

    try:
        setattr(bot, "_phoenix_target", float(target))
        setattr(bot, "_phoenix_pred_dir", str(d))
        setattr(bot, "_phoenix_conf", float(conf))
        setattr(bot, "_phoenix_instinct", bool(instinct))
        setattr(bot, "_pp800_phoenix_last_ts", float(now))
        setattr(bot, "_pp800_phoenix_cache", dict(out))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    return out


# --- Patch 1: VetoCouncil: instinct threshold + shadow guard veto for BUY (non-breaking) ---
try:
    if "SovereignVetoCouncil" in globals():
        _pp800__orig_should_veto = getattr(SovereignVetoCouncil, "should_veto", None)

        if callable(_pp800__orig_should_veto):
            def _pp800_should_veto(self, sym: str, proposed: str, payload: dict):
                bot = getattr(self, "bot", None)
                try:
                    if bot is not None:
                        _pp800_phoenix_update(bot)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

                # v711: USDT escape hatch — never veto BUY USDTIRT (Sanctuary / Inflation Hunter)
                try:
                    if bot is not None and str(sym).upper() == "USDTIRT" and str(proposed or "").upper() == "BUY":
                        return False, "usdt_escape"
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

                # Shadow Guard: block BUYs during anomaly, allow SELL exits
                try:
                    if bot is not None and str(proposed or "").upper() == "BUY":
                        now = _pp800__now()
                        until = float(getattr(bot, "_pp800_shadow_guard_until", 0.0) or 0.0)
                        if until > 0 and now < until and str(sym).upper() != 'USDTIRT':
                            return True, f"shadow_guard:{int(until-now)}s"
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

                veto, reason = _pp800__orig_should_veto(self, sym, proposed, payload)

                # Instinct Mode: relax consensus threshold for Step-1 BUY to 70%
                try:
                    if bot is None:
                        return veto, reason
                    if str(proposed or "").upper() != "BUY":
                        return veto, reason
                    if not bool(getattr(bot, "_phoenix_instinct", False)):
                        return veto, reason

                    # Step-1 heuristic: no position + no open orders for this symbol in the acting wallet
                    w = ""
                    try:
                        if isinstance(payload, dict):
                            w = str(payload.get("wallet") or payload.get("wname") or payload.get("account") or "")
                    except Exception:
                        w = ""
                    st = None
                    try:
                        st = (getattr(bot, "states", {}) or {}).get(w) if w else None
                        if st is None:
                            st = next(iter((getattr(bot, "states", {}) or {}).values()), None)
                    except Exception:
                        st = None
                    symst = None
                    try:
                        symst = (getattr(st, "per_symbol", {}) or {}).get(str(sym))
                    except Exception:
                        symst = None
                    step1 = True
                    try:
                        if symst is not None:
                            step1 = (float(getattr(symst, "pos_qty", 0.0) or 0.0) <= 0.0) and (len(getattr(symst, "open_order_ids", set()) or []) == 0)
                    except Exception:
                        step1 = True
                    if not step1:
                        return veto, reason

                    # Re-evaluate consensus with a capped threshold=0.70 when instinct is active
                    try:
                        c = float(SovereignVetoCouncil._consensus_from_payload(payload))
                    except Exception:
                        c = 0.0
                    if c >= 0.70:
                        return False, "phoenix_instinct_relaxed:{:.2f}>=0.70".format(c)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

                return veto, reason

            SovereignVetoCouncil.should_veto = _pp800_should_veto
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


