# =====================================================================================
# PP7783 ROOTFIX — Balance fetch must never collapse EQUITY to 0
# - No feature removal: preserves API circuit breakers, jitter proxy, anti-ban logic.
# - Prevents "READY lock" caused by transient wallet_balance failures.
# - Uses last-known-good per-wallet snapshot for one cycle if the private API is flaky.
# =====================================================================================
try:
    def _pp7783__find_wallet_name(bot, api_obj):
        try:
            amap = getattr(bot, 'apis', None)
            if isinstance(amap, dict):
                for k, v in amap.items():
                    if v is api_obj:
                        return str(k)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return ''

    def _pp7783__normalize_balance_map(raw):
        """
        Normalize balances to a flat {ASSET: Decimal} map (Decimal-first).
        Accepts numeric, strings (including scientific), and nested dicts like free/locked.
        """
        out = {}
        if not isinstance(raw, dict):
            return out
        for k, v in raw.items():
            try:
                kk = str(k or '').strip().upper()
                if not kk:
                    continue
                if isinstance(v, dict):
                    # common shapes: free/locked/available/total
                    try:
                        if 'total' in v:
                            out[kk] = _pp7826__to_dec(v.get('total'))
                            continue
                        if 'balance' in v:
                            out[kk] = _pp7826__to_dec(v.get('balance'))
                            continue
                        if 'available' in v:
                            out[kk] = _pp7826__to_dec(v.get('available'))
                            continue
                        if ('free' in v) or ('locked' in v):
                            out[kk] = _pp7826__to_dec(v.get('free')) + _pp7826__to_dec(v.get('locked'))
                            continue
                        # sum numeric leafs best-effort
                        s = _pp7826__to_dec("0")
                        for _vv in v.values():
                            s += _pp7826__to_dec(_vv)
                        out[kk] = s
                        continue
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                out[kk] = _pp7826__to_dec(v)
            except Exception:
                continue
        return out

    def _pp7783__split_symbol(sym: str, default_quote: str = "IRT"):
        base = ""
        quote = ""
        try:
            s = str(sym or "").upper().strip()
            s2 = s.replace("_", "/").replace("-", "/")
            if "/" in s2:
                p = [x for x in s2.split("/") if x]
                if len(p) >= 2:
                    base, quote = p[0].strip(), p[1].strip()
            else:
                q = str(default_quote or "IRT").upper().strip()
                if q and s2.endswith(q) and len(s2) > len(q):
                    base = s2[:-len(q)].strip()
                    quote = q
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return base, quote

    def _pp7783__prune_recent_orders(bot, now_ts: float, max_age_sec: float = 180.0):
        try:
            ro = getattr(bot, "_pp_recent_orders", None)
            if not isinstance(ro, list):
                return
            bot._pp_recent_orders = [x for x in ro if isinstance(x, dict) and (now_ts - float(x.get("ts", 0.0) or 0.0)) <= max_age_sec]
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    def _pp7783__orders_explain_delta(bot, wname: str, asset: str, delta_dec, now_ts: float, window_sec: float = 60.0) -> bool:
        # Heuristic: check if any recent OK order for this wallet could explain the delta direction & magnitude.
        try:
            ro = getattr(bot, "_pp_recent_orders", None)
            if not isinstance(ro, list) or not ro:
                return False
            a = str(asset or "").upper().strip()
            if not a:
                return False
            try:
                from decimal import Decimal
            except Exception:
                Decimal = None  # type: ignore
            # Coerce delta
            try:
                dlt = delta_dec
                if Decimal is not None and not isinstance(dlt, Decimal):
                    dlt = _pp7826__to_dec(dlt)
            except Exception:
                dlt = _pp7826__to_dec("0")
            # ignore tiny deltas
            try:
                if abs(dlt) <= _pp7826__to_dec("0.00000001"):
                    return True
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

            for o in ro:
                try:
                    if str(o.get("wallet", "")).strip() != str(wname):
                        continue
                    if not bool(o.get("ok", True)):
                        continue
                    ts = float(o.get("ts", 0.0) or 0.0)
                    if ts <= 0.0 or (now_ts - ts) > float(window_sec):
                        continue
                    side = str(o.get("side", "")).lower().strip()
                    base = str(o.get("base", "")).upper().strip()
                    quote = str(o.get("quote", "")).upper().strip()
                    qty = _pp7826__to_dec(o.get("qty", "0"))
                    price = _pp7826__to_dec(o.get("price", "0"))
                    expected = _pp7826__to_dec("0")
                    if a == base and qty > _pp7826__to_dec("0"):
                        expected = qty
                        # BUY -> base increases; SELL -> base decreases
                        if side == "buy" and dlt > _pp7826__to_dec("0"):
                            pass
                        elif side == "sell" and dlt < _pp7826__to_dec("0"):
                            pass
                        else:
                            continue
                        # magnitude (loose): delta within [0.15x .. 2.5x] expected
                        if abs(dlt) >= (expected * _pp7826__to_dec("0.15")) and abs(dlt) <= (expected * _pp7826__to_dec("2.50")):
                            return True
                    if a == quote and qty > _pp7826__to_dec("0") and price > _pp7826__to_dec("0"):
                        expected = qty * price
                        # BUY -> quote decreases; SELL -> quote increases
                        if side == "buy" and dlt < _pp7826__to_dec("0"):
                            pass
                        elif side == "sell" and dlt > _pp7826__to_dec("0"):
                            pass
                        else:
                            continue
                        if abs(dlt) >= (expected * _pp7826__to_dec("0.05")) and abs(dlt) <= (expected * _pp7826__to_dec("3.50")):
                            return True
                except Exception:
                    continue
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False
        return False

    def _pp7783__rational_balance_filter(bot, wname: str, cur_map: dict, now_ts: float) -> dict:
        """
        Dynamic Asset Tracking (Sync_Balances):
          - No fixed BTC/USDT numbers.
          - Keeps last verified balances per wallet in bot._last_verified_balance[wname]
          - If a sudden change is not explained by recent orders (trade history proxy), keep previous.
          - BTC special rule: if it drops >80% and no recent SELL -> treat as exchange glitch and keep previous.
        """
        try:
            from decimal import Decimal
        except Exception:
            pass

        if not hasattr(bot, "_last_verified_balance"):
            bot._last_verified_balance = {}
        lv_all = getattr(bot, "_last_verified_balance", None)
        if not isinstance(lv_all, dict):
            bot._last_verified_balance = {}
            lv_all = bot._last_verified_balance

        prev_map = {}
        try:
            if wname and isinstance(lv_all.get(wname), dict):
                prev_map = dict(lv_all.get(wname) or {})
        except Exception:
            prev_map = {}

        # ensure recent orders pruned
        _pp7783__prune_recent_orders(bot, now_ts, max_age_sec=180.0)

        # time windows
        try:
            ts_sell_map = getattr(bot, "_pp_last_sell_ts_by_wallet", None)
            last_sell = float(ts_sell_map.get(str(wname), 0.0) or 0.0) if isinstance(ts_sell_map, dict) else 0.0
        except Exception:
            last_sell = 0.0
        try:
            ts_buy_map = getattr(bot, "_pp_last_buy_ts_by_wallet", None)
            last_buy = float(ts_buy_map.get(str(wname), 0.0) or 0.0) if isinstance(ts_buy_map, dict) else 0.0
        except Exception:
            last_buy = 0.0

        def _recent(tsv: float, win: float) -> bool:
            try:
                return (tsv > 0.0) and ((now_ts - float(tsv)) <= float(win))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return False

        recent_sell = _recent(last_sell, 30.0)
        recent_buy = _recent(last_buy, 30.0)

        out = {}
        keys = set()
        try:
            keys.update([str(k).upper() for k in (cur_map or {}).keys()])
            keys.update([str(k).upper() for k in (prev_map or {}).keys()])
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        for a in keys:
            try:
                asset = str(a or "").upper().strip()
                if not asset:
                    continue
                cur = cur_map.get(asset, None)
                prev = prev_map.get(asset, None)

                curd = _pp7826__to_dec(cur) if cur is not None else _pp7826__to_dec(prev)
                prevd = _pp7826__to_dec(prev) if prev is not None else _pp7826__to_dec(curd)

                # Default accept current if no previous
                if (prev is None) and (cur is not None):
                    out[asset] = curd
                    continue
                if (cur is None) and (prev is not None):
                    out[asset] = prevd
                    continue

                # Deltas
                dlt = curd - prevd

                # BTC hard-glitch rule (only for extreme collapses)
                if asset == "BTC":
                    try:
                        if prevd > _pp7826__to_dec("0") and curd >= _pp7826__to_dec("0") and curd < (prevd * _pp7826__to_dec("0.20")):
                            if not recent_sell and (not _pp7783__orders_explain_delta(bot, wname, asset, dlt, now_ts, window_sec=60.0)):
                                out[asset] = prevd
                                continue
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                    # BTC increases can be real (buy/deposit); if absurd jump without any recent trade,
                    # require 2-cycle confirmation to avoid single-tick exchange glitches.
                    try:
                        if prevd > _pp7826__to_dec("0") and curd > (prevd * _pp7826__to_dec("5.0")) and (not recent_buy) and (not recent_sell):
                            if not _pp7783__orders_explain_delta(bot, wname, asset, dlt, now_ts, window_sec=60.0):
                                # 2-cycle confirm
                                if not hasattr(bot, "_pp_balance_candidate"):
                                    bot._pp_balance_candidate = {}
                                cand = getattr(bot, "_pp_balance_candidate", None)
                                if not isinstance(cand, dict):
                                    bot._pp_balance_candidate = {}
                                    cand = bot._pp_balance_candidate
                                ck = f"{wname}:{asset}"
                                prev_c = cand.get(ck)
                                if prev_c is not None and _pp7826__to_dec(prev_c) == curd:
                                    out[asset] = curd
                                else:
                                    cand[ck] = curd
                                    out[asset] = prevd
                                continue
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")

                # Generic sudden-change filter (all assets including USDT):
                # If change is extreme AND not explained by recent orders -> keep previous.
                try:
                    if prevd > _pp7826__to_dec("0"):
                        # relative change magnitude
                        rel = abs(dlt) / prevd if prevd != _pp7826__to_dec("0") else _pp7826__to_dec("0")
                        if rel >= _pp7826__to_dec("0.80"):
                            # If there is a recent trade that explains it, accept.
                            explained = _pp7783__orders_explain_delta(bot, wname, asset, dlt, now_ts, window_sec=90.0)
                            if asset == "USDT":
                                # quote currency: allow if recent buy/sell even if heuristic fails (fees/partial fills)
                                explained = explained or recent_buy or recent_sell
                            if not explained:
                                out[asset] = prevd
                                continue
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

                # Accept current
                out[asset] = curd
            except Exception:
                continue

        # Persist
        try:
            if wname:
                lv_all[wname] = dict(out)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return out


    # Wrap bot._balances once (idempotent)
    _pp7783__patched = False
    for _cls_name in ("PP5LiveTripleWallet", "PP5LiveTripleWalletPro", "PP5LiveTripleWalletFundGrade", "PP5LiveTripleWalletInstitutional"):
        try:
            _cls = globals().get(_cls_name)
            if _cls is None or not hasattr(_cls, '_balances'):
                continue
            if getattr(_cls, '_pp7783_bal_wrap', False):
                continue

            _orig = getattr(_cls, '_balances')

            def _balances_safe(self, api, _orig=_orig):
                import time
                try:
                    # 1) Fetch raw balances from exchange (original implementation)
                    b = _orig(self, api)

                    # 2) Normalize to Decimal map
                    b2 = _pp7783__normalize_balance_map(b)

                    # 3) Dynamic Asset Tracking (Sync_Balances) with rational filter
                    try:
                        wname = _pp7783__find_wallet_name(self, api)
                    except Exception:
                        wname = ''
                    now_ts = _pp920_time.time()
                    try:
                        b2 = _pp7783__rational_balance_filter(self, str(wname), b2, float(now_ts))
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")

                    # 4) Persist last-good snapshot for hard failures (NOT a fixed anchor)
                    try:
                        if wname:
                            if not hasattr(self, '_pp7783_last_good_bal'):
                                setattr(self, '_pp7783_last_good_bal', {})
                            lg = getattr(self, '_pp7783_last_good_bal', {})
                            if isinstance(lg, dict):
                                lg[str(wname)] = dict(b2)
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")

                    # 5) Expose Sync_Balances method for clarity / external call sites
                    try:
                        if not hasattr(self.__class__, "Sync_Balances"):
                            def _sync(self, api_obj, _orig_inner=_orig):
                                rawb = _orig_inner(self, api_obj)
                                nm = _pp7783__find_wallet_name(self, api_obj)
                                nb = _pp7783__normalize_balance_map(rawb)
                                return _pp7783__rational_balance_filter(self, str(nm), nb, _pp920_time.time())
                            setattr(self.__class__, "Sync_Balances", _sync)
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")

                    return b2
                except Exception as e:
                    # Fallback to last verified (keeps equity alive, avoids dashboard red spikes)
                    wname = _pp7783__find_wallet_name(self, api)
                    fb = None
                    try:
                        lv = getattr(self, "_last_verified_balance", None)
                        if isinstance(lv, dict) and wname and isinstance(lv.get(str(wname)), dict):
                            fb = dict(lv.get(str(wname)) or {})
                    except Exception:
                        fb = None
                    if fb is None:
                        try:
                            lg = getattr(self, '_pp7783_last_good_bal', None)
                            if isinstance(lg, dict) and wname and isinstance(lg.get(wname), dict):
                                fb = dict(lg.get(wname) or {})
                        except Exception:
                            fb = None
                    if fb is None:
                        try:
                            dc = getattr(self, '_dash_balances_cache', None)
                            if isinstance(dc, dict) and wname and isinstance(dc.get(wname), dict):
                                fb = dict(dc.get(wname) or {})
                        except Exception:
                            fb = None
                    fb = _pp7783__normalize_balance_map(fb or {})

                    # Record error only for real exceptions (not for rational-filter events)
                    try:
                        if not hasattr(self, '_dash_wallet_errors'):
                            self._dash_wallet_errors = {}
                        if isinstance(getattr(self, '_dash_wallet_errors', None), dict) and wname:
                            self._dash_wallet_errors[wname] = f"wallet_balance_fallback:{type(e).__name__}"
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                    return fb
            setattr(_cls, '_balances', _balances_safe)
            setattr(_cls, '_pp7783_bal_wrap', True)
            _pp7783__patched = True
        except Exception:
            continue
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")
