# 4) W3 RECOVERY — ensure 1M-BABYDOGE priced in IRT for EQUITY
# ============================================================

def _pp_w3_seed_babydoge() -> None:
    """Ensure price_cache includes equilibrium price for 1M-BABYDOGE, without touching holdings."""
    try:
        if os is None:
            return
        seed = float(os.getenv("BABYDOGE_SEED_IRT", "0") or 0.0)
    except Exception:
        seed = 0.0
    if seed <= 0.0:
        return
    try:
        # use existing price cache primitive if present
        if "price_cache" in globals() and isinstance(globals().get("price_cache"), dict):
            pc = globals().get("price_cache")
            rec = pc.get("1M-BABYDOGE") if isinstance(pc, dict) else None
            ok = False
            if isinstance(rec, dict):
                try:
                    ok = float(rec.get("px") or 0.0) > 0.0
                except Exception:
                    ok = False
            if not ok:
                try:
                    _pp_price_cache_set("1M-BABYDOGE", float(seed), src="W3_SEED")  # type: ignore[name-defined]
                except Exception:
                    try:
                        pc["1M-BABYDOGE"] = {"px": float(seed), "ts": float(_pp920_time.time()) if time is not None else 0.0, "src": "W3_SEED"}
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                try:
                    _pp_price_cache_save(force=False)  # type: ignore[name-defined]
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return

# Wrap price-cache load to seed once after load
try:
    _pp__orig_price_cache_load = _pp_price_cache_load  # type: ignore[name-defined]
except Exception:
    _pp__orig_price_cache_load = None

def _pp_price_cache_load_w3() -> None:
    try:
        if callable(_pp__orig_price_cache_load):
            _pp__orig_price_cache_load()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    try:
        _pp_w3_seed_babydoge()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

try:
    if _pp__orig_price_cache_load is not None:
        globals()["_pp_price_cache_load"] = _pp_price_cache_load_w3
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

