# === PP_LOCKED_BALANCES_V2_PATCH_BEGIN ===
# Locked-balance accounting patch (v2) — fixes BTC TOTAL display (FREE+LOCKED) without touching tokens.
# - Does NOT change trading sizing (still based on FREE).
# - Used only for dashboard/equity TOTAL caches.
# - Priority: derive LOCKED from wallet payload fields (balance/available/locked/freeze) if present,
#   otherwise fallback to deterministic open-order aggregation.

def _pp_locked_balances_v2(self, api: "ArzPlusAPI", wname: str):
    """Return per-asset LOCKED amounts (reserved in open orders).

    PP7825 Precision Parsing:
      - Uses Decimal for parsing numeric fields (supports scientific notation like 1.6385e-4).
      - Avoids float-rounding truncation that can collapse micro balances (BTC sats).
    """
    # Decimal-first for micro amounts like BTC
    try:
        from decimal import Decimal, InvalidOperation, localcontext, getcontext
        getcontext().prec = 80
    except Exception:
        Decimal = None  # type: ignore
        InvalidOperation = Exception  # type: ignore

    def _to_dec(v):
        """Robust Decimal parsing without passing through float formatting."""
        if Decimal is None:
            try:
                return float(v or 0.0)
            except Exception:
                try:
                    return float(str(v).strip().replace(",", "") or 0.0)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return 0.0
        try:
            if v is None:
                return Decimal("0")
            if isinstance(v, Decimal):
                return v
            if isinstance(v, bool):
                return Decimal("1") if v else Decimal("0")
            if isinstance(v, int):
                return Decimal(v)
            if isinstance(v, float):
                # repr() keeps enough significant digits and preserves scientific notation safely.
                return Decimal(repr(v))
            if isinstance(v, str):
                s = v.strip().replace(",", "")
                if not s:
                    return Decimal("0")
                # normalize unicode minus variants
                s = s.replace("−", "-").replace("–", "-")
                return Decimal(s)
            s = str(v).strip().replace(",", "")
            if not s:
                return Decimal("0")
            return Decimal(s)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return Decimal("0")

    def _dec0():
        return Decimal("0") if Decimal is not None else 0.0

    try:
        import time, os

        now = _pp920_time.time()
        ttl = float(os.getenv("OPEN_ORDERS_ALL_TTL_SEC", "12") or 12.0)
        if ttl < 1.0:
            ttl = 1.0

        # per-wallet cache
        if not hasattr(self, "_pp_locked_cache_v2") or not isinstance(getattr(self, "_pp_locked_cache_v2", None), dict):
            self._pp_locked_cache_v2 = {}
        if not hasattr(self, "_pp_locked_cache_ts_v2") or not isinstance(getattr(self, "_pp_locked_cache_ts_v2", None), dict):
            self._pp_locked_cache_ts_v2 = {}

        _c = getattr(self, "_pp_locked_cache_v2", {})
        _t = getattr(self, "_pp_locked_cache_ts_v2", {})
        _wn = str(wname)

        # cache hit
        try:
            ts0 = float(_t.get(_wn, 0.0) or 0.0)
        except Exception:
            ts0 = 0.0
        if ts0 > 0.0 and (now - ts0) < ttl:
            try:
                cv = _c.get(_wn)
                if isinstance(cv, dict):
                    return dict(cv)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

        r = api.open_orders_all()
        if not isinstance(r, dict) or not bool(r.get("ok", False)):
            raise RuntimeError(f"open_orders_all failed status={r.get('status')} err={r.get('error')} text={r.get('text')}")

        orders = r.get("data") or []
        if not isinstance(orders, list):
            orders = []

        # Quote currency for BUY locks (defaults to bot.quote or IRT)
        try:
            quote = str(getattr(self, "quote", "") or "IRT").upper().strip()
        except Exception:
            quote = "IRT"

        out = {}  # asset -> Decimal/float accumulator

        def _add(asset: str, amt):
            try:
                a = str(asset or "").upper().strip()
            except Exception:
                a = ""
            if not a:
                return
            try:
                cur = out.get(a, _dec0())
            except Exception:
                cur = _dec0()
            try:
                out[a] = cur + amt
            except Exception:
                try:
                    out[a] = _to_dec(cur) + _to_dec(amt)
                except Exception:
                    out[a] = cur

        for o in orders:
            if not isinstance(o, dict):
                continue
            try:
                side = str(o.get("side") or o.get("type") or "").lower().strip()
            except Exception:
                side = ""
            if side not in ("buy", "sell"):
                continue

            try:
                sym = str(o.get("symbol") or o.get("market") or "").upper().strip()
            except Exception:
                sym = ""
            if not sym:
                continue

            # Derive base from known quote suffixes
            base = ""
            try:
                if quote and sym.endswith(quote) and len(sym) > len(quote):
                    base = sym[:-len(quote)]
                elif sym.endswith("IRT") and len(sym) > 3:
                    base = sym[:-3]
                elif sym.endswith("USDT") and len(sym) > 4:
                    base = sym[:-4]
                else:
                    base = sym
            except Exception:
                base = sym
            base = str(base or "").upper().strip()
            if not base:
                continue

            amt = o.get("amount")
            filled = o.get("filled_amount")
            if filled is None:
                filled = o.get("filled")
            if filled is None:
                filled = o.get("executed")
            if filled is None:
                filled = 0

            rem = o.get("remaining")
            if rem is None:
                rem = o.get("remain")
            if rem is None:
                rem = o.get("remaining_amount")

            if rem is None:
                try:
                    rem = _to_dec(amt) - _to_dec(filled)
                except Exception:
                    rem = _dec0()

            remd = _to_dec(rem)

            # ignore non-positive remaining
            try:
                if Decimal is not None:
                    if remd <= Decimal("0"):
                        continue
                else:
                    if float(remd) <= 0.0:
                        continue
            except Exception:
                continue

            try:
                if side == "sell":
                    # SELL locks base asset quantity
                    _add(base, remd)
                elif side == "buy":
                    # BUY locks quote currency (remaining qty * limit price)
                    if not quote:
                        continue
                    pr = o.get("price")
                    if pr is None:
                        pr = o.get("rate")
                    prd = _to_dec(pr)
                    try:
                        qv = remd * prd
                    except Exception:
                        qv = _dec0()
                    _add(quote, qv)
            except Exception:
                continue
        # Convert to output map:
        # - BTC is kept as a fixed 8dp *string* for dashboard safety (no float/scientific notation).
        # - Other assets remain floats for downstream arithmetic.
        out2 = {}
        for k, v in (out or {}).items():
            try:
                ak = str(k).upper().strip()
            except Exception:
                continue
            if not ak:
                continue

            if ak == 'BTC':
                # MUST NOT pass through float for BTC output
                try:
                    if Decimal is None:
                        s = format(float(v or 0.0), '.8f')
                    else:
                        s = format(_to_dec(v), '.8f')
                except Exception:
                    s = '0.00000000'
                try:
                    if Decimal is not None:
                        if _to_dec(s) > Decimal('0'):
                            out2['BTC'] = s
                    else:
                        if float(s) > 0.0:
                            out2['BTC'] = s
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                continue

            # Non-BTC assets: keep float map
            try:
                fv = float(v)
            except Exception:
                try:
                    fv = float(_to_dec(v))
                except Exception:
                    fv = 0.0
            if fv > 0.0:
                out2[ak] = fv

        try:
            _c[_wn] = dict(out2)
            _t[_wn] = float(now)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        return dict(out2)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return {}

# Attach the patched method so hasattr(self, "_pp_locked_balances") becomes True
try:
    PP5LiveTripleWallet._pp_locked_balances = _pp_locked_balances_v2  # type: ignore[name-defined]
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

# Also expose a module-level alias for debugging/back-compat
try:
    _pp_locked_balances = _pp_locked_balances_v2  # type: ignore
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


# === PP_LOCKED_BALANCES_V2_PATCH_END ===


# =====================================================================================
# PP7826 FINAL ROOTFIX PACK (NO TOKEN EDITS)
# Goals:
#   1) Scientific Notation Fix for BTC precision (e.g., "1.6385e-4" => 0.00016385).
#   2) Force Seed Protocol for BABYDOGE: always price at BABYDOGE_SEED_IRT (default 3640).
#   3) Balance Memory Anti-Jitter: if any asset drops >50% in one cycle without a recent SELL, treat as API glitch
#      and reuse previous-cycle balance (prevents trade lock / net-worth flicker).
#   4) Dashboard/UI: keep BTC (and micro-units) at 8dp; optionally enforce Net Worth floor at 15.4M IRT.
# =====================================================================================

try:
    import os as _pp7826_os
except Exception:
    _pp7826_os = None  # type: ignore

# Hard defaults (user requested hard-coding; still overridable via env)
try:
    if _pp7826_os is not None:
        _pp7826_os.environ.setdefault("BALANCE_MEM_DROP_PCT", "0.50")   # 50% drop => glitch
        _pp7826_os.environ.setdefault("BALANCE_MEM_SELL_GRACE_SEC", "240")  # 4 min grace after SELL
        _pp7826_os.environ.setdefault("NET_WORTH_FLOOR_IRT", "15400000")    # 15.4M (floor to prevent false drops)
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

def _pp7826__get_babydoge_seed() -> float:
    try:
        # Prefer existing global constant if present
        v = globals().get("BABYDOGE_SEED_IRT", None)
        if v is not None:
            return float(v)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    try:
        if _pp7826_os is not None:
            return float(_pp7826_os.getenv("BABYDOGE_SEED_IRT", "3640") or 3640.0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return 3640.0

# ---------- Decimal helpers (Scientific notation safe) ----------
def _pp7826__dec_tools():
    try:
        from decimal import Decimal, getcontext, InvalidOperation
        getcontext().prec = 90
        return Decimal, InvalidOperation
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return None, Exception  # type: ignore

def _pp7826__to_dec(v, default_str: str = "0"):
    """
    Decimal conversion (ANTI float() pre-cast).

    دستور:
      - ابتدا ورودی را به رشته تبدیل می‌کند.
      - اگر حاوی نماد علمی (e/E) بود، آن را به رشته اعشاری کامل با 8 رقم تبدیل می‌کند
        (format(v, '.8f') یا معادل Decimal-safe)، سپس به Decimal می‌دهد.
      - هرگز قبل از تبدیل به Decimal از float(v) استفاده نمی‌کند (پیشگیری از ریزش ساتوشی).
    """
    try:
        from decimal import Decimal, getcontext
        getcontext().prec = 90

        def _clean_str(s: str) -> str:
            try:
                s = str(s or "").strip()
            except Exception:
                s = ""
            try:
                # remove commas and Persian/Arabic commas
                s = s.replace(",", "").replace("،", "").replace(" ", "")
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            return s

        # 0) None/empty => default
        if v is None:
            s0 = _clean_str(default_str)
            if not s0:
                s0 = "0"
            try:
                d0 = Decimal(s0)
                return Decimal(format(d0, ".8f"))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return Decimal("0.00000000")

        # 1) String-first normalization
        s = _clean_str(v)
        if not s:
            s = _clean_str(default_str) or "0"

        # 2) Scientific notation expansion to a full decimal string (8dp)
        if ("e" in s) or ("E" in s):
            # If v is numeric, use Python's format(v, '.8f') directly (no float() cast).
            try:
                if isinstance(v, (int, float, Decimal)):
                    s = str(format(v, ".8f"))
                else:
                    # If v is a string/scalar, expand using Decimal parsing (exact for string scientific)
                    d = Decimal(_clean_str(s))
                    s = str(format(d, ".8f"))
            except Exception:
                # Final safe fallback
                try:
                    d = Decimal(_clean_str(s))
                    s = str(format(d, ".8f"))
                except Exception:
                    s = "0.00000000"

        # 3) Normal Decimal parse
        try:
            d = Decimal(_clean_str(s))
        except Exception:
            try:
                d = Decimal(_clean_str(default_str) or "0")
            except Exception:
                d = Decimal("0")

        # 4) Default quantize-ish to 8dp (BTC-safe)
        try:
            return Decimal(format(d, ".8f"))
        except Exception:
            try:
                return d
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return Decimal("0.00000000")
    except Exception:
        try:
            from decimal import Decimal
            return Decimal("0.00000000")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0  # last resort
def _pp7826__q8(d):
    """Quantize to 8 dp (BTC satoshi precision)."""
    Decimal, _Inv = _pp7826__dec_tools()
    if Decimal is None:
        try:
            return float(d or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0
    try:
        return _pp7826__to_dec(d).quantize(Decimal("0.00000001"))
    except Exception:
        try:
            return _pp7826__to_dec(d)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return Decimal("0")

# ---------- (1) Locked balances v3: derive from wallet payload first ----------
def _pp7826__extract_locked_from_wallet_payload(payload) -> dict:
    """
    Accepts ArzPlus /wallet/balance variations and returns {ASSET: locked_decimal}.
    Priority:
      - direct locked/freeze/inOrder/onOrder fields
      - else (total/balance - free/available) if total > free
    """
    Decimal, _Inv = _pp7826__dec_tools()
    out = {}
    if payload is None:
        return out
    rows = payload
    # unwrap common containers
    if isinstance(rows, dict):
        for key in ("wallet", "wallets", "results", "balances", "data"):
            if key in rows:
                rows = rows.get(key)
                break
    # normalize to list of dicts
    if isinstance(rows, dict):
        # Sometimes payload is mapping asset-> {free/balance/...}
        tmp = []
        for k, v in rows.items():
            if isinstance(v, dict):
                vv = dict(v)
                vv.setdefault("asset", k)
                tmp.append(vv)
        rows = tmp
    if not isinstance(rows, list):
        return out

    for it in rows:
        if not isinstance(it, dict):
            continue
        a = it.get("asset")
        if a is None:
            a = it.get("coin")
        if a is None:
            a = it.get("currency")
        if a is None:
            a = it.get("symbol")
        if a is None:
            a = it.get("code")
        a = str(a or "").upper().strip()
        if not a:
            continue

        # free/available
        free = it.get("available")
        if free is None:
            free = it.get("free")

        # total/balance
        total = it.get("balance")
        if total is None:
            total = it.get("total")
        if total is None:
            total = it.get("amount")

        # locked/freeze
        locked = it.get("locked")
        if locked is None:
            locked = it.get("freeze")
        if locked is None:
            locked = it.get("inOrder")
        if locked is None:
            locked = it.get("in_order")
        if locked is None:
            locked = it.get("onOrder")
        if locked is None:
            locked = it.get("on_order")

        try:
            ld = _pp7826__to_dec(locked)
        except Exception:
            ld = _pp7826__to_dec("0")

        if Decimal is not None:
            try:
                if ld <= Decimal("0"):
                    raise Exception("no_direct_locked")
            except Exception:
                # compute (total - free) if possible
                td = _pp7826__to_dec(total)
                fd = _pp7826__to_dec(free)
                try:
                    if td > fd:
                        ld = td - fd
                    else:
                        ld = _pp7826__to_dec("0")
                except Exception:
                    ld = _pp7826__to_dec("0")
        else:
            # float mode
            try:
                if float(ld or 0.0) <= 0.0:
                    td = float(_pp7826__to_dec(total) or 0.0)
                    fd = float(_pp7826__to_dec(free) or 0.0)
                    ld = max(0.0, td - fd)
            except Exception:
                ld = 0.0

        # BTC quantize to 8dp
        try:
            if a == "BTC" and Decimal is not None:
                ld = _pp7826__q8(ld)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        try:
            if Decimal is not None:
                if ld > Decimal("0"):
                    out[a] = ld
            else:
                if float(ld or 0.0) > 0.0:
                    out[a] = ld
        except Exception:
            continue
    return out


def _pp7826__extract_total_from_wallet_payload(payload, wallet_name=None) -> dict:
    """
    Extract TOTAL (free+locked) per-asset amounts from ArzPlus /wallet/balance payload.

    نکته‌ی مهم:
      بعضی نسخه‌های API مقدارها را داخل دیکشنری‌های تو در تو می‌دهند:
        {"asset":"BTC","balance":{"available":"...","inOrder":"...","total":"..."}}
      یا ساختار چند-کیف‌پولی:
        {"data":{"wallets":[{"wallet":"W3","balances":[...]} , ...]}}
      این تابع بدون اثر روی توکن‌ها/ترید، فقط برای داشبورد TOTAL را درست استخراج می‌کند.

    خروجی: {ASSET: float_total}
    """
    Decimal, _Inv = _pp7826__dec_tools()
    out = {}
    if payload is None:
        return out

    def _to_dec(x):
        try:
            return _pp7826__to_dec(x)
        except Exception:
            if Decimal is None:
                try:
                    return float(x or 0.0)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return 0.0
            return Decimal("0")

    def _wallet_norm(s: str) -> str:
        try:
            s = str(s or "").strip().upper()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return ""
        if not s:
            return ""
        # keep only alnum to make "Wallet-3" == "WALLET3"
        try:
            s2 = "".join(ch for ch in s if ch.isalnum())
        except Exception:
            s2 = s
        return s2

    def _wallet_digits(s: str) -> str:
        try:
            s = _wallet_norm(s)
        except Exception:
            s = ""
        if not s:
            return ""
        # extract trailing digits (W3, WALLET3, 3)
        try:
            digs = "".join(ch for ch in s if ch.isdigit())
        except Exception:
            digs = ""
        return digs

    def _wallet_match(tag, wn) -> bool:
        if wn is None:
            return True
        wn0 = _wallet_norm(wn)
        if not wn0:
            return True
        tg0 = _wallet_norm(tag)
        if not tg0:
            return False
        if tg0 == wn0:
            return True
        # match by digits when present (W3 vs 3 vs WALLET3)
        d1 = _wallet_digits(tg0)
        d2 = _wallet_digits(wn0)
        if d1 and d2 and d1 == d2:
            return True
        return False

    def _unwrap_containers(obj):
        """
        Repeatedly unwrap common wrapper keys.
        """
        cur = obj
        for _ in range(8):
            if isinstance(cur, dict):
                # direct wallet-keyed payload
                try:
                    wn = str(wallet_name or "").strip()
                except Exception:
                    wn = ""
                if wn and wn in cur and isinstance(cur.get(wn), (list, dict)):
                    cur = cur.get(wn)
                    continue
                # common wrapper keys (nested)
                moved = False
                for k in ("data", "result", "results", "wallet", "wallets", "balances", "items", "list"):
                    try:
                        if k in cur and isinstance(cur.get(k), (list, dict)):
                            cur = cur.get(k)
                            moved = True
                            break
                    except Exception:
                        continue
                if moved:
                    continue
            break
        return cur

    def _pick_num(v):
        try:
            if v is None:
                return None
            if isinstance(v, (int, float)):
                return v
            if isinstance(v, str):
                s = v.strip().replace(",", "")
                if not s:
                    return None
                return s
            return v
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return None

    def _extract_total_from_row(row: dict):
        """
        Returns (asset, total_float) or (None, None)
        """
        if not isinstance(row, dict):
            return (None, None)

        # asset symbol
        a = row.get("asset")
        if a is None:
            a = row.get("coin")
        if a is None:
            a = row.get("currency")
        if a is None:
            a = row.get("symbol")
        if a is None:
            a = row.get("code")
        try:
            a = str(a or "").strip().upper()
        except Exception:
            a = ""
        if not a:
            return (None, None)

        # wallet filter (if row carries wallet name/id)
        try:
            wn = str(wallet_name or "").strip()
        except Exception:
            wn = ""
        if wn:
            try:
                wtag = row.get("wallet") or row.get("wallet_name") or row.get("walletId") or row.get("wallet_id") \
                    or row.get("account") or row.get("portfolio") or row.get("name") or row.get("label")
                if wtag is not None and str(wtag).strip():
                    if not _wallet_match(wtag, wn):
                        return (None, None)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

        # many payloads nest amounts under "balance"
        bal = row.get("balance")
        bal2 = bal if isinstance(bal, dict) else {}

        def _g(keys, default=None):
            # look in row then in nested balance dict
            for k in keys:
                if k in row and row.get(k) is not None:
                    return row.get(k)
            for k in keys:
                if isinstance(bal2, dict) and k in bal2 and bal2.get(k) is not None:
                    return bal2.get(k)
            return default

        total = _g(("total", "Total", "TOTAL"))
        if total is None:
            total = _g(("balance_total", "total_balance"))
        if total is None:
            # some APIs call it balance/amount/value but these may be total
            total = _g(("balance", "amount", "value"))

        free = _g(("available", "free", "Available", "FREE"))
        if free is None:
            free = _g(("usable", "spendable"))

        locked = _g(("locked", "freeze", "frozen", "inOrder", "in_order", "onOrder", "on_order",
                     "on_order_amount", "blocked", "hold", "reserved"))

        # if "balance" itself is dict, avoid treating dict as numeric
        if isinstance(total, dict):
            # try common keys inside it
            try:
                total = total.get("total") or total.get("balance") or total.get("amount") or total.get("value")
            except Exception:
                total = None

        if isinstance(free, dict):
            try:
                free = free.get("available") or free.get("free") or free.get("usable")
            except Exception:
                free = None

        if isinstance(locked, dict):
            try:
                locked = locked.get("locked") or locked.get("freeze") or locked.get("inOrder") or locked.get("onOrder")
            except Exception:
                locked = None

        # compute total if not present
        if total is None:
            if free is not None and locked is not None:
                try:
                    total = _to_dec(_pick_num(free)) + _to_dec(_pick_num(locked))
                except Exception:
                    total = free
            else:
                total = free

        try:
            tv = float(_to_dec(_pick_num(total)))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return (None, None)

        if tv > 0.0:
            return (a, tv)
        return (None, None)

    rows = _unwrap_containers(payload)

    # If we received a list of wallet-containers, select wallet first
    if isinstance(rows, list) and wallet_name:
        try:
            wn = str(wallet_name or "").strip()
        except Exception:
            wn = ""
        if wn:
            chosen = None
            for it in (rows or []):
                if not isinstance(it, dict):
                    continue
                # wallet tag candidates
                wtag = it.get("wallet") or it.get("wallet_name") or it.get("walletId") or it.get("wallet_id") \
                    or it.get("account") or it.get("portfolio") or it.get("name") or it.get("label")
                if wtag is not None and str(wtag).strip() and _wallet_match(wtag, wn):
                    chosen = it
                    break
            if isinstance(chosen, dict):
                for k in ("balances", "assets", "coins", "currencies", "items", "data", "result", "results", "wallet"):
                    if k in chosen and isinstance(chosen.get(k), (list, dict)):
                        rows = _unwrap_containers(chosen.get(k))
                        break
                else:
                    rows = chosen

    # dict mapping asset->scalar or asset->dict
    if isinstance(rows, dict):
        # scalar mapping {BTC: "0.1", ...}
        try:
            if all(not isinstance(v, (list, dict)) for v in (rows or {}).values()):
                for k, v in (rows or {}).items():
                    try:
                        a = str(k or "").strip().upper()
                    except Exception:
                        a = ""
                    if not a:
                        continue
                    try:
                        tv = float(_to_dec(_pick_num(v)))
                    except Exception:
                        continue
                    if tv > 0.0:
                        out[a] = tv
                return out
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        # mapping {BTC:{...}, ...} -> list-of-rows
        tmp = []
        try:
            for k, v in (rows or {}).items():
                if isinstance(v, dict):
                    vv = dict(v)
                    vv.setdefault("asset", k)
                    tmp.append(vv)
        except Exception:
            tmp = []
        rows = tmp

    if not isinstance(rows, list):
        return out

    # list-of-dicts (typical)
    for it in (rows or []):
        if not isinstance(it, dict):
            continue
        a, tv = _extract_total_from_row(it)
        if a and (tv is not None):
            out[a] = float(tv)

    return out


def _pp_locked_balances_v3(self, api: "ArzPlusAPI", wname: str):
    """
    v3 locked-balance accounting:
      - First attempt: derive locked from /wallet/balance payload fields (locked/freeze or balance-available).
      - Fallback: deterministic aggregation from open_orders_all().
      - Parsing: Decimal(str(x)) to support scientific notation and preserve BTC micro units.
    """
    try:
        import time as _t
        now = float(_t.time())
    except Exception:
        now = 0.0

    # Cache per-wallet
    try:
        ttl = 12.0
        if _pp7826_os is not None:
            ttl = float(_pp7826_os.getenv("OPEN_ORDERS_ALL_TTL_SEC", "12") or 12.0)
        ttl = max(1.0, ttl)
    except Exception:
        ttl = 12.0

    try:
        if not hasattr(self, "_pp_locked_cache_v3") or not isinstance(getattr(self, "_pp_locked_cache_v3", None), dict):
            self._pp_locked_cache_v3 = {}
        if not hasattr(self, "_pp_locked_cache_ts_v3") or not isinstance(getattr(self, "_pp_locked_cache_ts_v3", None), dict):
            self._pp_locked_cache_ts_v3 = {}
        _c = getattr(self, "_pp_locked_cache_v3", {})
        _ts = getattr(self, "_pp_locked_cache_ts_v3", {})
    except Exception:
        _c, _ts = {}, {}

    wn = str(wname or "")
    try:
        ts0 = float(_ts.get(wn, 0.0) or 0.0)
    except Exception:
        ts0 = 0.0

    if ts0 > 0.0 and now > 0.0 and (now - ts0) < ttl:
        try:
            cv = _c.get(wn)
            if isinstance(cv, dict):
                return dict(cv)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # 1) wallet payload locked extraction
    locked_map = {}
    try:
        r = api.wallet_balance()
        if isinstance(r, dict) and bool(r.get("ok")):
            payload = r.get("data")
            locked_map = _pp7826__extract_locked_from_wallet_payload(payload)
    except Exception:
        locked_map = {}

    # If we got any locked amounts from wallet payload, use them (more accurate than inferring from open orders)
    if isinstance(locked_map, dict) and locked_map:
        out2 = {}
        for k, v in locked_map.items():
            try:
                if k == "BTC":
                    # force 8dp for BTC locked to avoid satoshi loss
                    out2["BTC"] = format(_pp7826__q8(v), '.8f')  # keep BTC as 8dp string
                else:
                    out2[str(k).upper()] = float(_pp7826__to_dec(v))
            except Exception:
                continue
        try:
            _c[wn] = dict(out2)
            _ts[wn] = float(now or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return dict(out2)

    # 2) Fallback: open orders aggregation (same idea as v2 but strict Decimal parsing)
    try:
        r = api.open_orders_all()
        if (not isinstance(r, dict)) or (not bool(r.get("ok", False))):
            raise RuntimeError("open_orders_all_failed")

        orders = r.get("data") or []
        if not isinstance(orders, list):
            orders = []

        try:
            quote = str(getattr(self, "quote", "") or "IRT").upper().strip()
        except Exception:
            quote = "IRT"

        Decimal, _Inv = _pp7826__dec_tools()
        out = {}

        def _add(asset: str, amt):
            a = str(asset or "").upper().strip()
            if not a:
                return
            try:
                cur = out.get(a, _pp7826__to_dec("0"))
            except Exception:
                cur = _pp7826__to_dec("0")
            try:
                out[a] = _pp7826__to_dec(cur) + _pp7826__to_dec(amt)
            except Exception:
                out[a] = cur

        for o in orders:
            if not isinstance(o, dict):
                continue
            try:
                side = str(o.get("side") or o.get("type") or "").lower().strip()
            except Exception:
                side = ""
            if side not in ("buy", "sell"):
                continue
            try:
                sym = str(o.get("symbol") or o.get("market") or "").upper().strip()
            except Exception:
                sym = ""
            if not sym:
                continue
            # base parse
            base = ""
            try:
                if quote and sym.endswith(quote) and len(sym) > len(quote):
                    base = sym[:-len(quote)]
                elif sym.endswith("IRT") and len(sym) > 3:
                    base = sym[:-3]
                elif sym.endswith("USDT") and len(sym) > 4:
                    base = sym[:-4]
                else:
                    base = sym
            except Exception:
                base = sym
            base = str(base or "").upper().strip()
            if not base:
                continue

            amt = o.get("amount")
            filled = o.get("filled_amount")
            if filled is None:
                filled = o.get("filled")
            if filled is None:
                filled = o.get("executed")
            if filled is None:
                filled = 0

            rem = o.get("remaining")
            if rem is None:
                rem = o.get("remain")
            if rem is None:
                rem = o.get("remaining_amount")

            if rem is None:
                try:
                    rem = _pp7826__to_dec(amt) - _pp7826__to_dec(filled)
                except Exception:
                    rem = _pp7826__to_dec("0")

            remd = _pp7826__to_dec(rem)
            try:
                if Decimal is not None and remd <= Decimal("0"):
                    continue
            except Exception:
                try:
                    if float(remd or 0.0) <= 0.0:
                        continue
                except Exception:
                    continue

            if side == "sell":
                _add(base, remd)
            else:
                # buy locks quote qty * price
                pr = o.get("price")
                if pr is None:
                    pr = o.get("rate")
                prd = _pp7826__to_dec(pr)
                try:
                    qv = remd * prd
                except Exception:
                    qv = _pp7826__to_dec("0")
                _add(quote, qv)

        out2 = {}
        for k, v in (out or {}).items():
            try:
                if str(k).upper() == "BTC":
                    out2["BTC"] = format(_pp7826__q8(v), '.8f')  # keep BTC as 8dp string
                else:
                    out2[str(k).upper()] = float(_pp7826__to_dec(v))
            except Exception:
                continue
        try:
            _c[wn] = dict(out2)
            _ts[wn] = float(now or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return dict(out2)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return {}

