# ---------- (4) Trade Unlock / Reduced sensitivity for min-USDT gate ----------
try:
    _PP7826_PREV_VETO = getattr(SovereignVetoCouncil, "should_veto", None)  # type: ignore[name-defined]
except Exception:
    _PP7826_PREV_VETO = None

def _pp7826_should_veto(self, bot, wname: str, sym: str, side: str, qty: float, price: float, meta=None):  # type: ignore[override]
    # Integrity unlock: once Net Worth is stable for 2 consecutive cycles, remove ALL VETO constraints.
    try:
        if bot is not None:
            if not bool(getattr(bot, "_pp7826_integrity_unlocked", False)):
                # Redundant safety: if dashboard updater isn't running, infer stability from the latest published net worth.
                try:
                    cur_nw = float(getattr(bot, "_dash_net_worth_raw", 0.0) or 0.0)
                except Exception:
                    cur_nw = 0.0
                if cur_nw > 0.0:
                    prev_nw = float(getattr(bot, "_pp7826_prev_net_worth_raw", 0.0) or 0.0)
                    has_prev = bool(getattr(bot, "_pp7826_prev_net_worth_set", False))
                    stable_cycles = int(getattr(bot, "_pp7826_net_worth_stable_cycles", 0) or 0)
                    tol = max(1.0, abs(cur_nw) * 0.001, 50000.0)
                    if has_prev and abs(cur_nw - prev_nw) <= tol:
                        stable_cycles += 1
                    else:
                        stable_cycles = 1
                    setattr(bot, "_pp7826_prev_net_worth_raw", cur_nw)
                    setattr(bot, "_pp7826_prev_net_worth_set", True)
                    setattr(bot, "_pp7826_net_worth_stable_cycles", int(stable_cycles))
                    if int(stable_cycles) >= 2:
                        setattr(bot, "_pp7826_integrity_unlocked", True)
                        try:
                            bot._pp255_freeze_until = 0.0
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                        try:
                            bot._pp255_freeze_reason = "PP7826_INTEGRITY_UNLOCK"
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
            if bool(getattr(bot, "_pp7826_integrity_unlocked", False)):
                return (False, "PP7826_INTEGRITY_UNLOCK")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    try:
        veto, reason = (False, "ok")
        if callable(_PP7826_PREV_VETO):
            veto, reason = _PP7826_PREV_VETO(self, bot, wname, sym, side, qty, price, meta)
        else:
            veto, reason = (False, "ok")
    except Exception:
        veto, reason = (False, "ok")

    # If we have prices and USDT is positive, do NOT veto BUY due to small quality/equity jitter.
    try:
        if veto and str(side or "").lower().strip() == "buy":
            rs = str(reason or "")
            if "first_law_min_usdt" in rs:
                tot = 0.0
                try:
                    if hasattr(self, "_liquidity_snapshot_usdt"):
                        _tmp = self._liquidity_snapshot_usdt(bot, wname)
                        if isinstance(_tmp, (tuple, list)) and len(_tmp) >= 1:
                            tot = float(_tmp[0] or 0.0)
                except Exception:
                    tot = 0.0

                # PP7828 Force Trade Integrity: unlock BUY veto based on regression signal (not price-change jitter)
                has_reg_signal = False
                try:
                    if isinstance(meta, dict):
                        for _k in ("reg_slope", "reg_slope_pct", "slope", "slope_pct", "linreg_slope_pct"):
                            if _k in meta:
                                try:
                                    if abs(float(meta.get(_k) or 0.0)) > 0.0:
                                        has_reg_signal = True
                                        break
                                except Exception as _pp200_e:
                                    _pp200_report(_pp200_e, tag="exc_pass")
                        if not has_reg_signal:
                            det = meta.get("details") or []
                            if isinstance(det, list):
                                for _d in det:
                                    if not isinstance(_d, (list, tuple)) or len(_d) < 2:
                                        continue
                                    _nm = str(_d[0] or "").upper()
                                    if any(x in _nm for x in ("LINREG", "REG", "SLOPE")):
                                        _v = str(_d[1] or "HOLD").upper()
                                        if _v in ("BUY", "SELL"):
                                            has_reg_signal = True
                                            break
                except Exception:
                    has_reg_signal = False

                if bool(has_reg_signal) and float(tot or 0.0) > 0.0:
                    return (False, "PP7828_UNLOCK:usdt_positive_with_regression_signal")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return (bool(veto), str(reason or "ok"))

try:
    SovereignVetoCouncil.should_veto = _pp7826_should_veto  # type: ignore[name-defined]
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

# ---------- (5) Dashboard: enforce Net Worth floor + keep BTC 8dp in UI caches ----------
try:
    _PP7826_PREV_AI_PANEL = getattr(DashboardManager, "_ai_status_panel", None)  # type: ignore[name-defined]
except Exception:
    _PP7826_PREV_AI_PANEL = None

def _pp7826_ai_status_panel(self):  # type: ignore[override]
    # Call existing panel builder first
    p = None
    try:
        if callable(_PP7826_PREV_AI_PANEL):
            p = _PP7826_PREV_AI_PANEL(self)
    except Exception:
        p = None

    # Additionally publish a stable net worth number onto bot for other panels (Reports uses _dash_net_worth_raw)
    try:
        bot = getattr(self, "bot", None)
        if bot is not None:
            floor = 0.0
            try:
                if _pp7826_os is not None:
                    floor = float(_pp7826_os.getenv("NET_WORTH_FLOOR_IRT", "0") or 0.0)
            except Exception:
                floor = 0.0

            # compute raw from TOTAL equity cache deterministically
            raw = 0.0
            try:
                from decimal import Decimal, getcontext
                getcontext().prec = 60
                ec = getattr(bot, "_dash_equity_total_cache", None) or getattr(bot, "_dash_equity_raw_cache", None) or getattr(bot, "_dash_equity_cache", {}) or {}
                if isinstance(ec, dict):
                    s = Decimal("0")
                    for v in ec.values():
                        s += _pp7826__to_dec(v)
                    raw = float(s)
            except Exception:
                raw = 0.0

            if floor > 0.0 and raw > 0.0 and raw < floor:
                raw = float(floor)
            # publish
            try:
                setattr(bot, "_dash_net_worth_raw", float(raw))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

            # PP7826 Trade Engine Unlock:
            # If Net Worth is stable for 2 consecutive cycles -> unlock all VETO constraints.
            try:
                cur_nw = float(raw or 0.0)
                if cur_nw > 0.0:
                    prev_nw = float(getattr(bot, "_pp7826_prev_net_worth_raw", 0.0) or 0.0)
                    has_prev = bool(getattr(bot, "_pp7826_prev_net_worth_set", False))
                    stable_cycles = int(getattr(bot, "_pp7826_net_worth_stable_cycles", 0) or 0)

                    # Stability tolerance: 0.1% of net worth OR 50k toman (whichever larger)
                    tol = max(1.0, abs(cur_nw) * 0.001, 50000.0)
                    if has_prev and abs(cur_nw - prev_nw) <= tol:
                        stable_cycles += 1
                    else:
                        stable_cycles = 1

                    setattr(bot, "_pp7826_prev_net_worth_raw", cur_nw)
                    setattr(bot, "_pp7826_prev_net_worth_set", True)
                    setattr(bot, "_pp7826_net_worth_stable_cycles", int(stable_cycles))

                    if int(stable_cycles) >= 2:
                        setattr(bot, "_pp7826_integrity_unlocked", True)
                        # Clear any OMS veto-freeze window (if set)
                        try:
                            bot._pp255_freeze_until = 0.0
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                        try:
                            bot._pp255_freeze_reason = "PP7826_INTEGRITY_UNLOCK"
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                else:
                    setattr(bot, "_pp7826_prev_net_worth_set", False)
                    setattr(bot, "_pp7826_net_worth_stable_cycles", 0)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    return p

