# ---- Life-Support: allow disk price cache reads when live data is missing/invalid ----
try:
    _PP7841_PREV_DISK_ALLOWED = globals().get("_pp_disk_price_cache_allowed", None)
except Exception:
    _PP7841_PREV_DISK_ALLOWED = None

def _pp7841_disk_price_cache_allowed() -> bool:
    try:
        import time as _t
        # If strict policy is explicitly enabled, keep legacy behavior.
        strict = False
        try:
            if _pp7841_os is not None:
                strict = str(_pp7841_os.getenv("PP_STRICT_EXCHANGE_PRICE_POLICY", "0") or "0").strip().lower() in ("1","true","yes","y","on")
        except Exception:
            strict = False

        if not strict:
            # Life-Support default: ON (read disk cache whenever needed)
            try:
                if _pp7841_os is not None:
                    ls = str(_pp7841_os.getenv("LIFE_SUPPORT_PROTOCOL", "1") or "1").strip().lower()
                    if ls not in ("0","false","no","off"):
                        return True
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return True

        # Legacy timeout-gated behavior
        try:
            return float(globals().get("_pp_disk_price_cache_allowed_until", 0.0) or 0.0) > float(_t.time())
        except Exception:
            if callable(_PP7841_PREV_DISK_ALLOWED):
                try:
                    return bool(_PP7841_PREV_DISK_ALLOWED())
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return False
            return False
    except Exception:
        try:
            if callable(_PP7841_PREV_DISK_ALLOWED):
                return bool(_PP7841_PREV_DISK_ALLOWED())
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return True

