# ---- Smart parsing: normalize any noisy numeric input into Decimal safely (no float() pre-cast) ----
try:
    _PP7841_PREV_TO_DEC = globals().get("_pp7826__to_dec", None)
except Exception:
    _PP7841_PREV_TO_DEC = None

def _pp7841__to_dec(v, default_str: str = "0"):
    try:
        from decimal import Decimal, getcontext
        getcontext().prec = 90

        def _strip_noise(s: str) -> str:
            try:
                s = str(s or "").strip()
            except Exception:
                s = ""
            if not s:
                return ""
            try:
                # normalize separators / spaces
                s = s.replace(",", "").replace("،", "").replace("_", "").replace(" ", "")
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

            # Try to extract first valid numeric token (supports scientific notation)
            try:
                import re as _re
                m = _re.search(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?", s)
                if m:
                    return m.group(0)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            return s

        if v is None:
            v = default_str

        # string-first
        s = _strip_noise(v)
        if not s:
            s = _strip_noise(default_str) or "0"

        # expand scientific notation to a full decimal string when needed (BTC-satoshi safe)
        if ("e" in s) or ("E" in s):
            try:
                # If v is numeric (already float/int/Decimal) use format(v,'.8f') directly (NO float()).
                if isinstance(v, (int, float, Decimal)):
                    s = str(format(v, ".8f"))
                else:
                    d = Decimal(_strip_noise(s) or "0")
                    s = str(format(d, ".8f"))
            except Exception:
                try:
                    d = Decimal(_strip_noise(s) or "0")
                    s = str(format(d, ".8f"))
                except Exception:
                    s = "0.00000000"

        try:
            return Decimal(s)
        except Exception:
            try:
                return Decimal(_strip_noise(default_str) or "0")
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return Decimal("0")
    except Exception:
        # fallback to previous implementation if available
        try:
            if callable(_PP7841_PREV_TO_DEC):
                return _PP7841_PREV_TO_DEC(v, default_str=default_str)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        try:
            from decimal import Decimal
            return Decimal("0")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0  # last resort

try:
    globals()["_pp7826__to_dec"] = _pp7841__to_dec
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

# ---- Future-proof balances: accept new, reject only impossible drops in BTC/USDT (unless traded) ----
def _pp7841__recent_trade(bot, wname: str, now_ts: float, window_sec: float = 30.0) -> bool:
    # Any recent BUY/SELL issued by the bot within window => balances changes are legal immediately.
    try:
        # Trim first (keeps list small)
        if "_pp7783__recent_orders_trim" in globals() and callable(globals().get("_pp7783__recent_orders_trim")):
            try:
                globals()["_pp7783__recent_orders_trim"](bot, now_ts, max_age_sec=max(120.0, float(window_sec or 30.0)))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
        ro = getattr(bot, "_pp_recent_orders", None)
        if isinstance(ro, list):
            for o in ro:
                if not isinstance(o, dict):
                    continue
                try:
                    if str(o.get("wallet") or "") != str(wname):
                        continue
                    if not bool(o.get("ok", True)):
                        continue
                    ts = float(o.get("ts", 0.0) or 0.0)
                    if ts > 0.0 and (now_ts - ts) <= float(window_sec):
                        return True
                except Exception:
                    continue
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    # Also consider explicit per-wallet buy/sell timestamps if present
    try:
        import time as _t
        now_rt = float(_t.time())
        for attr in ("_pp_last_buy_ts_by_wallet", "_pp_last_sell_ts_by_wallet"):
            m = getattr(bot, attr, None)
            if isinstance(m, dict):
                ts = float(m.get(str(wname), 0.0) or 0.0)
                if ts > 0.0 and (now_rt - ts) <= float(max(0.0, window_sec)):
                    return True
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return False

def _pp7841__rational_balance_filter(bot, wname: str, cur_map: dict, now_ts: float) -> dict:
    """
    Accept new balances by default.
    Only reject BTC/USDT drops >95% if NOT explained by a recent trade.
    """
    try:
        from decimal import Decimal
    except Exception:
        Decimal = None  # type: ignore

    # Memory store
    mem = {}
    try:
        mem = getattr(bot, "_last_verified_balance", None)
        if not isinstance(mem, dict):
            mem = {}
            setattr(bot, "_last_verified_balance", mem)
    except Exception:
        mem = {}
        try:
            setattr(bot, "_last_verified_balance", mem)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # Back-compat
    try:
        setattr(bot, "_pp7826_balance_mem", mem)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    prev = {}
    try:
        if isinstance(mem.get(str(wname)), dict):
            prev = dict(mem.get(str(wname)) or {})
    except Exception:
        prev = {}

    # If nothing current, fall back to prev (life support)
    if not isinstance(cur_map, dict) or not cur_map:
        try:
            if prev:
                return dict(prev)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return {}

    # If bot traded recently, accept immediately (operational stability for consecutive trades)
    if _pp7841__recent_trade(bot, wname, float(now_ts), window_sec=30.0):
        try:
            mem[str(wname)] = dict(cur_map)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return dict(cur_map)

    out = dict(cur_map)
    drop_assets = ("BTC", "USDT")
    for a in drop_assets:
        try:
            pa = _pp7841__to_dec(prev.get(a, "0"))
            ca = _pp7841__to_dec(cur_map.get(a, "0"))
        except Exception:
            continue

        try:
            if Decimal is not None:
                if pa > Decimal("0") and ca >= Decimal("0") and ca < (pa * Decimal("0.05")):
                    explained = False
                    try:
                        if "_pp7783__orders_explain_delta" in globals() and callable(globals().get("_pp7783__orders_explain_delta")):
                            explained = bool(globals()["_pp7783__orders_explain_delta"](bot, wname, a, float(ca - pa), now_ts, window_sec=120))
                    except Exception:
                        explained = False
                    if not explained:
                        out[a] = prev.get(a, out.get(a))
        except Exception:
            # float fallback
            try:
                pa_f = float(prev.get(a, 0.0) or 0.0)
                ca_f = float(cur_map.get(a, 0.0) or 0.0)
                if pa_f > 0.0 and ca_f >= 0.0 and ca_f < (pa_f * 0.05):
                    out[a] = prev.get(a, out.get(a))
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

    # Persist (post-filter) as last verified
    try:
        mem[str(wname)] = dict(out)
        setattr(bot, "_last_verified_balance", mem)
        setattr(bot, "_pp7826_balance_mem", mem)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    return dict(out)

try:
    globals()["_pp7783__rational_balance_filter"] = _pp7841__rational_balance_filter
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

