def _pp7841_balances(self, api):
    import time as _t
    now_ts = float(_t.time())

    # Try the true raw balances provider (before PP7826 anchoring), else fall back to current
    raw = {}
    try:
        if callable(_PP7841_PREV_BALANCES):
            raw = _PP7841_PREV_BALANCES(self, api) or {}
        else:
            raw = (getattr(self.__class__, "_balances", None) or (lambda *_: {}))(self, api)  # type: ignore[misc]
    except Exception:
        raw = {}

    # Derive wallet name (best-effort)
    wname = ""
    try:
        for _n, _a in (getattr(self, "apis", {}) or {}).items():
            if _a is api:
                wname = str(_n)
                break
    except Exception:
        wname = ""

    # Normalize + Decimal convert (no float() pre-cast)
    cur = {}
    try:
        if isinstance(raw, dict):
            for k, v in raw.items():
                kk = str(k or "").upper().strip()
                if not kk:
                    continue
                try:
                    cur[kk] = float(_pp7841__to_dec(v))
                except Exception:
                    try:
                        cur[kk] = float(v or 0.0)
                    except Exception:
                        cur[kk] = 0.0
    except Exception:
        cur = {}

    # Life-support: if payload is empty/invalid, keep last verified balances
    if not cur:
        try:
            mem = getattr(self, "_last_verified_balance", None)
            if isinstance(mem, dict) and isinstance(mem.get(str(wname)), dict) and mem.get(str(wname)):
                cur = dict(mem.get(str(wname)) or {})
                try:
                    if not hasattr(self, "_dash_wallet_errors"):
                        self._dash_wallet_errors = {}
                    if isinstance(getattr(self, "_dash_wallet_errors", None), dict):
                        self._dash_wallet_errors[str(wname)] = "LIFE_SUPPORT_BALANCE_CACHE"
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # Apply rational filter (future-proof)
    try:
        cur = _pp7841__rational_balance_filter(self, wname, cur, now_ts) or cur
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Always keep BTC display precision friendly
    try:
        if "BTC" in cur:
            # Keep internal float, but align to 8dp boundary
            cur["BTC"] = float(format(float(cur.get("BTC") or 0.0), ".8f"))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    return dict(cur)

