def _pp7841_wallet_snapshot(self, wname: str) -> dict:
    """
    Always returns ok=True (ONLINE) using:
      1) live wallet caches
      2) last-verified balances (memory anchor)
      3) last-known prices from .price_cache.json
    """
    # First attempt: use existing snapshot builder
    out = None
    try:
        if callable(_PP7841_PREV_WALLET_SNAPSHOT):
            out = _PP7841_PREV_WALLET_SNAPSHOT(self, wname)
    except Exception:
        out = None

    # If previous snapshot is good, keep it, but prevent OFFLINE due to transient errors
    try:
        if isinstance(out, dict):
            if not bool(out.get("ok", True)):
                out["ok"] = False
                # mark degraded if there was an error
                if out.get("err"):
                    out["degraded"] = True
            return out
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Minimal fallback snapshot (never crash the dashboard)
    try:
        bot = getattr(self, "bot", None)
        if bot is None:
            return {"ok": True, "wallet": wname, "assets": {}, "equity": 0.0, "pnl": 0.0, "err": "NO_BOT", "degraded": True}

        _lk = getattr(bot, "_dash_lock", None)
        if _lk is None:
            b = (getattr(bot, "_dash_balances_cache", {}) or {}).get(wname) or {}
            price_map = (getattr(bot, "_dash_price_map_cache", {}) or {}).get(wname) or {}
            eq = (getattr(bot, "_dash_equity_total_cache", None) or getattr(bot, "_dash_equity_cache", {}) or {}).get(wname, 0.0)
        else:
            with _lk:
                b = (getattr(bot, "_dash_balances_cache", {}) or {}).get(wname) or {}
                price_map = (getattr(bot, "_dash_price_map_cache", {}) or {}).get(wname) or {}
                eq = (getattr(bot, "_dash_equity_total_cache", None) or getattr(bot, "_dash_equity_cache", {}) or {}).get(wname, 0.0)

        # Life-support: if b empty, use last verified
        if (not isinstance(b, dict)) or (not b):
            try:
                mem = getattr(bot, "_last_verified_balance", None)
                if isinstance(mem, dict) and isinstance(mem.get(str(wname)), dict):
                    b = dict(mem.get(str(wname)) or {})
            except Exception:
                b = {}

        # Ensure price_map has at least USDT/BTC from cache for display
        try:
            if not isinstance(price_map, dict):
                price_map = {}
        except Exception:
            price_map = {}
        try:
            if float(price_map.get("USDT", 0.0) or 0.0) <= 0.0:
                price_map["USDT"] = float(globals().get("_pp_price_cache_get", lambda *_: 0.0)("USDT", 0.0) or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        try:
            if float(price_map.get("BTC", 0.0) or 0.0) <= 0.0:
                price_map["BTC"] = float(globals().get("_pp_price_cache_get", lambda *_: 0.0)("BTC", 0.0) or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        # Build formatted assets (always .8f)
        assets = {}
        try:
            for a, v in (b or {}).items():
                au = str(a or "").upper().strip()
                if not au:
                    continue
                try:
                    d = _pp7841__to_dec(v)
                    assets[au] = f"{d:.8f}"
                except Exception:
                    try:
                        assets[au] = f"{float(v or 0.0):.8f}"
                    except Exception:
                        assets[au] = "0.00000000"
        except Exception:
            assets = {}

        return {
            "ok": True,
            "wallet": str(wname),
            "assets": assets,
            "equity": float(eq or 0.0),
            "pnl": 0.0,
            "err": "LIFE_SUPPORT_FALLBACK",
            "degraded": True,
        }
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return {"ok": True, "wallet": wname, "assets": {}, "equity": 0.0, "pnl": 0.0, "err": "LIFE_SUPPORT_FAIL", "degraded": True}

