def _pp7841__extract_balance_map(payload) -> dict:
    """
    Extract flat {ASSET: Decimal} from many possible payload shapes.
    Never raises.
    """
    try:
        from decimal import Decimal
    except Exception:
        Decimal = None  # type: ignore

    out = {}

    def _put(asset, free_v=None, locked_v=None, total_v=None):
        try:
            a = str(asset or "").upper().strip()
            if not a:
                return
            if a == "RIAL":
                a = "IRT"
            if total_v is not None:
                d = _pp7841__smart_to_dec(total_v)
            else:
                d = _pp7841__smart_to_dec(free_v)
                if locked_v is not None:
                    d = d + _pp7841__smart_to_dec(locked_v)
            try:
                if Decimal is not None and isinstance(d, Decimal) and d.is_nan():
                    return
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            out[a] = d
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return

    def _parse_entry(item):
        if not isinstance(item, dict):
            return
        a = (
            item.get("asset") or item.get("symbol") or item.get("currency") or item.get("coin")
            or item.get("ccy") or item.get("name") or item.get("curr") or item.get("type")
        )
        if not a:
            return
        free = (
            item.get("free") or item.get("available") or item.get("avail") or item.get("balance")
            or item.get("amount") or item.get("qty") or item.get("value")
        )
        locked = (
            item.get("locked") or item.get("freeze") or item.get("frozen") or item.get("inOrder")
            or item.get("in_order") or item.get("hold")
        )
        total = item.get("total") or item.get("equity")
        _put(a, free_v=free, locked_v=locked, total_v=total)

    data = payload
    try:
        if isinstance(payload, dict):
            for k in ("data", "result", "results", "wallet", "wallets", "balances", "items"):
                if k in payload and payload.get(k) is not None:
                    data = payload.get(k)
                    break
    except Exception:
        data = payload

    if isinstance(data, dict):
        for k, v in (data or {}).items():
            try:
                kk = str(k or "").upper().strip()
                if not kk:
                    continue
                if isinstance(v, dict):
                    _parse_entry(dict(v, asset=kk))
                elif isinstance(v, (list, tuple)):
                    for it in v:
                        if isinstance(it, dict):
                            _parse_entry(it)
                else:
                    _put(kk, free_v=v)
            except Exception:
                continue
        return out

    if isinstance(data, (list, tuple)):
        for it in data:
            if isinstance(it, dict):
                _parse_entry(it)
        return out

    return out


def _pp7841__balances_lifesupport(self, api):
    """
    Replacement for PP5LiveTripleWallet._balances:
      - fetch + smart-parse
      - fallback to memory / disk cache
      - never returns empty dict (prevents EMPTY_OR_INVALID)
      - clears _dash_wallet_errors for non-fatal cases to keep UI ONLINE
    """
    import time as _t
    now = float(_t.time())
    wname = ""
    try:
        wname = _pp7841__find_wallet_name_by_api(self, api)
    except Exception:
        wname = ""

    # 1) Direct API (smart parsing)
    cur = {}
    raw_payload = None
    try:
        if hasattr(api, "balance") and callable(getattr(api, "balance")):
            raw_payload = api.balance()
        else:
            raw_payload = api.wallet_balance()
    except Exception:
        raw_payload = None

    try:
        cur = _pp7841__extract_balance_map(raw_payload)
    except Exception:
        cur = {}

    # 2) Fallback to previous impl (captured) if still empty
    if not cur:
        try:
            _prev = getattr(self, "_pp7841_prev_balances_impl", None)
            if callable(_prev):
                pm = _prev(self, api) or {}
                if isinstance(pm, dict):
                    for k, v in (pm or {}).items():
                        kk = str(k or "").upper().strip()
                        if kk:
                            cur[kk] = _pp7841__smart_to_dec(v)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # 3) Memory then disk fallback
    if not cur:
        try:
            mem = getattr(self, "_last_verified_balance", None)
            if isinstance(mem, dict) and wname and isinstance(mem.get(str(wname)), dict) and mem.get(str(wname)):
                cur = {str(k).upper().strip(): _pp7841__smart_to_dec(v) for k, v in (mem.get(str(wname)) or {}).items()}
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    if not cur:
        try:
            dc = _pp7841__balance_cache_load()
            rec = dc.get(str(wname)) if isinstance(dc, dict) else None
            if isinstance(rec, dict):
                bal = rec.get("bal") if isinstance(rec.get("bal"), dict) else rec
                if isinstance(bal, dict) and bal:
                    cur = {str(k).upper().strip(): _pp7841__smart_to_dec(v) for k, v in bal.items()}
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # Quote key always present
    try:
        q = str(getattr(self, "quote", "IRT") or "IRT").upper().strip()
    except Exception:
        q = "IRT"
    if q and q not in cur:
        cur[q] = _pp7841__smart_to_dec("0")

    # 4) Rational filter (BTC/USDT drop >95% unless explained by bot trades)
    try:
        if "_pp7841__rational_balance_filter" in globals() and callable(globals().get("_pp7841__rational_balance_filter")):
            cm = {k: (str(v) if v is not None else "0") for k, v in (cur or {}).items()}
            cm2 = globals()["_pp7841__rational_balance_filter"](self, str(wname), cm, float(now)) or cm
            cur = {str(k).upper().strip(): _pp7841__smart_to_dec(v) for k, v in (cm2 or {}).items()}
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # 5) Persist as last verified (memory + disk)
    try:
        mem = getattr(self, "_last_verified_balance", None)
        if not isinstance(mem, dict):
            mem = {}
        mem[str(wname)] = {k: (str(v) if v is not None else "0") for k, v in (cur or {}).items()}
        setattr(self, "_last_verified_balance", mem)
        setattr(self, "_pp7826_balance_mem", mem)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    try:
        dc = _pp7841__balance_cache_load()
        if not isinstance(dc, dict):
            dc = {}
        dc[str(wname)] = {"ts": float(now), "bal": {k: (str(v) if v is not None else "0") for k, v in (cur or {}).items()}}
        _pp7841__balance_cache_save(dc)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # 6) UI: keep ONLINE (warnings separate; errors cleared)
    try:
        if not hasattr(self, "_dash_wallet_warnings"):
            self._dash_wallet_warnings = {}
        if isinstance(getattr(self, "_dash_wallet_warnings", None), dict) and wname:
            if not raw_payload or (isinstance(raw_payload, dict) and raw_payload.get("ok") is False):
                self._dash_wallet_warnings[str(wname)] = "LIFE_SUPPORT_ACTIVE"
            else:
                self._dash_wallet_warnings[str(wname)] = ""
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    try:
        if hasattr(self, "_dash_wallet_errors") and isinstance(getattr(self, "_dash_wallet_errors", None), dict) and wname:
            self._dash_wallet_errors[str(wname)] = ""
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # 7) Return float mapping for engine compatibility
    out = {}
    for k, v in (cur or {}).items():
        try:
            kk = str(k or "").upper().strip()
            if kk:
                out[kk] = float(_pp7841__smart_to_dec(v))
        except Exception:
            continue

    if not out:
        out = {q: 0.0}
    return dict(out)


# Install patch (avoid recursion by storing previous impl into instance attribute name we call above)
try:
    _pp_cls = globals().get("PP5LiveTripleWallet")
    if _pp_cls is not None and hasattr(_pp_cls, "_balances"):
        # Store previous impl on the CLASS under a new name, then patch
        try:
            prev = getattr(_pp_cls, "_balances")
            setattr(_pp_cls, "_pp7841_prev_balances_impl", prev)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        setattr(_pp_cls, "_balances", _pp7841__balances_lifesupport)
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

