# Earlier PP7779 block is intentionally disabled because this file continues with additional genetic patches.
# This final block ensures ALL patches are loaded before starting watchdog/live loop.

# === PP20260102_LOCKED_EQUITY_ROOTFIX_BEGIN ===
# Root fix (2026-01-02):
#   1) TOTAL wallet balances/equity must include LOCKED funds (reserved in open orders), so BTC total like
#      0.00016385 is not incorrectly shown as free-only 0.00000085.
#   2) Dashboard snapshot must NOT overwrite TOTAL equity with FREE-only equity (bug introduced by PP9001 snapshot override).
# Notes:
#   - NO token edits.
#   - Trading sizing remains based on FREE (balances_cache). TOTAL is UI/accounting only.

def _pp20260102__locked_balances_v4(self, api, wname: str):
    """Return per-asset LOCKED amounts (reserved in open orders).

    Priority:
      A) If wallet/balance payload contains locked/freeze/total-available fields, use that.
      B) Else derive from open orders (open_orders_all if available, otherwise list_orders paging).

    Output:
      - BTC is returned as fixed 8dp string (to avoid scientific notation in UI).
      - Other assets are floats.
    """
    # Decimal-first parsing to preserve micro-units (BTC sats)
    try:
        from decimal import Decimal, getcontext
        getcontext().prec = 80
    except Exception:
        Decimal = None  # type: ignore

    def _to_dec(v):
        if Decimal is None:
            try:
                return float(v or 0.0)
            except Exception:
                try:
                    return float(str(v).strip().replace(",", "") or 0.0)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return 0.0
        try:
            if v is None:
                return Decimal("0")
            if isinstance(v, Decimal):
                return v
            if isinstance(v, bool):
                return Decimal("1") if v else Decimal("0")
            if isinstance(v, int):
                return Decimal(v)
            if isinstance(v, float):
                return Decimal(repr(v))
            if isinstance(v, str):
                s = v.strip().replace(",", "").replace("−", "-").replace("–", "-")
                return Decimal(s or "0")
            s = str(v).strip().replace(",", "")
            return Decimal(s or "0")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return Decimal("0")

    def _q8(d):
        try:
            if Decimal is None:
                return float(d or 0.0)
            return _to_dec(d).quantize(Decimal("0.00000001"))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return _to_dec("0")

    # Cache per-wallet (UI-only; keep light to avoid RL issues)
    try:
        import time as _t, os as _os
        now = float(_t.time())
        ttl = float(_os.getenv("OPEN_ORDERS_ALL_TTL_SEC", "12") or 12.0)
        ttl = max(1.0, ttl)
    except Exception:
        now = 0.0
        ttl = 12.0

    try:
        if not hasattr(self, "_pp_locked_cache_v4") or not isinstance(getattr(self, "_pp_locked_cache_v4", None), dict):
            self._pp_locked_cache_v4 = {}
        if not hasattr(self, "_pp_locked_cache_ts_v4") or not isinstance(getattr(self, "_pp_locked_cache_ts_v4", None), dict):
            self._pp_locked_cache_ts_v4 = {}
        _c = getattr(self, "_pp_locked_cache_v4", {})
        _ts = getattr(self, "_pp_locked_cache_ts_v4", {})
    except Exception:
        _c, _ts = {}, {}

    wn = str(wname or "")
    try:
        ts0 = float(_ts.get(wn, 0.0) or 0.0)
    except Exception:
        ts0 = 0.0
    if ts0 > 0.0 and now > 0.0 and (now - ts0) < ttl:
        try:
            cv = _c.get(wn)
            if isinstance(cv, dict):
                return dict(cv)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # --- A) wallet payload locked extraction (if available) ---
    locked_map = {}
    try:
        if hasattr(api, "wallet_balance"):
            r = api.wallet_balance()
            if isinstance(r, dict) and bool(r.get("ok")):
                payload = r.get("data")
                # Prefer existing extractor if present (PP7826)
                if "_pp7826__extract_locked_from_wallet_payload" in globals():
                    try:
                        locked_map = globals()["_pp7826__extract_locked_from_wallet_payload"](payload)  # type: ignore[call-arg]
                    except Exception:
                        locked_map = {}
                else:
                    # Best-effort extraction for common shapes
                    locked_map = {}
                    rows = payload
                    if isinstance(rows, dict):
                        for k in ("wallet", "wallets", "balances", "results", "data"):
                            if isinstance(rows.get(k), list):
                                rows = rows.get(k)
                                break
                    if isinstance(rows, list):
                        for it in rows:
                            if not isinstance(it, dict):
                                continue
                            a = str(it.get("asset") or it.get("coin") or it.get("currency") or it.get("symbol") or "").upper().strip()
                            if not a:
                                continue
                            free = it.get("free")
                            if free is None:
                                free = it.get("available")
                            total = it.get("balance")
                            if total is None:
                                total = it.get("total")
                            locked = it.get("locked")
                            if locked is None:
                                locked = it.get("freeze")
                            if locked is None:
                                # infer as total-free
                                try:
                                    td = _to_dec(total)
                                    fd = _to_dec(free)
                                    locked = (td - fd) if td > fd else _to_dec("0")
                                except Exception:
                                    locked = _to_dec("0")
                            ld = _to_dec(locked)
                            try:
                                if Decimal is not None and ld > Decimal("0"):
                                    locked_map[a] = ld
                            except Exception:
                                try:
                                    if float(ld or 0.0) > 0.0:
                                        locked_map[a] = ld
                                except Exception as _pp200_e:
                                    _pp200_report(_pp200_e, tag="exc_pass")
    except Exception:
        locked_map = {}

    if isinstance(locked_map, dict) and locked_map:
        out2 = {}
        for k, v in locked_map.items():
            try:
                ak = str(k or "").upper().strip()
            except Exception:
                continue
            if not ak:
                continue
            try:
                if ak == "BTC":
                    out2["BTC"] = format(_q8(v), ".8f")
                else:
                    out2[ak] = float(_to_dec(v))
            except Exception:
                continue
        try:
            _c[wn] = dict(out2)
            _ts[wn] = float(now or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return dict(out2)

    # --- B) derive locked from open orders ---
    try:
        quote = str(getattr(self, "quote", "") or "IRT").upper().strip()
    except Exception:
        quote = "IRT"

    # Split symbol into (base, quote) robustly
    def _split_sym(sym: str):
        s = str(sym or "").upper().strip()
        if not s:
            return ("", "")
        # common quote suffixes (longer first)
        suffixes = ["USDT", "USDC", "BUSD", "IRT", "IRR", "USD", "EUR", "TRY", "AED", "BTC", "ETH", "BNB"]
        for q in sorted(suffixes, key=len, reverse=True):
            if s.endswith(q) and len(s) > len(q):
                b = s[:-len(q)]
                while b and b[-1] in "-_/:":  # strip boundary separators only
                    b = b[:-1]
                return (b, q)
        if quote and s.endswith(quote) and len(s) > len(quote):
            return (s[:-len(quote)], quote)
        return (s, "")

    # Collect orders using the most supported API method
    orders = []
    # 1) open_orders_all (fast path)
    try:
        if hasattr(api, "open_orders_all"):
            r = api.open_orders_all()
            if isinstance(r, dict) and bool(r.get("ok")):
                dd = r.get("data") or []
                if isinstance(dd, list):
                    orders = dd
    except Exception:
        orders = []

    # 2) list_orders paging (fallback)
    if not orders:
        try:
            if hasattr(api, "list_orders"):
                limit = 50
                got_any = False
                for _status in ("new", "open", None):
                    offset = 0
                    page_guard = 0
                    while True:
                        page_guard += 1
                        if page_guard > 20:
                            break
                        try:
                            if _status is None:
                                rr = api.list_orders(limit=limit, offset=offset)
                            else:
                                rr = api.list_orders(status=_status, limit=limit, offset=offset)
                        except Exception:
                            rr = None
                        data = (rr or {}).get("data") if isinstance(rr, dict) else None
                        if not isinstance(data, dict):
                            break
                        rows = data.get("results")
                        if rows is None and isinstance(data, list):
                            rows = data
                        if not isinstance(rows, list):
                            rows = []
                        if rows:
                            got_any = True
                            orders.extend(rows)
                        try:
                            if len(rows) < int(limit):
                                break
                        except Exception:
                            break
                        try:
                            if not data.get("next"):
                                break
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                        offset += int(limit)
                    if got_any:
                        break
        except Exception:
            orders = orders

    locked_acc = {}
    def _acc(asset: str, amt):
        a = str(asset or "").upper().strip()
        if not a:
            return
        try:
            cur = locked_acc.get(a, _to_dec("0"))
            locked_acc[a] = _to_dec(cur) + _to_dec(amt)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    for o in (orders or []):
        if not isinstance(o, dict):
            continue
        try:
            side = str(o.get("side") or o.get("type") or "").lower().strip()
        except Exception:
            side = ""
        if side not in ("buy", "sell"):
            continue
        try:
            sym = str(o.get("symbol") or o.get("market") or "").upper().strip()
        except Exception:
            sym = ""
        if not sym:
            continue
        base, q = _split_sym(sym)
        base = str(base or "").upper().strip()
        q = str(q or "").upper().strip() or quote

        amt = o.get("amount")
        filled = o.get("filled_amount")
        if filled is None:
            filled = o.get("filled")
        if filled is None:
            filled = o.get("executed")
        if filled is None:
            filled = 0

        rem = o.get("remaining")
        if rem is None:
            rem = o.get("remain")
        if rem is None:
            rem = o.get("remaining_amount")
        if rem is None:
            try:
                rem = _to_dec(amt) - _to_dec(filled)
            except Exception:
                rem = _to_dec("0")
        remd = _to_dec(rem)
        try:
            if Decimal is not None and remd <= Decimal("0"):
                continue
        except Exception:
            try:
                if float(remd or 0.0) <= 0.0:
                    continue
            except Exception:
                continue

        if side == "sell":
            _acc(base, remd)
        else:
            pr = o.get("price")
            if pr is None:
                pr = o.get("rate")
            prd = _to_dec(pr)
            try:
                qv = remd * prd
            except Exception:
                qv = _to_dec("0")
            _acc(q, qv)

    out2 = {}
    for k, v in (locked_acc or {}).items():
        try:
            ak = str(k or "").upper().strip()
        except Exception:
            continue
        if not ak:
            continue
        try:
            if ak == "BTC":
                out2["BTC"] = format(_q8(v), ".8f")
            else:
                fv = float(_to_dec(v))
                if fv > 0.0:
                    out2[ak] = fv
        except Exception:
            continue

    try:
        _c[wn] = dict(out2)
        _ts[wn] = float(now or 0.0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return dict(out2)

# Attach locked-balance v4 to all known live bot classes (safe if absent).
try:
    for _cn in ("PP5LiveTripleWallet", "PP5LiveTripleWalletPro", "PP5LiveTripleWalletInstitutional", "PP5LiveTripleWalletFundGrade", "PP5LiveTripleWalletMega", "PP5LiveTripleWalletUltra"):
        _cls = globals().get(_cn)
        if _cls is not None:
            try:
                setattr(_cls, "_pp_locked_balances", _pp20260102__locked_balances_v4)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

