# =============================================================================
# PP_UI_MICRO_BALANCE_FIX_20260102
# هدف: نمایش درست مقادیر خیلی خیلی کوچک (micro balances) در داشبورد/پنل کیف‌پول
# - بدون دست زدن به توکن‌ها
# - فقط UI/نمایش (wallet_snapshot / wallet_panel)
# =============================================================================
try:
    import re as _ppui_re
except Exception:
    _ppui_re = None  # type: ignore

try:
    from decimal import Decimal as _ppui_D, getcontext as _ppui_getcontext, InvalidOperation as _ppui_InvalidOp
    _ppui_getcontext().prec = 90
except Exception:
    _ppui_D = None  # type: ignore
    _ppui_InvalidOp = Exception  # type: ignore

def _ppui_to_dec(v):
    """Robust numeric parsing. Supports scientific notation & noisy strings."""
    if _ppui_D is None:
        try:
            return float(v or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0
    try:
        if v is None or isinstance(v, bool):
            return _ppui_D("0")
        if isinstance(v, _ppui_D):
            return v
        if isinstance(v, int):
            return _ppui_D(v)
        if isinstance(v, float):
            return _ppui_D(str(v))
        s = str(v).strip().replace(",", "")
        if not s:
            return _ppui_D("0")
        if _ppui_re is not None:
            m = _ppui_re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", s)
            if m:
                s = m.group(0)
        return _ppui_D(s)
    except Exception:
        try:
            return _ppui_D("0")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0

def _ppui_fmt_num(x) -> str:
    """Human-friendly formatting that keeps micro-amounts visible (no collapse to 0.00000000)."""
    try:
        if _ppui_D is None:
            v = float(x or 0.0)
            av = abs(v)
            if av <= 0.0:
                return "0"
            if av >= 1000.0:
                return f"{v:,.0f}"
            if av >= 1.0:
                s = f"{v:.8f}"
                s = s.rstrip("0").rstrip(".")
                return s or "0"
            if av >= 1e-8:
                s = f"{v:.12f}"
                s = s.rstrip("0").rstrip(".")
                return s or "0"
            s = f"{v:.18f}"
            s = s.rstrip("0").rstrip(".")
            if not s or s in ("0", "-0"):
                s = f"{v:.6e}"
            return s
        d = _ppui_to_dec(x)
        ad = abs(d)
        if ad == _ppui_D("0"):
            return "0"
        if ad >= _ppui_D("1000"):
            try:
                if d == d.to_integral_value():
                    return format(d, ",.0f")
                # 4dp for very large fractional assets
                s = format(d.quantize(_ppui_D("1.0000")), ",f")
                s = s.rstrip("0").rstrip(".")
                return s
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_return")
                return str(d)
        if ad >= _ppui_D("1"):
            s = format(d.quantize(_ppui_D("1.00000000")), "f")
            s = s.rstrip("0").rstrip(".")
            return s or "0"
        if ad >= _ppui_D("0.00000001"):
            s = format(d.quantize(_ppui_D("0.000000000001")), "f")  # 12dp
            s = s.rstrip("0").rstrip(".")
            return s or "0"
        s = format(d.quantize(_ppui_D("0.000000000000000001")), "f")  # 18dp
        s = s.rstrip("0").rstrip(".")
        if not s or s in ("0", "-0"):
            try:
                s = format(d.normalize(), ".6E")
            except Exception:
                s = str(d)
        return s
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return "0"

# --- Patch wallet_snapshot to keep micro assets and avoid 8dp rounding drop ---
try:
    _PPUI_ORIG_WALLET_SNAPSHOT = DashboardManager._wallet_snapshot  # type: ignore[name-defined]
except Exception:
    _PPUI_ORIG_WALLET_SNAPSHOT = None

def _ppui_wallet_snapshot(self, wname: str):  # type: ignore[override]
    out = _PPUI_ORIG_WALLET_SNAPSHOT(self, wname) if callable(_PPUI_ORIG_WALLET_SNAPSHOT) else {}
    try:
        assets = out.get("assets", None)
        items = []
        if isinstance(assets, dict):
            items = list((assets or {}).items())
        elif isinstance(assets, list):
            items = list(assets or [])
        tmp = []
        for k, v in (items or []):
            ak = str(k or "").upper().strip()
            if not ak:
                continue
            d = _ppui_to_dec(v)
            try:
                is_zero = (abs(d) <= 0.0) if _ppui_D is None else (abs(d) == _ppui_D("0"))
            except Exception:
                is_zero = False
            if is_zero:
                continue
            sv = _ppui_fmt_num(d)
            try:
                sortv = abs(d)
            except Exception:
                sortv = 0
            tmp.append((ak, sv, sortv))
        # Sort by value desc then asset name
        try:
            tmp.sort(key=lambda t: (-t[2], t[0]))
        except Exception:
            tmp.sort(key=lambda t: (t[0],))
        if tmp:
            out["assets"] = [(a, s) for (a, s, _sv) in tmp]
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return out

try:
    DashboardManager._wallet_snapshot = _ppui_wallet_snapshot  # type: ignore[name-defined]
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

# --- Patch wallet_panel to never float-round strings back to 8dp (keeps micro values visible) ---
try:
    _PPUI_ORIG_WALLET_PANEL = DashboardManager._wallet_panel  # type: ignore[name-defined]
except Exception:
    _PPUI_ORIG_WALLET_PANEL = None

def _ppui_wallet_panel(self, wname: str):  # type: ignore[override]
    """Same wallet panel but with micro-safe asset formatting."""
    import os
    from rich.panel import Panel
    from rich.table import Table
    from rich.text import Text
    from rich import box

    s = self._wallet_snapshot(wname)
    mode = str(os.getenv("WALLET_PANEL_MODE", "compact") or "compact").strip().lower()
    if mode not in ("compact", "full"):
        mode = "compact"

    if not s.get("ok", True):
        t = Table.grid(padding=(0, 1))
        t.expand = True
        t.add_column(ratio=1)
        t.add_row(Text("OFFLINE", style="bold red"))
        err = str(s.get("err") or "Connection Error")[:200]
        t.add_row(Text(err, style="white"))
        return Panel(t, title=f"{wname}", box=box.SQUARE, padding=(0, 1), style="white on black", expand=True)

    # main metrics
    try:
        eq = float(s.get("eq") or 0.0)
    except Exception:
        eq = 0.0
    try:
        cash = float(s.get("cash") or 0.0)
    except Exception:
        cash = 0.0
    try:
        engaged = float(s.get("engaged") or 0.0)
    except Exception:
        engaged = 0.0
    try:
        steps = int(s.get("open_steps") or 0)
    except Exception:
        steps = 0
    try:
        pnl = float(s.get("pnl") or 0.0)
    except Exception:
        pnl = 0.0

    strat = (s.get("strategy") or "").strip() or "PREDICTING MARKET"
    status = self._status_cell(s)

    # USDT timer label
    ut_s = ""
    try:
        ut = s.get("usdt_timer", None)
        if ut is not None:
            rv = float(ut or 0.0)
            if rv <= 0.0:
                ut_s = "READY"
            else:
                mm = int(rv) // 60
                ss = int(rv) % 60
                ut_s = f"{mm:02d}:{ss:02d}"
    except Exception:
        ut_s = ""

    # Assets summary (single line)
    assets = s.get("assets") or []

    def _fmt_amt(v):
        # If it's already a string, keep it (avoid float-rounding to 8dp).
        try:
            if isinstance(v, str):
                sv = v.strip()
                return sv if sv else "0"
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return _ppui_fmt_num(v)

    a_parts = []
    try:
        for k, v in (assets or [])[:4]:
            a_parts.append(f"{k}:{_fmt_amt(v)}")
        if isinstance(assets, list) and len(assets) > 4:
            a_parts.append(f"+{len(assets) - 4}")
    except Exception:
        a_parts = []

    assets_line = " • ".join(a_parts) if a_parts else "-"

    has_trade = bool(steps and int(steps) > 0)
    if not has_trade:
        pnl_s = "[dim]NO ACTIVE TRADE[/dim]"
    else:
        pnl_style = "green" if pnl >= 0 else "red"
        pnl_s = f"[{pnl_style}]{pnl:+,.0f} TOMAN[/{pnl_style}]"

    # Optional: sanity + buy debug
    try:
        _san = str(s.get("sanity") or "").strip()
    except Exception:
        _san = ""
    try:
        _bd = s.get("buy_debug") or []
    except Exception:
        _bd = []
    # PP9001 extra debug key (if present)
    try:
        _bd2 = s.get("_pp9001_buy_dbg") or []
    except Exception:
        _bd2 = []

    if mode == "compact":
        t = Table.grid(padding=(0, 1))
        t.expand = True
        t.add_column(ratio=1)
        t.add_row(Text.from_markup(f"EQUITY {self._money_short(eq)}  |  CASH {self._money_short(cash)}", style="bold white"))
        line2 = f"ENG {self._money_short(engaged)}  |  STEPS {steps}"
        if ut_s:
            line2 += f"  |  USDT {ut_s}"
        t.add_row(Text(line2, style="white"))
        t.add_row(Text.from_markup(f"P&L {pnl_s}", style="white"))
        t.add_row(Text.from_markup(f"ASSETS {assets_line}", style="white"))
        if _san:
            t.add_row(Text.from_markup(f"[bold red]{_san[:120]}[/bold red]"))
        # Status (SSoT) must remain visible even when BUY DEBUG is present.
        # IMPORTANT: do NOT truncate markup strings (can hide Reason or break Rich markup parsing).
        try:
            t.add_row(Text.from_markup(str(status)[:240], style="white"))
        except Exception:
            t.add_row(Text(str(status)[:240], style="white"))
        try:
            _stg = str(strat or '').strip()
            if _stg:
                if len(_stg) > 96:
                    _stg = _stg[:96] + "…"
                t.add_row(Text(f"STRAT {_stg}", style="dim"))
        except Exception:
            pass

        if _bd:
            t.add_row(Text("BUY DEBUG:", style="bold yellow"))
            for _ln in list(_bd)[:4]:
                t.add_row(Text(str(_ln)[:120], style="dim"))
        if _bd2:
            t.add_row(Text("BUY DEBUG 2:", style="bold yellow"))
            for _ln in list(_bd2)[:4]:
                t.add_row(Text(str(_ln)[:120], style="dim"))

        return Panel(t, title=f"{wname}", box=box.SQUARE, padding=(0, 1), style="white on black", expand=True)

    # Full verbose mode
    t = Table.grid(padding=(0, 1))
    t.expand = True
    t.add_column(justify="left", ratio=1)
    t.add_column(justify="right", ratio=1)
    t.add_row("EQUITY", self._money_short(eq))
    t.add_row("CASH", self._money_short(cash))
    t.add_row("STEPS", str(steps))
    t.add_row("ENGAGED", self._money_short(engaged))
    if ut_s:
        t.add_row("USDT TIMER", ut_s)
    t.add_row("ASSETS", assets_line)
    if _san:
        t.add_row("SANITY", _san[:160])
    if _bd:
        t.add_row("BUY DEBUG", " | ".join([str(x)[:60] for x in list(_bd)[:3]]))
    if _bd2:
        t.add_row("BUY DEBUG 2", " | ".join([str(x)[:60] for x in list(_bd2)[:3]]))
    t.add_row("P&L", Text.from_markup(pnl_s))
    st = f"{status}  {strat}"
    if len(st) > 64:
        st = st[:64] + "…"
    t.add_row("STRATEGY", st)
    return Panel(t, title=f"{wname}", box=box.HEAVY, padding=(0, 1), style="white on black", expand=True)

try:
    DashboardManager._wallet_panel = _ppui_wallet_panel  # type: ignore[name-defined]
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

