# =========================
# PP20260102: OPEN_ORDERS_ALL SUPPORT (NO TOKEN EDITS)
# Reason:
#   _pp_locked_balances_v3 falls back to api.open_orders_all() when /wallet/balance payload
#   doesn't expose locked fields. If ArzPlusAPI lacks open_orders_all(), locked becomes empty
#   and UI TOTAL shows only FREE (e.g., BTC shows 0.00000085 instead of total 0.00016385).
# Fix:
#   Provide ArzPlusAPI.open_orders_all() as a thin wrapper around list_orders(status="new"/"open"),
#   with defensive unwrapping + pagination.
# =========================
try:
    if "ArzPlusAPI" in globals():
        if not hasattr(ArzPlusAPI, "open_orders_all"):
            def _pp20260102__rows_from_payload(_payload):
                if _payload is None:
                    return []
                if isinstance(_payload, list):
                    return _payload
                if not isinstance(_payload, dict):
                    return []
                if isinstance(_payload.get("results"), list):
                    return _payload.get("results") or []
                d = _payload.get("data")
                if isinstance(d, list):
                    return d
                if isinstance(d, dict):
                    if isinstance(d.get("results"), list):
                        return d.get("results") or []
                    if isinstance(d.get("data"), list):
                        return d.get("data") or []
                    if isinstance(d.get("orders"), list):
                        return d.get("orders") or []
                if isinstance(_payload.get("orders"), list):
                    return _payload.get("orders") or []
                return []

            def _pp20260102_open_orders_all(self, status: str = "new", limit: int = 50, max_pages: int = 10) -> dict:
                """Return ALL open orders for this authenticated wallet.

                Output shape: {"ok": bool, "status": int, "data": [order_dict, ...], "error": optional_str}
                """
                try:
                    limit_i = int(limit) if limit is not None else 50
                except Exception:
                    limit_i = 50
                limit_i = max(1, min(200, limit_i))

                try:
                    max_pages_i = int(max_pages) if max_pages is not None else 10
                except Exception:
                    max_pages_i = 10
                max_pages_i = max(1, min(50, max_pages_i))

                def _fetch(_status):
                    out = []
                    offset = 0
                    last_status = 0
                    for _ in range(max_pages_i):
                        try:
                            r = self.list_orders(status=_status, limit=limit_i, offset=offset) if _status else self.list_orders(limit=limit_i, offset=offset)
                        except TypeError:
                            # Some implementations may not accept limit/offset
                            try:
                                r = self.list_orders(status=_status) if _status else self.list_orders()
                            except Exception as e:
                                return {"ok": False, "status": 0, "data": [], "error": str(e)}
                        except Exception as e:
                            return {"ok": False, "status": 0, "data": [], "error": str(e)}

                        if not isinstance(r, dict) or not bool(r.get("ok", False)):
                            try:
                                st = int(r.get("status", 0)) if isinstance(r, dict) else 0
                            except Exception:
                                st = 0
                            return {"ok": False, "status": st, "data": [], "error": (r.get("error") if isinstance(r, dict) else "list_orders_failed")}

                        try:
                            last_status = int(r.get("status", 200) or 200)
                        except Exception:
                            last_status = 200

                        rows = _pp20260102__rows_from_payload(r.get("data"))
                        if not isinstance(rows, list):
                            rows = []
                        # Keep only dict rows
                        rows2 = [o for o in rows if isinstance(o, dict)]
                        out.extend(rows2)

                        # Stop if fewer than page size
                        if len(rows2) < limit_i:
                            break
                        offset += limit_i

                    return {"ok": True, "status": last_status, "data": out}

                # prefer status="new" then fallback to "open"
                r1 = _fetch(status or "new")
                if not bool(r1.get("ok", False)):
                    r2 = _fetch("open")
                    if bool(r2.get("ok", False)):
                        return r2
                return r1

            ArzPlusAPI.open_orders_all = _pp20260102_open_orders_all  # type: ignore[attr-defined]
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


# =========================
# PP_FIX_WALLET_TAG_MATCH (2026-01-02)
# هدف: اصلاح ریشه‌ای نمایش TOTAL (FREE+LOCKED) مخصوصاً BTC در W3
# بدون دستکاری توکن‌ها. فقط منطق فیلتر/تشخیص نام کیف پول در payload.
# =========================
try:
    import re as _pp_fix_re

    def _pp_fix__norm_tag(x):
        try:
            s = str(x or "").strip().lower()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return ""
        try:
            s = _pp_fix_re.sub(r"[^a-z0-9]+", "", s)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return s

    def _pp_fix__digits(x):
        try:
            s = str(x or "")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return ""
        try:
            ds = _pp_fix_re.findall(r"\d+", s)
        except Exception:
            ds = []
        return "".join(ds or [])

    def _pp_fix__wallet_match(tag, wallet_name):
        # Fuzzy match wallet tags like 'wallet_3', 'W3', '3', 'W03'
        try:
            wn = _pp_fix__norm_tag(wallet_name)
            tg = _pp_fix__norm_tag(tag)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False
        if not wn or not tg:
            return False
        if wn == tg:
            return True

        dw = _pp_fix__digits(wn)
        dt = _pp_fix__digits(tg)
        if dw and dt and dw == dt:
            return True

        if dw:
            if tg == ("w" + dw) or tg == ("wallet" + dw):
                return True
            if wn.startswith("w") and (tg.endswith(dw) and (tg.startswith("wallet") or tg.startswith("w"))):
                return True
        if dt:
            if wn == ("w" + dt) or wn == ("wallet" + dt):
                return True
            if tg.startswith("w") and (wn.endswith(dt) and (wn.startswith("wallet") or wn.startswith("w"))):
                return True
        return False

    def _pp_fix__select_wallet_payload(payload, wallet_name):
        # Try to select payload slice for a specific wallet, preserving original shape.
        rows = payload
        wn = str(wallet_name or "").strip()
        if not wn:
            return rows

        if isinstance(rows, dict):
            try:
                if wn in rows and isinstance(rows.get(wn), (list, dict)):
                    return rows.get(wn)
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            try:
                for k, v in (rows or {}).items():
                    if not isinstance(v, (list, dict)):
                        continue
                    ks = str(k or "")
                    if ("wallet" in ks.lower()) or ks.strip().upper().startswith("W") or _pp_fix__digits(ks):
                        if _pp_fix__wallet_match(ks, wn):
                            return v
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            try:
                for key in ("wallet", "wallets", "results", "balances", "data"):
                    if key in rows and isinstance(rows.get(key), (list, dict)):
                        rows = rows.get(key)
                        break
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            if isinstance(rows, dict):
                try:
                    if wn in rows and isinstance(rows.get(wn), (list, dict)):
                        return rows.get(wn)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                try:
                    for k, v in (rows or {}).items():
                        if isinstance(v, (list, dict)) and _pp_fix__wallet_match(k, wn):
                            return v
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")

        if isinstance(rows, list):
            try:
                filt = []
                for it in (rows or []):
                    if not isinstance(it, dict):
                        continue
                    wtag = it.get("wallet") or it.get("wallet_name") or it.get("account") or it.get("portfolio")
                    if wtag is None or (not str(wtag).strip()):
                        continue
                    if _pp_fix__wallet_match(wtag, wn):
                        filt.append(it)
                if filt:
                    return filt
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")

        return rows

    # ---- Wrap TOTAL extractor with wallet-tag fuzzy matching ----
    try:
        _PP_FIX__ORIG_EXTRACT_TOTAL = globals().get("_pp7826__extract_total_from_wallet_payload", None)
    except Exception:
        _PP_FIX__ORIG_EXTRACT_TOTAL = None

    if callable(_PP_FIX__ORIG_EXTRACT_TOTAL):
        def _pp7826__extract_total_from_wallet_payload(payload, wallet_name=None):  # noqa: F811
            try:
                rows = _pp_fix__select_wallet_payload(payload, wallet_name)
            except Exception:
                rows = payload
            try:
                return _PP_FIX__ORIG_EXTRACT_TOTAL(rows, None)
            except Exception:
                try:
                    return _PP_FIX__ORIG_EXTRACT_TOTAL(payload, wallet_name)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return {}

        globals()["_pp7826__extract_total_from_wallet_payload"] = _pp7826__extract_total_from_wallet_payload

    # ---- Wrap LOCKED extractor with wallet-tag fuzzy matching (backward compatible) ----
    try:
        _PP_FIX__ORIG_EXTRACT_LOCKED = globals().get("_pp7826__extract_locked_from_wallet_payload", None)
    except Exception:
        _PP_FIX__ORIG_EXTRACT_LOCKED = None

    if callable(_PP_FIX__ORIG_EXTRACT_LOCKED):
        def _pp7826__extract_locked_from_wallet_payload(payload, wallet_name=None):  # noqa: F811
            try:
                rows = _pp_fix__select_wallet_payload(payload, wallet_name)
            except Exception:
                rows = payload
            try:
                return _PP_FIX__ORIG_EXTRACT_LOCKED(rows)
            except Exception:
                try:
                    return _PP_FIX__ORIG_EXTRACT_LOCKED(payload)
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_return")
                    return {}

        globals()["_pp7826__extract_locked_from_wallet_payload"] = _pp7826__extract_locked_from_wallet_payload

    # ---- Improve per-wallet locked balances accuracy (if class exists) ----
    try:
        _cls = globals().get("PP5LiveTripleWallet")
        if _cls is not None and hasattr(_cls, "_pp_locked_balances"):
            _orig_lb = getattr(_cls, "_pp_locked_balances")
            def _pp_fix__locked_balances(self, api, wname):  # noqa: F811
                try:
                    r = api.wallet_balance() if hasattr(api, "wallet_balance") else None
                    if isinstance(r, dict) and bool(r.get("ok")):
                        payload = r.get("data")
                        lm = globals().get("_pp7826__extract_locked_from_wallet_payload")
                        if callable(lm):
                            out = lm(payload, wname)
                            if isinstance(out, dict) and out:
                                return out
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                return _orig_lb(self, api, wname)
            setattr(_cls, "_pp_locked_balances", _pp_fix__locked_balances)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


# =============================================================================
# PP20260102_W3_BTC_TOTAL_ROOTFIX
# هدف: بدون دست زدن به توکن‌ها یا منطق معاملات (Free)، نمایش TOTAL (Free+Locked)
# را برای داشبورد/Equity اصلاح می‌کند، مخصوصاً حالتی که API مقدار "balance"
# را به معنی AVAILABLE برمی‌گرداند و قفل‌ها در فیلدهای دیگری هستند.
# =============================================================================
try:
    from decimal import Decimal as _ppT_D, getcontext as _ppT_getcontext
    _ppT_getcontext().prec = 90
except Exception:
    _ppT_D = None  # type: ignore

try:
    import re as _ppT_re
except Exception:
    _ppT_re = None  # type: ignore

def _ppT_num(x, default="0"):
    """Robust Decimal parser (supports scientific notation, strips noise)."""
    if _ppT_D is None:
        try:
            return float(x or 0.0)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0
    try:
        if x is None or isinstance(x, bool):
            return _ppT_D(default)
        if isinstance(x, _ppT_D):
            return x
        if isinstance(x, (int, float)):
            return _ppT_D(str(x))
        s = str(x).strip().replace(",", "").replace("−", "-").replace("–", "-")
        if not s:
            return _ppT_D(default)
        if _ppT_re is not None:
            m = _ppT_re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", s)
            if m:
                s = m.group(0)
        return _ppT_D(s or default)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return _ppT_D(default) if _ppT_D is not None else 0.0

def _ppT_wallet_norm(s: str) -> str:
    try:
        s = str(s or "").strip().upper()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return ""
    if not s:
        return ""
    try:
        return "".join(ch for ch in s if ch.isalnum())
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return s

def _ppT_wallet_digits(s: str) -> str:
    s = _ppT_wallet_norm(s)
    if not s:
        return ""
    try:
        return "".join(ch for ch in s if ch.isdigit())
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return ""

def _ppT_wallet_match(tag, wn) -> bool:
    if not wn:
        return True
    wn0 = _ppT_wallet_norm(wn)
    if not wn0:
        return True
    tg0 = _ppT_wallet_norm(tag)
    if not tg0:
        return False
    if tg0 == wn0:
        return True
    d1 = _ppT_wallet_digits(tg0)
    d2 = _ppT_wallet_digits(wn0)
    return bool(d1 and d2 and d1 == d2)

# Key dictionaries (broad coverage)
_ppT_FREE_KEYS = (
    "available", "free", "avail", "usable", "spendable",
    "availableBalance", "available_balance", "freeBalance", "free_balance",
    "available_amount", "usable_amount"
)
_ppT_TOTAL_KEYS = (
    "total", "Total", "TOTAL", "balance_total", "total_balance", "totalBalance",
    "balanceTotal", "totalAmount", "amount_total", "value_total"
)
_ppT_LOCK_KEYS = (
    "locked", "lock", "freeze", "frozen", "inOrder", "in_order", "onOrder", "on_order",
    "onOrders", "on_orders", "blocked", "hold", "reserved",
    "lockedBalance", "locked_balance", "freezeBalance", "freeze_balance", "frozenBalance", "frozen_balance",
    "blockedAmount", "blocked_amount", "holdAmount", "hold_amount", "reservedAmount", "reserved_amount",
    "inOrderAmount", "in_order_amount", "onOrderAmount", "on_order_amount"
)
# ambiguous scalar "balance" often means AVAILABLE in some APIs
_ppT_BAL_SCALAR_KEYS = ("balance", "amount", "value")

def _ppT_g(row: dict, bal: dict, keys):
    for k in keys:
        try:
            if k in row and row.get(k) is not None:
                return row.get(k)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
    for k in keys:
        try:
            if isinstance(bal, dict) and k in bal and bal.get(k) is not None:
                return bal.get(k)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
    return None

def _ppT_extract_row(row: dict, wallet_name=None):
    """Return (asset, free, locked, total) as Decimal/float."""
    if not isinstance(row, dict):
        return None, None, None, None

    # wallet filter
    try:
        wn = str(wallet_name or "").strip()
    except Exception:
        wn = ""
    if wn:
        try:
            wtag = row.get("wallet") or row.get("wallet_name") or row.get("walletId") or row.get("wallet_id") \
                or row.get("account") or row.get("portfolio") or row.get("name") or row.get("label")
            if wtag is not None and str(wtag).strip() and (not _ppT_wallet_match(wtag, wn)):
                return None, None, None, None
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

    # asset symbol
    a = row.get("asset") or row.get("coin") or row.get("currency") or row.get("symbol") or row.get("code") or row.get("name")
    try:
        a = str(a or "").strip().upper()
    except Exception:
        a = ""
    if not a:
        return None, None, None, None

    bal = row.get("balance")
    bal2 = bal if isinstance(bal, dict) else {}

    free_v = _ppT_g(row, bal2, _ppT_FREE_KEYS)
    locked_v = _ppT_g(row, bal2, _ppT_LOCK_KEYS)
    total_v = _ppT_g(row, bal2, _ppT_TOTAL_KEYS)
    # scalar candidate balance/amount/value
    cand_bal = _ppT_g(row, bal2, _ppT_BAL_SCALAR_KEYS)

    # avoid dict-as-number
    if isinstance(free_v, dict): free_v = None
    if isinstance(locked_v, dict): locked_v = None
    if isinstance(total_v, dict):
        try:
            total_v = total_v.get("total") or total_v.get("balance") or total_v.get("amount") or total_v.get("value")
        except Exception:
            total_v = None
    if isinstance(cand_bal, dict): cand_bal = None

    fd = _ppT_num(free_v, "0")
    ld = _ppT_num(locked_v, "0")
    td = _ppT_num(total_v, "0")

    # If locked exists, TOTAL should at least be FREE+LOCKED (handles "balance"==available bug)
    try:
        if _ppT_D is not None:
            # if total missing, fall back to candidate scalar
            if td <= _ppT_D("0"):
                td = _ppT_num(cand_bal, "0")
            # core fix:
            if ld > _ppT_D("0") and fd >= _ppT_D("0"):
                t2 = fd + ld
                if t2 > td:
                    td = t2
            # if locked missing but total>free, infer locked
            if ld <= _ppT_D("0") and td > fd:
                ld = td - fd
            # if total still missing, set to free
            if td <= _ppT_D("0") and fd > _ppT_D("0"):
                td = fd
            # clamp negatives
            if fd < _ppT_D("0"): fd = _ppT_D("0")
            if ld < _ppT_D("0"): ld = _ppT_D("0")
            if td < _ppT_D("0"): td = _ppT_D("0")
        else:
            # float mode
            if float(td or 0.0) <= 0.0:
                td = _ppT_num(cand_bal, "0")
            if float(ld or 0.0) > 0.0:
                t2 = float(fd or 0.0) + float(ld or 0.0)
                if t2 > float(td or 0.0):
                    td = t2
            if float(ld or 0.0) <= 0.0 and float(td or 0.0) > float(fd or 0.0):
                ld = float(td or 0.0) - float(fd or 0.0)
            if float(td or 0.0) <= 0.0 and float(fd or 0.0) > 0.0:
                td = float(fd or 0.0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    return a, fd, ld, td

def _ppT_unwrap(obj):
    cur = obj
    for _ in range(8):
        if isinstance(cur, dict):
            moved = False
            for k in ("data","result","results","wallet","wallets","balances","items","list"):
                try:
                    v = cur.get(k)
                except Exception:
                    v = None
                if isinstance(v, (list, dict)):
                    cur = v
                    moved = True
                    break
            if moved:
                continue
        break
    return cur

def _ppT_select_wallet(rows, wallet_name):
    if not wallet_name or not isinstance(rows, list):
        return rows
    wn = str(wallet_name or "").strip()
    if not wn:
        return rows
    chosen = None
    for it in (rows or []):
        if not isinstance(it, dict):
            continue
        wtag = it.get("wallet") or it.get("wallet_name") or it.get("walletId") or it.get("wallet_id") \
            or it.get("account") or it.get("portfolio") or it.get("name") or it.get("label")
        if wtag is not None and str(wtag).strip() and _ppT_wallet_match(wtag, wn):
            chosen = it
            break
    if isinstance(chosen, dict):
        for k in ("balances","assets","coins","currencies","items","data","result","results","wallet"):
            if k in chosen and isinstance(chosen.get(k), (list, dict)):
                return _ppT_unwrap(chosen.get(k))
        return chosen
    return rows

# --- Override TOTAL extractor (used by balances_total_cache step #1) ---
def _pp7826__extract_total_from_wallet_payload(payload, wallet_name=None) -> dict:  # type: ignore[override]
    out = {}
    try:
        rows = _ppT_unwrap(payload)
        rows = _ppT_select_wallet(rows, wallet_name)
        # dict mapping asset->scalar or asset->dict
        if isinstance(rows, dict):
            # scalar mapping
            try:
                if all(not isinstance(v, (list, dict)) for v in (rows or {}).values()):
                    for k, v in (rows or {}).items():
                        a = str(k or "").strip().upper()
                        if not a:
                            continue
                        tv = _ppT_num(v, "0")
                        if (_ppT_D is None and float(tv or 0.0) > 0.0) or (_ppT_D is not None and tv > _ppT_D("0")):
                            out[a] = float(tv)
                    return out
            except Exception as _pp200_e:
                _pp200_report(_pp200_e, tag="exc_pass")
            # dict-of-assets -> list-of-rows
            tmp = []
            for k, v in (rows or {}).items():
                if isinstance(v, dict):
                    vv = dict(v)
                    vv.setdefault("asset", k)
                    tmp.append(vv)
            rows = tmp

        if isinstance(rows, list):
            for it in (rows or []):
                if not isinstance(it, dict):
                    continue
                a, fd, ld, td = _ppT_extract_row(it, wallet_name)
                if not a:
                    continue
                # ensure TOTAL >= FREE+LOCKED when locked present
                try:
                    if _ppT_D is not None:
                        if td is not None and td > _ppT_D("0"):
                            out[a] = float(td)
                    else:
                        if td is not None and float(td or 0.0) > 0.0:
                            out[a] = float(td)
                except Exception:
                    continue
        return out
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return out

# --- Override LOCKED extractor (used by locked-balance logic) ---
def _pp7826__extract_locked_from_wallet_payload(payload, wallet_name=None) -> dict:  # type: ignore[override]
    out = {}
    try:
        rows = _ppT_unwrap(payload)
        rows = _ppT_select_wallet(rows, wallet_name)
        # normalize dict-of-assets to list
        if isinstance(rows, dict):
            tmp = []
            for k, v in (rows or {}).items():
                if isinstance(v, dict):
                    vv = dict(v)
                    vv.setdefault("asset", k)
                    tmp.append(vv)
            rows = tmp if tmp else rows

        if isinstance(rows, list):
            for it in (rows or []):
                if not isinstance(it, dict):
                    continue
                a, fd, ld, td = _ppT_extract_row(it, wallet_name)
                if not a:
                    continue
                # prefer explicit locked if available; else infer from total-free
                if _ppT_D is not None:
                    if ld is not None and ld > _ppT_D("0"):
                        out[a] = ld
                else:
                    if float(ld or 0.0) > 0.0:
                        out[a] = float(ld)
        return out
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return out

# --- Override map-extractor used by _ppf_balances_free (TOTAL/FREE/LOCKED caching) ---
def _ppf_extract_balance_maps(payload):  # type: ignore[override]
    free_map = {}
    total_map = {}
    locked_map = {}
    try:
        rows = _ppT_unwrap(payload)
        # allow dict-of-assets
        if isinstance(rows, dict):
            # containers might already be unwrapped; if still dict-of-assets:
            # if it looks like {BTC:{...}, ...}
            if any(isinstance(v, dict) for v in (rows or {}).values()):
                tmp = []
                for k, v in (rows or {}).items():
                    if isinstance(v, dict):
                        vv = dict(v)
                        vv.setdefault("asset", k)
                        tmp.append(vv)
                rows = tmp
        if isinstance(rows, list):
            for it in (rows or []):
                if not isinstance(it, dict):
                    continue
                a, fd, ld, td = _ppT_extract_row(it, None)
                if not a:
                    continue
                # store (as Decimal when possible)
                if _ppT_D is not None:
                    free_map[a] = fd if fd is not None else _ppT_D("0")
                    total_map[a] = td if td is not None else (free_map[a] + (ld if ld is not None else _ppT_D("0")))
                    if ld is not None and ld > _ppT_D("0"):
                        locked_map[a] = ld
                else:
                    free_map[a] = float(fd or 0.0)
                    total_map[a] = float(td or 0.0)
                    if float(ld or 0.0) > 0.0:
                        locked_map[a] = float(ld or 0.0)
        elif isinstance(rows, dict):
            # scalar dict mapping => treat as free/total
            for k, v in (rows or {}).items():
                ak = str(k or "").strip().upper()
                if not ak:
                    continue
                tv = _ppT_num(v, "0")
                if _ppT_D is not None:
                    free_map[ak] = tv
                    total_map[ak] = tv
                else:
                    free_map[ak] = float(tv or 0.0)
                    total_map[ak] = float(tv or 0.0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return free_map, total_map, locked_map

# Ensure globals point to latest overrides
try:
    globals()["_pp7826__extract_total_from_wallet_payload"] = _pp7826__extract_total_from_wallet_payload
    globals()["_pp7826__extract_locked_from_wallet_payload"] = _pp7826__extract_locked_from_wallet_payload
    globals()["_ppf_extract_balance_maps"] = _ppf_extract_balance_maps
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

# --- Final locked-balances method: prefer payload-derived locked, then cached total-free ---
def _ppT_locked_balances_final(self, api, wname: str):  # type: ignore[override]
    # 1) cached locked map from last balance call (fast, no extra API calls)
    try:
        lm = getattr(api, "_pp_last_balance_locked", None)
        if isinstance(lm, dict) and lm:
            out = {}
            for k, v in lm.items():
                ak = str(k or "").upper().strip()
                if not ak:
                    continue
                try:
                    if float(v or 0.0) > 0.0:
                        out[ak] = float(v or 0.0)
                except Exception:
                    continue
            if out:
                return out
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # 2) cached total-free
    try:
        tm = getattr(api, "_pp_last_balance_total", None)
        fm = getattr(api, "_pp_last_balance_free", None)
        if isinstance(tm, dict) and isinstance(fm, dict) and tm:
            out = {}
            for k, tv in tm.items():
                ak = str(k or "").upper().strip()
                if not ak:
                    continue
                try:
                    td = float(tv or 0.0)
                    fd = float(fm.get(ak, 0.0) or 0.0)
                    ld = td - fd
                    if ld > 0.0:
                        out[ak] = float(ld)
                except Exception:
                    continue
            if out:
                return out
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # 3) direct payload extraction (one call)
    try:
        r = api.wallet_balance() if hasattr(api, "wallet_balance") else None
        if isinstance(r, dict) and bool(r.get("ok")):
            payload = r.get("data")
            lm = _pp7826__extract_locked_from_wallet_payload(payload, wname)
            if isinstance(lm, dict) and lm:
                out = {}
                for k, v in lm.items():
                    ak = str(k or "").upper().strip()
                    if not ak:
                        continue
                    try:
                        fv = float(v) if v is not None else 0.0
                        if fv > 0.0:
                            out[ak] = fv
                    except Exception:
                        continue
                if out:
                    return out
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # 4) fallback to existing implementation if present
    try:
        _orig = getattr(self, "_pp_locked_balances_orig", None)
        if callable(_orig):
            return _orig(api, wname)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return {}

# Attach final method (UI/accounting only)
try:
    _cls_names = ("PP5LiveTripleWallet", "PP5LiveTripleWalletPro", "PP5LiveTripleWalletInstitutional",
                  "PP5LiveTripleWalletFundGrade", "PP5LiveTripleWalletMega", "PP5LiveTripleWalletUltra")
    for _cn in _cls_names:
        _C = globals().get(_cn)
        if _C is None:
            continue
        try:
            if not hasattr(_C, "_pp_locked_balances_orig"):
                setattr(_C, "_pp_locked_balances_orig", getattr(_C, "_pp_locked_balances", None))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        try:
            setattr(_C, "_pp_locked_balances", _ppT_locked_balances_final)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")

