# =============================================================================
# PP_HARMONY_LAYER (2026-01-02) — conflict resolver + orphan gene linker
# - هدف: مدیریت تداخل/تضاد بین پچ‌ها، یکپارچه‌سازی خروجی‌ها، و اتصال ژن‌های یتیم
# - NOTE: Tokens are NOT modified here (read-only; no edits to token strings).
# =============================================================================
try:
    _PP_HARMONY_LAYER_APPLIED  # type: ignore[name-defined]
except Exception:
    _PP_HARMONY_LAYER_APPLIED = True  # type: ignore[assignment]

    def _ppH_env_true(key: str, default: str = "0") -> bool:
        try:
            import os as _ppH_os
            v = str(_ppH_os.getenv(key, default) or default).strip().lower()
            return v in ("1", "true", "yes", "on")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False

    def _ppH_dedupe_items(items):
        """
        Deduplicate status/report items created by multiple stacked patches.
        - If items are (k,v) pairs: keep first-seen order, but last value wins.
        - If items are strings: dedupe exact strings, keep order.
        """
        if not items:
            return []
        try:
            arr = list(items)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return []
        # Tuple pairs
        try:
            if arr and isinstance(arr[0], (tuple, list)) and len(arr[0]) >= 1:
                order = []
                store = {}
                for it in arr:
                    try:
                        k = str(it[0])
                        v = "" if len(it) < 2 else it[1]
                        if k not in store:
                            order.append(k)
                        store[k] = v
                    except Exception:
                        continue
                out = []
                for k in order:
                    try:
                        out.append((k, store.get(k, "")))
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                return out
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        # Strings
        seen = set()
        out = []
        for it in arr:
            try:
                s = str(it)
            except Exception:
                continue
            if s in seen:
                continue
            seen.add(s)
            out.append(s)
        return out

    # ---- LegacyIntelligenceManager: widen orphan discovery (safe & optional execution) ----
    try:
        import inspect as _ppH_inspect
    except Exception:  # pragma: no cover
        _ppH_inspect = None

    def _ppH_is_safe_orphan_name(nm: str) -> bool:
        """Heuristic filter to avoid orphans that look like trading/order side-effects."""
        try:
            s = str(nm or "").lower()
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False
        bad = ("buy", "sell", "order", "wallet", "token", "cancel", "withdraw", "deposit", "api", "login", "auth")
        if any(b in s for b in bad):
            return False
        return True

    def _ppH_safe_orphan_list(names):
        out = []
        for nm in (names or []):
            try:
                if not _ppH_is_safe_orphan_name(nm):
                    continue
                fn = globals().get(str(nm))
                if not callable(fn):
                    continue
                out.append(fn)
            except Exception:
                continue
        # stable unique
        uniq = []
        seen = set()
        for fn in out:
            try:
                nm = str(getattr(fn, "__name__", "") or "")
            except Exception:
                nm = ""
            key = nm or str(id(fn))
            if key in seen:
                continue
            seen.add(key)
            uniq.append(fn)
        return uniq

    # Patch __init__ to store orphan pool (does not execute by default)
    try:
        _LIM = globals().get("LegacyIntelligenceManager", None)
        if _LIM is not None and hasattr(_LIM, "__init__"):
            _ppH_orig_lim_init = _LIM.__init__
            if callable(_ppH_orig_lim_init) and not getattr(_ppH_orig_lim_init, "_ppH_wrapped", False):
                def _ppH_lim_init(self, *a, **k):  # noqa: ANN001
                    _ppH_orig_lim_init(self, *a, **k)
                    try:
                        # collect *all* discovered orphans as an available pool
                        names = list(getattr(self, "orphans", []) or [])
                        pool = _ppH_safe_orphan_list(names)
                        setattr(self, "orphan_funcs_all", pool)
                    except Exception:
                        setattr(self, "orphan_funcs_all", [])
                try:
                    _ppH_lim_init._ppH_wrapped = True  # type: ignore[attr-defined]
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                _LIM.__init__ = _ppH_lim_init
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Patch evaluate: optional execution of orphan pool (low weight; capped)
    try:
        _LIM = globals().get("LegacyIntelligenceManager", None)
        if _LIM is not None and hasattr(_LIM, "evaluate"):
            _ppH_orig_eval = getattr(_LIM, "evaluate")
            if callable(_ppH_orig_eval) and not getattr(_ppH_orig_eval, "_ppH_wrapped", False):
                def _ppH_eval(self, sym, symst, bid, ask, mid, depth_data):  # noqa: ANN001
                    # run existing pipeline first
                    delta, contrib = _ppH_orig_eval(self, sym, symst, bid, ask, mid, depth_data)
                    try:
                        delta = float(delta or 0.0)
                    except Exception:
                        delta = 0.0
                    try:
                        contrib = list(contrib or [])
                    except Exception:
                        contrib = []

                    # Optional: run orphan pool with very low weight and strict cap
                    if _ppH_env_true("PP170_ORPHAN_EXEC", default="0"):
                        try:
                            max_n = int(__import__("os").getenv("PP170_ORPHAN_MAX", "10") or 10)
                        except Exception:
                            max_n = 10
                        try:
                            w = float(__import__("os").getenv("PP170_ORPHAN_W", "0.03") or 0.03)
                        except Exception:
                            w = 0.03
                        max_n = max(0, min(25, int(max_n)))
                        w = max(0.0, min(0.15, float(w)))

                        pool = []
                        try:
                            pool = list(getattr(self, "orphan_funcs_all", []) or [])
                        except Exception:
                            pool = []

                        # exclude the already-running legacy_funcs to avoid double calls
                        try:
                            already = set(str(getattr(f, "__name__", "")) for f in (getattr(self, "legacy_funcs", []) or []))
                        except Exception:
                            already = set()

                        ran = 0
                        extra = []
                        for fn in (pool or []):
                            if ran >= max_n:
                                break
                            nm = str(getattr(fn, "__name__", "orphan"))
                            if nm in already:
                                continue
                            try:
                                # best-effort safe call (re-use existing helper if present)
                                sc = globals().get("_pp170__safe_call")
                                out = sc(fn, bot=getattr(self, "bot", None), sym=sym, symst=symst, bid=bid, ask=ask, mid=mid, depth_data=depth_data) if callable(sc) else fn()
                                if isinstance(out, (int, float)):
                                    vv = float(out)
                                    delta += w * vv
                                    if len(extra) < 6:
                                        extra.append((f"ORPH:{nm}", f"{vv:+.2f}"))
                                    ran += 1
                                elif isinstance(out, dict) and "score" in out:
                                    try:
                                        vv = float(out.get("score") or 0.0)
                                        delta += w * vv
                                        if len(extra) < 6:
                                            extra.append((f"ORPH:{nm}", f"{vv:+.2f}"))
                                        ran += 1
                                    except Exception as _pp200_e:
                                        _pp200_report(_pp200_e, tag="exc_pass")
                                elif isinstance(out, (tuple, list)) and out and isinstance(out[0], (int, float)):
                                    vv = float(out[0])
                                    delta += w * vv
                                    if len(extra) < 6:
                                        extra.append((f"ORPH:{nm}", f"{vv:+.2f}"))
                                    ran += 1
                            except Exception:
                                # silently skip noisy orphans
                                continue
                        if extra:
                            contrib.extend(extra)
                    # clamp like original
                    try:
                        delta = max(-0.75, min(0.75, float(delta)))
                    except Exception:
                        delta = 0.0
                    # return with updated contrib
                    return float(delta), contrib

                try:
                    _ppH_eval._ppH_wrapped = True  # type: ignore[attr-defined]
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                setattr(_LIM, "evaluate", _ppH_eval)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Patch status_items: dedupe + expose orphan pool state (without leaking secrets)
    try:
        _LIM = globals().get("LegacyIntelligenceManager", None)
        if _LIM is not None and hasattr(_LIM, "status_items"):
            _ppH_orig_status = getattr(_LIM, "status_items")
            if callable(_ppH_orig_status) and not getattr(_ppH_orig_status, "_ppH_wrapped", False):
                def _ppH_status_items(self, *a, **k):  # noqa: ANN001
                    try:
                        items = list(_ppH_orig_status(self, *a, **k) or [])
                    except Exception:
                        items = []
                    # add orphan pool status (available + exec flag)
                    try:
                        pool = list(getattr(self, "orphan_funcs_all", []) or [])
                        exec_on = "ON" if _ppH_env_true("PP170_ORPHAN_EXEC", default="0") else "OFF"
                        items.append(("Orphans-Available", str(len(pool))))
                        items.append(("Orphans-Exec", exec_on))
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                    return _ppH_dedupe_items(items)
                try:
                    _ppH_status_items._ppH_wrapped = True  # type: ignore[attr-defined]
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                setattr(_LIM, "status_items", _ppH_status_items)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # Optional: provide a compact "gene map" helper for debugging (no secrets)
    def PP_GENE_MAP() -> dict:
        """
        Returns a minimal map of active 'genes' (features/modules). Never includes token values.
        """
        m = {}
        try:
            bot_cls = globals().get("PP5LiveTripleWallet", None)
            m["PP5LiveTripleWallet"] = bool(bot_cls)
        except Exception:
            m["PP5LiveTripleWallet"] = False
        try:
            m["PP170_LegacyIntel"] = bool(globals().get("LegacyIntelligenceManager"))
        except Exception:
            m["PP170_LegacyIntel"] = False
        try:
            m["PP180_LegacyResurrectionHub"] = bool(globals().get("_PP180LegacyResurrectionHub"))
        except Exception:
            m["PP180_LegacyResurrectionHub"] = False
        try:
            m["PP113_DynamicScanner"] = bool(globals().get("_pp113_dynamic_scan"))
        except Exception:
            m["PP113_DynamicScanner"] = False
        try:
            m["PP727_OrderStringForce"] = bool(globals().get("_pp727__force_order_strings"))
        except Exception:
            m["PP727_OrderStringForce"] = False
        try:
            m["PP8081_RiskAppetiteBump"] = bool(globals().get("_pp8081_init"))
        except Exception:
            m["PP8081_RiskAppetiteBump"] = False
        try:
            m["HarmonyApplied"] = True
        except Exception:
            m["HarmonyApplied"] = False
        return m


# ============================================================
# PP FULL POWER DECISION LAYER (v2)
# - استفاده از همه‌ی ژن‌ها (حتی یتیم‌ها) برای تایید تصمیم‌ها
# - حل تضاد سیگنال‌ها + پایش خطا/کندی
# - بدون دست‌زدن به هیچ توکن/کلید/سکرت
# ============================================================
try:
    _PP_FULL_POWER_LAYER_APPLIED  # type: ignore[name-defined]
except Exception:
    _PP_FULL_POWER_LAYER_APPLIED = True  # type: ignore[assignment]

    import os as _ppFP_os
    import time as _ppFP_time

    def _ppFP_env_true(key: str, default: str = "0") -> bool:
        try:
            v = str(_ppFP_os.getenv(key, default) or default).strip().lower()
            return v in ("1", "true", "yes", "on")
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return False

    def _ppFP_env_float(key: str, default: float, lo: float | None = None, hi: float | None = None) -> float:
        try:
            v = float(_ppFP_os.getenv(key, str(default)) or default)
        except Exception:
            v = float(default)
        if lo is not None:
            v = max(float(lo), float(v))
        if hi is not None:
            v = min(float(hi), float(v))
        return float(v)

    def _ppFP_env_int(key: str, default: int, lo: int | None = None, hi: int | None = None) -> int:
        try:
            v = int(float(_ppFP_os.getenv(key, str(default)) or default))
        except Exception:
            v = int(default)
        if lo is not None:
            v = max(int(lo), int(v))
        if hi is not None:
            v = min(int(hi), int(v))
        return int(v)

    def _ppFP_clamp(x: float, lo: float = -1.0, hi: float = 1.0) -> float:
        try:
            x = float(x)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0
        if x < lo:
            return float(lo)
        if x > hi:
            return float(hi)
        return float(x)

    def _ppFP_parse_output(out):
        """
        Normalizes arbitrary orphan outputs into (delta, buy_cnt, sell_cnt).
        delta is in [-1,1].
        """
        buy = 0
        sell = 0
        d = 0.0
        try:
            # Numeric
            if isinstance(out, (int, float)):
                d = _ppFP_clamp(float(out))
                return d, buy, sell

            # Dict shape
            if isinstance(out, dict):
                sig = str(out.get("signal", "") or "").upper().strip()
                if sig == "BUY":
                    return 1.0, 1, 0
                if sig == "SELL":
                    return -1.0, 0, 1
                if "score" in out:
                    try:
                        return _ppFP_clamp(float(out.get("score") or 0.0)), 0, 0
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_return")
                        return 0.0, 0, 0
                return 0.0, 0, 0

            # Tuple/list shape
            if isinstance(out, (tuple, list)) and out:
                x = out[0]
                if isinstance(x, str):
                    sig = str(x or "").upper().strip()
                    if sig == "BUY":
                        return 1.0, 1, 0
                    if sig == "SELL":
                        return -1.0, 0, 1
                    return 0.0, 0, 0
                if isinstance(x, (int, float)):
                    return _ppFP_clamp(float(x)), 0, 0
                return 0.0, 0, 0

        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_return")
            return 0.0, 0, 0

        return 0.0, 0, 0

    # ---- Patch LegacyIntelligenceManager.__init__: build orphan pools
    try:
        _LIM = globals().get("LegacyIntelligenceManager", None)
        if _LIM is not None and hasattr(_LIM, "__init__"):
            _ppFP_orig_init = getattr(_LIM, "__init__")
            if callable(_ppFP_orig_init) and not getattr(_ppFP_orig_init, "_ppFP_wrapped", False):
                def _ppFP_init(self, bot):  # noqa: ANN001
                    _ppFP_orig_init(self, bot)
                    try:
                        names = list(getattr(self, "orphans", []) or [])
                        all_funcs = []
                        for nm in (names or []):
                            try:
                                fn = globals().get(str(nm))
                                if callable(fn):
                                    all_funcs.append(fn)
                            except Exception:
                                continue
                        setattr(self, "orphan_funcs_all", list(all_funcs))
                        legacy = set()
                        try:
                            for fn in (getattr(self, "legacy_funcs", []) or []):
                                legacy.add(str(getattr(fn, "__name__", "")))
                        except Exception:
                            legacy = set()
                        nonlegacy = []
                        for fn in all_funcs:
                            try:
                                if str(getattr(fn, "__name__", "")) not in legacy:
                                    nonlegacy.append(fn)
                            except Exception:
                                continue
                        setattr(self, "orphan_funcs_nonlegacy", list(nonlegacy))
                        if not hasattr(self, "_ppFP_orphan_stats"):
                            setattr(self, "_ppFP_orphan_stats", {})
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                try:
                    _ppFP_init._ppFP_wrapped = True  # type: ignore[attr-defined]
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                setattr(_LIM, "__init__", _ppFP_init)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # ---- Patch LegacyIntelligenceManager.evaluate: add orphan-confirmation layer
    try:
        _LIM = globals().get("LegacyIntelligenceManager", None)
        if _LIM is not None and hasattr(_LIM, "evaluate"):
            _ppFP_orig_eval = getattr(_LIM, "evaluate")
            if callable(_ppFP_orig_eval) and not getattr(_ppFP_orig_eval, "_ppFP_wrapped", False):
                def _ppFP_eval(self, sym, symst, bid, ask, mid, depth_data):  # noqa: ANN001
                    base_delta, contrib = _ppFP_orig_eval(self, sym, symst, bid, ask, mid, depth_data)
                    try:
                        base_delta = float(base_delta or 0.0)
                    except Exception:
                        base_delta = 0.0

                    # Live vs DryRun: در لایو بدون تایید صریح، فقط تایید خیلی کم‌اثر انجام می‌شود
                    try:
                        run_live = str(_ppFP_os.getenv("DRY_RUN", "0") or "0").strip() == "0"
                    except Exception:
                        run_live = True

                    # Full power: در تست/بک‌تست پیش‌فرض روشن؛ در لایو نیاز به تایید یا ORPHAN_EXEC
                    full_power = _ppFP_env_true("PP170_FULL_POWER", default=("0" if run_live else "1"))
                    if not full_power:
                        full_power = _ppFP_env_true("PP170_ORPHAN_EXEC", default="0")

                    # وزن و سقف تعداد
                    w = _ppFP_env_float("PP170_ORPHAN_W", 0.03, lo=0.0, hi=0.15)
                    if run_live and (not full_power):
                        w = min(w, 0.01)  # micro-confirm only
                    max_n = _ppFP_env_int("PP170_ORPHAN_MAX", 10, lo=0, hi=25)

                    # فقط زمانی اعمال کن که سیگنال پایه معنی‌دار باشد (مگر full_power)
                    confirm_min = _ppFP_env_float("PP170_CONFIRM_MIN", 0.08, lo=0.0, hi=0.5)
                    if (not full_power) and (abs(base_delta) < float(confirm_min)):
                        return float(base_delta), contrib

                    pool = list(getattr(self, "orphan_funcs_nonlegacy", []) or [])
                    if not pool or max_n <= 0 or w <= 0.0:
                        return float(base_delta), contrib

                    stats = getattr(self, "_ppFP_orphan_stats", None)
                    if not isinstance(stats, dict):
                        stats = {}
                        try:
                            setattr(self, "_ppFP_orphan_stats", stats)
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")

                    total = 0.0
                    buy = 0
                    sell = 0
                    used = 0

                    safe_call = globals().get("_pp170__safe_call", None)

                    for fn in (pool or []):
                        if used >= max_n:
                            break
                        nm = str(getattr(fn, "__name__", "orphan"))
                        st = stats.get(nm, {"ok": 0, "err": 0, "slow": 0})
                        try:
                            if int(st.get("err", 0)) >= 5 and int(st.get("ok", 0)) <= 1:
                                continue
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")

                        t0 = _ppFP_time.perf_counter()
                        try:
                            if callable(safe_call):
                                out = safe_call(fn, bot=self.bot, sym=sym, symst=symst, bid=bid, ask=ask, mid=mid, depth_data=depth_data)
                            else:
                                out = fn()
                            dt = _ppFP_time.perf_counter() - t0
                            if dt > 0.20:
                                st["slow"] = int(st.get("slow", 0)) + 1
                                if int(st["slow"]) >= 3:
                                    stats[nm] = st
                                    continue

                            d, b, s = _ppFP_parse_output(out)
                            total += float(d)
                            buy += int(b)
                            sell += int(s)
                            st["ok"] = int(st.get("ok", 0)) + 1
                            used += 1
                        except Exception:
                            st["err"] = int(st.get("err", 0)) + 1
                        stats[nm] = st

                    total = _ppFP_clamp(total)  # [-1,1]

                    # تضاد BUY/SELL => تضعیف اثر یتیم‌ها
                    if buy and sell:
                        total *= 0.6
                        try:
                            contrib = list(contrib or [])
                            contrib.append(("ORPHAN_CONFLICT", f"{buy}/{sell}"))
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")

                    add = float(w) * float(total)

                    # در حالت تایید کم‌اثر: اجازه نده یتیم‌ها جهت را برعکس کنند
                    if (not full_power) and (base_delta * add < 0):
                        add *= 0.1
                        try:
                            contrib = list(contrib or [])
                            contrib.append(("ORPHAN_CONTRA", f"{add:+.3f}"))
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")
                    else:
                        try:
                            contrib = list(contrib or [])
                            contrib.append(("ORPHANS", f"{add:+.3f}"))
                        except Exception as _pp200_e:
                            _pp200_report(_pp200_e, tag="exc_pass")

                    new_delta = float(base_delta) + float(add)

                    # clamp همان بازه‌ی اصلی
                    if new_delta > 0.75:
                        new_delta = 0.75
                    if new_delta < -0.75:
                        new_delta = -0.75

                    try:
                        self.last_contrib = list(contrib or [])
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")
                    return float(new_delta), contrib

                try:
                    _ppFP_eval._ppFP_wrapped = True  # type: ignore[attr-defined]
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                setattr(_LIM, "evaluate", _ppFP_eval)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")

    # ---- Patch status_items: show full-power + pools (dedupe if available)
    try:
        _LIM = globals().get("LegacyIntelligenceManager", None)
        if _LIM is not None and hasattr(_LIM, "status_items"):
            _ppFP_orig_status = getattr(_LIM, "status_items")
            if callable(_ppFP_orig_status) and not getattr(_ppFP_orig_status, "_ppFP_wrapped", False):
                def _ppFP_status_items(self):  # noqa: ANN001
                    items = []
                    try:
                        items = list(_ppFP_orig_status(self) or [])
                    except Exception:
                        items = []
                    try:
                        run_live = str(_ppFP_os.getenv("DRY_RUN", "0") or "0").strip() == "0"
                        full_power = _ppFP_env_true("PP170_FULL_POWER", default=("0" if run_live else "1"))
                        if not full_power:
                            full_power = _ppFP_env_true("PP170_ORPHAN_EXEC", default="0")

                        pool_all = list(getattr(self, "orphan_funcs_all", []) or [])
                        pool_nl = list(getattr(self, "orphan_funcs_nonlegacy", []) or [])
                        items.append(("FullPower", "ON" if full_power else "OFF"))
                        items.append(("Orphans-All", str(len(pool_all))))
                        items.append(("Orphans-NonLegacy", str(len(pool_nl))))
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")

                    # reuse Harmony dedupe if present
                    try:
                        _ded = globals().get("_ppH_dedupe_items", None)
                        if callable(_ded):
                            return _ded(items)
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")

                    # fallback simple dedupe
                    out = []
                    seen = set()
                    for k, v in (items or []):
                        kk = str(k)
                        vv = str(v)
                        if (kk, vv) in seen:
                            continue
                        seen.add((kk, vv))
                        out.append((kk, vv))
                    return out

                try:
                    _ppFP_status_items._ppFP_wrapped = True  # type: ignore[attr-defined]
                except Exception as _pp200_e:
                    _pp200_report(_pp200_e, tag="exc_pass")
                setattr(_LIM, "status_items", _ppFP_status_items)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")


# [PP9999] Defer actual start to TRUE EOF so late patch layers (e.g. PP171) are loaded first.
# NOTE: Tokens/keys are untouched; this only changes execution order.
try:
    globals()["_PP9999_DEFERRED_START"] = True
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


# ============================================================
# IDEAL DECISION LAYER (2026-01-02)
# هدف: تصمیم‌گیری پایدارتر + محافظت ریسک + ژورنال تصمیمات
# نکته: هیچ تغییری روی توکن‌ها/کلیدها انجام نمی‌دهد.
# فعال‌سازی:
#   - PP170_IDEAL=1 (پیش‌فرض: 1)
#   - در لایو برای «قدرت کامل»: PP170_IDEAL_LIVE=1
# خاموش‌کردن کامل: PP170_IDEAL=0
# ============================================================

try:
    import os as _ppID_os
    import time as _ppID_time
    import math as _ppID_math
    import json as _ppID_json
except Exception:  # pragma: no cover
    _ppID_os = None
    _ppID_time = None
    _ppID_math = None
    _ppID_json = None


def _ppID_env_bool(k: str, default: bool = False) -> bool:
    try:
        v = str((_ppID_os.getenv(k, "") if _ppID_os else "") or "").strip().lower()
        if v == "":
            return bool(default)
        return v in ("1", "true", "yes", "y", "on", "enable", "enabled")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return bool(default)


def _ppID_env_int(k: str, default: int, lo: int | None = None, hi: int | None = None) -> int:
    try:
        v = int(float(str((_ppID_os.getenv(k, str(default)) if _ppID_os else str(default)) or str(default)).strip()))
    except Exception:
        v = int(default)
    if lo is not None:
        v = max(int(lo), int(v))
    if hi is not None:
        v = min(int(hi), int(v))
    return int(v)


def _ppID_env_float(k: str, default: float, lo: float | None = None, hi: float | None = None) -> float:
    try:
        v = float(str((_ppID_os.getenv(k, str(default)) if _ppID_os else str(default)) or str(default)).strip())
    except Exception:
        v = float(default)
    if lo is not None:
        v = max(float(lo), float(v))
    if hi is not None:
        v = min(float(hi), float(v))
    return float(v)


def _ppID_get(x, key, default=None):
    try:
        if isinstance(x, dict):
            return x.get(key, default)
        return getattr(x, key, default)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return default


def _ppID_safe_float(v, default: float = 0.0) -> float:
    try:
        if v is None:
            return float(default)
        f = float(v)
        if _ppID_math and (_ppID_math.isnan(f) or _ppID_math.isinf(f)):
            return float(default)
        return float(f)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return float(default)


def _ppID_now_ts() -> float:
    try:
        return float(_ppID__pp920_time.time()) if _ppID_time else 0.0
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0


def _ppID_is_live() -> bool:
    # DRY_RUN=0 => live
    try:
        v = str((_ppID_os.getenv("DRY_RUN", "0") if _ppID_os else "0") or "0").strip().lower()
        return v in ("0", "false", "no", "off")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return True


def _ppID_redact(obj):
    """Redact sensitive fields by key name (بدون تغییر توکن‌ها در منبع)."""
    try:
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                ks = str(k).lower()
                if any(t in ks for t in ("token", "secret", "api_key", "apikey", "password", "pass", "key")):
                    out[k] = "***"
                else:
                    out[k] = _ppID_redact(v)
            return out
        if isinstance(obj, (list, tuple)):
            return [_ppID_redact(x) for x in obj]
        return obj
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return {"_redact_error": True}


def _ppID_journal(entry: dict) -> None:
    try:
        if not _ppID_os or not _ppID_json:
            return
        # پیش‌فرض: در DRY_RUN روشن، در LIVE خاموش
        default_on = "1" if (not _ppID_is_live()) else "0"
        if str(_ppID_os.getenv("PP170_JOURNAL", default_on) or default_on).strip().lower() in ("0", "false", "no", "off"):
            return
        fn = str(_ppID_os.getenv("PP170_JOURNAL_FILE", ".pp_decisions.jsonl") or ".pp_decisions.jsonl").strip()
        if not fn:
            return
        payload = _ppID_redact(dict(entry or {}))
        s = _ppID_json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
        with open(fn, "a", encoding="utf-8") as f:
            f.write(s + "\n")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return


class _PPIdealRiskGuard:
    """Guardrails: اگر داده‌ی لازم موجود باشد اعمال می‌شود، وگرنه مزاحم نیست."""
    @staticmethod
    def filter(action: str, score: float, ctx) -> str:
        try:
            if _ppID_env_bool("PP170_KILL", False) or _ppID_env_bool("PP170_EMERGENCY_STOP", False):
                return "HOLD"

            # drawdown / loss-streak
            dd = _ppID_safe_float(_ppID_get(ctx, "drawdown", None), 0.0)
            max_dd = _ppID_env_float("PP170_MAX_DRAWDOWN", 0.25, lo=0.0, hi=0.95)
            if dd > max_dd:
                return "HOLD"

            streak = _ppID_safe_float(_ppID_get(ctx, "consecutive_losses", None), 0.0)
            max_streak = _ppID_env_int("PP170_MAX_LOSS_STREAK", 3, lo=0, hi=25)
            if streak >= float(max_streak) and max_streak > 0:
                return "HOLD"

            # cooldown
            cd = _ppID_safe_float(_ppID_get(ctx, "cooldown_until_ts", None), 0.0)
            if cd > 0.0 and _ppID_now_ts() < cd:
                return "HOLD"

            # spread (bps)
            bid = _ppID_safe_float(_ppID_get(ctx, "bid", None), 0.0)
            ask = _ppID_safe_float(_ppID_get(ctx, "ask", None), 0.0)
            mid = _ppID_safe_float(_ppID_get(ctx, "mid", None), 0.0)
            if bid > 0.0 and ask > 0.0:
                mid2 = mid if mid > 0.0 else (bid + ask) / 2.0
                if mid2 > 0.0:
                    spread_bps = (ask - bid) / mid2 * 10000.0
                    max_spread = _ppID_env_float("PP170_MAX_SPREAD_BPS", 25.0 if (not _ppID_is_live()) else 18.0, lo=1.0, hi=500.0)
                    if spread_bps > max_spread:
                        return "HOLD"

            # latency
            lat = _ppID_safe_float(_ppID_get(ctx, "latency_ms", None), 0.0)
            if lat <= 0.0:
                lat = _ppID_safe_float(_ppID_get(ctx, "net_latency_ms", None), 0.0)
            max_lat = _ppID_env_float("PP170_MAX_LATENCY_MS", 900.0 if (not _ppID_is_live()) else 650.0, lo=50.0, hi=20000.0)
            if lat > 0.0 and lat > max_lat:
                return "HOLD"
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        return action


def _ppID_strength_from_signal(s) -> float:
    """Extract direction/strength from diverse signal shapes."""
    try:
        # explicit strength
        st = _ppID_get(s, "strength", None)
        if st is not None:
            return _ppID_safe_float(st, 0.0)

        # numeric score
        sc = _ppID_get(s, "score", None)
        if sc is not None:
            return _ppID_safe_float(sc, 0.0)

        # buy/sell keyword
        sig = str(_ppID_get(s, "signal", "") or _ppID_get(s, "action", "") or "").upper().strip()
        if sig == "BUY":
            return 1.0
        if sig == "SELL":
            return -1.0
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return 0.0


def _ppID_confidence(s) -> float:
    try:
        c = _ppID_get(s, "confidence", None)
        if c is None:
            c = _ppID_get(s, "conf", None)
        c = _ppID_safe_float(c, 0.0)
        if c < 0.0:
            c = 0.0
        if c > 1.0:
            c = 1.0
        return float(c)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0


def _ppID_name(s) -> str:
    try:
        return str(_ppID_get(s, "name", None) or _ppID_get(s, "source", None) or _ppID_get(s, "type", None) or "unknown")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return "unknown"


def _ppID_consensus_penalty(contribs: list[float]) -> float:
    """When signals fight each other, reduce effective score."""
    try:
        if not contribs:
            return 1.0
        buy = sum(1 for x in contribs if x > 0.0)
        sell = sum(1 for x in contribs if x < 0.0)
        n = max(1, buy + sell)
        # imbalance ratio in [0..1]
        imb = abs(buy - sell) / float(n)
        # low consensus => penalty down to 0.55
        return 0.55 + 0.45 * imb
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 1.0


def _ppID_ideal_decide(signals, runtime_context, signal_performance=None) -> str:
    # fallback
    try:
        _orig = getattr(DecisionEngine, "_ppID_orig_decide", None)
        if callable(_orig):
            base_decision = _orig(signals, runtime_context, signal_performance)
        else:
            base_decision = "HOLD"
    except Exception:
        base_decision = "HOLD"

    try:
        # enable?
        if not _ppID_env_bool("PP170_IDEAL", True):
            return base_decision

        live = _ppID_is_live()
        ideal_live = _ppID_env_bool("PP170_IDEAL_LIVE", False)
        # conservative in live unless explicitly enabled
        conservative = bool(live and (not ideal_live))

        # threshold (base + stress + vol)
        th = 0.18
        try:
            th = float(DecisionEngine._get_threshold(runtime_context))
        except Exception:
            th = 0.18

        stress = 0.0
        for attr in ("stress_level", "stress", "stress_score"):
            v = _ppID_safe_float(_ppID_get(runtime_context, attr, None), None)
            if v is not None:
                stress = float(v)
                break
        if stress < 0.0:
            stress = 0.0
        if stress > 1.0:
            stress = 1.0

        vol = 0.0
        for attr in ("volatility", "vol", "atr_pct", "vol_pct"):
            v = _ppID_get(runtime_context, attr, None)
            if v is not None:
                vol = _ppID_safe_float(v, 0.0)
                break
        vol = max(0.0, min(2.0, float(vol)))
        dd = max(0.0, min(1.0, _ppID_safe_float(_ppID_get(runtime_context, "drawdown", None), 0.0)))

        th_eff = th * (1.0 + 0.8 * stress) * (1.0 + 0.35 * min(1.0, vol)) * (1.0 + 0.6 * min(0.35, dd))

        # score fusion
        score = 0.0
        contribs = []
        name_counts = {}
        for s in list(signals or []):
            try:
                if _ppID_get(s, "value", True) is False:
                    continue
                nm = _ppID_name(s)
                try:
                    nm_canon = DecisionEngine._canon_sig_name(nm)
                except Exception:
                    nm_canon = (nm or "unknown").strip().lower() or "unknown"

                name_counts[nm_canon] = int(name_counts.get(nm_canon, 0)) + 1

                st = _ppID_strength_from_signal(s)
                cf = _ppID_confidence(s)
                base = float(st) * float(cf)

                # adaptive weights (if available)
                try:
                    w = float(DecisionEngine._adaptive_weight(nm_canon, runtime_context))
                except Exception:
                    w = 1.0

                # performance weights (optional)
                if signal_performance is not None:
                    try:
                        if hasattr(signal_performance, "get_weight"):
                            w *= float(signal_performance.get_weight(nm_canon))
                        elif hasattr(signal_performance, "weight_for"):
                            w *= float(signal_performance.weight_for(nm_canon))
                    except Exception as _pp200_e:
                        _pp200_report(_pp200_e, tag="exc_pass")

                # diversity penalty: repeated same type -> diminishing returns
                rep = int(name_counts.get(nm_canon, 1))
                if rep >= 2:
                    w *= (0.72 ** (rep - 1))

                c = base * w
                # clamp extreme
                if c > 2.0:
                    c = 2.0
                if c < -2.0:
                    c = -2.0
                score += float(c)
                contribs.append(float(c))
            except Exception:
                continue

        # consensus penalty
        score *= float(_ppID_consensus_penalty(contribs))

        # consensus gate: if too much fight, HOLD in live
        if conservative:
            buy = sum(1 for x in contribs if x > 0.02)
            sell = sum(1 for x in contribs if x < -0.02)
            n = max(1, buy + sell)
            imb = abs(buy - sell) / float(n)
            min_imb = _ppID_env_float("PP170_MIN_CONSENSUS", 0.18, lo=0.0, hi=1.0)
            if imb < min_imb and abs(score) < (1.15 * th_eff):
                ideal = "HOLD"
            else:
                ideal = "BUY" if score >= th_eff else ("SELL" if score <= -th_eff else "HOLD")
        else:
            ideal = "BUY" if score >= th_eff else ("SELL" if score <= -th_eff else "HOLD")

        # in conservative live: never flip the base decision; only confirm or downshift to HOLD
        if conservative:
            if base_decision in ("BUY", "SELL"):
                if ideal == base_decision:
                    out = base_decision
                else:
                    # if ideal disagrees, prefer HOLD (safer)
                    out = "HOLD"
            else:
                # base is HOLD; allow ideal only if very strong
                boost = _ppID_env_float("PP170_IDEAL_BOOST", 1.35, lo=1.0, hi=3.0)
                if abs(score) >= (boost * th_eff):
                    out = ideal
                else:
                    out = "HOLD"
        else:
            out = ideal

        # risk guard final
        out2 = _PPIdealRiskGuard.filter(out, float(score), runtime_context)

        # journal (light)
        try:
            _ppID_journal({
                "ts": _ppID_now_ts(),
                "decision": str(out2),
                "ideal": str(ideal),
                "base": str(base_decision),
                "score": float(score),
                "th_eff": float(th_eff),
                "stress": float(stress),
                "vol": float(vol),
                "dd": float(dd),
                "n_signals": int(len(signals or [])),
            })
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        return out2
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return base_decision


# ---- Monkey patch DecisionEngine.decide (safe, reversible)
try:
    if "DecisionEngine" in globals() and hasattr(DecisionEngine, "decide"):
        if not hasattr(DecisionEngine, "_ppID_orig_decide"):
            setattr(DecisionEngine, "_ppID_orig_decide", getattr(DecisionEngine, "decide"))
        setattr(DecisionEngine, "decide", staticmethod(_ppID_ideal_decide))
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


# ============================================================
# PP171: IDEAL AWAKENING BRIDGE (2026-01-02)
# هدف:
#   1) وصل‌کردن «ژن‌های خفته/یتیم» به تصمیم نهایی بدون دست‌زدن به توکن‌ها
#   2) استفاده‌ی ایمن از توانایی‌های موجود: Risk-Gene Registry + Performance Cache + Shadow Guard
#   3) بهبود کیفیت تصمیم با لایه‌ی متا (روی امتیاز نهایی score)
#
# نکته‌های مهم:
#   - هیچ تغییری روی توکن‌ها/کلیدها/ENV های مربوط به API انجام نمی‌دهد.
#   - در LIVE به‌صورت محافظه‌کارانه کار می‌کند مگر اینکه خودتان اجازه‌ی «قدرت کامل» بدهید.
#
# ENV:
#   PP171_AWAKEN=1                (پیش‌فرض: 1)
#   PP171_AWAKEN_LIVE=0           (پیش‌فرض: 0)  <-- برای اثرگذاری تهاجمی‌تر در لایو
#   PP171_RISKGENE_CALLS=24
#   PP171_RISK_DAMP_PER_HINT=0.12
#   PP171_RISK_DAMP_MIN=0.35
#   PP171_LOSS_DAMP=0.88
#   PP171_PROFIT_BOOST=1.00       (در لایو پیش‌فرض: 1.0 => بدون بوست)
#   PP171_SHADOW_DAMP=0.85
#   PP171_SPREAD_DAMP_BPS=35
#   PP171_SPREAD_DAMP=0.85
#   PP171_RA_STEP_DOWN=0.05
#   PP171_RA_STEP_UP=0.02
#   PP171_RA_MIN=0.60
#   PP171_RA_MAX=1.40
# ============================================================

try:
    import os as _pp171_os
    import time as _pp171_time
    import math as _pp171_math
except Exception:  # pragma: no cover
    _pp171_os = None
    _pp171_time = None
    _pp171_math = None


def _pp171_env_bool(k: str, default: bool) -> bool:
    try:
        v = str((_pp171_os.getenv(k, "") if _pp171_os else "") or "").strip().lower()
        if v == "":
            return bool(default)
        return v in ("1", "true", "yes", "y", "on", "enable", "enabled")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return bool(default)


def _pp171_env_float(k: str, default: float, lo: float | None = None, hi: float | None = None) -> float:
    try:
        v = float(str((_pp171_os.getenv(k, str(default)) if _pp171_os else str(default)) or str(default)).strip())
    except Exception:
        v = float(default)
    if lo is not None:
        try:
            v = max(float(lo), float(v))
        except Exception:
            v = float(default)
    if hi is not None:
        try:
            v = min(float(hi), float(v))
        except Exception:
            v = float(default)
    return float(v)


def _pp171_env_int(k: str, default: int, lo: int | None = None, hi: int | None = None) -> int:
    try:
        v = int(float(str((_pp171_os.getenv(k, str(default)) if _pp171_os else str(default)) or str(default)).strip()))
    except Exception:
        v = int(default)
    if lo is not None:
        v = max(int(lo), int(v))
    if hi is not None:
        v = min(int(hi), int(v))
    return int(v)


def _pp171_now() -> float:
    try:
        return float(_pp171__pp920_time.time()) if _pp171_time else 0.0
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0


def _pp171_is_live() -> bool:
    # DRY_RUN=0 => live
    try:
        v = str((_pp171_os.getenv("DRY_RUN", "0") if _pp171_os else "0") or "0").strip().lower()
        return v in ("0", "false", "no", "off")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return True


def _pp171_clamp(x: float, lo: float, hi: float) -> float:
    try:
        xf = float(x)
    except Exception:
        xf = 0.0
    try:
        if _pp171_math and (_pp171_math.isnan(xf) or _pp171_math.isinf(xf)):
            xf = 0.0
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return float(max(float(lo), min(float(hi), float(xf))))


def _pp171_safe_spread_bps(bid: float, ask: float, mid: float) -> float:
    """
    Stable spread-bps computation even for very low-price assets (e.g., BabyDoge).
    This does not change the meaning of the spread; it only protects against
    division-by-zero / float blowups when prices are extremely small.
    """
    try:
        import math as _math
        b = float(bid or 0.0)
        a = float(ask or 0.0)
        m = float(mid or 0.0)
        if (not _math.isfinite(b)) or (not _math.isfinite(a)) or (not _math.isfinite(m)):
            return 0.0
        if b <= 0.0 or a <= 0.0:
            return 0.0
        m2 = m if m > 0.0 else (b + a) / 2.0
        denom = max(abs(m2), (abs(a) + abs(b)) / 2.0, 1e-18)
        spr = max(0.0, a - b)
        return float((spr / denom) * 10000.0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return 0.0


def _pp171_get_risk_hints(bot, sym: str, mid: float, bid: float, ask: float, score: float, depth_data) -> list[tuple[str, str]]:
    """
    Risk genes are already indexed in _pp603_GENE_REGISTRY (PP603/PP700).
    We just consume them here as a *decision dampener* (نه دستوری برای سفارش).
    """
    try:
        gr = globals().get("_pp603_GENE_REGISTRY", None)
        if gr is None:
            try:
                ua = getattr(bot, "arsenal", None) or getattr(bot, "universal_arsenal", None)
                gr = getattr(ua, "gene_registry", None)() if ua is not None and hasattr(ua, "gene_registry") else None
            except Exception:
                gr = None
        if gr is None or (not hasattr(gr, "risk_hints")):
            return []
        payload = {
            "symbol": str(sym),
            "sym": str(sym),
            "price": float(mid or 0.0),
            "last_price": float(mid or 0.0),
            "bid": float(bid or 0.0),
            "ask": float(ask or 0.0),
            "mid": float(mid or 0.0),
            "score": float(score or 0.0),
            "ts": _pp171_now(),
            "depth": depth_data if isinstance(depth_data, dict) else {},
        }
        max_calls = _pp171_env_int("PP171_RISKGENE_CALLS", 24, lo=0, hi=80)
        hints = gr.risk_hints(payload or {}, self_obj=bot, max_calls=int(max_calls))
        if not isinstance(hints, list):
            return []
        out = []
        for it in hints[:10]:
            try:
                if isinstance(it, (tuple, list)) and len(it) >= 2:
                    out.append((str(it[0])[:32], str(it[1])[:180]))
            except Exception:
                continue
        return out
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return []


def _pp171_last_outcome() -> str:
    try:
        fn = globals().get("_pp_perf_last_outcome", None)
        if callable(fn):
            return str(fn() or "NONE").upper()
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_pass")
    return "NONE"


def _pp171_shadow_active() -> bool:
    try:
        return bool(globals().get("_pp_shadow_guard_active", False))
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return False


def _pp171_update_risk_appetite(bot) -> None:
    """
    احیای توانایی «خودتنظیمی» (Autonomy-like) به شکل امن:
    - پس از LOSS کمی ریسک را پایین می‌آورد (risk_appetite)
    - پس از PROFIT آرام‌آرام برمی‌گرداند
    - در Shadow Guard هم کمی محافظه‌کارتر می‌شود
    این کار روی «تصمیم‌گیری» اثر غیرمستقیم دارد چون ربات از risk_appetite برای relax حساسیت استفاده می‌کند.
    """
    try:
        if bot is None:
            return
        # throttle (per bot) to avoid jitter per symbol
        now = _pp171_now()
        last = float(getattr(bot, "_pp171_last_ra_ts", 0.0) or 0.0)
        if last > 0.0 and (now - last) < 2.0:
            return
        setattr(bot, "_pp171_last_ra_ts", float(now))

        base = float(getattr(bot, "_risk_appetite_base", getattr(bot, "risk_appetite", 1.12) or 1.12) or 1.12)
        cur = float(getattr(bot, "risk_appetite", base) or base)

        ra_min = _pp171_env_float("PP171_RA_MIN", 0.60, lo=0.10, hi=3.00)
        ra_max = _pp171_env_float("PP171_RA_MAX", 1.40, lo=0.10, hi=3.00)
        step_down = _pp171_env_float("PP171_RA_STEP_DOWN", 0.05, lo=0.0, hi=0.50)
        step_up = _pp171_env_float("PP171_RA_STEP_UP", 0.02, lo=0.0, hi=0.50)

        outc = _pp171_last_outcome()
        shadow = _pp171_shadow_active()

        if outc == "LOSS":
            cur = max(ra_min, cur - step_down)
        elif outc == "PROFIT":
            # restore towards base gently
            if cur < base:
                cur = min(base, cur + step_up)
            else:
                cur = min(ra_max, cur)  # don't inflate on profit by default
        else:
            # drift back to base slowly
            if cur < base:
                cur = min(base, cur + step_up * 0.50)
            elif cur > base:
                cur = max(base, cur - step_up * 0.50)

        if shadow:
            cur = max(ra_min, cur - (step_down * 0.50))

        cur = float(max(ra_min, min(ra_max, cur)))
        try:
            setattr(bot, "risk_appetite", float(cur))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        # optional: expose for dashboard
        try:
            setattr(bot, "_pp171_ra_status", {"risk_appetite": float(cur), "base": float(base), "outcome": outc, "shadow": bool(shadow)})
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return


# ---- Score wrapper: hook into *current* final postprocess_score (after all PP patches) ----
try:
    _pp171__orig_post = globals().get("_pp5_postprocess_score", None)
except Exception:
    _pp171__orig_post = None

def _pp171_postprocess_score(bot, sym, symst, bid, ask, mid, depth_data, score):
    # call existing (already includes PP170 legacy + PP7778 + whale/jitter patches)
    try:
        s = float(_pp171__orig_post(bot, sym, symst, bid, ask, mid, depth_data, score)) if callable(_pp171__orig_post) else float(score or 0.0)
    except Exception:
        s = float(score or 0.0)

    try:
        if not _pp171_env_bool("PP171_AWAKEN", True):
            return _pp171_clamp(s, -1.0, 1.0)

        live = _pp171_is_live()
        full_live = _pp171_env_bool("PP171_AWAKEN_LIVE", False)

        # update autonomy-like risk appetite (safe)
        _pp171_update_risk_appetite(bot)

        # Risk genes (PP603) => dampening
        hints = _pp171_get_risk_hints(bot, str(sym), float(mid or 0.0), float(bid or 0.0), float(ask or 0.0), float(s), depth_data)

        damp = 1.0
        if hints:
            per = _pp171_env_float("PP171_RISK_DAMP_PER_HINT", 0.12, lo=0.0, hi=0.50)
            mn = _pp171_env_float("PP171_RISK_DAMP_MIN", 0.35, lo=0.05, hi=1.0)
            damp = max(mn, 1.0 - per * float(len(hints)))

        # Performance cache outcome
        outc = _pp171_last_outcome()
        if outc == "LOSS":
            damp *= _pp171_env_float("PP171_LOSS_DAMP", 0.88, lo=0.05, hi=1.0)
        elif outc == "PROFIT":
            # In live: default no boost (1.0). In dry-run: can allow tiny boost.
            pb = _pp171_env_float("PP171_PROFIT_BOOST", 1.02 if (not live) else 1.00, lo=0.90, hi=1.20)
            if (not live) or full_live:
                damp *= pb

        # Shadow guard => extra damp
        if _pp171_shadow_active():
            damp *= _pp171_env_float("PP171_SHADOW_DAMP", 0.85, lo=0.05, hi=1.0)

        # Spread damp (execution quality)
        spr = _pp171_safe_spread_bps(float(bid or 0.0), float(ask or 0.0), float(mid or 0.0))
        spr_thr = _pp171_env_float("PP171_SPREAD_DAMP_BPS", 35.0 if (not live) else 25.0, lo=1.0, hi=500.0)
        if spr > spr_thr:
            damp *= _pp171_env_float("PP171_SPREAD_DAMP", 0.85, lo=0.05, hi=1.0)

        # Apply damp (score is signed; damp reduces magnitude)
        s2 = float(s) * float(damp)

        # Expose to symbol-state for dashboard/debug
        try:
            setattr(symst, "_pp171_damp", float(damp))
            if hints:
                setattr(symst, "_pp171_risk_hints", hints[:5])
            else:
                setattr(symst, "_pp171_risk_hints", [])
            setattr(symst, "_pp171_spread_bps", float(spr))
            setattr(symst, "_pp171_outcome", str(outc))
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")

        return _pp171_clamp(s2, -1.0, 1.0)
    except Exception as _pp200_e:
        _pp200_report(_pp200_e, tag="exc_return")
        return _pp171_clamp(s, -1.0, 1.0)

# Patch in place (only once)
try:
    if callable(_pp171__orig_post) and (not hasattr(_pp171__orig_post, "_pp171_wrapped")):
        try:
            setattr(_pp171_postprocess_score, "_pp171_wrapped", True)
        except Exception as _pp200_e:
            _pp200_report(_pp200_e, tag="exc_pass")
        globals()["_pp5_postprocess_score"] = _pp171_postprocess_score
except Exception as _pp200_e:
    _pp200_report(_pp200_e, tag="exc_pass")


