def _pp913_best_update(self, wname: str, sym: str, pred: str, edge: float,
                       veto: str, safety: str = "", thr: float = 0.0, notional: float = 0.0,
                       min_notional: float = 0.0, qty: float = 0.0, step_state: str = "") -> None:
    try:
                # Always keep dashboard "Live" timestamp moving, even if trace is disabled.
        try:
            self._pp_diag_last_veto_ts = float(_pp920_time.time())
        except Exception:
            pass
        if not bool(getattr(self, "_pp910_trace_on", False)):

            # Minimal veto genealogy hint even when trace is off.
            try:
                _v = str(veto or "").upper().strip()
                if _v:
                    if _v in ("NO_EDGE", "HOLD", "FLAT", "UNSTABLE", "NO_VOL"):
                        self._pp_diag_last_veto_gene = f"Edge:{sym}".strip()[:64]
                    elif ("SPREAD" in _v) or _v in ("CANT_TRADE", "MIN_NOTIONAL", "LOCK", "BAN", "RISK", "SAFETY", "TOP", "VETO_TOP"):
                        self._pp_diag_last_veto_gene = f"Saf:{sym}".strip()[:64]
                    else:
                        self._pp_diag_last_veto_gene = f"Thr:{sym}".strip()[:64]
            except Exception:
                pass
            return
        if (not hasattr(self, "_pp910_best")) or (not isinstance(getattr(self, "_pp910_best", None), dict)):
            self._pp910_best = {}
        d = getattr(self, "_pp910_best", {}) or {}
        _w = str(wname or "").strip() or "W?"
        _edge = float(edge or 0.0)

        _prev = d.get(_w)
        try:
            _prev_edge = float((_prev or {}).get("edge", 0.0)) if isinstance(_prev, dict) else 0.0
        except Exception:
            _prev_edge = 0.0

        # Keep the most "informative" (largest absolute edge OR non-trivial veto) per wallet in this cycle.
        _replace = False
        if _prev is None:
            _replace = True
        elif abs(_edge) >= abs(_prev_edge):
            _replace = True
        elif str(veto or "").upper() not in ("NO_EDGE", "") and str((_prev or {}).get("veto", "")).upper() in ("NO_EDGE", ""):
            _replace = True

        if _replace:
            try:
                _ts = _pp913_time.strftime("%H:%M:%S") if _pp913_time is not None else ""
            except Exception:
                _ts = ""
            d[_w] = {
                "ts": _ts,
                "sym": str(sym or ""),
                "pred": str(pred or ""),
                "edge": float(_edge),
                "thr": float(thr or 0.0),
                "veto": str(veto or ""),
                "safety": str(safety or ""),
                "notional": float(notional or 0.0),
                "minN": float(min_notional or 0.0),
                "qty": float(qty or 0.0),
                "step": str(step_state or ""),
            }
            self._pp910_best = d
    except Exception as _pp200_e:
        try:
            _pp200_heal(_pp200_e, tag="pp913_best_update")
        except Exception:
            pass

def _pp913_best_flush(self) -> None:
    try:
        if not bool(getattr(self, "_pp910_trace_on", False)):
            return
        d = getattr(self, "_pp910_best", {}) or {}
        if not isinstance(d, dict) or (not d):
            return

        best_gap = -1e18
        best_rec = None

        for _w, _rec in d.items():
            if not isinstance(_rec, dict):
                continue
            try:
                msg = (
                    f"DT sym={_rec.get('sym','')} pred={_rec.get('pred','')} "
                    f"edge={float(_rec.get('edge',0.0)):+.4f} thr={float(_rec.get('thr',0.0)):.3f} "
                    f"veto={_rec.get('veto','')} safety={_rec.get('safety','')} "
                    f"notional={float(_rec.get('notional',0.0)):.0f} minN={float(_rec.get('minN',0.0)):.0f} "
                    f"qty={float(_rec.get('qty',0.0)):.8f} step={_rec.get('step','')}"
                )
                _pp9001__dbg_push(self, str(_w), msg)
            except Exception:
                pass

            try:
                _gap = float(_rec.get("edge", 0.0) or 0.0) - float(_rec.get("thr", 0.0) or 0.0)
                if _gap > float(best_gap):
                    best_gap = float(_gap)
                    best_rec = dict(_rec)
            except Exception:
                pass

        # Publish concise "WHY" into DZH-BAN via existing channel.
        try:
            if isinstance(best_rec, dict) and best_rec:
                _sym = str(best_rec.get("sym", "") or "")
                _veto = str(best_rec.get("veto", "") or "")
                _saf = str(best_rec.get("safety", "") or "")
                _edge = float(best_rec.get("edge", 0.0) or 0.0)
                _thr = float(best_rec.get("thr", 0.0) or 0.0)
                s = f"{_sym} {_veto} {_saf} e={_edge:+.3f} t={_thr:.3f}"
                try:
                    self._pp_diag_last_veto_gene = s[:64]
                except Exception:
                    pass
        except Exception:
            pass

    except Exception as _pp200_e:
        try:
            _pp200_heal(_pp200_e, tag="pp913_best_flush")
        except Exception:
            pass

