def _ppHOT__clamp(x: float, lo=None, hi=None) -> float:
    try:
        xf = float(x)
    except Exception:
        xf = 0.0
    try:
        if lo is not None:
            xf = max(float(lo), xf)
    except Exception:
        pass
    try:
        if hi is not None:
            xf = min(float(hi), xf)
    except Exception:
        pass
    return float(xf)

