def _pp171_env_float(k: str, default: float, lo=None, hi=None) -> float:  # type: ignore[override]
    """
    Priority-One env override:
      - EDGE_THRESHOLD overrides PP171_EDGE_THRESHOLD (and any other edge-threshold callsite).
    """
    try:
        ku = str(k or "").upper()
    except Exception:
        ku = ""
    # Edge threshold: priority-one is EDGE_THRESHOLD
    if ("EDGE_THRESHOLD" in ku) or (ku in ("PP171_EDGE_THRESHOLD", "PP171EDGE_THRESHOLD")):
        try:
            v = str((_ppHOT_os.getenv("EDGE_THRESHOLD", "") if _ppHOT_os else "") or "").strip()
        except Exception:
            v = ""
        if v != "":
            try:
                return _ppHOT__clamp(float(v), lo=lo, hi=hi)
            except Exception:
                pass
    # fallback to original behavior
    try:
        if callable(_ppHOT__orig_env_float):
            return float(_ppHOT__orig_env_float(k, default, lo, hi))
    except Exception:
        pass
    return _ppHOT__clamp(float(default), lo=lo, hi=hi)

