def _ppHOT_locked_from_open_orders_all(self, api, wname: str) -> dict:
    """Compute locked balances from open_orders_all() (token-safe, robust parsing)."""
    try:
        orders = api.open_orders_all() if api is not None and hasattr(api, "open_orders_all") else []
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="open_orders_all")  # type: ignore[name-defined]
        except Exception:
            pass
        orders = []
    if not isinstance(orders, (list, tuple)):
        orders = []
    try:
        quote = str(getattr(self, "quote", "") or "IRT").upper().strip()
    except Exception:
        quote = "IRT"
    out = {}
    for o in orders:
        if not isinstance(o, dict):
            continue
        try:
            side = str(o.get("side") or o.get("type") or "").lower().strip()
        except Exception:
            side = ""
        if side not in ("buy", "sell"):
            continue
        try:
            sym = str(o.get("symbol") or o.get("market") or "").upper().strip()
        except Exception:
            sym = ""
        if not sym:
            continue
        # base extraction
        base = ""
        try:
            if quote and sym.endswith(quote) and len(sym) > len(quote):
                base = sym[:-len(quote)]
            elif "-" in sym:
                base = sym.split("-", 1)[0]
            elif "_" in sym:
                base = sym.split("_", 1)[0]
        except Exception:
            base = ""
        base = str(base or "").upper().strip()
        if not base:
            continue

        qty = _ppHOT__parse_float(
            o.get("remain") or o.get("remaining") or o.get("remaining_qty") or o.get("qty") or o.get("amount") or o.get("volume") or 0.0,
            0.0,
        )
        px = _ppHOT__parse_float(o.get("price") or o.get("limit") or o.get("limit_price") or 0.0, 0.0)
        if qty <= 0.0:
            continue

        if side == "sell":
            asset = base
            amt = qty
        else:
            asset = quote
            amt = qty * px
        try:
            out[asset] = float(out.get(asset, 0.0) or 0.0) + float(amt)
        except Exception:
            pass
    return out

def _pp_locked_balances_v3(self, api, wname: str):  # type: ignore[override]
    # Call existing v3 first (keeps its caching + decimal micro-unit parsing)
    try:
        base = dict(_ppHOT__orig_locked(self, api, wname)) if callable(_ppHOT__orig_locked) else {}
    except Exception as _e:
        try:
            _pp200_heal(_e, tag="locked_balances_v3")  # type: ignore[name-defined]
        except Exception:
            pass
        base = {}
    # If OPEN_ORDERS_ALL=1, augment/override locked via open_orders_all().
    try:
        force = bool(getattr(self, "_ppHOT_env_open_orders_all", False) or _ppHOT__env_true("OPEN_ORDERS_ALL", default=False))
    except Exception:
        force = _ppHOT__env_true("OPEN_ORDERS_ALL", default=False)
    if not force:
        return base
    try:
        oo = _ppHOT_locked_from_open_orders_all(self, api, wname)
        if isinstance(oo, dict) and oo:
            for k, v in oo.items():
                try:
                    kk = str(k).upper().strip()
                    if not kk:
                        continue
                    base[kk] = max(float(base.get(kk, 0.0) or 0.0), float(v or 0.0))
                except Exception:
                    pass
            # refresh cache if the underlying impl uses per-wallet cache (best-effort)
            try:
                _c = getattr(self, "_pp7826_oo_cache", None)
                _ts = getattr(self, "_pp7826_oo_cache_ts", None)
                if isinstance(_c, dict) and isinstance(_ts, dict):
                    wn = str(wname or "").strip() or "W?"
                    _c[wn] = dict(base)
                    _ts[wn] = float((_ppHOT__pp920_time.time() if _ppHOT_time is not None else 0.0) or 0.0)
            except Exception:
                pass
    except Exception:
        pass
    return base

