# -----------------------------
# (1) Monkeypatch Integrity: inject _pp916_best_flush everywhere (no orphans)
# -----------------------------
def _ppHOT_iter_wallet_classes() -> list:
    out = []
    seen = set()
    try:
        for _name, _obj in list(globals().items()):
            if isinstance(_obj, type):
                nm = str(_name or "")
                if ("Wallet" in nm) or nm.startswith("PP5"):
                    # heuristic: class must look like trading wallet/bot
                    try:
                        if any(hasattr(_obj, a) for a in ("tick", "_place_buy", "_pp_locked_balances", "_pp910_best_update", "_price_map")):
                            if id(_obj) not in seen:
                                seen.add(id(_obj))
                                out.append(_obj)
                    except Exception:
                        pass
    except Exception:
        pass
    # registry dicts (if any)
    try:
        for rn in ("PP5_BOT_REGISTRY", "PP5_REGISTRY"):
            reg = globals().get(rn, None)
            if isinstance(reg, dict):
                for _obj in list(reg.values()):
                    if isinstance(_obj, type) and id(_obj) not in seen:
                        seen.add(id(_obj))
                        out.append(_obj)
    except Exception:
        pass
    return out

def _ppHOT_inject_best_flush() -> list:
    """Returns a list of orphan class names that still lack the injected flush."""
    orphans = []
    fn = globals().get("_pp916_best_flush", None)
    if not callable(fn):
        fn = globals().get("_pp913_best_flush", None)
    if not callable(fn):
        return []
    targets = _ppHOT_iter_wallet_classes()
    for cls in targets:
        try:
            setattr(cls, "_pp910_best_flush", fn)  # hot-active bind
            try:
                setattr(cls, "_ppHOT_best_flush_bound", True)
            except Exception:
                pass
        except Exception:
            try:
                orphans.append(getattr(cls, "__name__", "<?>"))
            except Exception:
                pass
    # sanity: check subclasses of PP5LiveTripleWallet
    try:
        base = globals().get("PP5LiveTripleWallet", None)
        if isinstance(base, type):
            for cls in targets:
                try:
                    if issubclass(cls, base) and not hasattr(cls, "_pp910_best_flush"):
                        orphans.append(getattr(cls, "__name__", "<?>"))
                except Exception:
                    pass
    except Exception:
        pass
    try:
        globals()["_PP916_ORPHAN_CLASSES"] = sorted(set(orphans))
    except Exception:
        pass
    return sorted(set(orphans))

try:
    _ppHOT_inject_best_flush()
except Exception:
    pass

# -----------------------------
# (2) Veto Awake: push WHY immediately from consensus loop (Saf/Edge/Thr) to DZH-BAN
# -----------------------------
def _ppHOT_bucket_reason(reason: str) -> str:
    try:
        r = str(reason or "").upper()
    except Exception:
        r = ""
    if any(k in r for k in ("NO_EDGE", "EDGE", "FLAT", "UNSTABLE", "NO_VOL", "WEAK")):
        return "Edge"
    if any(k in r for k in ("THR", "THRESH", "BELOW", "MIN_THR", "ENTRY_THR")):
        return "Thr"
    if any(k in r for k in ("SAFE", "SAFETY", "SPREAD", "LOCK", "BAN", "RISK", "CANT", "VETO", "ERR", "ERROR", "FAIL", "TIMEOUT", "NETWORK", "HTTP", "SSL", "JSON", "DECODE", "FAKE", "INVALID", "429")):
        return "Saf"
    return "Thr"

def _ppHOT_emit_veto(bot, sym: str, why: str, reason: str = "") -> None:
    try:
        if bot is None:
            return
        s = str(sym or "").upper().strip()
        w = str(why or "").strip() or "Thr"
        try:
            bot._pp_diag_last_veto_gene = f"{w}:{s}".strip()[:64]
        except Exception:
            pass
        try:
            if _ppHOT_time is not None:
                bot._pp_diag_last_veto_ts = float(_ppHOT__pp920_time.time())
        except Exception:
            pass
        # optional immediate dashboard event
        try:
            _dash = globals().get("_dash_event", None)
            if callable(_dash) and _ppHOT_time is not None:
                _dash({"k": "veto", "sym": s, "why": w, "reason": str(reason or "")[:80], "ts": float(_ppHOT__pp920_time.time())})
        except Exception:
            pass
    except Exception:
        pass

def _ppHOT_patch_veto_awake(cls, mname="secondary_confirm_or_veto"):
    try:
        if cls is None or not hasattr(cls, mname):
            return
        _orig = getattr(cls, mname)
        if getattr(cls, "_ppHOT_veto_awake_patched", False):
            return
        def _wrapped(self, sym, proposed):
            res = _orig(self, sym, proposed)
            try:
                if isinstance(res, tuple) and len(res) >= 3:
                    confirm, veto, reason = res[0], res[1], res[2]
                else:
                    confirm, veto, reason = (False, False, "")
                # Central BUY loop wake-up (also for SELL, keeps DZH-BAN honest)
                p = str(proposed or "").upper().strip()
                if p in ("BUY", "SELL"):
                    if bool(veto) or (not bool(confirm)):
                        why = _ppHOT_bucket_reason(str(reason))
                        # find bot reference
                        bot = getattr(self, "bot", None)
                        if bot is None:
                            try:
                                w = getattr(self, "wallet", None)
                                bot = getattr(w, "bot", None) if w is not None else None
                            except Exception:
                                bot = None
                        _ppHOT_emit_veto(bot, str(sym or ""), why, str(reason or ""))
            except Exception as _e:
                try:
                    _pp200_heal(_e, tag="veto_awake")  # type: ignore[name-defined]
                except Exception:
                    pass
            return res
        setattr(cls, mname, _wrapped)
        setattr(cls, "_ppHOT_veto_awake_patched", True)
    except Exception:
        pass

