def _ppHOT__is_sensitive_fault(tag: str, e) -> bool:
    try:
        tl = str(tag or "").lower()
    except Exception:
        tl = ""
    try:
        msg = str(e or "").lower()
    except Exception:
        msg = ""
    keys = ("timeout", "network", "conn", "connect", "ssl", "http", "429", "rate", "json", "decode", "invalid", "schema", "fake", "gateway", "502", "503", "504")
    return any(k in tl for k in keys) or any(k in msg for k in keys)

def _pp200_heal(e, tag="heal"):  # type: ignore[override]
    # 1) run original ledger first
    try:
        if callable(_ppHOT__orig_heal):
            _ppHOT__orig_heal(e, tag=tag)
    except Exception:
        pass

    # 2) sensitive escalation: immediate resync / route rebuild hint
    try:
        if not _ppHOT__env_true("PP200_HEAL_SENSITIVE", default=True):
            return
        if not _ppHOT__is_sensitive_fault(tag, e):
            return

        bot = None
        # resolve bot via PP220 weakref if present
        try:
            _wr = globals().get("_pp220_bot_weakref", None)
            if callable(_wr):
                bot = _wr()
        except Exception:
            bot = None
        # mark force restart + attempt resync
        if bot is not None:
            try:
                bot._pp200_force_priority_restart = True
            except Exception:
                pass
            try:
                fn = globals().get("_pp255_attempt_resync", None)
                if callable(fn):
                    fn(bot)
            except Exception:
                pass
            try:
                _pub = getattr(bot, "public_api", None)
                if _pub is not None and hasattr(_pub, "reset_session"):
                    _pub.reset_session()
            except Exception:
                pass
            try:
                apis = getattr(bot, "apis", None) or {}
            except Exception:
                apis = {}
            try:
                for _a in (apis or {}).values():
                    if _a is not None and hasattr(_a, "reset_session"):
                        try:
                            _a.reset_session()
                        except Exception:
                            pass
            except Exception:
                pass
    except Exception:
        pass

try:
    globals()["_pp200_heal"] = _pp200_heal
except Exception:
    pass

