def _ppHOT_emit_veto(bot, sym: str, why: str, reason: str = "") -> None:  # type: ignore[override]
    try:
        if bot is None:
            return
        s = str(sym or "").upper().strip()
        w = str(why or "").strip() or "Thr"

        thr = 0.0
        try:
            thr = float(_pp750__infer_thr(bot))
        except Exception:
            thr = 0.0

        # Build compact gene (<=64) but include threshold when meaningful.
        gene = f"{w}:{s}"
        try:
            if thr > 0.0:
                gene = f"{gene} t={thr:.3f}"
        except Exception:
            pass

        try:
            bot._pp_diag_last_veto_gene = str(gene).strip()[:64]
        except Exception:
            pass
        try:
            if _pp750_time is not None:
                bot._pp_diag_last_veto_ts = float(_pp750__pp920_time.time())
        except Exception:
            pass

        # When the bot is stuck on NO_EDGE, publish a direct env hint (non-invasive).
        try:
            if w == "Edge":
                env_thr = _pp750__env_str("EDGE_THRESHOLD")
                if env_thr == "" and thr > 0.0:
                    hint = f"NO_EDGE thr={thr:.3f} | set EDGE_THRESHOLD lower"
                    try:
                        bot._pp_last_fs_reason = str(hint)[:120]
                        if _pp750_time is not None:
                            bot._pp_last_fs_ts = float(_pp750__pp920_time.time())
                    except Exception:
                        pass
        except Exception:
            pass

        # Preserve optional dashboard event behavior (if available)
        try:
            _dash = globals().get("_dash_event", None)
            if callable(_dash) and _pp750_time is not None:
                _dash({"k": "veto", "sym": s, "why": w, "reason": str(reason or "")[:120], "thr": float(thr or 0.0), "ts": float(_pp750__pp920_time.time())})
        except Exception:
            pass

    except Exception:
        # last resort fallback to older emitter
        try:
            if callable(_pp750__old_emit):
                _pp750__old_emit(bot, sym, why, reason)
        except Exception:
            pass

try:
    globals()["_ppHOT_emit_veto"] = _ppHOT_emit_veto
except Exception:
    pass


