# - Token-safe: NO edits to any token/key/secret lines.
# - Priority-One ENV: EDGE_THRESHOLD overrides legacy PP171_EDGE_THRESHOLD.
# - Better "WHY NO TRADE": publish live edge/thr gap into _pp_last_fs_reason
#   so DZH-BAN shows numeric cause instead of just FLAT+NO_EDGE.
# ============================================================

try:
    import os as _ppv2_os
except Exception:  # pragma: no cover
    _ppv2_os = None


# --- Priority-One ENV mapping: EDGE_THRESHOLD -> PP171_EDGE_THRESHOLD ---
try:
    _pp171_env_float__orig = _pp171_env_float  # type: ignore[name-defined]
except Exception:  # pragma: no cover
    _pp171_env_float__orig = None

if callable(_pp171_env_float__orig):
    def _pp171_env_float(k: str, default: float, lo: float | None = None, hi: float | None = None) -> float:  # type: ignore[override]
        """
        Priority-One ENV resolution.
        If code asks for PP171_EDGE_THRESHOLD but user set EDGE_THRESHOLD, use EDGE_THRESHOLD.
        Never touches token/secret envs.
        """
        try:
            kk = str(k or "").strip()
        except Exception:
            kk = k  # type: ignore[assignment]

        # Priority-One: EDGE_THRESHOLD wins for any PP171_EDGE_THRESHOLD reads
        try:
            if kk == "PP171_EDGE_THRESHOLD" and _ppv2_os:
                v = _ppv2_os.getenv("EDGE_THRESHOLD", "")
                if v not in (None, ""):
                    try:
                        fv = float(str(v).strip())
                        if lo is not None:
                            fv = max(float(lo), float(fv))
                        if hi is not None:
                            fv = min(float(hi), float(fv))
                        return float(fv)
                    except Exception:
                        pass
        except Exception:
            pass

        # Fallback to original behavior
        try:
            return float(_pp171_env_float__orig(k, default, lo=lo, hi=hi))  # type: ignore[misc]
        except Exception:
            return float(default)


# --- Publish numeric edge/thr reason so DZH-BAN becomes fully responsive ---
def _ppv2_publish_edge_gap_reason(bot: object) -> None:
    try:
        best = getattr(bot, "_pp910_last_best_global", None)
        if not isinstance(best, dict) or (not best):
            return
        try:
            edge = float(best.get("edge", 0.0) or 0.0)
        except Exception:
            edge = 0.0
        try:
            thr = float(best.get("thr", 0.0) or 0.0)
        except Exception:
            thr = 0.0
        try:
            veto = str(best.get("veto", "") or "").strip()
        except Exception:
            veto = ""

        gap = float(edge) - float(thr)

        # Only publish when it actually explains "no-trade" situations
        if veto in ("NO_EDGE", "EDGE_BELOW_THR", "MIN_NOTIONAL", "SIGNAL_OK", "") or gap < 0.0:
            msg = f"EDGE {edge:+.3f}<{thr:.3f} gap{gap:+.3f}"
            # keep short for panel
            msg = (msg[:56] + ("…" if len(msg) > 56 else ""))
            # Do not override a more specific existing force-start reason (network, postprocess, etc.)
            try:
                cur = str(getattr(bot, "_pp_last_fs_reason", "") or "").strip()
            except Exception:
                cur = ""
            if (not cur) or cur.startswith(("FLAT+NO_EDGE", "NO_RULE", "EDGE ", "NO_EDGE", "POSTPROCESS")):
                setattr(bot, "_pp_last_fs_reason", msg)
    except Exception:
        return


def _ppv2_wrap_best_flush_reason(cls: type) -> None:
    try:
        if not hasattr(cls, "_pp910_best_flush"):
            return
        if bool(getattr(cls, "_ppv2_best_flush_wrapped", False)):
            return
        orig = getattr(cls, "_pp910_best_flush")
        if not callable(orig):
            return

        def _wrapped(self, *a, **kw):  # type: ignore[no-redef]
            r = None
            try:
                r = orig(self, *a, **kw)
            except Exception as _e:
                try:
                    _pp200_heal(_e, tag="ppv2_best_flush")  # type: ignore[name-defined]
                except Exception:
                    pass
            try:
                _ppv2_publish_edge_gap_reason(self)
            except Exception:
                pass
            return r

        setattr(cls, "_pp910_best_flush", _wrapped)
        # Keep aliases consistent if present
        try:
            if hasattr(cls, "_pp916_best_flush"):
                setattr(cls, "_pp916_best_flush", _wrapped)
        except Exception:
            pass
        try:
            if hasattr(cls, "_pp913_best_flush"):
                setattr(cls, "_pp913_best_flush", _wrapped)
        except Exception:
            pass

        setattr(cls, "_ppv2_best_flush_wrapped", True)
    except Exception:
        return


def _ppv2_apply_global_wrappers() -> None:
    try:
        for _obj in list(globals().values()):
            try:
                if isinstance(_obj, type):
                    _ppv2_wrap_best_flush_reason(_obj)
            except Exception:
                continue
    except Exception:
        return


try:
    _ppv2_apply_global_wrappers()
except Exception:
    pass

