def _pp7980__edge_floor() -> float:
    """Maintain EDGE_THRESHOLD floor at 0.0005 (do NOT relax profitability standards)."""
    try:
        if _pp7980_os is None:
            return 0.0005
        v = float(_pp7980_os.getenv("EDGE_THRESHOLD", "0.0005") or 0.0005)
    except Exception:
        v = 0.0005
