def _pp7980__veto_genealogy_v7980(bot, rec: dict) -> str:
    try:
        r = dict(rec or {}) if isinstance(rec, dict) else {}
        sym = str(r.get("sym", "") or "").upper().strip()
        pred = str(r.get("pred", "") or "").upper().strip()
        veto = str(r.get("veto", "") or "").upper().strip()
        safety = str(r.get("safety", "") or "").upper().strip()
        try:
            edge = float(r.get("edge", 0.0) or 0.0)
        except Exception:
            edge = 0.0
        try:
            thr = float(r.get("thr", 0.0) or 0.0)
        except Exception:
            thr = 0.0

        # Merge in final-order rejection reason if fresh
        try:
            lr = getattr(bot, "_pp7980_last_reject", None)
            if isinstance(lr, dict) and _pp7980_time is not None:
                ts = float(lr.get("ts", 0.0) or 0.0)
                if ts > 0 and (float(_pp7980__pp920_time.time()) - ts) <= float(_pp7980_os.getenv("PP7980_REJECT_WINDOW_SEC", "15") or 15):
                    ls = str(lr.get("sym", "") or "").upper().strip()
                    rr = str(lr.get("reason", "") or "").upper().strip()
                    if rr and (not sym or not ls or sym == ls):
                        # attach as safety so it's surfaced as Saf:... in dashboard
                        safety = rr
                        r["safety"] = rr
                        if not sym and ls:
                            sym = ls
        except Exception:
            pass

        reason = _pp7980__infer_bestflush_reason_v7980(r)

        code = "Edge"
        if reason == "SAFETY":
            code = "Saf"
        elif reason == "THRESHOLD":
            code = "Thr"
        elif reason == "OK":
            code = "OK"
        else:
            code = "Edge"

        why = ""
        if reason == "SAFETY":
            why = safety or veto or pred or ""
        elif reason == "THRESHOLD":
            if thr > 0.0:
                why = f"e={edge:+.6f}<t={thr:.6f}"
            else:
                why = f"e={edge:+.6f}"
        elif reason == "NO_EDGE":
            # If AI is FLAT but we truly have no edge, we still show the math / veto.
            why = veto or f"e={edge:+.6f}"
        else:
            why = f"e={edge:+.6f}"

        s = f"{code}:{(sym or '?')}"
        if why:
            cand = f"{s} {why}".strip()
            s = cand if len(cand) <= 64 else s

        # include short blocker gene if present
        try:
            gene = str(r.get("gene", "") or "").upper().strip()
            if gene:
                g = gene[:12]
                if g not in ("UNKNOWN", "NONE", "-"):
                    cand = f"{s} g={g}"
                    s = cand if len(cand) <= 64 else s
        except Exception:
            pass

        return (s or "UNKNOWN")[:64]
    except Exception:
        return "UNKNOWN"

