# -----------------------------------------------------------------------------
# 2) Laddering & Min-Notional: auto-reduce steps so each step >= min_notional,
#    and allocate the FULL intended size (no partial "locked ladder").
# -----------------------------------------------------------------------------
try:
    _pp7980__orig_ladder_plan = globals().get("_pp745__ladder_plan", None)
except Exception:
    _pp7980__orig_ladder_plan = None

def _pp7980__ladder_plan_v7980(total_qty: float, mid_price: float, steps: int, min_notional: float):
    try:
        tq = float(total_qty or 0.0)
        mp = float(mid_price or 0.0)
        if tq <= 0.0 or mp <= 0.0:
            return [(max(0.0, tq), max(0.0, mp))]
        s_req = int(steps or 1)
        s_req = max(1, min(8, s_req))
        mn = float(min_notional or 0.0)
        tot_notional = float(tq * mp)

        # Pick a steps count that satisfies min-notional per step.
        def _weights_for(k: int):
            if k == 1:
                return [1.0]
            if k == 2:
                return [0.60, 0.40]
            if k == 3:
                return [0.50, 0.30, 0.20]
            return [1.0 / float(k)] * k

        chosen_steps = s_req
        weights = _weights_for(chosen_steps)
        if mn > 0.0:
            # Reduce until all steps meet min-notional (based on notional split, not price)
            for k in range(s_req, 0, -1):
                w = _weights_for(k)
                ok = True
                for wi in w:
                    if (tot_notional * float(wi)) < mn:
                        ok = False
                        break
                if ok:
                    chosen_steps = k
                    weights = w
                    break
            if chosen_steps < 1:
                chosen_steps = 1
                weights = [1.0]

        # price ladder around mid (conservative)
        if chosen_steps <= 1:
            pxs = [mp]
        else:
            # small spread across steps (configurable)
            try:
                band_bps = float(_pp7980_os.getenv("PP7980_LADDER_BAND_BPS", "25") or 25.0) if _pp7980_os else 25.0
            except Exception:
                band_bps = 25.0
            band = max(0.0, float(band_bps) / 10000.0)
            # For BUY ladder: start near mid, then lower
            pxs = []
            for i in range(chosen_steps):
                # evenly spaced from +0 to -band
                t = 0.0 if chosen_steps == 1 else float(i) / float(max(1, chosen_steps - 1))
                px = mp * (1.0 - band * t)
                pxs.append(float(px))

        out = []
        # allocate full notional across chosen steps (no skipping)
        for i in range(chosen_steps):
            wi = float(weights[i]) if i < len(weights) else (1.0 / float(chosen_steps))
            px = float(pxs[i]) if i < len(pxs) else mp
            px = max(1e-12, px)
            not_i = tot_notional * wi
            qty_i = not_i / px
            out.append((float(qty_i), float(px)))

        # Safety: normalize qty sum exactly to total_qty (avoid rounding drift)
        try:
            s = sum(q for q, _ in out)
            if s > 0:
                k = tq / s
                out = [(float(q * k), float(px)) for q, px in out]
        except Exception:
            pass

        return out
    except Exception:
        try:
            if callable(_pp7980__orig_ladder_plan):
                return _pp7980__orig_ladder_plan(total_qty, mid_price, steps, min_notional)
        except Exception:
            pass
        return [(float(total_qty or 0.0), float(mid_price or 0.0))]

try:
    globals()["_pp745__ladder_plan"] = _pp7980__ladder_plan_v7980
except Exception:
    pass

