def _pp7980__place_buy_v745_wrap(self, api, wname: str, sym: str, qty: float, price: float):
    try:
        # compute requested steps as v745 does
        env = "1"
        try:
            env = str((_pp7980_os.getenv("ADV_LADDERING", "1") if _pp7980_os else "1") or "1")
        except Exception:
            env = "1"
        adv = env.lower() in ("1", "true", "yes", "on")
        req_steps = 1
        try:
            req_steps = int(getattr(self, "ladder_steps", 3) or 3)
        except Exception:
            req_steps = 3
        req_steps = max(1, min(8, req_steps))
        # if laddering would be used, anticipate adjustment
        if adv and req_steps > 1:
            try:
                mn = float((_pp7980_os.getenv("MIN_ORDER_IRT", "0") if _pp7980_os else 0.0) or 0.0)
            except Exception:
                mn = 0.0
            plan = _pp7980__ladder_plan_v7980(float(qty or 0.0), float(price or 0.0), req_steps, mn)
            used = len(plan) if isinstance(plan, (list, tuple)) else 1
            if used < req_steps:
                _pp7980__mark_last_reject(self, str(sym or ""), "MIN_NOTIONAL", f"LADDER {req_steps}->{used}")
    except Exception:
        pass
    return _pp7980__orig_place_buy_v745(self, api, wname, sym, qty, price)

