def _pp7981__wallet_cash_irt(bot, api, quote: str) -> float:
    try:
        bal_fn = getattr(bot, "_balances", None)
        if callable(bal_fn):
            b = bal_fn(api)
            if isinstance(b, dict):
                return float(b.get(quote, 0.0) or 0.0)
    except Exception:
        pass
    return 0.0


def _pp7981__required_irt(bot, sym: str, qty: float, price: float) -> float:
    try:
        minN = float(getattr(bot, "min_notional_irt", 200000.0) or 200000.0)
    except Exception:
        minN = 200000.0
    try:
        notional = max(0.0, float(qty) * float(price))
    except Exception:
        notional = 0.0
    steps = 1
    try:
        if _pp7981_os is not None:
            ladder_on = str(_pp7981_os.getenv("ADV_LADDERING", "1") or "1").strip().lower() in ("1", "true", "yes", "on")
            if ladder_on:
                steps = int(float(_pp7981_os.getenv("LADDER_STEPS", "1") or 1))
    except Exception:
        steps = 1
    ladder_floor = float(minN) * float(max(1, steps)) if steps > 1 else 0.0
    safety_floor = float(_pp7981__env_float("SAFETY_FLOOR_IRT", 0.0))
    fee_bps = float(_pp7981__env_float("TAKER_FEE_BPS", 15.0))
    slip_bps = float(_pp7981__env_float("LIVE_FEE_BPS", 12.0))
    safety_bps = float(_pp7981__env_float("ORDER_SAFETY_BPS", 10.0))
    frac = float(max(0.0, (fee_bps + slip_bps + safety_bps) / 10000.0))
    base = float(max(minN, ladder_floor, safety_floor, notional))
    return float(base * (1.0 + frac))


def _pp7981__maybe_usdt_fund(bot, api, wname: str, required_irt: float) -> None:
    '''Attempt best-effort USDT->IRT conversion (if sanctuary/bridge exists).'''
    try:
        fn = globals().get("_pp160_auto_usdt_conversion")
        if callable(fn):
            fn(bot, api, wallet_name=str(wname), min_irt=float(required_irt))
    except Exception:
        pass


def _pp7981__best_sym_in_group(bot, group: str) -> str:
    try:
        cands = getattr(bot, "_pp7981_cands", None)
        if not isinstance(cands, list) or not cands:
            return ""
        best = ""
        best_sc = -1e18
        for rec in cands:
            if not isinstance(rec, dict):
                continue
            sym = str(rec.get("sym", "") or "").upper().strip()
            if _pp7981__corr_group(sym) != group:
                continue
            sc = float(rec.get("final_score", rec.get("gap", 0.0)) or 0.0)
            if sc > best_sc:
                best_sc = sc
                best = sym
        return str(best or "")
    except Exception:
        return ""


try:
    if "PP5LiveTripleWallet" in globals():
        _pp7981__old_place_buy = getattr(PP5LiveTripleWallet, "_place_buy", None)

        def _pp7981__place_buy(self, api, wname: str, sym: str, qty: float, price: float):
            symU = str(sym or "").upper().strip()

            mult = 1.0
            try:
                m = getattr(self, "_pp7981_size_mult", {}) or {}
                mult = float(m.get((str(wname), symU), m.get(symU, 1.0)) or 1.0)
            except Exception:
                mult = 1.0
            mult = float(_pp7981__clamp(mult, 0.0, 1.0))
            qty_adj = float(qty or 0.0) * float(mult)

            try:
                minN = float(getattr(self, "min_notional_irt", 200000.0) or 200000.0)
                px = max(1e-9, float(price or 0.0))
                min_qty = float(minN) / float(px)
                if qty_adj > 0.0 and qty >= min_qty and qty_adj < min_qty and mult < 1.0:
                    qty_adj = float(min_qty)
                    qty_adj = float(min(qty_adj, float(qty)))
            except Exception:
                pass

            try:
                g = _pp7981__corr_group(symU)
                if g:
                    best_sym = _pp7981__best_sym_in_group(self, g)
                    if best_sym and best_sym != symU:
                        try:
                            rec_fn = globals().get("_pp7980__record_reject")
                            if callable(rec_fn):
                                rec_fn(self, symU, "CORR_ALT_BETTER", extra=str(best_sym))
                        except Exception:
                            pass
                        return {"ok": False, "status": 0, "error": "corr_skip", "text": f"CORR_ALT_BETTER:{best_sym}"}
                    taken = (getattr(self, "_pp7981_corr_taken", {}) or {}).get(g)
                    if taken and str(taken) != symU:
                        return {"ok": False, "status": 0, "error": "corr_taken", "text": f"CORR_PICKED:{taken}"}
            except Exception:
                pass

            quote = str(getattr(self, "quote", "IRT") or "IRT").upper()
            required_irt = float(_pp7981__required_irt(self, symU, qty_adj, float(price or 0.0)))

            routed = ""
            try:
                cash = float(_pp7981__wallet_cash_irt(self, api, quote))
                if cash < required_irt:
                    _pp7981__maybe_usdt_fund(self, api, str(wname), required_irt)
                    cash = float(_pp7981__wallet_cash_irt(self, api, quote))
                if cash < required_irt:
                    apis = getattr(self, "apis", {}) or {}
                    order = ["W1", "W2", "W3"]
                    try:
                        for wc in (getattr(self, "wallets", []) or []):
                            nm = str(getattr(wc, "name", "") or "")
                            if nm and nm not in order:
                                order.append(nm)
                    except Exception:
                        pass
                    for nm in order:
                        if str(nm) == str(wname):
                            continue
                        api2 = apis.get(nm)
                        if api2 is None:
                            continue
                        try:
                            cash2 = float(_pp7981__wallet_cash_irt(self, api2, quote))
                        except Exception:
                            cash2 = 0.0
                        if cash2 >= required_irt:
                            api = api2
                            wname = nm
                            routed = f"ROUTED_{nm}"
                            break
                    if not routed and cash < required_irt:
                        try:
                            rec_fn = globals().get("_pp7980__record_reject")
                            if callable(rec_fn):
                                rec_fn(self, symU, "WALLET_LIQ_LOW", extra=f"need={required_irt:.0f} have={cash:.0f}")
                        except Exception:
                            pass
                        return {"ok": False, "status": 0, "error": "WALLET_LIQ_LOW", "text": f"need={required_irt:.0f} have={cash:.0f}"}
            except Exception:
                pass

            old_steps = None
            try:
                if _pp7981_os is not None:
                    ladder_on = str(_pp7981_os.getenv("ADV_LADDERING", "1") or "1").strip().lower() in ("1", "true", "yes", "on")
                    if ladder_on:
                        old_steps = _pp7981_os.getenv("LADDER_STEPS", None)
                        try:
                            minN = float(getattr(self, "min_notional_irt", 200000.0) or 200000.0)
                            notional = float(qty_adj) * float(price)
                            max_steps = int(max(1, _pp7981_math.floor(max(1.0, notional) / max(1.0, minN)))) if _pp7981_math is not None else 1
                            cur_steps = int(float(_pp7981_os.getenv("LADDER_STEPS", "1") or 1))
                            if max_steps < cur_steps:
                                _pp7981_os.environ["LADDER_STEPS"] = str(max_steps)
                        except Exception:
                            pass
            except Exception:
                old_steps = None

            resp = None
            try:
                if callable(_pp7981__old_place_buy):
                    resp = _pp7981__old_place_buy(self, api, str(wname), symU, float(qty_adj), float(price))
                else:
                    resp = {"ok": False, "status": 0, "error": "no_impl", "text": "place_buy missing"}
            finally:
                try:
                    if old_steps is not None and _pp7981_os is not None:
                        _pp7981_os.environ["LADDER_STEPS"] = str(old_steps)
                except Exception:
                    pass

            try:
                if isinstance(resp, dict) and bool(resp.get("ok")):
                    g = _pp7981__corr_group(symU)
                    if g:
                        taken = getattr(self, "_pp7981_corr_taken", None)
                        if not isinstance(taken, dict):
                            taken = {}
                        taken[g] = symU
                        self._pp7981_corr_taken = taken
            except Exception:
                pass

            try:
                if isinstance(resp, dict):
                    resp["pp7981"] = {
                        "sym": symU,
                        "size_mult": float(mult),
                        "qty_in": float(qty or 0.0),
                        "qty_out": float(qty_adj or 0.0),
                        "routed": str(routed or ""),
                    }
            except Exception:
                pass
            return resp

        if callable(_pp7981__old_place_buy):
            PP5LiveTripleWallet._place_buy = _pp7981__place_buy  # type: ignore[attr-defined]
except Exception:
    pass


