try:
    _pp7981__orig_ai_gate = globals().get("_pp745__ai_gate")

    def _pp7981__ai_gate(bot, wname: str, sym: str, side: str):
        ok = True
        reason = ""
        try:
            if callable(_pp7981__orig_ai_gate):
                ok, reason = _pp7981__orig_ai_gate(bot, wname, sym, side)
        except Exception:
            ok, reason = True, ""

        try:
            if not ok and str(side).lower() == "buy":
                symU = str(sym or "").upper().strip()
                try:
                    st = (getattr(bot, "states", {}) or {}).get(str(wname), None)
                    symst = (getattr(st, "per_symbol", {}) or {}).get(symU, None) if st is not None else None
                    sc = float(getattr(symst, "last_score", 0.0) or 0.0) if symst is not None else 0.0
                except Exception:
                    sc = 0.0
                floor = float(_pp7981__edge_floor())
                thr = float(getattr(bot, "buy_thr", 0.0) or 0.0)
                if (sc - thr) > 0.0 and sc > floor:
                    return True, "SOFT_WARN AUTO_AI: gated -> sized (v7981)"
        except Exception:
            pass

        return bool(ok), str(reason)

    if callable(_pp7981__orig_ai_gate):
        globals()["_pp745__ai_gate"] = _pp7981__ai_gate
except Exception:
    pass

