try:
    if callable(_pp920__orig_update_signal_streak) and not getattr(_pp920__orig_update_signal_streak, "_pp920_wrapped", False):
        def _pp110_update_signal_streak(symst, score, buy_thr, sell_thr):
            # Preserve legacy output
            sig = "HOLD"
            streak = 0
            try:
                sig, streak = _pp920__orig_update_signal_streak(symst, score, buy_thr, sell_thr)
            except Exception as _pp200_e:
                try:
                    _pp200_report(_pp200_e, tag="pp920_sig_streak")
                except Exception:
                    pass
                sig, streak = ("HOLD", 0)

            # Build unified packet (shadow-safe)
            bot = None
            try:
                bot = getattr(symst, "_pp920_bot", None)
            except Exception:
                bot = None
            sym = ""
            try:
                sym = str(getattr(symst, "symbol", getattr(symst, "sym", "")) or "")
            except Exception:
                sym = ""
            try:
                # Some flows provide symst attached to bot dict; if missing, fall back to last_signal parse
                if not sym:
                    sym = str(getattr(symst, "last_symbol", "") or "")
            except Exception:
                pass

            try:
                packet = _pp920_compute_packet(bot, sym, symst, float(score or 0.0), float(buy_thr or 0.0), float(sell_thr or 0.0), str(sig), int(streak or 0))
                _pp920_record_packet(bot, sym, symst, packet)
            except Exception as _pp200_e:
                try:
                    _pp200_report(_pp200_e, tag="pp920_packet")
                except Exception:
                    pass
                packet = None

            # Shadow mode (default): do NOT alter behavior; only log
            mode = _pp920_safe_str(_pp920_get_env("DECISION_CORE_MODE", "shadow"), 16).lower()
            if mode == "shadow":
                try:
                    if packet is not None and _pp920_get_env("PP920_SHADOW_LOG", "0").strip().lower() in ("1","true","yes","y","on"):
                        _pp920_log_packet(bot, packet)
                except Exception:
                    pass
                return sig, streak

            # Primary mode (OPT-IN): return coherent decision if safe
            if mode == "primary":
                try:
                    if packet is None:
                        return sig, streak
                    dec = str(packet.get("decision", "WAIT") or "WAIT").upper()
                    # Map to legacy-compatible signal words
                    if dec == "BUY":
                        return ("BUY", max(int(streak or 0), 1))
                    if dec == "SELL":
                        return ("SELL", max(int(streak or 0), 1))
                    # WAIT maps to HOLD
                    return ("HOLD", int(streak or 0))
                except Exception:
                    return sig, streak

            # Unknown mode => preserve legacy
            return sig, streak

        setattr(_pp110_update_signal_streak, "_pp920_wrapped", True)
        globals()["_pp110_update_signal_streak"] = _pp110_update_signal_streak
except Exception as _pp200_e:
    try:
        _pp200_heal(_pp200_e, tag="pp920_wrap_update_signal_streak")
    except Exception:
        pass

