# === PP_WALLET_QTY_DISPLAY_FIX_BEGIN ===
# Wallet quantity display fix (balances/fees/dust): Decimal-first + no truncation to 8dp.
# Does NOT touch tokens or trading sizing; UI-only.
try:
    from decimal import Decimal as _PPW_DEC, ROUND_DOWN as _PPW_RD, getcontext as _PPW_GC
    _PPW_GC().prec = 80
except Exception:
    _PPW_DEC = None  # type: ignore
    _PPW_RD = None  # type: ignore

def _ppw_to_dec(v):
    """Robust Decimal parsing for wallet quantities (supports '1e-8', commas, unicode minus)."""
    if _PPW_DEC is None:
        try:
            return float(v or 0.0)
        except Exception:
            try:
                return float(str(v).strip().replace(",", "") or 0.0)
            except Exception:
                return 0.0
    try:
        if v is None:
            return _PPW_DEC("0")
        if isinstance(v, _PPW_DEC):
            return v
        if isinstance(v, bool):
            return _PPW_DEC("1") if v else _PPW_DEC("0")
        if isinstance(v, int):
            return _PPW_DEC(v)
        if isinstance(v, float):
            return _PPW_DEC(repr(v))
        if isinstance(v, str):
            s = v.strip().replace(",", "")
            if not s:
                return _PPW_DEC("0")
            s = s.replace("−", "-").replace("–", "-")
            return _PPW_DEC(s)
        s = str(v).strip().replace(",", "")
        if not s:
            return _PPW_DEC("0")
        s = s.replace("−", "-").replace("–", "-")
        return _PPW_DEC(s)
    except Exception:
        return _PPW_DEC("0")

def _ppw_numstr(v, max_dec: int = 18) -> str:
    """Human+exact wallet qty string: expands scientific, trims trailing zeros, caps decimals (ROUND_DOWN)."""
    try:
        if _PPW_DEC is None:
            x = float(v or 0.0)
            # show more precision for tiny dust
            if abs(x) < 1e-6 and x != 0.0:
                s = f"{x:.18f}"
            else:
                s = f"{x:.12f}"
            if "." in s:
                s = s.rstrip("0").rstrip(".")
            return s or "0"
        d = _ppw_to_dec(v)
        if d == _PPW_DEC("0"):
            return "0"
        # quantize only if too many decimals (ROUND_DOWN to avoid showing more than owned)
        dn = d.normalize()
        exp = int(dn.as_tuple().exponent)
        decs = max(0, -exp)
        if decs > int(max_dec):
            q = _PPW_DEC("1").scaleb(-int(max_dec))
            d = d.quantize(q, rounding=_PPW_RD)
        s = format(d, "f")  # never scientific
        if "." in s:
            s = s.rstrip("0").rstrip(".")
        return s or "0"
    except Exception:
        try:
            return str(v)
        except Exception:
            return "0"

def _ppw_is_nonzero(v) -> bool:
    try:
        if _PPW_DEC is None:
            return abs(float(v or 0.0)) > 0.0
        return abs(_ppw_to_dec(v)) > _PPW_DEC("0")
    except Exception:
        return False

# Patch snapshot: rebuild assets list using Decimal formatting (not fixed 8dp).
try:
    _PPW_PREV_SNAP = DashboardManager._wallet_snapshot  # type: ignore[name-defined]
except Exception:
    _PPW_PREV_SNAP = None

def _ppw_wallet_snapshot(self, wname: str) -> dict:  # type: ignore[override]
    out = None
    try:
        if callable(_PPW_PREV_SNAP):
            out = _PPW_PREV_SNAP(self, wname)
    except Exception:
        out = None
    if not isinstance(out, dict):
        out = {"ok": True, "name": wname}

    bot = getattr(self, "bot", None)
    if bot is None:
        return out

    # Read total balances (FREE+LOCKED) if available; fall back to free.
    b = {}
    try:
        quote = str(getattr(bot, "quote", "IRT") or "IRT").upper().strip()
    except Exception:
        quote = "IRT"

    try:
        _lk = getattr(bot, "_dash_lock", None)
        if _lk is None:
            bc_free = getattr(bot, "_dash_balances_cache", {}) or {}
            bc_total = getattr(bot, "_dash_balances_total_cache", None)
            if not isinstance(bc_total, dict):
                bc_total = bc_free
            b = (bc_total.get(wname, {}) or {}) if isinstance(bc_total, dict) else {}
        else:
            with _lk:
                bc_free = getattr(bot, "_dash_balances_cache", {}) or {}
                bc_total = getattr(bot, "_dash_balances_total_cache", None)
                if not isinstance(bc_total, dict):
                    bc_total = bc_free
                b = (bc_total.get(wname, {}) or {}) if isinstance(bc_total, dict) else {}
    except Exception:
        b = {}

    assets_tmp = []
    try:
        if isinstance(b, dict):
            for k, v in (b or {}).items():
                ak = str(k)
                auk = ak.upper().strip()
                if not auk or auk == quote:
                    continue
                if not _ppw_is_nonzero(v):
                    continue
                s = _ppw_numstr(v, max_dec=18)
                try:
                    sortv = abs(_ppw_to_dec(s)) if _PPW_DEC is not None else abs(float(s))
                except Exception:
                    sortv = abs(_ppw_to_dec(v)) if _PPW_DEC is not None else abs(float(v or 0.0))
                assets_tmp.append((ak, s, sortv))
    except Exception:
        assets_tmp = []

    try:
        assets_tmp.sort(key=lambda t: (-t[2], t[0]))
    except Exception:
        try:
            assets_tmp.sort(key=lambda t: (t[0],))
        except Exception:
            pass

    out["assets"] = [(a, v) for (a, v, _sv) in assets_tmp]
    return out

try:
    DashboardManager._wallet_snapshot = _ppw_wallet_snapshot  # type: ignore[name-defined]
except Exception:
    pass

# Patch panel: do NOT float-convert numeric strings; show as-is (after Decimal normalize).
def _ppw_wallet_panel(self, wname: str):  # type: ignore[override]
    import os
    try:
        from rich.panel import Panel
        from rich.table import Table
        from rich.text import Text
        from rich import box
        from rich.console import Group
    except Exception:
        # Rich missing: fallback to plain text
        s = self._wallet_snapshot(wname)
        return f"{wname}: EQ={s.get('eq')} CASH={s.get('cash')} ASSETS={s.get('assets')}"

    s = self._wallet_snapshot(wname)
    mode = str(os.getenv("WALLET_PANEL_MODE", "compact") or "compact").strip().lower()
    if mode not in ("compact", "full"):
        mode = "compact"

    if not s.get("ok", True):
        t = Table.grid(padding=(0, 1))
        t.expand = True
        t.add_column(ratio=1)
        t.add_row(Text("OFFLINE", style="bold red"))
        err = str(s.get("err") or "Connection Error")[:200]
        t.add_row(Text(err, style="white"))
        p = Panel(t, title=f"{wname}", box=box.SQUARE, padding=(0, 1), style="white on black", expand=True)
        return p

    # Money fields
    def _f(x):
        try:
            return float(x or 0.0)
        except Exception:
            return 0.0

    eq = _f(s.get("eq"))
    cash = _f(s.get("cash"))
    engaged = _f(s.get("engaged"))
    try:
        steps = int(s.get("open_steps") or 0)
    except Exception:
        steps = 0
    pnl = _f(s.get("pnl"))

    strat = (s.get("strategy") or "").strip() or "PREDICTING MARKET"
    status = ""
    try:
        status = self._status_cell(s)
    except Exception:
        status = str(s.get("status_override") or "WAITING")

    # USDT timer label
    ut_s = ""
    try:
        ut = s.get("usdt_timer", None)
        if ut is not None:
            rv = float(ut or 0.0)
            if rv <= 0.0:
                ut_s = "READY"
            else:
                mm = int(rv) // 60
                ss = int(rv) % 60
                ut_s = f"{mm:02d}:{ss:02d}"
    except Exception:
        ut_s = ""

    # P&L display
    if not bool(steps and int(steps) > 0):
        pnl_s = "[dim]NO ACTIVE TRADE[/dim]"
    else:
        pnl_style = "green" if pnl >= 0 else "red"
        pnl_s = f"[{pnl_style}]{pnl:+,.0f} TOMAN[/{pnl_style}]"

    # Assets summary
    assets = s.get("assets") or []
    a_parts = []
    try:
        for k, v in (assets or [])[:4]:
            a_parts.append(f"{k}:{_ppw_numstr(v, max_dec=18)}")
        if isinstance(assets, list) and len(assets) > 4:
            a_parts.append(f"+{len(assets) - 4}")
    except Exception:
        a_parts = []
    assets_line = " • ".join(a_parts) if a_parts else "-"

    if mode == "compact":
        t = Table.grid(padding=(0, 1))
        t.expand = True
        t.add_column(ratio=1)
        try:
            t.add_row(Text.from_markup(f"EQUITY {self._money_short(eq)}  |  CASH {self._money_short(cash)}", style="bold white"))
        except Exception:
            t.add_row(Text(f"EQUITY {eq} | CASH {cash}", style="bold white"))
        line2 = ""
        try:
            line2 = f"ENG {self._money_short(engaged)}  |  STEPS {steps}"
        except Exception:
            line2 = f"ENG {engaged} | STEPS {steps}"
        if ut_s:
            line2 += f"  |  USDT {ut_s}"
        t.add_row(Text(line2, style="white"))
        t.add_row(Text.from_markup(f"P&L {pnl_s}", style="white"))
        t.add_row(Text.from_markup(f"ASSETS {assets_line}", style="white"))
        try:
            t.add_row(Text.from_markup(str(status), style="white"))
        except Exception:
            t.add_row(Text(str(status), style="white"))
        if strat:
            t.add_row(Text(str(strat), style="white"))
        p = Panel(t, title=f"{wname}", box=box.SQUARE, padding=(0, 1), style="white on black", expand=True)
    else:
        t = Table(box=box.SIMPLE_HEAVY)
        t.add_column("Metric", style="bold white")
        t.add_column("Value", style="white")
        try:
            t.add_row("Equity", self._money_short(eq))
            t.add_row("Cash", self._money_short(cash))
            t.add_row("Engaged", self._money_short(engaged))
        except Exception:
            t.add_row("Equity", str(eq))
            t.add_row("Cash", str(cash))
            t.add_row("Engaged", str(engaged))
        t.add_row("Steps", str(steps))
        if ut_s:
            t.add_row("USDT", ut_s)
        t.add_row("P&L", Text.from_markup(pnl_s))
        t.add_row("Assets", assets_line)
        t.add_row("Status", Text.from_markup(str(status)))
        t.add_row("Strategy", strat)
        p = Panel(t, title=f"{wname}", box=box.SQUARE, padding=(0, 1), style="white on black", expand=True)

    # Preserve BUY DEBUG lines (PP9001) if present
    try:
        dbg = s.get("_pp9001_buy_dbg") or []
        if dbg and hasattr(p, "renderable"):
            lines = [Text("BUY DEBUG", style="bold yellow")]
            for it in (dbg or [])[:6]:
                lines.append(Text(str(it), style="white"))
            p.renderable = Group(p.renderable, *lines)
    except Exception:
        pass

    return p

try:
    DashboardManager._wallet_panel = _ppw_wallet_panel  # type: ignore[name-defined]
except Exception:
    pass

