# =============================================================================
# PP_WALLET_VIEW_MATURED_FIX_20260130
# هدف (UI فقط):
#   - Quantity = FREE
#   - Cash     = FREE * PRICE
#   - جلوگیری از Qty=Cash (پر شدن دو ستون از یک مقدار)
#   - Wallet3: resolve کلید کیف‌پول + عدم override اشتباه با last-good/cache
#   - Decimal-first formatting (بدون float-casting در مسیر نمایش Qty/Cash)
# =============================================================================

try:
    _PPW_MATURED_PREV_SNAP = DashboardManager._wallet_snapshot  # type: ignore[name-defined]
except Exception:
    _PPW_MATURED_PREV_SNAP = None

def _ppw_matured__norm_key(s: str) -> str:
    try:
        return str(s or "").upper().strip().replace(" ", "").replace("_", "").replace("-", "").replace("/", "")
    except Exception:
        return ""

def _ppw_matured__resolve_wallet_key(cache: dict, wn: str) -> str:
    """Resolve wallet cache key robustly (fix Wallet3 mismap)."""
    try:
        if not isinstance(cache, dict) or not cache:
            return wn
        if wn in cache:
            return wn
        wn2 = str(wn or "").strip()
        if wn2 in cache:
            return wn2
        n = _ppw_matured__norm_key(wn2)
        for k in cache.keys():
            if _ppw_matured__norm_key(k) == n:
                return k
        # common aliases for w1/w2/w3
        if "1" in n:
            for cand in ("W1", "WALLET1", "WALLET_1", "ACC1", "A1"):
                for k in cache.keys():
                    if _ppw_matured__norm_key(k) == _ppw_matured__norm_key(cand):
                        return k
        if "2" in n:
            for cand in ("W2", "WALLET2", "WALLET_2", "ACC2", "A2"):
                for k in cache.keys():
                    if _ppw_matured__norm_key(k) == _ppw_matured__norm_key(cand):
                        return k
        if "3" in n:
            for cand in ("W3", "WALLET3", "WALLET_3", "ACC3", "A3"):
                for k in cache.keys():
                    if _ppw_matured__norm_key(k) == _ppw_matured__norm_key(cand):
                        return k
    except Exception:
        pass
    return wn

def _ppw_matured__dec(v):
    try:
        if _PPW_DEC is None:
            # fallback: best-effort numeric
            return float(v or 0.0)
        return _ppw_to_dec(v)
    except Exception:
        try:
            return _PPW_DEC(str(v).strip().replace(",", "")) if _PPW_DEC is not None else float(v or 0.0)
        except Exception:
            return (_PPW_DEC("0") if _PPW_DEC is not None else 0.0)

def _ppw_matured__fmt(d):
    """Decimal-first compact formatter; never scientific."""
    try:
        if _PPW_DEC is None:
            s = f"{float(d or 0.0):.12f}"
            s = s.rstrip("0").rstrip(".")
            return s or "0"
        dd = d if isinstance(d, _PPW_DEC) else _ppw_to_dec(d)
        # normalize then format "f"
        try:
            s = format(dd.normalize(), "f")
        except Exception:
            s = format(dd, "f")
        if "." in s:
            s = s.rstrip("0").rstrip(".")
        return s or "0"
    except Exception:
        try:
            return str(d)
        except Exception:
            return "0"

def _ppw_matured__pm_build(bot, pm_raw: dict, quote: str) -> dict:
    """Build normalized price map as {NORM(KEY): Decimal(px)}."""
    out = {}
    q = str(quote or "IRT").upper().strip() or "IRT"
    try:
        out[_ppw_matured__norm_key(q)] = (_PPW_DEC("1") if _PPW_DEC is not None else 1.0)
    except Exception:
        pass

    def _put(k, v):
        try:
            kk = _ppw_matured__norm_key(k)
            if not kk:
                return
            if v is None:
                return
            out[kk] = _ppw_matured__dec(v)
        except Exception:
            pass

    # 1) raw price_map
    try:
        if isinstance(pm_raw, dict):
            for k, v in (pm_raw or {}).items():
                _put(k, v)
    except Exception:
        pass

    # 2) optional symbol->px map
    try:
        sym_px = getattr(bot, "_dash_symbol_px_map", None) or {}
        if isinstance(sym_px, dict):
            for k, v in (sym_px or {}).items():
                _put(k, v)
    except Exception:
        pass

    return out

def _ppw_matured__pm_get(pm_norm: dict, key: str, default=None):
    try:
        return (pm_norm or {}).get(_ppw_matured__norm_key(key), default)
    except Exception:
        return default

def _ppw_matured__price(pm_norm: dict, asset: str, quote: str):
    """Best-effort price(asset->quote) with simple cross (USDT/BTC)."""
    a = str(asset or "").upper().strip()
    q = str(quote or "IRT").upper().strip() or "IRT"
    if not a:
        return _ppw_matured__dec("0")
    if a == q:
        return _ppw_matured__dec("1")
    # direct asset key
    px = _ppw_matured__pm_get(pm_norm, a, None)
    if px is not None:
        return px
    # direct pair
    for cand_q in (q, "IRT", "TOMAN", "IRR", "TMN"):
        px = _ppw_matured__pm_get(pm_norm, f"{a}{cand_q}", None)
        if px is not None:
            return px
        px = _ppw_matured__pm_get(pm_norm, f"{a}/{cand_q}", None)
        if px is not None:
            return px
        px = _ppw_matured__pm_get(pm_norm, f"{a}-{cand_q}", None)
        if px is not None:
            return px
        px = _ppw_matured__pm_get(pm_norm, f"{a}_{cand_q}", None)
        if px is not None:
            return px

    # cross via USDT
    try:
        px_a_usdt = _ppw_matured__pm_get(pm_norm, f"{a}USDT", None)
        if px_a_usdt is None:
            px_a_usdt = _ppw_matured__pm_get(pm_norm, f"{a}/USDT", None)
        if px_a_usdt is not None:
            if q == "USDT":
                return px_a_usdt
            px_usdt_q = _ppw_matured__pm_get(pm_norm, f"USDT{q}", None)
            if px_usdt_q is None:
                for cand_q in (q, "IRT", "TOMAN", "IRR", "TMN"):
                    px_usdt_q = _ppw_matured__pm_get(pm_norm, f"USDT{cand_q}", None)
                    if px_usdt_q is not None:
                        break
            if px_usdt_q is not None:
                return _ppw_matured__dec(px_a_usdt) * _ppw_matured__dec(px_usdt_q)
    except Exception:
        pass

    # cross via BTC
    try:
        px_a_btc = _ppw_matured__pm_get(pm_norm, f"{a}BTC", None)
        if px_a_btc is None:
            px_a_btc = _ppw_matured__pm_get(pm_norm, f"{a}/BTC", None)
        if px_a_btc is not None:
            px_btc_q = _ppw_matured__pm_get(pm_norm, f"BTC{q}", None)
            if px_btc_q is None:
                for cand_q in (q, "IRT", "TOMAN", "IRR", "TMN"):
                    px_btc_q = _ppw_matured__pm_get(pm_norm, f"BTC{cand_q}", None)
                    if px_btc_q is not None:
                        break
            if px_btc_q is not None:
                return _ppw_matured__dec(px_a_btc) * _ppw_matured__dec(px_btc_q)
    except Exception:
        pass

    return _ppw_matured__dec("0")

def _ppw_wallet_snapshot_matured(self, wname: str) -> dict:  # type: ignore[override]
    # keep existing snapshot fields (pnl, open_steps, strategy, etc.)
    try:
        out = _PPW_MATURED_PREV_SNAP(self, wname) if callable(_PPW_MATURED_PREV_SNAP) else {"ok": True, "name": wname}
        if not isinstance(out, dict):
            out = {"ok": True, "name": wname}
    except Exception as e:
        out = {"ok": False, "name": wname, "err": str(e)}

    bot = getattr(self, "bot", None)
    if bot is None:
        return out

    # quote currency
    try:
        quote = str(getattr(bot, "quote", "IRT") or "IRT").upper().strip() or "IRT"
    except Exception:
        quote = "IRT"

    # read caches atomically (do NOT touch tokens/keys)
    try:
        _lk = getattr(bot, "_dash_lock", None)
    except Exception:
        _lk = None

    def _read():
        bc_free = getattr(bot, "_dash_balances_cache", {}) or {}
        pm = getattr(bot, "_dash_price_map", {}) or {}
        wk = _ppw_matured__resolve_wallet_key(bc_free, wname)
        b_free = (bc_free.get(wk, {}) or {}) if isinstance(bc_free, dict) else {}
        return wk, b_free, pm

    if _lk is None:
        wk, b_free, pm_raw = _read()
    else:
        with _lk:
            wk, b_free, pm_raw = _read()

    out["name"] = str(wname)
    try:
        out["wallet_key"] = str(wk)
    except Exception:
        pass

    # compute CASH (quote free only) robustly; do not rely on mis-mapped older fields
    cash_dec = _ppw_matured__dec((b_free or {}).get(quote, "0"))
    if str(quote).upper().strip() in ("IRT", "IRR", "TOMAN", "TMN"):
        # tolerate aliases: choose max non-zero to avoid wrong key
        for qk in ("IRT", "IRR", "TOMAN", "TMN"):
            try:
                cash_dec = max(_ppw_matured__dec((b_free or {}).get(qk, "0")), cash_dec)
            except Exception:
                pass
    try:
        out["cash"] = float(cash_dec) if _PPW_DEC is not None else float(cash_dec or 0.0)
    except Exception:
        pass
    out["cash_str"] = _ppw_matured__fmt(cash_dec)

    # build per-asset rows from FREE only (Quantity=free; Cash=free*price)
    pm_norm = _ppw_matured__pm_build(bot, pm_raw if isinstance(pm_raw, dict) else {}, quote)

    assets_detail_tmp = []
    try:
        for k, free_raw in (b_free or {}).items():
            ak = str(k or "").upper().strip()
            if not ak or ak == quote:
                continue
            qty_dec = _ppw_matured__dec(free_raw)
            try:
                if _PPW_DEC is not None and abs(qty_dec) <= _PPW_DEC("0"):
                    continue
                if _PPW_DEC is None and abs(float(qty_dec or 0.0)) <= 0.0:
                    continue
            except Exception:
                continue

            px = _ppw_matured__price(pm_norm, ak, quote)
            cash_asset = qty_dec * px if _PPW_DEC is not None else float(qty_dec) * float(px)
            qty_s = _ppw_matured__fmt(qty_dec)
            cash_s = _ppw_matured__fmt(cash_asset)

            # sort by cash value if possible (fallback by qty)
            sortv = None
            try:
                sortv = abs(cash_asset) if _PPW_DEC is not None else abs(float(cash_asset))
            except Exception:
                try:
                    sortv = abs(qty_dec)
                except Exception:
                    sortv = 0
            assets_detail_tmp.append((ak, qty_s, cash_s, sortv))
    except Exception:
        assets_detail_tmp = []

    try:
        assets_detail_tmp.sort(key=lambda t: (-t[3], t[0]))
    except Exception:
        pass

    out["assets_detail"] = [(a, qs, cs) for (a, qs, cs, _sv) in (assets_detail_tmp or [])][:64]
    out["assets"] = [(a, qs) for (a, qs, _cs, _sv) in (assets_detail_tmp or [])][:24]

    return out

try:
    DashboardManager._wallet_snapshot = _ppw_wallet_snapshot_matured  # type: ignore[name-defined]
except Exception:
    pass

# Optional: improve wallet panel assets line using assets_detail (shows qty≈cash per asset)
try:
    _PPW_MATURED_PREV_PANEL = DashboardManager._wallet_panel  # type: ignore[name-defined]
except Exception:
    _PPW_MATURED_PREV_PANEL = None

def _ppw_wallet_panel_matured(self, wname: str):  # type: ignore[override]
    # defer to the existing panel, but enhance assets string if possible
    try:
        s = self._wallet_snapshot(wname)
        if isinstance(s, dict) and s.get("assets_detail"):
            # inject a prebuilt "assets_line_detail" for renderers that support it
            try:
                parts = []
                for a, qs, cs in (s.get("assets_detail") or [])[:4]:
                    parts.append(f"{a}:{qs}≈{cs}")
                if isinstance(s.get("assets_detail"), list) and len(s.get("assets_detail")) > 4:
                    parts.append(f"+{len(s.get('assets_detail')) - 4}")
                s["assets_line_detail"] = " • ".join(parts) if parts else s.get("assets_line_detail")
            except Exception:
                pass
            # temporarily monkeypatch snapshot output for downstream panel renderers
            try:
                _orig = getattr(self, "_wallet_snapshot")
                def _tmp(_wn):
                    return s if _wn == wname else _orig(_wn)
                setattr(self, "_wallet_snapshot", _tmp)
            except Exception:
                pass
    except Exception:
        pass
    try:
        if callable(_PPW_MATURED_PREV_PANEL):
            return _PPW_MATURED_PREV_PANEL(self, wname)
    except Exception:
        pass
    # fallback to current implementation if available
    try:
        return _ppw_wallet_panel(self, wname)  # type: ignore[name-defined]
    except Exception:
        return str(wname)

try:
    DashboardManager._wallet_panel = _ppw_wallet_panel_matured  # type: ignore[name-defined]
except Exception:
    pass

# === PP_WALLET_VIEW_MATURED_FIX_20260130_END ===



# =====================
# v8071 COORDINATED WALLET QUANTITY FIX (UI-ONLY)
# - Enforces: Quantity = free (never cash/value)
# - Applies across all wallet views without touching trade logic or tokens
# =====================
from decimal import Decimal

def _pp__safe_dec(x):
    try:
        return Decimal(str(x))
    except Exception:
        return Decimal('0')

# Monkey-patch asset extraction to prefer `free` when balance items are dicts
def _pp__extract_qty(v):
    # v may be: Decimal/float/int OR dict from API
    if isinstance(v, dict):
        if 'free' in v:
            return _pp__safe_dec(v.get('free'))
        # hard block against using cash/value as qty
        return Decimal('0')
    return _pp__safe_dec(v)

# Patch point: override any locally-scoped builder that iterates balances
try:
    _pp__orig_build = globals().get('_pp_build_assets_from_balances')
except Exception:
    _pp__orig_build = None

def _pp_build_assets_from_balances(balances):
    assets_tmp = []
    for k, v in (balances or {}).items():
        try:
            qty = _pp__extract_qty(v)
            if qty > 0:
                assets_tmp.append((str(k), qty))
        except Exception:
            continue
    return assets_tmp

# If legacy code didn't have a named builder, inject a post-filter hook
def _pp__assets_post_filter(assets):
    out = []
    for a, v in (assets or []):
        try:
            q = _pp__safe_dec(v)
            if q > 0:
                out.append((a, q))
        except Exception:
            continue
    return out

globals()['_pp__assets_post_filter'] = _pp__assets_post_filter
